      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 01-NOV-2021 (JDR) (NJB) (EDW)
      module subroutine azlcpo ( ctx, method, target, et, abcorr, azccw, elplsz, obspos, obsctr, obsref, azlsta, lt )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: pi
      use pepper_math, only: ident, mxv, recazl
      use pepper_strings, only: eqstr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: method  !! Method to obtain the surface normal vector.
      character(*), intent(in) :: target  !! Name of target ephemeris object.
      real(wp), intent(in) :: et  !! Observation epoch.
      character(*), intent(in) :: abcorr  !! Aberration correction.
      logical, intent(in) :: azccw  !! Flag indicating how azimuth is measured.
      logical, intent(in) :: elplsz  !! Flag indicating how elevation is measured.
      real(wp), intent(in) :: obspos ( 3 )  !! Observer position relative to center of motion.
      character(*), intent(in) :: obsctr  !! Center of motion of observer.
      character(*), intent(in) :: obsref  !! Body-fixed, body-centered frame of observer's center.
      real(wp), intent(out) :: azlsta ( 6 )  !! State of target with respect to observer, in azimuth/elevation coordinates.
      real(wp), intent(out) :: lt  !! One way light time between target and observer.
      character(*), parameter :: refloc = 'OBSERVER'
      real(wp) :: alt
      real(wp) :: jacobi ( 3, 3 )
      real(wp) :: lhsta  ( 6    )
      real(wp) :: normal ( 3    )
      real(wp) :: obsspt ( 3    )
      real(wp) :: radii  ( 3    )
      real(wp) :: state  ( 6    )
      real(wp) :: tmpmat ( 3, 3 )
      real(wp) :: xftopo ( 3, 3 )
      integer(ip) :: center
      integer(ip) :: clssid
      integer(ip) :: frclss
      integer(ip) :: fxfcde
      integer(ip) :: obscde
      logical :: found
      if ( .not. allocated ( ctx%azlcpo_state ) ) allocate ( ctx%azlcpo_state )
      associate ( z => ctx%azlcpo_state%z )
      if ( ctx%failed() ) return

!
!     Get the center of motion ID code here, since it will be
!     need later on several calls.
!
      call bods2c ( ctx, obsctr, obscde, found )

      if ( .not. found ) then

         call ctx%setmsg ( 'The observer''s center of motion, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you did not load a ' &
         //            'text kernel containing body-name mapping ' &
         //            'assignments for this name, or that you ' &
         //            'need an updated version of the SPICE ' &
         //            'Toolkit.'                                 )
         call ctx%errch  ( '#', obsctr                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     Determine the attributes of the frame designated by OBSREF.
!
      call namfrm ( ctx, obsref, fxfcde )
      call frinfo ( ctx, fxfcde, center, frclss, clssid, found )

      if ( ctx%failed() ) return

      if ( .not. found ) then

         call ctx%setmsg ( 'Reference frame # is not recognized by ' &
         //            'the SPICE frame subsystem. Possibly ' &
         //            'a required frame definition kernel has ' &
         //            'not been loaded.'                        )
         call ctx%errch  ( '#',  obsref                              )
         call ctx%sigerr ( 'SPICE(UNKNOWNFRAME)'                     )
         return

      end if

!
!     Make sure that OBSREF is centered at the observer's center of
!     motion.
!
      if ( center /= obscde ) then

         call ctx%setmsg ( 'Reference frame # is not centered at the ' &
         //            'observer''s center of motion #. The ID ' &
         //            'code of the frame center is #.'           )
         call ctx%errch  ( '#',  obsref                               )
         call ctx%errch  ( '#',  obsctr                               )
         call ctx%errint ( '#',  center                               )
         call ctx%sigerr ( 'SPICE(INVALIDFRAME)'                      )
         return

      end if

!
!     Construct the local topocentric reference frame. Check
!     first the method to be used.
!
      if ( eqstr( method, 'ELLIPSOID' )  ) then

!
!        If the input observer position is on the Z-axis of the
!        body-fixed, the local topocentric frame will be defined
!        as follows:
!
!           - the +Z axis aligned with the outward normal vector;
!
!           - the +X axis aligned with the +X axis of the body-fixed
!             reference frame;
!
!           - the +Y axis completes the right-handed system.
!
!        otherwise, the local topocentric frame will be defined as
!        follows:
!
!           - the +Z axis aligned with the outward normal vector;
!
!           - the +X axis aligned with the component of the +Z axis
!             of the body-fixed reference frame orthogonal to the
!             outward normal vector;
!
!           - the +Y axis completes the right-handed frame.
!
         if (       ( obspos(1) == 0.0_wp ) &
              .and. ( obspos(2) == 0.0_wp ) ) then

            call ident ( xftopo )

            if ( obspos(3) < 0.0_wp ) then

               call rotmat ( ctx, xftopo, pi, 1, tmpmat )
               xftopo = tmpmat

            end if

         else
!
!           Get the radii of the observer center of motion from the
!           kernel pool.
!
            call zzgftreb ( ctx, obscde, radii )

            if ( ctx%failed() ) return

!
!           The observer's position does not need to be located on
!           the surface of the reference ellipsoid. Find the nearest
!           point on the ellipsoid to the observer.
!
            call nearpt ( ctx, obspos, radii(1), radii(2), radii(3), &
                          obsspt, alt                          )

!
!           Get the outward-pointing, unit normal vector from the point
!           on the surface of the reference ellipsoid.
!
            call surfnm ( ctx, radii(1), radii(2), radii(3), obsspt, normal )

!
!           Construct the transformation matrix from the body-fixed
!           reference frame associated with the observer's center of
!           motion and the local topocentric frame at the observer's
!           location.
!
            call twovec ( ctx, normal, 3, z, 1, xftopo )

         end if

      else

         call ctx%setmsg ( 'The computation method # was not recognized. ' )
         call ctx%errch  ( '#',  method                                    )
         call ctx%sigerr ( 'SPICE(INVALIDMETHOD)'                          )
         return

      end if

!
!     Compute the observer-target position vector. Use as OUTREF the
!     same reference frame used for expressing the OBSPOS vector
!     (OBSREF).
!
      call spkcpo ( ctx, target, et,     obsref, refloc, abcorr, &
                    obspos, obsctr, obsref, state,  lt     )

      if ( ctx%failed() ) return

!
!     STATE is expressed with respect to the reference frame
!     specified by OBSREF. Convert this vector from OBSREF frame
!     to local-horizon frame.
!
      call mxv ( xftopo, state,    lhsta    )
      call mxv ( xftopo, state(4), lhsta(4) )

!
!     Convert LHSTA from rectangular to azimuth/elevation coordinates
!
      call recazl ( lhsta,     azccw,     elplsz, &
                    azlsta(1), azlsta(2), azlsta(3) )

      call dazldr ( ctx, lhsta(1),  lhsta(2),  lhsta(3), &
                    azccw,     elplsz,    jacobi    )

      if ( ctx%failed() ) return

      call mxv ( jacobi, lhsta(4), azlsta(4) )

      return
      end associate
      end subroutine azlcpo

      !> Return a set containing the frame IDs of all built-in frames of a
      !> specified class.
      !>
      !>## Detailed Input
      !>
      !>     FRMCLS   is an integer code specifying the frame class or
      !>              classes for which built-in frame ID codes are
      !>              requested. FRMCLS may designate a single class or
      !>              "all classes."
      !>
      !>              The include file frmtyp.inc declares parameters
      !>              identifying frame classes. The supported values
      !>              and corresponding meanings of FRMCLS are
      !>
      !>                 Parameter      Value    Meaning
      !>                 =========      =====    =================
      !>                 ALL              -1     All frame classes
      !>                 INERTL            1     Built-in inertial
      !>                 PCK               2     PCK-based frame
      !>                 CK                3     CK-based frame
      !>                 TK                4     Fixed offset ("text
      !>                                         kernel") frame
      !>                 DYN               5     Dynamic frame
      !>                 SWTCH             6     Switch frame
      !>
      !>## Detailed Output
      !>
      !>     IDSET    is a SPICE set containing the ID codes of all
      !>              built-in reference frames of the specified class
      !>              or classes.
      !>
      !>              If IDSET is non-empty on input, its contents will be
      !>              discarded.
      !>
      !>              IDSET must be initialized by the caller via the
      !>              SPICELIB routine SSIZEI.
      !>
      !>## Parameters
      !>
      !>     See the INCLUDE file frmtyp.inc.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input frame class argument is not defined in
      !>         frmtyp.inc, the error SPICE(BADFRAMECLASS) is signaled.
      !>
      !>     2)  If the size of IDSET is too small to hold the requested
      !>         frame ID set, the error SPICE(SETTOOSMALL) is signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine has a counterpart
      !>
      !>        KPLFRM
      !>
      !>     which fetches the frame IDs of all frames specified in the kernel
      !>     pool.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Display the IDs and names of all SPICE built-in frames.
      !>        Group the outputs by frame class. Also fetch and display
      !>        the entire set of IDs and names using the parameter ALL.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM BLTFRM_EX1
      !>      IMPLICIT NONE
      !>
      !>      INCLUDE 'ninert.inc'
      !>      INCLUDE 'nninrt.inc'
      !>      INCLUDE 'frmtyp.inc'
      !>C
      !>C     SPICELIB functions
      !>C
      !>      INTEGER               CARDI
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               NFRAME
      !>      PARAMETER           ( NFRAME = NINERT + NNINRT )
      !>
      !>      INTEGER               LBCELL
      !>      PARAMETER           ( LBCELL = -5 )
      !>
      !>      INTEGER               LNSIZE
      !>      PARAMETER           ( LNSIZE = 80 )
      !>
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(FRNMLN)    FRNAME
      !>      CHARACTER*(LNSIZE)    OUTLIN
      !>      CHARACTER*(LNSIZE)    VERSN
      !>
      !>      INTEGER               I
      !>      INTEGER               IDSET ( LBCELL : NFRAME )
      !>      INTEGER               NFRMS
      !>      INTEGER               J
      !>
      !>C
      !>C     Get the Toolkit version number and display it.
      !>C
      !>      CALL TKVRSN ( 'TOOLKIT', VERSN )
      !>      CALL TOSTDO ( 'Toolkit version: ' // VERSN )
      !>
      !>C
      !>C     Initialize the frame set.
      !>C
      !>      CALL SSIZEI ( NFRAME, IDSET )
      !>
      !>C
      !>C     Fetch and display the frames of each class.
      !>C
      !>      DO I = 1, 7
      !>
      !>         IF ( I .LT. 7 ) THEN
      !>C
      !>C           Fetch the frames of class I.
      !>C
      !>            CALL BLTFRM ( I, IDSET )
      !>
      !>            OUTLIN = 'Number of frames of class #: #'
      !>            CALL REPMI ( OUTLIN, '#', I,            OUTLIN )
      !>            CALL REPMI ( OUTLIN, '#', CARDI(IDSET), OUTLIN )
      !>
      !>         ELSE
      !>C
      !>C           Fetch IDs of all built-in frames.
      !>C
      !>            CALL BLTFRM ( ALL, IDSET )
      !>
      !>            OUTLIN = 'Number of built-in frames: #'
      !>            CALL REPMI ( OUTLIN, '#', CARDI(IDSET), OUTLIN )
      !>
      !>         END IF
      !>
      !>         CALL TOSTDO ( ' '    )
      !>         CALL TOSTDO ( OUTLIN )
      !>         CALL TOSTDO ( '   Frame IDs and names' )
      !>
      !>C
      !>C        Display the NAIF ID and name of a maximum of 5 frames
      !>C        per family.
      !>C
      !>         NFRMS = MIN( 5, CARDI(IDSET) )
      !>
      !>         DO J = 1, NFRMS
      !>            CALL FRMNAM ( IDSET(J), FRNAME )
      !>            WRITE (*,*) IDSET(J), '  ', FRNAME
      !>         END DO
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Toolkit version: N0067
      !>
      !>        Number of frames of class 1: 21
      !>           Frame IDs and names
      !>                   1   J2000
      !>                   2   B1950
      !>                   3   FK4
      !>                   4   DE-118
      !>                   5   DE-96
      !>
      !>        Number of frames of class 2: 105
      !>           Frame IDs and names
      !>               10001   IAU_MERCURY_BARYCENTER
      !>               10002   IAU_VENUS_BARYCENTER
      !>               10003   IAU_EARTH_BARYCENTER
      !>               10004   IAU_MARS_BARYCENTER
      !>               10005   IAU_JUPITER_BARYCENTER
      !>
      !>        Number of frames of class 3: 0
      !>           Frame IDs and names
      !>
      !>        Number of frames of class 4: 1
      !>           Frame IDs and names
      !>               10081   EARTH_FIXED
      !>
      !>        Number of frames of class 5: 0
      !>           Frame IDs and names
      !>
      !>        Number of frames of class 6: 0
      !>           Frame IDs and names
      !>
      !>        Number of built-in frames: 127
      !>           Frame IDs and names
      !>                   1   J2000
      !>                   2   B1950
      !>                   3   FK4
      !>                   4   DE-118
      !>                   5   DE-96
      !>
      !>        Note that the set of built-in frames, particularly the
      !>        non-inertial ones, will grow over time, so the output
      !>        shown here may be out of sync with that produced by a
      !>        current SPICE Toolkit. Only the first 5 frames of each
      !>        family are presented in the output.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.0.0, 08-AUG-2021 (JDR) (NJB)
      !>
      !>        Updated to account for switch frame class.
      !>
      !>        Edited the header to comply with NAIF standard. Updated
      !>        code example to limit the number of frames presented in the
      !>        output.
      !>
      !>        Extended IDSET description to indicate that the set must
      !>        be declared and initialized before calling this routine and
      !>        that its contents will be discarded.
      !>
      !>-    SPICELIB Version 1.1.0, 09-AUG-2013 (BVS)
      !>
      !>        Updated for changed ZZFDAT calling sequence.
      !>
      !>-    SPICELIB Version 1.0.0, 21-MAY-2012 (NJB)
      module subroutine bltfrm ( ctx, frmcls, idset )
      use pepper_kinds, only: ip
      use pepper_arrays, only: orderi
      use pepper_inc_frmtyp, frmtyp_all => all  ! PEPPER: ALL (unused) would hide the intrinsic
      use pepper_inc_ninert
      use pepper_inc_nninrt
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      integer(ip), intent(in) :: frmcls  !! Frame class.
      integer(ip), intent(inout) :: idset  ( lbcell : * )  !! Set of ID codes of frames of the specified class.
      integer(ip), parameter :: nframe = ninert + nninrt
      integer(ip), parameter :: frnmln = 32
      integer(ip), parameter :: lbpool = -5
      integer(ip), parameter :: maxbfr = nframe+1
      integer(ip) :: to
      integer(ip) :: j
      integer(ip) :: ctrord ( nframe )
      integer(ip) :: fclsid ( nframe )
      character(frnmln) :: frname ( nframe )
      integer(ip) :: bidlst  (          maxbfr )
      integer(ip) :: corder ( nframe )
      integer(ip) :: bididx  (          maxbfr )
      integer(ip) :: bnmpol  ( lbpool : maxbfr )
      integer(ip) :: bnmidx  (          maxbfr )
      integer(ip) :: bnmlst  (          maxbfr )
      integer(ip) :: bidpol  ( lbpool : maxbfr )
      integer(ip) :: bidids  (          maxbfr )
      character(frnmln) :: bnmnms  (          maxbfr )
      integer(ip) :: i
      integer(ip) :: center ( nframe )
      if ( .not. allocated ( ctx%bltfrm_state ) ) allocate ( ctx%bltfrm_state )
      associate ( fclass => ctx%bltfrm_state%fclass, &
                  fcode => ctx%bltfrm_state%fcode, &
                  pass1 => ctx%bltfrm_state%pass1 )
      if ( ctx%failed() ) return

!
!     The output set starts out empty.
!
      call scardi ( ctx, 0, idset )

!
!     On the first pass, fetch all data for the
!     built-in frames.
!
      if ( pass1 ) then

         call zzfdat ( ctx, nframe, maxbfr, frname, fcode, &
                       center, fclass, fclsid, ctrord, &
                       bnmlst, bnmpol, bnmnms, bnmidx, &
                       bidlst, bidpol, bidids, bididx )

         if ( ctx%failed() ) return

         pass1 = .false.

      end if

!
!     Check the input frame class.
!
!     This block of code must be kept in sync with frmtyp.inc.
!
      if  (      ( frmcls > swtch ) &
            .or. ( frmcls == 0   ) &
            .or. ( frmcls < frmtyp_all )  ) then

         call ctx%setmsg ( 'Frame class specifier FRMCLS was #; this ' &
         //            'value is not supported.'                  )
         call ctx%errint ( '#',  frmcls                               )
         call ctx%sigerr ( 'SPICE(BADFRAMECLASS)'                     )
         return

      end if

!
!     Make sure the set is large enough to hold all of
!     the IDs of the built-in frames.
!
      if ( sizei( ctx,idset) < nframe ) then

         call ctx%setmsg ( 'Frame ID set argument IDSET has size #; ' &
         //            'required size is at least #.'           )
         call ctx%errint ( '#', sizei( ctx,idset)                        )
         call ctx%errint ( '#', nframe                              )
         call ctx%sigerr ( 'SPICE(SETTOOSMALL)'                     )
         return

      end if

!
!     Transfer ID codes of all frames of the specified class
!     to the output set. First, generate an order vector for
!     the ID codes.
!
      call orderi ( fcode, nframe, corder )

      to = 0

      do i = 1, nframe
!
!        Get the index J in the parallel data arrays of
!        the Ith frame, ordered by ID code.
!
         j = corder(i)

         if (      ( fclass(j) == frmcls ) &
              .or. ( frmcls    == frmtyp_all    )  ) then
!
!           The frame at index J belongs to the
!           requested class. Append the frame's ID
!           code to the set.
!
            to        = to + 1
            idset(to) = fcode(j)

         end if

      end do

!
!     Set the cardinality of the output set.
!
!     Note that we populated the set using an order vector, so sorting
!     the elements is not necessary. We rely on ZZFDAT to not give us
!     duplicate frame specifications.
!
      call scardi ( ctx, to, idset )

      return
      end associate
      end subroutine bltfrm

      !> Return the J2000 to body Equator and Prime Meridian coordinate
      !> transformation matrix for a specified body.
      !>
      !>## Detailed Input
      !>
      !>     BODY     is the integer ID code of the body for which the
      !>              transformation is requested. Bodies are numbered
      !>              according to the standard NAIF numbering scheme.
      !>
      !>     ET       is the epoch at which the transformation is
      !>              requested. (This is typically the epoch of
      !>              observation minus the one-way light time from
      !>              the observer to the body at the epoch of
      !>              observation.)
      !>
      !>## Detailed Output
      !>
      !>     TIPM     is the transformation matrix from Inertial to body
      !>              Equator and Prime Meridian. The X axis of the PM
      !>              system is directed to the intersection of the
      !>              equator and prime meridian. The Z axis points north.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If data required to define the body-fixed frame associated
      !>         with BODY are not found in the binary PCK system or the kernel
      !>         pool, the error SPICE(FRAMEDATANOTFOUND) is signaled. In
      !>         the case of IAU style body-fixed frames, the absence of
      !>         prime meridian polynomial data (which are required) is used
      !>         as an indicator of missing data.
      !>
      !>     2)  If the test for exception (1) passes, but in fact requested
      !>         data are not available in the kernel pool, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     3)  If the kernel pool does not contain all of the data required
      !>         to define the number of nutation precession angles
      !>         corresponding to the available nutation precession
      !>         coefficients, the error SPICE(INSUFFICIENTANGLES) is
      !>         signaled.
      !>
      !>     4)  If the reference frame REF is not recognized, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     5)  If the specified body code BODY is not recognized, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine is related to the more general routine TIPBOD
      !>     which returns a matrix that transforms vectors from a
      !>     specified inertial reference frame to body equator and
      !>     prime meridian coordinates. TIPBOD accepts an input argument
      !>     REF that allows the caller to specify an inertial reference
      !>     frame.
      !>
      !>     The transformation represented by BODMAT's output argument TIPM
      !>     is defined as follows:
      !>
      !>        TIPM = [W] [DELTA] [PHI]
      !>                 3        1     3
      !>
      !>     If there exists high-precision binary PCK kernel information
      !>     for the body at the requested time, these angles, W, DELTA
      !>     and PHI are computed directly from that file. The most
      !>     recently loaded binary PCK file has first priority followed
      !>     by previously loaded binary PCK files in backward time order.
      !>     If no binary PCK file has been loaded, the text P_constants
      !>     kernel file is used.
      !>
      !>     If there is only text PCK kernel information, it is
      !>     expressed in terms of RA, DEC and W (same W as above), where
      !>
      !>        RA    = PHI - HALFPI()
      !>        DEC   = HALFPI() - DELTA
      !>
      !>     RA, DEC, and W are defined as follows in the text PCK file:
      !>
      !>        RA  = RA0  + RA1*T  + RA2*T*T   + a  sin theta
      !>                                           i          i
      !>
      !>        DEC = DEC0 + DEC1*T + DEC2*T*T  + d  cos theta
      !>                                           i          i
      !>
      !>        W   = W0   + W1*d   + W2*d*d    + w  sin theta
      !>                                           i          i
      !>
      !>     where:
      !>
      !>        d = days past J2000.
      !>
      !>        T = Julian centuries past J2000.
      !>
      !>        a , d , and w  arrays apply to satellites only.
      !>         i   i       i
      !>
      !>        theta  = THETA0 * THETA1*T are specific to each planet.
      !>             i
      !>
      !>     These angles -- typically nodal rates -- vary in number and
      !>     definition from one planetary system to the next.
      !>
      !>## Examples
      !>
      !>     In the following code fragment, BODMAT is used to rotate
      !>     the position vector (POS) from a target body (BODY) to a
      !>     spacecraft from inertial coordinates to body-fixed coordinates
      !>     at a specific epoch (ET), in order to compute the planetocentric
      !>     longitude (PCLONG) of the spacecraft.
      !>
      !>        CALL BODMAT ( BODY, ET, TIPM )
      !>        CALL MXV    ( TIPM, POS, POS )
      !>        CALL RECLAT ( POS, RADIUS, PCLONG, LAT )
      !>
      !>     To compute the equivalent planetographic longitude (PGLONG),
      !>     it is necessary to know the direction of rotation of the target
      !>     body, as shown below.
      !>
      !>        CALL BODVCD ( BODY, 'PM', 3, DIM, VALUES )
      !>
      !>        IF ( VALUES(2) .GT. 0.D0 ) THEN
      !>           PGLONG = PCLONG
      !>        ELSE
      !>           PGLONG = TWOPI() - PCLONG
      !>        END IF
      !>
      !>     Note that the items necessary to compute the transformation
      !>     TIPM must have been loaded into the kernel pool (by one or more
      !>     previous calls to FURNSH).
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>     K.S. Zukor         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 4.2.1, 14-APR-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard. Moved NAIF_IDS
      !>        required reading from $Literature_References to
      !>        $Required_Reading section.
      !>
      !>-    SPICELIB Version 4.2.0, 27-JUL-2016 (BVS)
      !>
      !>        Updated to use the 3x3 top-left corner of the 6x6 matrix
      !>        returned by TISBOD instead of fetching kernel data and doing
      !>        computations in-line.
      !>
      !>-    SPICELIB Version 4.1.1, 01-FEB-2008 (NJB)
      !>
      !>        The routine was updated to improve the error messages created
      !>        when required PCK data are not found. Now in most cases the
      !>        messages are created locally rather than by the kernel pool
      !>        access routines. In particular missing binary PCK data will
      !>        be indicated with a reasonable error message.
      !>
      !>-    SPICELIB Version 4.1.0, 25-AUG-2005 (NJB)
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in MXM call.
      !>
      !>        Calls to ZZBODVCD have been replaced with calls to
      !>        BODVCD.
      !>
      !>-    SPICELIB Version 4.0.0, 12-FEB-2004 (NJB)
      !>
      !>        Code has been updated to support satellite ID codes in the
      !>        range 10000 to 99999 and to allow nutation precession angles
      !>        to be associated with any object.
      !>
      !>        Implementation changes were made to improve robustness
      !>        of the code.
      !>
      !>-    SPICELIB Version 3.2.0, 22-MAR-1995 (KSZ)
      !>
      !>        Gets TSIPM matrix from PCKMAT (instead of Euler angles
      !>        from PCKEUL.)
      !>
      !>-    SPICELIB Version 3.0.0, 10-MAR-1994 (KSZ)
      !>
      !>        Ability to get Euler angles from binary PCK file added.
      !>        This uses the new routine PCKEUL.
      !>
      !>-    SPICELIB Version 2.0.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 2.0.0, 04-SEP-1991 (NJB)
      !>
      !>        Updated to handle P_constants referenced to different epochs
      !>        and inertial reference frames.
      !>
      !>        The header was updated to specify that the inertial reference
      !>        frame used by BODMAT is restricted to be J2000.
      !>
      !>-    SPICELIB Version 1.0.0, 31-JAN-1990 (WLT) (IMU)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 4.2.0, 27-JUL-2016 (BVS)
      !>
      !>        Updated to use the 3x3 top-left corner of the 6x6 matrix
      !>        returned by TISBOD instead of fetching kernel data and doing
      !>        computations in-line.
      !>
      !>-    SPICELIB Version 4.1.0, 25-AUG-2005 (NJB)
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in MXM call.
      !>
      !>        Calls to ZZBODVCD have been replaced with calls to
      !>        BODVCD.
      !>
      !>-    SPICELIB Version 4.0.0, 12-FEB-2004 (NJB)
      !>
      !>        Code has been updated to support satellite ID codes in the
      !>        range 10000 to 99999 and to allow nutation precession angles
      !>        to be associated with any object.
      !>
      !>        Calls to deprecated kernel pool access routine RTPOOL
      !>        were replaced by calls to GDPOOL.
      !>
      !>        Calls to BODVAR have been replaced with calls to
      !>        ZZBODVCD.
      !>
      !>-    SPICELIB Version 3.2.0, 22-MAR-1995 (KSZ)
      !>
      !>        BODMAT now get the TSIPM matrix from PCKMAT, and
      !>        unpacks TIPM from it. Also the calculated but unused
      !>        variable LAMBDA was removed.
      !>
      !>-    SPICELIB Version 3.0.0, 10-MAR-1994 (KSZ)
      !>
      !>        BODMAT now uses new software to check for the
      !>        existence of binary PCK files, search the for
      !>        data corresponding to the requested body and time,
      !>        and return the appropriate Euler angles, using the
      !>        new routine PCKEUL. Otherwise the code calculates
      !>        the Euler angles from the P_constants kernel file.
      !>
      !>-    SPICELIB Version 2.0.0, 04-SEP-1991 (NJB)
      !>
      !>        Updated to handle P_constants referenced to different epochs
      !>        and inertial reference frames.
      !>
      !>        The header was updated to specify that the inertial reference
      !>        frame used by BODMAT is restricted to be J2000.
      !>
      !>        BODMAT now checks the kernel pool for presence of the
      !>        variables
      !>
      !>           BODY#_CONSTANTS_REF_FRAME
      !>
      !>        and
      !>
      !>           BODY#_CONSTANTS_JED_EPOCH
      !>
      !>        where # is the NAIF integer code of the barycenter of a
      !>        planetary system or of a body other than a planet or
      !>        satellite. If either or both of these variables are
      !>        present, the P_constants for BODY are presumed to be
      !>        referenced to the specified inertial frame or epoch.
      !>        If the epoch of the constants is not J2000, the input
      !>        time ET is converted to seconds past the reference epoch.
      !>        If the frame of the constants is not J2000, the rotation from
      !>        the P_constants' frame to body-fixed coordinates is
      !>        transformed to the rotation from J2000 coordinates to
      !>        body-fixed coordinates.
      !>
      !>        For efficiency reasons, this routine now duplicates much
      !>        of the code of BODEUL so that it doesn't have to call BODEUL.
      !>        In some cases, BODEUL must covert Euler angles to a matrix,
      !>        rotate the matrix, and convert the result back to Euler
      !>        angles. If this routine called BODEUL, then in such cases
      !>        this routine would convert the transformed angles back to
      !>        a matrix. That would be a bit much....
      !>
      !>-    Beta Version 1.1.0, 16-FEB-1989 (IMU) (NJB)
      !>
      !>        $Examples section completed. Declaration of unused variable
      !>        FOUND removed.
      module subroutine bodmat ( ctx, body, et, tipm )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: body  !! ID code of body.
      real(wp), intent(in) :: et  !! Epoch of transformation.
      real(wp), intent(out) :: tipm   ( 3,3 )  !! Transformation from Inertial to PM for BODY at ET.

      real(wp) :: tsipm   ( 6, 6 )

      integer(ip) :: i
      integer(ip) :: j

!
!     Standard SPICE Error handling.
!
      if ( ctx%failed() ) return

!
!     Get 6x6 state transformation from TISBOD. If succeeded, pull out
!     left-top 3x3 matrix.
!
      call tisbod ( ctx, 'J2000', body, et, tsipm )

      if ( ctx%failed() ) return

      do  i = 1, 3
         do   j  = 1, 3
            tipm  ( i, j ) = tsipm  ( i, j )
         end do
      end do

      return
      end subroutine bodmat

      !> Determine the state (position, velocity) of an orbiting body
      !> from a set of elliptic, hyperbolic, or parabolic orbital
      !> elements.
      !>
      !>## Detailed Input
      !>
      !>     ELTS     are conic elements describing the orbit of a body
      !>              around a primary. The elements are, in order:
      !>
      !>                 RP      Perifocal distance.
      !>                 ECC     Eccentricity.
      !>                 INC     Inclination.
      !>                 LNODE   Longitude of the ascending node.
      !>                 ARGP    Argument of periapse.
      !>                 M0      Mean anomaly at epoch.
      !>                 T0      Epoch.
      !>                 MU      Gravitational parameter.
      !>
      !>              Units are km, rad, rad/sec, km**3/sec**2. The epoch
      !>              is given in ephemeris seconds past J2000. The same
      !>              elements are used to describe all three types
      !>              (elliptic, hyperbolic, and parabolic) of conic orbit.
      !>
      !>     ET       is the time at which the state of the orbiting body
      !>              is to be determined, in ephemeris seconds J2000.
      !>
      !>## Detailed Output
      !>
      !>     STATE    is the state (position and velocity) of the body at
      !>              time ET. Components are x, y, z, dx/dt, dy/dt, dz/dt.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the eccentricity supplied is less than 0, the error
      !>         SPICE(BADECCENTRICITY) is signaled.
      !>
      !>     2)  If a non-positive periapse distance is supplied, the error
      !>         SPICE(BADPERIAPSEVALUE) is signaled.
      !>
      !>     3)  If a non-positive value for the attracting mass is supplied,
      !>         the error SPICE(BADGM) is signaled.
      !>
      !>     4)  If ELTS is such that the resulting orbit at periapsis has
      !>         either its position or velocity equal to zero, or the square
      !>         of the resulting specific angular momentum's magnitude is
      !>         zero, an error is signaled by a routine in the call tree of
      !>         this routine. This is an indication of invalid ELTS elements.
      !>
      !>     5)  If ET is such that the offset in time from periapsis, at which
      !>         the state is to be determined, is so large that there is a
      !>         danger of floating point overflow during computation, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     None.
      !>
      !>## Examples
      !>
      !>     Let VINIT contain the initial state of a spacecraft relative to
      !>     the center of a planet at epoch ET, and let GM be the gravitation
      !>     parameter of the planet. The call
      !>
      !>        CALL OSCELT ( VINIT, ET, GM, ELTS )
      !>
      !>     produces a set of osculating elements describing the nominal
      !>     orbit that the spacecraft would follow in the absence of all
      !>     other bodies in the solar system and non-gravitational forces
      !>     on the spacecraft.
      !>
      !>     Now let STATE contain the state of the same spacecraft at some
      !>     other epoch, LATER. The difference between this state and the
      !>     state predicted by the nominal orbit at the same epoch can be
      !>     computed as follows.
      !>
      !>        CALL CONICS ( ELTS, LATER, NOMINAL )
      !>        CALL VSUBG  ( NOMINAL, STATE, 6, DIFF )
      !>
      !>        WRITE (*,*) 'Perturbation in x, dx/dt = ', DIFF(1), DIFF(4)
      !>        WRITE (*,*) '                y, dy/dt = ', DIFF(2), DIFF(5)
      !>        WRITE (*,*) '                z, dz/dt = ', DIFF(3), DIFF(6)
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     [1]  R. Bate, D. Mueller, and J. White, "Fundamentals of
      !>          Astrodynamics," Dover Publications Inc., 1971.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 4.1.0, 13-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard. Removed
      !>        unnecessary entries in $Revisions section.
      !>
      !>        Added entry #4 and updated entry #5 in $Exceptions section.
      !>
      !>-    SPICELIB Version 4.0.0, 26-MAR-1998 (WLT)
      !>
      !>        There was a coding error in the computation of the mean
      !>        anomaly in the parabolic case. This problem has been
      !>        corrected.
      !>
      !>-    SPICELIB Version 3.0.1, 15-OCT-1996 (WLT)
      !>
      !>        Corrected a typo in the description of the units associated
      !>        with the input elements.
      !>
      !>-    SPICELIB Version 3.0.0, 12-NOV-1992 (WLT)
      !>
      !>        The routine was re-written to make use of NAIF's universal
      !>        variables formulation for state propagation (PROP2B). As
      !>        a result, several problems were simultaneously corrected.
      !>
      !>        A major bug was fixed that caused improper state evaluations
      !>        for ET's that precede the epoch of the elements in the
      !>        elliptic case.
      !>
      !>        A danger of non-convergence in the solution of Kepler's
      !>        equation has been eliminated.
      !>
      !>        In addition to this reformulation of CONICS checks were
      !>        installed that ensure the elements supplied are physically
      !>        meaningful. Eccentricity must be non-negative. The
      !>        distance at periapse and central mass must be positive. If
      !>        not errors are signaled.
      !>
      !>-    SPICELIB Version 2.0.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 2.0.0, 19-APR-1991 (WLT)
      !>
      !>        An error in the hyperbolic state generation was corrected.
      !>
      !>-    SPICELIB Version 1.0.0, 31-JAN-1990 (IMU)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 3.0.0, 12-NOV-1992 (WLT)
      !>
      !>        The routine was re-written to make use of NAIF's universal
      !>        variables formulation for state propagation (PROP2B). As
      !>        a result, several problems were simultaneously corrected.
      !>
      !>        A major bug was fixed that caused improper state
      !>        evaluations for ET's that precede the epoch of the
      !>        elements in the elliptic case.
      !>
      !>        A danger of non-convergence in the solution of Kepler's
      !>        equation has been eliminated.
      !>
      !>        In addition to this reformulation of CONICS checks were
      !>        installed that ensure the elements supplied are physically
      !>        meaningful. Eccentricity must be non-negative. The
      !>        distance at periapse and central mass must be positive.
      !>        If not errors are signaled.
      !>
      !>        These changes were prompted by the discovery that the old
      !>        formulation had a severe bug for elliptic orbits and
      !>        epochs prior to the epoch of the input elements, and by
      !>        the discovery that the time of flight routines had
      !>        problems with convergence.
      !>
      !>-    SPICELIB Version 2.0.0, 19-APR-1991 (WLT)
      !>
      !>        The original version of the routine had a bug in that
      !>        it attempted to restrict the hyperbolic anomaly to
      !>        the interval 0 to 2*PI. This has been fixed.
      module subroutine conics ( ctx, elts, et, state )
      use pepper_kinds, only: wp
      use pepper_constants, only: twopi
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: elts    ( 8 )  !! Conic elements.
      real(wp), intent(in) :: et  !! Input time.
      real(wp), intent(out) :: state   ( 6 )  !! State of orbiting body at ET.

      real(wp) :: rp
      real(wp) :: ecc
      real(wp) :: inc
      real(wp) :: lnode
      real(wp) :: argp
      real(wp) :: m0
      real(wp) :: t0
      real(wp) :: mu
      real(wp) :: n
      real(wp) :: period

      real(wp) :: ainvrs
      real(wp) :: dt

      real(wp) :: cosi
      real(wp) :: sini
      real(wp) :: cosn
      real(wp) :: sinn
      real(wp) :: cosw
      real(wp) :: sinw

      real(wp) :: snci
      real(wp) :: cnci

      real(wp) :: basisp     ( 3 )
      real(wp) :: basisq     ( 3 )
      real(wp) :: pstate     ( 6 )
      real(wp) :: v

!
!      The only real work required by this routine is the construction
!      of a preliminary state vector from the input elements.  Once this
!      is in hand, we can simply let the routine PROP2B do the real
!      work, free from the instabilities inherent in the classical
!      elements formulation of two-body motion.
!
!      To do this we shall construct a basis of vectors that lie in the
!      plane of the orbit.  The first vector P shall point towards the
!      position of the orbiting body at periapse.  The second
!      vector Q shall point along the velocity vector of the body at
!      periapse.
!
!      The only other consideration is determining an epoch, TP, of
!      this state and the delta time ET - TP.
!

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Unpack the element vector.
!
      rp     = elts(1)
      ecc    = elts(2)
      inc    = elts(3)
      lnode  = elts(4)
      argp   = elts(5)
      m0     = elts(6)
      t0     = elts(7)
      mu     = elts(8)

!
!     Handle all of the exceptions first.
!

      if ( ecc < 0 ) then
         call ctx%setmsg ( 'The eccentricity supplied was negative. Only '// &
                       'positive values are meaningful.  The value '  // &
                       'was #'                  )
         call ctx%errdp  ( '#', ecc                 )
         call ctx%sigerr ( 'SPICE(BADECCENTRICITY)' )
         return
      end if

      if ( rp <= 0 ) then
         call ctx%setmsg ( 'The value of periapse range supplied was '    // &
                       'non-positive.  Only positive values are '     // &
                       'allowed.  The value supplied was #. '         )
         call ctx%errdp  ( '#', rp                                        )
         call ctx%sigerr ( 'SPICE(BADPERIAPSEVALUE)'                      )
         return
      end if

      if ( mu <= 0 ) then
         call ctx%setmsg ( 'The value of GM supplied was '                // &
                       'non-positive.  Only positive values are '     // &
                       'allowed.  The value supplied was #. '         )
         call ctx%errdp  ( '#', mu                                        )
         call ctx%sigerr ( 'SPICE(BADGM)'                                 )
         return
      end if

!
!     First construct the orthonormal basis vectors that span the orbit
!     plane.
!
      cosi      =  dcos ( inc   )
      sini      =  dsin ( inc   )
      cosn      =  dcos ( lnode )
      sinn      =  dsin ( lnode )
      cosw      =  dcos ( argp  )
      sinw      =  dsin ( argp  )

      snci      =  sinn * cosi
      cnci      =  cosn * cosi

      basisp(1) =  cosn * cosw  -  snci * sinw
      basisp(2) =  sinn * cosw  +  cnci * sinw
      basisp(3) =  sini * sinw

      basisq(1) = -cosn * sinw  -  snci * cosw
      basisq(2) = -sinn * sinw  +  cnci * cosw
      basisq(3) =  sini * cosw

!
!     Next construct the state at periapse.
!
!     The position at periapse is just BASISP scaled by the distance
!     at periapse.
!
!     The velocity must be constructed so that we can get an orbit
!     of this shape.  Recall that the magnitude of the specific angular
!     momentum vector is given by DSQRT ( MU*RP*(1+ECC) )
!     The velocity will be given by V * BASISQ.  But we must have the
!     magnitude of the cross product of position and velocity be
!     equal to DSQRT ( MU*RP*(1+ECC) ). So we must have
!
!        RP*V = DSQRT( MU*RP*(1+ECC) )
!
!     so that:
!
      v = dsqrt( mu*(1.0_wp + ecc) / rp )

      pstate(1:3) = rp*basisp
      pstate(4:6) = v*basisq

!
!     Finally compute DT the elapsed time since the epoch of periapse.
!     Ellipses first, since they are the most common.
!
      if ( ecc < 1.0_wp ) then

!
!        Recall that:
!
!        N ( mean motion ) is given by DSQRT( MU / A**3 ).
!        But since, A = RP / ( 1 - ECC ) ...
!
         ainvrs = (1.0_wp - ecc)   / rp
         n      = sqrt(mu*ainvrs) * ainvrs
         period = twopi         / n

!
!        In general the mean anomaly is given by
!
!           M  = (T - TP) * N
!
!        Where TP is the time of periapse passage.  M0 is the mean
!        anomaly at time T0 so that
!        Thus
!
!           M0 = ( T0 - TP ) * N
!
!        So TP = T0-M0/N hence the time since periapse at time ET
!        is given by ET - T0 + M0/N.  Finally, since elliptic orbits are
!        periodic, we can mod this value by the period of the orbit.
!
         dt = mod ( et - t0 + m0/n, period )

!
!     Hyperbolas next.
!
      else if ( ecc > 1 ) then

!
!        Again, recall that:
!
!        N ( mean motion ) is given by DSQRT( MU / |A**3| ).
!        But since, |A| = RP / ( ECC - 1 ) ...
!
         ainvrs = (ecc - 1.0_wp)    / rp
         n      = dsqrt(mu*ainvrs) * ainvrs
         dt     = et - t0          + m0/n

!
!     Finally, parabolas.
!
      else

         n  = dsqrt( mu / (2.0_wp*rp) ) / rp
         dt = et - t0                + m0/n

      end if

!
!     Now let PROP2B do the work of propagating the state.
!
      call prop2b ( ctx, mu, pstate, dt, state )

      return
      end subroutine conics

      !> Delete a file.
      !>
      !>## Detailed Input
      !>
      !>     FILNAM   is the name of a file that is to be deleted. Upon
      !>              successful completion of this routine this file will
      !>              no longer exist. The file to be deleted must be closed
      !>              when this routine is called.
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the file name is blank, the error SPICE(BLANKFILENAME)
      !>         is signaled.
      !>
      !>     2)  If the inquire on the filename specified by FILNAM fails for
      !>         some reason, the error SPICE(INQUIREERROR) is signaled.
      !>
      !>     3)  If the file specified by FILNAM is already open, the error
      !>         SPICE(FILECURRENTLYOPEN) is signaled.
      !>
      !>     4)  If the file specified by FILNAM does not exist, the error
      !>         SPICE(NOSUCHFILE) is signaled.
      !>
      !>     5)  If the attempt to open the file specified by FILNAM fails,
      !>         the error SPICE(FILEOPENFAILED) is signaled.
      !>
      !>     6)  If the attempt to close the file with STATUS='DELETE' fails,
      !>         the error SPICE(FILEDELETEFAILED) is signaled.
      !>
      !>## Files
      !>
      !>     The  file specified by FILNAM is opened and then closed by this
      !>     routine with STATUS = 'DELETE' to delete it. The file must be
      !>     closed for this routine to delete it.
      !>
      !>## Particulars
      !>
      !>     This subroutine is a support utility that deletes a file.
      !>
      !>## Examples
      !>
      !>     Suppose you wish to delete a file named 'delete.me' in the
      !>     current directory. The code fragment below would accomplish this.
      !>
      !>        FILE = 'delete.me'
      !>        CALL DELFIL ( FILE )
      !>
      !>## Restrictions
      !>
      !>     1)  The file to be deleted must be closed when this routine is
      !>         invoked.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 02-JUN-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 20-DEC-1995 (KRG)
      module subroutine delfil ( ctx, filnam )
      use pepper_kinds, only: ip
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: filnam  !! The name of a file to be deleted.
      integer(ip) :: iostat
      integer(ip) :: lunit

      logical :: exists
      logical :: opened

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return
!
!     Check to see if the filename we got is blank. If it is, signal an
!     error and return.
!
      if ( filnam == ' ' ) then

         call ctx%setmsg ( 'The file name is blank.' )
         call ctx%sigerr ( 'SPICE(BLANKFILENAME)'    )
         return

      end if
!
!     We inquire before we try opening anything to see if the file
!     exists or is currently open.
!
      inquire ( file   = filnam, &
                exist  = exists, &
                iostat = iostat, &
                opened = opened  )
!
!     Not too likely, but if the INQUIRE statement fails signal an error
!     and return.
!
      if ( iostat /= 0 ) then

         call ctx%setmsg ( 'INQUIRE statement failed for file ''#''.' // &
                       ' IOSTAT = #.'                              )
         call ctx%errch  ( '#', filnam                                 )
         call ctx%errint ( '#', iostat                                 )
         call ctx%sigerr ( 'SPICE(INQUIREFAILED)'                      )
         return

      end if
!
!     The file ought to exist if you're trying to delete it. If not,
!     signal an error and return.
!
      if ( .not. exists ) then

         call ctx%setmsg ( 'The file ''#'' does not exist.' )
         call ctx%errch  ( '#', filnam                      )
         call ctx%sigerr ( 'SPICE(NOSUCHFILE)'              )
         return

      end if
!
!     The file that is to be deleted should not be in use, indicated by
!     it being open, by anything when we try to delete it. If it is
!     open, signal an error and return.
!
      if ( opened ) then

         call ctx%setmsg ( 'The file ''#'' is currently open and'  // &
                       ' cannot be deleted.'                    )
         call ctx%errch  ( '#', filnam                              )
         call ctx%sigerr ( 'SPICE(FILECURRENTLYOPEN)'               )
         return

      end if
!
!     Get an available logical unit and attempt to open the file.
!
!     PEPPER: the unit comes from NEWUNIT= in the OPEN below.

      open ( newunit=lunit, file=filnam, status='OLD', iostat=iostat )
!
!     If we had trouble opening the file, signal an appropriate error
!     and return.
!
      if ( iostat /= 0 ) then

         call ctx%setmsg ( 'Attempt to open the file ''#'' failed.' )
         call ctx%errch  ( '#', filnam                              )
         call ctx%sigerr ( 'SPICE(FILEOPENFAILED)'                  )
         return

      end if
!
!     We opened the file successfully, so let's try to close it with
!     STATUS = 'DELETE'. If this fails, attempt to just close the file,
!     signal an error and return.
!
      close ( lunit, status='DELETE', iostat=iostat )

      if ( iostat /= 0 ) then

         close       ( lunit                                      )
         call ctx%setmsg ( 'Attempt to delete the file ''#'' failed.' )
         call ctx%errch  ( '#', filnam                                )
         call ctx%sigerr ( 'SPICE(FILEDELETEFAILED)'                  )
         return

      end if

      return

      end subroutine delfil

      !> Compute the Jacobian matrix of the transformation from
      !> rectangular to geodetic coordinates.
      !>
      !>## Detailed Input
      !>
      !>     X,
      !>     Y,
      !>     Z        are the rectangular coordinates of the point at
      !>              which the Jacobian of the map from rectangular
      !>              to geodetic coordinates is desired.
      !>
      !>     RE       is the equatorial radius of the reference spheroid.
      !>
      !>     F        is the flattening coefficient = (RE-RP) / RE,  where RP
      !>              is the polar radius of the spheroid. (More importantly
      !>              RP = RE*(1-F).)
      !>
      !>## Detailed Output
      !>
      !>     JACOBI   is the matrix of partial derivatives of the conversion
      !>              between rectangular and geodetic coordinates. It
      !>              has the form
      !>
      !>                  .-                               -.
      !>                  |  DLONG/DX   DLONG/DY  DLONG/DZ  |
      !>                  |  DLAT/DX    DLAT/DY   DLAT/DZ   |
      !>                  |  DALT/DX    DALT/DY   DALT/DZ   |
      !>                  `-                               -'
      !>
      !>               evaluated at the input values of X, Y, and Z.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input point is on the z-axis (X = 0 and Y = 0), the
      !>         Jacobian is undefined, the error SPICE(POINTONZAXIS) is
      !>         signaled.
      !>
      !>     2)  If the flattening coefficient is greater than or equal to
      !>         one, the error SPICE(VALUEOUTOFRANGE) is signaled.
      !>
      !>     3)  If the equatorial radius is not positive, the error
      !>         SPICE(BADRADIUS) is signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     When performing vector calculations with velocities it is
      !>     usually most convenient to work in rectangular coordinates.
      !>     However, once the vector manipulations have been performed,
      !>     it is often desirable to convert the rectangular representations
      !>     into geodetic coordinates to gain insights about phenomena
      !>     in this coordinate frame.
      !>
      !>     To transform rectangular velocities to derivatives of coordinates
      !>     in a geodetic system, one uses the Jacobian of the transformation
      !>     between the two systems.
      !>
      !>     Given a state in rectangular coordinates
      !>
      !>        ( x, y, z, dx, dy, dz )
      !>
      !>     the velocity in geodetic coordinates is given by the matrix
      !>     equation:
      !>                          t          |                     t
      !>        (dlon, dlat, dalt)   = JACOBI|       * (dx, dy, dz)
      !>                                     |(x,y,z)
      !>
      !>     This routine computes the matrix
      !>
      !>              |
      !>        JACOBI|
      !>              |(x, y, z)
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Find the geodetic state of the earth as seen from
      !>        Mars in the IAU_MARS reference frame at January 1, 2005 TDB.
      !>        Map this state back to rectangular coordinates as a check.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: dgeodr_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de421.bsp                     Planetary ephemeris
      !>              pck00010.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0009.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de421.bsp',
      !>                                  'pck00010.tpc',
      !>                                  'naif0009.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM DGEODR_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      RPD
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         FMT1
      !>      PARAMETER           ( FMT1 = '(A,E18.8)' )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      DOUBLE PRECISION      ALT
      !>      DOUBLE PRECISION      DRECTN ( 3 )
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      F
      !>      DOUBLE PRECISION      JACOBI ( 3, 3 )
      !>      DOUBLE PRECISION      LAT
      !>      DOUBLE PRECISION      LON
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      GEOVEL ( 3 )
      !>      DOUBLE PRECISION      RADII  ( 3 )
      !>      DOUBLE PRECISION      RE
      !>      DOUBLE PRECISION      RECTAN ( 3 )
      !>      DOUBLE PRECISION      RP
      !>      DOUBLE PRECISION      STATE  ( 6 )
      !>
      !>      INTEGER               N
      !>
      !>C
      !>C     Load SPK, PCK, and LSK kernels, use a meta kernel for
      !>C     convenience.
      !>C
      !>      CALL FURNSH ( 'dgeodr_ex1.tm' )
      !>
      !>C
      !>C     Look up the radii for Mars.  Although we
      !>C     omit it here, we could first call BADKPV
      !>C     to make sure the variable BODY499_RADII
      !>C     has three elements and numeric data type.
      !>C     If the variable is not present in the kernel
      !>C     pool, BODVRD will signal an error.
      !>C
      !>      CALL BODVRD ( 'MARS', 'RADII', 3, N, RADII )
      !>
      !>C
      !>C     Compute flattening coefficient.
      !>C
      !>      RE  =  RADII(1)
      !>      RP  =  RADII(3)
      !>      F   =  ( RE - RP ) / RE
      !>
      !>C
      !>C     Look up the apparent state of earth as seen from Mars at
      !>C     January 1, 2005 TDB, relative to the IAU_MARS reference
      !>C     frame.
      !>C
      !>      CALL STR2ET ( 'January 1, 2005 TDB', ET )
      !>
      !>      CALL SPKEZR ( 'Earth', ET,    'IAU_MARS', 'LT+S',
      !>     .              'Mars',  STATE, LT                )
      !>
      !>C
      !>C     Convert position to geodetic coordinates.
      !>C
      !>      CALL RECGEO ( STATE, RE, F, LON, LAT, ALT )
      !>
      !>C
      !>C     Convert velocity to geodetic coordinates.
      !>C
      !>
      !>      CALL DGEODR (  STATE(1), STATE(2), STATE(3),
      !>     .               RE,       F,        JACOBI   )
      !>
      !>      CALL MXV ( JACOBI, STATE(4), GEOVEL )
      !>
      !>C
      !>C     As a check, convert the geodetic state back to
      !>C     rectangular coordinates.
      !>C
      !>      CALL GEOREC ( LON, LAT, ALT, RE, F, RECTAN )
      !>
      !>      CALL DRDGEO ( LON, LAT, ALT, RE, F, JACOBI )
      !>
      !>      CALL MXV ( JACOBI, GEOVEL, DRECTN )
      !>
      !>      WRITE(*,*) ' '
      !>      WRITE(*,*) 'Rectangular coordinates:'
      !>      WRITE(*,*) ' '
      !>      WRITE(*,FMT1) '  X (km)                 = ', STATE(1)
      !>      WRITE(*,FMT1) '  Y (km)                 = ', STATE(2)
      !>      WRITE(*,FMT1) '  Z (km)                 = ', STATE(3)
      !>      WRITE(*,*) ' '
      !>      WRITE(*,*) 'Rectangular velocity:'
      !>      WRITE(*,*) ' '
      !>      WRITE(*,FMT1) '  dX/dt (km/s)           = ', STATE(4)
      !>      WRITE(*,FMT1) '  dY/dt (km/s)           = ', STATE(5)
      !>      WRITE(*,FMT1) '  dZ/dt (km/s)           = ', STATE(6)
      !>      WRITE(*,*) ' '
      !>      WRITE(*,*) 'Ellipsoid shape parameters: '
      !>      WRITE(*,*) ' '
      !>      WRITE(*,FMT1) '  Equatorial radius (km) = ', RE
      !>      WRITE(*,FMT1) '  Polar radius      (km) = ', RP
      !>      WRITE(*,FMT1) '  Flattening coefficient = ', F
      !>      WRITE(*,*) ' '
      !>      WRITE(*,*) 'Geodetic coordinates:'
      !>      WRITE(*,*) ' '
      !>      WRITE(*,FMT1) '  Longitude (deg)        = ', LON / RPD()
      !>      WRITE(*,FMT1) '  Latitude  (deg)        = ', LAT / RPD()
      !>      WRITE(*,FMT1) '  Altitude  (km)         = ', ALT
      !>      WRITE(*,*) ' '
      !>      WRITE(*,*) 'Geodetic velocity:'
      !>      WRITE(*,*) ' '
      !>      WRITE(*,FMT1) '  d Longitude/dt (deg/s) = ',
      !>     .                                         GEOVEL(1)/RPD()
      !>      WRITE(*,FMT1) '  d Latitude/dt  (deg/s) = ',
      !>     .                                         GEOVEL(2)/RPD()
      !>      WRITE(*,FMT1) '  d Altitude/dt  (km/s)  = ', GEOVEL(3)
      !>      WRITE(*,*) ' '
      !>      WRITE(*,*) 'Rectangular coordinates from inverse ' //
      !>     .           'mapping:'
      !>      WRITE(*,*) ' '
      !>      WRITE(*,FMT1) '  X (km)                 = ', RECTAN(1)
      !>      WRITE(*,FMT1) '  Y (km)                 = ', RECTAN(2)
      !>      WRITE(*,FMT1) '  Z (km)                 = ', RECTAN(3)
      !>      WRITE(*,*) ' '
      !>      WRITE(*,*) 'Rectangular velocity from inverse mapping:'
      !>      WRITE(*,*) ' '
      !>      WRITE(*,FMT1) '  dX/dt (km/s)           = ', DRECTN(1)
      !>      WRITE(*,FMT1) '  dY/dt (km/s)           = ', DRECTN(2)
      !>      WRITE(*,FMT1) '  dZ/dt (km/s)           = ', DRECTN(3)
      !>      WRITE(*,*) ' '
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Rectangular coordinates:
      !>
      !>          X (km)                 =    -0.76096183E+08
      !>          Y (km)                 =     0.32436380E+09
      !>          Z (km)                 =     0.47470484E+08
      !>
      !>         Rectangular velocity:
      !>
      !>          dX/dt (km/s)           =     0.22952075E+05
      !>          dY/dt (km/s)           =     0.53760111E+04
      !>          dZ/dt (km/s)           =    -0.20881149E+02
      !>
      !>         Ellipsoid shape parameters:
      !>
      !>          Equatorial radius (km) =     0.33961900E+04
      !>          Polar radius      (km) =     0.33762000E+04
      !>          Flattening coefficient =     0.58860076E-02
      !>
      !>         Geodetic coordinates:
      !>
      !>          Longitude (deg)        =     0.10320290E+03
      !>          Latitude  (deg)        =     0.81089876E+01
      !>          Altitude  (km)         =     0.33653182E+09
      !>
      !>         Geodetic velocity:
      !>
      !>          d Longitude/dt (deg/s) =    -0.40539288E-02
      !>          d Latitude/dt  (deg/s) =    -0.33189934E-05
      !>          d Altitude/dt  (km/s)  =    -0.11211601E+02
      !>
      !>         Rectangular coordinates from inverse mapping:
      !>
      !>          X (km)                 =    -0.76096183E+08
      !>          Y (km)                 =     0.32436380E+09
      !>          Z (km)                 =     0.47470484E+08
      !>
      !>         Rectangular velocity from inverse mapping:
      !>
      !>          dX/dt (km/s)           =     0.22952075E+05
      !>          dY/dt (km/s)           =     0.53760111E+04
      !>          dZ/dt (km/s)           =    -0.20881149E+02
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 26-OCT-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>        Added complete code example.
      !>
      !>-    SPICELIB Version 1.0.0, 20-JUL-2001 (WLT)
      module subroutine dgeodr ( ctx, x, y, z, re, f, jacobi )
      use pepper_kinds, only: wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: x  !! X-coordinate of point.
      real(wp), intent(in) :: y  !! Y-coordinate of point.
      real(wp), intent(in) :: z  !! Z-coordinate of point.
      real(wp), intent(in) :: re  !! Equatorial radius of the reference spheroid.
      real(wp), intent(in) :: f  !! Flattening coefficient.
      real(wp), intent(out) :: jacobi ( 3, 3 )  !! Matrix of partial derivatives.

      real(wp) :: rectan  ( 3 )
      real(wp) :: long
      real(wp) :: lat
      real(wp) :: alt
      real(wp) :: injacb  ( 3, 3 )

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     If the flattening coefficient is greater than one, the polar
!     radius computed below is negative. If it's equal to one, the
!     polar radius is zero. Either case is a problem, so signal an
!     error.
!
      if ( f >= 1.0_wp ) then

          call ctx%setmsg ( 'Flattening coefficient was *.'  )
          call ctx%errdp  ( '*', f                           )
          call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'         )
          return

      end if

      if ( re <= 0.0_wp ) then

          call ctx%setmsg ( 'Equatorial Radius <= 0.0D0. RE = *' )
          call ctx%errdp  ( '*', re                              )
          call ctx%sigerr ( 'SPICE(BADRADIUS)'                   )
          return

      end if

!
!     There is a singularity of the Jacobian for points on the z-axis.
!
      if ( ( x == 0 ) .and. ( y == 0 ) ) then

         call ctx%setmsg ( 'The Jacobian of the transformation from '     // &
                       'rectangular to geodetic coordinates '         // &
                       'is not defined for points on the z-axis.'      )
         call ctx%sigerr ( 'SPICE(POINTONZAXIS)'                           )
         return

      end if

!
!     We will get the Jacobian of rectangular to geodetic by
!     implicit differentiation.
!
!     First move the X,Y and Z coordinates into a vector.
!
      rectan = [x, y, z]

!
!     Convert from rectangular to geodetic coordinates.
!
      call recgeo ( ctx, rectan, re, f, long, lat, alt  )

!
!     Get the Jacobian of the transformation from geodetic to
!     rectangular coordinates at LONG, LAT, ALT.
!
      call drdgeo ( ctx, long,  lat, alt, re, f, injacb )

!
!     Now invert INJACB to get the Jacobian of the transformation
!     from rectangular to geodetic coordinates.
!
      call invort ( ctx, injacb, jacobi )

      return
      end subroutine dgeodr

      !> Calculate the value of the time derivative of the
      !> half angle of a spherical body given a state vector
      !> STATE and body radius BODYR.
      !>
      !>## Detailed Input
      !>
      !>     STATE    is the state vector of a target body as seen from an
      !>              observer.
      !>
      !>     BODYR    is the radius of the target body observed from the
      !>              position in STATE; the target body assumed as a sphere.
      !>
      !>## Detailed Output
      !>
      !>     The function returns the double precision value of the time
      !>     derivative of the half angle of a spherical body in radians
      !>     per second.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the radius of the body BODYR is less than zero, the error
      !>         SPICE(BADRADIUS) is signaled.
      !>
      !>     2)  If the position component of STATE equals the zero vector, the
      !>         error SPICE(DEGENERATECASE) is signaled.
      !>
      !>     3)  If the body radius exceeds the distance from the body to the
      !>         observer, the error SPICE(BADGEOMETRY) is signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     In this discussion, the notation
      !>
      !>        < V1, V2 >
      !>
      !>     indicates the dot product of vectors V1 and V2.
      !>
      !>     The expression
      !>
      !>                     body_radius
      !>        sin(ALPHA) = -----------                                    (1)
      !>                       range
      !>
      !>     describes the half angle (ALPHA) of a spherical body, i.e. the
      !>     angular radius of the spherical body as viewed by an observer at
      !>     distance 'range'.
      !>
      !>     Solve for ALPHA
      !>
      !>                   -1  body_radius
      !>        ALPHA = sin  ( ----------- )                                (2)
      !>                         range
      !>
      !>     Take the derivative of ALPHA with respect to time
      !>
      !>        d                   1                   d    body_radius
      !>        --(ALPHA) =  --------------------- *    __ (----------- )   (3)
      !>        dt           1 -   body_radius  2   1/2 dt    range
      !>                  (      [ ----------- ]   )
      !>                            range
      !>
      !>        d              - body_radius             1      d
      !>        --(ALPHA) =  --------------------- *   ------ * __(range)   (4)
      !>        dt           1 -   body_radius  2  1/2      2   dt
      !>                  (      [ ----------- ]  )    range
      !>                            range
      !>
      !>     With
      !>                          _  _
      !>        d               < R, V >              -
      !>        -- ( range )  = -------- ,  range = ||R||                   (5)
      !>        dt                 -
      !>                         ||R||
      !>
      !>     Apply (5) to equation (4)
      !>                                                          _  _
      !>        d              - body_radius             1      < R, V >
      !>        --(ALPHA) =  --------------------- *   ------ *  --------   (6)
      !>        dt           1 -   body_radius  2  1/2     2     range
      !>                  (      [ ----------- ]  )    range
      !>                              range
      !>
      !>     Carry range through the denominator gives
      !>
      !>                                                  _  _
      !>        d              - body_radius            < R, V >
      !>        --(ALPHA) =  --------------------- *    --------            (7)
      !>        dt                 2            2  1/2        2
      !>                     (range - body_radius )      range
      !>
      !>     So since
      !>                        -    -         _  _
      !>          ^  -       <  R,   V >     < R, V >
      !>        < R, V >   =   ---        =  --------
      !>                        -              range
      !>                      ||R||
      !>
      !>                                                ^  _
      !>        d              - body_radius            < R, V >
      !>        --(ALPHA) =  --------------------- *    --------            (8)
      !>        dt                 2            2  1/2
      !>                     (range - body_radius )      range
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Compute the half angle derivative at the approximate time
      !>        corresponding to a maximal angular separation between the
      !>        Earth and Moon as seen from the Sun, and two weeks later.
      !>
      !>        The two derivate values shall have similar magnitudes but
      !>        opposite signs.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: dhfa_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de421.bsp                     Planetary ephemeris
      !>              pck00010.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0012.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de421.bsp',
      !>                                  'pck00010.tpc',
      !>                                  'naif0012.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM DHFA_EX
      !>      IMPLICIT              NONE
      !>
      !>      INTEGER               DIM
      !>
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      LT
      !>      DOUBLE PRECISION      DHADT
      !>      DOUBLE PRECISION      RAD   (3)
      !>      DOUBLE PRECISION      STATE (6)
      !>
      !>      INTEGER               STRLEN
      !>      PARAMETER           ( STRLEN = 64 )
      !>
      !>      CHARACTER*(STRLEN)    BEGSTR
      !>
      !>      DOUBLE PRECISION      SPD
      !>      DOUBLE PRECISION      DHFA
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ('dhfa_ex1.tm')
      !>
      !>C
      !>C     An approximate time corresponding to a maximal angular
      !>C     separation between the Earth and Moon as seen from the
      !>C     Sun.
      !>C
      !>      BEGSTR = '2007-DEC-17 04:04:46.935443 (TDB)'
      !>      CALL STR2ET( BEGSTR, ET )
      !>
      !>      CALL BODVRD ('SUN', 'RADII', 3, DIM, RAD )
      !>
      !>      CALL SPKEZR ('MOON', ET, 'J2000', 'NONE', 'SUN',
      !>     .              STATE, LT                         )
      !>
      !>C
      !>C     The derivative of the half angle at ET should have a
      !>C     near-to maximal value as the Moon velocity vector points
      !>C     either towards the Sun or away.
      !>C
      !>      DHADT = DHFA( STATE, RAD(1) )
      !>      WRITE(*,*) 'Half angle derivative:'
      !>      WRITE(*,*) '   at begin time  : ', DHADT
      !>
      !>C
      !>C     Two weeks later the derivate should have a similar
      !>C     magnitude but the opposite sign.
      !>C
      !>      ET = SPD() * 14.D0 + ET
      !>
      !>      CALL SPKEZR ('MOON', ET, 'J2000', 'NONE', 'SUN',
      !>     .              STATE, LT                         )
      !>
      !>      DHADT = DHFA( STATE, RAD(1) )
      !>      WRITE(*,*) '   two weeks later: ', DHADT
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Half angle derivative:
      !>            at begin time  :   -2.5387993682459762E-011
      !>            two weeks later:    2.9436205837172777E-011
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.2, 23-JUN-2020 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard. Added problem
      !>        statement and meta-kernel to the example. Modified output to
      !>        comply with maximum line length of header comments.
      !>
      !>-    SPICELIB Version 1.0.1, 06-JUL-2009 (EDW)
      !>
      !>        Rename of the ZZDHA call to DHFA.
      !>
      !>-    SPICELIB Version 1.0.0, 10-FEB-2009 (EDW) (NJB)
      module real(wp) function dhfa ( ctx, state, bodyr )
      use pepper_kinds, only: wp
      use pepper_math, only: unorm, vdot
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: state (6)  !! SPICE state vector
      real(wp), intent(in) :: bodyr  !! Radius of body

      real(wp) :: p     (3)
      real(wp) :: r
      real(wp) :: rngrat
      real(wp) :: base

      if ( ctx%failed() ) then
         dhfa = 0.0_wp
         return
      end if

!
!     A zero body radius (point object) returns a zero for the
!     derivative. A negative value indicates an error
!     the caller should diagnose.
!
      if ( bodyr == 0 ) then

         dhfa = 0.0_wp
         return

      else if ( bodyr < 0 ) then

         dhfa = 0.0_wp
         call ctx%setmsg( 'Non physical case. The input body radius ' &
            //        'has a negative value.'                      )
         call ctx%sigerr( 'SPICE(BADRADIUS)'                           )
         return

      end if

!
!     Normalize the position component of STATE. Store the unit vector
!     in P.
!
      call unorm( state(1), p, r)

      if ( all(p == 0.0_wp) ) then

         dhfa = 0.0_wp
         call ctx%setmsg( 'The position component of the input state ' &
            //        'vector equals the zero vector.'             )
         call ctx%sigerr( 'SPICE(DEGENERATECASE)'                      )
         return

      end if

!
!     Calculate the range rate.
!
      rngrat = vdot( p, state(4) )

!
!     Confirm R > BODYR.
!
      base = r**2 - bodyr**2

      if ( base <= 0 ) then

         dhfa = 0.0_wp
         call ctx%setmsg( 'Invalid case. The body radius, #1, equals ' &
            //        'or exceeds the range to the target, #2.'    )
         call ctx%errdp ( '#1', bodyr                                  )
         call ctx%errdp ( '#2', r                                      )
         call ctx%sigerr( 'SPICE(BADGEOMETRY)'                         )
         return

      end if

!
!     Now we safely take the square root of BASE.
!
      base = dsqrt( base )
      dhfa = -(rngrat * bodyr)/(base * r)

      return

      end function dhfa

      !> Diagonalize a symmetric 2x2 matrix.
      !>
      !>## Detailed Input
      !>
      !>     SYMMAT   is a symmetric 2x2 matrix. That is, SYMMAT has the
      !>              form
      !>
      !>                 .-        -.
      !>                 |  A    B  |
      !>                 |          |
      !>                 |  B    C  |
      !>                 `-        -'
      !>
      !>              This routine uses only the upper-triangular
      !>              elements of SYMMAT, that is, the elements
      !>
      !>                 SYMMAT(1,1)
      !>                 SYMMAT(1,2)
      !>                 SYMMAT(2,2)
      !>
      !>              to determine the outputs DIAG and ROTATE.
      !>
      !>## Detailed Output
      !>
      !>     DIAG,
      !>     ROTATE   are, respectively, a diagonal matrix and a 2x2
      !>              rotation matrix that satisfy the equation
      !>
      !>                                  T
      !>                 DIAG   =   ROTATE   *  SYMMAT  *  ROTATE.
      !>
      !>              In other words, DIAG is similar to SYMMAT, and ROTATE is
      !>              a change-of-basis matrix that diagonalizes SYMMAT. DIAGS2
      !>              chooses ROTATE so that its angle of rotation has the
      !>              smallest possible magnitude. If there are two rotations
      !>              that meet these criteria (they will be inverses of one
      !>              another), either rotation may be chosen.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     Error free.
      !>
      !>     1)  The matrix element SYMMAT(2,1) is not used in this routine's
      !>         computations, so the condition
      !>
      !>            SYMMAT(1,2)  .NE.  SYMMAT(2,1)
      !>
      !>         has no effect on this routine's outputs.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     The capability of diagonalizing a 2x2 symmetric matrix is
      !>     especially useful in a number of geometric applications
      !>     involving quadratic curves such as ellipses. Such curves are
      !>     described by expressions of the form
      !>
      !>           2                    2
      !>        A x   +   B xy   +   C y   +   D x    +    E y   +   F   =   0.
      !>
      !>     Diagonalization of the matrix
      !>
      !>        .-         -.
      !>        | A     B/2 |
      !>        |           |
      !>        | B/2     C |
      !>        `-         -'
      !>
      !>     allows us to perform a coordinate transformation (a rotation,
      !>     specifically) such that the equation of the curve becomes
      !>
      !>           2         2
      !>        P u   +   Q v   +   R u    +    S v   +   T   =   0
      !>
      !>     in the transformed coordinates. This form is much easier to
      !>     handle. If the quadratic curve in question is an ellipse,
      !>     we can easily find its center, semi-major axis, and semi-minor
      !>     axis from the second equation.
      !>
      !>     Ellipses turn up frequently in navigation geometry problems;
      !>     for example, the limb and terminator (if we treat the Sun as a
      !>     point source) of a body modeled as a tri-axial ellipsoid are
      !>     ellipses.
      !>
      !>     A mathematical note: because SYMMAT is symmetric, we can ALWAYS
      !>     find an orthogonal similarity transformation that diagonalizes
      !>     SYMMAT, and we can choose the similarity transformation to be a
      !>     rotation matrix. By `orthogonal' we mean that if the ROTATE is
      !>     the matrix in question, then
      !>
      !>              T                         T
      !>        ROTATE  ROTATE  =  ROTATE ROTATE  =  I.
      !>
      !>     The reasons this routine handles only the 2x2 case are: first,
      !>     the 2x2 case is much simpler than the general case, in which
      !>     iterative diagonalization methods must be used, and second, the
      !>     2x2 case is adequate for solving problems involving ellipses in
      !>     3 dimensional space. Finally, this routine can be used to
      !>     support a routine that solves the general-dimension
      !>     diagonalization problem for symmetric matrices.
      !>
      !>     Another feature of the routine that might provoke curiosity is
      !>     its insistence on choosing the diagonalization matrix that
      !>     rotates the original basis vectors by the smallest amount. The
      !>     rotation angle of ROTATE is of no concern for most applications,
      !>     but can be important if this routine is used as part of an
      !>     iterative diagonalization method for higher-dimensional matrices.
      !>     In that case, it is most undesirable to interchange diagonal
      !>     matrix elements willy-nilly; the matrix to be diagonalized could
      !>     get ever closer to being diagonal without converging. Choosing
      !>     the smallest rotation angle precludes this possibility.
      !>
      !>## Examples
      !>
      !>     1)  A case that can be verified by hand computation:
      !>         Suppose SYMMAT is
      !>
      !>            +-                -+
      !>            |  1.0D0    4.0D0  |
      !>            |                  |
      !>            |  4.0D0   -5.0D0  |
      !>            +-                -+
      !>
      !>         Then SYMMAT is similar to the diagonal matrix
      !>
      !>            +-                -+
      !>            |  3.0D0    0.0D0  |
      !>            |                  |
      !>            |  0.0D0   -7.0D0  |
      !>            +-                -+
      !>
      !>         so
      !>
      !>            DIAG(1,1) =  3.D0
      !>            DIAG(2,1) =  0.D0
      !>            DIAG(1,2) =  0.D0
      !>            DIAG(2,2) = -7.D0
      !>
      !>         and ROTATE is
      !>
      !>            +-                                   -+
      !>            |   0.894427191          -0.447213595 |
      !>            |                                     |
      !>            |   0.447213595           0.894427191 |
      !>            +-                                   -+
      !>
      !>        which is an approximation to
      !>
      !>            +-                                   -+
      !>            |  0.4 * 5**(1/2)     -0.2 * 5**(1/2) |
      !>            |                                     |
      !>            |  0.2 * 5**(1/2)      0.4 * 5**(1/2) |
      !>            +-                                   -+
      !>
      !>     2)  Suppose we want to find the semi-axes of the ellipse defined
      !>         by
      !>                2                 2
      !>            27 x  +  10 xy  +  3 y   =  1.
      !>
      !>         We can write the above equation as the matrix equation
      !>
      !>            +-     -+  +-         -+  +- -+
      !>            | x   y |  | 27     5  |  | x |    =   1;
      !>            +-     -+  |           |  |   |
      !>                       |  5     3  |  | y |
      !>                       +-         -+  +- -+
      !>
      !>         let SYMMAT be the symmetric matrix on the left. The code
      !>         fragment
      !>
      !>            SYMMAT(1,1)  =  27.D0
      !>            SYMMAT(2,1)  =   5.D0
      !>            SYMMAT(1,2)  =   5.D0
      !>            SYMMAT(2,2)  =   3.D0
      !>
      !>            CALL DIAGS2 ( SYMMAT, DIAG, ROTATE )
      !>
      !>         will return DIAG, an array containing the eigenvalues of
      !>         SYMMAT, and ROTATE, the coordinate transformation required
      !>         to diagonalize SYMMAT. In this case,
      !>
      !>            DIAG(1,1)   =  28.D0
      !>            DIAG(2,1)   =  0.D0
      !>            DIAG(1,2)   =  0.D0
      !>            DIAG(2,2)   =  2.D0
      !>
      !>          and
      !>
      !>            ROTATE(1,1) =  0.980580676D0
      !>            ROTATE(2,1) =  0.196116135D0
      !>            ROTATE(1,2) = -0.196116135D0
      !>            ROTATE(2,2) =  0.980580676D0
      !>
      !>         The columns of ROTATE give the ellipse's axes, after scaling
      !>         them by
      !>
      !>                   1                            1
      !>            ----------------     and     ---------------
      !>              ____________                 ____________
      !>            \/  DIAG(1,1)                \/  DIAG(2,2)
      !>
      !>         respectively.
      !>
      !>         If SMAJOR and SMINOR are semi-major and semi-minor axes,
      !>         we can find them as shown below. For brevity, we omit the
      !>         check for zero or negative eigenvalues. Negative or zero
      !>         eigenvalues will occur only as a result of round-off error;
      !>         mathematically, the eigenvalues of the matrix SYMMAT are
      !>         guaranteed to be positive, since they are the reciprocals of
      !>         the squares of the lengths of the ellipse's semi-axes.
      !>
      !>            DO I = 1, 2
      !>               SMAJOR(I) = ROTATE(I,1)  /  DSQRT( DIAG(1,1) )
      !>               SMINOR(I) = ROTATE(I,2)  /  DSQRT( DIAG(2,2) )
      !>            END DO
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     [1]  T. Apostol, "Calculus, Vol. II," chapter 5, "Eigenvalues of
      !>          Operators Acting on Euclidean Spaces," John Wiley & Sons,
      !>          1969.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.3.0, 17-JUN-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard. Added
      !>        "Error free." to $Exceptions section. Removed unnecessary
      !>        $Revisions section.
      !>
      !>-    SPICELIB Version 1.2.0, 06-SEP-2005 (NJB)
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in VHATG and SWAPD calls.
      !>
      !>-    SPICELIB Version 1.1.0, 24-JAN-2002 (EDW)
      !>
      !>        Edited incorrect examples in the header. The example
      !>        outputs did not correspond to the actual function
      !>        of the routine.
      !>
      !>-    SPICELIB Version 1.0.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.0.0, 04-NOV-1990 (NJB)
      module subroutine diags2 ( ctx, symmat, diag, rotate )
      use pepper_kinds, only: wp
      use pepper_math, only: vhatg
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: symmat ( 2, 2 )  !! A symmetric 2x2 matrix.
      real(wp), intent(out) :: diag   ( 2, 2 )  !! A diagonal matrix similar to SYMMAT.
      real(wp), intent(out) :: rotate ( 2, 2 )  !! A rotation used as the similarity transformation.
      real(wp) :: a
      real(wp) :: b
      real(wp) :: c
      real(wp) :: eigvec ( 2 )
      real(wp) :: root1  ( 2 )
      real(wp) :: root2  ( 2 )
      real(wp) :: scale
      real(wp) :: tmpd
      real(wp) :: tmpv   ( 2 )
      if ( .not. allocated ( ctx%diags2_state ) ) allocate ( ctx%diags2_state )
      associate ( ident => ctx%diags2_state%ident )
      if ( ctx%failed() ) return

!
!     We check for the case of a diagonal input matrix, since
!     eigenvector determination is simplified by ruling out this
!     case.

      if  ( symmat(1,2) == 0.0_wp ) then

         rotate = ident
         diag = symmat
!
!        Explicitly zero out the (2,1) entry of DIAG, since DIAG is
!        guaranteed to be diagonal.
!
         diag(2,1) = 0.0_wp

         return

      end if

!
!     Getting here means there's some actual work to do.  We start out
!     by scaling our matrix, in order to reduce the chance of overflow.
!     We divide everything by the largest magnitude of any element of
!     SYMMAT.  We're guaranteed that SCALE is non-zero, since the 0
!     matrix is diagonal.
!
      scale  =  max (  dabs( symmat(1,1) ), &
                       dabs( symmat(1,2) ), &
                       dabs( symmat(2,2) )   )

      a      =  symmat(1,1) / scale
      b      =  symmat(1,2) / scale
      c      =  symmat(2,2) / scale

!
!     Compute the eigenvalues of the scaled version of SYMMAT.  The
!     eigenvalues are roots of the equation
!
!          DET (  (1 / SCALE) * SYMMAT  -  x * IDENTITY  ) = 0,
!
!     or equivalently,
!
!           2                             2
!          x   -  ( A + C ) x  +  ( AC - B )  =   0.
!
      call rquad ( ctx,  1.0_wp,  -(a + c),   a*c - b**2,   root1,   root2   )

!
!     ROOT1 is the root corresponding to the positive discriminant term;
!     this is guaranteed by RQUAD.
!
      diag(1,1) = root1(1)
      diag(2,1) = 0.0_wp
      diag(1,2) = 0.0_wp
      diag(2,2) = root2(1)

!
!     Our next job is to find an eigenvector corresponding to the
!     eigenvalue of smaller magnitude.  We can unitize it and choose
!     an orthogonal unit vector so as to create the desired rotation
!     matrix.
!
!        If our original matrix is
!
!           +-        -+
!           |  A    B  |
!           |          |,
!           |  B    C  |
!           +-        -+
!
!        then the matrix
!
!           +-                                -+
!           |  A - DIAG(x,x)    B              |
!           |                                  |
!           |  B                C - DIAG(x,x)  |
!           +-                                -+
!
!        maps to zero all elements of the eigenspace corresponding to
!        DIAG(x,x), where x is either 1 or 2.
!
!        So
!
!           +-               -+           +-               -+
!           |  B              |           |  DIAG(x,x) - C  |
!           |                 |   and     |                 |
!           |  DIAG(x,x) - A  |           |  B              |
!           +-               -+           +-               -+
!
!        are candidates for eigenvectors for DIAG(x,x).  To minimize
!        loss of accuracy in our eigenvector due to subtraction of
!        nearly equal quantities, we choose the vector in which the
!        term involving the eigenvalue has the larger magnitude.  The
!        rigorous justification of this choice would literally take
!        pages of explanation, and we are not going to go through it
!        here.  In most cases, either choice is satisfactory, and in
!        the case where cancellation is a problem, our choice is
!        preferable.
!
!        Note that there is nothing to be gained as far as accuracy is
!        concerned by working with one eigenvalue as opposed to the
!        other:  the magnitudes of the quantities DIAG(x,x) - A and
!        DIAG(x,x) - C would be interchanged by taking x = '2' instead
!        of x = '1'.
!

      if (  dabs( diag(1,1) - a ) >= dabs( diag(1,1) - c )  ) then
!
!        In this case, the second eigenvector component EIGVEC(2)
!        should be larger than |B|; we explain why in detail below.
!        We use the MAX function below to guard against reversal of the
!        inequality due to round-off error.
!
         eigvec(1)  =  b
         eigvec(2)  =  max (   diag(1,1) - a,   abs(b)   )

!
!        Recall that DIAG(1,1) is an eigenvalue of the scaled version
!        of SYMMAT
!
!           +-      -+
!           | A    B |
!           |        |.
!           | B    C |
!           +-      -+
!
!        DIAG(1,1) is the positive-discriminant root of this matrix's
!        characteristic equation.  EIGVEC's y-component
!
!           DIAG(1,1) - A
!
!        is positive and of magnitude at least as large as that of B,
!        since it is the larger of
!                                                 ______________________
!                                                /         2
!                             C - A             / ( A - C )           2
!           DIAG(1,1) - A  =  -----   +     \  /  ----------    +    B
!                               2            \/       4
!
!        and
!                                                 ______________________
!                                                /         2
!                             A - C             / ( A - C )           2
!           DIAG(1,1) - C  =  -----   +     \  /  ----------    +    B
!                               2            \/       4
!
!        Equality between these expressions can occur only when A is
!        equal to C, in which case both expressions are equal (except
!        for round-off error) to |B|.
!

!
!        So the argument of EIGVEC is in the interval [pi/4, 3*pi/4].
!        The second eigenvector is EIGVEC, and the first
!        eigenvector is found by rotating EIGVEC by -pi/2.  Since
!        DIAG(1,1) is the eigenvalue for the SECOND eigenvector, we
!        must swap the eigenvalues.
!

!
!        Unitize the eigenvector.
!
         call vhatg ( eigvec, 2, tmpv   )
         eigvec = tmpv

         rotate(1,1)  =  eigvec(2)
         rotate(2,1)  = -eigvec(1)
         rotate(1,2)  =  eigvec(1)
         rotate(2,2)  =  eigvec(2)

!
!        Swap DIAG(1,1) and DIAG(2,2).
!
         tmpd         =  diag(2,2)
         diag(2,2)    =  diag(1,1)
         diag(1,1)    =  tmpd

      else

         eigvec(1)  =  max (  diag(1,1) - c,   abs(b)  )
         eigvec(2)  =  b

!
!        The x-component of EIGVEC is positive and has magnitude
!        greater than or equal to that of the y-component of EIGVEC.
!        The argument of EIGVEC is in [-pi/4, pi/4], and the second
!        eigenvector is found by rotating EIGVEC by pi/2.
!

!
!        Unitize the eigenvector.
!
         call vhatg ( eigvec, 2, tmpv   )
         eigvec = tmpv

         rotate(1,1)  =  eigvec(1)
         rotate(2,1)  =  eigvec(2)
         rotate(1,2)  = -eigvec(2)
         rotate(2,2)  =  eigvec(1)

      end if

!
!     We must scale the eigenvalues.
!
      diag(1,1)  =  diag(1,1)  *  scale
      diag(2,2)  =  diag(2,2)  *  scale

      return
      end associate
      end subroutine diags2

      !> Calculate the derivative with respect to the angle of rotation
      !> of a 3x3 coordinate system rotation matrix generated by a
      !> rotation of a specified angle about a specified axis.
      !>
      !>## Detailed Input
      !>
      !>     ANGLE    is the angle given in radians, through which the rotation
      !>              is performed.
      !>
      !>     IAXIS    is the coordinate axis number of the rotation. The X, Y,
      !>              and Z axes have indices 1, 2 and 3 respectively.
      !>
      !>              Together ANGLE and IAXIS define the coordinate system
      !>              rotation [ANGLE]     .
      !>                              IAXIS
      !>
      !>## Detailed Output
      !>
      !>     DMOUT    is the derivative of the rotation matrix with respect to
      !>              the angle of rotation. That is, DMOUT is the derivative
      !>              with respect to ANGLE of the matrix [ANGLE]     .
      !>                                                         IAXIS
      !>
      !>              (The rotation matrix being differentiated describes
      !>              the rotation of the COORDINATE system through ANGLE
      !>              radians about the axis whose index is IAXIS.)
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the axis index is not in the range 1 to 3, the error
      !>         SPICE(BADAXIS) is signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     A coordinate system rotation by ANGLE radians rotation about
      !>     the first, i.e. x-axis, [ANGLE]  is described by
      !>                                    1
      !>
      !>           |  1        0          0      |
      !>           |  0   cos(ANGLE) sin(ANGLE)  |
      !>           |  0  -sin(ANGLE) cos(ANGLE)  |
      !>
      !>     A coordinate system rotation by ANGLE radians rotation about the
      !>     second, i.e. y-axis, [ANGLE]  is described by
      !>                                 2
      !>
      !>           |  cos(ANGLE)  0  -sin(ANGLE)  |
      !>           |      0       1        0      |
      !>           |  sin(ANGLE)  0   cos(ANGLE)  |
      !>
      !>     A coordinate system rotation by ANGLE radians rotation about
      !>     the third, i.e. z-axis, [ANGLE]  is described by
      !>                         3
      !>
      !>           |  cos(ANGLE) sin(ANGLE)   0   |
      !>           | -sin(ANGLE) cos(ANGLE)   0   |
      !>           |       0          0       1   |
      !>
      !>     The derivatives of these matrices are:
      !>
      !>     about the x-axis
      !>
      !>           |  0        0           0      |
      !>           |  0  -sin(ANGLE)  cos(ANGLE)  |
      !>           |  0  -cos(ANGLE) -sin(ANGLE)  |
      !>
      !>     about the y-axis
      !>
      !>           | -sin(ANGLE)  0  -cos(ANGLE)  |
      !>           |      0       0        0      |
      !>           |  cos(ANGLE)  0  -sin(ANGLE)  |
      !>
      !>     about the z-axis
      !>
      !>           | -sin(ANGLE)  cos(ANGLE)   0   |
      !>           | -cos(ANGLE) -sin(ANGLE)   0   |
      !>           |       0           0       0   |
      !>
      !>## Examples
      !>
      !>     If ROTATE is called from a FORTRAN program as follows:
      !>
      !>           CALL DROTAT (PI()/4, 3, DMOUT)
      !>
      !>     then DMOUT will be
      !>
      !>           |-SQRT(2)/2   SQRT(2)/2   0  |
      !>           |-SQRT(2)/2  -SQRT(2)/2   0  |
      !>           |     0           0       0  |
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 12-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.0.0, 05-NOV-1990 (WLT)
      module subroutine drotat ( ctx, angle, iaxis, dmout )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: angle  !! Angle of rotation (radians).
      integer(ip), intent(in) :: iaxis  !! Coordinate axis number (X=1, Y=2, Z=3).
      real(wp), intent(out) :: dmout  ( 3,3 )  !! Derivative of rotation matrix [ANGLE] w.r.t. angle IAXIS

      real(wp) :: s
      real(wp) :: c

      integer(ip) :: i1
      integer(ip) :: i2
      integer(ip) :: i3
      integer(ip), parameter :: indexs ( 5 ) = &
         [ 1, 2, 3, 1, 2 ]

!
!     First make sure the input axis is reasonable.
!
      if (      ( iaxis > 3 ) &
           .or. ( iaxis < 1 ) ) then

         call ctx%setmsg ( 'The input axis is out of range.  Its value '  // &
                       'is #.')
         call ctx%errint ( '#', iaxis       )
         call ctx%sigerr ( 'SPICE(BADAXIS)' )
         return

      end if

!
!     Get the sine and cosine of ANGLE
!
      s  = dsin(angle)
      c  = dcos(angle)

!
!     Get indices for axes. The first index is for the axis of rotation.
!     The next two axes follow in right hand order (XYZ).
!
      i1 = indexs( iaxis     )
      i2 = indexs( iaxis + 1 )
      i3 = indexs( iaxis + 2 )

!
!  Construct the rotation matrix
!
      dmout(i1,i1) =  0.0_wp
      dmout(i2,i1) =  0.0_wp
      dmout(i3,i1) =  0.0_wp
      dmout(i1,i2) =  0.0_wp
      dmout(i2,i2) = -s
      dmout(i3,i2) = -c
      dmout(i1,i3) =  0.0_wp
      dmout(i2,i3) =  c
      dmout(i3,i3) = -s
      return
      end subroutine drotat

      !> Locate a keyword and succeeding numeric words within a string.
      !> Parse and store the numeric words. Remove the keyword and
      !> numeric words from the input string.
      !>
      !>## Detailed Input
      !>
      !>     KEYWD    is a word used to mark the start of a set of numeric
      !>              words of interest.
      !>
      !>     MAXWDS   is the maximum number of numeric words that can be
      !>              parsed and returned.
      !>
      !>     STRING   is a string potentially containing KEYWD and numbers.
      !>
      !>## Detailed Output
      !>
      !>     STRING   is the input string stripped of all parsed
      !>              numeric words. If there was room available to parse
      !>              all of the numeric words associated with KEYWD, the
      !>              keyword that marked the beginning of the parsed
      !>              numbers in the original string will also be removed.
      !>
      !>     NFOUND   is the number of numeric words that were found
      !>              following KEYWD but preceding the next non-numeric
      !>              word of the string. If the KEYWD is not present in
      !>              the string, NFOUND is returned as -1. If the keyword
      !>              is located but the next word in the string is
      !>              non-numeric NFOUND will be returned as 0.
      !>
      !>     PARSED   is the number of numeric words that were actually
      !>              parsed and stored in the output array VALUES. If no
      !>              values are parsed PARSED is returned as 0.
      !>
      !>     VALUES   are the double precision values for the parsed
      !>              numeric words that follow the first occurrence of the
      !>              keyword but precede the next non-numeric word.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     Error free.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     Definitions:
      !>
      !>        WORD           is a set of consecutive non-blank characters
      !>                       delimited by blanks or the end of the string
      !>                       that contains them.
      !>
      !>        NUMERIC WORD   a word that can be parsed by the
      !>                       SPICELIB routine NPARSD without error. All
      !>                       FORTRAN numeric representations are numeric
      !>                       words. In addition 'PI', 'Pi', 'pI', and 'pi'
      !>                       are all recognized as having the value:
      !>
      !>                          3.1415926535897932384626D0
      !>
      !>                       See NPARSD FOR A a full description of
      !>                       legitimate numeric words.
      !>
      !>     Given a string and a keyword this routine locates the first
      !>     occurrence of the keyword in the string and returns the double
      !>     precision representations of up to MAXWDS succeeding numeric
      !>     words. All parsed numeric words are removed from the string.
      !>     If every numeric word following KEYWD but preceding the next
      !>     non-numeric word is parsed,  KEYWD will also be removed from
      !>     the string.
      !>
      !>     If the keyword cannot be located in the string, the variable
      !>     NFOUND will be returned as -1 and the string will be unchanged.
      !>
      !>     In all other cases, some part of the string (possibly all of it)
      !>     will be removed.
      !>
      !>## Examples
      !>
      !>     Input   STRING  'LONGITUDE 39.2829  LATITUDE 24.27682'
      !>             KEYWD   'LONGITUDE'
      !>             MAXWDS   4
      !>
      !>     Output: STRING  '  LATITUDE 24.27682'
      !>             NFOUND  1
      !>             PARSED  1
      !>             VALUES  3.92829D+01
      !>
      !>     Input   STRING  'THIS IS A BAD STRING FOR NUMBERS'
      !>             KEYWD   'RADIUS'
      !>             MAXWDS  2
      !>
      !>     Output: STRING  'THIS IS A BAD STRING FOR NUMBERS'
      !>             NFOUND  -1
      !>             PARSED   0
      !>             VALUES   (unchanged)
      !>
      !>     Input   STRING  'PRIMES 11  13 17 19 23 NON-PRIMES 12 14 15'
      !>             KEYWD   'PRIMES'
      !>             MAXWDS  3
      !>
      !>     Output: STRING  'PRIMES  19 23 NON-PRIMES 12 14 15'
      !>             NFOUND  5
      !>             PARSED  3
      !>             VALUES  1.1D+01
      !>                     1.3D+01
      !>                     1.7D+01
      !>
      !>     Input   STRING  'PRIMES 11  13 17 19 23 NON-PRIMES 12 14 15'
      !>             KEYWD   'PRIMES'
      !>             MAXWDS  5
      !>
      !>     Output: STRING  ' NON-PRIMES 12 14 15'
      !>             NFOUND  5
      !>             PARSED  5
      !>             VALUES  1.1D+01
      !>                     1.3D+01
      !>                     1.7D+01
      !>                     1.9D+01
      !>                     2.3D+01
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     H.A. Neilan        (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 05-JUN-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.1.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.1.0, 23-MAY-1990 (HAN)
      !>
      !>        The variable FOUND was changed to NFOUND.
      !>
      !>-    SPICELIB Version 1.0.0, 31-JAN-1990 (WLT) (IMU)
      !>
      !>## Revisions
      !>
      !>-     SPICELIB Version 1.1.0, 23-MAY-1990 (HAN)
      !>
      !>         The variable FOUND was changed to NFOUND. Other SPICELIB
      !>         routines that use the variable FOUND declare it as a logical.
      !>         In order to conform to this convention, FOUND was changed to
      !>         NFOUND to indicate that it has an integer value, not a logical
      !>         value.
      module subroutine dxtrct ( ctx, keywd, maxwds, string, nfound, parsed, values )
      use pepper_kinds, only: ip, wp
      use pepper_strings, only: fndnwd, nblen, nparsd, wdindx
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: keywd  !! Keyword used to mark start of a set of numbers.
      integer(ip), intent(in) :: maxwds  !! Maximum number of numeric words that can be parsed
      character(*), intent(inout) :: string  !! String potentially containing KEYWD and numbers.
      integer(ip), intent(out) :: nfound  !! Number of numeric words found following the KEYWD.
      integer(ip), intent(out) :: parsed  !! Number of numeric words translated and returned.
      real(wp), intent(out) :: values ( * )  !! The double precision values for the numbers.

      integer(ip) :: length
      integer(ip) :: positn

      integer(ip) :: berase
      integer(ip) :: eerase
      integer(ip) :: fallbk

      integer(ip) :: start
      integer(ip) :: i
      integer(ip) :: j

      real(wp) :: x
      character(80) :: error
      integer(ip) :: pntr

!
!     No keywords or numbers have been located yet.
!
      nfound  =  0
      parsed  =  0

!
!     Locate the keyword within the string and get the length of the
!     string.
!
      positn  =  wdindx ( string, keywd )
      length  =  len_trim(string)

      if ( positn == 0 ) then
         nfound = -1
         parsed =  0
         return
      end if

!
!     Set the begin erase marker to the start of the current word
!     Set the end   erase marker to the end   of the current word
!
      berase  = positn
      eerase  = positn + nblen(keywd) - 1

      start   = eerase + 1

      if ( start < length ) then

!
!        Locate the next word and try to parse it ...
!
         call fndnwd ( string,      start, i,     j    )
         call nparsd ( string(i:j), x,     error, pntr )

         if ( error == ' ' ) then
!
!           ...  mark its starting position as a possible starting
!           point for deletion if we run out of room for parsed numbers.
!
            fallbk         = i
            eerase         = j
            start          = j      + 1
            nfound         = nfound + 1
            parsed         = parsed + 1
            values(parsed) = x
         end if

      else

         string(berase: )  = ' '
         return

      end if

!
!     Now find all of the succeeding numeric words until we run out of
!     numeric words or string to look at.
!
      do while (       ( start < length ) &
                 .and. ( error == ' '    ) )

!
!        Find the next word and try to parse it as a number.
!
         call fndnwd ( string,      start, i,     j       )
         call nparsd ( string(i:j), x,     error, pntr )

         if ( error == ' ' ) then

!
!           It's a number! Congratulations!
!
            nfound = nfound + 1

!
!           If there is room ...
!
            if ( nfound <= maxwds ) then

!
!              1.  Increment the counter PARSED.
!              2.  Load the DP value into the output array.
!              3.  Set the pointer for the end of the erase
!                   region to be the end of this word.
!
               parsed         = parsed + 1
               values(parsed) = x
               eerase         = j

            else

!
!              Set the pointer of the begin erase region to be the
!              the pointer set up just for this occasion.
!
               berase = fallbk

            end if

!
!           Set the place to begin looking for the next word to be
!           at the first character following the end of the current
!           word.
!
            start = j + 1

         end if

      end do

!
!     Remove the parsed words from the string.
!
      i = berase
      j = eerase + 1

      do while ( j <= length )
         string(i:i) = string(j:j)
         i           = i + 1
         j           = j + 1
      end do

      string(i:) = ' '

      return

      end subroutine dxtrct

      !> **Deprecated:** This routine has been superseded by the SPICELIB
      !> routine [[evsgp4]]. *ALL* TLE evaluations should use that routine.
      !> NAIF supports [[ev2lin]] only for backward compatibility.
      !>
      !> Evaluate NORAD two-line element data for near-earth, earth
      !> orbiting spacecraft (that is spacecraft with orbital periods
      !> less-than 225 minutes). This evaluator uses algorithms as
      !> described in Hoots 1980 [1].
      !>
      !>## Detailed Input
      !>
      !>     ET       is the epoch in TDB seconds past ephemeris epoch J2000
      !>              at which a state should be produced from the
      !>              input elements.
      !>
      !>     GEOPHS   is a collection of 8 geophysical constants needed
      !>              for computing a state. The order of these
      !>              constants must be:
      !>
      !>                 GEOPHS(1) = J2 gravitational harmonic for Earth.
      !>                 GEOPHS(2) = J3 gravitational harmonic for Earth.
      !>                 GEOPHS(3) = J4 gravitational harmonic for Earth.
      !>
      !>              These first three constants are dimensionless.
      !>
      !>                 GEOPHS(4) = KE: Square root of the GM for Earth where
      !>                             GM is expressed in Earth radii cubed per
      !>                             minutes squared.
      !>
      !>                 GEOPHS(5) = QO: High altitude bound for atmospheric
      !>                             model in km.
      !>
      !>                 GEOPHS(6) = SO: Low altitude bound for atmospheric
      !>                             model in km.
      !>
      !>                 GEOPHS(7) = RE: Equatorial radius of the earth in km.
      !>
      !>                 GEOPHS(8) = AE: Distance units/earth radius
      !>                             (normally 1)
      !>
      !>              Below are currently recommended values for these
      !>              items:
      !>
      !>                 J2 =    1.082616D-3
      !>                 J3 =   -2.53881D-6
      !>                 J4 =   -1.65597D-6
      !>
      !>              The next item is the square root of GM for the Earth
      !>              given in units of earth-radii**1.5/Minute
      !>
      !>                 KE =    7.43669161D-2
      !>
      !>              The next two items define the top and bottom of the
      !>              atmospheric drag model used by the type 10 ephemeris
      !>              type. Don't adjust these unless you understand the full
      !>              implications of such changes.
      !>
      !>                 QO =  120.0D0
      !>                 SO =   78.0D0
      !>
      !>              The ER value is the equatorial radius in km of the Earth
      !>              as used by NORAD.
      !>
      !>                 ER = 6378.135D0
      !>
      !>              The value of AE is the number of distance units per
      !>              Earth radii used by the NORAD state propagation
      !>              software. The value should be 1 unless you've got a very
      !>              good understanding of the NORAD routine SGP4 and the
      !>              affect of changing this value.
      !>
      !>                 AE =    1.0D0
      !>
      !>     ELEMS    is an array containing two-line element data
      !>              as prescribed below. The elements NDD6O and BSTAR
      !>              must already be scaled by the proper exponent stored
      !>              in the two line elements set. Moreover, the
      !>              various items must be converted to the units shown
      !>              here.
      !>
      !>                 ELEMS (  1 ) = NDT20 in radians/minute**2
      !>                 ELEMS (  2 ) = NDD60 in radians/minute**3
      !>                 ELEMS (  3 ) = BSTAR
      !>                 ELEMS (  4 ) = INCL  in radians
      !>                 ELEMS (  5 ) = NODE0 in radians
      !>                 ELEMS (  6 ) = ECC
      !>                 ELEMS (  7 ) = OMEGA in radians
      !>                 ELEMS (  8 ) = M0    in radians
      !>                 ELEMS (  9 ) = N0    in radians/minute
      !>                 ELEMS ( 10 ) = EPOCH of the elements in seconds
      !>                                past ephemeris epoch J2000.
      !>
      !>## Detailed Output
      !>
      !>     STATE    is the state produced by evaluating the input elements
      !>              at the input epoch ET. Units are km and km/sec relative
      !>              to the TEME reference frame.
      !>
      !>## Parameters
      !>
      !>     NMODL    is a parameter that controls how many element sets
      !>              can be buffered internally. Since there are a lot
      !>              of computations that are independent of time these
      !>              are buffered and only computed if an unbuffered
      !>              model is supplied. This value should always
      !>              be at least 2. Increasing it a great deal is not
      !>              advised since the time needed to search the
      !>              buffered elements for a match increases linearly
      !>              with the NMODL. Empirically, 6 seems to be a good
      !>              break even value for NMODL.
      !>
      !>## Exceptions
      !>
      !>     1)  No checks are made on the reasonableness of the inputs.
      !>
      !>     2)  If the number of iterations for the calculation exceeds the
      !>         limit for this value, the error SPICE(ITERATIONEXCEEDED) is
      !>         signaled. This error should signal only for bad (nonphysical)
      !>         TLEs.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine evaluates NORAD two-line element sets for
      !>     near-earth orbiting satellites using the algorithms described in
      !>     Hoots 1980 [1]. This code is an adaptation of
      !>     the NORAD routine SGP4 to eliminate common blocks, allow
      !>     buffering of models and intermediate parameters and double
      !>     precision calculations.
      !>
      !>     Near earth is as an orbital period of less than 225
      !>     minutes.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Suppose you have a set of two-line elements for the LUME 1
      !>        cubesat. This example shows how you can use this routine
      !>        together with the routine GETELM to propagate a state to an
      !>        epoch of interest.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: ev2lin_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name           Contents
      !>              ---------           ------------------------------------
      !>              naif0012.tls        Leapseconds
      !>              geophysical.ker     geophysical constants for evaluation
      !>                                  of two-line element sets.
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'naif0012.tls',
      !>                                  'geophysical.ker'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EV2LIN_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local parameters.
      !>C
      !>      CHARACTER*(*)         TIMSTR
      !>      PARAMETER           ( TIMSTR = '2020-05-26 02:25:00' )
      !>
      !>      INTEGER               PNAMLN
      !>      PARAMETER           ( PNAMLN = 2  )
      !>
      !>      INTEGER               TLELLN
      !>      PARAMETER           ( TLELLN = 69 )
      !>
      !>C
      !>C     The LUME-1 cubesat is an Earth orbiting object; set
      !>C     the center ID to the Earth ID.
      !>C
      !>      INTEGER               CENTER
      !>      PARAMETER           ( CENTER  = 399     )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      CHARACTER*(PNAMLN)    NOADPN ( 8  )
      !>      CHARACTER*(TLELLN)    TLE    ( 2  )
      !>
      !>      DOUBLE PRECISION      ELEMS  ( 10 )
      !>      DOUBLE PRECISION      EPOCH
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      GEOPHS ( 8  )
      !>      DOUBLE PRECISION      STATE  ( 6  )
      !>
      !>      INTEGER               I
      !>      INTEGER               N
      !>
      !>C
      !>C     These are the variables that will hold the constants
      !>C     required by EV2LIN. These constants are available from
      !>C     the loaded PCK file, which provides the actual values
      !>C     and units as used by NORAD propagation model.
      !>C
      !>C        Constant   Meaning
      !>C        --------   ------------------------------------------
      !>C        J2         J2 gravitational harmonic for Earth.
      !>C        J3         J3 gravitational harmonic for Earth.
      !>C        J4         J4 gravitational harmonic for Earth.
      !>C        KE         Square root of the GM for Earth.
      !>C        QO         High altitude bound for atmospheric model.
      !>C        SO         Low altitude bound for atmospheric model.
      !>C        ER         Equatorial radius of the Earth.
      !>C        AE         Distance units/earth radius.
      !>C
      !>      DATA          NOADPN  /  'J2', 'J3', 'J4', 'KE',
      !>     .                         'QO', 'SO', 'ER', 'AE'  /
      !>
      !>C
      !>C     Define the Two-Line Element set for LUME-1.
      !>C
      !>      TLE(1)  = '1 43908U 18111AJ  20146.60805006  .00000806'
      !>     .      //                   '  00000-0  34965-4 0  9999'
      !>      TLE(2)  = '2 43908  97.2676  47.2136 0020001 220.6050 '
      !>     .      //                   '139.3698 15.24999521 78544'
      !>
      !>C
      !>C     Load the PCK file that provides the geophysical
      !>C     constants required for the evaluation of the two-line
      !>C     elements sets. Load also an LSK, as it is required by
      !>C     GETELM to perform time conversions. Use a meta-kernel for
      !>C     convenience.
      !>C
      !>      CALL FURNSH ( 'ev2lin_ex1.tm' )
      !>
      !>C
      !>C     Retrieve the data from the kernel, and place it on
      !>C     the GEOPHS array.
      !>C
      !>      DO I = 1, 8
      !>
      !>         CALL BODVCD ( CENTER, NOADPN(I), 1, N, GEOPHS(I) )
      !>
      !>      END DO
      !>
      !>C
      !>C     Convert the Two Line Elements lines to the element sets.
      !>C     Set the lower bound for the years to be the beginning
      !>C     of the space age.
      !>C
      !>      CALL GETELM ( 1957, TLE, EPOCH, ELEMS )
      !>
      !>C
      !>C     Now propagate the state using EV2LIN to the epoch of
      !>C     interest.
      !>C
      !>      CALL STR2ET ( TIMSTR, ET )
      !>      CALL EV2LIN ( ET, GEOPHS, ELEMS, STATE )
      !>
      !>C
      !>C     Display the results.
      !>C
      !>      WRITE(*,'(2A)')       'Epoch   : ', TIMSTR
      !>      WRITE(*,'(A,3F16.8)') 'Position:', (STATE(I), I=1,3)
      !>      WRITE(*,'(A,3F16.8)') 'Velocity:', (STATE(I), I=4,6)
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Epoch   : 2020-05-26 02:25:00
      !>        Position:  -4644.60403398  -5038.95025540   -337.27141117
      !>        Velocity:     -0.45719025      0.92884817     -7.55917355
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     [1]  F. Hoots and R. Roehrich, "Spacetrack Report #3: Models for
      !>          Propagation of the NORAD Element Sets," U.S. Air Force
      !>          Aerospace Defense Command, Colorado Springs, CO, 1980.
      !>
      !>     [2]  F. Hoots, "Spacetrack Report #6: Models for Propagation of
      !>          Space Command Element Sets,"  U.S. Air Force Aerospace
      !>          Defense Command, Colorado Springs, CO, 1986.
      !>
      !>     [3]  F. Hoots, P. Schumacher and R. Glover, "History of Analytical
      !>          Orbit Modeling in the U. S. Space Surveillance System,"
      !>          Journal of Guidance, Control, and Dynamics. 27(2):174-185,
      !>          2004.
      !>
      !>     [4]  D. Vallado, P. Crawford, R. Hujsak and T. Kelso, "Revisiting
      !>          Spacetrack Report #3," paper AIAA 2006-6753 presented at the
      !>          AIAA/AAS Astrodynamics Specialist Conference, Keystone, CO.,
      !>          August 21-24, 2006.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.1, 01-NOV-2021 (JDR) (EDW)
      !>
      !>        Declared routine as deprecated.
      !>
      !>        Corrected the description of QO and SO constants in the
      !>        detailed description of the input argument GEOPHS and the input
      !>        element names in ELEMS.
      !>
      !>        Added Spacetrack Report #3 to literature references.
      !>
      !>        Edited the header to comply with NAIF standard. Added complete
      !>        code example based on existing fragments.
      !>
      !>-    SPICELIB Version 1.1.0, 15-SEP-2014 (EDW)
      !>
      !>        Added error check to prevent infinite loop in
      !>        calculation of EST.
      !>
      !>-    SPICELIB Version 1.0.3, 02-JAN-2008 (EDW)
      !>
      !>        Corrected error in the calculation of the C4 term
      !>        identified by Curtis Haase.
      !>
      !>        Minor edit to the COEF1 declaration strictly
      !>        identifying the constant as a double.
      !>
      !>        From:
      !>
      !>           COEF1  = COEF  / PSISQ**3.5
      !>
      !>        To:
      !>
      !>           COEF1  = COEF  / PSISQ**3.5D0
      !>
      !>-    SPICELIB Version 1.0.2, 08-JUL-2004 (EDW)
      !>
      !>        Corrected error in the calculation of the C2 term.
      !>        Reordered C1, C2 calculations to avoid division
      !>        by BSTAR.
      !>
      !>-    SPICELIB Version 1.0.1, 10-MAR-1998 (EDW)
      !>
      !>        Corrected error in header describing the GEOPHS array.
      !>
      !>-    SPICELIB Version 1.0.0, 14-JAN-1994 (WLT)
      module subroutine ev2lin ( ctx, et, geophs, elems, state )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: twopi
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Epoch in seconds past ephemeris epoch J2000.
      real(wp), intent(in) :: geophs ( * )  !! Geophysical constants
      real(wp), intent(in) :: elems  ( * )  !! Two-line element data
      real(wp), intent(out) :: state  ( * )  !! Evaluated state
      integer(ip), parameter :: nmodl = 6
      integer(ip), parameter :: kj2 = 1
      integer(ip), parameter :: kj3 = 2
      integer(ip), parameter :: kj4 = 3
      integer(ip), parameter :: kke = 4
      integer(ip), parameter :: kqo = 5
      integer(ip), parameter :: kso = 6
      integer(ip), parameter :: ker = 7
      integer(ip), parameter :: kae = 8
      integer(ip), parameter :: ngeocn = kae
      integer(ip), parameter :: kndt20 = 1
      integer(ip), parameter :: kndd60 = 2
      integer(ip), parameter :: kbstar = 3
      integer(ip), parameter :: kincl = 4
      integer(ip), parameter :: knode0 = 5
      integer(ip), parameter :: kecc = 6
      integer(ip), parameter :: komega = 7
      integer(ip), parameter :: kmo = 8
      integer(ip), parameter :: kno = 9
      integer(ip), parameter :: kepoch = 10
      integer(ip), parameter :: nelems = kepoch
      integer(ip), parameter :: next = 1
      integer(ip), parameter :: prev = 2
      integer(ip), parameter :: nil = 0
      integer(ip), parameter :: mxloop = 20
      real(wp), parameter :: half = 0.5_wp
      real(wp), parameter :: f3ov8 = 3.0_wp/8.0_wp
      real(wp), parameter :: f3ov2 = 1.50_wp
      real(wp), parameter :: onethd = 1.0_wp/3.0_wp
      real(wp) :: c5
      real(wp) :: f
      real(wp) :: xmdf
      integer(ip) :: j
      real(wp) :: so
      real(wp) :: betao
      real(wp) :: cosu
      real(wp) :: cosepw
      real(wp) :: cosnok
      real(wp) :: est
      real(wp) :: j3
      real(wp) :: delo
      real(wp) :: fmod2p
      real(wp) :: qoms24
      real(wp) :: epoch
      real(wp) :: xmcof
      real(wp) :: sinnok
      real(wp) :: c1
      real(wp) :: eeta
      real(wp) :: cosik
      real(wp) :: aodp
      real(wp) :: xnode
      logical :: newgeo
      real(wp) :: del1
      real(wp) :: vz
      real(wp) :: sinu
      real(wp) :: tsince
      real(wp) :: aynl
      real(wp) :: ayn
      integer(ip) :: n
      real(wp) :: etasq
      real(wp) :: ecose
      real(wp) :: mov1m
      logical :: unrec
      real(wp) :: sinuk
      real(wp) :: t2cof
      real(wp) :: temp2
      real(wp) :: uz
      real(wp) :: axn
      real(wp) :: theta4
      real(wp) :: pinvsq
      real(wp) :: temp3
      real(wp) :: xnodcf
      real(wp) :: temp
      real(wp) :: fprime
      real(wp) :: cosuk
      real(wp) :: xnodek
      real(wp) :: templ
      real(wp) :: temp6
      real(wp) :: omgdot
      real(wp) :: betao4
      real(wp) :: esine
      real(wp) :: c2
      real(wp) :: j2
      real(wp) :: elsq
      real(wp) :: cosio
      real(wp) :: u
      real(wp) :: uk
      integer(ip) :: after
      real(wp) :: vx
      real(wp) :: bstar
      real(wp) :: xincl
      real(wp) :: sinik
      real(wp) :: delm
      real(wp) :: temp5
      real(wp) :: xlcof
      integer(ip) :: before
      real(wp) :: cos2u
      real(wp) :: betao3
      real(wp) :: omgcof
      real(wp) :: theta2
      real(wp) :: tcube
      real(wp) :: x1m5th
      real(wp) :: temp4
      real(wp) :: sinepw
      real(wp) :: perige
      real(wp) :: xndt2o
      real(wp) :: tsq
      real(wp) :: aycof
      real(wp) :: eta
      real(wp) :: temp1
      real(wp) :: uy
      real(wp) :: m
      real(wp) :: rk
      real(wp) :: c3
      real(wp) :: r
      real(wp) :: xnodeo
      real(wp) :: rdot
      real(wp) :: betao2
      real(wp) :: c4
      real(wp) :: x7thm1
      real(wp) :: a
      real(wp) :: eo
      real(wp) :: xmy
      real(wp) :: epsiln
      real(wp) :: rfdotk
      real(wp) :: capu
      real(wp) :: qo
      real(wp) :: xmo
      real(wp) :: qomso
      real(wp) :: c1sq
      real(wp) :: s4
      real(wp) :: betal
      real(wp) :: pl
      real(wp) :: xndd6o
      real(wp) :: ae4
      real(wp) :: vy
      real(wp) :: xno
      real(wp) :: ae2
      real(wp) :: ae3
      real(wp) :: tfour
      real(wp) :: xmx
      real(wp) :: e
      real(wp) :: tempe
      real(wp) :: xlt
      real(wp) :: omegao
      real(wp) :: rfdot
      real(wp) :: rdotk
      real(wp) :: q1
      real(wp) :: tsi
      real(wp) :: sin2u
      real(wp) :: xl
      real(wp) :: xnodot
      real(wp) :: delomg
      real(wp) :: epw
      real(wp) :: xll
      real(wp) :: xmdot
      real(wp) :: psisq
      integer(ip) :: i
      real(wp) :: j4
      real(wp) :: sinio
      real(wp) :: a1
      real(wp) :: sinmo
      real(wp) :: omgadf
      real(wp) :: coef
      real(wp) :: epwnxt
      integer(ip) :: count
      real(wp) :: omega
      real(wp) :: tempa
      real(wp) :: xinck
      real(wp) :: xmp
      real(wp) :: delmo
      real(wp) :: xnodp
      real(wp) :: x1mth2
      real(wp) :: xnoddf
      real(wp) :: xhdot1
      real(wp) :: x3thm1
      real(wp) :: coef1
      real(wp) :: xn
      real(wp) :: ux
      real(wp) :: q2
      real(wp) :: ao
      if ( .not. allocated ( ctx%ev2lin_state ) ) allocate ( ctx%ev2lin_state )
      associate ( ke => ctx%ev2lin_state%ke, &
                  er => ctx%ev2lin_state%er, &
                  ae => ctx%ev2lin_state%ae, &
                  ck2 => ctx%ev2lin_state%ck2, &
                  a3ovk2 => ctx%ev2lin_state%a3ovk2, &
                  ck4 => ctx%ev2lin_state%ck4, &
                  qoms2t => ctx%ev2lin_state%qoms2t, &
                  s => ctx%ev2lin_state%s, &
                  d2 => ctx%ev2lin_state%d2, &
                  d3 => ctx%ev2lin_state%d3, &
                  d4 => ctx%ev2lin_state%d4, &
                  elemnt => ctx%ev2lin_state%elemnt, &
                  fl => ctx%ev2lin_state%fl, &
                  fu => ctx%ev2lin_state%fu, &
                  lower => ctx%ev2lin_state%lower, &
                  lstgeo => ctx%ev2lin_state%lstgeo, &
                  pix2 => ctx%ev2lin_state%pix2, &
                  prelim => ctx%ev2lin_state%prelim, &
                  t3cof => ctx%ev2lin_state%t3cof, &
                  t4cof => ctx%ev2lin_state%t4cof, &
                  t5cof => ctx%ev2lin_state%t5cof, &
                  tokm => ctx%ev2lin_state%tokm, &
                  tokmps => ctx%ev2lin_state%tokmps, &
                  upper => ctx%ev2lin_state%upper, &
                  head => ctx%ev2lin_state%head, &
                  last => ctx%ev2lin_state%last, &
                  list => ctx%ev2lin_state%list, &
                  doinit => ctx%ev2lin_state%doinit, &
                  recog => ctx%ev2lin_state%recog )
      if ( doinit ) then

         doinit = .false.
         pix2   = twopi

         do i = 1, ngeocn
            lstgeo(i) = 0.0_wp
         end do

         do i = 1, nmodl
            do j = 1, nelems
               elemnt ( j, i ) = 0.0_wp
            end do
         end do

!
!        Set up our doubly linked list of most recently used
!        models.  Here's how things are supposed to be arranged:
!
!        LIST(NEXT,I)   points to the ephemeris model that was used
!                       most recently after ephemeris model I.
!        LIST(PREV,I)   points to the latest ephemeris model used
!                       that was used more recently than I.
!
!        HEAD           points to the most recently used ephemeris
!                       model.
!
         head            = 1

         list(prev,head) = nil
         list(next,1   ) = 2

         do i = 2,nmodl-1
            list(next,i) = i+1
            list(prev,i) = i-1
         end do

         list(next,nmodl) = nil
         list(prev,nmodl) = nmodl - 1

      end if
!
!     We update the geophysical parameters only if there
!     has been a change from the last time they were
!     supplied.
!
      if (       ( lstgeo( kae ) /= geophs( kae ) ) &
           .or.  ( lstgeo( ker ) /= geophs( ker ) ) &
           .or.  ( lstgeo( kj2 ) /= geophs( kj2 ) ) &
           .or.  ( lstgeo( kj3 ) /= geophs( kj3 ) ) &
           .or.  ( lstgeo( kj4 ) /= geophs( kj4 ) ) &
           .or.  ( lstgeo( kke ) /= geophs( kke ) ) &
           .or.  ( lstgeo( kqo ) /= geophs( kqo ) ) &
           .or.  ( lstgeo( kso ) /= geophs( kso ) ) ) then

         do i = 1, ngeocn
            lstgeo(i) = geophs(i)
         end do

         j2     = geophs( kj2 )
         j3     = geophs( kj3 )
         j4     = geophs( kj4 )
         ke     = geophs( kke )
         qo     = geophs( kqo )
         so     = geophs( kso )
         er     = geophs( ker )
         ae     = geophs( kae )

         ae2    =  ae    * ae
         ae3    =  ae    * ae2
         ae4    =  ae    * ae3
         ck2    =  half  * j2 * ae2
         a3ovk2 = -2.0_wp * j3 * ae  / j2
         ck4    = -f3ov8 * j4 * ae4
         qomso  = qo-so
         q1     = qomso  * ae / er
         q2     = q1     * q1
         qoms2t = q2     * q2
         s      = ae     * (one+so/er)
!
!        When we've finished up we will need to convert everything
!        back to KM and KM/SEC  the two variables below give the
!        factors we shall need to do this.
!
         tokm   = er/ae
         tokmps = tokm   / 60.0_wp

         newgeo = .true.

      else

         newgeo = .false.

      end if

!
!     Fetch all of the pieces of this model.
!
      epoch  = elems ( kepoch )
      xndt2o = elems ( kndt20 )
      xndd6o = elems ( kndd60 )
      bstar  = elems ( kbstar )
      xincl  = elems ( kincl  )
      xnodeo = elems ( knode0 )
      eo     = elems ( kecc   )
      omegao = elems ( komega )
      xmo    = elems ( kmo    )
      xno    = elems ( kno    )

!
!     See if this model is already buffered, start at the first
!     model in the list (the most recently used model).
!

      unrec = .true.
      n     =  head

      do while (  n /= nil .and. unrec )

!
!        The actual order of the elements is such that we can
!        usually tell that a stored model is different from
!        the one under consideration by looking at the
!        end of the list first.  Hence we start with I = NELEMS
!        and decrement I until we have looked at everything
!        or found a mismatch.
!
         recog = .true.
         i     =  nelems

         do while  ( recog .and. i           > 0      )
            recog  = recog .and. elemnt(i,n) == elems(i)
            i      = i - 1
         end do

         unrec = .not. recog

         if ( unrec ) then
            last = n
            n    = list(next,n)
         end if

      end do

      if ( n == nil ) then
         n = last
      end if
!
!     Either N points to a recognized item or it points to the
!     tail of the list where the least recently used items is
!     located.  In either case N must be made the head of the
!     list.  (If it is already the head of the list we don't
!     have to bother with anything.)
!
      if ( n /= head ) then

!
!        Find the items that come before and after N and
!        link them together.
!
         before                = list ( prev, n )
         after                 = list ( next, n )

         list ( next, before ) = after

         if ( after /= nil ) then
            list ( prev, after  ) = before
         end if
!
!        Now the guy that will come after N is the current
!        head of the list.  N will have no predecessor.
!
         list ( next, n      ) = head
         list ( prev, n      ) = nil
!
!        The predecessor the current head of the list becomes N
!
         list ( prev, head   ) = n
!
!        and finally, N becomes the head of the list.
!
         head = n

      end if

      if ( recog .and. .not. newgeo ) then
!
!        We can just look up the intermediate values from
!        computations performed on a previous call to this
!        routine.
!
         aodp   = prelim (  1, n )
         aycof  = prelim (  2, n )
         c1     = prelim (  3, n )
         c4     = prelim (  4, n )
         c5     = prelim (  5, n )
         cosio  = prelim (  6, n )
         d2     = prelim (  7, n )
         d3     = prelim (  8, n )
         d4     = prelim (  9, n )
         delmo  = prelim ( 10, n )
         eta    = prelim ( 11, n )
         omgcof = prelim ( 12, n )
         omgdot = prelim ( 13, n )
         perige = prelim ( 14, n )
         sinio  = prelim ( 15, n )
         sinmo  = prelim ( 16, n )
         t2cof  = prelim ( 17, n )
         t3cof  = prelim ( 18, n )
         t4cof  = prelim ( 19, n )
         t5cof  = prelim ( 20, n )
         x1mth2 = prelim ( 21, n )
         x3thm1 = prelim ( 22, n )
         x7thm1 = prelim ( 23, n )
         xlcof  = prelim ( 24, n )
         xmcof  = prelim ( 25, n )
         xmdot  = prelim ( 26, n )
         xnodcf = prelim ( 27, n )
         xnodot = prelim ( 28, n )
         xnodp  = prelim ( 29, n )

      else

!
!        Compute all of the intermediate items needed.
!        First, the inclination dependent constants.
!
         cosio  = dcos ( xincl )
         sinio  = dsin ( xincl )
         theta2 = cosio  * cosio

         theta4 = theta2 * theta2
         x3thm1 = 3.0_wp  * theta2  -  one
         x7thm1 = 7.0_wp  * theta2  -  one

         x1mth2 = one    - theta2
         x1m5th = one    - 5.0_wp * theta2
!
!        Eccentricity dependent constants
!
         betao  = dsqrt(one - eo*eo)
         betao2 = one       - eo*eo
         betao3 = betao  * betao2
         betao4 = betao2 * betao2
!
!        Semi-major axis and ascending node related constants.
!
         a1     = (ke/xno)**tothrd
         del1   = 1.5_wp * ck2 * x3thm1 / ( a1*a1*betao3 )

         ao     = a1    * ( one &
                           - del1*( onethd &
                                 + del1*( one + del1*134.0_wp/81.0_wp)))

         delo   = 1.5_wp * ck2 * x3thm1 / (ao*ao*betao3)

         xnodp  = xno / (one + delo)
         aodp   = ao  / (one - delo)

         s4     = s
         qoms24 = qoms2t
         perige = er * ( aodp*(one-eo) - ae )

!
!        For perigee below 156 km, the values of S and QOMS2T are
!        altered.
!
         if ( perige < 156.0_wp ) then
            s4 = perige - 78.0_wp

            if ( perige <= 98.0_wp ) then
               s4 = 20.0_wp
            end if

            qoms24 = ( (120.0_wp-s4)*ae / er )**4
            s4     = ae + ( s4/er )
         end if
!
!        The next block is simply a pretty print of the code in
!        sgp4 from label number 10 through the label 90.
!
         pinvsq = one  / (aodp * aodp * betao4)
         tsi    = one  / (aodp - s4           )

         eta    = aodp   *  eo  * tsi
         etasq  = eta    *  eta
         eeta   = eo     *  eta
         coef   = qoms24 *  tsi**4

         psisq  = dabs(one - etasq)

         coef1  = coef  / psisq**3.5_wp
         c2     = coef1 &
                  * xnodp &
                  * (   aodp   * (  one &
                                 + f3ov2*etasq &
                                 + eeta *( 4.0_wp +       etasq) ) &
                     + 0.75_wp * ck2 &
                              * (tsi/psisq) &
                              * x3thm1 &
                              * (  8.0_wp &
                                 + etasq*(24.0_wp + 3.0_wp*etasq) )   )

         c1     =  c2 * bstar

         c3     =  coef * tsi * a3ovk2 * xnodp *ae * sinio / eo

         c4    = 2.0_wp * xnodp * coef1 * aodp &
               * betao2 &
               * (  eta   * ( 2.0_wp + 0.50_wp*etasq  ) &
                  + eo    * ( half  + 2.0_wp*etasq  ) &
                  - 2.0_wp * ( ck2*tsi/(aodp*psisq) ) &
                           * ( -3.00_wp * x3thm1 &
                                       * ( one &
                                         - eeta * 2.0_wp &
                                         + etasq*(f3ov2 - half*eeta)) &
                              + 0.75_wp * dcos ( 2.0_wp * omegao ) &
                                       * x1mth2 &
                                       * (  etasq * 2.0_wp &
                                          - eeta  * (one+etasq))))

         c5    = 2.0_wp*coef1*aodp*betao2 &
                        *(one + 2.75_wp*(etasq+eeta) + eeta*etasq )

         temp1  = 3.0_wp  * ck2 * pinvsq * xnodp
         temp2  = temp1  * ck2 * pinvsq
         temp3  = 1.25_wp * ck4 * pinvsq * pinvsq * xnodp

         xmdot  =  xnodp &
                  +  half     * temp1 * betao * x3thm1 &
                  +  0.0625_wp * temp2 * betao * (  13.0_wp &
                                             -  78.0_wp*theta2 &
                                             + 137.0_wp*theta4 )

         omgdot = -half      * temp1 * x1m5th &
                  + 0.0625_wp * temp2 * (   7.0_wp &
                                       - 114.0_wp*theta2 &
                                       + 395.0_wp*theta4 ) &
                  +            temp3 * (   3.0_wp &
                                       -  36.0_wp*theta2 &
                                       +  49.0_wp*theta4 )

         xhdot1 = -temp1*cosio

         xnodot = xhdot1 &
                  + cosio * (  half  * temp2*(4.0_wp - 19.0_wp*theta2) &
                           + 2.0_wp * temp3*(3.0_wp -  7.0_wp*theta2) )

         omgcof =  bstar   * c3     * dcos(omegao)
         xmcof  = -bstar   * tothrd * coef  * ae / eeta
         xnodcf =  3.5_wp   * betao2 * xhdot1* c1
         t2cof  =  f3ov2   * c1
         aycof  =  0.250_wp * a3ovk2 * sinio
         xlcof  =  half    * aycof  * (3.0_wp + 5.0_wp*cosio) &
                                    / (one   +       cosio)

         delmo  =  (one    + eta*cos(xmo) )**3
         sinmo  =  sin(xmo)
!
!        For perigee less than 220 kilometers, the ISIMP flag is set
!        and the equations are truncated to linear variation in SQRT
!        A and quadratic variation in mean anomaly.  Also, the C3
!        term, the Delta OMEGA term, and the Delta M term are
!        dropped.  (Note: Normally we would just use
!
         if ( perige >= 220.0_wp ) then

            c1sq  = c1*c1
            d2    = 4.0_wp * tsi   * c1sq   * aodp
            temp  = d2    * tsi   * c1     * onethd
            d3    = temp  * (s4   + 17.0_wp * aodp )
            d4    = temp  * tsi   * c1     * aodp &
                          * half  *(221.0_wp* aodp + 31.0_wp*s4)

            t3cof = d2    + 2.0_wp * c1sq

            t4cof = 0.25_wp * ( 3.0_wp*d3 + c1*(  12.0_wp*d2 &
                                              + 10.0_wp*c1sq) )

            t5cof = 0.20_wp * (3.0_wp*d4 + 12.0_wp*c1*d3 &
                                       +  6.0_wp*d2*d2 &
                                       + 15.0_wp*c1sq*(  2.0_wp*d2 &
                                                      + c1sq) )
         end if
!
!        Now store the intermediate computations so that if we
!        should hit this model again we can just look up the needed
!        results from the above computations.
!
         prelim (  1, n ) = aodp
         prelim (  2, n ) = aycof
         prelim (  3, n ) = c1
         prelim (  4, n ) = c4
         prelim (  5, n ) = c5
         prelim (  6, n ) = cosio
         prelim (  7, n ) = d2
         prelim (  8, n ) = d3
         prelim (  9, n ) = d4
         prelim ( 10, n ) = delmo
         prelim ( 11, n ) = eta
         prelim ( 12, n ) = omgcof
         prelim ( 13, n ) = omgdot
         prelim ( 14, n ) = perige
         prelim ( 15, n ) = sinio
         prelim ( 16, n ) = sinmo
         prelim ( 17, n ) = t2cof
         prelim ( 18, n ) = t3cof
         prelim ( 19, n ) = t4cof
         prelim ( 20, n ) = t5cof
         prelim ( 21, n ) = x1mth2
         prelim ( 22, n ) = x3thm1
         prelim ( 23, n ) = x7thm1
         prelim ( 24, n ) = xlcof
         prelim ( 25, n ) = xmcof
         prelim ( 26, n ) = xmdot
         prelim ( 27, n ) = xnodcf
         prelim ( 28, n ) = xnodot
         prelim ( 29, n ) = xnodp
!
!        Finally, move these elements in the storage area
!        for checking the next time through.
!
         do i = 1, nelems
            elemnt(i,n) = elems(i)
         end do

      end if
!
!     Now that all of the introductions are out of the way
!     we can get down to business.
!
!     Compute the time since the epoch for this model.
!
      tsince = et - epoch
!
!     and convert it to minutes
!
      tsince = tsince / 60.0_wp

      xmdf   = xmo      +   xmdot  * tsince
      omgadf = omegao   +   omgdot * tsince
      xnoddf = xnodeo   +   xnodot * tsince
      omega  = omgadf
      xmp    = xmdf

      tsq    = tsince  *  tsince
      xnode  = xnoddf  +  xnodcf * tsq
      tempa  = 1.0_wp   -  c1     * tsince
      tempe  = bstar   *  c4     * tsince
      templ  = t2cof   *  tsq

      if(perige > 220.0_wp ) then

         tcube  = tsq    * tsince
         tfour  = tcube  * tsince

         delomg = omgcof * tsince
         delm   = xmcof* ( (1.0_wp + eta*cos(xmdf))**3  -  delmo )
         temp   = delomg + delm
         xmp    = xmdf   + temp
         omega  = omgadf - temp

         tempa  = tempa - d2*tsq &
                        - d3*tcube &
                        - d4*tfour

         tempe  = tempe  +  bstar * c5 * (sin(xmp) - sinmo)
         templ  = templ  +  tcube * t3cof &
                         +  tfour *(t4cof + tsince*t5cof)
      end if

      a    =  aodp * tempa**2
      xl   =  xmp  + omega  +  xnode  +  xnodp*templ

      e    =  eo   - tempe

!
!     The parameter BETA used to be needed, but it's only use
!     was in the computation of TEMP below where it got squared
!     so we'll remove it from the list of things to compute.
!
!     BETA =  DSQRT( 1.0D0 - E*E )
!

      xn   =  ke/a**1.5_wp

!
!     Long period periodics
!
      temp = 1.0_wp/(a*(1.0_wp - e*e) )
      aynl = temp * aycof
      ayn  = e    * sin(omega)   +    aynl
      axn  = e    * cos(omega)

      xll  = temp * xlcof * axn
      xlt  = xl   + xll

!
!     Solve Kepler's equation.
!
!     We are going to solve for the roots of this equation by
!     using a mixture of Newton's method and the prescription for
!     root finding outlined in the SPICE routine UNITIM.
!
!     We are going to solve the equation
!
!           U = EPW - AXN * SIN(EPW)  +  AYN * COS(EPW)
!
!     Where
!
!        AYN  = E    * SIN(OMEGA)   +    AYNL
!        AXN  = E    * COS(OMEGA)
!
!     And
!
!        AYNL =  -0.50D0  * SINIO * AE * J3   / (J2*A*(1.0D0 - E*E))
!
!     Since this is a low earth orbiter (period less than 225 minutes)
!     The maximum value E can take (without having the orbiter
!     plowing fields) is approximately 0.47 and AYNL will not be
!     more than about .01.  ( Typically E will be much smaller
!     on the order of about .1 )  Thus we can initially
!     view the problem of solving the equation for EPW as a
!     function of the form
!
!     U = EPW + F ( EPW )                                   (1)
!
!     Where F( EPW ) = -AXN*SIN(EPW) + AYN*COS(EPW)
!
!     Note that | F'(EPW) | < M =  DSQRT( AXN**2 + AYN**2 ) < 0.48
!
!     From the above discussion it is evident that F is a contraction
!     mapping.  So that we can employ the same techniques as were
!     used in the routine UNITIM to get our first approximations of
!     the root.  Once we have some good first approximations, we
!     will speed up the root finding by using Newton's method for
!     finding a zero of a function.  The function we will work on
!     is
!
!        f  (x) = x - U - AXN*SIN(x) + AYN*COS(x)         (2)
!
!     By applying Newton's method we will go from linear to
!     quadratic convergence.
!
!     We will keep track of our error bounds along the way so
!     that we will know how many iterations to perform in each
!     phase of the root extraction.
!
!     few steps using bisection.
!
!     For the benefit of those interested
!     here's the basics of what we'll do.
!
!        Whichever EPW satisfies equation (1) will be
!        unique. The uniqueness of the solution is ensured because the
!        expression on the right-hand side of the equation is
!        monotone increasing in EPW.
!
!        Let's suppose that EPW is the solution, then the following
!        is true.
!
!           EPW = U - F(EPW)
!
!        but we can also replace the EPW on the right hand side of the
!        equation by U - F(EPW).  Thus
!
!           EPW = U - F( U - F(EPW))
!
!               = U - F( U - F( U - F(EPW)))
!
!               = U - F( U - F( U - F( U - F(EPW))))
!
!               = U - F( U - F( U - F( U - F( U - F(EPW)))))
!               .
!               .
!               .
!               = U - F( U - F( U - F( U - F( U - F(U - ... )))
!
!        and so on, for as long as we have patience to perform the
!        substitutions.
!
!        The point of doing this recursive substitution is that we
!        hope to move EPW to an insignificant part of the computation.
!        This would seem to have a reasonable chance of success since
!        F is a bounded and has a small derivative.
!
!        Following this idea, we will attempt to solve for EPW using
!        the recursive method outlined below.
!
!     We will make our first guess at EPW, call it EPW_0.
!
!        EPW_0 = U
!
!     Our next guess, EPW_1, is given by:
!
!        EPW_1 = U - F(EPW_0)
!
!     And so on:
!
!        EPW_2 = U - F(EPW_1)        [ = U - F(U - F(U))          ]
!        EPW_3 = U - F(EPW_2)        [ = U - F(U - F(U - F(U)))   ]
!           .
!           .
!           .
!        EPW_n = U - F(EPW_(n-1))    [ = U - F(U - F(U - F(U...)))]
!
!        The questions to ask at this point are:
!
!           1) Do the EPW_i's converge?
!           2) If they converge, do they converge to EPW?
!           3) If they converge to EPW, how fast do they get there?
!
!        1) The sequence of approximations converges.
!
!           | EPW_n - EPW_(n-1) | =  [ U - F( EPW_(n-1) ) ]
!                                 -  [ U - F( EPW_(n-2) ) ]
!
!                                 =  [ F( EPW_(n-2) ) - F( EPW_(n-1)) ]
!
!     The function F has an important property. The absolute
!     value of its derivative is always less than M.
!     This means that for any pair of real numbers s,t
!
!        | F(t) - F(s) |  < M*| t - s |.
!
!     From this observation, we can see that
!
!        | EPW_n - EPW_(n-1) | < M*| EPW_(n-1) - EPW_(n-2) |
!
!     With this fact available, we could (with a bit more work)
!     conclude that the sequence of EPW_i's converges and that
!     it converges at a rate that is at least as fast as the
!     sequence M, M**2, M**3.  In fact the difference
!        |EPW - EPW_N| < M/(1-M) * | EPW_N - EPW_(N-1) |
!
!                       < M/(1-M) * M**N | EPW_1 - EPW_0 |
!
!     2) If we let EPW be the limit of the EPW_i's then it follows
!        that
!
!               EPW = U - F(EPW).
!
!     or that
!
!               U = EPW + F(EPW).
!
!     We will use this technique to get an approximation that
!     is within a tolerance of EPW and then switch to
!     a Newton's method. (We'll compute the tolerance using
!     the value of M given above).
!
!     For the Newton's method portion of the problem, recall
!     from Taylor's formula that:
!
!        f(x) = f(x_0) + f'(x_0)(x-x_0) +  f''(c)/2 (x-x_0)**2
!
!     for some c between x and x_0
!
!     If x happens to be a zero of f then we can rearrange the
!     terms above to get
!
!                       f(x_0)       f''(c)
!           x = x_0 -   -------  +  -------- ( x - x_0)**2
!                       f'(x_0)      f'(x_0)
!
!     Thus the error in the Newton approximation
!
!                       f(x_0)
!           x = x_0  -  -------
!                       f'(x_0)
!
!     is
!
!                     f''(c)
!                    -------- ( x - x_0)**2
!                     f'(x_0)
!
!     Thus if we can bound f'' and pick a good first
!     choice for x_0 (using the first method outlined
!     above we can get quadratic convergence.)
!
!     In our case we have
!
!        f  (x) = x - U - AXN*SIN(x) + AYN*COS(x)
!        f' (x) = 1     - AXN*COS(x) - AYN*SIN(x)
!        f''(x) =         AXN*SIN(x) - AYN*COS(x)
!
!     So that:
!
!        f' (x) >  1 - M
!
!        f''(x) <  M
!
!     Thus the error in the Newton's approximation is
!     at most
!
!        M/(1-M) * ( x - x_0 )**2
!
!     Thus as long as our original estimate (determined using
!     the contraction method) gets within a reasonable tolerance
!     of x, we can use Newton's method to achieve faster
!     convergence.
!

      m      = dsqrt ( axn*axn + ayn*ayn )
      mov1m  = dabs  ( m / ( 1.0_wp - m ) )

      fmod2p = dmod(xlt-xnode,pix2)

      if ( fmod2p < 0 ) then
         fmod2p = fmod2p + pix2
      end if

      capu  = fmod2p
      epw   = capu
      est   = 1.0_wp

      count = 0

      do while ( est > 0.125_wp )

         count = count + 1

         if ( count > mxloop ) then
            call ctx%setmsg ( 'EST iteration count of #1 exceeded at ' &
            //            'time ET #2. This error may indicate a ' &
            //            'bad TLE set.'                       )
            call ctx%errint ( '#1', mxloop                         )
            call ctx%errdp  ( '#2', et                             )
            call ctx%sigerr ( 'SPICE(ITERATIONEXCEEDED)'           )
            return
         end if

         epwnxt = capu - axn*sin(epw) + ayn*cos(epw)
         est    = mov1m * dabs ( epwnxt - epw )
         epw    = epwnxt

      end do

!
!     We need to be able to add something to EPW and not
!     get EPW (but not too much).
!
      epsiln = est

      if ( epsiln + epw /= epw ) then

!
!        Now we switch over to Newton's method.  Note that
!        since our error estimate is less than 1/8, six iterations
!        of Newton's method should get us to within 1/2**96 of
!        the correct answer (If there were no round off to contend
!        with).
!
         do i = 1, 5

            sinepw = sin(epw)
            cosepw = cos(epw)

            f      =  epw - capu - axn * sinepw + ayn * cosepw
            fprime =  1.0_wp      - axn * cosepw -  ayn * sinepw

            epwnxt = epw -  f/fprime
!
!           Our new error estimate comes from the discussion
!           of convergence of Newton's method.
!
            epw    = epwnxt

            if ( epw + est /= epw ) then
               epsiln = est
               est    = mov1m * est * est
            end if

         end do

      end if
!
!     Finally, we use bisection to avoid the problems of
!     round-off that may be present in Newton's method.  Since
!     we've gotten quite close to the answer (theoretically
!     anyway)  we won't have to perform many bisection passes.
!
!     First we must bracket the root.  Note that we will
!     increase EPSILN so that we don't spend much time
!     determining the bracketing interval.  Also if the first
!     addition of EPSILN to EPW doesn't modify it, were set up
!     to just quit.  This happens only if F is sufficiently
!     close to zero that it can't alter EPW by adding it to
!     or subtracting it from EPW.
!

      sinepw = sin(epw)
      cosepw = cos(epw)

      f      =  epw - capu - axn * sinepw + ayn * cosepw
      epsiln =  max ( dabs(f), epsiln )

      if ( f == 0 ) then

         lower = epw
         upper = epw

      else if ( f > 0 ) then

         fu    = f
         upper = epw
         lower = epw - epsiln
         epw   = lower

         do while ( f > 0 .and. lower /= upper )
            epw    = epw - epsiln
            f      = epw - capu - axn * sin(epw) + ayn * cos(epw)
            epsiln = epsiln * 2.0_wp
         end do

         lower = epw
         fl    = f

         if ( f == 0 ) then
            upper = lower
         end if

      else if ( f < 0 ) then

         fl    = f
         lower = epw
         upper = epw + epsiln
         epw   = upper

         do while ( f < 0 .and. lower /= upper )
            epw    = epw + epsiln
            f      = epw - capu - axn * sin(epw) + ayn * cos(epw)
            epsiln = epsiln * 2.0_wp
         end do

         upper = epw
         fu    = f

         if ( f == 0 ) then
            lower = epw
         end if

      end if

!
!     Finally, bisect until we can do no more.
!
      count = 0

      do while ( upper > lower .and. count < mxloop )
         count = count + 1
         epw   = max(min(lower, upper), min(max(lower, upper), 0.5_wp * ( upper + lower )))
!
!        EPW eventually will not be different from one of the
!        two bracketing values.  If this is the time, we need
!        to decide on a value for EPW.  That's done below.
!
         if   (      ( epw == upper ) &
                .or. ( epw == lower ) ) then

            if ( -fl < fu ) then
               epw   = lower
               upper = lower
            else
               epw   = upper
               lower = upper
            end if

         else

            f   = epw - capu - axn * sin(epw) + ayn * cos(epw)

            if ( f > 0 ) then
               upper = epw
               fu    = f
            else if ( f < 0 ) then
               lower = epw
               fl    = f
            else
               lower = epw
               upper = epw
            end if

         end if

      end do

!
!     Short period preliminary quantities
!

      sinepw = sin(epw)
      cosepw = cos(epw)

      temp3  = axn * sinepw
      temp4  = ayn * cosepw

      temp5  = axn * cosepw
      temp6  = ayn * sinepw

      ecose = temp5   + temp6
      esine = temp3   - temp4
      elsq  = axn*axn + ayn*ayn
      temp  = 1.0_wp   - elsq
      pl    = a       * temp
      r     = a       * (1.0_wp - ecose)

      temp1 = 1.0_wp   /  r
      rdot  = ke      * temp1 * sqrt(a)  * esine
      rfdot = ke      * temp1 * sqrt(pl)
      temp2 = a       * temp1
      betal = dsqrt   ( temp )
      temp3 = 1.0_wp / (1.0_wp + betal)

      cosu  = temp2 * (cosepw  -  axn  +  ayn * esine * temp3)
      sinu  = temp2 * (sinepw  -  ayn  -  axn * esine * temp3)
!
!     Compute the angle from the x-axis of the point ( COSU, SINU )
!
      if (      sinu /= 0.0_wp &
           .or. cosu /= 0.0_wp ) then

         u     = datan2 (sinu,cosu)

         if ( u < 0 ) then
            u = u + pix2
         end if

      else

         u = 0.0_wp

      end if

      sin2u = 2.0_wp * sinu * cosu
      cos2u = 2.0_wp * cosu * cosu  -  1.0_wp
      temp  = 1.0_wp / pl
      temp1 = ck2   * temp
      temp2 = temp1 * temp

!
!     Update for short periodics
!
      rk     = r * ( 1.0_wp   -  1.5_wp * temp2 * betal * x3thm1) &
             +     0.50_wp * temp1 * x1mth2 * cos2u
      uk     = u - 0.25_wp * temp2 * x7thm1 * sin2u

      xnodek = xnode + 1.50_wp * temp2 * cosio  * sin2u
      xinck  = xincl + 1.50_wp * temp2 * cosio  * cos2u * sinio
      rdotk  = rdot  - xn     * temp1 * x1mth2 * sin2u
      rfdotk = rfdot + xn     * temp1 *(x1mth2 * cos2u + 1.5_wp*x3thm1)
!
!     Orientation vectors
!
      sinuk  = sin(uk)
      cosuk  = cos(uk)

      sinik  = sin(xinck)
      cosik  = cos(xinck)

      sinnok = sin(xnodek)
      cosnok = cos(xnodek)

      xmx    = -sinnok * cosik
      xmy    =  cosnok * cosik

      ux     =  xmx    * sinuk   +   cosnok * cosuk
      uy     =  xmy    * sinuk   +   sinnok * cosuk
      uz     =  sinik  * sinuk
      vx     =  xmx    * cosuk   -   cosnok * sinuk
      vy     =  xmy    * cosuk   -   sinnok * sinuk
      vz     =  sinik  * cosuk
!
!     Position and velocity
!
      state(1) = tokm    *   rk    * ux
      state(2) = tokm    *   rk    * uy
      state(3) = tokm    *   rk    * uz
      state(4) = tokmps  * ( rdotk * ux     +   rfdotk * vx )
      state(5) = tokmps  * ( rdotk * uy     +   rfdotk * vy )
      state(6) = tokmps  * ( rdotk * uz     +   rfdotk * vz )

      return
      end associate
      end subroutine ev2lin

      !> Evaluate NORAD two-line element data for earth orbiting
      !> spacecraft. This evaluator uses algorithms as described
      !> in Vallado 2006 [4].
      !>
      !> This routine supersedes SPICELIB routines EV2LIN and DPSPCE.
      !>
      !>## Detailed Input
      !>
      !>     ET       is the epoch in seconds past ephemeris epoch J2000
      !>              at which a state should be produced from the
      !>              input elements.
      !>
      !>     GEOPHS   is a collection of 8 geophysical constants needed
      !>              for computing a state. The order of these
      !>              constants must be:
      !>
      !>                 GEOPHS(1) = J2 gravitational harmonic for Earth.
      !>                 GEOPHS(2) = J3 gravitational harmonic for Earth.
      !>                 GEOPHS(3) = J4 gravitational harmonic for Earth.
      !>
      !>              These first three constants are dimensionless.
      !>
      !>                 GEOPHS(4) = KE: Square root of the GM for Earth where
      !>                             GM is expressed in Earth radii cubed per
      !>                             minutes squared.
      !>
      !>                 GEOPHS(5) = QO: High altitude bound for atmospheric
      !>                             model in km.
      !>
      !>                 GEOPHS(6) = SO: Low altitude bound for atmospheric
      !>                             model in km.
      !>
      !>                 GEOPHS(7) = RE: Equatorial radius of the earth in km.
      !>
      !>                 GEOPHS(8) = AE: Distance units/earth radius
      !>                             (normally 1)
      !>
      !>              Below are currently recommended values for these
      !>              items:
      !>
      !>                 J2 =    1.082616D-3
      !>                 J3 =   -2.53881D-6
      !>                 J4 =   -1.65597D-6
      !>
      !>              The next item is the square root of GM for the Earth
      !>              given in units of earth-radii**1.5/Minute
      !>
      !>                 KE =    7.43669161D-2
      !>
      !>              The next two items define the top and bottom of the
      !>              atmospheric drag model used by the type 10 ephemeris
      !>              type. Don't adjust these unless you understand the full
      !>              implications of such changes.
      !>
      !>                 QO =  120.0D0
      !>                 SO =   78.0D0
      !>
      !>              The ER value is the equatorial radius in km of the Earth
      !>              as used by NORAD.
      !>
      !>                 ER = 6378.135D0
      !>
      !>              The value of AE is the number of distance units per
      !>              Earth radii used by the NORAD state propagation
      !>              software. The value should be 1 unless you've got a very
      !>              good understanding of the NORAD routine SGP4 and the
      !>              affect of changing this value.
      !>
      !>                 AE =    1.0D0
      !>
      !>     ELEMS    is an array containing two-line element data
      !>              as prescribed below. The elements NDD6O and BSTAR
      !>              must already be scaled by the proper exponent stored
      !>              in the two line elements set. Moreover, the
      !>              various items must be converted to the units shown
      !>              here.
      !>
      !>                 ELEMS (  1 ) = NDT20 in radians/minute**2
      !>                 ELEMS (  2 ) = NDD60 in radians/minute**3
      !>                 ELEMS (  3 ) = BSTAR
      !>                 ELEMS (  4 ) = INCL  in radians
      !>                 ELEMS (  5 ) = NODE0 in radians
      !>                 ELEMS (  6 ) = ECC
      !>                 ELEMS (  7 ) = OMEGA in radians
      !>                 ELEMS (  8 ) = M0    in radians
      !>                 ELEMS (  9 ) = N0    in radians/minute
      !>                 ELEMS ( 10 ) = EPOCH of the elements in seconds
      !>                                past ephemeris epoch J2000.
      !>
      !>## Detailed Output
      !>
      !>     STATE    is the state produced by evaluating the input elements
      !>              at the input epoch ET. Units are km and km/sec relative
      !>              to the TEME reference frame.
      !>
      !>## Parameters
      !>
      !>     AFSPC    set the SGP4 propagator to use the original
      !>              Space Track #3 GST algorithm as described in Hoots [1];
      !>              value defined in zzsgp4.inc.
      !>
      !>## Exceptions
      !>
      !>     1)  No checks are made on the reasonableness of the inputs.
      !>
      !>     2)  If a problem occurs when evaluating the elements, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine evaluates any NORAD two-line element sets for
      !>     near-earth orbiting satellites using the algorithms described in
      !>     Vallado 2006 [4].
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Suppose you have a set of two-line elements for the LUME 1
      !>        cubesat. This example shows how you can use this routine
      !>        together with the routine GETELM to propagate a state to an
      !>        epoch of interest.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: evsgp4_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name           Contents
      !>              ---------           ------------------------------------
      !>              naif0012.tls        Leapseconds
      !>              geophysical.ker     geophysical constants for evaluation
      !>                                  of two-line element sets.
      !>
      !>           The geophysical.ker is a PCK file that is provided with the
      !>           SPICE toolkit under the "/data" directory.
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'naif0012.tls',
      !>                                  'geophysical.ker'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EVSGP4_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local parameters.
      !>C
      !>      CHARACTER*(*)         TIMSTR
      !>      PARAMETER           ( TIMSTR = '2020-05-26 02:25:00' )
      !>
      !>      INTEGER               PNAMLN
      !>      PARAMETER           ( PNAMLN = 2  )
      !>
      !>      INTEGER               TLELLN
      !>      PARAMETER           ( TLELLN = 69 )
      !>
      !>C
      !>C     The LUME-1 cubesat is an Earth orbiting object; set
      !>C     the center ID to the Earth ID.
      !>C
      !>      INTEGER               CENTER
      !>      PARAMETER           ( CENTER  = 399     )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      CHARACTER*(PNAMLN)    NOADPN ( 8  )
      !>      CHARACTER*(TLELLN)    TLE    ( 2  )
      !>
      !>      DOUBLE PRECISION      ELEMS  ( 10 )
      !>      DOUBLE PRECISION      EPOCH
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      GEOPHS ( 8  )
      !>      DOUBLE PRECISION      STATE  ( 6  )
      !>
      !>      INTEGER               I
      !>      INTEGER               N
      !>
      !>C
      !>C     These are the variables that will hold the constants
      !>C     required by EVSGP4. These constants are available from
      !>C     the loaded PCK file, which provides the actual values
      !>C     and units as used by NORAD propagation model.
      !>C
      !>C     Constant   Meaning
      !>C     --------   ------------------------------------------
      !>C     J2         J2 gravitational harmonic for Earth.
      !>C     J3         J3 gravitational harmonic for Earth.
      !>C     J4         J4 gravitational harmonic for Earth.
      !>C     KE         Square root of the GM for Earth.
      !>C     QO         High altitude bound for atmospheric model.
      !>C     SO         Low altitude bound for atmospheric model.
      !>C     ER         Equatorial radius of the Earth.
      !>C     AE         Distance units/earth radius.
      !>C
      !>      DATA          NOADPN  /  'J2', 'J3', 'J4', 'KE',
      !>     .                         'QO', 'SO', 'ER', 'AE'  /
      !>
      !>C
      !>C     Define the Two-Line Element set for LUME-1.
      !>C
      !>      TLE(1)  = '1 43908U 18111AJ  20146.60805006  .00000806'
      !>     .      //                   '  00000-0  34965-4 0  9999'
      !>      TLE(2)  = '2 43908  97.2676  47.2136 0020001 220.6050 '
      !>     .      //                   '139.3698 15.24999521 78544'
      !>
      !>C
      !>C     Load the MK file that includes the PCK file that provides
      !>C     the geophysical constants required for the evaluation of
      !>C     the two-line elements sets and the LSK, as it is required
      !>C     by GETELM to perform time conversions.
      !>C
      !>      CALL FURNSH ( 'evsgp4_ex1.tm' )
      !>
      !>C
      !>C     Retrieve the data from the kernel, and place it on
      !>C     the GEOPHS array.
      !>C
      !>      DO I = 1, 8
      !>         CALL BODVCD ( CENTER, NOADPN(I), 1, N, GEOPHS(I) )
      !>      END DO
      !>
      !>C
      !>C     Convert the Two Line Elements lines to the element sets.
      !>C     Set the lower bound for the years to be the beginning
      !>C     of the space age.
      !>C
      !>      CALL GETELM ( 1957, TLE, EPOCH, ELEMS )
      !>
      !>C
      !>C     Now propagate the state using EVSGP4 to the epoch of
      !>C     interest.
      !>C
      !>      CALL STR2ET ( TIMSTR, ET )
      !>      CALL EVSGP4 ( ET, GEOPHS, ELEMS, STATE )
      !>
      !>C
      !>C     Display the results.
      !>C
      !>      WRITE(*,'(2A)')       'Epoch   : ', TIMSTR
      !>      WRITE(*,'(A,3F16.8)') 'Position:', (STATE(I), I=1,3)
      !>      WRITE(*,'(A,3F16.8)') 'Velocity:', (STATE(I), I=4,6)
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a PC/Linux/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Epoch   : 2020-05-26 02:25:00
      !>        Position:  -4644.60403398  -5038.95025539   -337.27141116
      !>        Velocity:     -0.45719025      0.92884817     -7.55917355
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     [1]  F. Hoots and R. Roehrich, "Spacetrack Report #3: Models for
      !>          Propagation of the NORAD Element Sets," U.S. Air Force
      !>          Aerospace Defense Command, Colorado Springs, CO, 1980.
      !>
      !>     [2]  F. Hoots, "Spacetrack Report #6: Models for Propagation of
      !>          Space Command Element Sets,"  U.S. Air Force Aerospace
      !>          Defense Command, Colorado Springs, CO, 1986.
      !>
      !>     [3]  F. Hoots, P. Schumacher and R. Glover, "History of Analytical
      !>          Orbit Modeling in the U. S. Space Surveillance System,"
      !>          Journal of Guidance, Control, and Dynamics. 27(2):174-185,
      !>          2004.
      !>
      !>     [4]  D. Vallado, P. Crawford, R. Hujsak and T. Kelso, "Revisiting
      !>          Spacetrack Report #3," paper AIAA 2006-6753 presented at the
      !>          AIAA/AAS Astrodynamics Specialist Conference, Keystone, CO.,
      !>          August 21-24, 2006.
      !>
      !>## Author and Institution
      !>
      !>     M. Costa Sitja     (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 02-NOV-2021 (EDW) (MCS)
      module subroutine evsgp4 ( ctx, et, geophs, elems, state )
      use pepper_kinds, only: wp
      use pepper_inc_zzsgp4
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Epoch in seconds past ephemeris epoch J2000.
      real(wp), intent(in) :: geophs (  8 )  !! Geophysical constants
      real(wp), intent(in) :: elems  ( 10 )  !! Two-line element data
      real(wp), intent(out) :: state  (  6 )  !! Evaluated state

      real(wp) :: t1

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Evaluate TLE.
!

!
!     Initialize.
!
      call xxsgp4i ( ctx, geophs, elems, afspc )

      if ( ctx%failed() ) return

!
!     Calculate time from epoch in minutes.
!
      t1 = elems ( kepoch )
      t1 = (et - t1)/60.0_wp

!
!     Compute state.
!
      call xxsgp4e ( ctx, t1, state )

      if ( ctx%failed() ) return

!
!     Checkout, then return.
!
      return

      end subroutine evsgp4

      !> Return the location within the set array of the NTH element within
      !> the order imposed by the ASCII collating sequence.
      !>
      !> The function returns the location of the NTH element in the set.
      !>
      !>## Detailed Input
      !>
      !>     NTH      is an index to an element of a set. If the set is to
      !>              be conceived as sorted in increasing order, then the
      !>              NTH element of a set is well defined.
      !>
      !>     SET      is a set.
      !>
      !>## Detailed Output
      !>
      !>     The function returns the location within the set array of the
      !>     NTH element within the order imposed by the ASCII collating
      !>     sequence. Thus, a set may be traversed in order:
      !>
      !>        SET( FETCHC ( 1 ) )
      !>        SET( FETCHC ( 2 ) )
      !>         .
      !>         .
      !>        SET( FETCHC ( CARDC ( SET ) ) )
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the element does not exist, the error SPICE(INVALIDINDEX)
      !>         is signaled, and the value of FETCHC is zero.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     Within a set, the elements may be stored in arbitrary
      !>     order. The elements of a set may be retrieved by stepping
      !>     through the set array:
      !>
      !>        SET( 1 )
      !>        SET( 2 )
      !>         .
      !>         .
      !>        SET( CARDC ( SET ) )
      !>
      !>     Likewise, the elements may be retrieved in the order imposed by
      !>     the ASCII collating sequence, by using FETCHC:
      !>
      !>        SET( FETCHC ( 1, SET ) )
      !>        SET( FETCHC ( 2, SET ) )
      !>         .
      !>         .
      !>        SET( FETCHC ( CARDC ( SET ), SET ) )
      !>
      !>     In general, FETCHC ( I, SET ) is not equal to I.
      !>
      !>## Examples
      !>
      !>     Let SET contain the following elements.
      !>
      !>        'Feynman'
      !>        'Einstein'
      !>        'Bohr'
      !>        'Newton'
      !>
      !>     Then the code fragment
      !>
      !>        DO I = 1, CARDC ( SET )
      !>           WRITE (*,*) SET(FETCHC(I,SET))
      !>        END DO
      !>
      !>     always produces the following output.
      !>
      !>        Bohr
      !>        Einstein
      !>        Feynman
      !>        Newton
      !>
      !>     The code fragment
      !>
      !>        DO I = 1, CARDC ( SET )
      !>           WRITE (*,*) SET(I)
      !>        END DO
      !>
      !>     produces the same elements in unspecified order.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     H.A. Neilan        (JPL)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 27-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.1.0, 17-MAY-1994 (HAN)
      !>
      !>        If the value of the function RETURN is .TRUE. upon execution of
      !>        this module, this function is assigned a default value of
      !>        either 0, 0.0D0, .FALSE., or blank depending on the type of
      !>        the function.
      !>
      !>-    SPICELIB Version 1.0.1, 10-MAR-1992 (WLT)
      !>
      !>         Comment section for permuted index source lines was added
      !>         following the header.
      !>
      !>-    SPICELIB Version 1.0.0, 31-JAN-1990 (WLT) (IMU)
      module integer(ip) function fetchc ( ctx, nth, set )
      use pepper_kinds, only: ip
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      integer(ip), intent(in) :: nth  !! Index of a particular element.
      character(*), intent(in) :: set      ( lbcell:* )  !! Input set.


!
!     Set up the error processing.
!
      if ( ctx%failed() ) then
         fetchc = 0
         return
      end if

!
!     Check to see if the N'TH element exists.
!
      if ( nth < 1  .or.  nth > cardc ( ctx, set ) ) then
         fetchc = 0
         call ctx%setmsg ( 'NTH element does not exist. NTH was *.' )
         call ctx%errint ( '*', nth              )
         call ctx%sigerr ( 'SPICE(INVALIDINDEX)' )

!
!     The great secret is that, for now, sets really are maintained
!     in order, for reasons of efficiency.
!
      else
         fetchc = nth
      end if

      return
      end function fetchc

      !> Return the location within the set array of the NTH element
      !> within the order imposed by the values of the elements.
      !>
      !> The function returns the location of the NTH element in the set.
      !>
      !>## Detailed Input
      !>
      !>     NTH      is an index to an element of a set. If the set is to
      !>              be conceived as sorted in increasing order, then the
      !>              NTH element of a set is well defined.
      !>
      !>     SET      is a set.
      !>
      !>## Detailed Output
      !>
      !>     The function returns the location within the set array of the NTH
      !>     element within the order imposed by the values of the elements,
      !>
      !>        ... -1.D0 < 0.D0 < 1.D0 < 2.D0 < 3.D0 ...
      !>
      !>     Thus, a set may be traversed in order:
      !>
      !>        SET( FETCHD ( 1 ) )
      !>        SET( FETCHD ( 2 ) )
      !>         .
      !>         .
      !>        SET( FETCHD ( CARDD ( SET ) ) )
      !>
      !>## Parameters
