      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: x  !! Double precision value, unused.
      real(wp), intent(out) :: value  !! Double precision value, unused. (PEPPER: an output, as for any [[gf_scalar]]; not set)

