      !>     This function operates by side effects.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     Error free.
      !>
      !>## Files
      !>
      !>     This routine does not use SPICE kernels directly, but it
      !>     supports searches for DSK segments.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to prepare for DSK segment searches
      !>     using the DSK segment comparison callback
      !>
      !>        ZZDSKCIT
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 11-JUL-2016 (NJB)
      module logical function zzdsksit ( ctx, bodyid, nsurf, srflst, et )
      use pepper_containers, only: grow
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: twopi
      use pepper_arrays, only: shelli
      use pepper_inc_dskdsc
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: nsurf  !! Surface ID count.
      integer(ip), intent(in) :: srflst ( * )  !! Surface ID list.
      integer(ip), intent(in) :: bodyid  !! ID code of target body.
      real(wp), intent(in) :: et  !! Epoch, expressed as seconds past J2000 TDB.
      real(wp) :: alt
      real(wp) :: co1max
      real(wp) :: co1min
      real(wp) :: co2max
      real(wp) :: co2min
      real(wp) :: f
      real(wp) :: lat
      real(wp) :: loccor ( 1 )
      real(wp) :: locpos ( 3 )
      real(wp) :: lon
      real(wp) :: r
      real(wp) :: re
      real(wp) :: rmat   ( 3, 3 )
      real(wp) :: scale
      integer(ip) :: i
      integer(ip) :: segfid
      integer(ip) :: segsys
      integer(ip) :: surf
      if ( .not. allocated ( ctx%zzdsksel_state ) ) allocate ( ctx%zzdsksel_state )
!
!     PEPPER: the surface list has room for any number of surfaces (it
!     grows before the ASSOCIATE block; SPICELIB's held MAXSRF, 100).
!
      call grow ( ctx%zzdsksel_state%savsrf, max(1_ip, nsurf) )
      associate ( savbid => ctx%zzdsksel_state%savbid, &
                  savet => ctx%zzdsksel_state%savet, &
                  savnsf => ctx%zzdsksel_state%savnsf, &
                  savsrf => ctx%zzdsksel_state%savsrf )
      zzdsksit = .false.
!
!     Save input values.
!
      savbid = bodyid
      savet  = et

!
!     PEPPER: any number of surfaces (SPICELIB signaled
!     SPICE(VALUEOUTOFRANGE) above MAXSRF, 100).
!

      savnsf = nsurf

      do i = 1, nsurf
         savsrf(i) = srflst(i)
      end do

      call shelli ( nsurf, savsrf )

      return
      end associate
      end function zzdsksit

      !> The function returns .TRUE. if and only if the specified segment
      !> matches the body ID set via [[zzdsksit]].
