      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 23-NOV-2020 (JDR) (NJB)
      !>
      !>        Corrected Brief_I/O description of input DSKDSC.
      !>
      !>-    SPICELIB Version 1.0.0, 11-JUL-2016 (NJB)
      module logical function zzdskcit ( ctx, handle, dladsc, dskdsc )
      use pepper_containers, only: grow
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: twopi
      use pepper_arrays, only: bsrchi
      use pepper_inc_dskdsc
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of DSK containing segment to be checked.
      integer(ip), intent(in) :: dladsc ( * )  !! DLA descriptor of segment to be checked.
      real(wp), intent(in) :: dskdsc ( * )  !! DSK descriptor of segment to be checked.
      real(wp) :: alt
      real(wp) :: co1max
      real(wp) :: co1min
      real(wp) :: co2max
      real(wp) :: co2min
      real(wp) :: f
      real(wp) :: lat
      real(wp) :: loccor ( 1 )
      real(wp) :: locpos ( 3 )
      real(wp) :: lon
      real(wp) :: r
      real(wp) :: re
      real(wp) :: rmat   ( 3, 3 )
      real(wp) :: scale
      integer(ip) :: i
      integer(ip) :: segfid
      integer(ip) :: segsys
      integer(ip) :: surf
      if ( .not. allocated ( ctx%zzdsksel_state ) ) allocate ( ctx%zzdsksel_state )
!
!     PEPPER: the surface list has room for any number of surfaces (it
!     grows before the ASSOCIATE block; SPICELIB's held MAXSRF, 100).
!
      call grow ( ctx%zzdsksel_state%savsrf, 1_ip )
      associate ( savbid => ctx%zzdsksel_state%savbid, &
                  savet => ctx%zzdsksel_state%savet, &
                  savnsf => ctx%zzdsksel_state%savnsf, &
                  savsrf => ctx%zzdsksel_state%savsrf )
      zzdskcit = .false.

      if ( savbid  == nint( dskdsc(ctridx) )  ) then

         if (      ( savet >= dskdsc(btmidx) ) &
             .and. ( savet <= dskdsc(etmidx) )  ) then

            if ( savnsf < 1 ) then
!
!              There are no surface ID constraints; we have
!              a match.
!
               zzdskcit = .true.

            else
!
!              We have a match if and only if the surface ID of this
!              segment is on the list of allowed surface IDs.
!
               surf     = nint( dskdsc(srfidx) )

               zzdskcit = bsrchi( surf, savnsf, savsrf ) > 0

            end if

         end if

      end if

      return
      end associate
      end function zzdskcit

