      module logical function zzdskmsc ( ctx, bodyid, surfid, framid, corsys, corpar, et, cor1, cor2 )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: twopi
      use pepper_inc_dskdsc
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: surfid  !! ID code of target surface.
      integer(ip), intent(in) :: bodyid  !! ID code of target body.
      integer(ip), intent(in) :: corsys  !! Coordinate system code.
      real(wp), intent(in) :: corpar ( * )  !! Coordinate system parameters.
      real(wp), intent(in) :: cor1  !! First coordinate.
      real(wp), intent(in) :: cor2  !! Second coordinate.
      integer(ip), intent(in) :: framid  !! ID code of body-fixed reference frame.
      real(wp), intent(in) :: et  !! Epoch, expressed as seconds past J2000 TDB.
      real(wp) :: alt
      real(wp) :: co1max
      real(wp) :: co1min
      real(wp) :: co2max
      real(wp) :: co2min
      real(wp) :: f
      real(wp) :: lat
      real(wp) :: loccor ( 1 )
      real(wp) :: locpos ( 3 )
      real(wp) :: lon
      real(wp) :: r
      real(wp) :: re
      real(wp) :: rmat   ( 3, 3 )
      real(wp) :: scale
      integer(ip) :: i
      integer(ip) :: segfid
      integer(ip) :: segsys
      integer(ip) :: surf
      if ( .not. allocated ( ctx%zzdsksel_state ) ) allocate ( ctx%zzdsksel_state )
      associate ( savbid => ctx%zzdsksel_state%savbid, &
                  savco1 => ctx%zzdsksel_state%savco1, &
                  savco2 => ctx%zzdsksel_state%savco2, &
                  savet => ctx%zzdsksel_state%savet, &
                  savfid => ctx%zzdsksel_state%savfid, &
                  savpar => ctx%zzdsksel_state%savpar, &
                  savsys => ctx%zzdsksel_state%savsys, &
                  savtrg => ctx%zzdsksel_state%savtrg )
      zzdskmsc = .false.

      savtrg = bodyid
      savbid = surfid
      savfid = framid
      savsys = corsys

      savpar = corpar(1:nsypar)

      savet  = et
      savco1 = cor1
      savco2 = cor2

      return
      end associate
      end function zzdskmsc

      !> The function returns .TRUE. if and only if the specified segment
      !> matches the body ID set via [[zzdskmsc]].
      !>
      !> Perform a matched attribute comparison using target ID, surface
      !> ID, frame ID, coordinate system, coordinate parameters, time, and
      !> coordinates.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE     is the handle of the DSK containing a segment to
      !>                be checked.
      !>
      !>     DLADSC,
      !>     DSKDSC     are, respectively, the DLA descriptor and DSK
      !>                descriptor of a segment to be checked.
      !>
      !>## Detailed Output
      !>
      !>     The function returns .TRUE. if and only if the specified segment
      !>     matches the
      !>
      !>        body ID
      !>        surface ID
      !>        frame ID
      !>        coordinate system
      !>        coordinate parameters
      !>        time
      !>        coordinates
      !>
      !>     set via ZZDSKMSC.
      !>
      !>     A time and coordinate match means that the input values are
      !>     contained in the respective time interval and spatial coverage
      !>     region of the segment.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     Error free.
      !>
      !>## Files
      !>
      !>     This routine does not use SPICE kernels directly, but it
      !>     supports searches for DSK segments.
      !>
      !>## Particulars
      !>
      !>     This routine is used to search for DSK segments that have
      !>     attributes matching the values set via the latest call to
      !>
      !>        ZZDSKMSC
      !>
      !>     This is a "matched attribute" search, also known as a
      !>     "checked" search. See Detailed_Output above.
      !>
      !>     These searches are conducted by ZZDSKSNS. This function
      !>     is passed to that routine as a callback argument.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 23-NOV-2020 (JDR) (NJB)
      !>
      !>        Corrected Brief_I/O description of input DSKDSC.
      !>
      !>-    SPICELIB Version 1.0.0, 11-JUL-2016 (NJB)
      module logical function zzdskmmc ( ctx, handle, dladsc, dskdsc )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: twopi
      use pepper_inc_dskdsc
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! Handle of DSK containing segment to be checked.
      integer(ip), intent(in) :: dladsc ( * )  !! DLA descriptor of segment to be checked.
      real(wp), intent(in) :: dskdsc ( * )  !! DSK descriptor of segment to be checked.
      real(wp) :: alt
      real(wp) :: co1max
      real(wp) :: co1min
      real(wp) :: co2max
      real(wp) :: co2min
      real(wp) :: f
      real(wp) :: lat
      real(wp) :: loccor ( 1 )
      real(wp) :: locpos ( 3 )
      real(wp) :: lon
      real(wp) :: r
      real(wp) :: re
      real(wp) :: rmat   ( 3, 3 )
      real(wp) :: scale
      integer(ip) :: i
      integer(ip) :: segfid
      integer(ip) :: segsys
      integer(ip) :: surf
      real(wp), parameter :: pi2 = twopi
      if ( .not. allocated ( ctx%zzdsksel_state ) ) allocate ( ctx%zzdsksel_state )
      associate ( savbid => ctx%zzdsksel_state%savbid, &
                  savco1 => ctx%zzdsksel_state%savco1, &
                  savco2 => ctx%zzdsksel_state%savco2, &
                  savet => ctx%zzdsksel_state%savet, &
                  savfid => ctx%zzdsksel_state%savfid, &
                  savpar => ctx%zzdsksel_state%savpar, &
                  savsys => ctx%zzdsksel_state%savsys, &
                  savtrg => ctx%zzdsksel_state%savtrg )
      zzdskmmc = .false.

!
!     Check the target ID.
!
      if ( savtrg  /= nint( dskdsc(ctridx) )  ) return

!
!     Check the surface ID.
!
      if ( savbid  /= nint( dskdsc(srfidx) )  ) return

!
!     Check the frame ID.
!
      if ( savfid  /= nint( dskdsc(frmidx) )  ) return

!
!     Check the coordinate system.
!
      if ( savsys  /= nint( dskdsc(sysidx) )  ) return

!
!     If the system is planetodetic, check the reference
!     ellipsoid parameters.
!
      if ( savsys == pdtsys ) then

         if (  abs( savpar(1) - dskdsc(paridx)   ) > margin ) return

         if (  abs( savpar(2) - dskdsc(paridx+1) ) > margin ) return

      end if

!
!     The segment attributes match; check the time coverage.
!
      if (      ( savet >= dskdsc(btmidx) ) &
          .and. ( savet <= dskdsc(etmidx) )  ) then
!
!        Check the coordinates.
!
         segsys = nint( dskdsc(sysidx) )
!
!        Make a local copy of the first coordinate.
!
         loccor(1) = savco1

         if (      ( segsys == latsys ) &
              .or. ( segsys == pdtsys ) ) then
!
!           Adjust segment bounds using a small margin.
!
            co1min = dskdsc( mn1idx ) - margin
            co1max = dskdsc( mx1idx ) + margin
            co2min = dskdsc( mn2idx ) - margin
            co2max = dskdsc( mx2idx ) + margin

!
!           Move longitude into range.
!
            if ( loccor(1) < co1min ) then

               loccor(1) = loccor(1) + pi2

            else if ( loccor(1) > co1max ) then

               loccor(1) = loccor(1) - pi2

            end if

         else

            scale  = ( 1.0_wp + margin )

            co1min = dskdsc( mn1idx ) - scale * abs( dskdsc(mn1idx) )
            co1max = dskdsc( mx1idx ) + scale * abs( dskdsc(mx1idx) )
            co2min = dskdsc( mn2idx ) - scale * abs( dskdsc(mn2idx) )
            co2max = dskdsc( mx2idx ) + scale * abs( dskdsc(mx2idx) )

         end if

!
!        Check the first coordinate against the segment's
!        corresponding coverage range.
!
         if (     ( loccor(1) < co1min ) &
             .or. ( loccor(1) > co1max ) ) then
!
!           The first input coordinate is not covered by this
!           segment.
!
            return

         end if

!
!        Compare the second coordinate against the segment's
!        corresponding coverage range.
!
         if (     ( savco2 < co2min ) &
             .or. ( savco2 > co2max ) ) then
!
!           The second input coordinate is not covered by this
!           segment.
!
            return

         end if

!
!        At this point we have a match.
!
         zzdskmmc = .true.

      end if

      return
      end associate
      end function zzdskmmc

      !> The function always returns the value .FALSE.
      !>
      !> Set surface and target ID, data class, ET, and rectangular
      !> coordinates for a coverage match search. Set the frame ID
