      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.1.0, 01-NOV-2021 (JDR) (EDW)
      !>
      !>        Declared routine as deprecated.
      !>
      !>        Changed input argument name "TIME" to "ET" for consistency
      !>        with other routines.
      !>
      !>        Corrected the description of QO and SO constants in the
      !>        detailed description of the input argument GEOPHS and the input
      !>        element names in ELEMS.
      !>
      !>        Edited the header to comply with NAIF standard. Added complete
      !>        code example based on existing fragments.
      !>
      !>-    SPICELIB Version 2.0.0, 23-JAN-2013 (EDW)
      !>
      !>        Corrected initialization block error. The ZZDPINIT call
      !>        causes a side-effect required for each DPSPCE call.
      !>        The ZZDPINIT call now occurs outside the initialization
      !>        block. Note from designer, side-effects are bad.
      !>
      !>        Added proper citation for Hoots paper.
      !>
      !>-    SPICELIB Version 1.2.2, 22-AUG-2006 (EDW)
      !>
      !>        Replaced references to LDPOOL with references
      !>        to FURNSH.
      !>
      !>-    SPICELIB Version 1.2.1, 27-DEC-2000 (EDW)
      !>
      !>        Corrected error in header documentation. Horner's Rule
      !>        not Butcher's.
      !>
      !>-    SPICELIB Version 1.2.0, 24-MAR-1999 (EDW)
      !>
      !>        Documentation expanded to include modifications made
      !>        to private routines. Some English errors corrected.
      !>
      !>        Alphabetized variable declaration lists.
      !>
      !>        Temporary variable TEMP removed. OMGDOT argument added to
      !>        ZZDPSEC call.
      !>
      !>-    SPICELIB Version 1.1.0, 05-OCT-1998 (WLT)
      !>
      !>        Forced initialization section until we can figure out
      !>        why it doesn't work on SUNs.
      !>
      !>-    SPICELIB Version 1.0.1, 11-MAR-1998 (EDW)
      !>
      !>        Corrected error in header describing GEOPHS array.
      !>
      !>-    SPICELIB Version 1.0.0, 11-NOV-1998 (EDW)
      module subroutine dpspce ( ctx, et, geophs, elems, state )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: halfpi, twopi
      use pepper_math, only: latrec
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Time for state evaluation in seconds past ephemeris epoch J2000.
      real(wp), intent(in) :: geophs ( 8  )  !! The array of geophysical constants.
      real(wp), intent(in) :: elems  ( 10 )  !! Array of orbit elements.
      real(wp), intent(out) :: state  ( 6  )  !! State vector at ET.
      real(wp), parameter :: tol = 1.0e-6_wp
      integer(ip), parameter :: numgeo = 8
      integer(ip), parameter :: numelm = 10
      real(wp) :: eta
      real(wp) :: etasq
      real(wp) :: tsq
      real(wp) :: xmdf
      real(wp) :: temp1
      real(wp) :: coef
      real(wp) :: tsi
      real(wp) :: psisq
      real(wp) :: qoms24
      real(wp) :: templ
      real(wp) :: coef1
      real(wp) :: theta2
      real(wp) :: e
      real(wp) :: xno
      real(wp) :: cosuk
      real(wp) :: rdot
      real(wp) :: xj4
      real(wp) :: c2
      real(wp) :: qo
      real(wp) :: axn
      real(wp) :: betao
      integer(ip) :: i
      logical :: cont
      real(wp) :: pinvsq
      real(wp) :: sin2u
      real(wp) :: pl
      real(wp) :: x1m5th
      real(wp) :: xj3
      real(wp) :: eo
      real(wp) :: xj2
      real(wp) :: rfdot
      real(wp) :: s4
      real(wp) :: cos2u
      real(wp) :: perige
      real(wp) :: del1
      real(wp) :: rfdotk
      real(wp) :: xn
      real(wp) :: delo
      real(wp) :: temp2
      real(wp) :: xnodek
      real(wp) :: ao
      real(wp) :: qoms2t
      real(wp) :: n     ( 3 )
      real(wp) :: betao2
      real(wp) :: tsince
      real(wp) :: temp
      real(wp) :: a
      real(wp) :: xmam
      real(wp) :: em
      real(wp) :: a1
      real(wp) :: epw
      real(wp) :: rk
      real(wp) :: scale
      real(wp) :: aynl
      real(wp) :: uk
      real(wp) :: xll
      real(wp) :: a3ovk2
      real(wp) :: u     ( 3 )
      real(wp) :: capu
      real(wp) :: ck4
      real(wp) :: xincl
      real(wp) :: ecose
      real(wp) :: sinuk
      real(wp) :: betal
      real(wp) :: so
      real(wp) :: s
      real(wp) :: esine
      real(wp) :: tempa
      real(wp) :: xhdot1
      real(wp) :: uang
      real(wp) :: xlt
      real(wp) :: omgadf
      real(wp) :: m     ( 3 )
      real(wp) :: xl
      real(wp) :: ayn
      real(wp) :: cosu
      real(wp) :: rdotk
      real(wp) :: tempe
      real(wp) :: xnoddf
      real(wp) :: elsq
      real(wp) :: eeta
      real(wp) :: xinck
      real(wp) :: xinc
      real(wp) :: v     ( 3 )
      real(wp) :: sinu
      real(wp) :: xnode
      if ( .not. allocated ( ctx%dpspce_state ) ) allocate ( ctx%dpspce_state )
      associate ( ae => ctx%dpspce_state%ae, &
                  ck2 => ctx%dpspce_state%ck2, &
                  xke => ctx%dpspce_state%xke, &
                  xkmper => ctx%dpspce_state%xkmper, &
                  lstphs => ctx%dpspce_state%lstphs, &
                  bstar => ctx%dpspce_state%bstar, &
                  epoch => ctx%dpspce_state%epoch, &
                  omegao => ctx%dpspce_state%omegao, &
                  xmo => ctx%dpspce_state%xmo, &
                  xnodeo => ctx%dpspce_state%xnodeo, &
                  lstelm => ctx%dpspce_state%lstelm, &
                  aodp => ctx%dpspce_state%aodp, &
                  aycof => ctx%dpspce_state%aycof, &
                  c1 => ctx%dpspce_state%c1, &
                  c4 => ctx%dpspce_state%c4, &
                  cosepw => ctx%dpspce_state%cosepw, &
                  cosio => ctx%dpspce_state%cosio, &
                  omgdot => ctx%dpspce_state%omgdot, &
                  pio2 => ctx%dpspce_state%pio2, &
                  pix2 => ctx%dpspce_state%pix2, &
                  sinepw => ctx%dpspce_state%sinepw, &
                  sinio => ctx%dpspce_state%sinio, &
                  t2cof => ctx%dpspce_state%t2cof, &
                  temp3 => ctx%dpspce_state%temp3, &
                  temp4 => ctx%dpspce_state%temp4, &
                  temp5 => ctx%dpspce_state%temp5, &
                  temp6 => ctx%dpspce_state%temp6, &
                  x1mth2 => ctx%dpspce_state%x1mth2, &
                  x3thm1 => ctx%dpspce_state%x3thm1, &
                  x7thm1 => ctx%dpspce_state%x7thm1, &
                  xlcof => ctx%dpspce_state%xlcof, &
                  xmdot => ctx%dpspce_state%xmdot, &
                  xnodcf => ctx%dpspce_state%xnodcf, &
                  xnodot => ctx%dpspce_state%xnodot, &
                  xnodp => ctx%dpspce_state%xnodp, &
                  doinit => ctx%dpspce_state%doinit, &
                  first => ctx%dpspce_state%first )
      if ( ctx%failed() ) return

!
!     If this is the very first time into this routine, set these
!     values.
!
      if ( first ) then

         pix2   = twopi
         pio2   = halfpi
         first  = .false.

      end if

!
!     If initialization flag is .FALSE., then this is not the first
!     call to this routine.  Check the stuff.
!
      if ( .not. doinit ) then

!
!        Check whether the current and last constants and elements
!        match.  If not, we need to reinitialize everything
!        since the propagation is dependent on the value of these
!        arrays.
!
         do i = 1, numgeo

           if( lstphs( i ) /= geophs( i ) ) then
              doinit = .true.
           end if

         end do

         do i = 1, numelm

           if( lstelm( i ) /= elems( i ) ) then
              doinit = .true.
           end if

         end do

      end if

!
!     Initialization block.  Always called on the initial entry and
!     anytime the geophysical or elements array changes.
!
      if ( doinit ) then

         doinit = .false.

!
!        Retrieve the geophysical constants from the GEOPHS array
!
         xj2    = geophs( 1 )
         xj3    = geophs( 2 )
         xj4    = geophs( 3 )
         xke    = geophs( 4 )
         qo     = geophs( 5 )
         so     = geophs( 6 )
         xkmper = geophs( 7 )
         ae     = geophs( 8 )

!
!        Save the geophysical constants for later comparison
!
         do i = 1, numgeo
            lstphs( i ) = geophs( i )
         end do

!
!        Unpack the elements array.
!
         bstar  = elems( 3  )
         xincl  = elems( 4  )
         xnodeo = elems( 5  )
         eo     = elems( 6  )
         omegao = elems( 7  )
         xmo    = elems( 8  )
         xno    = elems( 9  )
         epoch  = elems( 10 )

!
!        Save the elements for later comparison
!
         do i = 1, numelm
            lstelm( i ) = elems( i )
         end do

!
!        Set common variables, the init flag and calculate the
!        WGS-72 physical and geopotential constants
!
!        CK2 =  0.5   * J2 * AE^2
!        CK4 = -0.375 * J4 * AE^4
!
!        These are values calculated only once and then saved for
!        future access.
!
         ck2    = 0.5_wp   * xj2 * ae**2
         ck4    =-0.375_wp * xj4 * ae**4
         qoms2t = ( (qo - so)*ae/xkmper )**4
         s      = ae * ( one + so/xkmper )

!
!        Recover original mean motion (XNODP) and semimajor axis (AODP)
!        from input elements
!
         a1     = ( xke / xno )**tothrd
         cosio  = dcos( xincl )
         theta2 = cosio**2
         x3thm1 = 3.0_wp * theta2  -  one
         betao2 = one - eo**2
         betao  = dsqrt( betao2 )

         del1   = 1.5_wp*ck2*x3thm1/( (a1**2) * betao * betao2 )
         ao     = a1 * ( one - del1 * ( 0.5_wp * tothrd  + &
                  del1*( one + 134.0_wp/81.0_wp * del1 ) ) )

         delo   = 1.5_wp * ck2 * x3thm1/( (ao**2)*betao*betao2 )
         xnodp  = xno/( one + delo )
         aodp   =  ao/( one - delo )

!
!        For perigee below 156 km, the values of S and QOMS2T are
!        altered
!
         s4     = s
         qoms24 = qoms2t
         perige = ( aodp * ( one - eo ) - ae ) * xkmper

         if ( perige < 156.0_wp ) then

            s4 = perige - 78.0_wp

            if ( perige > 98.0_wp) then

               qoms24 = ( (120.0_wp - s4) * ae/xkmper )**4
               s4     = s4/xkmper + ae

            else
               s4     = 20.0_wp

            end if

         end if

         pinvsq = one/(aodp**2 * betao2**2)
         tsi    = one/(aodp - s4)
         eta    = aodp*eo*tsi
         etasq  = eta**2
         eeta   = eo*eta
         psisq  = dabs(one-etasq)
         coef   = qoms24 * tsi**4
         coef1  = coef / psisq**3.5_wp

         c2     = coef1 * xnodp * &
                 ( aodp * &
                   ( one + 1.5_wp * etasq + &
                                    eeta * ( 4.0_wp + etasq) ) + &
                   0.75_wp * ck2 * tsi/psisq * x3thm1 * &
                      (8.0_wp + 3.0_wp * etasq * (8.0_wp+etasq) ) )

         c1     = bstar * c2
         sinio  = dsin( xincl )
         a3ovk2 =-xj3 / ck2 * ae**3
         x1mth2 = one - theta2

         c4     = 2.0_wp * xnodp * coef1 * aodp * betao2 * &
                 ( eta * ( 2.0_wp + 0.5_wp * etasq ) + &
                   eo * ( 0.5_wp + 2.0_wp * etasq ) - &
                   2.0_wp * ck2 * tsi/( aodp * psisq ) * &
                   (-3.0_wp * x3thm1 * &
                   ( one - 2.0_wp * eeta + &
                                 etasq *( 1.5_wp - 0.5_wp*eeta) ) + &
                   0.75_wp * x1mth2 * ( 2.0_wp * etasq - eeta * &
                   ( one + etasq ) ) * dcos( 2.0_wp * omegao) ) )

         temp1  = 3.0_wp   * ck2 * pinvsq * xnodp
         temp2  = temp1  * ck2 * pinvsq
         temp3  = 1.25_wp * ck4 * pinvsq * pinvsq * xnodp

         xmdot  = xnodp + 0.5_wp * temp1 * betao * x3thm1 + &
                  0.0625_wp * temp2 * betao * &
                  ( 13.0_wp + theta2 * ( 137.0_wp * theta2 - 78.0_wp ) )

         x1m5th = one - 5.0_wp * theta2

         omgdot =-0.5_wp * temp1 * x1m5th + 0.0625_wp * &
                  temp2 * (7.0_wp + theta2*( 395.0_wp * theta2 - 114.0_wp)) &
                + temp3 * (3.0_wp + theta2*(  49.0_wp * theta2 - 36.0_wp ))

         xhdot1 =-temp1 * cosio

         xnodot = xhdot1 + ( 0.5_wp*temp2*( 4.0_wp - 19.0_wp * theta2 ) &
                         + 2.0_wp * temp3 &
                         * ( 3.0_wp - 7.0_wp * theta2 ) )*cosio

         xnodcf = 3.5_wp * betao2 * xhdot1 * c1
         t2cof  = 1.5_wp * c1
         xlcof  = 0.125_wp*a3ovk2*sinio*(3.0_wp+5.0_wp*cosio)/(one+cosio)
         aycof  = 0.25_wp * a3ovk2*sinio
         x7thm1 = 7.0_wp * theta2 - one

      end if

      call zzdpinit( ctx, aodp  , xmdot, omgdot, xnodot, &
                     xnodp , elems )

!
!     Get the time since the EPOCH in minutes.
!
      tsince = ( et - epoch )/60.0_wp

!
!     Update for secular gravity and atmospheric drag
!
      xmdf   = xmo    +  xmdot  * tsince
      omgadf = omegao +  omgdot * tsince
      xnoddf = xnodeo +  xnodot * tsince
      tsq    =           tsince * tsince
      xnode  = xnoddf +  xnodcf * tsq
      tempa  = one    -  c1     * tsince
      tempe  =           bstar  * c4 * tsince
      templ  =           t2cof  * tsq
      xn     = xnodp

!
!     Calculate the secular terms.
!
      call zzdpsec( ctx, xmdf , omgadf, xnode, em, xinc, xn, tsince, &
                    elems, omgdot )

      a    = ( (xke/xn)**tothrd ) * tempa**2
      e    = em - tempe
      xmam = xmdf + xnodp * templ

!
!     Calculate the periodic terms.
!
      call zzdpper( ctx, tsince, e, xinc, omgadf, xnode, xmam )

      xl   = xmam + omgadf + xnode
      xn   = xke/( a**1.5_wp )

!
!      Long period periodics
!
      axn  = e * dcos( omgadf )
      temp = one/( a * (one - e**2) )
      xll  = temp * xlcof * axn
      aynl = temp * aycof
      xlt  = xl + xll
      ayn  = e * dsin( omgadf ) + aynl

!
!     Solve Kepler's equation
!
!           U = EPW - AXN * SIN(EPW)  +  AYN * COS(EPW)
!
!     Where
!
!        AYN  = E * SIN(OMEGA)  +   AYNL
!        AXN  = E * COS(OMEGA)
!
!     And
!
!        AYNL =  -0.50D0 * SINIO * AE * J3 / (J2 * A * (1.0D0  -  E^2))
!

!
!     Get the mod division of CAPU with 2 Pi
!
      capu = dmod( (xlt - xnode), pix2 )

      if ( capu < zero ) then
         capu = capu + pix2
      end if

!
!     Set initial states for the Kepler solution
!

      epw   = capu
      cont  =.true.

      do while ( cont )

         temp2  = epw
         sinepw = dsin( temp2 )
         cosepw = dcos( temp2 )
         temp3  = axn * sinepw
         temp4  = ayn * cosepw
         temp5  = axn * cosepw
         temp6  = ayn * sinepw
         epw    = (capu-temp4+temp3-temp2)/(one-temp5-temp6)+temp2

!
!        Test for convergence against the defined tolerance
!

         if ( dabs( epw - temp2 ) <= tol ) then
            cont = .false.
         end if

      end do

!
!     Short period preliminary quantities
!

      ecose = temp5 + temp6
      esine = temp3 - temp4
      elsq  = axn * axn  +  ayn * ayn
      temp  = one - elsq
      pl    = a * temp
      rk    = a * ( one - ecose )
      temp1 = one/rk
      rdot  = xke * dsqrt(a) * esine * temp1
      rfdot = xke * dsqrt(pl)* temp1
      temp2 = a * temp1
      betal = dsqrt( temp )
      temp3 = one/( one + betal )

      cosu  = temp2 * ( cosepw - axn + ayn * esine * temp3 )
      sinu  = temp2 * ( sinepw - ayn - axn * esine * temp3 )

!
!     Compute the angle from the x-axis of the point ( COSU, SINU )
!
      if (      sinu /= zero &
           .or. cosu /= zero ) then

         uang = datan2 (sinu,cosu)

         if ( uang < zero ) then
            uang = uang + pix2
         end if

      else
         uang = zero

      end if

      sin2u = 2.0_wp * sinu * cosu
      cos2u = 2.0_wp * cosu * cosu  -  one
      temp1 = ck2   * ( one/pl )
      temp2 = temp1 * ( one/pl )

!
!     Update for short periodics
!
      rk     = rk*( one - 1.5_wp * temp2 * betal * x3thm1 ) + &
               0.5_wp * temp1 * x1mth2 * cos2u
      uk     = uang  - 0.25_wp * temp2 * x7thm1 * sin2u
      xnodek = xnode + 1.5_wp  * temp2 * cosio  * sin2u
      xinck  = xinc  + 1.5_wp  * temp2 * cosio  * sinio  * cos2u
      rdotk  = rdot  -          xn    * temp1  * x1mth2 * sin2u
      rfdotk = rfdot + xn * temp1*( x1mth2*cos2u + 1.5_wp*x3thm1 )

!
!     Orientation vectors are calculated by
!
!     U = M sin(uk) + N cos(uk)
!     V = M cos(uk) - N sin(uk)
!
!     Where M and N are euclidean 3 vectors
!
!     M = (-sin(xnodek)cos(xinck), cos(xnodek)cos(xinck), sin(xinck) )
!     N = (           cos(xnodek), sin(xnodek)          , 0          )
!

      sinuk  = dsin(uk)
      cosuk  = dcos(uk)

!
!     Use LATREC to generate M and N.  M is a latitude to rectangle
!     conversion of a unit vector where PI/2 + XNODEK is the longitude
!

      call latrec( one, pio2 + xnodek, xinck, m )
      call latrec( one,        xnodek,  zero, n )

!
!     Sum the components to obtain U and V
!
      u = sinuk*m + cosuk*n
      v = cosuk*m + (-sinuk)*n

!
!     Determine the position and velocity then pack the STATE vector
!     with value scaled to KM and KPS.
!
!     R = RK    U +        0 V
!     V = RKDOT U + RK RFDOT V
!

      scale = xkmper/ae

      state(1:3) = (rk*scale)*u + zero*v

!
!     Now scale to KPS for the velocity component
!

      scale = scale / 60.0_wp

      state(4:6) = (rdotk*scale)*u + (rfdotk*scale)*v

!
!     All done now....
!

      return
      end associate
      end subroutine dpspce

      !> Compute the local solar time for a given ephemeris epoch ET
      !> for an object on the surface of a body at a specified longitude.
      !>
      !>## Detailed Input
      !>
      !>     ET       is the epoch expressed in TDB seconds past the J2000
      !>              epoch at which a local time is desired.
      !>
      !>     BODY     is the NAIF ID-code of a body on which local time is to
      !>              be measured.
      !>
      !>     LON      is the longitude (either planetocentric or
      !>              planetographic) in radians of the site on the surface of
      !>              body for which local time should be computed.
      !>
      !>     TYPE     is the form of longitude supplied by the variable LON.
      !>              Allowed values are:
      !>
      !>                 'PLANETOCENTRIC'
      !>                 'PLANETOGRAPHIC'
      !>
      !>              Note the case of the letters in TYPE is insignificant.
      !>              Both 'PLANETOCENTRIC' and 'planetocentric' are
      !>              recognized.
      !>
      !>## Detailed Output
      !>
      !>     HR       is the local "hour" of the site specified at the epoch
      !>              ET. Note that an "hour" of local time does not have the
      !>              same duration as an hour measured by conventional clocks.
      !>              It is simply a representation of an angle. See the
      !>              $Particulars section for a more complete discussion of
      !>              the meaning of local time.
      !>
      !>     MN       is the number of "minutes" past the hour of the local
      !>              time of the site at the epoch ET. Again note that a
      !>              "local minute" is not the same as a minute you would
      !>              measure with conventional clocks.
      !>
      !>     SC       is the number of "seconds" past the minute of the local
      !>              time of the site at the epoch ET. Again note that a
      !>              "local second" is not the same as a second you would
      !>              measure with conventional clocks.
      !>
      !>     TIME     is a string expressing the local time on a "24 hour"
      !>              local clock.
      !>
      !>     AMPM     is a string expressing the local time on a "12 hour"
      !>              local clock together with the traditional AM/PM label to
      !>              indicate whether the sun has crossed the local zenith
      !>              meridian.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  This routine defines local solar time for any point on the
      !>         surface of the Sun to be 12:00:00 noon.
      !>
      !>     2)  If the TYPE of the coordinates is not recognized, the
      !>         error SPICE(UNKNOWNSYSTEM) is signaled.
      !>
      !>     3)  If the body-fixed frame to associate with BODY cannot be
      !>         determined, the error SPICE(CANTFINDFRAME) is signaled.
      !>
      !>     4)  If insufficient data are available to compute the location of
      !>         the sun in body-fixed coordinates, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     5)  If the BODY#_PM keyword required to determine the body
      !>         rotation sense is not found in the POOL or if it is found but
      !>         is not a numeric keyword with at least two elements, the error
      !>         SPICE(CANTGETROTATIONTYPE) is signaled.
      !>
      !>## Files
      !>
      !>     Suitable SPK and PCK files must be loaded prior to calling this
      !>     routine so that the body-fixed position of the sun relative to
      !>     BODY can be computed. The PCK files must contain the standard
      !>     BODY#_PM keyword need by this routine to determine the body
      !>     rotation sense.
      !>
      !>     When the input longitude is planetographic, the default
      !>     interpretation of this value can be overridden using the optional
      !>     kernel variable
      !>
      !>        BODY<body ID>_PGR_POSITIVE_LON
      !>
      !>     which is normally defined via loading a text kernel.
      !>
      !>## Particulars
      !>
      !>     This routine returns the local solar time at a user
      !>     specified location on a user specified body.
      !>
      !>     Let SUNLNG be the planetocentric longitude (in degrees) of
      !>     the sun as viewed from the center of the body of interest.
      !>
      !>     Let SITLNG be the planetocentric longitude (in degrees) of
      !>     the site for which local time is desired.
      !>
      !>     We define local time to be 12 + (SITLNG - SUNLNG)/15
      !>
      !>     (where appropriate care is taken to map ( SITLNG - SUNLNG )
      !>     into the range from -180 to 180).
      !>
      !>     Using this definition, we see that from the point of view
      !>     of this routine, local solar time is simply a measure of angles
      !>     between meridians on the surface of a body. Consequently,
      !>     this routine is not appropriate for computing "local times"
      !>     in the sense of Pacific Standard Time. For computing times
      !>     relative to standard time zones on earth, see the routines
      !>     TIMOUT and STR2ET.
      !>
      !>     Regarding planetographic longitude
      !>     ----------------------------------
      !>
      !>     In the planetographic coordinate system, longitude is defined
      !>     using the spin sense of the body. Longitude is positive to the
      !>     west if the spin is prograde and positive to the east if the spin
      !>     is retrograde. The spin sense is given by the sign of the first
      !>     degree term of the time-dependent polynomial for the body's prime
      !>     meridian Euler angle "W":  the spin is retrograde if this term is
      !>     negative and prograde otherwise. For the sun, planets, most
      !>     natural satellites, and selected asteroids, the polynomial
      !>     expression for W may be found in a SPICE PCK kernel.
      !>
      !>     The earth, moon, and sun are exceptions: planetographic longitude
      !>     is measured positive east for these bodies.
      !>
      !>     If you wish to override the default sense of positive
      !>     planetographic longitude for a particular body, you can do so by
      !>     defining the kernel variable
      !>
      !>        BODY<body ID>_PGR_POSITIVE_LON
      !>
      !>     where <body ID> represents the NAIF ID code of the body. This
      !>     variable may be assigned either of the values
      !>
      !>        'WEST'
      !>        'EAST'
      !>
      !>     For example, you can have this routine treat the longitude
      !>     of the earth as increasing to the west using the kernel
      !>     variable assignment
      !>
      !>        BODY399_PGR_POSITIVE_LON = 'WEST'
      !>
      !>     Normally such assignments are made by placing them in a text
      !>     kernel and loading that kernel via FURNSH.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) The following code example illustrates how to compute the
      !>        local time at a site on Mars with planetographic longitude
      !>        +326.17 deg at epoch ET.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: et2lst_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                     Contents
      !>              ---------                     --------
      !>              de421.bsp                     Planetary ephemeris
      !>              pck00010.tpc                  Planet orientation and
      !>                                            radii
      !>              naif0012.tls                  Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de421.bsp',
      !>                                  'pck00010.tpc',
      !>                                  'naif0012.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM ET2LST_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      RPD
      !>
      !>C
      !>C     Local parameters.
      !>C
      !>      CHARACTER*(*)         FMT
      !>      PARAMETER           ( FMT    = '(A,F7.2,A)'    )
      !>
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'et2lst_ex1.tm' )
      !>
      !>      CHARACTER*(*)         TYPE
      !>      PARAMETER           ( TYPE   = 'PLANETOGRAPHIC' )
      !>
      !>      INTEGER               AMPMLEN
      !>      PARAMETER           ( AMPMLEN = 51 )
      !>
      !>      INTEGER               MARS
      !>      PARAMETER           ( MARS   = 499 )
      !>
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 51 )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      CHARACTER*(AMPMLEN)   AMPM
      !>      CHARACTER*(TIMLEN)    TIME
      !>      CHARACTER*(20)        UTCSTR
      !>
      !>      DOUBLE PRECISION      DLON
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      RLON
      !>
      !>      INTEGER               HR
      !>      INTEGER               MN
      !>      INTEGER               SC
      !>
      !>C
      !>C     Load the kernels.
      !>C
      !>      CALL FURNSH ( META )
      !>
      !>      DLON   =  326.17D0
      !>      RLON   =  DLON * RPD( )
      !>      UTCSTR = '2002 SEP 02 00:00:00'
      !>
      !>      CALL STR2ET ( UTCSTR, ET )
      !>
      !>      CALL ET2LST ( ET, MARS, RLON, TYPE,
      !>     .              HR, MN,   SC,   TIME, AMPM )
      !>
      !>      WRITE(*,FMT) 'Local time at Mars', DLON,
      !>     .             ' degrees planetographic longitude:'
      !>      WRITE(*,*)   '   at UTC ', UTCSTR, ', LST = ', AMPM
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Local time at Mars 326.17 degrees planetographic longitude:
      !>            at UTC 2002 SEP 02 00:00:00, LST = 03:25:35 A.M.
      !>
      !>## Restrictions
      !>
      !>     1)  This routine relies on being able to determine the name
      !>         of the body-fixed frame associated with BODY through the
      !>         frames subsystem. If the BODY specified is NOT one of the
      !>         nine planets or their satellites, you will need to load
      !>         an appropriate frame definition kernel that contains
      !>         the relationship between the body id and the body-fixed frame
      !>         name. See frames.req required reading for more details
      !>         on specifying this relationship.
      !>
      !>     2)  The routine determines the body rotation sense using the PCK
      !>         keyword BODY#_PM. Therefore, you will need to a text PCK file
      !>         defining the complete set of the standard PCK body rotation
      !>         keywords for the body of interest. The text PCK file must be
      !>         loaded independently of whether a binary PCK file providing
      !>         rotation data for the same body is loaded or not.
      !>
      !>     3)  Although it is not currently the case for any of the Solar
      !>         System bodies, it is possible that the retrograde rotation
      !>         rate of a body would be slower than the orbital rate of the
      !>         body rotation around the Sun. The routine does not account for
      !>         such cases; for them it will compute incorrect the local time
      !>         progressing backwards.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     W.L. Taber         (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 3.1.0, 26-OCT-2021 (JDR)
      !>
      !>        Changed the input argument name LONG to LON for consistency
      !>        with other routines.
      !>
      !>        Edited the header to comply with NAIF standard. Removed
      !>        unnecessary $Revisions section. Added complete code example
      !>        from existing fragment.
      !>
      !>-    SPICELIB Version 3.0.2, 18-APR-2014 (BVS)
      !>
      !>        Minor edits to long error messages.
      !>
      !>-    SPICELIB Version 3.0.1, 09-SEP-2009 (EDW)
      !>
      !>        Header edits: deleted a spurious C$ marker from the
      !>        "Detailed_Output" section. The existence of the marker
      !>        caused a failure in the HTML documentation creation script.
      !>
      !>        Deleted the "Revisions" section as it contained several
      !>        identical entries from the "Version" section.
      !>
      !>        Corrected order of header sections.
      !>
      !>-    SPICELIB Version 3.0.0, 28-OCT-2006 (BVS)
      !>
      !>        Bug fix: incorrect computation of the local time for the
      !>        bodies with the retrograde rotation causing the local time to
      !>        flow backwards has been fixed. The local time for all types of
      !>        bodies now progresses as expected -- midnight, increasing AM
      !>        hours, noon, increasing PM hours, next midnight, and so on.
      !>
      !>-    SPICELIB Version 2.0.0, 03-NOV-2005 (NJB)
      !>
      !>        Bug fix: treatment of planetographic longitude has been
      !>        updated to be consistent with the SPICE planetographic/
      !>        rectangular coordinate conversion routines. The effect of
      !>        this change is that the default sense of positive longitude
      !>        for the moon is now east; also, the default sense of positive
      !>        planetographic longitude now may be overridden for any body
      !>        (see $Particulars above).
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in RMAIND calls.
      !>
      !>-    SPICELIB Version 1.1.0, 24-MAR-1998 (WLT)
      !>
      !>        The integer variable SUN was never initialized in the
      !>        previous version of the routine. Now it is set to
      !>        the proper value of 10.
      !>
      !>-    SPICELIB Version 1.0.0, 09-JUL-1997 (WLT)
      module subroutine et2lst ( ctx, et, body, lon, type, hr, mn, sc, time, ampm )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: pi, twopi
      use pepper_math, only: reclat
      use pepper_strings, only: intstr, repmi_inplace, ucase_inplace
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Epoch in seconds past J2000 epoch
      integer(ip), intent(in) :: body  !! ID-code of the body of interest
      real(wp), intent(in) :: lon  !! Longitude of surface point (RADIANS)
      character(*), intent(in) :: type  !! Type of longitude 'PLANETOCENTRIC', etc.
      integer(ip), intent(out) :: hr  !! Local hour on a "24 hour" clock
      integer(ip), intent(out) :: mn  !! Minutes past the hour
      integer(ip), intent(out) :: sc  !! Seconds past the minute
      character(*), intent(out) :: time  !! String giving local time on 24 hour clock
      character(*), intent(out) :: ampm  !! String giving time on A.M./ P.M. scale
      real(wp) :: rate_1(1)  !! one-element copy of rate (array argument)




      character(4) :: amorpm
      character(:), allocatable :: bodnam
      character(wdsize) :: frame
      character(2) :: h
      character(wdsize) :: bpmkwd
      character(2) :: m
      character(wdsize) :: mytype
      character(2) :: s
      character(1) :: kwtype

      real(wp) :: angle
      real(wp) :: hours
      real(wp) :: lat
      real(wp) :: lt
      real(wp) :: mins
      real(wp) :: mylong
      real(wp) :: range
      real(wp) :: rate
      real(wp) :: q
      real(wp) :: secnds
      real(wp) :: slat
      real(wp) :: slong
      real(wp) :: spoint ( 3 )
      real(wp) :: state  ( 6 )
      real(wp) :: tmpang
      real(wp) :: tmpsec

      integer(ip) :: frcode
      integer(ip) :: hrampm
      integer(ip) :: n

      logical :: found

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

      mytype = adjustl(type)
      call ucase_inplace ( mytype )

      if ( mytype == 'PLANETOGRAPHIC' ) then
!
!        Find planetocentric longitude corresponding to the input
!        longitude.  We first represent in rectangular coordinates
!        a surface point having zero latitude, zero altitude, and
!        the input planetographic longitude. We then find the
!        planetocentric longitude of this point.
!
!        Since PGRREC accepts a body name, map the input code to
!        a name, if possible.  Otherwise, just convert the input code
!        to a string.
!
         call body_name_of ( ctx, body, bodnam, found )

         if ( .not. found ) then
            bodnam = repeat ( ' ', 11 )
            call intstr ( body, bodnam )
         end if

!
!        Convert planetographic coordinates to rectangular coordinates.
!        All we care about here is longitude.  Set the other inputs
!        as follows:
!
!            Latitude          = 0
!            Altitude          = 0
!            Equatorial radius = 1
!            Flattening factor = 0
!
         call pgrrec ( ctx, bodnam, lon, 0.0_wp, 0.0_wp, 1.0_wp, 0.0_wp, spoint )

!
!        The output MYLONG is planetocentric longitude.  The other
!        outputs are not used.  Note that the variable RANGE appears
!        later in another RECLAT call; it's not used after that.
!
         call reclat ( spoint, range, mylong, lat )

      else if ( mytype == 'PLANETOCENTRIC' ) then

         mylong = lon

      else

         call ctx%setmsg ( 'The coordinate system ''#'' is not a ' &
         //            'recognized system of longitude.  The ' &
         //            'recognized systems are ' &
         //            '''PLANETOCENTRIC'' and ' &
         //            '''PLANETOGRAPHIC''. ' )

         call ctx%errch  ( '#', type )
         call ctx%sigerr ( 'SPICE(UNKNOWNSYSTEM)'  )
         return

      end if
!
!     It's always noon on the surface of the sun.
!
      if ( body == 10 ) then

         hr = 12
         mn = 0
         sc = 0

         time = '12:00:00'
         ampm = '12:00:00 P.M.'

         return

      end if

!
!     Get the body-fixed position of the sun.
!
      call cidfrm ( ctx, body, frcode, frame, found )

      if ( .not. found ) then

         call ctx%setmsg ( 'The body-fixed frame associated with ' &
         //            'body # could not be determined.  This ' &
         //            'information needs to be "loaded" via a ' &
         //            'frames definition kernel.  See ' &
         //            'frames.req for more details. '         )
         call ctx%errint ( '#', body                               )
         call ctx%sigerr ( 'SPICE(CANTFINDFRAME)'                  )
         return

      end if

      call spkez  ( ctx,  sun,   et,    frame, 'LT+S', body, state, lt )
      call reclat (  state, range, slong,  slat )

      angle = mylong - slong

!
!     Force the angle into the region from -PI to PI
!
      call rmaind ( ctx, angle, twopi, q, tmpang )
      angle = tmpang

      if ( angle > pi ) then
         angle = angle - twopi
      end if

!
!     Get the rotation sense of the body and invert the angle if the
!     rotation sense is retrograde. Use the BODY#_PM PCK keyword to
!     determine the sense of the body rotation.
!
      bpmkwd = 'BODY#_PM'
      call repmi_inplace ( bpmkwd, '#', body )

      call dtpool ( ctx, bpmkwd, found, n, kwtype )

      if (      .not. found &
            .or. kwtype /= 'N' &
            .or. n      <  2  ) then

         call ctx%setmsg ( 'The rotation type for the body # could ' &
         //            'not be determined because the # keyword ' &
         //            'was either not found in the POOL or ' &
         //            'or it was not of the expected type and/or ' &
         //            'dimension. This keyword is usually ' &
         //            'provided via a planetary constants ' &
         //            'kernel. See pck.req for more details. ')
         call ctx%errint ( '#', body                               )
         call ctx%errch  ( '#', bpmkwd                             )
         call ctx%sigerr ( 'SPICE(CANTGETROTATIONTYPE)'            )
         return

      else

!
!        If the rotation rate is negative, invert the angle.
!
         call gdpool ( ctx, bpmkwd, 2, 1, n, rate_1, found )
         rate = rate_1(1)

         if ( rate < 0.0_wp ) then
            angle = - angle
         end if

      end if

!
!     Convert the angle to "angle seconds" before or after local noon.
!
      secnds = 86400.0_wp * angle / twopi
      secnds = max(-43200.0_wp, min(43200.0_wp, secnds))

!
!     Get the hour, and minutes components of the local time.
!
      call rmaind ( ctx, secnds, 3600.0_wp, hours, tmpsec )
      call rmaind ( ctx, tmpsec, 60.0_wp,   mins,  secnds )
!
!     Construct the integer components of the local time.
!
      hr = 12 + int(hours)
      mn =      int(mins)
      sc =      int(secnds)
!
!     Set the A.M./P.M. components of local time.
!
      if      ( hr == 24 ) then

         hr     = 0
         hrampm = 12
         amorpm = 'A.M.'

      else if ( hr > 12 ) then

         hrampm = hr - 12
         amorpm = 'P.M.'

      else if ( hr == 12 ) then

         hrampm = 12
         amorpm = 'P.M.'

      else if ( hr == 0 ) then

         hrampm = 12
         amorpm = 'A.M.'

      else

         hrampm = hr
         amorpm = 'A.M.'

      end if

!
!     Now construct the two strings we need.
!
      hours  = real(hr, wp)
      mins   = real(mn, wp)
      secnds = real(sc, wp)

      call dpfmt ( ctx, hours,  '0x', h )
      call dpfmt ( ctx, mins,   '0x', m )
      call dpfmt ( ctx, secnds, '0x', s )

      time = h // ':' // m // ':' // s

      hours = real(hrampm, wp)

      call dpfmt ( ctx, hours,  '0x', h )

      ampm = h // ':' // m // ':' // s //  ' ' // amorpm

      return
      end subroutine et2lst

      !> Compute the points of intersection of a specified nappe of a cone
      !> and a line segment.
      !>
      !>## Detailed Input
      !>
      !>     APEX     is the apex (tip) of the cone. In this routine's
      !>              documentation, we'll consider the cone to be a
      !>              semi-infinite pyramid with circular cross-section. In
      !>              some contexts, this object is called one "nappe" of
      !>              the complete cone.
      !>
      !>     AXIS     is an axis vector of the cone.
      !>
      !>     ANGLE    is the angular separation from AXIS of the rays
      !>              comprising the cone. Let the notation
      !>
      !>                 < A, B >
      !>
      !>              denote the dot product of vectors A and B, and let
      !>
      !>                 ||A||
      !>
      !>              denote the norm of vector A. Then the cone is the set
      !>              of points
      !>
      !>                           X-APEX       AXIS
      !>                 { X:  < ----------,  -------- >  =  cos(ANGLE) }
      !>                         ||X-APEX||   ||AXIS||
      !>
      !>     ENDPT1,
      !>     ENDPT2   are endpoints of a line segment. These points
      !>              must be distinct.
      !>
      !>## Detailed Output
      !>
      !>     NXPTS    is the number of points of intersection of the input
      !>              line segment and cone.
      !>
      !>     XPT1     is the point of intersection of the segment and cone
      !>              that is closest to ENDPT1, if an intersection exists.
      !>              If there are no intersections, XPT1 is undefined.
      !>
      !>     XPT2     is the point of intersection of the segment and cone
      !>              that is farthest from ENDPT1, if two points of
      !>              intersection exist. If there are not two
      !>              intersections, XPT2 is undefined.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If AXIS is the zero vector, the error SPICE(ZEROVECTOR)
      !>         is signaled.
      !>
      !>     2)  If ANGLE is less than zero, the error SPICE(INVALIDANGLE)
      !>         is signaled.
      !>
      !>     3)  If ENDPT1 and ENDPT2 coincide, the error
      !>         SPICE(ENDPOINTSMATCH) is signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine is used by the SPICELIB DSK subsystem. In
      !>     particular, it is used to determine whether a ray contacts a
      !>     latitude boundary of a volume element in either planetocentric
      !>     latitudinal or planetodetic coordinates.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as input
      !>     (if any), the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Compute the intersection of a line segment and cone in
      !>        a simple case for which the results can easily be checked.
      !>
      !>        Let the apex of the cone be at the origin. Let the axis
      !>        of the cone lie on the +X axis. Let the angle of the cone
      !>        be 45 degrees. Let the line segment have endpoints
      !>
      !>           ENDPT1 = ( 1,   -2, sqrt(3)/2 )
      !>           ENDPT2 = ( 1,    2, sqrt(3)/2 )
      !>
      !>        We expect there to be two points of intersection:
      !>
      !>           XPT1   = ( 1, -1/2, sqrt(3)/2 )
      !>           XPT2   = ( 1,  1/2, sqrt(3)/2 )
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM INCNSG_EX1
      !>      IMPLICIT NONE
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      RPD
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         FMT1
      !>      PARAMETER           ( FMT1 = '(A,3F13.8)' )
      !>
      !>      CHARACTER*(*)         FMT2
      !>      PARAMETER           ( FMT2 = '(A,I2)' )
      !>C
      !>C     Local variables
      !>C
      !>      DOUBLE PRECISION      ANGLE
      !>      DOUBLE PRECISION      APEX   ( 3 )
      !>      DOUBLE PRECISION      AXIS   ( 3 )
      !>      DOUBLE PRECISION      ENDPT1 ( 3 )
      !>      DOUBLE PRECISION      ENDPT2 ( 3 )
      !>      DOUBLE PRECISION      SQ3
      !>      DOUBLE PRECISION      XPT1   ( 3 )
      !>      DOUBLE PRECISION      XPT2   ( 3 )
      !>
      !>      INTEGER               NXPTS
      !>
      !>C
      !>C     Set up the cone's geometric attributes.
      !>C
      !>      CALL VPACK ( 0.D0, 0.D0, 0.D0, APEX )
      !>      CALL VPACK ( 1.D0, 0.D0, 0.D0, AXIS )
      !>
      !>      ANGLE = 45.D0 * RPD()
      !>C
      !>C     Initialize the line segment's endpoints.
      !>C
      !>      SQ3 = SQRT( 3.D0  )
      !>
      !>      CALL VPACK ( 1.D0, -2.D0, SQ3/2, ENDPT1 )
      !>      CALL VPACK ( 1.D0,  2.D0, SQ3/2, ENDPT2 )
      !>C
      !>C     Find the points of intersection.
      !>C
      !>      CALL INCNSG ( APEX,   AXIS,  ANGLE, ENDPT1,
      !>     .              ENDPT2, NXPTS, XPT1,  XPT2   )
      !>
      !>      WRITE (*,*) ' '
      !>      WRITE (*,FMT1) 'Apex:        ', APEX
      !>      WRITE (*,FMT1) 'Axis:        ', AXIS
      !>      WRITE (*,FMT1) 'Angle (deg): ', ANGLE/RPD()
      !>      WRITE (*,FMT1) 'Endpoint 1:  ', ENDPT1
      !>      WRITE (*,FMT1) 'Endpoint 2:  ', ENDPT2
      !>      WRITE (*,*) ' '
      !>      WRITE (*,FMT2) 'Number of intersection points: ',
      !>     .            NXPTS
      !>      WRITE (*,*) ' '
      !>      WRITE (*,FMT1) 'Point 1:    ', XPT1
      !>      WRITE (*,FMT1) 'Point 2:    ', XPT2
      !>      WRITE (*,*) ' '
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Apex:           0.00000000   0.00000000   0.00000000
      !>        Axis:           1.00000000   0.00000000   0.00000000
      !>        Angle (deg):   45.00000000
      !>        Endpoint 1:     1.00000000  -2.00000000   0.86602540
      !>        Endpoint 2:     1.00000000   2.00000000   0.86602540
      !>
      !>        Number of intersection points:  2
      !>
      !>        Point 1:       1.00000000  -0.50000000   0.86602540
      !>        Point 2:       1.00000000   0.50000000   0.86602540
      !>
      !>## Restrictions
      !>
      !>     1)  This routine is designed to avoid arithmetic overflow in
      !>         normal cases, such as those in which the line segment is
      !>         nearly parallel to the cone. However, it is possible to cause
      !>         arithmetic overflow by using input vectors with extremely
      !>         large magnitudes.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 06-JUL-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 26-OCT-2016 (NJB)
      module subroutine incnsg ( ctx, apex, axis, angle, endpt1, endpt2, nxpts, xpt1, xpt2 )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: halfpi, pi
      use pepper_math, only: frame, mtxv, mxv, unorm, vdist, vdot, vhat
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: apex   ( 3 )  !! Apex of cone.
      real(wp), intent(in) :: axis   ( 3 )  !! Axis of cone.
      real(wp), intent(in) :: angle  !! Angle of cone.
      real(wp), intent(in) :: endpt1 ( 3 )  !! Endpoints of line segment.
      real(wp), intent(in) :: endpt2 ( 3 )  !! Endpoints of line segment.
      integer(ip), intent(out) :: nxpts  !! Number of intersection points.
      real(wp), intent(out) :: xpt1   ( 3 )  !! First intersection point, if it exists.
      real(wp), intent(out) :: xpt2   ( 3 )  !! Second intersection point, if it exists.
      real(wp), parameter :: costol = 1.0e-10_wp
      real(wp), parameter :: hsptol = 1.0e-14_wp
      real(wp) :: a
      real(wp) :: axmag
      real(wp) :: b
      real(wp) :: c
      real(wp) :: ca2
      real(wp) :: colat
      real(wp) :: cosang
      real(wp) :: coserr
      real(wp) :: dir    ( 3 )
      real(wp) :: dmag
      real(wp) :: dp1
      real(wp) :: dp2
      real(wp) :: locang
      real(wp) :: maxlat
      real(wp) :: maxp   ( 3 )
      real(wp) :: minlat
      real(wp) :: minp   ( 3 )
      real(wp) :: nrmpln ( ubpl )
      real(wp) :: off1   ( 3 )
      real(wp) :: off2   ( 3 )
      real(wp) :: plnx   ( 3 )
      real(wp) :: s1
      real(wp) :: s2
      real(wp) :: uaxis  ( 3 )
      real(wp) :: udir   ( 3 )
      real(wp) :: uoff1  ( 3 )
      real(wp) :: uoff2  ( 3 )
      real(wp) :: uuax
      real(wp) :: uv1    ( 3 )
      real(wp) :: uv2    ( 3 )
      real(wp) :: v1     ( 3 )
      real(wp) :: v1mag
      real(wp) :: v2     ( 3 )
      real(wp) :: v2mag
      real(wp) :: vtemp  ( 3 )
      real(wp) :: vtemp2 ( 3 )
      real(wp) :: w2
      real(wp) :: wu
      real(wp) :: wuax
      real(wp) :: x      ( 3 )
      real(wp) :: xoff1  ( 3 )
      real(wp) :: xoff2  ( 3 )
      real(wp) :: xform  ( 3, 3 )
      integer(ip) :: i
      integer(ip) :: n
      integer(ip) :: nplnx
      logical :: in1
      logical :: in2
      logical :: isbrck
      logical :: neg1
      logical :: neg2
      real(wp) :: y      ( 3 )
      if ( .not. allocated ( ctx%incnsg_state ) ) allocate ( ctx%incnsg_state )
      associate ( origin => ctx%incnsg_state%origin, &
                  z => ctx%incnsg_state%z )
      if ( ctx%failed() ) return

!
!     No intersection was found so far.
!
      nxpts = 0

!
!     The cone's axis vector must be non-zero.
!
      call unorm ( axis, uaxis, axmag )

      if ( axmag == 0.0_wp ) then

         call ctx%setmsg ( 'The cone''s axis vector must be non-zero ' &
         //            'but sadly, it failed to meet this criterion.' )
         call ctx%sigerr ( 'SPICE(ZEROVECTOR)'                            )
         return

      end if

!
!     The cone's angular radius must be non-negative.
!
      if ( angle < 0.0_wp ) then

         call ctx%setmsg ( 'The cone''s angular radius must be ' &
         //            ' non-negative but was # (radians).' )
         call ctx%errdp  ( '#', angle                           )
         call ctx%sigerr ( 'SPICE(INVALIDANGLE)'                )
         return

      end if

!
!     The endpoints of the segment must be distinct. Check this after
!     computing a unit direction vector for the line segment.
!
      dir = endpt2 - endpt1

      call unorm ( dir, udir, dmag )

      if ( dmag == 0.0_wp ) then

         call ctx%setmsg ( 'The distance between the segment''s ' &
         //            'endpoints was zero. First endpoint: ' &
         //            '(# # #).'                            )
         call ctx%errdp  ( '#', endpt1(1)                        )
         call ctx%errdp  ( '#', endpt1(2)                        )
         call ctx%errdp  ( '#', endpt1(3)                        )
         call ctx%sigerr ( 'SPICE(ENDPOINTSMATCH)'               )
         return

      end if

!
!     Store the cosine of the cone's angular radius. We'll treat all
!     cases with COSANG equal to 0 as though the cone is actually a
!     plane normal to the axis and containing the apex.
!
      cosang = cos( angle )
      locang = angle
!
!     We'll work with a local axis that has angular separation of
!     no more than pi/2 from the nappe.
!
      if ( cosang < 0.0_wp ) then

         cosang   = - cosang
         locang   =   pi - angle

         uaxis(1) = - uaxis(1)
         uaxis(2) = - uaxis(2)
         uaxis(3) = - uaxis(3)

      end if

!
!     Compute the offsets of the endpoints of the segment from
!     the cone's apex.
!
      off1 = endpt1 - apex
      off2 = endpt2 - apex

!
!     Deal with some of the simple cases first.
!
      call vhat ( off1, uoff1 )
      call vhat ( off2, uoff2 )

      dp1  = vdot( uoff1, uaxis )
      dp2  = vdot( uoff2, uaxis )

!
!     The given axis is inside the nappe defined by the angular radius.
!
!     There's no intersection if both endpoints are in the interior of
!     the nappe of the cone (since the nappe is convex).
!
      in1  = dp1 >= cosang
      in2  = dp2 >= cosang
!
!     If the line segment lies on the far side of the plane that
!     contains the apex and is orthogonal to the axis, there's no
!     intersection.
!
      neg1 = dp1 < 0.0_wp
      neg2 = dp2 < 0.0_wp

      if (      ( in1  .and. in2  ) &
           .or. ( neg1 .and. neg2 ) ) then
!
!        The segment is in the interior of the cone or
!        on the far side of the plane.
!
         nxpts = 0

         return

      end if

!
!     Here's where we handle the half-space case.
!
      if ( abs(cosang) < hsptol ) then
!
!        See whether the ray emanating from the first endpoint and
!        having direction UDIR hits the plane normal to the axis and
!        containing the apex. We'll call this plane NRMPLN.
!
!        NVP2PL can signal an error only if the input axis is the
!        zero vector. We've ensured that it isn't.
!
         call nvp2pl ( ctx, uaxis,  apex, nrmpln )
         call inrypl ( ctx, endpt1, udir, nrmpln, nplnx, plnx )

!
!        If the ray doesn't hit the plane, we're done. Otherwise,
!        check the intercept.
!
         if ( nplnx == 1 ) then
!
!           The ray does hit the plane. If the intersection is on the
!           line segment, we have a solution.
!
            if ( vdist(plnx, endpt1) <= dmag ) then
!
!              The intercept is not further along the ray than the
!              second endpoint. It's a valid solution.
!
               nxpts = 1
               xpt1 = plnx

            end if

         end if
!
!        This is the end of the half-space case.
!
         return

      end if

!
!     At this point we've disposed of the trivial cases. We'll
!     set up a quadratic equation for the intersection of the
!     line segment with the surface of the cone's nappe.
!
!     Due to round-off errors, the solution of the quadratic may
!     either be inaccurate or may not be found at all. We'll
!     examine the solutions we find and solve the problem by
!     an alternate method if necessary. However, the quadratic
!     method is fast, so we give it priority.
!
!     The equation of a ray starting at ENDPT1 and having unit
!     direction vector UDIR is
!
!        RAY  = { ENDPT1 + s*UDIR, s >= 0 }                          (1)
!
!     The equation of the nappe of the cone is
!
!        CONE = { X: < X - APEX, UAXIS > = ||X-APEX|| * cos(ANGLE) } (2)
!
!     where ANGLE is the angular radius of the cone and UAXIS is the
!     unit axis vector. Substituting the right hand side expression of
!     (1) for X in equation (2) and squaring both sides yields a
!     quadratic equation for S. We'll derive the coefficients of the
!     equation below.
!
!     Let
!
!        Q  = X - APEX
!        W  = ENDPT1 - APEX
!        U  = UDIR
!        CA = cos(ANGLE)
!
!     We can translate the cone and ray by -APEX, and (1) and (2)
!     can be re-written as
!
!        RAY  = { W + s*U, s >= 0 }                                  (3)
!
!        CONE = { Q: < Q, UAXIS > = ||Q|| * cos(ANGLE) }             (4)
!
!        Substituting the ray expression for Q, we obtain
!
!           < W + s*U, UAXIS > = ||W+s*U|| * CA                      (5)
!
!        and squaring both sides yields
!
!                      2                                      2   2
!             <W,UAXIS>  + 2*<W,UAXIS>*<U,UAXIS>*s + <U,UAXIS> * s
!
!                    2                2       2
!           = ( ||W||  + 2*<W,U>*s + s  ) * CA                       (6)
!
!       Collecting coefficients of powers of s, we have
!
!                         2     2     2
!              ( <U,UAXIS>  - CA ) * s
!
!                                            2
!            + 2 * ( <W,UAXIS>*<U,UAXIS> - CA * <W,U> ) * s
!
!                       2        2    2
!            + <W,UAXIS>  - ||W|| * CA
!
!         =  0                                                       (7)
!
!      Before continuing, we observe that the only non-unit vector
!      in (7) is W. So the coefficients in (7) have no possibility
!      of overflowing unless the vertex of the ray is very far from
!      the apex of the cone.
!
!      W has been computed above as OFF1.
!
!         [ Consider adding check on OFF1 here. ]
!
!     Intermediate values:
!
      uuax = vdot( udir, uaxis )
      wuax = vdot( off1, uaxis )
      wu   = vdot( off1, udir  )
      w2   = vdot( off1, off1  )
      ca2  = cosang * cosang

!
!     Quadratic coefficients:
!
      a    = ( uuax * uuax ) - ca2

      b    = 2 * (  ( wuax * uuax ) - ( ca2 * wu )  )

      c    = ( wuax * wuax ) - ( w2 * ca2 )

!
!     We're not interested in solutions that lie outside
!     of the line segment. The length of the segment is
!     DMAG.
!
!     Solve the equation, using DMAG as an upper bound
!     on the magnitude of the roots.
!
      call zzcnquad ( ctx, a, b, c, dmag, n, s1, s2 )

!
!     Compute the possible intersection points and test them
!     to make sure they really are solutions.
!
      if ( n > 0 ) then
!
!        Start with the solution closest to the ray's vertex.
!        Compute XPT1 and make sure it's on the correct nappe
!        of the cone.
!
         if ( s1 >= 0.0_wp ) then

            xpt1(1) = endpt1(1) + s1*udir(1)
            xpt1(2) = endpt1(2) + s1*udir(2)
            xpt1(3) = endpt1(3) + s1*udir(3)

            v1 = xpt1 - apex

!
!           See whether V1 is on the cone.
!
            call unorm ( v1, uv1, v1mag )

            if ( v1mag > 0.0_wp ) then

               coserr = abs( vdot(uv1,uaxis) - cosang )
            else
               coserr = 0.0_wp
            end if

            if (      ( v1mag  == 0.0_wp   ) &
                 .or. ( coserr < costol ) ) then
!
!              The root is on the cone (on the apex if V1MAG is zero).
!
!              We accept this root. Update NXPTS. Note that this is
!              not necessarily the final value of NXPTS; that
!              depends on the validity of the second root.

               nxpts = 1

            end if

         end if

         if ( n == 2 ) then
!
!           Check the second root.
!
            if ( s2 >= 0.0_wp ) then

               xpt2(1) = endpt1(1) + s2*udir(1)
               xpt2(2) = endpt1(2) + s2*udir(2)
               xpt2(3) = endpt1(3) + s2*udir(3)

               v2 = xpt2 - apex

!
!              See whether V2 is on the cone.
!
               call unorm ( v2, uv2, v2mag )

               if ( v2mag > 0.0_wp ) then

                  coserr = abs( vdot(uv2,uaxis) - cosang )
               else
                  coserr = 0.0_wp
               end if

               if (      ( v2mag  == 0.0_wp   ) &
                    .or. ( coserr < costol ) ) then
!
!                 The root is on the cone (on the apex if V2MAG is
!                 zero).
!
!                 We accept this root.
!
                  nxpts = nxpts + 1

                  if ( nxpts == 1 ) then
!
!                    This is the only valid root; overwrite XPT1.
!
                     xpt1 = xpt2

                  end if

               end if

            end if

         end if

      end if

!
!     We're not done yet. If we have fewer roots than we should, we'll
!     need to solve the problem by an alternate method.
!
!     If we have two roots, we're in good shape. Otherwise we must
!     determine how many roots should be found.
!
      if ( nxpts < 2 ) then
!
!        We must determine the expected number of roots, and if
!        we didn't come up with them, we must find the roots
!        by an alternate method.
!
!        We'll examine the containment of the endpoints within the
!        cone.
!
!        The case where both endpoints are inside the cone was handled
!        earlier.
!
!        If one endpoint is inside the cone and one is outside,
!        we expect to have one root.
!
         if (     ( in1 .and. ( .not. in2 ) ) &
             .or. ( in2 .and. ( .not. in1 ) )  ) then
!
!           There's supposed to be one root. If we found none, find one
!           now.
!
            if ( nxpts == 0 ) then
!
!              ZZCXBRUT signals an error if the axis is the zero
!              vector, but not otherwise. We've already ruled out this
!              situation. Therefore, we don't check in before the
!              following call.
!
               call zzcxbrut ( ctx, apex,   uaxis,  locang, &
                               endpt1, endpt2, xpt1,  isbrck )

               if ( isbrck ) then
!
!                 As long as the root was bracketed, XPT1 is a
!                 solution.
!
                  nxpts = 1

               end if

            end if

         else

!
!           Both endpoints are outside the cone. We could have zero to
!           two roots. If the minimum angular separation of the segment
!           from the axis is less than ANGLE, we expect to find two
!           roots; if it's equal to ANGLE, we expect to find one, and
!           if it's greater than ANGLE, none.
!
!           We'll transform OFF1 and OFF2 into a reference frame in
!           which angular separation from the axis is equivalent to
!           colatitude. Then we'll find the maximum latitude attained
!           on the segment.
!
!           We'll count the roots we find, so we'll start at zero.
!
            nxpts = 0

            call frame ( uaxis, x, y )

            do i = 1, 3

               xform(1,i) = x(i)
               xform(2,i) = y(i)
               xform(3,i) = uaxis(i)

            end do

            call mxv ( xform, off1, xoff1 )
            call mxv ( xform, off2, xoff2 )

            call zzsglatx ( ctx, xoff1, xoff2, minlat, minp, maxlat, maxp )

            if ( ctx%failed() ) return

!
!           COLAT is the colatitude of the point of maximum latitude.
!
            colat = halfpi - maxlat

            if ( colat < locang ) then
!
!              MAXP is inside the cone. There should be an intersection
!              on the segment between XOFF1 and MAXP and another
!              between MAXP and XOFF2.
!
               call zzcxbrut ( ctx, origin, z,    locang, &
                               xoff1,  maxp, vtemp,  isbrck )

               if ( isbrck ) then
!
!                 Convert VTEMP to the original frame, then translate
!                 it so that it's represented as an offset from the
!                 origin.
!
                  call mtxv ( xform,  vtemp, vtemp2 )
                  xpt1 = vtemp2 + apex

                  nxpts = 1

               end if

               call zzcxbrut ( ctx, origin, z,     locang, &
                               maxp,   xoff2, vtemp,  isbrck )

               if ( isbrck ) then
!
!                 Convert VTEMP to the original frame, then translate
!                 it so that it's represented as an offset from the
!                 origin.
!
                  call mtxv ( xform,  vtemp, vtemp2 )
                  xpt2 = vtemp2 + apex

                  if ( nxpts == 1 ) then
!
!                    Both roots are valid.
!
                     nxpts = 2

                  else
!
!                    The second root is the only valid root. Move it
!                    into XPT1.
!
                     xpt1 = xpt2

                     nxpts = 1

                  end if

               end if

            else if ( colat == locang ) then
!
!              The root corresponds to a point of tangency of
!              the segment and cone. This occurs at the point
!              having maximum latitude: MAXP.
!
               xpt1 = maxp

               nxpts = 1

!
!           Note that if COLAT > LOCANG, there are no roots.
!
            end if

         end if
!
!        This is the end of portion of the "brute force" branch in
!        which both endpoints are outside the cone.
!
      end if

!
!     NXPTS  has been set.
!
!     If NXPTS is 1, then XPT1 is set.
!
!     If NXPTS is 2, then both XPT1 and XPT2 are set.
!

      return
      end associate
      end subroutine incnsg

      !> Scan a string from a specified starting position for the
      !> end of a number.
      !>
      !>## Detailed Input
      !>
      !>     STRING   is any character string.
      !>
      !>     FIRST    is the location in the string to beginning scanning
      !>              for a  number. It is assumed that the number begins
      !>              at FIRST.
      !>
      !>## Detailed Output
      !>
      !>     LAST     is the last character at or after FIRST such that
      !>              the substring STRING(FIRST:LAST) is a number.
      !>              If there is no such substring, LAST will be returned
      !>              with the value FIRST-1.
      !>
      !>     NCHAR    is the number of characters in the number
      !>              that begins at FIRST and ends at last. If there
      !>              is no such string NCHAR will be given the value 0.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     Error free.
      !>
      !>     1)  If FIRST is beyond either end of the string, then LAST will be
      !>         returned with the value FIRST-1 and NCHAR will be returned
      !>         with the value 0.
      !>
      !>     2)  If STRING(FIRST:FIRST) is not part of a number
      !>         then LAST will be returned with the value FIRST-1 and NCHAR
      !>         will be returned with the value 0.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine allows you to scan forward in a string to locate
      !>     a number that begins on the input character FIRST. Note
      !>     that all decimal numbers are included in the list of numbers.
      !>     The main difference between decimal numbers and numbers is that
      !>     numbers may have an exponential expression attached (i.e. the
      !>     exponent character 'e','E','d' or 'D' followed by an signed
      !>     integer).
      !>
      !>## Examples
      !>
      !>     Suppose you believe that a string has the form
      !>
      !>        X%Y%Z
      !>
      !>     where X, Y, and Z are decimal numbers of some unknown
      !>     length and % stands for some non-numeric character. You could
      !>     use this routine to locate the numbers in the
      !>     string as shown below. We'll keep track of the beginning and
      !>     ending of the numbers in the integer arrays B and E.
      !>
      !>     FIRST = 1
      !>     I     = 0
      !>
      !>     DO WHILE ( FIRST .LT. LEN(STRING) )
      !>
      !>        CALL LX4NUM ( STRING, FIRST, LAST, NCHAR )
      !>
      !>        IF ( NCHAR .GT. 0 ) THEN
      !>
      !>           I     = I    + 1
      !>           B(I)  = FIRST
      !>           E(I)  = LAST
      !>           FIRST = LAST + 2
      !>
      !>        ELSE
      !>
      !>           FIRST = FIRST + 1
      !>
      !>        END IF
      !>
      !>     END DO
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 04-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Fixed return value for LAST in $Exceptions section entry #1.
      !>
      !>-    SPICELIB Version 1.0.0, 12-JUL-1994 (WLT)
      module subroutine lx4num ( ctx, string, first, last, nchar )
      use pepper_kinds, only: ip
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: string  !! any character string
      integer(ip), intent(in) :: first  !! first character to scan from in STRING
      integer(ip), intent(out) :: last  !! last character that is part of a number
      integer(ip), intent(out) :: nchar  !! number of characters in the number.

      integer(ip) :: f
      integer(ip) :: i
      integer(ip) :: l
      integer(ip) :: n
      integer(ip) :: temp

      last  = first - 1
      l     = len ( string )
!
!     If start is beyond the ends of the string, we  can quit now.
!
      if ( first < 1 .or. first > l ) then
         nchar = 0
         return
      end if
!
!     If this is a number, it must begin with a decimal number
!     substring.
!
      call lx4dec ( ctx, string, first, last, nchar )

      if ( nchar > 0 .and. last < l ) then

         f = last + 1
         i = ichar ( string(f:f) )
!
!        See if we have an exponent.
!
         if (      i == ichar('e') &
              .or. i == ichar('E') &
              .or. i == ichar('D') &
              .or. i == ichar('d') ) then
!
!           Starting after the exponent character see
!           if we have a signed integer.
!
            f = f + 1

            call lx4sgn ( ctx, string, f, temp, n )
!
!           If there was a signed integer, N will be bigger than
!           zero and TEMP will point to the last character of
!           the number.  Otherwise we just fall through and leave
!           LAST and NCHAR alone.
!
            if ( n > 0 ) then

               last  = temp
               nchar = last + 1 - first

            end if

         end if

      end if

      return
      end subroutine lx4num

      !> Read the next variable from a SPICE ASCII kernel file into a
      !> double precision symbol table.
      !>
      !>## Detailed Input
      !>
      !>     TABSYM,
      !>     TABPTR,
      !>     TABVAL   are the components of a double precision symbol table. On
      !>              input, the table may or may not contain any variables.
      !>
      !>## Detailed Output
      !>
      !>     TABSYM,
      !>     TABPTR,
      !>     TABVAL   on output, contains the name and values of the next
      !>              variable in kernel file. Depending on the assignment
      !>              directive, the values in the file may replace or augment
      !>              any existing values.
      !>
      !>      NAME    is the name of the variable. NAME is blank if no variable
      !>              is read.
      !>
      !>      EOF     is .TRUE. when the end of the kernel file has been
      !>              reached, and is .FALSE. otherwise. The kernel file is
      !>              closed automatically when the end of the file is reached.
      !>
      !>## Parameters
      !>
      !>     LINLEN   is the maximum length of a line in the kernel file.
      !>
      !>## Exceptions
      !>
      !>     1)  If an error occurs parsing a date from the kernel file, the
      !>         error SPICE(DATEEXPECTED) is signaled.
      !>
      !>     2)  If an error occurs parsing a numeric value from the kernel
      !>         file, the error SPICE(NUMBEREXPECTED) is signaled.
      !>
      !>## Files
      !>
      !>     RDKVAR reads from the file most recently opened by RDKNEW.
      !>
      !>## Particulars
      !>
      !>     None.
      !>
      !>## Examples
      !>
      !>     In the following example, RDKNEW and RDKVAR are used to read
      !>     the contents of two kernel files into a single symbol table.
      !>     First, the table is cleared.
      !>
      !>         CALL SCARDC ( 0, TABSYM )
      !>         CALL SCARDI ( 0, TABPTR )
      !>         CALL SCARDD ( 0, TABVAL )
      !>
      !>     Next, the files are opened and read individually.
      !>
      !>         DO I = 1, 2
      !>            CALL RDKNEW ( KERNEL(I), EOF )
      !>
      !>            DO WHILE ( .NOT. EOF )
      !>               CALL RDKVAR ( TABSYM, TABPTR, TABVAL, NAME, EOF )
      !>            END DO
      !>         END DO
      !>
      !>     Let the files KERNEL(1) and KERNEL(2) contain
      !>
      !>         ===========================================================
      !>
      !>         \begindata
      !>         DELTA_T_A       =   32.184
      !>         K               =    1.657D-3
      !>         ORBIT_ECC       =    1.671D-2
      !>         MEAN_ANOM       = (  6.239996D0,  1.99096871D-7 )
      !>
      !>         ===========================================================
      !>
      !>     and
      !>
      !>         ===========================================================
      !>         \begindata
      !>          K               =    0.0D0
      !>         ===========================================================
      !>
      !>     respectively. Then the contents of the symbol table are
      !>
      !>          DELTA_T_A  -->   32.184
      !>          K          -->    0.0D0
      !>          MEAN_ANOM  -->    6.239996D0
      !>                            1.99096871D-7
      !>          ORBIT_ECC  -->    1.671D-2
      !>
      !>     In particular, the value of K read from the second file replaces
      !>     the value read from the first file.
      !>
      !>## Restrictions
      !>
      !>     1)  The input file must be opened and initialized by RDKNEW prior
      !>         to the first call to RDKVAR.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>     I.M. Underwood     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 17-JUN-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.1.0, 10-MAR-1992 (WLT)
      !>
      !>        Changed the length of the local character variable ERROR so
      !>        that it would always have a length greater than the lengths of
      !>        the character string values placed into it.
      !>
      !>-    SPICELIB Version 1.0.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.0.0, 31-JAN-1990 (IMU)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 10-MAR-1992 (WLT)
      !>
      !>        Changed the length of the local character variable ERROR so
      !>        that it would always have a length greater than the lengths of
      !>        the character string values placed into it.
      !>
      !>        The length of the character variable ERROR was changed from 30
      !>        to 80.
      !>
      !>-    SPICELIB Version 1.0.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>-    Beta Version 2.0.0, 23-OCT-1989 (HAN)
      !>
      !>        Added a test to FAILED in the main DO-loop to prevent
      !>        infinite looping. If the error mode was set to 'RETURN'
      !>        and an error occurred, the same line could be processed
      !>        forever.
      !>
      !>-    Beta Version 1.1.0, 13-JAN-1989 (IMU)
      !>
      !>        Variable name may now take up an entire line. The previous
      !>        maximum length (32 characters) was tied to the known length
      !>        used by POOL. That length is now parameterized. Rather than
      !>        have two parameters, which could get out of synch, RDKVAR
      !>        now assumes that a variable name can be as long as an input
      !>        line.
      module subroutine rdkvar ( ctx, tabsym, tabptr, tabval, name, eof )
      use pepper_kinds, only: ip, wp
      use pepper_strings, only: nparsd, nextwd_inplace, replch_inplace
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: lbcell = -5
      character(*), intent(inout) :: tabsym     ( lbcell:* )  !! Symbol table.
      integer(ip), intent(inout) :: tabptr     ( lbcell:* )  !! Symbol table.
      real(wp), intent(inout) :: tabval     ( lbcell:* )  !! Symbol table.
      character(*), intent(out) :: name  !! Name of the variable.
      logical, intent(out) :: eof  !! End of file indicator.


      integer(ip), parameter :: linlen = 80

      character(1), parameter :: comma = ','



      character(1), parameter :: rparen = ')'

      character(linlen) :: line
      character(linlen) :: varnam
      character(3) :: dirctv
      character(6) :: status

      character(30) :: cvalue
      real(wp) :: dvalue
      integer(ip) :: i

      character(80) :: error

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     No variable yet.
!
      name  = ' '

!
!     No parsing error has occurred yet.
!
      error = ' '

!
!     Get the next data line. Unless something is terribly wrong,
!     this will begin a new variable definition. We have to read
!     the whole variable, unless we luck out and get an error, in
!     which case we can quit.
!
      status = 'BEGIN'

      do while ( ( status /= 'DONE' ) .and. ( .not. ctx%failed() ) )

         call rdkdat ( ctx, line, eof )

         if ( eof ) return

!
!        Replace commas with blanks. We make no distinctions between
!        the two.
!
         call replch_inplace ( line, comma, blank )

!
!        The first word on the first line should be the name of a
!        variable. The second word should be a directive: = or +=.
!
         if ( status == 'BEGIN' ) then

            call nextwd_inplace ( line, varnam )
            call nextwd_inplace ( line, dirctv )

!
!           If this is replacement (=) and not an addition (+=),
!           delete the values currently associated with the variable.
!           They will be replaced later.
!
            if ( dirctv == '=' ) then
               call sydeld ( ctx, varnam, tabsym, tabptr, tabval )
            end if

!
!           If this is a vector, the next thing on the line will be a
!           left parenthesis. Otherwise, assume that this is a scalar.
!           If it's a vector, get the first value. If it's a scalar,
!           plant a bogus right parenthesis, to make the following loop
!           terminate after one iteration.
!
            call nextwd_inplace ( line, cvalue )

            if ( cvalue == lparen ) then
               call nextwd_inplace ( line, cvalue )
            else
               line = rparen
            end if

!
!        For subsequent lines, treat everything as a new value.
!
         else

            call nextwd_inplace ( line, cvalue )

         end if

!
!        We have a value anyway. Store it in the table.
!
!        Keep going until the other shoe (the right parenthesis)
!        drops, or until the end of the line is reached.
!
!        Dates begin with @; anything else is presumed to be a number.
!
         do while ( cvalue /= rparen  .and.  cvalue /= blank )

            if ( cvalue(1:1) == '@' ) then

               call tparse ( ctx, cvalue(2: ), dvalue, error )

               if ( error /= ' ' ) then
                  error  =  'Encountered : ' // cvalue(2: )
                  call ctx%setmsg ( error    )
                  call ctx%sigerr ( 'SPICE(DATEEXPECTED)' )
                  return
               end if

            else

               call nparsd ( cvalue, dvalue, error, i )

               if ( error /= ' ' ) then
                  error =  'Encountered : ' // cvalue
                  call ctx%setmsg ( error    )
                  call ctx%sigerr ( 'SPICE(NUMBEREXPECTED)' )
                  return
               end if

            end if

            call syenqd ( ctx, varnam, dvalue, tabsym, &
                                          tabptr, &
                                          tabval )

            call nextwd_inplace ( line, cvalue )

         end do

         if ( cvalue == rparen ) then
            status = 'DONE'
         else
            status = 'INVAR'
         end if

      end do

!
!     Return the name of the variable, but only if everything went okay.
!
      name = varnam

      return
      end subroutine rdkvar

      !> Transform a state between coordinate systems.
      !>
      !>## Detailed Input
      !>
      !>     ISTATE   is a state vector in the input ICOSYS coordinate
      !>              system representing position and velocity.
      !>
      !>              All angular measurements must be in radians.
      !>
      !>              Note: body radii values taken from the kernel
      !>              pool are used when converting to or from geodetic or
      !>              planetographic coordinates. It is the user's
      !>              responsibility to verify the distance inputs are in
      !>              the same units as the radii in the kernel pool,
      !>              typically kilometers.
      !>
      !>     ICOSYS   is the name of the coordinate system that the input
      !>              state vector ISTATE is currently in.
      !>
      !>              ICOSYS may be any of the following:
      !>
      !>                 'RECTANGULAR'
      !>                 'CYLINDRICAL'
      !>                 'LATITUDINAL'
      !>                 'SPHERICAL'
      !>                 'GEODETIC'
      !>                 'PLANETOGRAPHIC'
      !>
      !>              Leading spaces, trailing spaces, and letter case
      !>              are ignored. For example, ' cyLindRical  ' would be
      !>              accepted.
      !>
      !>     OCOSYS   is the name of the coordinate system that the state
      !>              should be converted to.
      !>
      !>              Please see the description of ICOSYS for details.
      !>
      !>     BODY     is the name or NAIF ID of the body associated with the
      !>              planetographic or geodetic coordinate system.
      !>
      !>              If neither of the coordinate system choices are
      !>              geodetic or planetographic, BODY is ignored. It may
      !>              be a blank string.
      !>
      !>              Examples of accepted body names or IDs are:
      !>
      !>                 'Earth'
      !>                 '399'
      !>
      !>              Leading spaces, trailing spaces, and letter case are
      !>              ignored.
      !>
      !>## Detailed Output
      !>
      !>     OSTATE   is the state vector that has been converted to the
      !>              output coordinate system OCOSYS.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If either the input or output coordinate system is not
      !>         recognized, the error SPICE(COORDSYSNOTREC) is signaled.
      !>
      !>     2)  If the input body name cannot be converted to a NAIF ID
      !>         (applies to geodetic and planetographic coordinate
      !>         systems), the error SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     3)  If the input state ISTATE is not valid, meaning the position
      !>         but not the velocity is along the z-axis, the error
      !>         SPICE(INVALIDSTATE) is signaled.
      !>
      !>         Note: If both the input position and velocity are along
      !>         the z-axis and the output coordinate system is not
      !>         rectangular, the velocity can still be calculated even
      !>         though the Jacobian is undefined. This case will not
      !>         signal an error. An example of the input position and
      !>         velocity along the z-axis is below.
      !>
      !>                       Term    Value
      !>                       -----   ------
      !>                         x       0
      !>                         y       0
      !>                         z       z
      !>                       dx/dt     0
      !>                       dy/dt     0
      !>                       dz/dt   dz_dt
      !>
      !>     4)  If either the input or output coordinate system is
      !>         geodetic or planetographic and at least one of the body's
      !>         radii is less than or equal to zero, the error
      !>         SPICE(INVALIDRADIUS) is signaled.
      !>
      !>     5)  If either the input or output coordinate system is
      !>         geodetic or planetographic and the difference of the
      !>         equatorial and polar radii divided by the equatorial radius
      !>         would produce numeric overflow, the error
      !>         SPICE(INVALIDRADIUS) is signaled.
      !>
      !>     6)  If the product of the Jacobian and velocity components
      !>         may lead to numeric overflow, the error
      !>         SPICE(NUMERICOVERFLOW) is signaled.
      !>
      !>     7)  If radii for BODY are not found in the kernel pool, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     8)  If the size of the BODY radii kernel variable is not three,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     9)  If any of the three BODY radii is less-than or equal to zero,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     10) If body's equatorial radii are not equal and either the
      !>         input or output coordinate system is geodetic or
      !>         planetographic, the error SPICE(NOTSUPPORTED) is signaled.
      !>
      !>## Files
      !>
      !>     SPK, PCK, CK, and FK kernels may be required.
      !>
      !>     If the input or output coordinate systems are either geodetic or
      !>     planetographic, a PCK providing the radii of the body
      !>     name BODY must be loaded via FURNSH.
      !>
      !>     Kernel data are normally loaded once per program run, NOT every
      !>     time this routine is called.
      !>
      !>## Particulars
      !>
      !>     Input Order
      !>     -------------------------------------------
      !>
      !>     The input and output states will be structured by the
      !>     following descriptions.
      !>
      !>     For rectangular coordinates, the state vector is the following
      !>     in which X, Y, and Z are the rectangular position components and
      !>     DX, DY, and DZ are the time derivatives of each position
      !>     component.
      !>
      !>             ISTATE = ( X, Y, Z, DX, DY, DZ )
      !>
      !>     For cylindrical coordinates, the state vector is the following
      !>     in which R is the radius, LONG is the longitudes, Z is the
      !>     height, and DR, DLONG, and DZ are the time derivatives of each
      !>     position component.
      !>
      !>             ISTATE = ( R, LONG, Z, DR, DLONG, DZ )
      !>
      !>     For latitudinal coordinates, the state vector is the following
      !>     in which R is the radius, LONG is the longitude, LAT is the
      !>     latitude, and DR, DLONG, and DLAT are the time derivatives of
      !>     each position component.
      !>
      !>             ISTATE = ( R, LONG, LAT, DR, DLONG, DLAT )
      !>
      !>     For spherical coordinates, the state vector is the following in
      !>     which R is the radius, COLAT is the colatitude, LONG is the
      !>     longitude, and DR, DCOLAT, and DLONG are the time derivatives of
      !>     each position component.
      !>
      !>             ISTATE = ( R, COLAT, LONG, DR, DCOLAT, DLONG )
      !>
      !>     For geodetic coordinates, the state vector is the following in
      !>     which LONG is the longitude, LAT is the latitude, ALT is the
      !>     altitude, and DLONG, DLAT, and DALT are the time derivatives of
      !>     each position component.
      !>
      !>             ISTATE = ( LONG, LAT, ALT, DLONG, DLAT, DALT )
      !>
      !>     For planetographic coordinates, the state vector is the
      !>     following in which LONG is the longitude, LAT is the latitude,
      !>     ALT is the altitude, and DLONG, DLAT, and DALT are the time
      !>     derivatives of each position component.
      !>
      !>             ISTATE = ( LONG, LAT, ALT, DLONG, DLAT, DALT )
      !>
      !>     Input Boundaries
      !>     -------------------------------------------
      !>
      !>     There are intervals the input angles must fall within if
      !>     the input coordinate system is not rectangular. These
      !>     intervals are provided below.
      !>
      !>        Input variable    Input meaning   Input interval [rad]
      !>        --------------    -------------   ------------------------
      !>            LONG           Longitude        0     <= LONG  <  2*pi
      !>            LAT            Latitude        -pi/2  <= LAT   <= pi/2
      !>            COLAT          Colatitude       0     <= COLAT <= pi
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Find the apparent state of Phoebe as seen by CASSINI in the
      !>        J2000 frame at 2004 Jun 11 19:32:00. Transform the state
      !>        from rectangular to latitudinal coordinates. For verification,
      !>        transform the state back from latitudinal to rectangular
      !>        coordinates.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: xfmsta_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                        Contents
      !>              ---------                        --------
      !>              pck00010.tpc                     Planet orientation and
      !>                                               radii
      !>              naif0012.tls                     Leapseconds
      !>              041014R_SCPSE_01066_04199.bsp    CASSINI, planetary and
      !>                                               Saturn Satellite
      !>                                               ephemeris
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'naif0012.tls',
      !>                                  '041014R_SCPSE_01066_04199.bsp',
      !>                                  'pck00010.tpc'                 )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM XFMSTA_EX1
      !>      IMPLICIT NONE
      !>C
      !>C     Local parameters
      !>C
      !>C     METAKR is the meta-kernel's filename.
      !>C
      !>      CHARACTER*(*)         METAKR
      !>      PARAMETER           ( METAKR = 'xfmsta_ex1.tm' )
      !>
      !>      CHARACTER*(*)         FORM
      !>      PARAMETER           ( FORM = '(F16.6, F16.6, F16.6)' )
      !>
      !>C
      !>C     Local variables
      !>C
      !>C     STAREC is the state of Phoebe with respect to CASSINI in
      !>C     rectangular coordinates. STALAT is the state rotated into
      !>C     latitudinal coordinates. STREC2 is the state transformed
      !>C     back into rectangular coordinates from latitudinal.
      !>C
      !>      DOUBLE PRECISION      STAREC (6)
      !>      DOUBLE PRECISION      STALAT (6)
      !>      DOUBLE PRECISION      STREC2 (6)
      !>
      !>C
      !>C     ET is the ephemeris time (TDB) corresponding to the
      !>C     observation.
      !>C
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      LT
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     The required kernels must be loaded.
      !>C
      !>      CALL FURNSH ( METAKR )
      !>
      !>C
      !>C     Calculate the state at 2004 Jun 11 19:32:00 UTC.
      !>C
      !>      CALL STR2ET ( '2004-JUN-11-19:32:00', ET )
      !>
      !>C
      !>C     Calculate the apparent state of Phoebe as seen by
      !>C     CASSINI in the J2000 frame.
      !>C
      !>      CALL SPKEZR ( 'PHOEBE',  ET, 'IAU_PHOEBE', 'LT+S',
      !>     .              'CASSINI', STAREC, LT              )
      !>
      !>C
      !>C     Transform the state from rectangular to latitudinal.
      !>C     Notice that since neither the input nor output
      !>C     coordinate frames are 'geodetic' or 'planetographic',
      !>C     the input for the body name is a blank string.
      !>C
      !>      CALL XFMSTA ( STAREC, 'RECTANGULAR', 'LATITUDINAL', ' ',
      !>     .              STALAT )
      !>
      !>C
      !>C     Transform the state back to rectangular from latitudinal
      !>C     for verification. This result should be very similar to
      !>C     STAREC.
      !>C
      !>      CALL XFMSTA ( STALAT, 'LATITUDINAL', 'RECTANGULAR',' ',
      !>     .              STREC2 )
      !>
      !>C
      !>C     Report the results.
      !>C
      !>      WRITE (*,*)    ' '
      !>      WRITE (*,*)    'Phoebe as seen by CASSINI - rectangular'
      !>      WRITE (*,*)    '  Position [km]:'
      !>      WRITE (*,FORM) (STAREC(I), I = 1, 3)
      !>      WRITE (*,*)    '  Velocity [km/s]:'
      !>      WRITE (*,FORM) (STAREC(I), I = 4, 6)
      !>      WRITE (*,*)    ' '
      !>      WRITE (*,*)    'Phoebe as seen by CASSINI - latitudinal'
      !>      WRITE (*,*)    '  Position [km, rad, rad]:'
      !>      WRITE (*,FORM) (STALAT(I), I = 1, 3)
      !>      WRITE (*,*)    '  Velocity [km/s, rad/s, rad/s]:'
      !>      WRITE (*,FORM) (STALAT(I), I = 4, 6)
      !>      WRITE (*,*)    ' '
      !>      WRITE (*,*)    'Verification: '
      !>      WRITE (*,*)    'Phoebe as seen by CASSINI - rectangular'
      !>      WRITE (*,*)    '  Position [km]:'
      !>      WRITE (*,FORM) (STREC2(I), I = 1, 3)
      !>      WRITE (*,*)    '  Velocity [km/s]:'
      !>      WRITE (*,FORM) (STREC2(I), I = 4, 6)
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Phoebe as seen by CASSINI - rectangular
      !>           Position [km]:
      !>            -2059.271283     -942.128329      -95.837672
      !>           Velocity [km/s]:
      !>                3.910113       -4.228139       -1.526561
      !>
      !>         Phoebe as seen by CASSINI - latitudinal
      !>           Position [km, rad, rad]:
      !>             2266.580876       -2.712515       -0.042296
      !>           Velocity [km/s, rad/s, rad/s]:
      !>               -1.730462        0.002416       -0.000706
      !>
      !>         Verification:
      !>         Phoebe as seen by CASSINI - rectangular
      !>           Position [km]:
      !>            -2059.271283     -942.128329      -95.837672
      !>           Velocity [km/s]:
      !>                3.910113       -4.228139       -1.526561
      !>
      !>     2) Transform a given state from cylindrical to planetographic
      !>        coordinates with respect to Earth.
      !>
      !>        Use the PCK kernel below to load the required triaxial
      !>        ellipsoidal shape model and orientation data for the Earth.
      !>
      !>           pck00010.tpc
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM XFMSTA_EX2
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         FORM
      !>      PARAMETER           ( FORM = '(F16.6, F16.6, F16.6)' )
      !>
      !>C
      !>C     Local variables
      !>C
      !>C     STACYL is the state in cylindrical coordinates.
      !>C
      !>      DOUBLE PRECISION      STACYL (6)
      !>C
      !>C     STAPLN is the state transformed into planetographic
      !>C     coordinates.
      !>C
      !>      DOUBLE PRECISION      STAPLN (6)
      !>C
      !>C     STCYL2 is the state transformed back into
      !>C     cylindrical coordinates from planetographic.
      !>C
      !>      DOUBLE PRECISION      STCYL2 (6)
      !>
      !>      INTEGER               I
      !>
      !>      DATA STACYL / 1.0D0, 0.5D0, 0.5D0, 0.2D0, 0.1D0, -0.2D0 /
      !>
      !>C
      !>C     The required kernels must be loaded.
      !>C
      !>      CALL FURNSH ( 'pck00010.tpc' )
      !>
      !>C
      !>C     Transform the state from cylindrical to planetographic.
      !>C     Note that since one of the coordinate systems is
      !>C     planetographic, the body name must be input.
      !>C
      !>      CALL XFMSTA ( STACYL, 'CYLINDRICAL', 'PLANETOGRAPHIC',
      !>     .              'EARTH', STAPLN )
      !>
      !>C
      !>C     Transform the state back to cylindrical from
      !>C     planetographic for verification. The result should be
      !>C     very close to STACYL.
      !>C
      !>      CALL XFMSTA ( STAPLN, 'PLANETOGRAPHIC', 'CYLINDRICAL',
      !>     .              'EARTH', STCYL2 )
      !>
      !>C
      !>C     Report the results.
      !>C
      !>      WRITE (*,*)    'Cylindrical state'
      !>      WRITE (*,*)    '  Position [km, rad, km]:'
      !>      WRITE (*,FORM) (STACYL(I), I = 1, 3)
      !>      WRITE (*,*)    '  Velocity [km/s, rad/s, km/s]:'
      !>      WRITE (*,FORM) (STACYL(I), I = 4, 6)
      !>      WRITE (*,*)    ' '
      !>      WRITE (*,*) 'Planetographic state'
      !>      WRITE (*,*)    '  Position [rad, rad, km]:'
      !>      WRITE (*,FORM) (STAPLN(I), I = 1, 3)
      !>      WRITE (*,*)    '  Velocity [rad/s, rad/s, km/s]:'
      !>      WRITE (*,FORM) (STAPLN(I), I = 4, 6)
      !>      WRITE (*,*)    ' '
      !>      WRITE (*,*)    'Verification:  Cylindrical state'
      !>      WRITE (*,*)    '  Position [km, rad, km]:'
      !>      WRITE (*,FORM) (STCYL2(I), I = 1, 3)
      !>      WRITE (*,*)    '  Velocity [km/s, rad/s, km/s]:'
      !>      WRITE (*,FORM) (STCYL2(I), I = 4, 6)
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Cylindrical state
      !>           Position [km, rad, km]:
      !>                1.000000        0.500000        0.500000
      !>           Velocity [km/s, rad/s, km/s]:
      !>                0.200000        0.100000       -0.200000
      !>
      !>         Planetographic state
      !>           Position [rad, rad, km]:
      !>                0.500000        1.547722    -6356.240364
      !>           Velocity [rad/s, rad/s, km/s]:
      !>                0.100000       -0.004722       -0.195332
      !>
      !>         Verification:  Cylindrical state
      !>           Position [km, rad, km]:
      !>                1.000000        0.500000        0.500000
      !>           Velocity [km/s, rad/s, km/s]:
      !>                0.200000        0.100000       -0.200000
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     J. Diaz del Rio    (ODC Space)
      !>     S.C. Krening       (JPL)
      !>     B.V. Semenov       (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.2.0, 01-NOV-2021 (EDW) (JDR)
      !>
      !>        Body radii accessed from kernel pool using ZZGFTREB.
      !>
      !>        Edited he header to comply with NAIF standard.
      !>        Added missing begintext tag to the meta-kernel of example #1.
      !>        Modified example #2 to furnish a single kernel.
      !>
      !>        Updated Examples' kernels set to use PDS archived data.
      !>
      !>-    SPICELIB Version 1.1.0, 09-FEB-2017 (BVS)
      !>
      !>        BUG FIX: the routine no longer allows converting to and from
      !>        geodetic and planetographic coordinates for bodies with
      !>        unequal equatorial radii. Previously it arbitrarily picked the
      !>        first and the third radii to compute body's flattening
      !>        coefficient.
      !>
      !>-    SPICELIB Version 1.0.0, 22-APR-2014 (SCK) (BVS)
      module subroutine xfmsta ( ctx, istate, icosys, ocosys, body, ostate )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: dpmax
      use pepper_math, only: cylrec, drdcyl, drdlat, drdsph, latrec, mxv, reccyl, reclat, recsph, sphrec
      use pepper_strings, only: ljucrs
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: istate(6)  !! Input state.
      character(*), intent(in) :: icosys  !! Current (input) coordinate system.
      character(*), intent(in) :: ocosys  !! Desired (output) coordinate system.
      character(*), intent(in) :: body  !! Name or NAIF ID of body with which coordinates are associated (if applicable).
      real(wp), intent(out) :: ostate(6)  !! Converted output state.
      real(wp), parameter :: margin = 1.0e2_wp
      integer(ip), parameter :: chsiz = 40
      integer(ip), parameter :: ncosys = 6
      integer(ip), parameter :: rectan = 1
      integer(ip), parameter :: cyl = 2
      integer(ip), parameter :: latnl = 3
      integer(ip), parameter :: sphcl = 4
      integer(ip), parameter :: geodet = 5
      integer(ip), parameter :: plntgr = 6
      character(chsiz), parameter :: cosys ( ncosys ) = [ character(chsiz) :: &
         'RECTANGULAR',&
         'CYLINDRICAL',&
         'LATITUDINAL',&
         'SPHERICAL',&
         'GEODETIC',&
         'PLANETOGRAPHIC' ]
      character(chsiz) :: isysu
      character(chsiz) :: osysu
      real(wp) :: ipos   ( 3 )
      real(wp) :: ivel   ( 3 )
      real(wp) :: radii  ( 3 )
      real(wp) :: jacobi ( 3, 3 )
      real(wp) :: f
      real(wp) :: sqtmp
      real(wp) :: toobig
      integer(ip) :: bodyid
      integer(ip) :: i
      integer(ip) :: isys
      integer(ip) :: j
      integer(ip) :: osys
      logical :: found
      if ( .not. allocated ( ctx%xfmsta_state ) ) allocate ( ctx%xfmsta_state )
      associate ( svctr1 => ctx%xfmsta_state%svctr1, &
                  svbody => ctx%xfmsta_state%svbody, &
                  svbdid => ctx%xfmsta_state%svbdid, &
                  svfnd1 => ctx%xfmsta_state%svfnd1, &
                  first => ctx%xfmsta_state%first )
      if ( ctx%failed() ) return

!
!     Initialization.
!
      if ( first ) then

!
!        Initialize counter.
!
         call zzctruin( ctx, svctr1 )

         first = .false.

      end if

!
!     Remove initial and trailing spaces.
!     Convert the input coordinate systems to upper case.
!
      call ljucrs ( 0, icosys, isysu )
      call ljucrs ( 0, ocosys, osysu )

!
!     Check to see if the input and output coordinate systems
!     provided by the user are acceptable. Store the integer
!     code of the input and output coordinate systems into
!     ISYS and OSYS.
!
      isys = findloc(cosys, isysu, dim=1)
      osys = findloc(cosys, osysu, dim=1)

!
!     If the coordinate systems are not acceptable, an error is
!     signaled.
!
      if ( ( isys == 0 )  .or.  ( osys == 0 ) ) then

         if    ( ( isys == 0 )  .and. ( osys == 0 ) ) then

!
!           Both the input and the output coordinate systems were not
!           recognized.
!
            call ctx%setmsg ( 'Input coordinate system # ' &
                      //  'and output coordinate system # ' &
                      //  'are not recognized.' )
            call ctx%errch  ( '#', icosys )
            call ctx%errch  ( '#', ocosys )
            call ctx%sigerr ( 'SPICE(COORDSYSNOTREC)' )
            return

         else if ( isys == 0 ) then

!
!           The input coordinate system was not recognized.
!
            call ctx%setmsg ( 'Input coordinate system # ' &
                     //   'was not recognized'  )
            call ctx%errch  ( '#', icosys )
            call ctx%sigerr ( 'SPICE(COORDSYSNOTREC)' )
            return

         else

!
!           The output coordinate system was not recognized.
!
            call ctx%setmsg ( 'Output coordinate system # ' &
                     //   'was not recognized'    )
            call ctx%errch  ( '#', ocosys )
            call ctx%sigerr ( 'SPICE(COORDSYSNOTREC)' )
            return

         end if

      end if

!
!     If the input and output coordinate systems are equal, set the
!     output equal to the input since no conversion needs to take
!     place.
!
      if ( isys == osys ) then

         ostate = istate
         return

      end if

!
!     If converting to or from either geodetic or planetographic, the
!     NAIF ID must be found from the input body name BODY. If the
!     body name does not have a valid NAIF ID code, an error is
!     signaled. If the NAIF ID is valid, the radii of the body are
!     located and the flattening coefficient is calculated.
!
      if ( ( osys == geodet ) .or. ( osys == plntgr )   .or. &
           ( isys == geodet ) .or. ( isys == plntgr ) ) then

!
!        Find the NAIF ID code
!
         call zzbods2c ( ctx, svctr1, svbody, svbdid, svfnd1, &
                         body, bodyid, found    )
!
!        If the body's name was found, find the body's radii and
!        compute flattening coefficient. Otherwise, signal an error.
!
         if ( found ) then

            call zzgftreb ( ctx, bodyid, radii )

            if ( ctx%failed() ) return

!
!           If the difference of the equatorial and polar radii
!           divided by the equatorial radius is greater than DPMAX,
!           a numeric overflow may occur, so an error is signaled.
!
            if ( sqrt(abs( radii(1) - radii(3) )) / &
                 sqrt(abs( radii(1) )) >= sqrt(dpmax) ) then

               call ctx%setmsg ( 'The equatorial radius for # ' &
                        //   'has a value of # and a polar radius of ' &
                        //   '#. The flattening coefficient cannot be ' &
                        //   'calculated due to numeric overflow.' )
               call ctx%errch  ( '#', body     )
               call ctx%errdp  ( '#', radii(1) )
               call ctx%errdp  ( '#', radii(3) )
               call ctx%sigerr ( 'SPICE(INVALIDRADIUS)' )
               return

            end if

!
!           At this point, we also check for unequal equatorial radii,
!           which are not allowed with geodetic or planetographic
!           coordinates.
!
            if ( radii(1) /= radii(2) ) then

               call ctx%setmsg ( 'The body # has radii (#, #, #). ' &
               //            'Unequal equatorial ellipsoid radii are ' &
               //            'not supported for # and # coordinates.')
               call ctx%errch  ( '#', body                               )
               call ctx%errdp  ( '#', radii(1)                           )
               call ctx%errdp  ( '#', radii(2)                           )
               call ctx%errdp  ( '#', radii(3)                           )
               call ctx%errch  ( '#', cosys ( geodet )                   )
               call ctx%errch  ( '#', cosys ( plntgr )                   )
               call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                   )
               return

            end if

!
!           Calculate the flattening coefficient, F.
!
            f = ( radii(1) - radii(3) ) / radii(1)

         else

            call ctx%setmsg ( 'The input body name # does not ' &
                     //   'have a valid NAIF ID code.' )
            call ctx%errch  ( '#', body )
            call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'     )
            return

         end if

      end if

!
!     Conversion of the input to rectangular coordinates
!     ----------------------------------------------------------------
!
!     First, the position and velocity coordinates will be converted
!     into rectangular coordinates. If the input system is not
!     rectangular, then the velocity coordinates must be translated
!     into rectangular using the Jacobian. If the input system is
!     rectangular, then the input state must simply be saved into IPOS
!     and IVEL.
!
!     TOOBIG is used for preventing numerical overflow. The square
!     roots of values are used to safely check if overflow will occur.
!
      toobig = sqrt ( dpmax / margin )

      if  ( isys /= rectan ) then
!
!        To rectangular...
!
         if       ( isys == cyl )    then

!
!                  ... from cylindrical
!
            call cylrec ( istate(1), istate(2), istate(3), ipos   )

            call drdcyl ( istate(1), istate(2), istate(3), jacobi )

         else if  ( isys == latnl )  then

!
!                  ... from latitudinal
!
            call latrec ( istate(1), istate(2), istate(3), ipos   )

            call drdlat ( istate(1), istate(2), istate(3), jacobi )

         else if  ( isys == sphcl )  then

!
!                  ... from spherical
!
            call sphrec ( istate(1), istate(2), istate(3), ipos   )

            call drdsph ( istate(1), istate(2), istate(3), jacobi )

         else if  ( isys == geodet ) then

!
!                  ... from geodetic
!
            call georec ( ctx, istate(1), istate(2), istate(3), radii(1), &
                          f, ipos )

            if ( ctx%failed() ) return

            call drdgeo ( ctx, istate(1), istate(2), istate(3), radii(1), &
                          f, jacobi )

         else if  ( isys == plntgr ) then

!
!                  ... from planetographic
!
            call pgrrec ( ctx, body, istate(1), istate(2), istate(3), &
                          radii(1), f, ipos   )

            if ( ctx%failed() ) return

            call drdpgr ( ctx, body, istate(1), istate(2), istate(3), &
                          radii(1), f, jacobi )

         else

            call ctx%setmsg ( 'This error should never occur. ' &
                     //   'This is an intermediate step in which a ' &
                     //   'non-rectangular input state should be ' &
                     //   'transferred to rectangular.  The input ' &
                     //   'coordinate system is not recognized, yet ' &
                     //   'was not caught by an earlier check.' )
            call ctx%sigerr ( 'SPICE(BUG1)')
            return

         end if

!
!        Some DRD* routines are not error free. Be safe and check
!        FAILED to not use un-initialized JACOBI.
!
         if ( ctx%failed() ) return

!
!        If the multiplication of the Jacobian and velocity can cause
!        overflow, signal an error.
!
         do  i = 1, 3

            do  j = 1, 3

               sqtmp = sqrt ( abs ( jacobi(i,j) ) ) * &
                       sqrt ( abs ( istate(j+3) ) )

               if ( sqtmp > toobig ) then

                  call ctx%setmsg ( 'The product of the Jacobian ' &
                           //   'and velocity may cause numeric ' &
                           //   'overflow.' )
                  call ctx%sigerr ( 'SPICE(NUMERICOVERFLOW)' )
                  return

               end if

            end do

         end do

!
!        Transform the velocity into rectangular coordinates.
!
         call mxv ( jacobi, istate(4), ivel )

      else if  ( isys == rectan ) then

!
!        If the input coordinate system is rectangular, the input
!        position does not need to be translated into rectangular.
!
         ipos = istate(1:3)
         ivel = istate(4:6)

      else

         call ctx%setmsg ( 'This error should never occur. ' &
                  //   'This is an ELSE statement. If the input ' &
                  //   'coordinate system is not rectangular, the ' &
                  //   'IF should be executed. If the input ' &
                  //   'coordinate system is rectangular, the ELSE IF ' &
                  //   'should be executed.' )
         call ctx%sigerr ( 'SPICE(BUG2)' )
         return

      end if

!
!     Conversion from rectangular into the output coordinates
!     ----------------------------------------------------------------
!
!     Convert to the output coordinate system. If the output
!     coordinate system is not rectangular, four calculations must
!     be made:
!
!       1)  Verify the position and velocity are not along the z-axis.
!           If the position and velocity are along the z-axis, the
!           velocity can still be converted even though the
!           Jacobian is not defined. If the position is along the
!           z-axis but the velocity is not, the velocity cannot be
!           converted to the output coordinate system.
!
!       2)  Calculate the Jacobian from rectangular to the output
!           coordinate system and verify the product of the Jacobian
!           and velocity will not cause numeric overflow.
!
!       3)  Transform the position to the output coordinate system.
!
!       4)  Transform the velocity to the output coordinates using
!           the Jacobian and the rectangular velocity IVEL.
!
      if ( osys /= rectan ) then

!
!        From rectangular for the case when the input position is along
!        the z-axis ...
!
         if ( ( abs(ipos(1)) + abs(ipos(2)) ) == 0.0_wp) then

            if ( ( abs(ivel(1)) + abs(ivel(2)) ) == 0.0_wp ) then
!
!              If the velocity is along the z-axis, then the velocity
!              can be computed in the output coordinate frame even
!              though the Jacobian is not defined.
!
               if       ( osys == cyl )    then

!
!                  ... to cylindrical
!
                  ostate(4:6) = [0.0_wp, 0.0_wp, ivel(3)]

                  call reccyl ( ipos(1),  ostate(1), ostate(2), &
                                ostate(3) )

               else if  ( osys == latnl )  then

!
!                  ... to latitudinal
!
                  ostate(4:6) = [ivel(3), 0.0_wp, 0.0_wp]

                  call reclat ( ipos(1), ostate(1),  ostate(2), &
                                ostate(3) )

               else if  ( osys == sphcl )  then

!
!                  ... to spherical
!
                  ostate(4:6) = [ivel(3), 0.0_wp, 0.0_wp]

                  call recsph ( ipos(1), ostate(1),  ostate(2), &
                                ostate(3) )

               else if  ( osys == geodet ) then

!
!                  ... to geodetic
!
                  ostate(4:6) = [0.0_wp, 0.0_wp, ivel(3)]

                  call recgeo ( ctx, ipos(1), radii(1), f, ostate(1), &
                                ostate(2), ostate(3) )

               else if  ( osys == plntgr ) then

!
!                  ... to planetographic
!
                  ostate(4:6) = [0.0_wp, 0.0_wp, ivel(3)]

                  call recpgr ( ctx, body, ipos(1), radii(1), f, ostate(1), &
                                ostate(2), ostate(3) )

               else

                  call ctx%setmsg ( 'This error should never ' &
                       //   'occur. This is an intermediate step in ' &
                       //   'which a position and velocity along ' &
                       //   'the z-axis are converted to a ' &
                       //   'non-rectangular coordinate system from ' &
                       //   'rectangular. The output coordinate ' &
                       //   'system is not recognized, yet was not ' &
                       //   'caught by an earlier check.' )
                  call ctx%sigerr ( 'SPICE(BUG3)' )
                  return

               end if
!
!              The output state has been calculated for the special
!              case of the position and velocity existing along the
!              z-axis.
!
               return

            else
!
!              The Jacobian is undefined and the velocity cannot be
!              converted since it is not along the z-axis.
!              Signal an error.
!
               call ctx%setmsg ( 'Invalid input state: z axis.' )
               call ctx%sigerr ( 'SPICE(INVALIDSTATE)' )
               return

            end if

         end if

!
!        From rectangular for cases when the input position is not along
!        the z-axis ...
!
         if       ( osys == cyl )    then
!
!                  ... to cylindrical
!
            call dcyldr ( ctx, ipos(1), ipos(2),   ipos(3),   jacobi    )

            call reccyl ( ipos(1), ostate(1), ostate(2), ostate(3) )

         else if  ( osys == latnl )  then

!
!                  ... to latitudinal
!
            call dlatdr ( ctx, ipos(1), ipos(2),   ipos(3),   jacobi    )

            call reclat ( ipos(1), ostate(1), ostate(2), ostate(3) )

         else if  ( osys == sphcl )  then

!
!                  ... to spherical
!
            call dsphdr ( ctx, ipos(1), ipos(2),   ipos(3),   jacobi    )

            call recsph ( ipos(1), ostate(1), ostate(2), ostate(3) )

         else if  ( osys == geodet ) then

!
!                  ... to geodetic
!
            call dgeodr ( ctx, ipos(1), ipos(2),  ipos(3), radii(1), f, &
                          jacobi )

            call recgeo ( ctx, ipos(1), radii(1), f, ostate(1), ostate(2), &
                          ostate(3) )

         else if  ( osys == plntgr ) then

!
!                  ... to planetographic
!
            call dpgrdr ( ctx, body, ipos(1), ipos(2), ipos(3), radii(1), &
                          f,    jacobi )

            call recpgr ( ctx, body, ipos(1), radii(1), f, ostate(1), &
                          ostate(2), ostate(3) )

         else

            call ctx%setmsg ( 'This error should never occur. ' &
                     //   'This is an intermediate step in which a ' &
                     //   'state is converted to a non-rectangular ' &
                     //   'coordinate system from rectangular. The ' &
                     //   'output coordinate system is not recognized, ' &
                     //   'yet was not caught by an earlier check.' )
            call ctx%sigerr ( 'SPICE(BUG4)' )
            return

         end if

!
!        Many D*DR and REC* routines are not error free. Be safe and
!        check FAILED to not use un-initialized JACOBI.
!
         if ( ctx%failed() ) return

!
!        If the multiplication of the Jacobian and velocity can cause
!        overflow, signal an error.
!
         do i = 1, 3

            do  j = 1, 3

               sqtmp = sqrt ( abs ( jacobi(i,j) ) ) * &
                       sqrt ( abs ( ivel(j)     ) )

               if ( sqtmp > toobig ) then

                  call ctx%setmsg ( 'The product of the Jacobian ' &
                           //   'and velocity may cause numeric ' &
                           //   'overflow.' )
                  call ctx%sigerr ( 'SPICE(NUMERICOVERFLOW)' )
                  return

               end if

            end do

         end do

!
!        Calculate the velocity in the output coordinate system.
!
         call mxv ( jacobi, ivel, ostate(4) )

      else if ( osys == rectan ) then

!
!        If the output coordinate system is rectangular, the position
!        and velocity components of the output state are set equal to
!        the rectangular IPOS and IVEL, respectively, because the
!        components have already been converted to rectangular.
!
         ostate(1:3) = ipos
         ostate(4:6) = ivel

      else

         call ctx%setmsg ( 'This error should never occur. ' &
                  //   'This is an ELSE statement. If the output ' &
                  //   'coordinate system is not rectangular, the ' &
                  //   'IF should be executed. If the output ' &
                  //   'coordinate system is rectangular, the ELSE IF ' &
                  //   'should be executed.' )
         call ctx%sigerr ( 'SPICE(BUG5)' )
         return

      end if

      return
      end associate
      end subroutine xfmsta

      !> Compute illumination angles and their rates of change at a
      !> surface point.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due
      !> to the volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     METHOD         is a string specifying the computation method to
      !>                    be used by this routine. The only value currently
      !>                    allowed is 'ELLIPSOID'. This indicates that the
      !>                    target body shape is modeled as an ellipsoid.
      !>
      !>                    Case and leading and trailing blanks are not
      !>                    significant in METHOD.
      !>
      !>     TARGET         is the name of the target body associated with the
      !>                    surface point SPOINT. TARGET may be a body name or
      !>                    an ID code provided as as string.
      !>
      !>     ILLUM          is the name of the illumination source used to
      !>                    define the illumination angles computed by this
      !>                    routine. ILLUM may be a body name or an ID code
      !>                    provided as as string.
      !>
      !>     ET             is the observation time. ET is expressed as
      !>                    seconds past J2000 TDB.
      !>
      !>     FIXREF         is the name of the body-centered, body-fixed
      !>                    reference frame relative to which SPOINT is
      !>                    specified. The frame's center must coincide with
      !>                    TARGET.
      !>
      !>     ABCORR         indicates the aberration corrections to be
      !>                    applied. Only reception corrections are supported.
      !>                    See the header of ILUMIN for a discussion of
      !>                    aberration corrections used in illumination angle
      !>                    computations.
      !>
      !>     OBSRVR         is the name of the observing body. OBSRVR may be a
      !>                    body name or an ID code provided as as string.
      !>
      !>     SPOINT         is a 3-vector containing the cartesian coordinates
      !>                    of the surface point at which the illumination
      !>                    angle states are to be computed. SPOINT is
      !>                    expressed in the body-centered, body-fixed frame
      !>                    designated by FIXREF (see description above).
      !>
      !>                    Units are km.
      !>
      !>     NORMAL         is an outward normal vector to be used for
      !>                    emission angle and solar incidence angle
      !>                    calculations. NORMAL should be orthogonal to the
      !>                    plane tangent at SPOINT to the target body's
      !>                    surface.
      !>
      !>## Detailed Output
      !>
      !>     PHSSTA         is the phase angle and its rate of change with
      !>                    respect to TDB, evaluated at ET.
      !>
      !>     INCSTA         is the solar incidence angle and its rate of
      !>                    change with respect to TDB, evaluated at ET.
      !>
      !>     EMISTA         is the emission angle and its rate of change with
      !>                    respect to TDB, evaluated at ET.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the computation method is not recognized, the error
      !>         SPICE(INVALIDMETHOD) is signaled.
      !>
      !>     2)  If ABCORR specifies a transmission aberration correction,
      !>         the error SPICE(INVALIDOPTION) is signaled.
      !>
      !>     3)  If an error occurs while looking up a state vector, the
      !>         error will be signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>     4)  If the input normal vector is zero, the error
      !>         SPICE(ZEROVECTOR) is signaled.
      !>
      !>## Files
      !>
      !>     See GFILUM.
      !>
      !>## Particulars
      !>
      !>     The term "state" used in the name of this routine refers to
      !>     the combination of a function and its derivative with respect
      !>     to time.
      !>
      !>     This routine centralizes computation of illumination angles and
      !>     their rates of change. It also exposes the illumination angle
      !>     rates of change used by the GF system in order to allow these
      !>     rates to be tested using the TSPICE system.
      !>
      !>     See the SPICELIB routine ILUMIN for a description of the
      !>     illumination angles computed by this routine.
      !>
      !>## Examples
      !>
      !>     See usage in ZZGFILDC.
      !>
      !>## Restrictions
      !>
      !>     1) This routine is intended for use only by the GF subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 02-APR-2012 (NJB)
      !>
      !>       Previous version was dated 21-MAR-2012
      module subroutine zzilusta ( ctx, method, target, illum, et, fixref, abcorr, obsrvr, spoint, normal, phssta, incsta, emista )
      use pepper_kinds, only: wp
      use pepper_constants, only: clight
      use pepper_math, only: mxvg, vdot, vhat, vsep
      use pepper_strings, only: eqstr
      use pepper_inc_zzabcorr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: method  !! Computation method.
      character(*), intent(in) :: target  !! Name of target body associated with surface point.
      character(*), intent(in) :: illum  !! Name of illumination source.
      real(wp), intent(in) :: et  !! Observation epoch (TDB).
      character(*), intent(in) :: fixref  !! Body-fixed reference frame.
      character(*), intent(in) :: abcorr  !! Aberration correction.
      character(*), intent(in) :: obsrvr  !! Name of observer.
      real(wp), intent(in) :: spoint ( 3 )  !! Surface point.
      real(wp), intent(in) :: normal ( 3 )  !! Outward normal vector at surface point.
      real(wp), intent(out) :: phssta ( 2 )  !! Phase angle state.
      real(wp), intent(out) :: incsta ( 2 )  !! Solar incidence angle state.
      real(wp), intent(out) :: emista ( 2 )  !! Emission angle state.


      real(wp) :: dlt
      real(wp) :: etsurf
      real(wp) :: fxnsta ( 6 )
      real(wp) :: lt
      real(wp) :: ltsrc
      real(wp) :: nrmsta ( 6 )
      real(wp) :: obssta ( 6 )
      real(wp) :: srcsta ( 6 )
      real(wp) :: starg  ( 6 )
      real(wp) :: tmpxfm ( 6, 6 )
      real(wp) :: uvec   ( 3 )
      real(wp) :: xform  ( 6, 6 )

      logical :: attblk ( abatsz )
      logical :: uselt
      logical :: xmit

      if ( ctx%failed() ) return

!
!     For now, only ellipsoids are supported as target shapes.
!
      if (  .not.  eqstr( method, 'ELLIPSOID' )  ) then

         call ctx%setmsg ( 'The computation method # was not recognized. ' )
         call ctx%errch  ( '#',  method                                    )
         call ctx%sigerr ( 'SPICE(INVALIDMETHOD)'                          )
         return

      end if

!
!     Reject zero normal vectors.
!
      if ( all(normal == 0.0_wp) ) then

         call ctx%setmsg ( 'The input normal vector must not be zero, ' &
         //            'but sadly, it was.'                       )
         call ctx%sigerr ( 'SPICE(ZEROVECTOR)'                        )
         return

      end if

!
!     Look up the state of the target with respect to the
!     observer. We'll represent the state in an inertial
!     reference frame.
!
      call spkcpt ( ctx, spoint,   target, fixref, et,    iref, &
                    'TARGET', abcorr, obsrvr, starg, lt    )

!
!     Compute the epoch associated with the surface point.
!
      call zzcorepc ( ctx, abcorr, et, lt, etsurf )

!
!     Now let the surface point be the observer, let the observation
!     epoch be ETSURF, and find the apparent state of the illumination
!     source as seen from the surface point.
!
      call spkcpo ( ctx, illum,  etsurf, iref,   'OBSERVER', abcorr, &
                    spoint, target, fixref, srcsta,     ltsrc  )

      if ( ctx%failed() ) return

!
!     We will need to transform the state of the normal vector to
!     the inertial frame. The epoch at which the transformation must be
!     evaluated is that associated with the surface point.

      call sxform ( ctx, fixref, iref, etsurf, xform )

!
!     Correct the body-fixed to inertial frame transformation for the
!     rate of change with respect to ET of observer-surface point light
!     time, if light time corrections are used.
!
!     Start out by parsing ABCORR.
!
      call zzvalcor ( ctx, abcorr, attblk )

      if ( ctx%failed() ) return

      uselt = attblk( ltidx  )
      xmit  = attblk( xmtidx )

      if ( xmit ) then

         call ctx%setmsg ( 'Aberration correction # is for transmission; ' &
         //            'only reception corrections are supported by ' &
         //            'this routine.'                                )
         call ctx%errch  ( '#', abcorr                                    )
         call ctx%sigerr ( 'SPICE(INVALIDOPTION)'                         )
         return

      end if

      if ( uselt ) then
!
!        Compute the rate of change with respect to ET of the
!        observer-surface point light time. This rate is the range rate
!        divided by the speed of light.
!
         call vhat ( starg, uvec )

         dlt = vdot ( starg(4), uvec ) / clight
!
!        Correct the state transformation.
!
         call zzcorsxf ( ctx, .false., dlt, xform, tmpxfm )

         xform = tmpxfm

      end if

!
!     Create a body-fixed state vector for the normal vector.
!     Convert the normal vector to unit length for safety.
!
      call vhat   ( normal, fxnsta    )
      fxnsta(4:6) = 0.0_wp

!
!     Transform the state of the normal vector to the inertial
!     frame.
!
      call mxvg ( xform,  fxnsta, 6, 6, nrmsta )

!
!     We also must adjust the state of the illumination source for the
!     rate of change with respect to ET of the observer-surface point
!     light time. The velocity portion of the state we've computed is
!     the derivative with respect to ETSURF (time at the surface point)
!     of the surface point-illumination source vector. We must convert
!     this to a derivative with respect to ET.
!
!     This code assumes reception corrections.
!
      if ( uselt ) then
!
!        ETSURF = ET - LT, so
!
!        d(ETSURF) / d(ET) = ( 1 - DLT )
!
         srcsta(4:6) = (1.0_wp - dlt)*srcsta(4:6)

      end if

!
!     The surface-point observer state we wish to use is the negative
!     of the observer-surface point state.
!
      obssta = -starg

!
!     Compute the state (value and rate of change )
!     of the phase angle.
!
      phssta( 1 ) =  vsep  ( obssta, srcsta )
      phssta( 2 ) =  dvsep ( ctx, obssta, srcsta )

!
!     Compute the state of the illumination source
!     incidence angle.
!
      incsta( 1 ) =  vsep  ( nrmsta, srcsta )
      incsta( 2 ) =  dvsep ( ctx, nrmsta, srcsta )

!
!     Compute the state of the emission angle.
!
      emista( 1 ) =  vsep  ( nrmsta, obssta )
      emista( 2 ) =  dvsep ( ctx, nrmsta, obssta )

      return
      end subroutine zzilusta

      !> Test a point represented by a set of latitudinal coordinates for
      !> inclusion in a specified latitudinal volume element. The test is
      !> performed using margins for the element.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     P          is a point expressed in Cartesian coordinates. The
      !>                point is to be checked to determine whether it is
      !>                inside the volume element specified by BOUNDS.
      !>
      !>     BOUNDS     is an 2x3 array containing the bounds of a volume
      !>                element expressed in latitudinal coordinates. BOUNDS
      !>                defines the volume element used in the comparison. In
      !>                the element
      !>
      !>                   BOUNDS(I,J)
      !>
      !>                J is the coordinate index. J is one of
      !>
      !>                   { LONIDX, LATIDX, RADIDX }
      !>
      !>                I is the bound index.
      !>
      !>                   I = 1   ->   lower bound
      !>                   I = 2   ->   upper bound
      !>
      !>                If necessary, the longitude bounds are normalized
      !>                for the comparison. The normalized bounds differ
      !>                by no more than 2*pi and are in increasing order.
      !>                See ZZNRMLON for details.
      !>
      !>                The aliasing margin LONALI, the greedy margin, and the
      !>                angular rounding margin ANGMRG are used for longitude
      !>                comparisons. ANGMRG is used if its magnitude exceeds
      !>                that of the greedy margin. See the Parameters section
      !>                below for further information.
      !>
      !>     MARGIN     is a fraction used to expand the volume element for
      !>                inclusion testing.
      !>
      !>                   - The outer radius is scaled by (1+MARGIN).
      !>                     The inner radius is scaled by (1-MARGIN).
      !>
      !>                   - Latitude bounds are extended by MARGIN radians,
      !>                     within the interval -pi/2 : pi/2.
      !>
      !>                   - For any input point having latitude "not close"
      !>                     to pi/2 or -pi/2, the element's longitude
      !>                     interval is extended by
      !>
      !>                        MARGIN / cos(LAT)
      !>
      !>                     where LAT is the latitude of the input point.
      !>
      !>                     Here "close to" means "within LATMRG radians of."
      !>
      !>                   - For any input point having latitude close to
      !>                     pi/2 or -pi/2, comparison against the longitude
      !>                     bounds of the volume element is omitted if
      !>                     MARGIN > 0.
      !>
      !>     EXCLUD     is either a coordinate index or the parameter NONE.
      !>
      !>                If EXCLUD is set to one of
      !>
      !>                   { LONIDX, LATIDX, RADIDX }
      !>
      !>                then the indicated coordinate is excluded from
      !>                comparison with the corresponding volume element
      !>                boundaries.
      !>
      !>                If EXCLUD is set to NONE, all coordinates are
      !>                compared.
      !>
      !>                Exclusion of coordinates is used in cases where a
      !>                point is known to be on a level surface of a given
      !>                coordinate. For example, if a point is on the sphere
      !>                of radius equal to the upper radius bound, radius need
      !>                not be used in the comparison and in fact can't be
      !>                meaningfully compared, due to round-off errors.
      !>
      !>## Detailed Output
      !>
      !>     INSIDE     is a logical flag that is set to .TRUE. if and
      !>                only if the input coordinates represent a
      !>                point inside or on the surface of the volume
      !>                element, according to the comparisons that are
      !>                performed.
      !>
      !>                The value of INSIDE is not affected by the value
      !>                of any excluded coordinate.
      !>
      !>## Parameters
      !>
      !>     LATMRG     Margin for determining whether the input latitude is
      !>                "close" to the poles. Units are radians. This value
      !>                should be kept in sync with the default "greedy"
      !>                margin.
      !>
      !>     LONALI     is a longitude shift margin. If the input longitude
      !>                coordinate LON is less than the longitude lower bound
      !>                by more than this amount, the value LON + 2*pi is
      !>                used in the longitude comparison, provided that the
      !>                comparison is not excluded.
      !>
      !>                See dsktol.inc for details.
      !>
      !>     ANGMRG     is an angular rounding margin. If the input longitude
      !>                is outside of the longitude bounds by less than this
      !>                amount, the longitude is considered to be within the
      !>                bounds. ANGMRG is used when the magnitude of the
      !>                "greedy" margin is less than ANGMRG. ANGMRG is not
      !>                used for computations involving coordinates other than
      !>                longitude.
      !>
      !>                This margin is distinct from the "greedy" segment
      !>                selection margin, which is used to expand a volume
      !>                element for the purpose of determining whether a given
      !>                point lies in that element.
      !>
      !>                See dsktol.inc for details.
      !>
      !>     NONE       when used as a value of the input argument EXCLUD,
      !>                indicates that no coordinates should be excluded from
      !>                comparison.
      !>
      !>     LONIDX     is the index of longitude in the second dimension of
      !>                BOUNDS. When used as a value of the input argument
      !>                EXCLUD, indicates that longitude should be excluded
      !>                from comparison.
      !>
      !>     LATIDX     is the index of latitude in the second dimension of
      !>                BOUNDS. When used as a value of the input argument
      !>                EXCLUD, indicates that latitude should be excluded
      !>                from comparison.
      !>
      !>     RADIDX     is the index of radius in the second dimension of
      !>                BOUNDS. When used as a value of the input argument
      !>                EXCLUD, indicates that radius should be excluded
      !>                from comparison.
      !>
      !>## Exceptions
      !>
      !>     1)  If MARGIN is negative, the error SPICE(VALUEOUTOFRANGE)
      !>         is signaled.
      !>
      !>     2)  If EXCLUD is outside of the range 0:3, the error
      !>         SPICE(VALUEOUTOFRANGE) is signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     None.
      !>
      !>## Examples
      !>
      !>     See usage in ZZRYTLAT.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 03-JUN-2016 (NJB)
      !>
      !>        Original version 03-OCT-2014 (NJB)
      module subroutine zzinlat ( ctx, p, bounds, margin, exclud, inside )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: halfpi, twopi
      use pepper_math, only: reclat
      use pepper_inc_dsktol
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: p      ( 3 )  !! Input point.
      real(wp), intent(in) :: bounds ( 2, 3 )  !! Coordinate bounds of element.
      real(wp), intent(in) :: margin  !! Margin used for inclusion testing.
      integer(ip), intent(in) :: exclud  !! Index of coordinate to exclude from test.
      logical, intent(out) :: inside  !! Flag indicating whether point is in element.

      integer(ip), parameter :: none = 0





      real(wp) :: amaxr
      real(wp) :: aminr
      real(wp) :: amaxlt
      real(wp) :: aminlt
      real(wp) :: amaxlo
      real(wp) :: aminlo
      real(wp) :: dlon
      real(wp) :: lat
      real(wp) :: lon
      real(wp) :: lonmrg
      real(wp) :: maxlat
      real(wp) :: maxlon
      real(wp) :: maxr
      real(wp) :: minlat
      real(wp) :: minlon
      real(wp) :: minr
      real(wp) :: r
      real(wp) :: smax
      real(wp) :: smin

!
!     Constants (SPICELIB computed them on the first call).
!
      real(wp), parameter :: pi2 = twopi
      real(wp), parameter :: hpi = halfpi

      if ( ctx%failed() ) return

!
!     Get the latitudinal coordinates of the input point.
!
      call reclat ( p, r, lon, lat )

!
!     Handle the simpler zero-margin case separately.
!
      if ( margin == 0.0_wp ) then

         call zzinlat0 ( ctx, r, lon, lat, bounds, exclud, inside )

         return

      else if ( margin < 0.0_wp ) then

         call ctx%setmsg ( 'Margin must be non-negative but was #.' )
         call ctx%errdp  ( '#', margin                              )
         call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'                 )
         return

      end if

      if (  ( exclud < 0 ) .or. ( exclud > 3 )  ) then

         call ctx%setmsg ( 'EXCLUD must be in the range 0:3 but was #.' )
         call ctx%errint ( '#', exclud                                  )
         call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'                     )
         return

      end if

!
!     Special case: if the input point is within distance MARGIN
!     from the origin, and the minimum radius of the volume element
!     is less than or equal to MARGIN, the point is inside.
!
      if ( r <= margin ) then

         if ( bounds(inner, radidx) <= margin ) then

            inside = .true.

            return

         end if

      end if

!
!     Assume the point is outside to start. This allows us
!     to skip setting INSIDE when we find a boundary test
!     failure.
!
      inside = .false.

!
!     Get local copies of the coordinate bounds. Don't normalize the
!     longitude bounds until we know we need them.
!
      minr   = bounds( inner, radidx )
      maxr   = bounds( outer, radidx )

      minlat = bounds( south, latidx )
      maxlat = bounds( north, latidx )

!
!     Compare coordinates to adjusted latitude and radius
!     boundaries.
!
      if ( exclud /= radidx ) then
!
!        Create adjusted radius bounds.
!
         smax  = 1.0_wp + margin
         smin  = 1.0_wp - margin

         aminr = max( 0.0_wp,  minr*smin )
         amaxr = maxr * smax

         if ( ( r < aminr ) .or. ( r > amaxr ) ) return

      end if

      if ( exclud /= latidx ) then
!
!        Create adjusted latitude bounds.
!
         aminlt = max( -hpi, minlat - margin )
         amaxlt = min(  hpi, maxlat + margin )

         if ( ( lat < aminlt ) .or. ( lat > amaxlt ) ) return

      end if

!
!     At this point, the input radius and latitude are within the
!     adjusted bounds, if their tests haven't been excluded by
!     the caller.
!
!     Perform longitude tests, unless they're excluded by the
!     caller.
!
      if ( exclud /= lonidx ) then

         call zznrmlon ( ctx, bounds(west,lonidx), bounds(east,lonidx), &
                         angmrg,              minlon, &
                         maxlon                                   )
!
!        Set the margin to be used for longitude interval
!        inclusion tests.
!
         lonmrg = max( abs(angmrg), abs(margin) )

!
!        We have a special case for segments that include the poles. If
!        the input point is close enough to a pole contained in the
!        segment, we consider the point to be included in the segment,
!        regardless of the point's longitude. All other points get the
!        normal longitude test.
!
         if (       ( lat <= (  hpi - latmrg ) ) &
              .and. ( lat >= ( -hpi + latmrg ) )  ) then
!
!           This is the usual case: the latitude of the input point
!           is bounded away from the poles.
!
!           Check the point's longitude against the segment's
!           longitude bounds.
!
!           We'll scale the longitude margin to compensate for the
!           latitude of the input point. Note that the division
!           below is safe; presuming a reasonable value of MARGIN;
!           we know that
!
!              DLON << 1
!
            dlon   = lonmrg / max( abs(cos(lat)), latmrg )

            aminlo = minlon - dlon
            amaxlo = maxlon + dlon

!
!           Now move the input point's longitude into range, if
!           necessary.
!
            if ( lon < aminlo ) then

               if (  lon  < ( aminlo - lonali )  ) then
!
!                 See whether an aliased version of LON is a match.
!
                  lon = lon + pi2

               else
!
!                 Consider LON to be a match with the lower bound.
!
                  lon = aminlo

               end if

            else if ( lon > amaxlo ) then

               if (  lon  > ( amaxlo + lonali )  ) then
!
!                 See whether an aliased version of LON is a match.
!
                  lon = lon - pi2

               else
!
!                 Consider LON to be a match with the upper bound.
!
                  lon = amaxlo

               end if

            end if

!
!           Compare the adjusted longitude of the input point to the
!           adjusted longitude bounds.
!
            if ( ( lon < aminlo ) .or. ( lon > amaxlo ) ) return

         else
!
!           The latitude of the input point is close to one of the
!           poles.
!
!           This is a no-op case.
!
!           The input point has already passed whichever of the radius
!           and latitude tests that were not excluded.
!
!           If the element has a non-degenerate latitude boundary
!           having the same sign as the latitude of the input point,
!           and if latitude is excluded because the input point is
!           already nominally on that boundary, then passing the radius
!           check implies that the point is close to the element.
!
!           If the element has a degenerate latitude boundary having
!           the same sign as the latitude of the input point---namely,
!           the element contains the pole, and latitude is excluded,
!           then then passing the radius check implies that the point
!           is close to the portion of the Z-axis contained in the
!           element.
!
!           If the radius check has been excluded because the point is
!           already nominally on one of the element's radius boundaries,
!           the passing the latitude test implies the point is close
!           to the element.
!
!           In all cases, as long as EXCLUD has been set appropriately,
!           the point is close to the element. We consider the point to
!           be in the expanded element.
!
         end if

      end if

!
!     All tests that were commanded have been passed. The input
!     point is considered to be contained in the expanded volume
!     element.
!
      inside = .true.

      end subroutine zzinlat

      !> Test a point represented by a set of planetodetic coordinates for
      !> inclusion in a specified planetodetic volume element. Ellipsoidal
      !> surfaces are used in place of surfaces of constant altitude. The
      !> test is performed without using the "greedy" margins for the
      !> element. The built-in angular rounding tolerance is still used
      !> for the longitude comparison.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     P          is a point expressed in Cartesian coordinates. The
      !>                reference frame is that of the segment of interest.
      !>                The point is to be checked to determine whether it is
      !>                inside the volume element specified by BOUNDS.
      !>
      !>     LON        is the planetocentric longitude of the point P.
      !>
      !>     BOUNDS     is an 2x3 array containing the bounds of a volume
      !>                element expressed in planetodetic coordinates. BOUNDS
      !>                defines the volume element used in the comparison. In
      !>                the element
      !>
      !>                   BOUNDS(I,J)
      !>
      !>                J is the coordinate index. J is one of
      !>
      !>                   { LONIDX, LATIDX, ALTIDX }
      !>
      !>                I is the bound index.
      !>
      !>                   I = 1   ->   lower bound
      !>                   I = 2   ->   upper bound
      !>
      !>                If necessary, the longitude bounds are normalized
      !>                for the comparison. The normalized bounds differ
      !>                by no more than 2*pi and are in increasing order.
      !>                See ZZNRMLON for details.
      !>
      !>                The aliasing margin LONALI and the angular rounding
      !>                margin ANGMRG are used for longitude comparisons.
      !>                However, the greedy margin is not used. See the
      !>                Parameters section below for further information.
      !>
      !>     CORPAR     is an array of coordinate parameters; normally these
      !>                are obtained from a DSK descriptor. The first element
      !>                is the equatorial radius of the reference spheroid.
      !>                The second element is the flattening coefficient.
      !>                Any other elements are ignored by this routine.
      !>
      !>     EXCLUD     is either a coordinate index or the parameter NONE.
      !>
      !>                If EXCLUD is set to one of
      !>
      !>                   { LONIDX, LATIDX, ALTIDX }
      !>
      !>                then the indicated coordinate is excluded from
      !>                comparison with the corresponding volume element
      !>                boundaries.
      !>
      !>                If EXCLUD is set to NONE, all coordinates are
      !>                compared.
      !>
      !>                Exclusion of coordinates is used in cases where a
      !>                point is known to be on a level surface of a given
      !>                coordinate. For example, if a point is on the surface
      !>                of altitude equal to the upper altitude bound,
      !>                altitude need not be used in the comparison and in
      !>                fact can't be meaningfully compared, due to round-off
      !>                errors.
      !>
      !>## Detailed Output
      !>
      !>     INSIDE     is a logical flag that is set to .TRUE. if and
      !>                only if the input coordinates represent a
      !>                point inside or on the surface of the volume
      !>                element, according to the comparisons that are
      !>                performed.
      !>
      !>                The value of INSIDE is not affected by the value
      !>                of any excluded coordinate.
      !>
      !>## Parameters
      !>
      !>     LONALI     is a longitude shift margin. If the input longitude
      !>                coordinate LON is less than the longitude lower bound
      !>                by more than this amount, the value LON + 2*pi is used
      !>                in the longitude comparison. If the input longitude
      !>                exceeds the upper longitude bound by this amount, the
      !>                value LON - 2*pi is used in the comparison.
      !>
      !>     ANGMRG     is an angular rounding margin. If the input longitude
      !>                is outside of the longitude bounds by less than this
      !>                amount, the longitude is considered to be within the
      !>                bounds. The margin is used analogously for latitude.
      !>
      !>                This margin is distinct from the "greedy" segment
      !>                selection margin, which is used to expand a volume
      !>                element for the purpose of determining whether a given
      !>                point lies in that element.
      !>
      !>                See dsktol.inc for details.
      !>
      !>     NONE       when used as a value of the input argument EXCLUD,
      !>                indicates that no coordinates should be excluded from
      !>                comparison.
      !>
      !>     LONIDX     is the index of longitude in the second dimension of
      !>                BOUNDS. When used as a value of the input argument
      !>                EXCLUD, indicates that longitude should be excluded
      !>                from comparison.
      !>
      !>     LATIDX     is the index of latitude in the second dimension of
      !>                BOUNDS. When used as a value of the input argument
      !>                EXCLUD, indicates that latitude should be excluded
      !>                from comparison.
      !>
      !>     ALTIDX     is the index of altitude in the second dimension of
      !>                BOUNDS. When used as a value of the input argument
      !>                EXCLUD, indicates that altitude should be excluded
      !>                from comparison.
      !>
      !>## Exceptions
      !>
      !>     Error free.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine uses ellipsoidal bounding surfaces, in place of
      !>     surfaces of constant altitude, to represent the "outer" and
      !>     "inner" segment boundaries. These surfaces must be consistent
      !>     with those used by the ray-planetodetic volume element intercept
      !>     routine ZZRYTPDT.
      !>
      !>     The radii of these ellipsoidal surfaces are those produced by
      !>     the routine ZZELLBDS.
      !>
      !>     Note that a margin is used for longitude shifting, although
      !>     none is used to expand the volume element.
      !>
      !>## Examples
      !>
      !>     See usage in ZZINPDT.
      !>
      !>## Restrictions
      !>
      !>     1)  Validity of the ellipsoid shape parameters must be ensured by
      !>         the caller.
      !>
      !>     2)  This is a private routine. It is meant to be used only by the
      !>         DSK subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 16-AUG-2016 (NJB)
      !>
      !>        Now uses ANGMRG for latitude comparisons.
      !>
      !>        25-MAY-2016 (NJB)
      !>
      !>           Original version.
      module subroutine zzinpdt0 ( ctx, p, lon, bounds, corpar, exclud, inside )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: twopi
      use pepper_constants, only: halfpi
      use pepper_inc_dsktol
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: p      ( 3 )  !! Cartesian coordinates of point.
      real(wp), intent(in) :: lon  !! Planetocentric longitude of point.
      real(wp), intent(in) :: bounds ( 2, 3 )  !! Coordinate bounds of element.
      real(wp), intent(in) :: corpar ( * )  !! Coordinate parameters.
      integer(ip), intent(in) :: exclud  !! Index of coordinate to exclude from test.
      logical, intent(out) :: inside  !! Flag indicating whether point is in element.

      integer(ip), parameter :: none = 0




      integer(ip), parameter :: lower = 1

      integer(ip), parameter :: upper = 2

      real(wp) :: emax
      real(wp) :: emin
      real(wp) :: f
      real(wp) :: level
      real(wp) :: loclon
      real(wp) :: maxlat
      real(wp) :: maxlon
      real(wp) :: maxalt
      real(wp) :: minlat
      real(wp) :: minlon
      real(wp) :: minalt
      real(wp) :: pmax
      real(wp) :: pmin
      real(wp) :: re
      real(wp) :: rp

      integer(ip) :: maxrel
      integer(ip) :: minrel

!     Constants (SPICELIB computed them on the first call).
!
      real(wp), parameter :: pi2 = twopi

      if ( ctx%failed() ) return

!
!     Unpack the shape parameters. Set the polar axis length for
!     later use.
!
      re = corpar(1)
      f  = corpar(2)
      rp = re * ( 1.0_wp - f )

!
!     Assume the point is outside to start. This allows us
!     to skip setting INSIDE when we find a boundary test
!     failure.
!
      inside = .false.
!
!     Compare coordinates of the input point and the segment
!     bounds. Deal with altitude last, since it involves the
!     most work. We may be able to exit before performing the
!     altitude tests.
!
      if ( exclud /= latidx ) then
!
!        Compare the point's latitude to the segment's latitude bounds.
!
         minlat = max( bounds(lower, latidx) - angmrg, -halfpi )
         maxlat = min( bounds(upper, latidx) + angmrg,  halfpi )

         call zzpdcmpl ( ctx, re, f, p, minlat, minrel )
         call zzpdcmpl ( ctx, re, f, p, maxlat, maxrel )

         if ( ctx%failed() ) return

         if (      ( minrel == lt ) &
              .or. ( maxrel == gt )  ) then
!
!           The point's latitude is outside of the segment's range.
!
            return

         end if

      end if

!
!     Move the longitude of the input point into the interval
!
!        [ MINLON, MAXLON ]
!
!     if necessary and if possible.
!
      if ( exclud /= lonidx ) then
!
!        Put the local longitude bounds in order, if necessary.
!
         call zznrmlon ( ctx, bounds(lower,lonidx),  bounds(upper,lonidx), &
                         angmrg,       minlon,  maxlon               )
!
!        Compare the point's longitude to the segment's longitude
!        bounds.
!
         loclon = lon

         if ( lon < ( minlon - lonali ) ) then
!
!           If the point's longitude is less than the segment's
!           longitude by more than a small margin, shift the longitude
!           right by 2*pi.

            loclon = lon + pi2

         else if ( lon > ( maxlon + lonali ) ) then
!
!           If the point's longitude is greater than the segment's
!           longitude by more than a small margin, shift the longitude
!           left by 2*pi.

            loclon = lon - pi2

         end if

         if (        ( loclon < (minlon-angmrg) ) &
                .or. ( loclon > (maxlon+angmrg) )  ) then
!
!           The point's longitude, adjusted if necessary for
!           comparison, is outside of the segment's range.
!
            return

         end if

      end if

      if ( exclud /= altidx ) then
!
!        Extract altitude bounds from the segment descriptor.
!
         minalt = bounds(lower, altidx)
         maxalt = bounds(upper, altidx)
!
!        Find the semi-axes of the bounding spheroids.
!
         if ( f >= 0.0_wp ) then
!
!           This is the oblate case. Get the semi-axis lengths
!           for the inner and outer bounding spheroids.
!
            call zzellbds ( ctx, re,   rp,   maxalt, minalt, &
                            emax, pmax, emin,   pmin   )

         else
!
!           This is the prolate case. RP is the longer axis. Get the
!           semi-axis lengths for the inner and outer bounding
!           spheroids.
!
!           In this call, we'll store the radii associated with
!           the longer axis in PMAX and PMIN.
!
            call zzellbds ( ctx, rp,   re,   maxalt, minalt, &
                            pmax, emax, pmin,   emin   )

         end if

!
!        Compute the input point's level surface parameters
!        for the inner and outer bounding ellipsoids. Do these
!        computations one at a time, so the second one can be
!        skipped if the first one shows the point is outside
!        the outer ellipsoid.
!
         level = ( p(1)/emax )**2 + ( p(2)/emax )**2 + ( p(3)/pmax )**2

         if ( level > 1.0_wp ) then
!
!           The point is outside of the outer bounding ellipsoid.
!
            return

         end if

         level = ( p(1)/emin )**2 + ( p(2)/emin )**2 + ( p(3)/pmin )**2

         if ( level < 1.0_wp ) then
!
!           The point is inside the inner bounding ellipsoid, which
!           implies it is outside of the segment's boundaries.
!
            return

         end if

      end if

!
!     Getting to this point means the input point is inside
!     the segment. Being on the boundary counts as inside.
!
      inside = .true.

      return
      end subroutine zzinpdt0

      !> Find nearest intersection to ray's vertex of ray and
      !> rectangular volume element. If the vertex is inside
      !> the element, the vertex is considered to be the solution.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     VERTEX,
      !>     RAYDIR     are, respectively, the vertex and direction vector of
      !>                the ray to be used in the intercept computation.
      !>
      !>                Both the vertex and ray direction must be represented
      !>                in the reference frame of the segment to which the
      !>                volume element boundaries correspond. The vertex is
      !>                considered to be an offset from the center of the
      !>                reference frame associated with the segment.
      !>
      !>     BOUNDS     is a 2x3 array containing the bounds of a rectangular
      !>                volume element. Normally this is the coverage boundary
      !>                of a DSK segment. In the element
      !>
      !>                   BOUNDS(I,J)
      !>
      !>                J is the coordinate index. J is one of
      !>
      !>                   { 1, 2, 3 }
      !>
      !>                I is the bound index.
      !>
      !>                   I = 1   ->   lower bound
      !>                   I = 2   ->   upper bound
      !>
      !>## Detailed Output
      !>
      !>     XPT        is the intercept of the ray on the boundary of the
      !>                input volume element, if such an intercept exists. If
      !>                the ray's vertex is inside the element, XPT is set
      !>                equal to the vertex. XPT is valid if and only if FOUND
      !>                is .TRUE.
      !>
      !>                XPT is expressed in the reference frame associated
      !>                with the inputs VERTEX and RAYDIR. XPT represents
      !>                an offset from the origin of the coordinate system.
      !>
      !>                XPT is valid only if NXPTS is set to 1.
      !>
      !>     NXPTS      is the number of intercept points of the ray and
      !>                the volume element.
      !>
      !>                Currently there are only two possible values for
      !>                NXPTS:
      !>
      !>                   1 for an intersection
      !>                   0 for no intersection
      !>
      !>                If the vertex is inside the element, NXPTS is
      !>                set to 1.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1) If the minimum value of any coordinate exceeds the maximum,
      !>        the error will be signaled by a routine in the call tree of
      !>        this routine.
      !>
      !>## Files
      !>
      !>     None. However, the input segment boundaries normally have
      !>     been obtained from a loaded DSK file.
      !>
      !>## Particulars
      !>
      !>     This routine sits on top of data DSK type-specific ray-segment
      !>     intercept routines such as DSKX02.
      !>
      !>## Examples
      !>
      !>     See usage in ZZDSKBUX.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 01-MAR-2016 (NJB)
      module subroutine zzrytrec ( ctx, vertex, raydir, bounds, margin, nxpts, xpt )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: vertex ( 3 )  !! Ray's vertex.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      real(wp), intent(in) :: bounds ( 2, 3 )  !! Bounds of rectangular volume element.
      real(wp), intent(in) :: margin  !! Margin used for element expansion.
      integer(ip), intent(out) :: nxpts  !! Number of intercept points.
      real(wp), intent(out) :: xpt    ( 3 )  !! Intercept.

      integer(ip), parameter :: none = 0

!
!     Element boundary indices:
!
      integer(ip), parameter :: lower = 1

      integer(ip), parameter :: upper = 2

      real(wp) :: boxori ( 3 )
      real(wp) :: extent ( 3 )
      real(wp) :: delta  ( 3 )
      real(wp) :: l      ( 3 )

      integer(ip) :: i

      logical :: found
      logical :: inside

      if ( ctx%failed() ) return

!
!     Compute the original volume edge lengths from the coordinate
!     bounds.
!
      do i = 1, 3

         l(i) = bounds(upper, i) - bounds(lower, i)

         if ( l(i) <= 0.0_wp ) then

            call ctx%setmsg ( 'Coordinate # bounds were #:#; bounds ' &
            //            'must be strictly increasing.'           )
            call ctx%errint ( '#',  i                                  )
            call ctx%errdp  ( '#',  bounds(lower,i)                    )
            call ctx%errdp  ( '#',  bounds(upper,i)                    )
            call ctx%sigerr ( 'SPICE(BADCOORDBOUNDS)'                  )
            return

         end if

      end do

!
!     Determine whether the vertex is inside the element.
!     Use double the margin for this test, since we don't
!     want to have false negative tests for rays having
!     vertices lying on the expanded element boundary.
!
      nxpts = 0

      call zzinrec ( ctx, vertex, bounds, 2*margin, none, inside )

      if ( inside ) then
!
!        We know the answer.
!
         nxpts = 1

         xpt = vertex

         return

      end if

!
!     Expand the box using the specified margin.
!
      do i = 1, 3

         delta(i)  = margin * abs( l(i) )

         boxori(i) = bounds(lower,i) - delta(i)

         extent(i) = l(i) + ( 2*delta(i) )

      end do

!
!     Find the ray-surface intercept on the expanded element,
!     if the intercept exists.
!
      call zzraybox ( ctx, vertex, raydir, boxori, extent, xpt, found )

      if ( found ) then
         nxpts = 1
      end if

      return
      end subroutine zzrytrec

      !> Create a bounding box for a DSK segment volume element.
      !> The outputs are the box's center and radius. The center
      !> is relative to the segment's frame center.
      !>
      !>## Detailed Input
      !>
      !>     DSKDSC     is the DSK descriptor for the segment of interest.
      !>
      !>## Detailed Output
      !>
      !>     BOXCTR     is a double precision 3-vector representing the center
      !>                of a box tangent to and containing the volume
      !>                specified by the coordinate system, coordinate
      !>                parameters, if any, and bounds specified in the DSK
      !>                segment descriptor.
      !>
      !>                The box bounds the surface specified by the input
      !>                descriptor; the offset between the center of the
      !>                segment's reference frame and the segment's central
      !>                body plays no role.
      !>
      !>     MAXR       is the radius of the sphere that circumscribes the
      !>                box. RADIUS is equal to the length of a line segment
      !>                connecting the center of the box to any corner.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If coordinate system specified in the descriptor is not
      !>         recognized, the error SPICE(NOTSUPPORTED) is signaled.
      !>
      !>     2)  Any errors that occur while deriving the bounding box
      !>         will be signaled by routines in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine consolidates the logic branch needed to compute a
      !>     bounding box for a DSK segment. Using this routine can eliminate
      !>     the need to test higher-level routines using each type of
      !>     coordinate system.
      !>
      !>     The box bounds the surface specified by the input descriptor; the
      !>     offset between the center of the segment's reference frame and
      !>     the segment's central body plays no role.
      !>
      !>     To compute a body's DSK bounding sphere, centered at the body,
      !>     and taking into account all loaded segments, use ZZDSKSPH.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 17-JUN-2016 (NJB)
      module subroutine zzsegbox ( ctx, dskdsc, boxctr, maxr )
      use pepper_kinds, only: ip, wp
      use pepper_inc_dskdsc
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: dskdsc ( * )  !! DSK segment descriptor.
      real(wp), intent(out) :: boxctr ( 3 )  !! Center of bounding box.
      real(wp), intent(out) :: maxr  !! Radius of box.
      real(wp) :: l1
      real(wp) :: l2
      real(wp) :: l3

      integer(ip) :: corsys

      if ( ctx%failed() ) return

      corsys = nint( dskdsc(sysidx) )

      if ( corsys == latsys ) then

         call zzlatbox ( ctx, dskdsc(mn1idx), boxctr, l1, &
                         l2,             l3,     maxr )

      else if ( corsys == recsys ) then

         call zzrecbox ( ctx, dskdsc(mn1idx), boxctr, l1, &
                         l2,             l3,     maxr )

      else if ( corsys == pdtsys ) then

         call zzpdtbox ( ctx, dskdsc(mn1idx), dskdsc(paridx), boxctr, &
                         l1,             l2,             l3, &
                         maxr                                   )

      else

         call ctx%setmsg ( 'Coordinate system # is not supported.' )
         call ctx%errint ( '#',  corsys                            )
         call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                   )
         return

      end if

      return
      end subroutine zzsegbox

      !> Map a surface name and body ID code to a surface ID code.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines.  Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     SRFNAM     is the name of surface to be translated.
      !>
      !>     BODYID     is the ID code of a body with which the surface
      !>                designated by SRFNAM is associated.
      !>
      !>## Detailed Output
      !>
      !>     SURFID     is the surface ID code associated with the input
      !>                surface name and body ID code.
      !>
      !>                If multiple assignments for the input surface
      !>                name and body ID are present in the kernel pool,
      !>                the latest one is used to determine SURFID.
      !>
      !>     FOUND      is a logical flag that is .TRUE. if the inputs
      !>                were mapped to a surface ID code and .FALSE.
      !>                otherwise.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If an error occurs when the data structures of this package
      !>         are initialized, it will be signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>## Files
      !>
      !>     Surface-to-name mappings may be defined at run time by loading
      !>     text kernels containing kernel variable assignments of the form
      !>
      !>        NAIF_SURFACE_NAME += ( <surface name 1>, ... )
      !>        NAIF_SURFACE_CODE += ( <surface code 1>, ... )
      !>        NAIF_SURFACE_BODY += ( <body code 1>,    ... )
      !>
      !>     Here the set of the three Ith list items on the right hand side
      !>     of the three assignments define the Ith surface name/ID mapping.
      !>
      !>     The same effect can be achieved using assignments formatted as
      !>     follows:
      !>
      !>        NAIF_SURFACE_NAME += <surface name 1>
      !>        NAIF_SURFACE_CODE += <surface code 1>
      !>        NAIF_SURFACE_BODY += <body code 1>
      !>
      !>        NAIF_SURFACE_NAME += <surface name 2>
      !>        NAIF_SURFACE_CODE += <surface code 2>
      !>        NAIF_SURFACE_BODY += <body code 2>
      !>
      !>           ...
      !>
      !>     Note the use of the
      !>
      !>        +=
      !>
      !>     operator; this operator appends to rather than overwrites the
      !>     kernel variable named on the left hand side of the assignment.
      !>
      !>## Particulars
      !>
      !>     This routine maps pairs of surface names and body ID codes to
      !>     surface ID codes. It relies on the mapping variables in the
      !>     kernel pool.
      !>
      !>     On the first pass through this routine, this routine
      !>     initializes the shared data structures of this package,
      !>     if the initialization has not already been done.
      !>
      !>## Examples
      !>
      !>     See the routines
      !>
      !>        SRFS2C
      !>        SRFSCC
      !>
      !>## Restrictions
      !>
      !>     This routine must not be called by user applications.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>     B.V. Semenov    (JPL)
      !>     E.D. Wright     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 01-APR-2016 (NJB) (EDW) (BVS)
      module subroutine zzsrfn2c ( ctx, srfnam, bodyid, surfid, found )
      use pepper_kinds, only: ip
      use pepper_hash, only: name_hash
      use pepper_strings, only: cmprss, ljucrs
      use pepper_inc_srftrn
      use pepper_inc_zzctr
      use pepper_inc_zzsrftrn
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: bodyid  !! Body ID code.
      character(*), intent(in) :: srfnam  !! Surface name.
      integer(ip), intent(out) :: surfid  !! Surface ID code.
      logical, intent(out) :: found  !! Found flag.
      integer(ip) :: idx
      integer(ip) :: nkvar
      integer(ip) :: node
      integer(ip) :: lookat
      logical :: lupdte
      if ( .not. allocated ( ctx%zzsrftrn_state ) ) allocate ( ctx%zzsrftrn_state )
      associate ( srf => ctx%zzsrftrn_state%srf, &
                  polctr => ctx%zzsrftrn_state%polctr, &
                  srfctr => ctx%zzsrftrn_state%srfctr, &
                  pass1 => ctx%zzsrftrn_state%pass1 )
      if ( ctx%failed() ) return

!
!     No result has been found.
!
      found = .false.

      if ( pass1 ) then
!
!        Initialize the surface kernel variable update counter
!        and the local pool counter. Note that this routine
!        is a "subsystem" as seen by its callers and a "user"
!        with respect to the kernel pool. Hence the different
!        initializations.
!
         call zzctrsin ( ctx, srfctr )
         call zzctruin ( ctx, polctr )

!
!        Initialize local data structures. The first instance of this
!        call also sets a watch on the surface mapping kernel
!        variables.
!
         call zzsrfker ( ctx, srf )
!
!        Sync POLCTR with the kernel pool counter.
!
         call zzcvpool ( ctx, 'ZZSRFTRN', polctr, lupdte )

         if ( ctx%failed() ) return

         pass1  = .false.

      end if

!
!     Determine whether the data structures need to be updated
!     due to a change in the kernel pool contents.
!
      call zzcvpool ( ctx, 'ZZSRFTRN', polctr, lupdte )

      if ( lupdte ) then
!
!        Conservatively increment the ZZSRFTRN state counter in
!        expectation of successful update.
!
         call zzctrinc ( ctx, srfctr )
!
!        Initialize local data structures.
!
         call zzsrfker ( ctx, srf )

         if ( ctx%failed() ) return

      end if

!
!     No translation can be done if the surface mapping variables
!     are not in the pool.
!
      if ( .not. srf%extker ) return

!
!     Get a "normalized" copy of the input name: left-justified,
!     compressed, upper case.
!
      block
         character(len(srfnam)) :: buf
         call ljucrs ( 1, srfnam, buf )
         idx = srf%name_index ( trim(buf), bodyid )
      end block
      found = idx > 0
      if ( found ) surfid = srf%ids(idx)

      return
      end associate
      end subroutine zzsrfn2c

      !> Map a surface ID code and body ID code to a surface name.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
