      !>-    SPICELIB Version 1.0.0, 01-APR-2016 (NJB) (EDW) (BVS)
      module subroutine zzsrfc2n ( ctx, surfid, bodyid, srfnam, found )
      use pepper_kinds, only: ip
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: bodyid  !! Body ID code.
      character(*), intent(out) :: srfnam  !! Surface name.
      integer(ip), intent(in) :: surfid  !! Surface ID code.
      logical, intent(out) :: found  !! Found flag.
      character(:), allocatable :: name
!
!     PEPPER: the work is done by SURFACE_NAME, which returns the name
!     at its full length.
!
      call surface_name ( ctx, surfid, bodyid, name, found )
      if ( found ) srfnam = name
      end subroutine zzsrfc2n

      !> The name of a surface from its ID code and body, of any length
      !> (PEPPER; the body of [[zzsrfc2n]], which truncates to its argument's
      !> length). Unlike [[srfc2s]], a surface without a name gives an empty
      !> NAME, not the code as a string.
      module subroutine surface_name ( ctx, code, body, name, found )
      use pepper_kinds, only: ip
      use pepper_hash, only: name_hash
      use pepper_inc_srftrn
      use pepper_inc_zzctr
      use pepper_inc_zzsrftrn
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: code  !! the surface ID code
      integer(ip), intent(in) :: body  !! the ID code of the body of the surface
      character(:), allocatable, intent(out) :: name  !! the surface name (empty if not found)
      logical, intent(out) :: found  !! the surface has a name
      integer(ip) :: idx
      integer(ip) :: nkvar
      integer(ip) :: node
      integer(ip) :: lookat
      logical :: lupdte
      name  = ''
      found = .false.
      if ( .not. allocated ( ctx%zzsrftrn_state ) ) allocate ( ctx%zzsrftrn_state )
      associate ( srf => ctx%zzsrftrn_state%srf, &
                  polctr => ctx%zzsrftrn_state%polctr, &
                  srfctr => ctx%zzsrftrn_state%srfctr, &
                  pass1 => ctx%zzsrftrn_state%pass1 )
      if ( ctx%failed() ) return

!
!     No result has been found.
!
      found = .false.

      if ( pass1 ) then
!
!        Initialize the surface kernel variable update counter
!        and the local pool counter. Note that this routine
!        is a "subsystem" as seen by its callers and a "user"
!        with respect to the kernel pool. Hence the different
!        initializations.
!
         call zzctrsin ( ctx, srfctr )
         call zzctruin ( ctx, polctr )

!
!        Initialize local data structures. The first instance of this
!        call also sets a watch on the surface mapping kernel
!        variables.
!
         call zzsrfker ( ctx, srf )
!
!        Sync SRFCTR with the kernel pool counter.
!
         call zzcvpool ( ctx, 'ZZSRFTRN', polctr, lupdte )

         if ( ctx%failed() ) return

         pass1  = .false.

      end if

!
!     Determine whether the data structures need to be updated
!     due to a change in the kernel pool contents.
!
      call zzcvpool ( ctx, 'ZZSRFTRN', polctr, lupdte )

      if ( lupdte ) then
!
!        Conservatively increment the ZZSRFTRN state counter in
!        expectation of successful update.
!
         call zzctrinc ( ctx, srfctr )

!
!        Initialize local data structures.
!
         call zzsrfker ( ctx, srf )

         if ( ctx%failed() ) return

      end if

!
!     No translation can be done if the surface mapping variables
!     are not in the pool.
!
      if ( .not. srf%extker ) return

!
!     Find the hash value of the squished input name.
!
      idx   = srf%id_index ( code, body )
      found = idx > 0
      if ( found ) name = srf%names(idx)%s

      return
      end associate
      end subroutine surface_name

      !> Check a user counter against the surface mapping counter
      !> maintained by this package. Indicate whether the caller
      !> needs to update variables associated with the user counter.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines.  Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     USRCTR     is a counter passed in by a calling routine. Normally
      !>                USRCTR would be used to enable the application calling
      !>                this routine to determine whether local associations
      !>                of surface names and IDs are up to date.
      !>
      !>## Detailed Output
      !>
      !>     USRCTR     is the user counter, updated if necessary to match the
      !>                counter maintained by this package.
      !>
      !>     UPDATE     is a logical flag indicating whether USRCTR was
      !>                updated.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If an error occurs when the data structures of this package
      !>         are initialized, it will be signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>## Files
      !>
      !>     Surface-to-name mappings may be defined at run time by loading
      !>     text kernels containing kernel variable assignments of the form
      !>
      !>        NAIF_SURFACE_NAME += ( <surface name 1>, ... )
      !>        NAIF_SURFACE_CODE += ( <surface code 1>, ... )
      !>        NAIF_SURFACE_BODY += ( <body code 1>,    ... )
      !>
      !>     Here the set of the three Ith list items on the right hand side
      !>     of the three assignments define the Ith surface name/ID mapping.
      !>
      !>     The same effect can be achieved using assignments formatted as
      !>     follows:
      !>
      !>        NAIF_SURFACE_NAME += <surface name 1>
      !>        NAIF_SURFACE_CODE += <surface code 1>
      !>        NAIF_SURFACE_BODY += <body code 1>
      !>
      !>        NAIF_SURFACE_NAME += <surface name 2>
      !>        NAIF_SURFACE_CODE += <surface code 2>
      !>        NAIF_SURFACE_BODY += <body code 2>
      !>
      !>           ...
      !>
      !>     Note the use of the
      !>
      !>        +=
      !>
      !>     operator; this operator appends to rather than overwrites the
      !>     kernel variable named on the left hand side of the assignment.
      !>
      !>## Particulars
      !>
      !>     This routine allows SPICELIB routines to determine whether the
      !>     the surface mapping has been updated.
      !>
      !>     On every pass through this routine, this routine tests whether
      !>     the local mapping data structures need to be updated. If they do,
      !>     the data structures are re-initialized using the surface mapping
      !>     variables, if these are present in the kernel pool.
      !>
      !>## Examples
      !>
      !>     See use of this routine in SPICELIB high-level geometry
      !>     routines such as
      !>
      !>        ILLUMF
      !>        SINCPT
      !>        SUBPNT
      !>
      !>## Restrictions
      !>
      !>     This routine must not be called by user applications.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>     B.V. Semenov    (JPL)
      !>     E.D. Wright     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 01-APR-2016 (NJB) (EDW) (BVS)
      module subroutine zzsrftrk ( ctx, usrctr, update )
      use pepper_kinds, only: ip
      use pepper_hash, only: name_hash
      use pepper_inc_srftrn
      use pepper_inc_zzctr
      use pepper_inc_zzsrftrn
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(inout) :: usrctr ( 2 )  !! User counter.
      logical, intent(out) :: update  !! Update flag.
      integer(ip) :: nkvar
      logical :: lupdte
      if ( .not. allocated ( ctx%zzsrftrn_state ) ) allocate ( ctx%zzsrftrn_state )
      associate ( srf => ctx%zzsrftrn_state%srf, &
                  polctr => ctx%zzsrftrn_state%polctr, &
                  srfctr => ctx%zzsrftrn_state%srfctr, &
                  pass1 => ctx%zzsrftrn_state%pass1 )
      if ( ctx%failed() ) return

      if ( pass1 ) then
!
!        Check in because ZZSRFKER can fail.
!
!        Initialize the surface kernel variable update counter
!        and the local pool counter. Note that this routine
!        is a "subsystem" as seen by its callers and a "user"
!        with respect to the kernel pool. Hence the different
!        initializations.
!
         call zzctrsin ( ctx, srfctr )
         call zzctruin ( ctx, polctr )

!
!        Initialize local data structures. The first instance of this
!        call also sets a watch on the surface mapping kernel
!        variables.
!
         call zzsrfker ( ctx, srf )
!
!        Sync SRFCTR with the kernel pool counter.
!
         call zzcvpool ( ctx, 'ZZSRFTRN', polctr, lupdte )
!
!        Check out here since this routine doesn't check out
!        before its normal exit.
!

         if ( ctx%failed() ) return

         pass1  = .false.

      end if

!
!     Check for updates to the kernel pool variables.
!
      call zzcvpool ( ctx, 'ZZSRFTRN', polctr, lupdte )

      if ( lupdte ) then
!
!        Check in because ZZSRFKER can fail.
!

!
!        Conservatively increment the ZZSRFTRN state counter in
!        expectation of successful update.
!
         call zzctrinc ( ctx, srfctr )

!
!        Update kernel pool mapping lists and hashes.
!
         call zzsrfker ( ctx, srf )

         if ( ctx%failed() ) return

      end if

!
!     Check the input counter against the ZZSRFTRN counter;
!     sync the user counter.
!
      call zzctrchk ( ctx, srfctr, usrctr, update )

      return
      end associate
      end subroutine zzsrftrk

      !> Find the intersection of a triaxial ellipsoid and a plane.
      !>
      !>## Detailed Input
      !>
      !>     A,
      !>     B,
      !>     C        are the lengths of the semi-axes of a triaxial
      !>              ellipsoid. The ellipsoid is centered at the
      !>              origin and oriented so that its axes lie on the
      !>              x, y and z axes.  A, B, and C are the lengths of
      !>              the semi-axes that point in the x, y, and z
      !>              directions respectively.
      !>
      !>     PLANE    is a SPICE plane.
      !>
      !>## Detailed Output
      !>
      !>     ELLIPS   is the SPICE ellipse formed by the intersection
      !>              of the input plane and ellipsoid. ELLIPS will
      !>              represent a single point if the ellipsoid and
      !>              plane are tangent.
      !>
      !>              If the intersection of the ellipsoid and plane is
      !>              empty, ELLIPS is not modified.
      !>
      !>     FOUND    is .TRUE. if and only if the intersection of the
      !>              ellipsoid and plane is non-empty.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If any of the lengths of the semi-axes of the input ellipsoid
      !>         are non-positive, the error SPICE(DEGENERATECASE) is
      !>         signaled. ELLIPS is not modified. FOUND is set to .FALSE.
      !>
      !>     2)  If the input plane in invalid, in other words, if the input
      !>         plane as the zero vector as its normal vector, the error
      !>         SPICE(INVALIDPLANE) is signaled. ELLIPS is not modified.
      !>         FOUND is set to .FALSE.
      !>
      !>     3)  If the input plane and ellipsoid are very nearly tangent,
      !>         roundoff error may cause this routine to give unreliable
      !>         results.
      !>
      !>     4)  If the input plane and ellipsoid are precisely tangent, the
      !>         intersection is a single point. In this case, the output
      !>         ellipse is degenerate, but FOUND will still have the value
      !>         .TRUE. You must decide whether this output makes sense for
      !>         your application.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     An ellipsoid and a plane can intersect in an ellipse, a single
      !>     point, or the empty set.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Suppose we wish to find the limb of a body, as observed from
      !>        location LOC in body-fixed coordinates. The SPICELIB routine
      !>        EDLIMB solves this problem. Here's how INEDPL is used in
      !>        that solution.
      !>
      !>        We assume LOC is outside of the body. The body is modeled as
      !>        a triaxial ellipsoid with semi-axes of length A, B, and C.
      !>
      !>        The notation
      !>
      !>           < X, Y >
      !>
      !>        indicates the inner product of the vectors X and Y.
      !>
      !>        The limb lies on the plane defined by
      !>
      !>           < X,  N >  =  1,
      !>
      !>        where the vector N is defined as
      !>
      !>                       2              2              2
      !>           ( LOC(1) / A ,   LOC(2) / B ,   LOC(3) / C  ).
      !>
      !>        The assignments
      !>
      !>           N(1) = LOC(1) / ( A*A )
      !>           N(2) = LOC(2) / ( B*B )
      !>           N(3) = LOC(3) / ( C*C )
      !>
      !>        and the calls
      !>
      !>           CALL NVC2PL ( N,  1.0D0,  PLANE )
      !>
      !>           CALL INEDPL ( A,  B,  C,  PLANE,  LIMB,  FOUND )
      !>
      !>           CALL EL2CGV ( LIMB, CENTER, SMAJOR, SMINOR )
      !>
      !>        will return the center and semi-axes of the limb.
      !>
      !>        How do we know that  < X, N > = 1  for all X on the limb?
      !>        This is because all limb points X satisfy
      !>
      !>           < LOC - X, SURFNM(X) >  =  0,
      !>
      !>        where SURFNM(X) is a surface normal at X.  SURFNM(X) is
      !>        parallel to the vector
      !>
      !>                          2            2            2
      !>           V = (  X(1) / A ,   X(2) / B ,   X(3) / C   )
      !>
      !>        so we have
      !>
      !>           < LOC - X, V >  =  0,
      !>
      !>           < LOC, V >      =  < X, V >  =  1  (from the original
      !>                                               ellipsoid
      !>                                               equation);
      !>        and finally
      !>
      !>           < X,   N >      =  1,
      !>
      !>        where N is as defined above.
      !>
      !>     2) We'd like to find the apparent limb of Jupiter, corrected for
      !>        light time and stellar aberration, as seen from JUNO
      !>        spacecraft's position at a given UTC time.
      !>
      !>        This example is equivalent to the one in EDLIMB, but it uses
      !>        INEDPL to compute the limb.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: inedpl_ex2.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                           Contents
      !>              ---------                           --------
      !>              juno_rec_160522_160729_160909.bsp   JUNO s/c ephemeris
      !>              pck00010.tpc                        Planet orientation
      !>                                                  and radii
      !>              naif0012.tls                        Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'juno_rec_160522_160729_160909.bsp',
      !>                                  'pck00010.tpc',
      !>                                  'naif0012.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM INEDPL_EX2
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local parameters.
      !>C
      !>      CHARACTER*(*)           UTCSTR
      !>      PARAMETER             ( UTCSTR = '2016 Jul 14 19:45:00' )
      !>
      !>      INTEGER                 UBEL
      !>      PARAMETER             ( UBEL =   9 )
      !>
      !>      INTEGER                 UBPL
      !>      PARAMETER             ( UBPL =   4 )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      DOUBLE PRECISION        CENTER ( 3    )
      !>      DOUBLE PRECISION        ET
      !>      DOUBLE PRECISION        JPOS   ( 3    )
      !>      DOUBLE PRECISION        LIMB   ( UBEL )
      !>      DOUBLE PRECISION        LT
      !>      DOUBLE PRECISION        PLANE  ( UBPL )
      !>      DOUBLE PRECISION        RAD    ( 3    )
      !>      DOUBLE PRECISION        SMAJOR ( 3    )
      !>      DOUBLE PRECISION        SMINOR ( 3    )
      !>      DOUBLE PRECISION        SCPOS  ( 3    )
      !>      DOUBLE PRECISION        TIPM   ( 3, 3 )
      !>
      !>      INTEGER                 N
      !>
      !>      LOGICAL                 FOUND
      !>
      !>C
      !>C     Load the required kernels.
      !>C
      !>      CALL FURNSH ( 'inedpl_ex2.tm' )
      !>
      !>C
      !>C     Find the viewing point in Jupiter-fixed coordinates. To
      !>C     do this, find the apparent position of Jupiter as seen
      !>C     from the spacecraft in Jupiter-fixed coordinates and
      !>C     negate this vector. In this case we'll use light time
      !>C     and stellar aberration corrections to arrive at the
      !>C     apparent limb. JPOS is the Jupiter's position as seen
      !>C     from the spacecraft.  SCPOS is the spacecraft's position
      !>C     relative to Jupiter.
      !>C
      !>      CALL STR2ET ( UTCSTR,    ET )
      !>      CALL SPKPOS ( 'JUPITER', ET, 'J2000', 'LT+S', 'JUNO',
      !>     .               JPOS,     LT                         )
      !>
      !>      CALL VMINUS ( JPOS, SCPOS )
      !>
      !>C
      !>C     Get Jupiter's semi-axis lengths...
      !>C
      !>      CALL BODVRD ( 'JUPITER', 'RADII', 3, N, RAD )
      !>
      !>C
      !>C     ...and the transformation from J2000 to Jupiter
      !>C     equator and prime meridian coordinates. Note that we
      !>C     use the orientation of Jupiter at the time of
      !>C     emission of the light that arrived at the
      !>C     spacecraft at time ET.
      !>C
      !>      CALL PXFORM ( 'J2000', 'IAU_JUPITER', ET-LT, TIPM )
      !>
      !>C
      !>C     Transform the spacecraft's position into Jupiter-
      !>C     fixed coordinates.
      !>C
      !>      CALL MXV ( TIPM, SCPOS, SCPOS )
      !>
      !>C
      !>C     Normalize the position to factors of the radii.
      !>C
      !>      SCPOS(1) = SCPOS(1) / RAD(1)**2
      !>      SCPOS(2) = SCPOS(2) / RAD(2)**2
      !>      SCPOS(3) = SCPOS(3) / RAD(3)**2
      !>
      !>C
      !>C     Find the apparent limb.  LIMB is a SPICE ellipse
      !>C     representing the limb.
      !>C
      !>      CALL NVC2PL ( SCPOS,  1.0D0,  PLANE  )
      !>      CALL INEDPL ( RAD(1), RAD(2), RAD(3),
      !>     .              PLANE,  LIMB,   FOUND  )
      !>
      !>C
      !>C     CENTER, SMAJOR, and SMINOR are the limb's center,
      !>C     semi-major axis of the limb, and a semi-minor axis
      !>C     of the limb.  We obtain these from LIMB using the
      !>C     SPICELIB routine EL2CGV ( Ellipse to center and
      !>C     generating vectors ).
      !>C
      !>      CALL EL2CGV ( LIMB, CENTER, SMAJOR, SMINOR )
      !>
      !>C
      !>C     Output the structure components.
      !>C
      !>      WRITE(*,'(A)') 'Apparent limb of Jupiter as seen '
      !>     .            // 'from JUNO:'
      !>      WRITE(*,'(2A)')       '   UTC time       : ', UTCSTR
      !>      WRITE(*,'(A,3F14.6)') '   Semi-minor axis:', SMINOR
      !>      WRITE(*,'(A,3F14.6)') '   Semi-major axis:', SMAJOR
      !>      WRITE(*,'(A,3F14.6)') '   Center         :', CENTER
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Apparent limb of Jupiter as seen from JUNO:
      !>           UTC time       : 2016 Jul 14 19:45:00
      !>           Semi-minor axis:  12425.547643  -5135.572410  65656.053303
      !>           Semi-major axis:  27305.667297  66066.222576      0.000000
      !>           Center         :    791.732472   -327.228993   -153.408849
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     K.R. Gehringer     (JPL)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.3.0, 24-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>        Added complete code example.
      !>
      !>-    SPICELIB Version 1.2.0, 16-NOV-2005 (NJB)
      !>
      !>        Bug fix: error detection for case of invalid input plane was
      !>        added.
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in VSCL calls.
      !>
      !>-    SPICELIB Version 1.1.0, 11-JUL-1995 (KRG)
      !>
      !>        Removed potential numerical precision problems that could be
      !>        caused by using a REAL constant in a double precision
      !>        computation. The value 1.0 was replaced with the value 1.0D0
      !>        in the following three lines:
      !>
      !>           DSTORT(1) = 1.0 / A
      !>           DSTORT(2) = 1.0 / B
      !>           DSTORT(3) = 1.0 / C
      !>
      !>        Also changed was a numeric constant from 1.D0 to the
      !>        equivalent, but more aesthetically pleasing 1.0D0.
      !>
      !>-    SPICELIB Version 1.0.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.0.0, 02-NOV-1990 (NJB)
      module subroutine inedpl ( ctx, a, b, c, plane, ellips, found )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: pl2nvc, pl2psv, vnorm
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: ubel = 9
      integer(ip), parameter :: ubpl = 4
      real(wp), intent(in) :: a  !! Length of ellipsoid semi-axis lying on the x-axis.
      real(wp), intent(in) :: b  !! Length of ellipsoid semi-axis lying on the y-axis.
      real(wp), intent(in) :: c  !! Length of ellipsoid semi-axis lying on the z-axis.
      real(wp), intent(in) :: plane  ( ubpl )  !! Plane that intersects ellipsoid.
      real(wp), intent(out) :: ellips ( ubel )  !! Intersection ellipse, when FOUND is .TRUE.
      logical, intent(out) :: found  !! Flag indicating whether ellipse was found.



      real(wp) :: center ( 3 )
      real(wp) :: const
      real(wp) :: dplane ( ubpl )
      real(wp) :: dist
      real(wp) :: dstort ( 3 )
      real(wp) :: invdst ( 3 )
      real(wp) :: maxrad
      real(wp) :: normal ( 3 )
      real(wp) :: point  ( 3 )
      real(wp) :: rcircl
      real(wp) :: span1  ( 3 )
      real(wp) :: span2  ( 3 )
      real(wp) :: vec1   ( 3 )
      real(wp) :: vec2   ( 3 )

      integer(ip) :: i

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     We don't want to worry about flat ellipsoids:
!
      if (         ( a <= 0.0_wp ) &
            .or.   ( b <= 0.0_wp ) &
            .or.   ( c <= 0.0_wp )   )   then

         found = .false.

         call ctx%setmsg ( 'Semi-axes: A = #,  B = #,  C = #.'  )
         call ctx%errdp  ( '#', a                               )
         call ctx%errdp  ( '#', b                               )
         call ctx%errdp  ( '#', c                               )
         call ctx%sigerr ( 'SPICE(DEGENERATECASE)'              )
         return

      end if

!
!     Check input plane for zero normal vector.
!
      call pl2nvc ( plane, normal, const )

      if ( all(normal == 0.0_wp) ) then

         call ctx%setmsg ( 'Normal vector of the input ' // &
                       'PLANE is the zero vector.'   )
         call ctx%sigerr ( 'SPICE(INVALIDPLANE)'         )
         return

      end if

!
!     This algorithm is partitioned into a series of steps:
!
!     1)  Identify a linear transformation that maps the input
!         ellipsoid to the unit sphere.  We'll call this mapping the
!         `distortion' mapping.  Apply the distortion mapping to both
!         the input plane and ellipsoid.  The image of the plane under
!         this transformation will be a plane.
!
!     2)  Find the intersection of the transformed plane and the unit
!         sphere.
!
!     3)  Apply the inverse of the distortion mapping to the
!         intersection ellipse to find the undistorted intersection
!         ellipse.
!

!
!     Step 1:
!
!     Find the image of the ellipsoid and plane under the distortion
!     matrix.  Since the image of the ellipsoid is the unit sphere,
!     only the plane transformation requires any work.
!
!     If the input plane is too far from the origin to possibly
!     intersect the ellipsoid, return now.  This can save us
!     some numerical problems when we scale the plane and ellipsoid.
!
!     The point returned by PL2PSV is the closest point in PLANE
!     to the origin, so its norm gives the distance of the plane
!     from the origin.
!
      call pl2psv  ( plane, point, span1, span2 )

      maxrad = max ( dabs(a), dabs(b), dabs(c) )

      if ( vnorm (point) > maxrad ) then

         found = .false.
         return

      end if

!
!     The distortion matrix and its inverse are
!
!        +-               -+        +-               -+
!        |  1/A   0    0   |        |   A    0    0   |
!        |   0   1/B   0   |,       |   0    B    0   |.
!        |   0    0   1/C  |        |   0    0    C   |
!        +-               -+        +-               -+
!
!     We declare them with length three, since we are going to make
!     use of the diagonal elements only.
!
      dstort(1) = 1.0_wp / a
      dstort(2) = 1.0_wp / b
      dstort(3) = 1.0_wp / c

      invdst(1) =  a
      invdst(2) =  b
      invdst(3) =  c

!
!     Apply the distortion mapping to the input plane.  Applying
!     the distortion mapping to a point and two spanning vectors that
!     define the input plane yields a point and two spanning vectors
!     that define the distorted plane.
!
      do i = 1, 3

         point(i)  =  dstort(i)  *  point(i)
         span1(i)  =  dstort(i)  *  span1(i)
         span2(i)  =  dstort(i)  *  span2(i)

      end do

      call psv2pl ( ctx, point,   span1,  span2,  dplane )

!
!     Step 2:
!
!     Find the intersection of the distorted plane and unit sphere.
!

!
!     The intersection of the distorted plane and the unit sphere
!     may be a circle, a point, or the empty set.  The distance of the
!     plane from the origin determines which type of intersection we
!     have.  If we represent the distorted plane by a unit normal
!     vector and constant, the size of the constant gives us the
!     distance of the plane from the origin.  If the distance is greater
!     than 1, the intersection of plane and unit sphere is empty. If
!     the distance is equal to 1, we have the tangency case.
!
!     The routine PL2PSV always gives us an output point that is the
!     closest point to the origin in the input plane.  This point is
!     the center of the intersection circle.  The spanning vectors
!     returned by PL2PSV, after we scale them by the radius of the
!     intersection circle, become an orthogonal pair of vectors that
!     extend from the center of the circle to the circle itself.  So,
!     the center and these scaled vectors define the intersection
!     circle.
!
      call pl2psv  ( dplane, center, vec1, vec2 )

      dist = vnorm ( center )

      if ( dist > 1.0_wp ) then

         found = .false.
         return

      end if

!
!     Scale the generating vectors by the radius of the intersection
!     circle.
!
      rcircl =  dsqrt (  max(0.0_wp, min(1.0_wp, 1.0_wp - dist**2))  )

      vec1 = rcircl*vec1
      vec2 = rcircl*vec2

!
!     Step 3:
!
!     Apply the inverse distortion to the intersection circle to find
!     the actual intersection ellipse.
!
      do i = 1, 3

         center(i)  =  invdst(i)  *  center(i)
         vec1(i)    =  invdst(i)  *  vec1(i)
         vec2(i)    =  invdst(i)  *  vec2(i)

      end do
!
!     Make an ellipse from the center and generating vectors.
!
      call cgv2el ( ctx, center, vec1, vec2, ellips )

      found  = .true.

      return
      end subroutine inedpl

      !> Project an ellipse onto a plane, orthogonally.
      !>
      !>## Detailed Input
      !>
      !>     ELIN,
      !>     PLANE    are, respectively, a SPICE ellipse and a
      !>              SPICE plane. The geometric ellipse represented
      !>              by ELIN is to be orthogonally projected onto the
      !>              geometric plane represented by PLANE.
      !>
      !>## Detailed Output
      !>
      !>     ELOUT    is a SPICE ellipse that represents the geometric
      !>              ellipse resulting from orthogonally projecting the
      !>              ellipse represented by INEL onto the plane
      !>              represented by PLANE.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input plane is invalid, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     2)  The input ellipse may be degenerate--its semi-axes may be
      !>         linearly dependent. Such ellipses are allowed as inputs.
      !>
      !>     3)  The ellipse resulting from orthogonally projecting the input
      !>         ellipse onto a plane may be degenerate, even if the input
      !>         ellipse is not.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     Projecting an ellipse orthogonally onto a plane can be thought of
      !>     finding the points on the plane that are `under' or `over' the
      !>     ellipse, with the `up' direction considered to be perpendicular
      !>     to the plane. More mathematically, the orthogonal projection is
      !>     the set of points Y in the plane such that for some point X in
      !>     the ellipse, the vector Y - X is perpendicular to the plane.
      !>     The orthogonal projection of an ellipse onto a plane yields
      !>     another ellipse.
      !>
      !>## Examples
      !>
      !>     1)  With  CENTER  = ( 1.D0,  1.D0,  1.D0 ),
      !>               VECT1   = ( 2.D0,  0.D0,  0.D0 ),
      !>               VECT2   = ( 0.D0,  1.D0,  1.D0 ),
      !>               NORMAL  = ( 0.D0,  0.D0,  1.D0 ),
      !>
      !>         the code fragment
      !>
      !>               CALL NVC2PL ( NORMAL,  0.D0,    PLANE           )
      !>               CALL CGV2EL ( CENTER,  VECT1,   VECT2,   ELIN   )
      !>               CALL PJELPL ( ELIN,    PLANE,   ELOUT           )
      !>               CALL EL2CGV ( ELOUT,   PRJCTR,  PRJMAJ,  PRJMIN )
      !>
      !>         returns
      !>
      !>               PRJCTR  = ( 1.D0,  1.D0,  0.D0 )
      !>               PRJMAJ  = ( 2.D0,  0.D0,  0.D0 )
      !>               PRJMIN  = ( 0.D0,  1.D0,  0.D0 )
      !>
      !>     2)  With  VECT1   = ( 2.D0,  0.D0,  0.D0 ),
      !>               VECT2   = ( 1.D0,  1.D0,  1.D0 ),
      !>               CENTER  = ( 0.D0,  0.D0,  0.D0 ),
      !>               NORMAL  = ( 0.D0,  0.D0,  1.D0 ),
      !>
      !>         the code fragment
      !>
      !>               CALL NVC2PL ( NORMAL,  0.D0,    PLANE           )
      !>               CALL CGV2EL ( CENTER,  VECT1,   VECT2,   ELIN   )
      !>               CALL PJELPL ( ELIN,    PLANE,   ELOUT           )
      !>               CALL EL2CGV ( ELOUT,   PRJCTR,  PRJMAJ,  PRJMIN )
      !>
      !>         returns
      !>
      !>               PRJCTR  = ( 0.D0,  0.D0,  0.D0 )
      !>
      !>               PRJMAJ  = ( -2.227032728823213D0,
      !>                           -5.257311121191336D-1,
      !>                            0.D0                  )
      !>
      !>               PRJMIN  = (  2.008114158862273D-1,
      !>                           -8.506508083520399D-1,
      !>                            0.D0                  )
      !>
      !>     3)    An example of actual use: Suppose we wish to compute the
      !>           distance from an ellipsoid to a line. Let the line be
      !>           defined by a point P and a direction vector DIRECT; the
      !>           line is the set of points
      !>
      !>              P   +   t * DIRECT,
      !>
      !>           where t is any real number. Let the ellipsoid have semi-
      !>           axis lengths A, B, and C.
      !>
      !>           We can reduce the problem to that of finding the distance
      !>           between the line and an ellipse on the ellipsoid surface by
      !>           considering the fact that the surface normal at the nearest
      !>           point to the line will be orthogonal to DIRECT; the set of
      !>           surface points where this condition holds lies in a plane,
      !>           and hence is an ellipse on the surface. The problem can be
      !>           further simplified by projecting the ellipse orthogonally
      !>           onto the plane defined by
      !>
      !>              < X, DIRECT >  =  0.
      !>
      !>           The problem is then a two dimensional one: find the
      !>           distance of the projected ellipse from the intersection of
      !>           the line and this plane (which is necessarily one point).
      !>           A `paraphrase' of the relevant code is:
      !>
      !>              C     Step 1. Find the candidate ellipse CAND.
      !>              C               NORMAL is a normal vector to the plane
      !>              C               containing the candidate ellipse. The
      !>              C               ellipse must exist, since it's the
      !>              C               intersection of an ellipsoid centered at
      !>              C               the origin and a plane containing the
      !>              C               origin. For this reason, we don't check
      !>              C               INEDPL's `found flag' FOUND below.
      !>              C
      !>                    NORMAL(1)  =  DIRECT(1) / A**2
      !>                    NORMAL(2)  =  DIRECT(2) / B**2
      !>                    NORMAL(3)  =  DIRECT(3) / C**2
      !>
      !>                    CALL NVC2PL ( NORMAL, 0.D0, CANDPL )
      !>
      !>                    CALL INEDPL ( A, B, C, CANDPL, CAND, FOUND )
      !>
      !>              C
      !>              C     Step 2. Project the candidate ellipse onto a
      !>              C               plane orthogonal to the line. We'll
      !>              C               call the plane PRJPL and the
      !>              C               projected ellipse PRJEL.
      !>              C
      !>                     CALL NVC2PL ( DIRECT,  0.D0,   PRJPL )
      !>                     CALL PJELPL ( CAND,    PRJPL,  PRJEL )
      !>
      !>              C
      !>              C     Step 3. Find the point on the line lying in the
      !>              C               projection plane, and then find the
      !>              C               near point PJNEAR on the projected
      !>              C               ellipse. Here PRJPT is the point on the
      !>              C               input line that lies in the projection
      !>              C               plane. The distance between PRJPT and
      !>              C               PJNEAR is DIST.
      !>
      !>                    CALL VPRJP  ( LINEPT,  PRJPL,  PRJPT         )
      !>                    CALL NPEDPT ( PRJEL,   PRJPT,  PJNEAR,  DIST )
      !>
      !>              C
      !>              C     Step 4. Find the near point PNEAR on the
      !>              C              ellipsoid by taking the inverse
      !>              C              orthogonal projection of PJNEAR; this is
      !>              C              the point on the candidate ellipse that
      !>              C              projects to PJNEAR. Note that the output
      !>              C              DIST was computed in step 3.
      !>              C
      !>              C              The inverse projection of PJNEAR is
      !>              C              guaranteed to exist, so we don't have to
      !>              C              check FOUND.
      !>              C
      !>                    CALL VPRJPI ( PJNEAR, PRJPL, CANDPL, PNEAR, FOUND )
      !>
      !>           The value of DIST returned is the distance we're looking
      !>           for.
      !>
      !>           The procedure described here is carried out in the routine
      !>           NPEDLN.
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 24-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.0.0, 02-NOV-1990 (NJB)
      module subroutine pjelpl ( ctx, elin, plane, elout )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: el2cgv, pl2nvc, vperp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: ubel = 9
      integer(ip), parameter :: ubpl = 4
      real(wp), intent(in) :: elin  ( ubel )  !! A SPICE ellipse to be projected.
      real(wp), intent(in) :: plane ( ubpl )  !! A plane onto which ELIN is to be projected.
      real(wp), intent(out) :: elout ( ubel )  !! A SPICE ellipse resulting from the projection.



      real(wp) :: center ( 3 )
      real(wp) :: const
      real(wp) :: normal ( 3 )
      real(wp) :: prjctr ( 3 )
      real(wp) :: prjvc1 ( 3 )
      real(wp) :: prjvc2 ( 3 )
      real(wp) :: smajor ( 3 )
      real(wp) :: sminor ( 3 )

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Find generating vectors of the input ellipse.
!
      call el2cgv ( elin, center, smajor, sminor )

!
!     Find a normal vector for the input plane.
!
      call pl2nvc ( plane, normal, const )

!
!     Find the components of the semi-axes that are orthogonal to the
!     input plane's normal vector.  The components are generating
!     vectors for the projected plane.
!
      call vperp ( smajor,  normal,  prjvc1 )
      call vperp ( sminor,  normal,  prjvc2 )

!
!     Find the projection of the ellipse's center onto the input plane.
!     This is the center of the projected ellipse.
!
!     In case the last assertion is non-obvious, note that the
!     projection we're carrying out is the composition of a linear
!     mapping (projection to a plane containing the origin and parallel
!     to PLANE) and a translation mapping (adding the closest point to
!     the origin in PLANE to every point), and both linear mappings and
!     translations carry the center of an ellipse to the center of the
!     ellipse's image.  Let's state this using mathematical symbols.
!     Let L be a linear mapping and let T be a translation mapping,
!     say
!
!        T(x) = x + A.
!
!     Then
!
!           T  (  L ( center + cos(theta)smajor + sin(theta)sminor )  )
!
!        =  A  +  L ( center + cos(theta)smajor + sin(theta)sminor )
!
!        =  A  +  L (center)
!              +  cos(theta) L(smajor)
!              +  sin(theta) L(sminor)
!
!     From the form of this last expression, we see that we have an
!     ellipse centered at
!
!           A  +  L (center)
!
!        =  T  (  L (center)  )
!
!     This last term is the image of the center of the original ellipse,
!     as we wished to demonstrate.
!
!     Now in the case of orthogonal projection onto a plane PL, L can be
!     taken as the orthogonal projection onto a parallel plane PL'
!     containing the origin.  Then L is a linear mapping.  Let M be
!     the multiple of the normal vector of PL such that M is contained
!     in PL (M is the closest point in PL to the origin).  Then the
!     orthogonal projection mapping onto PL, which we will name PRJ,
!     can be defined by
!
!       PRJ (x)  =  L (x)  +  M.
!
!     So PRJ is the composition of a translation and a linear mapping,
!     as claimed.
!
      call vprjp  ( ctx, center, plane,  prjctr )

!
!     Put together the projected ellipse.
!
      call cgv2el ( ctx, prjctr, prjvc1, prjvc2, elout )

      return
      end subroutine pjelpl

      !> Translate a surface ID code, together with a body ID code, to the
      !> corresponding surface name. If no such name exists, return a
      !> string representation of the surface ID code.
      !>
      !>## Detailed Input
      !>
      !>     CODE     is an integer code for a surface associated with a
      !>              body.
      !>
      !>     BODYID   is an integer code for the body associated with the
      !>              surface designated by CODE. The combination of CODE
      !>              and BODYID is to be mapped to a surface name.
      !>
      !>## Detailed Output
      !>
      !>     SRFSTR   is the name of the surface identified by CODE, for the
      !>              body designated by BODYID, if an association exists
      !>              between this pair of ID codes and a surface name.
      !>
      !>              If CODE has more than one translation, then the most
      !>              recently defined surface name corresponding to CODE is
      !>              returned. SRFSTR will have the exact format (case and
      !>              embedded blanks) used in the definition of the
      !>              name/code association.
      !>
      !>              If the input pair of codes does not map to a surface
      !>              name, SRFSTR is set to the string representation of
      !>              CODE.
      !>
      !>              SRFSTR should be declared with length SFNMLN (see the
      !>              $Parameters section below).
      !>
      !>     ISNAME   is a logical flag that is .TRUE. if a surface name
      !>              corresponding to the input ID codes was found and
      !>              .FALSE. otherwise. When ISNAME is .FALSE., the output
      !>              string SRFSTR contains a string representing the
      !>              integer CODE.
      !>
      !>## Parameters
      !>
      !>     SFNMLN   is the maximum length of a surface name. This
      !>              parameter is declared in the SPICELIB include file
      !>
      !>                 srftrn.inc
      !>
      !>## Exceptions
      !>
      !>     1)  If the input surface ID code cannot be mapped to a name, the
      !>         output SRFSTR is set to a string representation of the code.
      !>         The input body ID is ignored. The output ISNAME is set to
      !>         .FALSE.
      !>
      !>         This case is not treated as an error.
      !>
      !>## Files
      !>
      !>     Surface name-to-ID mappings may be defined at run time by loading
      !>     text kernels containing kernel variable assignments of the form
      !>
      !>        NAIF_SURFACE_NAME += ( <surface name 1>, ... )
      !>        NAIF_SURFACE_CODE += ( <surface code 1>, ... )
      !>        NAIF_SURFACE_BODY += ( <body code 1>,    ... )
      !>
      !>     Above, the Ith elements of the lists on the assignments' right
      !>     hand sides together define the Ith surface name/ID mapping.
      !>
      !>     The same effect can be achieved using assignments formatted as
      !>     follows:
      !>
      !>        NAIF_SURFACE_NAME += <surface name 1>
      !>        NAIF_SURFACE_CODE += <surface code 1>
      !>        NAIF_SURFACE_BODY += <body code 1>
      !>
      !>        NAIF_SURFACE_NAME += <surface name 2>
      !>        NAIF_SURFACE_CODE += <surface code 2>
      !>        NAIF_SURFACE_BODY += <body code 2>
      !>
      !>           ...
      !>
      !>     Note the use of the
      !>
      !>        +=
      !>
      !>     operator; this operator appends to rather than overwrites the
      !>     kernel variable named on the left hand side of the assignment.
      !>
      !>## Particulars
      !>
      !>     Surfaces are always associated with bodies (which usually are
      !>     ephemeris objects). For any given body, a mapping between surface
      !>     names and surface ID codes can be established.
      !>
      !>     Bodies serve to disambiguate surface names and ID codes: the set
      !>     of surface names and surface ID codes for a given body can be
      !>     thought of as belonging to a name space. A given surface ID code
      !>     or surface name may be used for surfaces of multiple bodies,
      !>     without conflict.
      !>
      !>     Associations between surface names and ID codes are always made
      !>     via kernel pool assignments; there are no built-in associations.
      !>
      !>     SRFC2S is one of four related subroutines:
      !>
      !>        SRFS2C      Surface string and body string to surface ID code
      !>        SRFSCC      Surface string and body ID code to surface ID code
      !>        SRFC2S      Surface ID code and body ID code to surface string
      !>        SRFCSS      Surface ID code and body string to surface string
      !>
      !>     SRFS2C, SRFC2S, SRFSCC, and SRFCSS perform translations between
      !>     surface strings and their corresponding integer ID codes.
      !>
      !>     Refer to naif_ids.req for details concerning adding new surface
      !>     name/code associations at run time by loading text kernels.
      !>
      !>## Examples
      !>
      !>     The formatting of the results shown for this example may differ
      !>     across platforms.
      !>
      !>     1) Supposed a text kernel has been loaded that contains
      !>        the following assignments:
      !>
      !>           NAIF_SURFACE_NAME += ( 'MGS MOLA  64 pixel/deg',
      !>                                  'MGS MOLA 128 pixel/deg',
      !>                                  'PHOBOS GASKELL Q512'     )
      !>           NAIF_SURFACE_CODE += (   1,   2,    1 )
      !>           NAIF_SURFACE_BODY += ( 499, 499,  401 )
      !>
      !>        Translate each surface and body ID code pair to the
      !>        associated surface name. Also perform a translation
      !>        for a surface ID having no matching name.
      !>
      !>        Use the meta-kernel shown below to define the required SPICE
      !>        kernel variables.
      !>
      !>           KPL/MK
      !>
      !>           File: srfc2s_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The file contents shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           \begindata
      !>
      !>           NAIF_SURFACE_NAME += ( 'MGS MOLA  64 pixel/deg',
      !>                                  'MGS MOLA 128 pixel/deg',
      !>                                  'PHOBOS GASKELL Q512'     )
      !>           NAIF_SURFACE_CODE += (   1,   2,    1 )
      !>           NAIF_SURFACE_BODY += ( 499, 499,  401 )
      !>
      !>           \begintext
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>       PROGRAM SRFC2S_EX1
      !>       IMPLICIT NONE
      !>
      !>       INCLUDE 'srftrn.inc'
      !>
      !>       INTEGER               FILSIZ
      !>       PARAMETER           ( FILSIZ = 255 )
      !>
      !>       INTEGER               NCASE
      !>       PARAMETER           ( NCASE  = 5 )
      !>
      !>       CHARACTER*(FILSIZ)    META
      !>       CHARACTER*(SFNMLN)    SRFNAM
      !>
      !>       INTEGER               BODYID ( NCASE )
      !>       INTEGER               I
      !>       INTEGER               SURFID ( NCASE )
      !>
      !>       LOGICAL               ISNAME
      !>
      !>       DATA  ( SURFID(I), BODYID(I), I = 1, NCASE ) /
      !>      .
      !>      .        1,         499,
      !>      .        1,         401,
      !>      .        2,         499,
      !>      .        3,         499,
      !>      .        1,          -1                      /
      !>
      !>       META = 'srfc2s_ex1.tm'
      !>
      !>       CALL FURNSH ( META )
      !>
      !>       WRITE (*,*) ' '
      !>
      !>       DO I = 1, NCASE
      !>
      !>          CALL SRFC2S ( SURFID(I), BODYID(I),
      !>      .                 SRFNAM,    ISNAME    )
      !>
      !>          WRITE (*,*) 'surface ID     = ', SURFID(I)
      !>          WRITE (*,*) 'body ID        = ', BODYID(I)
      !>          WRITE (*,*) 'name found     = ', ISNAME
      !>          WRITE (*,*) 'surface string = ', SRFNAM
      !>          WRITE (*,*) ' '
      !>
      !>       END DO
      !>
      !>       END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         surface ID     =            1
      !>         body ID        =          499
      !>         name found     =  T
      !>         surface string = MGS MOLA  64 pixel/deg
      !>
      !>         surface ID     =            1
      !>         body ID        =          401
      !>         name found     =  T
      !>         surface string = PHOBOS GASKELL Q512
      !>
      !>         surface ID     =            2
      !>         body ID        =          499
      !>         name found     =  T
      !>         surface string = MGS MOLA 128 pixel/deg
      !>
      !>         surface ID     =            3
      !>         body ID        =          499
      !>         name found     =  F
      !>         surface string = 3
      !>
      !>         surface ID     =            1
      !>         body ID        =           -1
      !>         name found     =  F
      !>         surface string = 1
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 12-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 14-JAN-2016 (NJB) (EDW) (BVS)
      module subroutine srfc2s ( ctx, code, bodyid, srfstr, isname )
      use pepper_kinds, only: ip
      use pepper_strings, only: intstr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: code  !! Integer surface ID code to translate to a string.
      integer(ip), intent(in) :: bodyid  !! ID code of body associated with surface.
      character(*), intent(out) :: srfstr  !! String corresponding to surface ID code.
      logical, intent(out) :: isname  !! Logical flag indicating output is a surface name.

      if ( ctx%failed() ) return

!
!     Try to translate the input codes to a known surface name.
!
      call zzsrfc2n ( ctx, code, bodyid, srfstr, isname )

      if ( ctx%failed() ) return

!
!     If there is no matching name, convert the surface ID code to a
!     string representation.
!
      if ( .not. isname ) then

         call intstr ( code, srfstr )

      end if

      return
      end subroutine srfc2s

      !> Translate a surface ID code, together with a body string, to the
      !> corresponding surface name. If no such surface name exists,
      !> return a string representation of the surface ID code.
      !>
      !>## Detailed Input
      !>
      !>     CODE     is an integer ID code for a surface associated with a
      !>              specified body.
      !>
      !>     BODSTR   is a string designating the body associated with the
      !>              input surface ID code. BODSTR may contain a body name
      !>              or a string representation of the body's integer ID
      !>              code. For example, BODSTR may contain
      !>
      !>                 '1000012'
      !>
      !>              instead of
      !>
      !>                 '67P/CHURYUMOV-GERASIMENKO (1969 R1)'
      !>
      !>              Case and leading and trailing blanks in a name are not
      !>              significant. Sequences of consecutive embedded blanks
      !>              are considered equivalent to a single blank. That is,
      !>              all of the following strings are equivalent names:
      !>
      !>                 '67P/CHURYUMOV-GERASIMENKO (1969 R1)'
      !>                 '67P/Churyumov-Gerasimenko (1969 R1)'
      !>                 '67P/CHURYUMOV-GERASIMENKO (1969 R1)   '
      !>                 '67P/CHURYUMOV-GERASIMENKO    (1969 R1)'
      !>                 '   67P/CHURYUMOV-GERASIMENKO (1969 R1)'
      !>
      !>              However, '67P/CHURYUMOV-GERASIMENKO(1969R1)'
      !>              is not equivalent to the names above.
      !>
      !>## Detailed Output
      !>
      !>     SRFSTR   is the name of the surface identified by CODE, for the
      !>              body designated by BODSTR, if for this body an
      !>              association exists between the input surface ID and a
      !>              surface name.
      !>
      !>              If CODE has more than one translation, then the most
      !>              recently defined surface name corresponding to CODE is
      !>              returned. SRFSTR will have the exact format (case and
      !>              embedded blanks) used in the definition of the
      !>              name/code association.
      !>
      !>              If the input surface ID code and body name do not map
      !>              to a surface name, SRFSTR is set to the string
      !>              representation of CODE.
      !>
      !>              SRFSTR should be declared with length SFNMLN (see the
      !>              $Parameters section below).
      !>
      !>     ISNAME   is a logical flag that is .TRUE. if a surface name
      !>              corresponding to the input ID codes was found and
      !>              .FALSE. otherwise. When ISNAME is .FALSE., the output
      !>              string SRFSTR contains a string representing the
      !>              integer CODE.
      !>
      !>## Parameters
      !>
      !>     SFNMLN   is the maximum length of a surface name. This
      !>              parameter is declared in the SPICELIB include file
      !>
      !>                 srftrn.inc
      !>
      !>## Exceptions
      !>
      !>     1)  If the input body string cannot be mapped to a body name, the
      !>         output SRFSTR is set to a string representation of the
      !>         surface ID code. The output ISNAME is set to .FALSE.
      !>
      !>         This case is not treated as an error.
      !>
      !>     2)  If the input surface code cannot be mapped to a surface name,
      !>         the output SRFSTR is set to a string representation of the
      !>         surface ID code. The input body string is ignored. The output
      !>         ISNAME is set to .FALSE.
      !>
      !>         This case is not treated as an error.
      !>
      !>## Files
      !>
      !>     Surface name-to-ID mappings may be defined at run time by loading
      !>     text kernels containing kernel variable assignments of the form
      !>
      !>        NAIF_SURFACE_NAME += ( <surface name 1>, ... )
      !>        NAIF_SURFACE_CODE += ( <surface code 1>, ... )
      !>        NAIF_SURFACE_BODY += ( <body code 1>,    ... )
      !>
      !>     Above, the Ith elements of the lists on the assignments' right
      !>     hand sides together define the Ith surface name/ID mapping.
      !>
      !>     The same effect can be achieved using assignments formatted as
      !>     follows:
      !>
      !>        NAIF_SURFACE_NAME += <surface name 1>
      !>        NAIF_SURFACE_CODE += <surface code 1>
      !>        NAIF_SURFACE_BODY += <body code 1>
      !>
      !>        NAIF_SURFACE_NAME += <surface name 2>
      !>        NAIF_SURFACE_CODE += <surface code 2>
      !>        NAIF_SURFACE_BODY += <body code 2>
      !>
      !>           ...
      !>
      !>     Note the use of the
      !>
      !>        +=
      !>
      !>     operator; this operator appends to rather than overwrites the
      !>     kernel variable named on the left hand side of the assignment.
      !>
      !>## Particulars
      !>
      !>     Surfaces are always associated with bodies (which usually are
      !>     ephemeris objects). For any given body, a mapping between surface
      !>     names and surface ID codes can be established.
      !>
      !>     Bodies serve to disambiguate surface names and ID codes: the set
      !>     of surface names and surface ID codes for a given body can be
      !>     thought of as belonging to a name space. A given surface ID code
      !>     or surface name may be used for surfaces of multiple bodies,
      !>     without conflict.
      !>
      !>     Associations between surface names and ID codes are always made
      !>     via kernel pool assignments; there are no built-in associations.
      !>
      !>     SRFCSS is one of four related subroutines:
      !>
      !>        SRFS2C      Surface string and body string to surface ID code
      !>        SRFSCC      Surface string and body ID code to surface ID code
      !>        SRFC2S      Surface ID code and body ID code to surface string
      !>        SRFCSS      Surface ID code and body string to surface string
      !>
      !>     SRFS2C, SRFC2S, SRFSCC, and SRFCSS perform translations between
      !>     surface strings and their corresponding integer ID codes.
      !>
      !>     Refer to naif_ids.req for details concerning adding new surface
      !>     name/code associations at run time by loading text kernels.
      !>
      !>## Examples
      !>
      !>     The formatting of the results shown for this example may differ
      !>     across platforms.
      !>
      !>     1) Supposed a text kernel has been loaded that contains
      !>        the following assignments:
      !>
      !>           NAIF_SURFACE_NAME += ( 'MGS MOLA  64 pixel/deg',
      !>                                  'MGS MOLA 128 pixel/deg',
      !>                                  'PHOBOS GASKELL Q512'     )
      !>           NAIF_SURFACE_CODE += (   1,   2,    1 )
      !>           NAIF_SURFACE_BODY += ( 499, 499,  401 )
      !>
      !>        Translate each surface and body ID code pair to the
      !>        associated surface name. Also perform a translation
      !>        for a surface ID having no matching name.
      !>
      !>        Use the meta-kernel shown below to define the required SPICE
      !>        kernel variables.
      !>
      !>           KPL/MK
      !>
      !>           File: srfcss_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The file contents shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           \begindata
      !>
      !>           NAIF_SURFACE_NAME += ( 'MGS MOLA  64 pixel/deg',
      !>                                  'MGS MOLA 128 pixel/deg',
      !>                                  'PHOBOS GASKELL Q512'     )
      !>           NAIF_SURFACE_CODE += (   1,   2,    1 )
      !>           NAIF_SURFACE_BODY += ( 499, 499,  401 )
      !>
      !>           \begintext
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>       PROGRAM SRFCSS_EX1
      !>       IMPLICIT NONE
      !>
      !>       INCLUDE 'srftrn.inc'
      !>
      !>       INTEGER               FILSIZ
      !>       PARAMETER           ( FILSIZ = 255 )
      !>
      !>       INTEGER               NCASE
      !>       PARAMETER           ( NCASE = 5 )
      !>
      !>       INTEGER               BDNMLN
      !>       PARAMETER           ( BDNMLN = 36 )
      !>
      !>       CHARACTER*(BDNMLN)    BODSTR ( NCASE )
      !>       CHARACTER*(FILSIZ)    META
      !>       CHARACTER*(SFNMLN)    SRFNAM
      !>
      !>       INTEGER               I
      !>       INTEGER               SURFID ( NCASE )
      !>
      !>       LOGICAL               ISNAME
      !>
      !>       DATA  ( SURFID(I), BODSTR(I), I = 1, NCASE ) /
      !>      .
      !>      .        1,         'MARS',
      !>      .        1,         'PHOBOS',
      !>      .        2,         '499',
      !>      .        3,         'MARS',
      !>      .        1,         'ZZZ'                     /
      !>
      !>       META = 'srfcss_ex1.tm'
      !>
      !>       CALL FURNSH ( META )
      !>
      !>       WRITE (*,*) ' '
      !>
      !>       DO I = 1, NCASE
      !>
      !>          CALL SRFCSS ( SURFID(I), BODSTR(I),
      !>      .                 SRFNAM,    ISNAME     )
      !>
      !>          WRITE (*,*) 'surface ID     = ', SURFID(I)
      !>          WRITE (*,*) 'body string    = ', BODSTR(I)
      !>          WRITE (*,*) 'name found     = ', ISNAME
      !>          WRITE (*,*) 'surface string = ', SRFNAM
      !>          WRITE (*,*) ' '
      !>
      !>       END DO
      !>
      !>       END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         surface ID     =            1
      !>         body string    = MARS
      !>         name found     =  T
      !>         surface string = MGS MOLA  64 pixel/deg
      !>
      !>         surface ID     =            1
      !>         body string    = PHOBOS
      !>         name found     =  T
      !>         surface string = PHOBOS GASKELL Q512
      !>
      !>         surface ID     =            2
      !>         body string    = 499
      !>         name found     =  T
      !>         surface string = MGS MOLA 128 pixel/deg
      !>
      !>         surface ID     =            3
      !>         body string    = MARS
      !>         name found     =  F
      !>         surface string = 3
      !>
      !>         surface ID     =            1
      !>         body string    = ZZZ
      !>         name found     =  F
      !>         surface string = 1
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 12-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 14-JAN-2016 (NJB) (EDW) (BVS)
      module subroutine srfcss ( ctx, code, bodstr, srfstr, isname )
      use pepper_kinds, only: ip
      use pepper_strings, only: intstr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: code  !! Integer surface ID code to translate to a string.
      character(*), intent(in) :: bodstr  !! Name or ID of body associated with surface.
      character(*), intent(out) :: srfstr  !! String corresponding to surface ID code.
      logical, intent(out) :: isname  !! Flag indicating whether output is a surface name.

      integer(ip) :: bodyid

      if ( ctx%failed() ) return

!
!     No name has been found yet.
!
      isname = .false.

!
!     Convert the body string to an ID code.
!
      call bods2c ( ctx, bodstr, bodyid, isname )

      if ( ctx%failed() ) return

      if ( isname ) then
!
!        Try to translate the surface and body codes to a known surface
!        name.
!
         call zzsrfc2n ( ctx, code, bodyid, srfstr, isname )

         if ( ctx%failed() ) return

      end if

!
!     If either the body string or surface code could not be
!     translated, convert the surface ID code to a string
!     representation.
!
      if ( .not. isname ) then

         call intstr ( code, srfstr )

      end if

      return
      end subroutine srfcss

      !> Translate a surface string, together with a body string, to the
      !> corresponding surface ID code. The input strings may contain
      !> names or integer ID codes.
      !>
      !>## Detailed Input
      !>
      !>     SRFSTR   is a string designating a surface. SRFSTR may contain
      !>              a surface name or a string representation of the
      !>              surface's integer ID code.
      !>
      !>              If, for the body specified by BODSTR, multiple surface
      !>              names are associated with one surface ID code, then any
      !>              of these names may be used as the value of SRFSTR.
      !>
      !>              Case and leading and trailing blanks in a surface name
      !>              are not significant. Sequences of consecutive embedded
      !>              blanks are considered equivalent to a single blank.
      !>              For example, all of the strings below are considered
      !>              to be equivalent:
      !>
      !>                 'MGS MOLA 128 PIXEL/DEG'
      !>                 'MGS MOLA 128 pixel/deg'
      !>                 'MGS MOLA 128 PIXEL/DEG   '
      !>                 'MGS MOLA 128    PIXEL/DEG'
      !>                 '   MGS MOLA 128 PIXEL/DEG'
      !>
      !>              However,
      !>
      !>                 'MGSMOLA 128PIXEL/DEG'
      !>
      !>              is not equivalent to the names above.
      !>
      !>     BODSTR   is a string designating the body associated with the
      !>              input surface string. BODSTR may contain a body name
      !>              or a string representation of the body's integer ID
      !>              code. For example, BODSTR may contain
      !>
      !>                 '1000012'
      !>
      !>              instead of
      !>
      !>                 '67P/CHURYUMOV-GERASIMENKO (1969 R1)'
      !>
      !>              Case and leading and trailing blanks in a name are not
      !>              significant. The treatment of blanks in BODSTR is the
      !>              same as for SRFSTR.
      !>
      !>## Detailed Output
      !>
      !>     CODE     is integer ID code of the surface designated by
      !>              SRFSTR, for the body designated by BODSTR, if for this
      !>              body an association exists between the input surface
      !>              string and a surface ID code. CODE is defined if and
      !>              only if the output flag FOUND is .TRUE.
      !>
      !>     FOUND    is a logical flag that is .TRUE. if a surface code
      !>              corresponding to the input strings was found and
      !>              .FALSE. otherwise.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input surface string does not map to an ID code
      !>         and does not represent an integer, the output CODE is
      !>         undefined and the output FOUND is set to .FALSE.
      !>
      !>         This case is not treated as an error.
      !>
      !>     2)  If the input body string does not map to an ID code and does
      !>         not represent an integer, the output CODE is undefined and
      !>         the output FOUND is set to .FALSE.
      !>
      !>         This case is not treated as an error.
      !>
      !>## Files
      !>
      !>     Surface name-to-ID mappings may be defined at run time by loading
      !>     text kernels containing kernel variable assignments of the form
      !>
      !>        NAIF_SURFACE_NAME += ( <surface name 1>, ... )
      !>        NAIF_SURFACE_CODE += ( <surface code 1>, ... )
      !>        NAIF_SURFACE_BODY += ( <body code 1>,    ... )
      !>
      !>     Above, the Ith elements of the lists on the assignments' right
      !>     hand sides together define the Ith surface name/ID mapping.
      !>
      !>     The same effect can be achieved using assignments formatted as
      !>     follows:
      !>
      !>        NAIF_SURFACE_NAME += <surface name 1>
      !>        NAIF_SURFACE_CODE += <surface code 1>
      !>        NAIF_SURFACE_BODY += <body code 1>
      !>
      !>        NAIF_SURFACE_NAME += <surface name 2>
      !>        NAIF_SURFACE_CODE += <surface code 2>
      !>        NAIF_SURFACE_BODY += <body code 2>
      !>
      !>           ...
      !>
      !>     Note the use of the
      !>
      !>        +=
      !>
      !>     operator; this operator appends to rather than overwrites the
      !>     kernel variable named on the left hand side of the assignment.
      !>
      !>## Particulars
      !>
      !>     Surfaces are always associated with bodies (which usually are
      !>     ephemeris objects). For any given body, a mapping between surface
      !>     names and surface ID codes can be established.
      !>
      !>     Bodies serve to disambiguate surface names and ID codes: the set
      !>     of surface names and surface ID codes for a given body can be
      !>     thought of as belonging to a name space. A given surface ID code
      !>     or surface name may be used for surfaces of multiple bodies,
      !>     without conflict.
      !>
      !>     Associations between surface names and ID codes are always made
      !>     via kernel pool assignments; there are no built-in associations.
      !>
      !>     SRFS2C is one of four related subroutines:
      !>
      !>        SRFS2C      Surface string and body string to surface ID code
      !>        SRFSCC      Surface string and body ID code to surface ID code
      !>        SRFC2S      Surface ID code and body ID code to surface string
      !>        SRFCSS      Surface ID code and body string to surface string
      !>
      !>     SRFS2C, SRFC2S, SRFSCC, and SRFCSS perform translations between
      !>     surface strings and their corresponding integer ID codes.
      !>
      !>     Refer to naif_ids.req for details concerning adding new surface
      !>     name/code associations at run time by loading text kernels.
      !>
      !>## Examples
      !>
      !>     The formatting of the results shown for this example may differ
      !>     across platforms.
      !>
      !>     1) Supposed a text kernel has been loaded that contains
      !>        the following assignments:
      !>
      !>           NAIF_SURFACE_NAME += ( 'MGS MOLA  64 pixel/deg',
      !>                                  'MGS MOLA 128 pixel/deg',
      !>                                  'PHOBOS GASKELL Q512'     )
      !>           NAIF_SURFACE_CODE += (   1,   2,    1 )
      !>           NAIF_SURFACE_BODY += ( 499, 499,  401 )
      !>
      !>        Translate each surface and body string pair to the
      !>        associated surface ID code. Also perform a translation
      !>        for a surface name having no matching ID and for
      !>        a body string having no matching body ID code.
      !>
      !>        Use the meta-kernel shown below to define the required SPICE
      !>        kernel variables.
      !>
      !>           KPL/MK
      !>
      !>           File: srfs2c_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The file contents shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           \begindata
      !>
      !>           NAIF_SURFACE_NAME += ( 'MGS MOLA  64 pixel/deg',
      !>                                  'MGS MOLA 128 pixel/deg',
      !>                                  'PHOBOS GASKELL Q512'     )
      !>           NAIF_SURFACE_CODE += (   1,   2,    1 )
      !>           NAIF_SURFACE_BODY += ( 499, 499,  401 )
      !>
      !>           \begintext
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>       PROGRAM SRFS2C_EX1
      !>       IMPLICIT NONE
      !>
      !>       INCLUDE 'srftrn.inc'
      !>
      !>       INTEGER               FILSIZ
      !>       PARAMETER           ( FILSIZ = 255 )
      !>
      !>       INTEGER               NCASE
      !>       PARAMETER           ( NCASE = 8 )
      !>
      !>       INTEGER               BDNMLN
      !>       PARAMETER           ( BDNMLN = 36 )
      !>
      !>       CHARACTER*(BDNMLN)    BODSTR ( NCASE )
      !>       CHARACTER*(FILSIZ)    META
      !>       CHARACTER*(SFNMLN)    SRFSTR ( NCASE )
      !>
      !>       INTEGER               I
      !>       INTEGER               SURFID
      !>
      !>       LOGICAL               FOUND
      !>
      !>       DATA  ( SRFSTR(I), BODSTR(I), I = 1, NCASE )  /
      !>      .
      !>      .        'MGS MOLA  64 pixel/deg',    'MARS',
      !>      .        'PHOBOS GASKELL Q512',       'PHOBOS',
      !>      .        'MGS MOLA 128 pixel/deg',    'MARS',
      !>      .        'MGS MOLA  64 pixel/deg',    '499',
      !>      .        '1',                         'PHOBOS',
      !>      .        '2',                         '499',
      !>      .        'ZZZ',                       'MARS',
      !>      .        '1',                         'ZZZ'    /
      !>
      !>       META = 'srfs2c_ex1.tm'
      !>
      !>       CALL FURNSH ( META )
      !>
      !>       WRITE (*,*) ' '
      !>
      !>       DO I = 1, NCASE
      !>
      !>          CALL SRFS2C ( SRFSTR(I), BODSTR(I),
      !>      .                 SURFID,    FOUND     )
      !>
      !>          WRITE (*,*) 'surface string   = ', SRFSTR(I)
      !>          WRITE (*,*) 'body string      = ', BODSTR(I)
      !>          WRITE (*,*) 'surface ID found = ', FOUND
      !>
      !>          IF ( FOUND ) THEN
      !>             WRITE (*,*) 'surface ID       = ', SURFID
      !>          END IF
      !>
      !>          WRITE (*,*) ' '
      !>
      !>       END DO
      !>
      !>       END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         surface string   = MGS MOLA  64 pixel/deg
      !>         body string      = MARS
      !>         surface ID found =  T
      !>         surface ID       =            1
      !>
      !>         surface string   = PHOBOS GASKELL Q512
      !>         body string      = PHOBOS
      !>         surface ID found =  T
      !>         surface ID       =            1
      !>
      !>         surface string   = MGS MOLA 128 pixel/deg
      !>         body string      = MARS
      !>         surface ID found =  T
      !>         surface ID       =            2
      !>
      !>         surface string   = MGS MOLA  64 pixel/deg
      !>         body string      = 499
      !>         surface ID found =  T
      !>         surface ID       =            1
      !>
      !>         surface string   = 1
      !>         body string      = PHOBOS
      !>         surface ID found =  T
      !>         surface ID       =            1
      !>
      !>         surface string   = 2
      !>         body string      = 499
      !>         surface ID found =  T
      !>         surface ID       =            2
      !>
      !>         surface string   = ZZZ
      !>         body string      = MARS
      !>         surface ID found =  F
      !>
      !>         surface string   = 1
      !>         body string      = ZZZ
      !>         surface ID found =  F
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 22-OCT-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Updated description of SRFSTR to indicate that any
      !>        surface name alias may be used.
      !>
      !>-    SPICELIB Version 1.0.0, 14-JAN-2016 (NJB) (EDW) (BVS)
      module subroutine srfs2c ( ctx, srfstr, bodstr, code, found )
      use pepper_kinds, only: ip
      use pepper_strings, only: nparsi
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: srfstr  !! Surface name or ID string.
      character(*), intent(in) :: bodstr  !! Body name or ID string.
      integer(ip), intent(out) :: code  !! Integer surface ID code.
      logical, intent(out) :: found  !! Flag indicating whether surface ID was found.


      character(msglen) :: errmsg

      integer(ip) :: bodyid
      integer(ip) :: ptr

      if ( ctx%failed() ) return

!
!     No result has been found yet.
!
      found = .false.

!
!     Obtain a body ID string.
!
      call bods2c ( ctx, bodstr, bodyid, found )

      if ( ctx%failed() ) return

      if ( found ) then
!
!        We have the body ID.
!
!        Try to translate the input name to a known surface ID code.
!
         call zzsrfn2c ( ctx, srfstr, bodyid, code, found )

         if ( ctx%failed() ) return

         if ( .not. found ) then
!
!           The surface string could not be mapped to an ID code.
!
!           It's possible the name is a string representation of an
!           integer, for example, '999'.  If so, find the equivalent
!           datum of INTEGER type.
!
            call nparsi ( srfstr, code, errmsg, ptr )
!
!           If the string parsed as an integer, PTR is zero;
!           otherwise it's non-zero.
!
            found = ptr == 0

         end if

      end if
!
!     CODE and FOUND are set.
!
      return
      end subroutine srfs2c

      !> Translate a surface string, together with a body ID code, to the
      !> corresponding surface ID code. The input surface string may
      !> contain a name or an integer ID code.
      !>
      !>## Detailed Input
      !>
      !>     SRFSTR   is a string designating a surface. SRFSTR may contain
      !>              a surface name or a string representation of the
      !>              surface's integer ID code.
      !>
      !>              If, for the body specified by BODYID, multiple surface
      !>              names are associated with one surface ID code, then any
      !>              of these names may be used as the value of SRFSTR.
      !>
      !>              Case and leading and trailing blanks in a surface name
      !>              are not significant. Sequences of consecutive embedded
      !>              blanks are considered equivalent to a single blank.
      !>              For example, all of the strings below are considered
      !>              to be equivalent:
      !>
      !>                 'MGS MOLA 128 PIXEL/DEG'
      !>                 'MGS MOLA 128 pixel/deg'
      !>                 'MGS MOLA 128 PIXEL/DEG   '
      !>                 'MGS MOLA 128    PIXEL/DEG'
      !>                 '   MGS MOLA 128 PIXEL/DEG'
