      !>       INCLUDE 'srftrn.inc'
      !>
      !>       INTEGER               FILSIZ
      !>       PARAMETER           ( FILSIZ = 255 )
      !>
      !>       INTEGER               NCASE
      !>       PARAMETER           ( NCASE = 7 )
      !>
      !>       INTEGER               BDNMLN
      !>       PARAMETER           ( BDNMLN = 36 )
      !>
      !>       CHARACTER*(FILSIZ)    META
      !>       CHARACTER*(SFNMLN)    SRFSTR ( NCASE )
      !>
      !>       INTEGER               BODYID ( NCASE )
      !>       INTEGER               I
      !>       INTEGER               SURFID
      !>
      !>       LOGICAL               FOUND
      !>
      !>       DATA  ( SRFSTR(I), BODYID(I), I = 1, NCASE )  /
      !>      .
      !>      .        'MGS MOLA  64 pixel/deg',    499,
      !>      .        'PHOBOS GASKELL Q512',       401,
      !>      .        'MGS MOLA 128 pixel/deg',    499,
      !>      .        '1',                         499,
      !>      .        '1',                         401,
      !>      .        '2',                         499,
      !>      .        'ZZZ',                       499      /
      !>
      !>       META = 'srfscc_ex1.tm'
      !>
      !>       CALL FURNSH ( META )
      !>
      !>       WRITE (*,*) ' '
      !>
      !>       DO I = 1, NCASE
      !>
      !>          CALL SRFSCC ( SRFSTR(I), BODYID(I),
      !>      .                 SURFID,    FOUND     )
      !>
      !>          WRITE (*,*) 'surface string   = ', SRFSTR(I)
      !>          WRITE (*,*) 'body ID          = ', BODYID(I)
      !>          WRITE (*,*) 'surface ID found = ', FOUND
      !>
      !>          IF ( FOUND ) THEN
      !>             WRITE (*,*) 'surface ID       = ', SURFID
      !>          END IF
      !>
      !>          WRITE (*,*) ' '
      !>
      !>       END DO
      !>
      !>       END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         surface string   = MGS MOLA  64 pixel/deg
      !>         body ID          =          499
      !>         surface ID found =  T
      !>         surface ID       =            1
      !>
      !>         surface string   = PHOBOS GASKELL Q512
      !>         body ID          =          401
      !>         surface ID found =  T
      !>         surface ID       =            1
      !>
      !>         surface string   = MGS MOLA 128 pixel/deg
      !>         body ID          =          499
      !>         surface ID found =  T
      !>         surface ID       =            2
      !>
      !>         surface string   = 1
      !>         body ID          =          499
      !>         surface ID found =  T
      !>         surface ID       =            1
      !>
      !>         surface string   = 1
      !>         body ID          =          401
      !>         surface ID found =  T
      !>         surface ID       =            1
      !>
      !>         surface string   = 2
      !>         body ID          =          499
      !>         surface ID found =  T
      !>         surface ID       =            2
      !>
      !>         surface string   = ZZZ
      !>         body ID          =          499
      !>         surface ID found =  F
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 22-OCT-2021 (JDR) (NJB)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Updated description of SRFSTR to indicate that any
      !>        surface name alias may be used.
      !>
      !>-    SPICELIB Version 1.0.0, 14-JAN-2016 (NJB) (EDW) (BVS)
      module subroutine srfscc ( ctx, srfstr, bodyid, code, found )
      use pepper_kinds, only: ip
      use pepper_strings, only: nparsi
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: srfstr  !! Surface name or ID string.
      integer(ip), intent(in) :: bodyid  !! Body ID code.
      integer(ip), intent(out) :: code  !! Integer surface ID code.
      logical, intent(out) :: found  !! Flag indicating whether surface ID was found.


      character(msglen) :: errmsg

      integer(ip) :: ptr

      if ( ctx%failed() ) return

!
!     No result has been found yet.
!
      found = .false.

!
!     Try to translate the input surface name to a known surface ID
!     code.
!
      call zzsrfn2c ( ctx, srfstr, bodyid, code, found )

      if ( ctx%failed() ) return

      if ( .not. found ) then
!
!        The surface string could not be mapped to an ID code.
!
!        It's possible the name is a string representation of an
!        integer, for example, '999'.  If so, find the equivalent datum
!        of INTEGER type.
!
         call nparsi ( srfstr, code, errmsg, ptr )
!
!        If the string parsed as an integer, PTR is zero; otherwise
!        it's non-zero.
!
         found = ptr == 0

      end if
!
!     CODE and FOUND are set.
!
      return
      end subroutine srfscc

      !> Add an entry for a specified body to the DSK API segment buffer
      !> data structure.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     BODYID     is the integer ID code of a body for which a new
      !>                entry is to be made.
      !>
      !>     MAXBOD     is the maximum size of the body table. BTBODY, BTSEGP,
      !>                and BTSTSZ must each be declared by the caller with
      !>                size at least MAXBOD.
      !>
      !>     STSIZE     is the size of the segment table. STHAN, STDSCR,
      !>                STDLAD, STOFF, STCTR, and STRAD must be declared large
      !>                enough to hold STSIZE entries.
      !>
      !>     BTBODY     is a table of body IDs.
      !>
      !>     BTNBOD     is the number of body IDs currently in BTBODY.
      !>
      !>     BTSEGP     is an array of start indices in the segment table
      !>                of existing entries.
      !>
      !>     BTSTSZ     is an array of segment list sizes. The Ith entry
      !>                of BTSTSZ is the length of the segment list for the
      !>                Ith body.
      !>
      !>     STHAN      is an array of DAS handles. Each entry of STHAN that
      !>                is in use contains the handle of the DAS file
      !>                containing the DSK segment to which that entry
      !>                corresponds. The Ith entries of STHAN, STDSCR, STDLAD,
      !>                STOFF, STCTR, and STRAD correspond to the same DSK
      !>                segment.
      !>
      !>     STDSCR     is an array of DSK descriptors.
      !>
      !>     STDLAD     is an array of DLA descriptors.
      !>
      !>     STFREE     is the index of the first free entry in the segment
      !>                table.
      !>
      !>     STOFF      is an array of offsets of segment frame centers
      !>                from the central bodies of the segment. These offsets
      !>                are expressed in the reference frame of the segment.
      !>                They are constant vectors. Units are km.
      !>
      !>     STCTR      is an array of centers of outer bounding spheres for
      !>                segments. Each segment has an outer bounding sphere
      !>                that completely encloses that segment. Each center
      !>                is a vector expressed in the reference frame of the
      !>                the segment, and it is an offset from the frame's
      !>                center. Units are km.
      !>
      !>     STRAD      is an array of radii of outer bounding spheres of
      !>                segments. Units are km.
      !>
      !>## Detailed Output
      !>
      !>     BTBODY     is the input body ID table, modified by this routine.
      !>                If BODYID was not in the table on input, it has been
      !>                appended to the table.
      !>
      !>                If it was necessary to delete a body from the table
      !>                to make room for the body designated by BODYID, that
      !>                has been done.
      !>
      !>     BTNBOD     is the number of bodies in the body table. Depending
      !>                on what deletions may have been necessary, this
      !>                number may be greater than, equal to, or less than
      !>                its value on input.
      !>
      !>     BTSEGP     is an array of start indices in the segment table
      !>                of existing entries, updated to reflect appending of
      !>                segments corresponding to BODYID.
      !>
      !>     BTSTSZ     is the array of sizes of segment lists of bodies.
      !>                BTSTSZ contains an entry for the body designated by
      !>                BODYID.
      !>
      !>                If it was necessary to make room, other entries of
      !>                BTSTSZ may have been deleted.
      !>
      !>     STHAN      is the segment handle array, updated to include
      !>                an entry for each loaded DSK segment associated
      !>                with BODYID.
      !>
      !>                If it was necessary to make room, other entries of
      !>                STHAN may have been deleted.
      !>
      !>     STDSCR     is the segment DSK descriptor array, updated to include
      !>                an entry for each loaded DSK segment associated
      !>                with BODYID.
      !>
      !>                Segment entries are created in the order segments are
      !>                found by ZZDSKSNS, so the highest-priority segment's
      !>                entry is at the lowest index in STDSCR.
      !>
      !>                If it was necessary to make room, other entries of
      !>                STDESR may have been deleted.
      !>
      !>     STDLAD     is the segment DLA descriptor array, updated to include
      !>                an entry for each loaded DSK segment associated
      !>                with BODYID.
      !>
      !>                If it was necessary to make room, other entries of
      !>                STDLAD may have been deleted.
      !>
      !>     STFREE     is the index of the first free element in each
      !>                segment table array.
      !>
      !>     STOFF      is the segment frame center offset array, updated to
      !>                include an entry for each loaded DSK segment
      !>                associated with BODYID.
      !>
      !>                If it was necessary to make room, other entries of
      !>                STOFF may have been deleted.
      !>
      !>     STCTR      is the segment bounding sphere center array, updated
      !>                to include an entry for each loaded DSK segment
      !>                associated with BODYID.
      !>
      !>                If it was necessary to make room, other entries of
      !>                STCTR may have been deleted.
      !>
      !>     STRAD      is the segment bounding sphere radius array, updated
      !>                to include an entry for each loaded DSK segment
      !>                associated with BODYID.
      !>
      !>                If it was necessary to make room, other entries of
      !>                STRAD may have been deleted.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If an attempt is made to add an entry for a body already in
      !>         the body table, the error SPICE(INVALIDADD) is signaled.
      !>
      !>     2)  If a DSK segment has an unrecognized coordinate system, an
      !>         error will be signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     3)  If the center of a frame of a DSK segment cannot be
      !>         obtained from the frame's ID code, the error
      !>         SPICE(NOFRAMEINFO) is signaled.
      !>
      !>     4)  If the name of a frame of a DSK segment cannot be
      !>         obtained from the frame's ID code, the error
      !>         SPICE(NOFRAMENAME) is signaled.
      !>
      !>     5)  If an error occurs while this routine attempts to
      !>         obtain segment information from ZZDSKBSR, an error
      !>         will be signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     6)  If the offset of a frame's center from the frame's
      !>         body is not computable at the TDB epoch at the
      !>         midpoint of the segment's time coverage interval,
      !>         an error will be signaled by a routine in the
      !>         SPK subsystem.
      !>
      !>     7)  If the segment table cannot accommodate all segments for
      !>         the specified body, the error SPICE(SEGMENTTABLEFULL) will
      !>         be signaled.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>     If any loaded DSK segment has a reference frame that is not
      !>     centered at the segment's central (target) body, SPK data are
      !>     required to compute the offset between the frame's center and
      !>     the segment's center.
      !>
      !>     Frame kernels may be required in order to look up a segment's
      !>     frame center offset. In some cases, additional kernels such
      !>     as CK kernels and SCLK kernels could be required to support
      !>     the offset vector lookup.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by the DSK subsystem.
      !>
      !>     This routine maintains data structures used by SPICELIB
      !>     geometry APIs to perform efficient computations using
      !>     DSK data. The umbrella routine in which these structures
      !>     are declared is ZZDSKSBF.
      !>
      !>     In a sense, ZZDSKSBF sits "above" the ZZDSKBSR subsystem.
      !>     High-level geometry routines access the data stored in the
      !>     ZZDSKSBF arrays directly; they don't call entry points of
      !>     ZZDSKBSR.
      !>
      !>     The ZZDSKSBF subsystem maintains two logical tables: a body
      !>     table and a segment table. Both tables are designed to store
      !>     a fixed maximum number of items; there is no "virtual storage"
      !>     concept that applies.
      !>
      !>     New entries are added to the tables by appending.
      !>
      !>     Items in both tables have priority assigned on a first-in,
      !>     first-out basis. When it becomes necessary to remove an
      !>     item to make room for another, the lowest-indexed item is
      !>     removed first, and the tables are compressed so that the
      !>     remaining items are contiguous.
      !>
      !>     When the state of the underlying ZZDSKBSR system changes due to
      !>     loading or unloading of DSK files, the ZZDSKSBF body and segment
      !>     tables must be re-initialized. Entry points of ZZDSKSBF are
      !>     expected to perform this action by calling ZZDSKSBI.
      !>
      !>## Examples
      !>
      !>     See usage in ZZDSKSBF.
      !>
      !>## Restrictions
      !>
      !>     1) This is a private routine.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 13-JUL-2016 (NJB)
      module subroutine zzdsksba ( ctx, bodyid, maxbod, stsize, btbody, btnbod, btsegp, btstsz, sthan, stdscr, stdlad, stfree, stoff, stctr, strad )
      use pepper_kinds, only: ip, wp
      use pepper_inc_dla
      use pepper_inc_dskdsc
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: bodyid  !! Body ID code.
      integer(ip), intent(in) :: maxbod  !! Maximum size of body table.
      integer(ip), intent(in) :: stsize  !! Maximum size of segment table.
      integer(ip), intent(inout) :: btbody ( * )  !! Body table's body ID array.
      integer(ip), intent(inout) :: btnbod  !! Number of entries in body table.
      integer(ip), intent(inout) :: btsegp ( * )  !! Array of pointers from bodies to segment table.
      integer(ip), intent(inout) :: btstsz ( * )  !! Array of sizes of body segment lists.
      integer(ip), intent(inout) :: sthan  ( * )  !! Array of handles of segments.
      real(wp), intent(inout) :: stdscr ( dskdsz, * )  !! Array of DSK descriptors of segments.
      integer(ip), intent(inout) :: stdlad ( dladsz, * )  !! Array of DLA descriptors of segments.
      integer(ip), intent(inout) :: stfree  !! Index of first free entry in segment table.
      real(wp), intent(inout) :: stoff  ( 3, * )  !! Offsets of segment frame centers from body.
      real(wp), intent(inout) :: stctr  ( 3, * )  !! Centers of bounding spheres for segments.
      real(wp), intent(inout) :: strad  ( * )  !! Radii of bounding spheres for segments.

      character(:), allocatable :: frname
      logical :: namfnd

      real(wp) :: dskdsc ( dskdsz )
      real(wp) :: et
      real(wp) :: lt

      integer(ip) :: avail
      integer(ip) :: dladsc ( dladsz )
      integer(ip) :: frmctr
      integer(ip) :: handle
      integer(ip) :: i
      integer(ip) :: j
      integer(ip) :: nseg
      integer(ip) :: segcld
      integer(ip) :: segcls
      integer(ip) :: segctr
      integer(ip) :: segfid

      logical :: frmfnd
      logical :: segfnd
      logical :: status

      if ( ctx%failed() ) return

!
!     Check the body table for presence of the new body. It's
!     an error to call this routine for a body that's already
!     present. (Such a call likely indicates the tables were
!     not re-initialized after a BSR state change.)
!
      i = findloc(btbody(1:btnbod), bodyid, dim=1)

      if ( i > 0 ) then

         call ctx%setmsg ( 'Body # is already present in the DSK segment ' &
         //            'buffer body table. The table must be ' &
         //            're-initialized before this body can be added.' )
         call ctx%errint ( '#', bodyid                                     )
         call ctx%sigerr ( 'SPICE(INVALIDADD)'                             )
         return

      end if

!
!     Make sure the BSR segment list for the body is up to
!     date.
!
      call zzdskbbl ( ctx, bodyid )

      if ( ctx%failed() ) return

!
!     Count the segments in the BSR system for the body.
!
      nseg   = 0
      status = zzdsksbd( ctx, bodyid )

      call zzdskbss( ctx, bodyid )
      call zzdsksns( ctx, zzdskbdc, handle, dladsc, dskdsc, segfnd )

      if ( ctx%failed() ) return

      do while ( segfnd )

         nseg = nseg + 1

         call zzdsksns( ctx, zzdskbdc, handle, dladsc, dskdsc, segfnd )

         if ( ctx%failed() ) return

      end do

!
!     Check the number of segments for BODY against the size of the
!     segment table. If the table isn't big enough, we can't make
!     room by deleting existing entries. This is a backstop check;
!     this situation should not occur if STSIZE is consistent with
!     the value in ZZDSKBSR.
!
      if ( nseg > stsize ) then

         call ctx%setmsg ( 'The number of segments for body # is #; ' &
         //            'the size STSIZE of the input segment table ' &
         //            'is #.'                                       )
         call ctx%errint ( '#', bodyid                                   )
         call ctx%errint ( '#', nseg                                     )
         call ctx%errint ( '#', stsize                                   )
         call ctx%sigerr ( 'SPICE(SEGMENTTABLEFULL)'                     )
         return

      end if

!
!     If we don't have enough room to store new entries in the body
!     table or in the segment table, make room.
!
      avail = stsize - stfree + 1

      if (  ( btnbod == maxbod ) .or. ( avail < nseg )  ) then

         call zzdsksbr ( ctx, nseg, &
                         maxbod, stsize, btbody, btnbod, btsegp, &
                         btstsz, sthan,  stdscr, stdlad, stfree, &
                         stoff,  stctr,  strad                  )

         if ( ctx%failed() ) return

      end if

!
!     Append the new body ID to the body table. We've ensured there's
!     room in the table.
!
      btnbod           = btnbod + 1
      btbody( btnbod ) = bodyid
      btsegp( btnbod ) = stfree
      btstsz( btnbod ) = nseg

!
!     Make a second pass through the BSR segment list, this time
!     accumulating segments in the input segment table as we go.
!
      status = zzdsksbd( ctx, bodyid )

      call zzdskbss( ctx, bodyid )
      call zzdsksns( ctx, zzdskbdc, handle, dladsc, dskdsc, segfnd )

      if ( ctx%failed() ) return

      do while ( segfnd )
!
!        Insert handle and descriptor data for the current segment at
!        index STFREE in the segment table.
!
         sthan( stfree ) = handle

         stdlad(:,stfree) = dladsc
         stdscr(:,stfree) = dskdsc

         stfree          = stfree + 1

         call zzdsksns( ctx, zzdskbdc, handle, dladsc, dskdsc, segfnd )

         if ( ctx%failed() ) return

      end do

!
!     Compute bounding spheres and frame center offsets for each
!     segment.
!
      do i = 1, nseg
!
!        J is the index in the segment table of the Ith segment
!        for BODYID.
!
         j  = btsegp( btnbod ) + i - 1

         call zzsegbox ( ctx, stdscr(1,j), stctr(1,j), strad(j) )

         if ( ctx%failed() ) return

!
!        Obtain the center of the frame for the Ith segment.
!
         segfid = nint( stdscr(frmidx,j) )

         call frinfo ( ctx, segfid, frmctr, segcls, segcld, frmfnd )

         if ( .not. frmfnd ) then

            call ctx%setmsg ( 'Could not look up frame info for ' &
            //            'segment frame having ID #.'       )
            call ctx%errint ( '#', segfid                        )
            call ctx%sigerr ( 'SPICE(NOFRAMEINFO)'               )
            return

         end if
!
!        If the frame center is not the same as the central
!        body, compute the offset between the two. Otherwise
!        set the offset to zero.
!
         segctr = nint( stdscr(ctridx,j) )

         if ( segctr == frmctr ) then

            stoff(:,j) = 0.0_wp

         else

            call frame_name_of ( ctx, segfid, frname, namfnd )

            if ( frname == ' ' ) then

               call ctx%setmsg ( 'Could not look up frame info for ' &
               //            'segment frame having ID #.'       )
               call ctx%errint ( '#', segfid                        )
               call ctx%sigerr ( 'SPICE(NOFRAMENAME)'               )
               return

            end if

!
!           Note that SPK data must be available at the midpoint of the
!           DSK coverage epoch in order for the following call to work.
!
            et = ( stdscr(btmidx,j) + stdscr(etmidx,j) ) / 2

            call spkgps ( ctx, frmctr, et, frname, segctr, stoff(1,j), lt )

            if ( ctx%failed() ) return

         end if

      end do

      return
      end subroutine zzdsksba

      !> Determine whether a specified ellipse intersects the pyramid
      !> defined by a polygonal field of view.
      !>
      !>## Detailed Input
      !>
      !>     ELLIPS         is a SPICELIB ellipse having non-zero semi-axes.
      !>
      !>     VERTEX         is the single point of intersection of the vectors
      !>                    defining the edges of a pyramid.  The vectors
      !>                    emanate from this point.  The pyramid represents
      !>                    the spatial region viewed by a polygonal field of
      !>                    view (FOV).
      !>
      !>     AXIS           is a vector emanating from VERTEX that lies inside
      !>                    the pyramid defined by VERTEX, N, and BOUNDS.
      !>                    AXIS represents the boresight direction of the FOV.
      !>
      !>     N,
      !>     BOUNDS         are, respectively, the number of boundary vectors
      !>                    defining the pyramid and the boundary vectors
      !>                    themselves.  Each pair of consecutive vectors in
      !>                    the array BOUNDS, together with VERTEX, defines a
      !>                    face of the pyramid.
      !>
      !>                    Each boundary vector must have angular separation
      !>                    of less than pi/2 radians from AXIS.
      !>
      !>                    For any plane that doesn't contain VERTEX and that
      !>                    intersects AXIS at right angles, the intersections
      !>                    of the boundary vectors with that plane are the
      !>                    vertices of a polygon.  The polygon need not be
      !>                    convex, but it must be non-self-intersecting.
      !>
      !>## Detailed Output
      !>
      !>     FOUND          is set to .TRUE. if the pyramid and ellipse
      !>                    intersect; otherwise FOUND is .FALSE.
      !>
      !>## Parameters
      !>
      !>     UBEL           is the array upper bound for SPICELIB ellipses.
      !>
      !>     UBPL           is the array upper bound for SPICELIB planes.
      !>
      !>     MAXFOV         PEPPER: removed. SPICELIB's maximum number of
      !>                    boundary vectors (10000) in BOUNDS; the work
      !>                    array grows to N.
      !>
      !>## Exceptions
      !>
      !>     If an error is found, the output argument FOUND will be set to
      !>     .FALSE.
      !>
      !>     1)  If either of the semi-axes of the input ellipse is the
      !>         zero vector, the error SPICE(ZEROVECTOR) will be signaled.
      !>
      !>     2)  If the norm of the input ellipse's semi-minor axis is
      !>         zero after division by the maximum of the norms of the
      !>         semi-major axis, the ellipse's center, and the vertex of
      !>         the pyramid, the error SPICE(DEGENERATECASE) will be
      !>         signaled.
      !>
      !>     3)  If the vertex of the pyramid lies in the plane containing
      !>         the ellipse, at most the edge of the ellipse can be "seen"
      !>         from the vertex.  This case is not considered to be an
      !>         error.
      !>
      !>     4)  If the number of boundary vectors N is not at least 3,
      !>         the error SPICE(INVALIDCOUNT) will be signaled. PEPPER:
      !>         there is no maximum (SPICELIB: MAXFOV = 10000).
      !>
      !>     5)  If any boundary vector is the zero vector, the error
      !>         SPICE(ZEROVECTOR) will be signaled.
      !>
      !>     6)  If the axis is the zero vector, the error SPICE(ZEROVECTOR)
      !>         will be signaled.
      !>
      !>     7)  If any boundary vector has angular separation of at least
      !>         pi/2 radians from AXIS, the error SPICE(INVALIDFOV)
      !>         will be signaled.
      !>
      !>     8)  If any boundary vector has angular separation of zero
      !>         radians from one of its neighbors, the error SPICE(INVALIDFOV)
      !>         will be signaled.
      !>
      !>     9)  No test is done to ensure that the input boundary vectors
      !>         define a non-self-intersecting polygon via their intersection
      !>         with a plane normal to AXIS.  If the boundary vectors don't
      !>         meet this condition, the results of this routine are
      !>         unreliable.
      !>
      !>     10) The pyramidal field of view and the input ellipse must not
      !>         differ too radically in scale, or great loss of precision
      !>         will result, making the results of this routine unreliable.
      !>         For example, if the ratio of the norm of the semi-minor axis
      !>         of the ellipse to the distance from VERTEX to the center of
      !>         the ellipse is less than double precision epsilon on the host
      !>         system, a meaningful result can't be computed.
      !>
      !>         This routine does not attempt to judge the minimum
      !>         acceptable level of accuracy.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     This routine is useful for determining whether an ellipsoidal
      !>     body is in the field of view of a remote-sensing instrument
      !>     with a field of view having polygonal cross section.
      !>
      !>## Examples
      !>
      !>     Test an ellipse for intersection with a square field
      !>     of view.
      !>
      !>           PROGRAM EX1
      !>           IMPLICIT NONE
      !>
      !>           INTEGER               MAXN
      !>           PARAMETER           ( MAXN   = 4 )
      !>
      !>           INTEGER               UBEL
      !>           PARAMETER           ( UBEL   = 9 )
      !>
      !>           DOUBLE PRECISION      AXIS   ( 3 )
      !>           DOUBLE PRECISION      CENTER ( 3 )
      !>           DOUBLE PRECISION      ELLIPS ( UBEL )
      !>           DOUBLE PRECISION      FOV    ( 3, MAXN )
      !>           DOUBLE PRECISION      SMAJOR ( 3 )
      !>           DOUBLE PRECISION      SMINOR ( 3 )
      !>           DOUBLE PRECISION      VERTEX ( 3 )
      !>
      !>           INTEGER               N
      !>
      !>           LOGICAL               FOUND
      !>
      !>     C
      !>     C     The FOV (field of view) "looks" in the -x direction:
      !>     C     the axis of the FOV is parallel to the x axis.
      !>     C     The FOV intersects the plane of the ellipse in a
      !>     C     square having height and width 4 units.  The edges
      !>     C     of the square are parallel to the y and z axes.
      !>     C
      !>           N = 4
      !>
      !>           CALL VPACK ( -1.D0,  -1.D0, -1.D0,  FOV(1,1) )
      !>           CALL VPACK ( -1.D0,   1.D0, -1.D0,  FOV(1,2) )
      !>           CALL VPACK ( -1.D0,   1.D0,  1.D0,  FOV(1,3) )
      !>           CALL VPACK ( -1.D0,  -1.D0,  1.D0,  FOV(1,4) )
      !>
      !>           CALL VPACK ( -1.D0,   0.D0,  0.D0,  AXIS     )
      !>           CALL VPACK (  1.D0,   0.D0,  0.D0,  VERTEX   )
      !>
      !>     C
      !>     C     The ellipse is oriented with the major axis
      !>     C     vertical and is parallel to the x-z plane.  The ellipse
      !>     C     lies in the plane defined by x = -1.  The ellipse
      !>     C     ever-so-slightly overlaps the bottom edge of the FOV.
      !>     C
      !>           CALL VPACK (  0.D0,   0.D0,   1.D0,           SMAJOR )
      !>           CALL VPACK (  0.D0,   5.D-1,  0.D0,           SMINOR )
      !>           CALL VPACK ( -1.D0,   0.D0,  -3.D0 + 1.D-12,  CENTER )
      !>
      !>     C
      !>     C     Create a SPICELIB ellipse from the center and semi-axes.
      !>     C
      !>           CALL CGV2EL ( CENTER, SMAJOR, SMINOR, ELLIPS )
      !>
      !>     C
      !>     C     Test for intersection.  We expect an intersection to be
      !>     C     found.
      !>     C
      !>           CALL ZZELVUPY ( ELLIPS, VERTEX, AXIS, N, FOV, FOUND )
      !>
      !>           WRITE (*,*) 'Case 1: FOUND = ', FOUND
      !>
      !>     C
      !>     C     Shift the ellipse center to move the ellipse outside of
      !>     C     the FOV, then repeat the test.  We expect FOUND to be
      !>     C     .FALSE.
      !>     C
      !>           CALL VPACK ( -1.D0,   0.D0,  -3.D0 - 1.D-12,  CENTER )
      !>
      !>           CALL CGV2EL ( CENTER, SMAJOR, SMINOR, ELLIPS )
      !>
      !>           CALL ZZELVUPY ( ELLIPS, VERTEX, AXIS, N, FOV, FOUND )
      !>
      !>           WRITE (*,*) 'Case 2: FOUND = ', FOUND
      !>
      !>           END
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     [1] `Calculus and Analytic Geometry', Thomas and Finney.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>     B.V. Semenov    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 28-FEB-2008 (BVS)
      !>
      !>        Corrected the contents of the Required_Reading section.
      !>
      !>-    SPICELIB Version 1.0.0, 10-AUG-2005 (NJB)
      module subroutine zzelvupy ( ctx, ellips, vertex, axis, n, bounds, found )
      use pepper_kinds, only: ip, wp
      use pepper_containers, only: grow
      use pepper_constants, only: pi
      use pepper_math, only: el2cgv, ucrss, vdist, vdot, vhat, vnorm, vsep
      use pepper_inc_errhnd
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: ubel = 9
      real(wp), intent(in) :: ellips ( ubel )  !! A SPICELIB ellipse.
      real(wp), intent(in) :: vertex ( 3 )  !! Vertex of a pyramid.
      real(wp), intent(in) :: axis   ( 3 )  !! Axis of a pyramid.
      integer(ip), intent(in) :: n  !! Number of boundary vectors of the pyramid.
      real(wp), intent(in) :: bounds ( 3, n )  !! Boundary vectors of the pyramid.
      logical, intent(out) :: found  !! Flag indicating whether intersection was found.
      character(lmsgln) :: errmsg
      real(wp) :: a
      real(wp) :: apex   ( 3 )
      real(wp) :: asep
      real(wp) :: b
      real(wp) :: center ( 3 )
      real(wp) :: consep
      real(wp) :: cp     ( 3 )
      real(wp) :: ctrvec ( 3 )
      real(wp) :: d
      real(wp) :: easize
      real(wp) :: ebsctr ( 3 )
      real(wp) :: edge1  ( 3 )
      real(wp) :: edge2  ( 3 )
      real(wp) :: ellscl ( ubel )
      real(wp) :: eplane ( ubpl )
      real(wp) :: fovpln ( ubpl )
      real(wp) :: gv1    ( 3 )
      real(wp) :: gv2    ( 3 )
      real(wp) :: hafedg
      real(wp) :: hafsec
      real(wp) :: offset ( 3 )
      real(wp) :: pasize
      real(wp) :: plane  ( ubpl )
      real(wp) :: scale
      real(wp) :: smajor ( 3 )
      real(wp) :: sminor ( 3 )
      real(wp) :: vbsctr ( 3 )
      real(wp) :: vtemp  ( 3 )
      real(wp) :: vxpt1  ( 3 )
      real(wp) :: vxpt2  ( 3 )
      real(wp) :: x
      real(wp) :: xpt    ( 3 )
      real(wp) :: xpt1   ( 3 )
      real(wp) :: xpt2   ( 3 )
      real(wp) :: y
      integer(ip) :: i
      integer(ip) :: j
      integer(ip) :: nxpts
      if ( .not. allocated ( ctx%zzelvupy_state ) ) then
         allocate ( ctx%zzelvupy_state )
         call init_zzelvupy_state ( ctx%zzelvupy_state )
      end if
      call grow ( ctx%zzelvupy_state%work, max ( n, 1_ip ), 3_ip )
      associate ( origin => ctx%zzelvupy_state%origin, &
                  work => ctx%zzelvupy_state%work )
      if ( ctx%failed() ) return

!
!     We start out by checking the inputs.
!
!     The next step will be to look for an intersection of the ellipse
!     and pyramid.  There are three intersection cases:
!
!        1) The ellipse is completely contained in the pyramid.
!
!        2) The ellipse "contains" the field of view in the sense
!           that the intersection of the pyramid and the plane of the
!           ellipse is contained in the region bounded by the ellipse.
!
!        3) One or more sides of the pyramid intersect the ellipse.
!
!     There is also a non-intersection case:  this is when cones
!     bounding the ellipse and pyramid and having their apexes in
!     common with that of the pyramid intersect only in that common
!     apex.  Before test (1), we perform this non-intersection test,
!     since it can be done quickly.
!
!     No intersection has been found so far.  Set the default value
!     of the FOUND flag here so it won't have to be set in every error
!     checking block below.
!
      found = .false.

!
!     Validate the ellipse.  First find the center and the semi-axes
!     of the ellipse.
!
      call el2cgv ( ellips, center, gv1,    gv2    )
      call saelgv ( ctx, gv1,    gv2,    smajor, sminor )

!
!     Check the semi-axis lengths.
!
!     If the semi-major axis is the zero vector, we'd expect
!     the semi-minor axis to be the zero vector as well.  But
!     round-off error could conceivably violate this assumption.
!
      if ( all(smajor == 0.0_wp) .or. all(sminor == 0.0_wp) ) then

         call ctx%setmsg ( 'Input ellipse has semi-major axis '   // &
                       'length # and semi-minor axis length ' // &
                       '#.  Both vectors are required to be ' // &
                       'non-zero.'                            )
         call ctx%errdp  ( '#', vnorm(smajor)                     )
         call ctx%errdp  ( '#', vnorm(sminor)                     )
         call ctx%sigerr ( 'SPICE(ZEROVECTOR)'                    )
         return

      end if

!
!     Scale the vectors defining the ellipse and the vertex of the
!     pyramid so that the largest of these vectors has unit length.
!
      scale = 1.0_wp / max ( vnorm(center), vnorm(smajor), vnorm(vertex) )

      do i = 1, 3

         center(i) = scale * center(i)
         smajor(i) = scale * smajor(i)
         sminor(i) = scale * sminor(i)
         apex  (i) = scale * vertex(i)

      end do

!
!     Create a scaled ellipse.  We'll perform the FOV side-ellipse
!     intersection computations using this ellipse.
!
      call cgv2el ( ctx, center, smajor, sminor, ellscl )

!
!     After scaling, make sure the semi-axes have sufficient length to
!     prevent numerical problems.  Let A and B be the scaled semi-axis
!     lengths of the ellipse.
!
      a = vnorm ( smajor )
      b = vnorm ( sminor )

      if ( b == 0.0_wp ) then

         call ctx%setmsg ( 'Scaled ellipse''s semi-minor axis length = 0.' )
         call ctx%sigerr ( 'SPICE(DEGENERATECASE)'                         )
         return

      end if

!
!     Validate the input pyramid.
!
!     The axis must not be the zero vector.
!
      if (  all(axis == 0.0_wp)  ) then

         call ctx%setmsg ( 'The pyramid''s axis the zero vector.' )
         call ctx%sigerr ( 'SPICE(ZEROVECTOR)'                    )
         return

      end if

!
!     There must be at least three boundary vectors.
!
      if ( n < 3 ) then

         call ctx%setmsg ( 'The number of boundary vectors was #; ' // &
                       'this number must be at least 3.'        )
         call ctx%errint ( '#',  n                                  )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                    )
         return

      end if

!
!     We must initialize certain variables before continuing with
!     the checks.
!
!     Let CTRVEC be the vector from the apex to the center of the
!     ellipse.  This vector will be used in several places later;
!     it's convenient to compute it here.
!
      ctrvec = center - apex

!
!     Compute PASIZE:  an upper bound on the angular radius of a
!     circular cone whose axis is the input central axis.  While
!     we're at it, check the angular separation of the boundary
!     vectors from the central axis and from each other.
!
      pasize = 0.0_wp

      do i = 1, n
!
!        Each boundary vector must have angular separation from the
!        axis of less than pi/2 radians.  Keep track of the maximum
!        angular separation PASIZE as we go.  We'll use this variable
!        later in a non-intersection test.
!
         asep = vsep ( axis, bounds(1,i) )

         if ( asep >= pi/2  ) then

            call ctx%setmsg ( 'The angular separation of boundary '   // &
                          'vector # from the axis is #. This '    // &
                          'number must less than pi/2.'           )
            call ctx%errint ( '#',  i                                 )
            call ctx%errdp  ( '#',  asep                              )
            call ctx%sigerr ( 'SPICE(INVALIDFOV)'                     )
            return

         end if

         pasize = max ( pasize, asep )

!
!        Each boundary vector must have non-zero angular separation
!        from its neighbors.
!
         if ( i < n ) then
            j  = i + 1
         else
            j  = 1
         end if

         call ucrss ( bounds(1,i), bounds(1,j), cp )

         if ( all(cp == 0.0_wp) ) then
!
!           The cross product may be zero because one of the
!           boundary vectors is zero.  Check this first.
!
            if (  all(bounds(:,j) == 0.0_wp) .or. all(bounds(:,i) == 0.0_wp) ) then

               if (  all(bounds(:,i) == 0.0_wp)  ) then
                  j = i
               end if

               call repmot ( ctx, 'The # boundary vector is the zero vector.', &
                             '#', j, 'L', errmsg )
               call ctx%setmsg ( errmsg                      )
               call ctx%sigerr ( 'SPICE(ZEROVECTOR)'         )

            else

               call ctx%setmsg ( 'The angular separation of boundary '   // &
                             'vector # from vector # is 0.'          // &
                             'This number must be positive.'         )
               call ctx%errint ( '#',  i                                 )
               call ctx%errint ( '#',  j                                 )
               call ctx%sigerr ( 'SPICE(INVALIDFOV)'                     )

            end if

            return

         end if

      end do

!
!     That's it for the error checks.  We'll now answer the question
!     this routine is meant to answer:  does the ellipse or the region
!     it bounds intersect the pyramid?
!
!     We'll start out with a simple check to rule out intersection
!     when the ellipse and pyramid are contained in disjoint right
!     circular cones with a common apex.
!
!     Find the angular radius (that is, one-half of the angular extent)
!     of a bounding cone of the ellipse as seen from the apex.  The
!     cone circumscribes a sphere of radius A centered at the ellipse's
!     center, where A is the length of the semi-major axis.  Note that
!     the cone does not in general circumscribe the ellipse itself.
!
!     The test can be performed only if the apex of the FOV is outside
!     of the sphere of radius A centered at the ellipse center.
!
      d  =  vdist ( center, apex )

      if ( a < d ) then

         easize  =  asin ( a / d )

!
!        The variable PASIZE already contains the angular radius of a
!        bounding cone of the pyramid as seen from the pyramid's apex.
!        The angular radius is the maximum of the angular separations
!        of each pyramid edge from the pyramid's axis. Check whether
!        the bounding cones of ellipse and pyramid are disjoint. Recall
!        CTRVEC is the vector from the apex to the center of the
!        ellipse.  If the angular separation of CTRVEC and AXIS exceeds
!        the sum of the angular radii of the ellipse's and pyramid's
!        bounding cones, there can be no intersection.
!
         consep = vsep ( ctrvec, axis )  -  ( easize + pasize )

         if ( consep > 0.0_wp ) return

      end if

!
!     At this point, we have to take a more detailed look at the
!     possible intersection of ellipse and pyramid.  First check
!     whether the center of the ellipse is contained in the pyramid.
!     If the ellipse is completely contained in the pyramid, this
!     check will yield a positive result.
!
!     The center of the ellipse is inside the pyramid if a plane
!     containing this point and normal to the axis vector
!     chops the pyramid in a polygon that has non-zero winding
!     number about the center.
!
!     The center of the ellipse must lie in the correct half-space
!     for this test to be applicable.
!
      if (  vdot( axis, ctrvec ) > 0.0_wp ) then
!
!        Construct the plane and find the polygon.
!
         call nvp2pl ( ctx, axis, ctrvec, fovpln )

!
!        Create the planar FOV boundary using the intersections
!        of the FOV boundary vectors with FOVPLN.
!
         do i = 1, n

            call inrypl ( ctx, origin,  bounds(1,i),  fovpln, &
                          nxpts,   work  (1,i)           )

!
!           We expect to have a single point of intersection for each
!           boundary vector.
!
            if ( nxpts /= 1 ) then

               call ctx%setmsg ( 'NXPTS = # for boundary vector #/FOV ' // &
                             'plane intersection.'                  )
               call ctx%errint ( '#',  nxpts                            )
               call ctx%errint ( '#',  i                                )
               call ctx%sigerr ( 'SPICE(BUG)'                           )
               return

            end if

         end do

!
!        Now WORK contains the polygon representing the intersection of
!        the pyramid with the plane FOVPLN. If the winding number of
!        the polygon about the ellipse center is non-zero, we conclude
!        the center is in the pyramid.
!
         if (   zzwind( ctx, fovpln, n, work, ctrvec )  /=  0 ) then
!
!           The center of the ellipse is inside the pyramid.  We're
!           done.
!
            found = .true.

            return

         end if

      end if

!
!     Check whether the ray defined by APEX and the first boundary
!     vector of the pyramid (the "boundary ray") intersects the plane
!     region bounded by the ellipse.  If the intersection of the
!     pyramid and the plane of the ellipse is completely contained in
!     the region bounded by the ellipse, this check will yield a
!     positive result.
!
!     First find the intersection of the boundary ray and the plane
!     containing the ellipse; represent this plane using the SPICELIB
!     plane EPLANE.

!     We don't check FAILED() here because the spanning vectors
!     are orthogonal, and because PSV2PL (via a call to UCRSS)
!     does scaling to prevent underflow.
!
      call psv2pl ( ctx, center,  smajor,       sminor,  eplane )

      call inrypl ( ctx, apex,    bounds(1,1),  eplane,  nxpts,  xpt )

!
!     The routine INRYPL can return the NXPTS values 1, 0, or INF---a
!     code indicating an infinite number of intersection points of ray
!     and plane.  If the value is 1, the boundary ray may intersect
!     the region bounded by the ellipse.
!
      if ( nxpts == 1 ) then
!
!        The boundary ray intersects the plane of the ellipse in a
!        single point. Decide whether this point is inside the ellipse.
!        To test for containment, find the "coordinates" of the
!        center-to-point vector relative to the two-dimensional basis
!        formed by the semi-axes of the ellipse.  Call this
!        center-to-point vector OFFSET.  Recall A and B are the
!        semi-axis lengths of the ellipse. Let X and Y be the
!        coordinates of OFFSET in the two-dimensional reference frame
!        whose basis consists of normalized versions of SMAJOR and
!        SMINOR.
!
!        Note that we could have the special case in which the vertex
!        of the pyramid lies in the plane of the ellipse, in which case
!        the FOV "sees" the ellipse edge-on.  However, since NXPTS is
!        not INF, the boundary vector does not lie in the plane of the
!        ellipse.  So in this special case, APEX would be in the region
!        bounded by the ellipse.
!
         offset = xpt - center

         x  =  vdot  ( offset, smajor ) / a
         y  =  vdot  ( offset, sminor ) / b

         if (  ( (x/a)**2.0_wp  +  (y/b)**2.0_wp ) <=  1.0_wp  ) then
!
!           The boundary-vector-plane intercept lies in the
!           topologically closed region bounded by the ellipse.
!
            found = .true.

            return

         end if

      end if

!
!     Check whether one of the pyramid's sides intersects the ellipse.
!     For each side, we first test whether the plane containing that
!     side intersects the ellipse.  If it does, the intersection is
!     a (possibly degenerate) line segment with endpoints on the
!     ellipse.  The triangle (or segment) defined by the pyramid's
!     apex and this segment (point) is then checked for intersection
!     with the currently considered side of the pyramid.
!
      i  =  1

      do while (  ( i <= n ) .and. ( .not. found )  )
!
!        Create a SPICELIB plane containing the Ith side of the
!        pyramid.
!
         if ( i < n ) then
            j  = i + 1
         else
            j  = 1
         end if

!
!        Although PSV2PL can signal an error if the spanning
!        vectors are linearly dependent, it won't do so here
!        because we've already ensured the cross product of
!        these vectors is non-zero.
!
         call psv2pl ( ctx, apex, bounds(1,i), bounds(1,j), plane )
!
!        Find the intersection of the plane and the ellipse.
!
         call inelpl ( ctx, ellscl, plane, nxpts, xpt1, xpt2 )

!
!        If the ellipse-plane intersection is non-empty, test it to see
!        whether it has non-empty intersection with the current side of
!        the pyramid.
!
         if ( nxpts > 0 ) then
!
!           Let EDGE1 and EDGE2 be the unit length boundary vectors
!           forming the edges of the currently considered side of the
!           pyramid.
!
            call vhat ( bounds(1,i), edge1 )
            call vhat ( bounds(1,j), edge2 )

!
!           Let EBSCTR ("pyramid edge bisector") be a bisector of the
!           sector bounded by EDGE1 and EDGE2.
!
            ebsctr = 0.5_wp*edge1 + 0.5_wp*edge2

!
!           Let HAFEDG be half of the angular measure of this sector.
!
            hafedg = vsep ( edge1, edge2 ) / 2.0_wp

!
!           Let VXPT1 and VXPT2 be the unit vectors pointing from the
!           pyramid's apex to the points of intersection of the ellipse
!           and the plane containing the currently considered side of
!           the pyramid.
!
            vtemp = xpt1 - apex
            call vhat ( vtemp,        vxpt1 )

            vtemp = xpt2 - apex
            call vhat ( vtemp,        vxpt2 )

!
!           At this point we'll introduce a bit of terminology. We're
!           going to work with plane regions defined by pairs of
!           vectors with a common endpoint.  We'll abuse standard
!           terminology a bit and call the region bounded by such a
!           vector pair a "sector."  Strictly speaking, sectors refer
!           only to subsets of a disc.
!
!           When it's convenient, we'll also identify "sectors" with
!           regions of the unit circle.  This will make it possible
!           to talk about intersections of sectors in terms of
!           intersections of the associated arcs on the unit circle.
!           By the "endpoints" of a sector we mean the endpoints
!           of the arc associated with the sector on the unit circle.
!
!           Let VBSCTR ("VXPT bisector") be a bisector of the sector
!           bounded by VXPT1 and VXPT2.
!
            vbsctr = 0.5_wp*vxpt1 + 0.5_wp*vxpt2

!
!           Let HAFSEC be half of the angular measure of the sector
!           bounded by VXPT1 and VXPT2.
!
            hafsec = vsep ( vxpt1, vxpt2 ) / 2.0_wp

!
!           EDGE1, EDGE2, VXPT1, and VXPT2 are four co-planar vectors
!           emanating from APEX.  We want to find out whether the
!           sector bounded by EDGE1 and EDGE2 intersects the sector
!           bounded by VXPT1 and VXPT2.  If there's an intersection, at
!           least one endpoint of one sector is contained in the other
!           sector.
!
!           Because of potential round-off problems when the sectors
!           are nearly coincident, we perform the precautionary check
!           (case 3) on the angle bisector of the sector defined by
!           VXPT1 and VXPT2.
!
!           If the sector defined by VXPT1 and VXPT2 has no endpoint
!           contained in the other sector, it's possible that the
!           former sector contains the latter.  In that case the
!           angular bisector of the latter sector is contained in the
!           former (case 4).
!
!           We test a vector's containment in a sector by comparing the
!           vector's angular separation from the sector's angle
!           bisector to one-half of the angular measure of the sector.
!
!              Case 1:  VXPT1 lies between EDGE1 and EDGE2.
!              Case 2:  VXPT2 lies between EDGE1 and EDGE2.
!              Case 3:  VBSCTR lies between EDGE1 and EDGE2.
!              Case 4:  EBSCTR lies between VXPT1 and VXPT2.
!
            if      ( vsep(vxpt1,  ebsctr) <= hafedg ) then

               found = .true.

            else if ( vsep(vxpt2,  ebsctr) <= hafedg ) then

               found = .true.

            else if ( vsep(vbsctr, ebsctr) <= hafedg ) then

               found = .true.

            else if ( vsep(ebsctr, vbsctr) <= hafsec ) then

               found = .true.

            end if

            if ( found ) then
!
!              We've found an intersection.  We're done.
!
               return

            end if

         end if

!
!        If no intersection was found, look at the next side of the
!        pyramid.
!
         i = i + 1

      end do

!
!     If we got this far, the ellipse is not in view.  FOUND has
!     already been set to .FALSE.
!

      return
      end associate
      end subroutine zzelvupy

      !> Test a point represented by a set of planetodetic coordinates for
      !> inclusion in a specified planetodetic volume element. Ellipsoidal
      !> surfaces are used in place of surfaces of constant altitude. The
      !> test is performed using margins for the element.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     P          is a point expressed in Cartesian coordinates. The
      !>                point is to be checked to determine whether it is
      !>                inside the volume element specified by BOUNDS.
      !>
      !>     BOUNDS     is an 2x3 array containing the bounds of a volume
      !>                element expressed in planetodetic coordinates. BOUNDS
      !>                defines the volume element used in the comparison. In
      !>                the element
      !>
      !>                   BOUNDS(I,J)
      !>
      !>                J is the coordinate index. J is one of
      !>
      !>                   { LONIDX, LATIDX, ALTIDX }
      !>
      !>                I is the bound index.
      !>
      !>                   I = 1   ->   lower bound
      !>                   I = 2   ->   upper bound
      !>
      !>                If the longitude upper bound is not greater than the
      !>                longitude lower bound, a value greater than the upper
      !>                bound by 2*pi is used for the comparison.
      !>
      !>     CORPAR     is an array of coordinate parameters; normally these
      !>                are obtained from a DSK descriptor. The first element
      !>                is the equatorial radius of the reference spheroid.
      !>                The second element is the flattening coefficient.
      !>                Any other elements are ignored by this routine.
      !>
      !>     MARGIN     is a fraction used to expand the volume element for
      !>                inclusion testing.
      !>
      !>                   - The upper altitude bound is increased by
      !>
      !>                        MARGIN*ABS( BOUNDS(2,3) )
      !>
      !>                     The lower altitude bound is decreased by
      !>
      !>                        MARGIN*ABS( BOUNDS(1,3) )
      !>
      !>                     Note that these bounds are used as inputs to
      !>                     compute the radii of upper and lower bounding
      !>                     ellipsoids. The input point's position is tested
      !>                     for inclusion within or exclusion from these
      !>                     ellipsoids.
      !>
      !>                   - Latitude bounds are extended by MARGIN radians,
      !>                     within the interval -pi/2 : pi/2.
      !>
      !>                   - For any input point having latitude "not close"
      !>                     to pi/2 or -pi/2, the element's longitude
      !>                     interval is extended by
      !>
      !>                        MARGIN / cos(LAT) radians
      !>
      !>                     where LAT is the planetocentric [sic] latitude of
      !>                     the input point.
      !>
      !>                     Here "close to" means "within LATMRG radians of."
      !>
      !>                   - For any input point having planetocentric
      !>                     latitude close to (within LATMRG radians of) pi/2
      !>                     or -pi/2, comparison against the longitude bounds
      !>                     of the volume element is omitted if MARGIN > 0.
      !>
      !>     EXCLUD     is either a coordinate index or the parameter NONE.
      !>
      !>                If EXCLUD is set to one of
      !>
      !>                   { LONIDX, LATIDX, ALTIDX }
      !>
      !>                then the indicated coordinate is excluded from
      !>                comparison with the corresponding volume element
      !>                boundaries.
      !>
      !>                If EXCLUD is set to NONE, all coordinates are
      !>                compared.
      !>
      !>                Exclusion of coordinates is used in cases where a
      !>                point is known to be on a level surface of a given
      !>                coordinate. For example, if a point is on the outer
      !>                bounding ellipsoid, the level surface parameter of the
      !>                point with respect to the ellipsoid need not be used
      !>                in the comparison and in fact can't be meaningfully
      !>                compared, due to round-off errors.
      !>
      !>## Detailed Output
      !>
      !>     INSIDE     is a logical flag that is set to .TRUE. if and
      !>                only if the input coordinates represent a
      !>                point inside or on the surface of the volume
      !>                element, according to the comparisons that are
      !>                performed.
      !>
      !>                The value of INSIDE is not affected by the value
      !>                of any excluded coordinate.
      !>
      !>## Parameters
      !>
      !>     LONALI     is a longitude shift margin. If the input longitude
      !>                coordinate LON is less than the longitude lower bound
      !>                by more than this amount, the value LON + 2*pi is
      !>                used in the longitude comparison, provided that the
      !>                comparison is not excluded.
      !>
      !>                See dsktol.inc for details.
      !>
      !>     NONE       when used as a value of the input argument EXCLUD,
      !>                indicates that no coordinates should be excluded from
      !>                comparison.
      !>
      !>     LONIDX     is the index of longitude in the second dimension of
      !>                BOUNDS. When used as a value of the input argument
      !>                EXCLUD, indicates that longitude should be excluded
      !>                from comparison.
      !>
      !>     LATIDX     is the index of latitude in the second dimension of
      !>                BOUNDS. When used as a value of the input argument
      !>                EXCLUD, indicates that latitude should be excluded
      !>                from comparison.
      !>
      !>     ALTIDX     is the index of altitude in the second dimension of
      !>                BOUNDS. When used as a value of the input argument
      !>                EXCLUD, indicates that altitude should be excluded
      !>                from comparison.
      !>
      !>     LATMRG     is the margin used to determine whether the input
      !>                latitude is "close" to the poles. Units are radians.
      !>                The value of this parameter must be kept in sync
      !>                with the "greedy" margin declared in dsktol.inc.
      !>
      !>## Exceptions
      !>
      !>     1)  If MARGIN is negative, the error SPICE(VALUEOUTOFRANGE)
      !>         is signaled.
      !>
      !>     2)  If EXCLUD is outside of the range 0:3, the error
      !>         SPICE(VALUEOUTOFRANGE) is signaled.
      !>
      !>     3)  If an error occurs while determining the planetodetic
      !>         coordinates of the input point, the error will be signaled by
      !>         a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     None.
      !>
      !>## Examples
      !>
      !>     See usage in ZZRYTPDT.
      !>
      !>## Restrictions
      !>
      !>     1)  This is a private routine. It is meant to be used only by the
      !>         DSK subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 13-FEB-2017 (NJB)
      !>
      !>        03-JUN-2016 (NJB)
      !>
      !>           Added standard traceback participation. Added check for
      !>           invalid values of EXCLUD.
      !>
      !>        05-MAR-2016 (NJB)
      !>
      !>           Original version 03-OCT-2014 (NJB)
      module subroutine zzinpdt ( ctx, p, bounds, corpar, margin, exclud, inside )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: halfpi, pi, twopi
      use pepper_math, only: reclat
      use pepper_inc_dsktol
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: p      ( 3 )  !! Input point.
      real(wp), intent(in) :: bounds ( 2, 3 )  !! Coordinate bounds of element.
      real(wp), intent(in) :: corpar ( * )  !! Coordinate system parameters.
      real(wp), intent(in) :: margin  !! Margin used for inclusion testing.
      integer(ip), intent(in) :: exclud  !! Index of coordinate to exclude from test.
      logical, intent(out) :: inside  !! Flag indicating whether point is in element.
      integer(ip), parameter :: none = 0
      integer(ip), parameter :: lower = 1
      integer(ip), parameter :: upper = 2
      real(wp) :: amnalt
      real(wp) :: amnlat
      real(wp) :: amnlon
      real(wp) :: amxalt
      real(wp) :: amxlat
      real(wp) :: amxlon
      real(wp) :: dlon
      real(wp) :: f
      real(wp) :: lon
      real(wp) :: lonmrg
      real(wp) :: maxalt
      real(wp) :: maxlat
      real(wp) :: maxlon
      real(wp) :: minalt
      real(wp) :: minlat
      real(wp) :: minlon
      real(wp) :: pcnlat
      real(wp) :: r
      real(wp) :: re
      integer(ip) :: relmin
      integer(ip) :: relmax
      logical :: alpass
      if ( .not. allocated ( ctx%zzinpdt_state ) ) allocate ( ctx%zzinpdt_state )
      associate ( altbds => ctx%zzinpdt_state%altbds, &
                  first => ctx%zzinpdt_state%first, &
                  hpi => ctx%zzinpdt_state%hpi, &
                  pi2 => ctx%zzinpdt_state%pi2 )
      if ( ctx%failed() ) return

      if ( first ) then

         hpi   = halfpi
         pi2   = twopi
!
!        Initialize the local array used for altitude checks.
!
         altbds( south, latidx ) =  - halfpi
         altbds( north, latidx ) =    halfpi
         altbds( west,  lonidx ) =  - pi
         altbds( east,  lonidx ) =    pi
         altbds( lower, altidx ) =    0.0_wp
         altbds( upper, altidx ) =    0.0_wp

         first = .false.

      end if

      if (  ( exclud < 0 ) .or. ( exclud > 3 )  ) then

         call ctx%setmsg ( 'EXCLUD must be in the range 0:3 but was #.' )
         call ctx%errint ( '#', exclud                                  )
         call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'                     )
         return

      end if

!
!     Get the planetocentric [sic] coordinates of the input point. The
!     latitude we obtain will be planetocentric. To emphasize this, we
!     use the name "PCNLAT."
!
      call reclat ( p, r, lon, pcnlat )
!
!     RECLAT is error free, so we don't call FAILED() here.
!

      if ( margin == 0.0_wp ) then
!
!        ZZINPDT0 contains the logic required to determine whether
!        the input point is contained in the element.
!
         call zzinpdt0 ( ctx, p,      lon, &
                         bounds, corpar, exclud, inside )

         return

      else if ( margin < 0.0_wp ) then

         call ctx%setmsg ( 'Margin must be non-negative but was #.' )
         call ctx%errdp  ( '#', margin                              )
         call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'                 )
         return

      end if

!
!     At this point a more detailed analysis is needed.
!
!     Assume the point is outside to start. This allows us
!     to skip setting INSIDE when we find a boundary test
!     failure.
!
      inside = .false.

!
!     We'll use the shape parameters for latitude and altitude
!     comparisons.
!
      re = corpar(1)
      f  = corpar(2)

!
!     Get local copies of the coordinate bounds. Don't normalize the
!     longitude bounds until we know we need them.
!
      minlat = bounds( south, latidx )
      maxlat = bounds( north, latidx )

      minalt = bounds( lower, altidx )
      maxalt = bounds( upper, altidx )

!
!     Compare coordinates to adjusted latitude boundaries.
!
      if ( exclud /= latidx ) then
!
!        Create adjusted latitude bounds.
!
         amnlat = max( -hpi-angmrg, minlat - margin )
         amxlat = min(  hpi+angmrg, maxlat + margin )

!
!        Compare the latitude of the input point to the bounds.
!
         call zzpdcmpl ( ctx, re, f, p, amnlat, relmin )
         call zzpdcmpl ( ctx, re, f, p, amxlat, relmax )

         if ( ctx%failed() ) return

         if ( ( relmin == lt ) .or. ( relmax == gt ) ) then
!
!           The latitude of P is strictly outside of the element's
!           latitude bounds.
!
            return
         end if

      end if

!
!     Test the point for inclusion in the region between the bounding
!     ellipsoids that act as proxies for altitude boundaries.
!
      if ( exclud /= altidx ) then
!
!        Extract altitude bounds from the segment descriptor.
!
         minalt = bounds(lower, altidx)
         maxalt = bounds(upper, altidx)
!
!        Adjust altitude bounds to account for the margin.
!
         amnalt = minalt  -  margin * abs(minalt)
         amxalt = maxalt  +  margin * abs(maxalt)
!
!        Set up a "boundary" array so that we can use ZZINPDT0
!        to do the altitude check for us. We'll exclude longitude
!        tests; the latitude test is set up for an automatic pass
!        (the latitude range of ALTBDS is [-pi/2, pi/2]).
!
         altbds( lower, altidx ) = amnalt
         altbds( upper, altidx ) = amxalt

         call zzinpdt0 ( ctx, p, lon, altbds, corpar, lonidx, alpass )

         if ( .not. alpass ) return

      end if

!
!     At this point, the input altitude and latitude are within the
!     adjusted bounds, if their tests haven't been excluded by
!     the caller.
!
!     Perform longitude tests, unless they're excluded by the
!     caller.
!
      if ( exclud /= lonidx ) then
!
!        Start out by normalizing the element's longitude bounds.
!
         call zznrmlon ( ctx, bounds(lower,lonidx),  bounds(upper,lonidx), &
                         angmrg,       minlon,  maxlon               )

         if ( ctx%failed() ) return
!
!        Set the margin to be used for longitude interval
!        inclusion tests.
!
         lonmrg = max( abs(angmrg), abs(margin) )

!
!        We have a special case for segments that include the poles. If
!        the latitude and altitude of the input point are within
!        bounds, and if the latitude of the point is close enough to a
!        pole we consider the point to be included in the segment,
!        regardless of the point's longitude. All other points get the
!        normal longitude test.
!
!        We use planetocentric latitude to determine whether the point
!        is "close" to a pole.
!
         call zzpdcmpl ( ctx, re, f, p,  hpi-latmrg, relmax )
         call zzpdcmpl ( ctx, re, f, p, -hpi+latmrg, relmin )

         if ( ctx%failed() ) return

         if (       ( relmax /= gt ) &
              .and. ( relmin /= lt )  ) then
!
!           This is the usual case: the latitude of the input point is
!           bounded away from the poles.
!
!           Check the point's longitude against the segment's longitude
!           bounds.
!
!           We'll scale the longitude margin to compensate for the
!           latitude of the input point. Note that the division
!           below is safe; presuming a reasonable value of MARGIN,
!           we know that
!
!              DLON << 1
!
!           Note that we use planetocentric latitude for scaling the
!           longitude margin. This substitution (for planetodetic
!           latitude) is adequate for this purpose.
!
            dlon   =  lonmrg / max( abs(cos(pcnlat)), latmrg )

            amnlon = minlon - dlon
            amxlon = maxlon + dlon

!
!           Now move the input point's longitude into range, if
!           necessary, so we can make a valid comparison against
!           the longitude bounds.
!
            if ( lon < amnlon ) then

               if (  lon  < ( amnlon - lonali )  ) then
!
!                 See whether an aliased version of LON is a match.
!
                  lon = lon + pi2

               else
!
!                 Consider LON to be a match with the lower bound.
!
                  lon = amnlon

               end if

            else if ( lon > amxlon ) then

               if (  lon  > ( amxlon + lonali )  ) then
!
!                 See whether an aliased version of LON is a match.
!
                  lon = lon - pi2

               else
!
!                 Consider LON to be a match with the upper bound.
!
                  lon = amxlon

               end if

            end if

            if ( ( lon < amnlon ) .or. ( lon > amxlon ) ) return

         else

!
!           The latitude of the input point is close to one of the
!           poles.
!
!           This is a no-op case.
!
!           The input point has already passed whichever of the
!           altitude and latitude tests that were not excluded.
!
!           If the element has a non-degenerate latitude boundary
!           having the same sign as the latitude of the input point,
!           and if latitude is excluded because the input point is
!           already nominally on that boundary, then passing the
!           altitude check implies that the point is close to the
!           element.
!
!           If the element has a degenerate latitude boundary having
!           the same sign as the latitude of the input point---namely,
!           the element contains the pole, and latitude is excluded,
!           then then passing the altitude check implies that the point
!           is close to the portion of the Z-axis contained in the
!           element.
!
!           If the altitude check has been excluded because the point
!           is already nominally on one of the element's altitude
!           boundaries, the passing the latitude test implies the point
!           is close to the element.
!
!           In all cases, as long as EXCLUD has been set appropriately,
!           the point is close to the element. We consider the point to
!           be in the expanded element.
!
         end if

      end if

!
!     All tests that were commanded have been passed. The input
!     point is considered to be contained in the expanded volume
!     element.
!
      inside = .true.

      return
      end associate
      end subroutine zzinpdt

      !> Find nearest intersection to a given ray's vertex of that ray and
      !> at latitudinal volume element. If the vertex is inside the
      !> element, the vertex is considered to be the solution.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     VERTEX,
      !>     RAYDIR     are, respectively, the vertex and direction vector of
      !>                the ray to be used in the intercept computation.
      !>
      !>                Both the vertex and ray direction must be represented
      !>                in the reference frame to which the volume element
      !>                boundaries correspond. The vertex is considered to be
      !>                an offset from the center of the reference frame
      !>                associated with the volume element.
      !>
      !>     BOUNDS     is a 2x3 array containing the bounds of a latitudinal
      !>                volume element. Normally this is the coverage boundary
      !>                of a DSK segment. In the element
      !>
      !>                   BOUNDS(I,J)
      !>
      !>                J is the coordinate index. J is one of
      !>
      !>                   { LONIDX, LATIDX, RADIDX }
      !>
      !>                I is the bound index.
      !>
      !>                   I = 1   ->   lower bound
      !>                   I = 2   ->   upper bound
      !>
      !>                If the longitude upper bound is not greater than the
      !>                longitude lower bound, a value greater than the upper
      !>                bound by 2*pi is used for the comparison.
      !>
      !>     MARGIN     is a scale factor used to effectively expand the
      !>                segment boundaries so as to include intersections
      !>                that lie slightly outside the volume element.
      !>
      !>## Detailed Output
      !>
      !>     XPT        is the intercept of the ray on the surface described
      !>                by the input coordinate bounds, if such an intercept
      !>                exists. If the ray intersects the surface at multiple
      !>                points, the one closest to the ray's vertex is
      !>                selected. XPT is valid if and only if FOUND is .TRUE.
      !>
      !>                XPT is expressed in the reference frame associated
      !>                with the inputs VERTEX and RAYDIR. XPT represents
      !>                an offset from the origin of the coordinate system.
      !>
      !>                XPT is valid only if NXPTS is set to 1.
      !>
      !>     NXPTS      is the number of intercept points of the ray and
      !>                the volume element.
      !>
      !>                Currently there are only two possible values for
      !>                NXPTS:
      !>
      !>                   1 for an intersection
      !>                   0 for no intersection
      !>
      !>                If the vertex is inside the element, NXPTS is
      !>                set to 1.
      !>
      !>## Parameters
      !>
      !>     LONIDX     is the index of longitude in the second dimension of
      !>                BOUNDS.
      !>
      !>     LATIDX     is the index of latitude in the second dimension of
      !>                BOUNDS.
      !>
      !>     RADIDX     is the index of radius in the second dimension of
      !>                BOUNDS.
      !>
      !>## Exceptions
      !>
      !>     For the sake of run-time efficiency, this routine does not
      !>     participate in call tracing. However, it's possible for
      !>     routines called by this routine to signal errors.
      !>
      !>## Files
      !>
      !>     None. However, the input volume element boundaries normally have
      !>     been obtained from a segment in a loaded DSK file.
      !>
      !>## Particulars
      !>
      !>     This routine sits on top of data DSK type-specific ray-segment
      !>     intercept routines such as DSKX02.
      !>
      !>## Examples
      !>
      !>     See usage in ZZDSKBUX.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 18-JAN-2017 (NJB)
      !>
      !>        Based on ZZRYXLAT 20-MAR-2015 (NJB)
      !>
      !>        Original 01-OCT-2014 (NJB)
      module subroutine zzrytlat ( ctx, vertex, raydir, bounds, margin, nxpts, xpt )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: dpmax, halfpi
      use pepper_math, only: reclat, ucrss, vdist, vdot, vhat, vnorm
      use pepper_inc_dsktol
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: vertex ( 3 )  !! Ray's vertex.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      real(wp), intent(in) :: bounds ( 2, 3 )  !! Bounds of latitudinal volume element.
      real(wp), intent(in) :: margin  !! Margin used for element expansion.
      integer(ip), intent(out) :: nxpts  !! Number of intercept points.
      real(wp), intent(out) :: xpt    ( 3 )  !! Intercept.
      real(wp) :: angle
      real(wp) :: dist
      real(wp) :: eastb  ( 3 )
      real(wp) :: eback  ( 3 )
      real(wp) :: endpt2 ( 3 )
      real(wp) :: loncov
      real(wp) :: maxlat
      real(wp) :: maxlon
      real(wp) :: maxr
      real(wp) :: minlat
      real(wp) :: minlon
      real(wp) :: minr
      real(wp) :: mndist
      real(wp) :: negdir ( 3 )
      real(wp) :: s
      real(wp) :: srfx   ( 3 )
      real(wp) :: udir   ( 3 )
      real(wp) :: vlat
      real(wp) :: vlon
      real(wp) :: vr
      real(wp) :: wback  ( 3 )
      real(wp) :: westb  ( 3 )
      real(wp) :: xpt2   ( 3 )
      integer(ip) :: nx
      logical :: found
      logical :: inside
      logical :: xin
      if ( .not. allocated ( ctx%zzrytlat_state ) ) allocate ( ctx%zzrytlat_state )
      associate ( origin => ctx%zzrytlat_state%origin, &
                  z => ctx%zzrytlat_state%z )
      call zzinlat ( ctx, vertex, bounds, 2*margin, 0, inside )

      if ( ctx%failed() ) return

      if ( inside ) then
!
!        We know the answer.
!
         nxpts = 1

         xpt = vertex

         return

      end if

!
!     Extract the segment's coordinate bounds into easily
!     readable variables.
!
      minr = bounds( inner, radidx )
      maxr = bounds( outer, radidx )
!
!     Normalize the longitude bounds. After this step, the bounds will
!     be in order and differ by no more than 2*pi.
!
      call zznrmlon( ctx, bounds(west,lonidx), bounds(east,lonidx), angmrg, &
                     minlon,              maxlon                       )

      if ( ctx%failed() ) return

      minlat = bounds( south, latidx )
      maxlat = bounds( north, latidx )

!
!     The vertex is outside the element.
!
!     Indicate no intersection to start.
!
      nxpts  = 0
!
!     We'll use a unit length copy of the ray's direction vector.
!
      call vhat ( raydir, udir )
!
!     Initialize the distance to the closest solution. We'll keep track
!     of this quantity in order to compare competing solutions.
!
      mndist = dpmax
!
!     Find the intersection of the ray and outer bounding sphere, if
!     possible. Often this intersection is the closest to the vertex.
!     If the intersection exists and is on the boundary of the element,
!     it's a winner.
!
      call zzryxsph ( ctx, vertex, udir, maxr, srfx, found )

      if ( .not. found ) then
!
!        There are no intersections. The ray cannot hit the
!        volume element.
!
         return

      end if
!
!     Get the latitudinal coordinates of the ray's vertex.
!
      call reclat ( vertex, vr, vlon, vlat )

!
!     The ray hits the outer bounding sphere. See whether
!     the longitude and latitude are within bounds, taking
!     the margin into account. Exclude the radius coordinate
!     from testing.
!
      call zzinlat ( ctx, srfx, bounds, margin, radidx, xin )

      if ( ctx%failed() ) return

      if ( xin ) then
!
!        This solution is a candidate.
!
         xpt = srfx
         nxpts  = 1

         if ( vr > maxr ) then
!
!           The vertex is outside this sphere, and the segment
!           lies within the sphere.
!
!           No other intersection can be closer to the vertex;
!           we don't need to check the other surfaces.
!
            return

         else
!
!           We have a possible solution.
!
            mndist = vdist( vertex, xpt )

         end if

      end if

!
!     So far there may be a candidate solution. We'll try the latitude
!     boundaries next.
!
!     For testing intersections with the latitude boundaries, we'll
!     need a far endpoint for the line segment on which to perform the
!     test.
!
      s = vnorm(vertex) + radfac * maxr

      endpt2 = 1.0_wp*vertex + s*udir

!
!     Now try the upper latitude bound. We can skip this test
!     if the upper bound is pi/2 radians.
!
      if ( maxlat < halfpi ) then
!
!        Let ANGLE be the angular separation of the surface of latitude
!        MAXLAT and the +Z axis. Note that the surface might be the
!        lower nappe of the cone.
!
         angle = max ( 0.0_wp,  halfpi - maxlat )

         call incnsg ( ctx, origin, z,  angle, vertex, &
                       endpt2, nx, srfx,  xpt2    )

         if ( ctx%failed() ) return

         if ( nx >= 1 ) then
!
!           See whether SRFX is in the element.
!
            call zzinlat ( ctx, srfx, bounds, margin, latidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then
!
!              SRFX is a candidate solution.
!
               dist = vdist( vertex, srfx )

               if ( dist < mndist ) then

                  xpt = srfx

                  nxpts  = 1

                  if ( vlat > maxlat ) then
!
!                    Since the latitude of the vertex is greater than
!                    MAXLAT, this is the best solution, since the
!                    volume element is on the other side of the maximum
!                    latitude boundary.
!
                     return

                  end if
!
!                 This is the best solution seen so far.
!
                  mndist = dist

               end if

            end if

            if ( nx == 2 ) then
!
!              Check the second solution as well.
!
               call zzinlat ( ctx, xpt2, bounds, margin, latidx, xin )

               if ( ctx%failed() ) return

               if ( xin ) then
!
!                 XPT2 is a candidate solution.
!
                  dist = vdist( vertex, xpt2 )

                  if ( dist < mndist ) then

                     xpt = xpt2

                     nxpts  = 1
                     mndist = dist
!
!                    This is the best solution seen so far.
!                    However, it's not necessarily the best
!                    solution. So we continue.
!
                  end if

               end if

            end if
!
!           We've handled the second root, if any.
!
         end if
!
!        We're done with the upper latitude boundary.
!
      end if

!
!     Try the lower latitude bound. We can skip this test if the lower
!     bound is -pi/2 radians.
!
      if (  minlat > -halfpi ) then
!
!        Let ANGLE be the angular separation of the surface
!        of latitude MINLAT and the +Z axis. Note that the
!        surface might be the lower nappe of the cone.
!
         angle = halfpi - minlat

         call incnsg ( ctx, origin, z,  angle, vertex, &
                       endpt2, nx, srfx,  xpt2    )

         if ( ctx%failed() ) return

         if ( nx >= 1 ) then
!
!           See whether SRFX is in the element.
!
            call zzinlat ( ctx, srfx, bounds, margin, latidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then
!
!              SRFX is a candidate solution.
!
               dist = vdist( vertex, srfx )

               if ( dist < mndist ) then

                  xpt = srfx

                  nxpts  = 1

                  if ( vlat < minlat ) then
!
!                    Since the latitude of the vertex is less than
!                    MINLAT, this is the best solution, since the
!                    volume element is on the other side of the minimum
!                    latitude boundary.
!
                     return

                  end if
!
!                 This is the best solution seen so far.
!
                  mndist = dist

               end if

            end if

            if ( nx == 2 ) then
!
!              Check the second solution as well.
!
               call zzinlat ( ctx, xpt2, bounds, margin, latidx, xin )

               if ( ctx%failed() ) return

               if ( xin ) then
!
!                 XPT2 is a candidate solution.
!
                  dist = vdist( vertex, xpt2 )

                  if ( dist < mndist ) then

                     xpt = xpt2

                     nxpts  = 1
                     mndist = dist
!
!                    This is the best solution seen so far.
!                    However, it's not necessarily the best
!                    solution. So we continue.
!
                     return

                  end if

               end if

            end if

         end if
!
!        We're done with the lower latitude boundary.
!
      end if

!
!     Perform longitude boundary checks if the coverage is not
!     2*pi radians. Note that MAXLON > MINLON at this point.
!
      loncov = maxlon - minlon

      if ( cos(loncov) < 1.0_wp ) then
!
!        We have distinct longitude boundaries. Go to work.
!
!        Check the longitude boundaries. Try the plane of western
!        longitude first.
!
!        The vector WESTB is an outward-facing vector normal to
!        the west boundary.
!
         westb = [sin(minlon), -cos(minlon), 0.0_wp]

         s = radfac * ( vnorm(vertex) + maxr )

         call zzinrypl ( ctx, vertex, udir, westb, 0.0_wp, s, nx, srfx )

         if ( nx == 1 ) then
!
!           We have one point of intersection. Determine whether it's a
!           candidate solution.  Don't use longitude in the following
!           inclusion test. Note that we'll perform a separate check
!           later in place of the longitude check.
!
            call zzinlat ( ctx, srfx, bounds, margin, lonidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then
!
!              Make sure the intercept is not too far on the
!              "wrong" side of the Z axis.
!
               call ucrss ( westb, z, wback )

               if (  vdot(srfx, wback) < (margin*maxr)  ) then
!
!                 The intercept is either on the same side of the Z
!                 axis as the west face of the segment, or is very
!                 close to the Z axis.
!
                  dist = vdist( vertex, srfx )

                  if ( dist < mndist ) then
!
!                    Record the intercept, distance, and surface index.
!
                     xpt = srfx

                     nxpts  = 1
                     mndist = dist

                  end if

               end if

            end if

         end if
!
!        We're done with the western boundary.
!
!        Try the plane of eastern longitude next.
!
!        The vector EASTB is an outward-facing vector normal to
!        the east boundary.

         eastb = [-sin(maxlon), cos(maxlon), 0.0_wp]

         call zzinrypl ( ctx, vertex, udir, eastb, 0.0_wp, s, nx, srfx )

         if ( nx == 1 ) then
!
!           We have one point of intersection. Determine whether it's a
!           candidate solution.
!
            call zzinlat ( ctx, srfx, bounds, margin, lonidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then
!
!              Make sure the intercept is not too far on the "wrong"
!              side of the Z axis.
!
               call ucrss ( z, eastb, eback )

               if (  vdot(srfx, eback) < (margin*maxr)  ) then
!
!                 The intercept is either on the same side of the Z
!                 axis as the east face of the segment, or is very
!                 close to the Z axis.
!
                  dist = vdist( vertex, srfx )

                  if ( dist < mndist ) then
!
!                    Record the intercept, distance, and surface index.
!
                     xpt = srfx

                     nxpts  = 1
                     mndist = dist

                  end if

               end if

            end if

         end if

      end if
!
!     End of longitude boundary checks.
!

!
!     Find the intersection of the ray and inner bounding
!     sphere, if possible.
!
      if ( minr > 0.0_wp ) then

         call zzryxsph ( ctx, vertex, udir, minr, srfx, found )

         if ( found ) then
!
!           See whether this solution is in the element.
!
            call zzinlat ( ctx, srfx, bounds, margin, radidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then

               dist = vdist( vertex, srfx )

               if ( dist < mndist ) then
!
!                 Record the intercept, distance, and surface index.
!
                  xpt = srfx

                  nxpts  = 1
                  mndist = dist

               end if

            end if

         end if

!
!        Unlike the outer sphere, either intersection of the ray with
!        the inner sphere can be an optimal solution. We'll test for
!        the case where the intercept further from the ray's vertex is
!        the correct solution.
!
         negdir = -udir

         call zzryxsph ( ctx, endpt2, negdir, minr, srfx, found )

         if ( found ) then

            call zzinlat ( ctx, srfx, bounds, margin, radidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then

               dist = vdist( vertex, srfx )

               if ( dist < mndist ) then
!
!                 Record the intercept, distance, and surface index.
!
                  xpt = srfx

                  nxpts  = 1
                  mndist = dist

               end if

            end if

         end if

      end if

!
!     NXPTS and XPT are set.
!
      end associate
      end subroutine zzrytlat

      !> Find the limb of a triaxial ellipsoid, viewed from a specified
      !> point.
      !>
      !>## Detailed Input
      !>
      !>     A,
      !>     B,
      !>     C        are the lengths of the semi-axes of a triaxial
      !>              ellipsoid. The ellipsoid is centered at the
      !>              origin and oriented so that its axes lie on the
      !>              x, y and z axes.  A, B, and C are the lengths of
      !>              the semi-axes that point in the x, y, and z
      !>              directions respectively.
      !>
      !>     VIEWPT   is a point from which the ellipsoid is viewed.
      !>              VIEWPT must be outside of the ellipsoid.
      !>
      !>## Detailed Output
      !>
      !>     LIMB     is a SPICE ellipse that represents the limb of
      !>              the ellipsoid.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the length of any semi-axis of the ellipsoid is
      !>         non-positive, the error SPICE(INVALIDAXISLENGTH) is signaled.
      !>         LIMB is not modified.
      !>
      !>     2)  If the length of any semi-axis of the ellipsoid is zero after
      !>         the semi-axis lengths are scaled by the reciprocal of the
      !>         magnitude of the longest semi-axis and then squared, the error
      !>         SPICE(DEGENERATECASE) is signaled. LIMB is not modified.
      !>
      !>     3)  If the viewing point VIEWPT is inside the ellipse, the error
      !>         SPICE(INVALIDPOINT) is signaled. LIMB is not modified.
      !>
      !>     4)  If the geometry defined by the input ellipsoid and viewing
      !>         point is so extreme that the limb cannot be found, the error
      !>         SPICE(DEGENERATECASE) is signaled.
      !>
      !>     5)  If the shape of the ellipsoid and the viewing geometry are
      !>         such that the limb is an excessively flat ellipsoid, the
      !>         limb may be a degenerate ellipse. You must determine whether
      !>         this possibility poses a problem for your application.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     The limb of a body, as seen from a viewing point, is the boundary
      !>     of the portion of the body's surface that is visible from that
      !>     viewing point. In this definition, we consider a surface point
      !>     to be `visible' if it can be connected to the viewing point by a
      !>     line segment that doesn't pass through the body. This is a purely
      !>     geometrical definition that ignores the matter of which portions
      !>     of the surface are illuminated, or whether the view is obscured by
      !>     any additional objects.
      !>
      !>     If a body is modeled as a triaxial ellipsoid, the limb is always
      !>     an ellipse. The limb is determined by its center, a semi-major
      !>     axis vector, and a semi-minor axis vector.
      !>
      !>     We note that the problem of finding the limb of a triaxial
      !>     ellipsoid is mathematically identical to that of finding its
      !>     terminator, if one makes the simplifying assumption that the
      !>     terminator is the limb of the body as seen from the vertex of the
      !>     umbra. So, this routine can be used to solve this simplified
      !>     version of the problem of finding the terminator.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Given an ellipsoid and a viewpoint exterior to it, calculate
      !>        the limb ellipse as seen from that viewpoint.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EDLIMB_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local constants.
      !>C
      !>      INTEGER                 UBEL
      !>      PARAMETER             ( UBEL =   9 )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      DOUBLE PRECISION        A
      !>      DOUBLE PRECISION        B
      !>      DOUBLE PRECISION        C
      !>      DOUBLE PRECISION        ECENTR ( 3    )
      !>      DOUBLE PRECISION        LIMB   ( UBEL )
      !>      DOUBLE PRECISION        SMAJOR ( 3    )
      !>      DOUBLE PRECISION        SMINOR ( 3    )
      !>      DOUBLE PRECISION        VIEWPT ( 3    )
      !>
      !>C
      !>C     Define a viewpoint exterior to the ellipsoid.
      !>C
      !>      DATA                    VIEWPT /  2.D0,  0.D0,  0.D0 /
      !>
      !>C
      !>C     Define an ellipsoid.
      !>C
      !>      A = SQRT( 2.D0 )
      !>      B = 2.D0 * SQRT( 2.D0 )
      !>      C = SQRT( 2.D0 )
      !>
      !>C
      !>C     Calculate the limb ellipse as seen by from the
      !>C     viewpoint.
      !>C
      !>      CALL EDLIMB ( A, B, C, VIEWPT, LIMB )
      !>
      !>C
      !>C     Output the structure components.
      !>C
      !>      CALL EL2CGV ( LIMB, ECENTR, SMAJOR, SMINOR )
      !>
      !>      WRITE(*,'(A)') 'Limb ellipse as seen from viewpoint:'
      !>      WRITE(*,'(A,3F11.6)') '   Semi-minor axis:', SMINOR
      !>      WRITE(*,'(A,3F11.6)') '   Semi-major axis:', SMAJOR
      !>      WRITE(*,'(A,3F11.6)') '   Center         :', ECENTR
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Limb ellipse as seen from viewpoint:
      !>           Semi-minor axis:   0.000000   0.000000  -1.000000
      !>           Semi-major axis:   0.000000   2.000000  -0.000000
      !>           Center         :   1.000000   0.000000   0.000000
      !>
      !>     2) We'd like to find the apparent limb of Jupiter, corrected for
      !>        light time and stellar aberration, as seen from JUNO
      !>        spacecraft's position at a given UTC time.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File name: edlimb_ex2.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                           Contents
      !>              ---------                           --------
      !>              juno_rec_160522_160729_160909.bsp   JUNO s/c ephemeris
      !>              pck00010.tpc                        Planet orientation
      !>                                                  and radii
      !>              naif0012.tls                        Leapseconds
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'juno_rec_160522_160729_160909.bsp',
      !>                                  'pck00010.tpc',
      !>                                  'naif0012.tls'  )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM EDLIMB_EX2
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Local parameters.
      !>C
      !>      CHARACTER*(*)           UTCSTR
      !>      PARAMETER             ( UTCSTR = '2016 Jul 14 19:45:00' )
      !>
      !>      INTEGER                 UBEL
      !>      PARAMETER             ( UBEL =   9 )
      !>
      !>C
      !>C     Local variables.
      !>C
      !>      DOUBLE PRECISION        CENTER ( 3    )
      !>      DOUBLE PRECISION        ET
      !>      DOUBLE PRECISION        JPOS   ( 3    )
      !>      DOUBLE PRECISION        LIMB   ( UBEL )
      !>      DOUBLE PRECISION        LT
      !>      DOUBLE PRECISION        RAD    ( 3    )
      !>      DOUBLE PRECISION        SMAJOR ( 3    )
      !>      DOUBLE PRECISION        SMINOR ( 3    )
      !>      DOUBLE PRECISION        SCPJFC ( 3    )
      !>      DOUBLE PRECISION        SCPOS  ( 3    )
      !>      DOUBLE PRECISION        TIPM   ( 3, 3 )
      !>
      !>      INTEGER                 N
      !>
      !>C
      !>C     Load the required kernels.
      !>C
      !>      CALL FURNSH ( 'edlimb_ex2.tm' )
      !>
      !>C
      !>C     Find the viewing point in Jupiter-fixed coordinates. To
      !>C     do this, find the apparent position of Jupiter as seen
      !>C     from the spacecraft in Jupiter-fixed coordinates and
      !>C     negate this vector. In this case we'll use light time
      !>C     and stellar aberration corrections to arrive at the
      !>C     apparent limb. JPOS is the Jupiter's position as seen
      !>C     from the spacecraft.  SCPOS is the spacecraft's position
      !>C     relative to Jupiter.
      !>C
      !>      CALL STR2ET ( UTCSTR,    ET )
      !>      CALL SPKPOS ( 'JUPITER', ET, 'J2000', 'LT+S', 'JUNO',
      !>     .               JPOS,     LT                         )
      !>
      !>      CALL VMINUS ( JPOS, SCPOS )
      !>
      !>C
      !>C     Get Jupiter's semi-axis lengths...
      !>C
      !>      CALL BODVRD ( 'JUPITER', 'RADII', 3, N, RAD )
      !>
      !>C
      !>C     ...and the transformation from J2000 to Jupiter
      !>C     equator and prime meridian coordinates. Note that we
      !>C     use the orientation of Jupiter at the time of
      !>C     emission of the light that arrived at the
      !>C     spacecraft at time ET.
      !>C
      !>      CALL PXFORM ( 'J2000', 'IAU_JUPITER', ET-LT, TIPM )
      !>
      !>C
      !>C     Transform the spacecraft's position into Jupiter-
      !>C     fixed coordinates.
      !>C
      !>      CALL MXV ( TIPM, SCPOS, SCPJFC )
      !>
      !>C
      !>C     Find the apparent limb.  LIMB is a SPICE ellipse
      !>C     representing the limb.
      !>C
      !>      CALL EDLIMB ( RAD(1), RAD(2), RAD(3), SCPJFC, LIMB )
      !>
      !>C
      !>C     CENTER, SMAJOR, and SMINOR are the limb's center,
      !>C     semi-major axis of the limb, and a semi-minor axis
      !>C     of the limb.  We obtain these from LIMB using the
      !>C     SPICELIB routine EL2CGV ( Ellipse to center and
      !>C     generating vectors ).
      !>C
      !>      CALL EL2CGV ( LIMB, CENTER, SMAJOR, SMINOR )
      !>
      !>C
      !>C     Output the structure components.
      !>C
      !>      WRITE(*,'(A)') 'Apparent limb of Jupiter as seen '
      !>     .            // 'from JUNO:'
      !>      WRITE(*,'(2A)')       '   UTC time       : ', UTCSTR
      !>      WRITE(*,'(A,3F14.6)') '   Semi-minor axis:', SMINOR
      !>      WRITE(*,'(A,3F14.6)') '   Semi-major axis:', SMAJOR
      !>      WRITE(*,'(A,3F14.6)') '   Center         :', CENTER
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Apparent limb of Jupiter as seen from JUNO:
      !>           UTC time       : 2016 Jul 14 19:45:00
      !>           Semi-minor axis:  12425.547643  -5135.572410  65656.053303
      !>           Semi-major axis:  27305.667297  66066.222576      0.000000
      !>           Center         :    791.732472   -327.228993   -153.408849
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
