      !>-    SPICELIB Version 1.2.0, 06-OCT-1993 (NJB)
      !>
      !>        Declaration of unused local variable NEAR was removed.
      !>
      !>-    SPICELIB Version 1.1.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.1.0, 04-DEC-1990 (NJB)
      !>
      !>        Error message and description changed for non-positive
      !>        axis length error.
      !>
      !>-    SPICELIB Version 1.0.0, 02-NOV-1990 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.1.0, 04-DEC-1990 (NJB)
      !>
      !>        Error message and description changed for non-positive
      !>        axis length error. The former message and description did
      !>        not match, and the description was incorrect: it described
      !>        `zero-length', rather than `non-positive' axes as invalid.
      module subroutine edlimb ( ctx, a, b, c, viewpt, limb )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), parameter :: ubel = 9
      real(wp), intent(in) :: a  !! Length of ellipsoid semi-axis lying on the x-axis.
      real(wp), intent(in) :: b  !! Length of ellipsoid semi-axis lying on the y-axis.
      real(wp), intent(in) :: c  !! Length of ellipsoid semi-axis lying on the z-axis.
      real(wp), intent(in) :: viewpt (    3 )  !! Location of viewing point.
      real(wp), intent(out) :: limb   ( ubel )  !! Limb of ellipsoid as seen from viewing point.



      real(wp) :: level
      real(wp) :: lplane ( ubpl )
      real(wp) :: normal (    3 )
      real(wp) :: scale
      real(wp) :: scla
      real(wp) :: scla2
      real(wp) :: sclb
      real(wp) :: sclb2
      real(wp) :: sclc
      real(wp) :: sclc2
      real(wp) :: tmpel  ( ubel )
      real(wp) :: v      (    3 )

      logical :: found

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     The semi-axes must have positive length.
!
      if (       ( a <= 0.0_wp ) &
           .or.  ( b <= 0.0_wp ) &
           .or.  ( c <= 0.0_wp )   )   then

         call ctx%setmsg ( 'Semi-axis lengths:  A = #, B = #, C = #. ' )
         call ctx%errdp  ( '#', a                                      )
         call ctx%errdp  ( '#', b                                      )
         call ctx%errdp  ( '#', c                                      )
         call ctx%sigerr ( 'SPICE(INVALIDAXISLENGTH)'                  )
         return

      end if

!
!     Scale the semi-axes lengths for better numerical behavior.
!     If squaring any one of the scaled lengths causes it to
!     underflow to zero, we cannot continue the computation. Otherwise,
!     scale the viewing point too.
!
      scale  =  max ( dabs(a), dabs(b), dabs(c) )

      scla   =  a / scale
      sclb   =  b / scale
      sclc   =  c / scale

      scla2  =  scla**2
      sclb2  =  sclb**2
      sclc2  =  sclc**2

      if (       ( scla2  ==  0.0_wp ) &
           .or.  ( sclb2  ==  0.0_wp ) &
           .or.  ( sclc2  ==  0.0_wp )   )   then

         call ctx%setmsg ( 'Semi-axis too small:  A = #, B = #, C = #. ' )
         call ctx%errdp  ( '#', a                                        )
         call ctx%errdp  ( '#', b                                        )
         call ctx%errdp  ( '#', c                                        )
         call ctx%sigerr ( 'SPICE(DEGENERATECASE)'                       )
         return

      end if

      v = (1.0_wp / scale)*viewpt

!
!     The viewing point must be outside of the ellipsoid.  LEVEL is the
!     constant of the level surface that V lies on.  The ellipsoid
!     itself is the level surface corresponding to LEVEL = 1.
!
      level   =     ( v(1)**2 / scla2 ) &
                 +  ( v(2)**2 / sclb2 ) &
                 +  ( v(3)**2 / sclc2 )

      if ( level < 1.0_wp ) then

         call ctx%setmsg ( 'Viewing point is inside the ellipsoid.' )
         call ctx%sigerr ( 'SPICE(DEGENERATECASE)'                  )
         return

      end if

!
!     Find a normal vector for the limb plane.
!
!     To compute this vector, we use the fact that the surface normal at
!     each limb point is orthogonal to the line segment connecting the
!     viewing point and the limb point.   Let the notation
!
!        < a, b >
!
!     indicate the dot product of the vectors a and b.  If we call the
!     viewing point V and the limb point X, then
!
!                            X(1)         X(2)         X(3)
!        0  =   < V - X,  ( -------- ,   -------- ,   --------  )  >
!                                2           2             2
!                            SCLA        SCLB          SCLC
!
!                            X(1)         X(2)         X(3)
!           =   <   V,    ( -------- ,   -------- ,   --------  )  >
!                                2           2             2
!                            SCLA        SCLB          SCLC
!
!                            X(1)         X(2)         X(3)
!            - <   X,    ( -------- ,   -------- ,   --------  )  >
!                                2           2             2
!                            SCLA        SCLB          SCLC
!
!                                2           2             2
!                            X(1)        X(2)          X(3)
!           =             --------  +   --------  +  --------
!                               2            2             2
!                           SCLA         SCLB          SCLC
!
!           =   1
!
!     This last equation is just the equation of the scaled ellipsoid.
!     We can combine the last two equalities and interchange the
!     positions of X and V to obtain
!
!                      V(1)         V(2)         V(3)
!        <   X,    ( -------- ,   -------- ,   --------  )  >   =   1
!                          2           2             2
!                      SCLA        SCLB          SCLC
!
!     This is the equation of the limb plane.
!

!
!     Put together a SPICE plane, LPLANE, that represents the limb
!     plane.
!
      normal(1)  =  v(1) / scla2
      normal(2)  =  v(2) / sclb2
      normal(3)  =  v(3) / sclc2

      call nvc2pl ( ctx, normal, 1.0_wp, lplane )

!
!     Find the limb by intersecting the limb plane with the ellipsoid.
!
      call inedpl ( ctx, scla,  sclb,  sclc,  lplane,  limb,  found )

!
!     FOUND should be true unless we've encountered numerical problems.
!
      if ( .not. found ) then

         call ctx%setmsg ( 'Ellipsoid shape and viewing geometry are too '// &
                       'extreme; the limb was not found. '             )
         call ctx%sigerr ( 'SPICE(DEGENERATECASE)'                         )
         return

      end if

!
!     Undo the scaling before returning the limb.
!
      tmpel = scale*limb
      limb = tmpel

      return
      end subroutine edlimb

      !> Find nearest point on a triaxial ellipsoid to a specified line,
      !> and the distance from the ellipsoid to the line.
      !>
      !>## Detailed Input
      !>
      !>     A,
      !>     B,
      !>     C        are the lengths of the semi-axes of a triaxial
      !>              ellipsoid which is centered at the origin and
      !>              oriented so that its axes lie on the x-, y- and
      !>              z- coordinate axes.  A, B, and C are the lengths of
      !>              the semi-axes that point in the x, y, and z
      !>              directions respectively.
      !>
      !>     LINEPT
      !>     LINEDR   are, respectively, a point and a direction vector
      !>              that define a line. The line is the set of vectors
      !>
      !>                 LINEPT   +   t * LINEDR
      !>
      !>              where t is any real number.
      !>
      !>## Detailed Output
      !>
      !>     PNEAR    is the point on the ellipsoid that is closest to
      !>              the line, if the line doesn't intersect the
      !>              ellipsoid.
      !>
      !>              If the line intersects the ellipsoid, PNEAR will
      !>              be a point of intersection. If LINEPT is outside
      !>              of the ellipsoid, PNEAR will be the closest point
      !>              of intersection. If LINEPT is inside the
      !>              ellipsoid, PNEAR will not necessarily be the
      !>              closest point of intersection.
      !>
      !>     DIST     is the distance of the line from the ellipsoid.
      !>              This is the minimum distance between any point on
      !>              the line and any point on the ellipsoid.
      !>
      !>              If the line intersects the ellipsoid, DIST is zero.
      !>
      !>## Parameters
      !>
      !>     UBEL     is the upper bound of the array used to contain
      !>              a SPICE ellipse. See the ELLIPSES Required
      !>              Reading for details.
      !>
      !>     UBPL     is the upper bound of the array used to contain
      !>              a SPICE plane. See the PLANES Required Reading
      !>              for details.
      !>
      !>## Exceptions
      !>
      !>     If this routine detects an error, the output arguments PNEAR and
      !>     DIST are not modified.
      !>
      !>     1)  If the length of any semi-axis of the ellipsoid is
      !>         non-positive, the error SPICE(INVALIDAXISLENGTH) is signaled.
      !>
      !>     2)  If the line's direction vector is the zero vector, the error
      !>         SPICE(ZEROVECTOR) is signaled.
      !>
      !>     3)  If the length of any semi-axis of the ellipsoid is zero after
      !>         the semi-axis lengths are scaled by the reciprocal of the
      !>         magnitude of the longest semi-axis and then squared, the error
      !>         SPICE(DEGENERATECASE) is signaled.
      !>
      !>     4)  If the input ellipsoid is extremely flat or needle-shaped
      !>         and has its shortest axis close to perpendicular to the input
      !>         line, numerical problems could cause this routine's algorithm
      !>         to fail, in which case, the error SPICE(DEGENERATECASE) is
      !>         signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     For any ellipsoid and line, if the line does not intersect the
      !>     ellipsoid, there is a unique point on the ellipsoid that is
      !>     closest to the line. Therefore, the distance DIST between
      !>     ellipsoid and line is well-defined. The unique line segment of
      !>     length DIST that connects the line and ellipsoid is normal to
      !>     both of these objects at its endpoints.
      !>
      !>     If the line intersects the ellipsoid, the distance between the
      !>     line and ellipsoid is zero.
      !>
      !>## Examples
      !>
      !>     1)   We can find the distance between an instrument optic axis ray
      !>          and the surface of a body modeled as a tri-axial ellipsoid
      !>          using this routine. If the instrument position and pointing
      !>          unit vector in body-fixed coordinates are
      !>
      !>             LINEPT = ( 1.0D6,  2.0D6,  3.0D6 )
      !>
      !>          and
      !>
      !>             LINEDR = ( -4.472091234D-1
      !>                        -8.944182469D-1,
      !>                        -4.472091234D-3  )
      !>
      !>          and the body semi-axes lengths are
      !>
      !>             A = 7.0D5
      !>             B = 7.0D5
      !>             C = 6.0D5,
      !>
      !>          then the call to NPEDLN
      !>
      !>             CALL NPEDLN ( A,      B,      C,
      !>            .              LINEPT, LINEDR,
      !>            .              PNEAR,  DIST        )
      !>
      !>          yields a value for PNEAR, the nearest point on the body to
      !>          the optic axis ray, of
      !>
      !>             (  -1.6333110792340931E+03,
      !>                -3.2666222157820771E+03,
      !>                 5.9999183350006724E+05  )
      !>
      !>          and a value for DIST, the distance to the ray, of
      !>
      !>             2.3899679338299707E+06
      !>
      !>          (These results were obtained on a PC-Linux system under g77.)
      !>
      !>          In some cases, it may not be clear that the closest point
      !>          on the line containing an instrument boresight ray is on
      !>          the boresight ray itself; the point may lie on the ray
      !>          having the same vertex as the boresight ray and pointing in
      !>          the opposite direction. To rule out this possibility, we
      !>          can make the following test:
      !>
      !>             C
      !>             C     Find the difference vector between the closest point
      !>             C     on the ellipsoid to the line containing the
      !>             C     boresight ray and the boresight ray's vertex. Find
      !>             C     the angular separation between this difference
      !>             C     vector and the boresight ray. If the angular
      !>             C     separation does not exceed pi/2, we have the nominal
      !>             C     geometry. Otherwise, we have an error.
      !>             C
      !>                   CALL  VSUB ( PNEAR,  LINEPT,  DIFF )
      !>                   SEP = VSEP ( DIFF,   LINEDR        )
      !>
      !>                   IF (  SEP .LE. HALFPI()  ) THEN
      !>
      !>                      [ perform normal processing ]
      !>
      !>                   ELSE
      !>
      !>                      [ handle error case ]
      !>
      !>                   END IF
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     W.L. Taber         (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.4.0, 24-AUG-2021 (JDR)
      !>
      !>        Added IMPLICIT NONE statement.
      !>
      !>        Edited the header to comply with NAIF standard. Corrected
      !>        argument name in $Exceptions section.
      !>
      !>-    SPICELIB Version 1.3.0, 15-NOV-2005 (NJB)
      !>
      !>        Updated to remove non-standard use of duplicate arguments
      !>        in VSCL calls. Changed exponents to DOUBLE PRECISION type
      !>        in the test for underflow of squared, scaled axis lengths.
      !>
      !>-    SPICELIB Version 1.2.1, 06-DEC-2002 (NJB)
      !>
      !>        Outputs shown in header example have been corrected to
      !>        be consistent with those produced by this routine.
      !>
      !>-    SPICELIB Version 1.2.0, 25-NOV-1992 (NJB)
      !>
      !>        Bug fix: in the intercept case, PNEAR is now properly
      !>        re-scaled prior to output. Also, an error in the $Examples
      !>        section was corrected.
      !>
      !>-    SPICELIB Version 1.1.1, 10-MAR-1992 (WLT)
      !>
      !>        Comment section for permuted index source lines was added
      !>        following the header.
      !>
      !>-    SPICELIB Version 1.1.0, 04-DEC-1990 (NJB)
      !>
      !>        Error message and description changed for non-positive
      !>        axis length error.
      !>
      !>-    SPICELIB Version 1.0.0, 02-NOV-1990 (NJB)
      !>
      !>## Revisions
      !>
      !>-    SPICELIB Version 1.2.0, 25-NOV-1992 (NJB)
      !>
      !>        Bug fix: in the intercept case, PNEAR is now properly
      !>        re-scaled prior to output. Formerly, it was returned without
      !>        having been re-scaled.
      !>
      !>        Also, an error in the $Examples section was corrected: the
      !>        line
      !>
      !>           CALL  VSUB ( LINEPT,  PNEAR,  DIFF )
      !>
      !>        was replaced by
      !>
      !>           CALL  VSUB ( PNEAR,  LINEPT,  DIFF )
      !>
      !>        The in-line comments were re-arranged slightly, and the claim
      !>        that the inverse orthogonal projection of PRJNPT is guaranteed
      !>        to exist was removed. (The check for this exception was already
      !>        being done.)
      !>
      !>-    SPICELIB Version 1.1.0, 04-DEC-1990 (NJB)
      !>
      !>        Error message and description changed for non-positive
      !>        axis length error. The former message and description did
      !>        not match, and the description was incorrect: it described
      !>        `zero-length', rather than `non-positive' axes as invalid.
      module subroutine npedln ( ctx, a, b, c, linept, linedr, pnear, dist )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: unorm
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: a  !! Length of ellipsoid's semi-axis in the x direction
      real(wp), intent(in) :: b  !! Length of ellipsoid's semi-axis in the y direction
      real(wp), intent(in) :: c  !! Length of ellipsoid's semi-axis in the z direction
      real(wp), intent(in) :: linept ( 3 )  !! Point on line
      real(wp), intent(in) :: linedr ( 3 )  !! Direction vector of line
      real(wp), intent(out) :: pnear  ( 3 )  !! Nearest point on ellipsoid to line
      real(wp), intent(out) :: dist  !! Distance of ellipsoid from line



      real(wp) :: candpl ( ubpl )
      real(wp) :: cand   ( ubel )
      real(wp) :: oppdir (    3 )
      real(wp) :: prjpl  ( ubpl )
      real(wp) :: mag
      real(wp) :: normal (    3 )
      real(wp) :: prjel  ( ubel )
      real(wp) :: prjpt  (    3 )
      real(wp) :: prjnpt (    3 )
      real(wp) :: pt     ( 3, 2 )
      real(wp) :: scale
      real(wp) :: scla
      real(wp) :: sclb
      real(wp) :: sclc
      real(wp) :: sclpt  (    3 )
      real(wp) :: udir   (    3 )

      integer(ip) :: i

      logical :: found  (    2 )
      logical :: ifound
      logical :: xfound

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     The algorithm used in this routine has two parts.  The first
!     part handles the case where the input line and ellipsoid
!     intersect.  Our procedure is simple in that case; we just
!     call SURFPT twice, passing it first one ray determined by the
!     input line, then a ray pointing in the opposite direction.
!     The second part of the algorithm handles the case where SURFPT
!     doesn't find an intersection.
!
!     Finding the nearest point on the ellipsoid to the line, when the
!     two do not intersect, is a matter of following four steps:
!
!     1)  Find the points on the ellipsoid where the surface normal
!         is normal to the line's direction.  This set of points is
!         an ellipse centered at the origin.  The point we seek MUST
!         lie on this `candidate' ellipse.
!
!     2)  Project the candidate ellipse onto a plane that is normal
!         to the line's direction.  This projection preserves
!         distance from the line; the nearest point to the line on
!         this new ellipse is the projection of the nearest point to
!         the line on the candidate ellipse, and these two points are
!         exactly the same distance from the line.  If computed using
!         infinite-precision arithmetic, this projection would be
!         guaranteed to be non-degenerate as long as the input
!         ellipsoid were non-degenerate.  This can be verified by
!         taking the inner product of the scaled normal to the candidate
!         ellipse plane and the line's unitized direction vector
!         (these vectors are called NORMAL and UDIR in the code below);
!         the inner product is strictly greater than 1 if the ellipsoid
!         is non-degenerate.
!
!     3)  The nearest point on the line to the projected ellipse will
!         be contained in the plane onto which the projection is done;
!         we find this point and then find the nearest point to it on
!         the projected ellipse.  The distance between these two points
!         is the distance between the line and the ellipsoid.
!
!     4)  Finally, we find the point on the candidate ellipse that was
!         projected to the nearest point to the line on the projected
!         ellipse that was found in step 3.  This is the nearest point
!         on the ellipsoid to the line.
!
!                      Glossary of Geometric Variables
!
!            A,
!            B,
!            C           Input ellipsoid's semi-axis lengths.
!
!            POINT       Point of intersection of line and ellipsoid
!                        if the intersection is non-empty.
!
!            CANDPL      Plane containing candidate ellipse.
!
!            NORMAL      Normal vector to the candidate plane CANDPL.
!
!            CAND        Candidate ellipse.
!
!            LINEPT,
!            LINEDR,     Point and direction vector on input line.
!
!            UDIR        Unitized line direction vector.
!
!            PRJPL       Projection plane; the candidate ellipse is
!                        projected onto this plane to yield PRJEL.
!
!            PRJEL       Projection of the candidate ellipse CAND onto
!                        the projection plane PRJEL.
!
!            PRJPT       Projection of line point.
!
!            PRJNPT      Nearest point on projected ellipse to
!                        projection of line point.
!
!            PNEAR       Nearest point on ellipsoid to line.
!

!
!     We need a valid normal vector.
!
      call unorm ( linedr, udir, mag )

      if ( mag == 0 ) then

         call ctx%setmsg( 'Line direction vector is the zero vector. ' )
         call ctx%sigerr( 'SPICE(ZEROVECTOR)'                          )
         return

!
!     The ellipsoid's semi-axes must have positive length.
!
      else if (         ( a <= 0.0_wp ) &
                 .or.   ( b <= 0.0_wp ) &
                 .or.   ( c <= 0.0_wp )   )   then

         call ctx%setmsg ( 'Semi-axes: A = #,  B = #,  C = #.'  )
         call ctx%errdp  ( '#', a                               )
         call ctx%errdp  ( '#', b                               )
         call ctx%errdp  ( '#', c                               )
         call ctx%sigerr ( 'SPICE(INVALIDAXISLENGTH)'           )
         return

      end if

!
!     Scale the semi-axes lengths for better numerical behavior.
!     If squaring any one of the scaled lengths causes it to
!     underflow to zero, we have an error.  Otherwise, scale the
!     point on the input line too.
!
      scale  =  max ( dabs(a), dabs(b), dabs(c) )

      scla   =  a / scale
      sclb   =  b / scale
      sclc   =  c / scale

      if (       ( scla**2.0_wp  ==  0.0_wp ) &
           .or.  ( sclb**2.0_wp  ==  0.0_wp ) &
           .or.  ( sclc**2.0_wp  ==  0.0_wp )   )   then

         call ctx%setmsg ( 'Semi-axis too small:  A = #, B = #, C = #. ' )
         call ctx%errdp  ( '#', a                                        )
         call ctx%errdp  ( '#', b                                        )
         call ctx%errdp  ( '#', c                                        )
         call ctx%sigerr ( 'SPICE(DEGENERATECASE)'                       )
         return

      end if

!
!     Scale LINEPT.  Because SCALE might be a very small number,
!     we avoid computing 1/SCALE; that's why we don't call VSCL here.
!
      sclpt(1)  =  linept(1) / scale
      sclpt(2)  =  linept(2) / scale
      sclpt(3)  =  linept(3) / scale

!
!     Hand off the intersection case to SURFPT.  SURFPT determines
!     whether rays intersect a body, so we treat the line as a pair
!     of rays.
!
      oppdir = -udir

      call surfpt ( ctx, sclpt, udir,   scla, sclb, sclc, pt(1,1), found(1) )
      call surfpt ( ctx, sclpt, oppdir, scla, sclb, sclc, pt(1,2), found(2) )

      do i = 1, 2

         if ( found(i) ) then

            dist  =  0.0_wp

            pnear = scale*pt(:,i)
            return

         end if

      end do

!
!     Getting here means the line doesn't intersect the ellipsoid.
!
!     Find the candidate ellipse CAND.  NORMAL is a normal vector to
!     the plane containing the candidate ellipse.   Mathematically the
!     ellipse must exist, since it's the intersection of an ellipsoid
!     centered at the origin and a plane containing the origin.  Only
!     numerical problems can prevent the intersection from being found.
!
      normal(1)  =  udir(1) / scla**2
      normal(2)  =  udir(2) / sclb**2
      normal(3)  =  udir(3) / sclc**2

      call nvc2pl ( ctx, normal, 0.0_wp, candpl )

      call inedpl ( ctx, scla, sclb, sclc, candpl, cand, xfound )

      if ( .not. xfound ) then
         call ctx%setmsg ( 'Candidate ellipse could not be found.'  )
         call ctx%sigerr ( 'SPICE(DEGENERATECASE)'                  )
         return
      end if

!
!     Project the candidate ellipse onto a plane orthogonal to the
!     line.  We'll call the plane PRJPL and the projected ellipse PRJEL.
!
      call nvc2pl ( ctx, udir,  0.0_wp,   prjpl )
      call pjelpl ( ctx, cand,  prjpl,  prjel )

!
!     Find the point on the line lying in the projection plane, and
!     then find the near point PRJNPT on the projected ellipse.  Here
!     PRJPT is the point on the line lying in the projection plane.
!     The distance between PRJPT and PRJNPT is DIST.
!
      call vprjp  ( ctx, sclpt,   prjpl,  prjpt         )
      call npelpt ( ctx, prjpt,   prjel,  prjnpt,  dist )

      if ( ctx%failed() ) return

!
!     Find the near point PNEAR on the ellipsoid by taking the inverse
!     orthogonal projection of PRJNPT; this is the point on the
!     candidate ellipse that projects to PRJNPT.  Note that the
!     output DIST was computed in step 3 and needs only to be re-scaled.
!
!     The inverse projection of PNEAR ought to exist, but may not
!     be calculable due to numerical problems (this can only happen
!     when the input ellipsoid is extremely flat or needle-shaped).
!
      call vprjpi ( ctx, prjnpt, prjpl, candpl, pnear, ifound )

      if ( .not. ifound ) then
         call ctx%setmsg ( 'Inverse projection could not be found.'  )
         call ctx%sigerr ( 'SPICE(DEGENERATECASE)'                   )
         return
      end if

!
!     Undo the scaling.
!
      pnear = scale*pnear

      dist = scale * dist

      return
      end subroutine npedln

      !> Test a point represented by a set of Cartesian coordinates for
      !> inclusion in a volume element in a specified coordinate system.
      !> The volume element is bounded by surfaces on which one coordinate
      !> is constant. The test is performed using margins for the element.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     P          is a point expressed in Cartesian coordinates. The
      !>                point is to be checked to determine whether it is
      !>                inside the volume element specified by BOUNDS.
      !>
      !>     CORSYS     is an integer parameter identifying the coordinate
      !>                system in which the bounds are to be computed. See the
      !>                include file dskdsc.inc for allowed values of CORSYS.
      !>
      !>     CORPAR     is an array of parameters associated with the
      !>                coordinate system. Currently the only supported system
      !>                that has associated parameters is the planetodetic
      !>                system. For planetodetic coordinates,
      !>
      !>                   CORPAR(1) is the equatorial radius
      !>
      !>                   CORPAR(2) is the flattening coefficient. Let RE and
      !>                   RP represent, respectively, the equatorial and
      !>                   polar radii of the reference ellipsoid of the
      !>                   system. Then
      !>
      !>                       CORPAR(2) = ( RE - RP ) / RE
      !>
      !>     BOUNDS     is an 2x3 array containing the bounds of a volume
      !>                element expressed in a supported coordinate system,
      !>                specifically one of:
      !>
      !>                   LATITUDINAL
      !>                   PLANETODETIC
      !>                   RECTANGULAR
      !>
      !>                BOUNDS defines the volume element used in the
      !>                comparison. In the element
      !>
      !>                   BOUNDS(I,J)
      !>
      !>                J is the coordinate index. I is the bound index.
      !>
      !>                   I = 1   ->   lower bound
      !>                   I = 2   ->   upper bound
      !>
      !>                See the routines
      !>
      !>                   ZZINLAT
      !>                   ZZINPDT
      !>                   ZZINREC
      !>
      !>                for details on the contents of BOUNDS for the
      !>                respective coordinate systems supported by those
      !>                routines.
      !>
      !>     MARGIN     is a fraction used to expand the volume element for
      !>                inclusion testing.
      !>
      !>                See the routines
      !>
      !>                   ZZINLAT
      !>                   ZZINPDT
      !>                   ZZINREC
      !>
      !>                for details regarding the application of MARGIN.
      !>
      !>     EXCLUD     is either a coordinate index or the parameter NONE.
      !>
      !>                If EXCLUD is set to one of
      !>
      !>                   { 1, 2, 3 }
      !>
      !>                then the indicated coordinate is excluded from
      !>                comparison with the corresponding volume element
      !>                boundaries.
      !>
      !>                If EXCLUD is set to NONE, all coordinates are
      !>                compared.
      !>
      !>                Exclusion of coordinates is used in cases where a
      !>                point is known to be on a level surface of a given
      !>                coordinate. For example, if a point is on the sphere
      !>                of radius equal to the upper radius bound, radius need
      !>                not be used in the comparison and in fact can't be
      !>                meaningfully compared, due to round-off errors.
      !>
      !>                See the routines
      !>
      !>                   ZZINLAT
      !>                   ZZINPDT
      !>                   ZZINREC
      !>
      !>                for details regarding the application of EXCLUD.
      !>
      !>## Detailed Output
      !>
      !>     INSIDE     is a logical flag that is set to .TRUE. if and only if
      !>                the input coordinates represent a point inside or on
      !>                the surface of the volume element, according to the
      !>                comparisons that are performed.
      !>
      !>                The value of INSIDE is not affected by the value of
      !>                any excluded coordinate.
      !>
      !>## Parameters
      !>
      !>     See the include files
      !>
      !>        dskdsc.inc
      !>        dsktol.inc
      !>
      !>     and the Parameters sections of the routines
      !>
      !>        ZZINLAT
      !>        ZZINPDT
      !>        ZZINREC
      !>
      !>## Exceptions
      !>
      !>     1)  If CORSYS is not recognized, the error SPICE(NOTSUPPORTED)
      !>         is signaled.
      !>
      !>     2)  If MARGIN is negative, the error SPICE(VALUEOUTOFRANGE)
      !>         is signaled.
      !>
      !>     3)  If EXCLUD is less than 0 or greater than 3, the error will
      !>         be signaled by a routine in the call tree of this routine.
      !>
      !>     4)  If an error occurs while determining the planetodetic
      !>         coordinates of the input point, the error will be signaled by
      !>         a routine in the call tree of this routine.
      !>
      !>     5)  If any rectangular coordinate upper bound is less than the
      !>         corresponding lower bound, the error will be signaled by
      !>         a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     None.
      !>
      !>## Examples
      !>
      !>     See usage in ZZPTPL02.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 04-APR-2017 (NJB)
      !>
      !>     03-JUN-2016 (NJB)
      !>
      !>        Original version.
      module subroutine zzinvelt ( ctx, p, corsys, corpar, bounds, margin, exclud, inside )
      use pepper_kinds, only: ip, wp
      use pepper_inc_dsktol
      use pepper_inc_dskdsc
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: p      ( 3 )  !! Input point.
      integer(ip), intent(in) :: corsys  !! Coordinate system code.
      real(wp), intent(in) :: corpar ( * )  !! Coordinate system parameters.
      real(wp), intent(in) :: bounds ( 2, 3 )  !! Coordinate bounds of element.
      real(wp), intent(in) :: margin  !! Margin used for inclusion testing.
      integer(ip), intent(in) :: exclud  !! Index of coordinate to exclude from test.
      logical, intent(out) :: inside  !! Flag indicating whether point is in element.

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

      if ( margin < 0.0_wp ) then

         call ctx%setmsg ( 'Margin must be non-negative but was #.' )
         call ctx%errdp  ( '#', margin                              )
         call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'                 )
         return

      end if

!
!     Delegate the job to one of the coordinate system-specific
!     routines.
!
      if ( corsys == latsys ) then

         call zzinlat ( ctx, p, bounds, margin, exclud, inside )

      else if ( corsys == pdtsys ) then

         call zzinpdt ( ctx, p, bounds, corpar, margin, exclud, inside )

      else if ( corsys == recsys ) then

         call zzinrec ( ctx, p, bounds, margin, exclud, inside )

      else

         call ctx%setmsg ( 'Coordinate system code # was not recognized.' )
         call ctx%errint ( '#', corsys                                    )
         call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                          )
         return

      end if

      return
      end subroutine zzinvelt

      !> Parse a method input string passed by a caller to a SPICE
      !> high-level geometry API. Return parameter values specified by the
      !> string.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     BODYID     is the body ID code of an ephemeris object. This
      !>                object is normally the "target" body of a geometric
      !>                computation. Any surfaces specified in the method
      !>                string are associated with this body. BODYID is
      !>                needed to map surface names to surface ID codes.
      !>
      !>     METHOD     is a "method" string to be parsed. This string
      !>                normally is passed by a caller to a SPICE high-level
      !>                high-level geometry routine.
      !>
      !>                METHOD indicates whether a target body surface is
      !>                to be modeled as an ellipsoid or by DSK data. It
      !>                may contain additional, computation-dependent
      !>                parameters.
      !>
      !>     MXNSRF     is the maximum number of surface IDs that can be
      !>                returned in the output array SRFLST. Normally
      !>                the caller should use the parameter MAXSRF to
      !>                set this value.
      !>
      !>## Detailed Output
      !>
      !>     SHAPE      is a string describing the shape model. Values are
      !>
      !>                    'ELLIPSOID' or 'DSK'
      !>
      !>     SUBTYP     is a string describing a sub-observer or sub-solar
      !>                point definition. Values are
      !>
      !>                    'INTERCEPT' or 'NEAR POINT'
      !>
      !>     PRI        is a logical flag indicating whether a DSK-based
      !>                computation uses DSK segments in a prioritized
      !>                fashion. PRI is .TRUE. if and only if the data
      !>                usage is prioritized. Note that for the N0066
      !>                version of SPICE, all DSK-based computations
      !>                use unprioritized data.
      !>
      !>     NSURF      is the number of elements of the surface ID list.
      !>
      !>     SRFLST     is a list of surface ID codes. All surfaces are
      !>                associated with the body designated by BODYID.
      !>
      !>     PNTDEF     is a string describing the point definition used
      !>                to compute limb or terminator points. Values are
      !>
      !>                   'TANGENT' or 'GUIDED'
      !>
      !>     TRMTYP     is a string that indicates the definition of the
      !>                terminator on the target body. Values are:
      !>
      !>                   'UMBRAL' or 'PENUMBRAL'
      !>
      !>## Parameters
      !>
      !>     MAXSRF is the maximum surface list size used by the DSK
      !>     subsystem. See dsk.inc for the parameter's value.
      !>
      !>## Exceptions
      !>
      !>     1)  If more than one shape keyword is found in METHOD,
      !>         the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>     2)  If more than one surface keyword is found in METHOD,
      !>         the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>     3)  If the surface keyword is found in METHOD, but no
      !>         surfaces are listed, the error SPICE(BADMETHODSYNTAX) is
      !>         signaled.
      !>
      !>     4)  If the equals sign ('=') is missing from the surface list,
      !>         the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>     5)  If the method string contains a double quote character (")
      !>         that doesn't delimit a quoted-string, the error
      !>          SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>     6)  If a surface name in the METHOD string can't be converted
      !>         to a surface ID code, the error SPICE(IDCODENOTFOUND) is
      !>         signaled.
      !>
      !>     7)  If all ID codes in the surface list can't be stored in the
      !>         SRFLST array, the error SPICE(TOOMANYSURFACES) is signaled.
      !>
      !>     8)  If the surface list in METHOD contains a comma not followed
      !>         by a surface name, the error SPICE(BADMETHODSYNTAX) is
      !>         signaled.
      !>
      !>     9)  If the surface list in METHOD contains an unrecognized token,
      !>         the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>    10)  If the string METHOD contains an extra prioritization token,
      !>         the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>    12)  If the string METHOD contains an extra sub-point type token,
      !>         the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>    13)  If the string METHOD contains an extra point definition
      !>         token, the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>    14)  If the string METHOD contains an extra terminator type token,
      !>         the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>    15)  If the string METHOD contains an extra slash character,
      !>         the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>    16)  If the string METHOD lacks a prioritization keyword,
      !>         the error SPICE(BADPRIORITYSPEC) is signaled.
      !>
      !>    17)  If a "legacy" method string is not one of the expected
      !>         values, the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>    18)  If the string METHOD contains any other unexpected tokens,
      !>         the error SPICE(BADMETHODSYNTAX) is signaled.
      !>
      !>## Files
      !>
      !>     Surface name-to-ID mappings may be defined at run time by loading
      !>     text kernels containing kernel variable assignments of the form
      !>
      !>        NAIF_SURFACE_NAME += ( <surface name 1>, ... )
      !>        NAIF_SURFACE_CODE += ( <surface code 1>, ... )
      !>        NAIF_SURFACE_BODY += ( <body code 1>,    ... )
      !>
      !>     Above, the Ith elements of the lists on the assignments' right
      !>     hand sides together define the Ith surface name/ID mapping.
      !>
      !>     The same effect can be achieved using assignments formatted as
      !>     follows:
      !>
      !>        NAIF_SURFACE_NAME += <surface name 1>
      !>        NAIF_SURFACE_CODE += <surface code 1>
      !>        NAIF_SURFACE_BODY += <body code 1>
      !>
      !>        NAIF_SURFACE_NAME += <surface name 2>
      !>        NAIF_SURFACE_CODE += <surface code 2>
      !>        NAIF_SURFACE_BODY += <body code 2>
      !>
      !>           ...
      !>
      !>     Note the use of the
      !>
      !>        +=
      !>
      !>     operator; this operator appends to rather than overwrites the
      !>     kernel variable named on the left hand side of the assignment.
      !>
      !>## Particulars
      !>
      !>     This routine supports parsing of the METHOD input argument
      !>     used by the SPICE geometry APIs
      !>
      !>        GFOCLT
      !>        ILLUMF
      !>        ILLUMG
      !>        ILUMIN
      !>        LATSRF
      !>        LIMBPT
      !>        SINCPT
      !>        SUBPNT
      !>        SUBSLR
      !>        TERMPT
      !>
      !>     Each API has its own syntax for its METHOD input argument.
      !>     All routines use a common syntax for surface lists. See
      !>     the headers of the routines for the exact syntax supported
      !>     by each routine.
      !>
      !>     In the METHOD string, the token delimiters are
      !>
      !>        / = , <blank>
      !>
      !>     Strings delimited by double quote characters are treated as
      !>     individual tokens. There is no escape syntax for indicating a
      !>     doubly quoted string within a doubly quoted string.
      !>
      !>## Examples
      !>
      !>     1) For the routine SUBPNT,
      !>
      !>           Method string =
      !>
      !>              METHOD = 'INTERCEPT / '
      !>              //       'DSK/UNPRIORITIZED/SURFACES = "MGS '
      !>              //       'MOLA 128 PIXEL/DEG", MARS_LOWRES'
      !>
      !>          Output parameters:
      !>
      !>             SHAPE  = 'DSK'
      !>             SUBTYP = 'INTERCEPT'
      !>             PRI    = .FALSE.
      !>             NSURF  = 2
      !>             SRFLST = <ID code 1>, <ID code 2>
      !>             PNTDEF = ' '
      !>             TRMTYP = ' '
      !>
      !>     2) For the routine TERMPT,
      !>
      !>           Method string =
      !>
      !>              METHOD = 'UMBRAL/TANGENT/ '
      !>              //       'DSK/UNPRIORITIZED/SURFACES = "MGS '
      !>              //       'MOLA 128 PIXEL/DEG", MARS_LOWRES'
      !>
      !>          Output parameters:
      !>
      !>             SHAPE  = 'DSK'
      !>             SUBTYP = ' '
      !>             PRI    = .FALSE.
      !>             NSURF  = 2
      !>             SRFLST = <ID code 1>, <ID code 2>
      !>             PNTDEF = 'TANGENT'
      !>             TRMTYP = 'UMBRAL'
      !>
      !>## Restrictions
      !>
      !>     This is a specialized parsing routine. It it meant to be used
      !>     only for the parsing "method" strings as described in
      !>     Particulars.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 24-FEB-2016 (NJB)
      !>
      !>        Based on version  4.0.0 12-NOV-2015 (NJB)
      !>        First version was 1.0.0 14-JAN-2015 (NJB)
      module subroutine zzprsmet ( ctx, bodyid, method, mxnsrf, shape, subtyp, pri, nsurf, srflst, pntdef, trmtyp )
      use pepper_kinds, only: ip
      use pepper_strings, only: eqstr, ljucrs
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: bodyid  !! Body ID code.
      character(*), intent(in) :: method  !! Method string.
      integer(ip), intent(in) :: mxnsrf  !! Maximum number of surface IDs that can be returned.
      character(*), intent(out) :: shape  !! Target shape.
      character(*), intent(out) :: subtyp  !! Sub-point type.
      logical, intent(out) :: pri  !! Prioritization flag.
      integer(ip), intent(out) :: nsurf  !! Number of surface IDs in list.
      integer(ip), intent(out) :: srflst ( * )  !! Surface ID list.
      character(*), intent(out) :: pntdef  !! Limb or terminator point definition.
      character(*), intent(out) :: trmtyp  !! Terminator type.

      character(*), parameter :: comma = ','


      character(*), parameter :: equals = '='

      character(*), parameter :: slash = '/'

      character(1) :: chr
!
!     PEPPER: the work string and the token arrays are sized from METHOD
!     (SPICELIB: 1000 characters, cut without an error, and 100 tokens).
!
      character(len(method)+1) :: locmth

      integer(ip) :: begs ( len(method) + 2 )
      integer(ip) :: code
      integer(ip) :: ends ( len(method) + 2 )
      integer(ip) :: i
      integer(ip) :: n
      integer(ip) :: npri
      integer(ip) :: nshape
      integer(ip) :: nlmbtp
      integer(ip) :: nsubtp
      integer(ip) :: nsrfls
      integer(ip) :: ntrmtp

      logical :: done
      logical :: fnd

      if ( ctx%failed() ) return

!
!     No shape or surfaces have been specified yet.
!
      shape  = ' '
      subtyp = ' '
      pntdef = ' '
      trmtyp = ' '
      pri    = .true.
      nsurf  = 0

!
!     Initialize clause counts.
!
      npri   = 0
      nshape = 0
      nsubtp = 0
      nlmbtp = 0
      ntrmtp = 0
      nsrfls = 0

      locmth(1:1) = slash
      begs(1)     = 1
      ends(1)     = 1

      call ljucrs ( 1, method, locmth(2:) )

!
!     Tokenize the input method string.
!
      call zzlexmet ( ctx, locmth(2:), int(len(method), ip), n, begs(2), ends(2) )

      if ( ctx%failed() ) return

      n = n + 1

      do i = 2, n
         begs(i) = begs(i) + 1
         ends(i) = ends(i) + 1
      end do

!
!     Identify the target shape.
!
      done = .false.
      i    = 1

      do while ( .not. done )

         if (  locmth( begs(i):ends(i) ) ==  'ELLIPSOID' ) then

            nshape = nshape + 1
            shape  = 'ELLIPSOID'

         else if (  locmth( begs(i):ends(i) ) ==  'DSK' ) then

            nshape = nshape + 1
            shape  = 'DSK'

         end if

         if ( i == n ) then

            done = .true.
         else
            i    = i + 1
         end if

      end do

      if ( nshape /= 1 ) then

         call ctx%setmsg ( 'The "method" or "shape" string must contain ' &
         //            'exactly one instance of a shape keyword: ' &
         //            'ELLIPSOID or DSK, or additionally, in the ' &
         //            'case of occultation computations, POINT. ' &
         //            'The number of shape keywords was #. ' &
         //            'The input string was <#>.'                  )
         call ctx%errint ( '#', nshape                                  )
         call ctx%errch  ( '#', method                                  )
         call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'                     )
         return

      end if

      if ( shape == 'DSK' ) then
!
!        Traverse the tokens; identify clauses in the method string.
!
         i = 1

         do while ( i < n )

            chr = locmth( begs(i):ends(i) )

            if ( chr == slash ) then
!
!              If the method string is correct, the next token should
!              be a keyword.
!
               i = i + 1

               if ( locmth( begs(i):ends(i) )  ==  'SURFACES' ) then
!
!                 Normally, we're looking at the start of a surface
!                 list at this point. We need at least an assignment
!                 operator ('=') and a surface name or ID code following
!                 the SURFACES keyword.
!
                  nsrfls = nsrfls + 1

                  if ( nsrfls > 1 ) then
!
!                    We have too many surface specifications.
!
                     call ctx%setmsg ( 'Extra SURFACES keyword was found ' &
                     //            'in the method string <#>.'       )
                     call ctx%errch  ( '#', method                       )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'          )
                     return

                  end if

                  if ( i > n-2 ) then

                     call ctx%setmsg ( 'The surface list in the method ' &
                     //            'string appears to be truncated. ' &
                     //            'The method string is <#>.'       )
                     call ctx%errch  ( '#', method                       )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'          )
                     return

                  end if

                  i   = i + 1

                  chr = locmth( begs(i):ends(i) )

                  if ( chr /= equals ) then

                     call ctx%setmsg ( 'The surface list in the method ' &
                     //            'string lacks an "=" sign after ' &
                     //            'the SURFACES keyword. ' &
                     //            'The method string is <#>.'      )
                     call ctx%errch  ( '#', method                      )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'         )
                     return

                  end if

!
!                 Prepare to read a list of names, quoted
!                 strings, or ID codes. The list must be non-empty. If
!                 there are multiple list entries, they're delimited by
!                 commas.
!
                  i    = i + 1
                  done = .false.

                  do while ( .not. done )

                     chr = locmth( begs(i):begs(i) )

                     if ( chr == dquote ) then
!
!                       We expect the current token to be a quoted
!                       string.
!
                        if ( ends(i) > begs(i)+1 ) then

                           begs(i) = begs(i) + 1
                           ends(i) = ends(i) - 1

                        else
!
!                          We have an invalid quoted string.
!
                           call ctx%setmsg ( 'The surface list in the ' &
                           //            'method string ' &
                           //            'contains a double quote ' &
                           //            'character that is not a ' &
                           //            'delimiter of a valid quoted ' &
                           //            'string. ' &
                           //            'The method string is <#>.'   )
                           call ctx%errch  ( '#', method                   )
                           call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'      )
                           return

                        end if

                     end if

!                    We have either a name or an integer in string form.
!                    Convert the token to a surface ID code.
!
                     call srfscc ( ctx, locmth(begs(i):ends(i)), &
                                   bodyid,   code,   fnd   )

                     if ( ctx%failed() ) return

                     if ( .not. fnd ) then

                        call ctx%setmsg ( 'The surface name <#> could not ' &
                        //            'be translated to an ID code. ' &
                        //            'The method string is <#>.'     )
                        call ctx%errch  ( '#', locmth(begs(i):ends(i))    )
                        call ctx%errch  ( '#', method                     )
                        call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'         )
                        return

                     end if

                     nsurf = nsurf + 1
!
!                    Make sure there's room in the surface ID array.
!
                     if ( nsurf > mxnsrf ) then

                        call ctx%setmsg ( 'The surface name <#> could not ' &
                        //            'be stored in the surface list ' &
                        //            'due to lack of room. The max' &
                        //            'imum number of surfaces that ' &
                        //            'can be specified is #. ' &
                        //            'The method string is <#>.'     )
                        call ctx%errch  ( '#', locmth(begs(i):ends(i))    )
                        call ctx%errint ( '#', mxnsrf                     )
                        call ctx%errch  ( '#', method                     )
                        call ctx%sigerr ( 'SPICE(TOOMANYSURFACES)'        )
                        return

                     end if

!
!                    Append the surface ID to the surface ID array.
!
                     srflst( nsurf ) = code

                     if ( i == n ) then
!
!                       We're at the end of the method string.
!
                        done = .true.

                     else
!
!                       There are more tokens; the surface list may
!                       contain more surface names or ID codes.
!
                        i   = i + 1
                        chr = locmth( begs(i):ends(i) )

                        if ( chr == slash ) then
!
!                          We're at the end of the surface list.
!
                           done = .true.
!
!                          Decrement the token pointer so that the
!                          slash will be seen as the next token.
!
                           i    = i - 1

                        else if ( chr == comma ) then
!
!                          We expect to find another surface name or
!                          ID in the list.
!
                           if ( i < n ) then

                              i = i + 1

                           else
!
!                             We have a syntax error in the surface
!                             list.
!
                              call ctx%setmsg ( 'The surface list in the ' &
                              //            'method string contains ' &
                              //            'a comma that is not ' &
                              //            'followed by a surface ' &
                              //            'name or ID code. The ' &
                              //            'method string is <#>.'   )
                              call ctx%errch  ( '#', method               )
                              call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'  )
                              return

                           end if

                        else
!
!                          We have a syntax error in the surface list.
!
                           call ctx%setmsg ( 'The surface list in the ' &
                           //            'method string is followed ' &
                           //            'by the unexpected token <#>.' &
                           //            ' The method string is <#>.'  )
                           call ctx%errch  ( '#', locmth(begs(i):ends(i))  )
                           call ctx%errch  ( '#', method                   )
                           call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'      )
                           return

                        end if

                     end if

                  end do

               else if (      locmth( begs(i):ends(i) ) &
                         == 'UNPRIORITIZED'            ) then

                  npri = npri + 1

                  if ( npri > 1 ) then
!
!                    We have too many prioritization specifications.
!
                     call ctx%setmsg ( 'Extra prioritization keyword was ' &
                     //            'found in the method string <#>.' )
                     call ctx%errch  ( '#', method                       )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'          )
                     return

                  end if

                  pri  = .false.

               else if (     (       locmth( begs(i):ends(i) ) &
                               == 'INTERCEPT'                ) &
                        .or. (       locmth( begs(i):ends(i) ) &
                               == 'NADIR'                    )  ) then
!
!                 This is a sub-point type specification.
!
                  nsubtp = nsubtp + 1

                  if ( nsubtp > 1 ) then
!
!                    We have too many sub-point specifications.
!
                     call ctx%setmsg ( 'Extra sub-point type <#> was found ' &
                     //            'in the method string <#>.'         )
                     call ctx%errch  ( '#', locmth( begs(i):ends(i) )      )
                     call ctx%errch  ( '#', method                         )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'            )
                     return

                  end if

                  subtyp = locmth( begs(i):ends(i) )

               else if (     (       locmth( begs(i):ends(i) ) &
                               == 'TANGENT'                ) &
                        .or. (       locmth( begs(i):ends(i) ) &
                               == 'GUIDED'                   )  ) then
!
!                 This is a point definition specification.
!
                  nlmbtp = nlmbtp + 1

                  if ( nlmbtp > 1 ) then
!
!                    We have too many point definition specifications.
!
                     call ctx%setmsg ( 'Extra point definition <#> was ' &
                     //            'found in the method string <#>.'   )
                     call ctx%errch  ( '#', locmth( begs(i):ends(i) )      )
                     call ctx%errch  ( '#', method                         )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'            )
                     return

                  end if

                  pntdef = locmth( begs(i):ends(i) )

               else if (     (       locmth( begs(i):ends(i) ) &
                               == 'UMBRAL'                   ) &
                        .or. (       locmth( begs(i):ends(i) ) &
                               == 'PENUMBRAL'                )  ) then
!
!                 This is a terminator type specification.
!
                  ntrmtp = ntrmtp + 1

                  if ( ntrmtp > 1 ) then
!
!                    We have too many terminator type specifications.
!
                     call ctx%setmsg ( 'Extra terminator type <#> was ' &
                     //            'found in the method string <#>.'   )
                     call ctx%errch  ( '#', locmth( begs(i):ends(i) )      )
                     call ctx%errch  ( '#', method                         )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'            )
                     return

                  end if

                  trmtyp = locmth( begs(i):ends(i) )

               else if (  locmth( begs(i):ends(i) ) == slash  )  then
!
!                 Adjust the token index in the message to account
!                 for the insertion of a slash at the beginning.
!
                  call ctx%setmsg ( 'An unexpected slash character was ' &
                  //            'found at index # in the method ' &
                  //            'string <#>.'                          )
                  call ctx%errint ( '#', begs(i)-1                         )
                  call ctx%errch  ( '#', method                            )
                  call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'               )
                  return

               else if ( locmth( begs(i):ends(i) )  /=  'DSK'  ) then
!
!                 'DSK' was the only valid token that could appear
!                 at this point.
!
                  call ctx%setmsg ( 'Unexpected token <#> was found ' &
                  //            'in the method string <#>.'       )
                  call ctx%errch  ( '#', locmth( begs(i):ends(i) )    )
                  call ctx%errch  ( '#', method                       )
                  call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'          )
                  return

               end if

            end if

            i = i + 1

         end do

!
!        Currently, the UNPRIORITIZED keyword must be provided
!        for DSK shapes.
!
         if ( pri ) then

            call ctx%setmsg ( 'The keyword UNPRIORITIZED must be ' &
            //            'present in the method string <#> ' &
            //            'when the target shape is DSK. ' &
            //            'Prioritized DSK segment searches ' &
            //            'are not currently supported.'      )
            call ctx%errch  ( '#', method                         )
            call ctx%sigerr ( 'SPICE(BADPRIORITYSPEC)'            )
            return

         end if

      else if ( shape == 'ELLIPSOID' ) then
!
!        Check for legacy string inputs.
!
         if ( eqstr(method, 'ELLIPSOID') ) then
!
!           There are no other outputs to set.
!
            return

         else if (      eqstr(method, 'NEARPOINT:ELLIPSOID') &
                   .or. eqstr(method, 'ELLIPSOID:NEARPOINT') &
                   .or. eqstr(method, 'NEARPOINT/ELLIPSOID') &
                   .or. eqstr(method, 'ELLIPSOID/NEARPOINT')  ) then

            subtyp = 'NEAR POINT'

            return

         else if (      eqstr(method, 'INTERCEPT:ELLIPSOID') &
                   .or. eqstr(method, 'ELLIPSOID:INTERCEPT') &
                   .or. eqstr(method, 'INTERCEPT/ELLIPSOID') &
                   .or. eqstr(method, 'ELLIPSOID/INTERCEPT')  ) then

            subtyp = 'INTERCEPT'

            return

         end if

!
!        At this point, we should have a "modern" style of method
!        specification for an ellipsoidal shape model.
!        Parse the method string.
!
!        Traverse the tokens; identify clauses in the method string.
!
         i = 1

         do while ( i <= n )

            chr = locmth( begs(i):ends(i) )

            if ( chr == slash ) then
!
!              If the method string is correct, the next token should
!              be a keyword. There had better be a next token.
!
               if ( i == n ) then

                  call ctx%setmsg ( 'Expected more tokens after final <#> ' &
                     //         'in the method string <#>.'            )
                  call ctx%errch  ( '#', locmth( begs(i):ends(i) )         )
                  call ctx%errch  ( '#', method                            )
                  call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'               )
                  return

               end if

               i = i + 1

               if (  locmth( begs(i):ends(i) ) ==  'ELLIPSOID' ) then
!
!                 This case is a no-op.
!

               else if (     (       locmth( begs(i):ends(i) ) &
                               == 'INTERCEPT'                ) &
                        .or. (       locmth( begs(i):ends(i) ) &
                               == 'NADIR'                    ) &
                        .or. (       locmth( begs(i):ends(i) ) &
                               == 'NEAR'                     )  ) then
!
!                 This is a sub-point type specification.
!
                  nsubtp = nsubtp + 1

                  if ( nsubtp > 1 ) then
!
!                    We have too many sub-point specifications.
!
                     call ctx%setmsg ( 'Extra sub-point type <#> was found ' &
                     //            'in the method string <#>.'         )
                     call ctx%errch  ( '#', locmth( begs(i):ends(i) )      )
                     call ctx%errch  ( '#', method                         )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'            )
                     return

                  end if

                  if ( locmth( begs(i):ends(i) ) == 'NEAR' ) then
!
!                    This may be a combination of old style and
!                    new syntax, e.g. 'ELLIPSOID/NEAR POINT'.
!
                     if (       ( shape == 'ELLIPSOID' ) &
                          .and. ( i     <  n          )  ) then
!
!                       We allow the "near point" sub-point type
!                       for ellipsoids but not for DSK surfaces.
!
                        if (     locmth( begs(i+1) : ends(i+1) ) &
                            == 'POINT'                          ) then

                           subtyp = 'NADIR'

                        end if

                     end if

                  else
                     subtyp = locmth( begs(i):ends(i) )
                  end if

               else if (     (       locmth( begs(i):ends(i) ) &
                               == 'TANGENT'                ) &
                        .or. (       locmth( begs(i):ends(i) ) &
                               == 'GUIDED'                   )  ) then
!
!                 This is a point definition specification.
!

                  nlmbtp = nlmbtp + 1

                  if ( nlmbtp > 1 ) then
!
!                    We have too many point definition specifications.
!
                     call ctx%setmsg ( 'Extra point definition <#> was ' &
                     //            'found in the method string <#>.'   )
                     call ctx%errch  ( '#', locmth( begs(i):ends(i) )      )
                     call ctx%errch  ( '#', method                         )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'            )
                     return

                  end if

                  pntdef = locmth( begs(i):ends(i) )

               else if (     (       locmth( begs(i):ends(i) ) &
                               == 'UMBRAL'                   ) &
                        .or. (       locmth( begs(i):ends(i) ) &
                               == 'PENUMBRAL'                )  ) then
!
!                 This is a terminator type specification.
!
                  ntrmtp = ntrmtp + 1

                  if ( ntrmtp > 1 ) then
!
!                    We have too many terminator type specifications.
!
                     call ctx%setmsg ( 'Extra terminator type <#> was ' &
                     //            'found in the method string <#>.'   )
                     call ctx%errch  ( '#', locmth( begs(i):ends(i) )      )
                     call ctx%errch  ( '#', method                         )
                     call ctx%sigerr ( 'SPICE(BADMETHODSYNTAX)'            )
                     return

                  end if

                  trmtyp = locmth( begs(i):ends(i) )

               else
!
!                 Sorry, no other strings are allowed.
!
                  call ctx%setmsg( 'Unexpected method string <#> was found ' &
                  //           'specifying an ellipsoid shape.'        )
                  call ctx%errch ( '#', method                             )
                  call ctx%sigerr( 'SPICE(BADMETHODSYNTAX)'                )
                  return

               end if

            else

               call ctx%setmsg( 'Unexpected method string <#> was found ' &
               //           'specifying an ellipsoid shape.'        )
               call ctx%errch ( '#', method                             )
               call ctx%sigerr( 'SPICE(BADMETHODSYNTAX)'                )
               return

            end if

            i = i + 1

         end do

      else
!
!        This is a backstop error check.
!
         call ctx%setmsg ( 'Unexpected shape value # was found. ' &
         //            'This is due to a coding error, not ' &
         //            'to user input.'                      )
         call ctx%errch  ( '#', shape                            )
         call ctx%sigerr ( 'SPICE(BUG)'                          )
         return

      end if

      return
      end subroutine zzprsmet

      !> Find nearest intersection to a given ray's vertex of the ray and
      !> a planetodetic volume element. If the vertex is inside the
      !> element, the vertex is considered to be the solution.
      !>
      !> In the computation performed by this routine, ellipsoidal
      !> surfaces are used, instead of surfaces of constant altitude, to
      !> define boundaries of planetodetic volume elements. The element
      !> defined by the input boundaries is contained in the element
      !> bounded by the input latitude and longitude boundaries and by the
      !> ellipsoidal surfaces.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     VERTEX,
      !>     RAYDIR     are, respectively, the vertex and direction vector of
      !>                the ray to be used in the intercept computation.
      !>
      !>                Both the vertex and ray direction must be represented
      !>                in the reference frame to which the planetodetic
      !>                volume element boundaries correspond. The vertex is
      !>                considered to be an offset from the center of the
      !>                reference frame associated with the element.
      !>
      !>     BOUNDS     is a 2x3 array containing the bounds of a planetodetic
      !>                volume element. Normally this is the coverage boundary
      !>                of a DSK segment. In the element
      !>
      !>                   BOUNDS(I,J)
      !>
      !>                J is the coordinate index. J is one of
      !>
      !>                   { LONIDX, LATIDX, ALTIDX }
      !>
      !>                I is the bound index.
      !>
      !>                   I = 1   ->   lower bound
      !>                   I = 2   ->   upper bound
      !>
      !>                If the longitude upper bound is not greater than the
      !>                longitude lower bound, a value greater than the upper
      !>                bound by 2*pi is used for the comparison.
      !>
      !>     RE,
      !>     F          are, respectively, the equatorial radius and
      !>                flattening coefficient associated with the
      !>                planetodetic coordinate system in which the input
      !>                volume element is described.
      !>
      !>     MARGIN     is a scale factor used to effectively expand the
      !>                segment boundaries so as to include intersections
      !>                that lie slightly outside the volume element.
      !>
      !>## Detailed Output
      !>
      !>     XPT        is the intercept of the ray on the surface described
      !>                by the segment, if such an intercept exists. If the
      !>                ray intersects the surface at multiple points, the
      !>                one closest to the ray's vertex is selected. XPT is
      !>                valid if and only if FOUND is .TRUE.
      !>
      !>                XPT is expressed in the reference frame associated
      !>                with the inputs VERTEX and RAYDIR. XPT represents
      !>                an offset from the origin of the coordinate system.
      !>
      !>                XPT is valid only if NXPTS is set to 1.
      !>
      !>     NXPTS      is the number of intercept points of the ray and
      !>                the volume element.
      !>
      !>                Currently there are only two possible values for
      !>                NXPTS:
      !>
      !>                   1 for an intersection
      !>                   0 for no intersection
      !>
      !>                If the vertex is inside the element, NXPTS is
      !>                set to 1.
      !>
      !>## Parameters
      !>
      !>     LONIDX     is the index of longitude in the second dimension of
      !>                BOUNDS.
      !>
      !>     LATIDX     is the index of latitude in the second dimension of
      !>                BOUNDS.
      !>
      !>     ALTIDX     is the index of altitude in the second dimension of
      !>                BOUNDS.
      !>
      !>## Exceptions
      !>
      !>     1)  If MARGIN is negative, the error SPICE(VALUEOUTOFRANGE)
      !>         is signaled.
      !>
      !>     2)  If the input ray direction vector is zero, the error
      !>         SPICE(ZEROVECTOR) will be signaled.
      !>
      !>     3)  Any errors that occur while calculating the ray-surface
      !>         intercept will be signaled by routines in the call tree
      !>         of this routine.
      !>
      !>## Files
      !>
      !>     None. However, the input segment boundaries normally have
      !>     been obtained from a loaded DSK file.
      !>
      !>## Particulars
      !>
      !>     This routine sits on top of data DSK type-specific ray-segment
      !>     intercept routines such as DSKX02.
      !>
      !>## Examples
      !>
      !>     See usage in ZZDSKBUX.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 19-JAN-2017 (NJB)
      module subroutine zzrytpdt ( ctx, vertex, raydir, bounds, corpar, margin, nxpts, xpt )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: dpmax, halfpi
      use pepper_math, only: ucrss, vdist, vdot, vhat, vnorm, vsep
      use pepper_inc_dsktol
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: vertex ( 3 )  !! Ray's vertex.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      real(wp), intent(in) :: bounds ( 2, 3 )  !! Bounds of planetodetic volume element.
      real(wp), intent(in) :: corpar ( * )  !! Coordinate parameters.
      real(wp), intent(in) :: margin  !! Margin used for element expansion.
      integer(ip), intent(out) :: nxpts  !! Number of intercept points.
      real(wp), intent(out) :: xpt    ( 3 )  !! Intercept.
      integer(ip), parameter :: lower = 1
      integer(ip), parameter :: upper = 2
      integer(ip), parameter :: none = 0
      real(wp) :: amnalt
      real(wp) :: amxalt
      real(wp) :: angle
      real(wp) :: apex   ( 3 )
      real(wp) :: dist
      real(wp) :: eastb  ( 3 )
      real(wp) :: eback  ( 3 )
      real(wp) :: emax
      real(wp) :: emin
      real(wp) :: endpt2 ( 3 )
      real(wp) :: f
      real(wp) :: loncov
      real(wp) :: maxalt
      real(wp) :: maxlat
      real(wp) :: maxlon
      real(wp) :: maxr
      real(wp) :: minalt
      real(wp) :: minlat
      real(wp) :: minlon
      real(wp) :: mndist
      real(wp) :: negdir ( 3 )
      real(wp) :: pmax
      real(wp) :: pmin
      real(wp) :: re
      real(wp) :: rp
      real(wp) :: s
      real(wp) :: srfx   ( 3 )
      real(wp) :: udir   ( 3 )
      real(wp) :: vtxang
      real(wp) :: vtxlvl
      real(wp) :: vtxoff ( 3 )
      real(wp) :: wback  ( 3 )
      real(wp) :: westb  ( 3 )
      real(wp) :: xpt2   ( 3 )
      real(wp) :: xincpt
      real(wp) :: yincpt
      integer(ip) :: nx
      logical :: found
      logical :: inside
      logical :: xin
      logical :: xval1
      logical :: xval2
      if ( .not. allocated ( ctx%zzrytpdt_state ) ) allocate ( ctx%zzrytpdt_state )
      associate ( z => ctx%zzrytpdt_state%z )
      if ( ctx%failed() ) return

      if ( margin < 0.0_wp ) then

         call ctx%setmsg ( 'Margin must be non-negative but was #.' )
         call ctx%errdp  ( '#', margin                              )
         call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'                 )
         return

      end if

      if ( all(raydir == 0.0_wp) ) then

         call ctx%setmsg ( 'The ray''s direction was the zero vector.' )
         call ctx%sigerr ( 'SPICE(ZEROVECTOR)'                         )
         return

      end if

!
!     Determine whether the vertex is inside the element.
!
      call zzinpdt ( ctx, vertex, bounds, corpar, margin, none, inside )

      if ( ctx%failed() ) return

      if ( inside ) then
!
!        We know the answer.
!
         nxpts = 1

         xpt = vertex

         return

      end if

!
!     Get semi-axis lengths of the reference spheroid.
!
      re = corpar(1)
      f  = corpar(2)
      rp = re * ( 1.0_wp - f )

!
!     Extract the segment's coordinate bounds into easily
!     readable variables.
!
      minalt = bounds( lower, altidx )
      maxalt = bounds( upper, altidx )
!
!     Normalize the longitude bounds. After this step, the bounds will
!     be in order and differ by no more than 2*pi.
!
      call zznrmlon( ctx, bounds(west,lonidx), bounds(east,lonidx), angmrg, &
                     minlon,              maxlon                      )

      if ( ctx%failed() ) return

      minlat = bounds( south, latidx )
      maxlat = bounds( north, latidx )

!
!     Compute adjusted altitude bounds, taking margin into
!     account.
!
      amnalt = minalt  -  margin * abs(minalt)
      amxalt = maxalt  +  margin * abs(maxalt)

!
!     Generate semi-axis lengths of inner and outer bounding
!     ellipsoids.
!
      if ( re >= rp ) then
!
!        The reference spheroid is oblate.
!
         call zzellbds ( ctx, re,   rp,   amxalt, amnalt, &
                         emax, pmax, emin,   pmin   )

      else
!
!        The reference spheroid is prolate.
!
         call zzellbds ( ctx, rp,   re,   amxalt, amnalt, &
                         pmax, emax, pmin,   emin   )

      end if

      if ( ctx%failed() ) return

!
!     The vertex is outside the element.
!
!     Indicate no intersection to start.
!
      nxpts  = 0
!
!     We'll use a unit length copy of the ray's direction vector.
!
      call vhat ( raydir, udir )
!
!     Initialize the distance to the closest solution. We'll keep track
!     of this quantity in order to compare competing solutions.
!
      mndist = dpmax
!
!     Find the intersection of the ray and outer bounding ellipsoid, if
!     possible. Often this intersection is the closest to the vertex.
!     If the intersection exists and is on the boundary of the element,
!     it's a winner.
!
      call surfpt ( ctx, vertex, udir, emax, emax, pmax, srfx, found )

      if ( ctx%failed() ) return

      if ( .not. found ) then
!
!        There are no intersections. The ray cannot hit the volume
!        element.
!
         return

      end if

!
!     The ray hits the outer bounding ellipsoid. See whether
!     the longitude and latitude are within bounds, taking
!     the margin into account. Exclude the altitude coordinate
!     from testing.
!
      call zzinpdt ( ctx, srfx, bounds, corpar, margin, altidx, xin )

      if ( ctx%failed() ) return

      if ( xin ) then
!
!        This solution is a candidate.
!
         xpt = srfx
         nxpts  = 1

!
!        Find the level surface parameter of the vertex relative
!        to the adjusted outer bounding ellipsoid.
!
         vtxlvl =     ( vertex(1)/emax )**2 &
                   +  ( vertex(2)/emax )**2 &
                   +  ( vertex(3)/pmax )**2

         if ( vtxlvl > 1.0_wp ) then
!
!           The vertex is outside this ellipsoid, and the DSK segment
!           lies within the ellipsoid.
!
!           No other intersection can be closer to the vertex;
!           we don't need to check the other surfaces.
!
            return

         else
!
!           We have a possible solution.
!
            mndist = vdist( vertex, xpt )

         end if

      end if

!
!     So far there may be a candidate solution. We'll try the latitude
!     boundaries next.
!
!     For testing intersections with the latitude boundaries, we'll
!     need a far endpoint for the line segment on which to perform the
!     test.
!
      maxr = max ( emax, pmax )

      s    = vnorm(vertex) + radfac * maxr

      endpt2 = 1.0_wp*vertex + s*udir

!
!     Now try the upper latitude bound. We can skip this test
!     if the upper bound is pi/2 radians.
!
      if ( maxlat < halfpi ) then
!
!        Let ANGLE be the angular separation of the surface of latitude
!        MAXLAT and the +Z axis. Note that the surface might be the
!        lower nappe of the cone.
!
         angle = max ( 0.0_wp,  halfpi - maxlat )

!
!        Compute the Z coordinate of the apex of the latitude cone.
!
         call zzelnaxx ( ctx, re, rp, maxlat, xincpt, yincpt )

         if ( ctx%failed() ) return

         apex(1) = 0.0_wp
         apex(2) = 0.0_wp
         apex(3) = yincpt

!
!        Find the offset of the ray's vertex from the cone's apex,
!        and find the angular separation of the offset from the +Z
!        axis. This separation enables us to compare the latitude of
!        the vertex to the latitude boundary without making a RECGEO
!        call to compute the planetodetic coordinates of the vertex.
!
!        (The comparison will be done later.)
!
         vtxoff = vertex - apex

         vtxang = vsep ( vtxoff, z )

!
!        Check for intersection of the ray with the latitude cone.
!
         call incnsg ( ctx, apex, z, angle, vertex, endpt2, nx, srfx, xpt2 )

         if ( ctx%failed() ) return

!
!        Unlike the case of latitudinal coordinates, for planetodetic
!        coordinates, the surface of the latitude cone does not
!        coincide with the set of points having that latitude (which is
!        equal to pi/2 - the cone's angular separation from the +Z
!        axis). The subset of the cone having the specified latitude is
!        truncated by the X-Y plane. If we ignore round-off errors, we
!        can assert that the Z-coordinate of a point having the given
!        planetodetic latitude must match the direction of the nappe of
!        the cone: positive if ANGLE < pi/2, negative if ANGLE > pi/2,
!        and 0 if ANGLE = pi/2.
!
!        However, we cannot ignore round-off errors. For a cone having
!        angle from its central axis of nearly pi/2, it's possible for
!        a valid ray-cone intercept to be on the "wrong" side of the
!        X-Y plane due to round-off errors. So we use a more robust
!        check to determine whether an intercept should be considered
!        to have the same latitude as the cone.
!
!        Check all intercepts.
!
         if ( nx > 0 ) then
!
!           Check the first intercept.
!
            xval1 =  zzpdpltc( ctx, re, f, srfx, maxlat )
            xval2 =  .false.

            if ( nx == 2 ) then
!
!              Check the second intercept.
!
               xval2 =  zzpdpltc( ctx, re, f, xpt2, maxlat )

            end if

            if ( xval1 .and. ( .not. xval2 ) ) then

               nx = 1

            else if (  xval2  .and.  (.not. xval1 )  ) then
!
!              Only the second solution is valid. Overwrite
!              the first.
!
               nx = 1

               srfx = xpt2

            else if (  ( .not. xval1 )  .and.  ( .not. xval2 )  ) then
!
!              Neither solution is valid.
!
               nx = 0

            end if

         end if

         if ( nx >= 1 ) then
!
!           The ray intercept SRFX lies on the upper latitude boundary.
!
!           See whether SRFX meets the longitude and proxy altitude
!           constraints.
!
            call zzinpdt ( ctx, srfx, bounds, corpar, margin, latidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then
!
!              SRFX is a candidate solution.
!
               dist = vdist( vertex, srfx )

               if ( dist < mndist ) then

                  xpt = srfx

                  nxpts  = 1

                  if ( vtxang < angle ) then

                     if (      ( maxlat    < 0.0_wp ) &
                          .or. ( vertex(3) > 0.0_wp )  ) then
!
!                       If MAXLAT is negative, the vertex offset
!                       being outside the cone is enough to
!                       guarantee the planetodetic latitude of the
!                       vertex is greater than that of the cone.
!
!                       If MAXLAT is non-negative, the angle of the
!                       vertex offset relative to the +Z axis is not
!                       enough; we need the vertex to lie above the
!                       X-Y plane as well.
!
!                       Getting here means one of these conditions
!                       was met.
!
!                       Since the latitude of the vertex is greater
!                       than MAXLAT, this is the best solution, since
!                       the volume element is on the other side of the
!                       maximum latitude boundary.
!
                        return

                     end if

                  end if
!
!                 This is the best solution seen so far, but we
!                 need to check the remaining boundaries.
!
                  mndist = dist

               end if

            end if

            if ( nx == 2 ) then
!
!              Check the second solution as well.
!
               call zzinpdt ( ctx, xpt2,   bounds, corpar, &
                              margin, latidx, xin    )

               if ( ctx%failed() ) return

               if ( xin ) then
!
!                 XPT2 is a candidate solution.
!
                  dist = vdist( vertex, xpt2 )

                  if ( dist < mndist ) then

                     xpt = xpt2

                     nxpts  = 1
                     mndist = dist
!
!                    This is the best solution seen so far.
!                    However, it's not necessarily the best
!                    solution. So we continue.
!
                  end if

               end if

            end if
!
!           We've handled the second root, if any.
!
         end if
!
!        We're done with the upper latitude boundary.
!
      end if

!
!     Try the lower latitude bound. We can skip this test if the lower
!     bound is -pi/2 radians.
!
      if (  minlat > -halfpi ) then
!
!        Let ANGLE be the angular separation of the surface
!        of latitude MINLAT and the +Z axis. Note that the
!        surface might be the lower nappe of the cone.
!
         angle = halfpi - minlat

!        Compute the Z coordinate of the apex of the latitude cone.
!
         call zzelnaxx ( ctx, re, rp, minlat, xincpt, yincpt )

         if ( ctx%failed() ) return

         apex(1) = 0.0_wp
         apex(2) = 0.0_wp
         apex(3) = yincpt

         call incnsg ( ctx, apex,   z,  angle, vertex, &
                       endpt2, nx, srfx,  xpt2    )

         if ( ctx%failed() ) return

!
!        Find the offset of the ray's vertex from the cone's apex,
!        and find the angular separation of the offset from the +Z
!        axis. This separation enables us to compare the latitude of
!        the vertex to the latitude boundary without making a RECGEO
!        call to compute the planetodetic coordinates of the vertex.
!
!        (The comparison will be done later.)
!
         vtxoff = vertex - apex

         vtxang = vsep ( vtxoff, z )

!
!        Check whether the latitude of the intercept can be
!        considered to match that of the cone.
!
         if ( nx > 0 ) then
!
!           Check the first intercept.
!
            xval1 =  zzpdpltc( ctx, re, f, srfx, minlat )
            xval2 =  .false.

            if ( nx == 2 ) then
!
!              Check the second intercept.
!
               xval2 =  zzpdpltc( ctx, re, f, xpt2, minlat )

            end if

            if ( xval1 .and. ( .not. xval2 ) ) then

               nx = 1

            else if (  xval2  .and.  (.not. xval1 )  ) then
!
!              Only the second solution is valid. Overwrite
!              the first.
!
               nx = 1

               srfx = xpt2

            else if (  ( .not. xval1 )  .and.  ( .not. xval2 )  ) then
!
!              Neither solution is valid.
!
               nx = 0

            end if

         end if

         if ( nx >= 1 ) then
!
!           The ray intercept SRFX lies on the lower latitude boundary.
!
!           See whether SRFX meets the longitude and proxy altitude
!           constraints.
!
            call zzinpdt ( ctx, srfx, bounds, corpar, margin, latidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then
!
!              SRFX is a candidate solution.
!
               dist = vdist( vertex, srfx )

               if ( dist < mndist ) then

                  xpt = srfx

                  nxpts  = 1

                  if ( vtxang > angle ) then

                     if (      ( minlat    > 0.0_wp ) &
                          .or. ( vertex(3) < 0.0_wp )  ) then
!
!                       If MINLAT is positive, the vertex offset
!                       being outside the cone is enough to
!                       guarantee the planetodetic latitude of the
!                       vertex is less than that of the cone.
!
!                       If MINLAT is non-positive, the angle of the
!                       vertex offset relative to the +Z axis is not
!                       enough; we need the vertex to lie below the
!                       X-Y plane as well.
!
!                       Getting here means one of these conditions
!                       was met.
!
!                       Since the latitude of the vertex is less than
!                       than MINLAT, this is the best solution, since
!                       the volume element is on the other side of the
!                       minimum latitude boundary.
!
                        return

                     end if

                  end if
!
!                 This is the best solution seen so far, but we
!                 need to check the remaining boundaries.

                  mndist = dist

               end if

            end if

            if ( nx == 2 ) then
!
!              Check the second solution as well.
!
               call zzinpdt ( ctx, xpt2,   bounds, corpar, &
                              margin, latidx, xin    )

               if ( ctx%failed() ) return

               if ( xin ) then
!
!                 XPT2 is a candidate solution.
!
                  dist = vdist( vertex, xpt2 )

                  if ( dist < mndist ) then

                     xpt = xpt2

                     nxpts  = 1
                     mndist = dist
!
!                    This is the best solution seen so far.
!                    However, it's not necessarily the best
!                    solution. So we continue.
!
                     return

                  end if

               end if

            end if

         end if
!
!        We're done with the lower latitude boundary.
!
      end if

!
!     Perform longitude boundary checks if the coverage is not
!     2*pi radians. Note that MAXLON > MINLON at this point.
!
      loncov = maxlon - minlon

      if ( cos(loncov) < 1.0_wp ) then
!
!        We have distinct longitude boundaries. Go to work.
!
!        Check the longitude boundaries. Try the plane of western
!        longitude first.
!
         westb = [sin(minlon), -cos(minlon), 0.0_wp]

         s = radfac * ( vnorm(vertex) + maxr )

         call zzinrypl ( ctx, vertex, udir, westb, 0.0_wp, s, nx, srfx )

         if ( nx == 1 ) then
!
!           We have one point of intersection. Determine whether it's a
!           candidate solution.  Don't use longitude in the following
!           inclusion test. Note that we'll perform a separate check
!           later in place of the longitude check.
!
            call zzinpdt ( ctx, srfx, bounds, corpar, margin, lonidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then
!
!              Make sure the intercept is not too far on the
!              "wrong" side of the Z axis.
!
               call ucrss ( westb, z, wback )

               if (  vdot(srfx, wback) < (margin*maxr)  ) then
!
!                 The intercept is either on the same side of the Z
!                 axis as the west face of the segment, or is very
!                 close to the Z axis.
!
                  dist = vdist( vertex, srfx )

                  if ( dist < mndist ) then
!
!                    Record the intercept, distance, and surface index.
!
                     xpt = srfx

                     nxpts  = 1
                     mndist = dist

                  end if

               end if

            end if

         end if
!
!        We're done with the western boundary.
!
!        Try the plane of eastern longitude next.
!
         eastb = [-sin(maxlon), cos(maxlon), 0.0_wp]

         call zzinrypl ( ctx, vertex, udir, eastb, 0.0_wp, s, nx, srfx )

         if ( nx == 1 ) then
!
!           We have one point of intersection. Determine whether it's a
!           candidate solution.
!
            call zzinpdt ( ctx, srfx, bounds, corpar, margin, lonidx, xin )

            if ( ctx%failed() ) return

            if ( xin ) then
!
!              Make sure the intercept is not too far on the "wrong"
!              side of the Z axis.
!
               call ucrss ( z, eastb, eback )

               if (  vdot(srfx, eback) < (margin*maxr)  ) then
!
!                 The intercept is either on the same side of the Z
!                 axis as the east face of the segment, or is very
!                 close to the Z axis.
!
                  dist = vdist( vertex, srfx )

                  if ( dist < mndist ) then
!
!                    Record the intercept, distance, and surface index.
!
                     xpt = srfx

                     nxpts  = 1
                     mndist = dist

                  end if

               end if

            end if

         end if

      end if
!
!     End of longitude boundary checks.
!

!
!     Find the intersection of the ray and lower bounding
!     ellipsoid, if possible.
!
      call surfpt ( ctx, vertex, udir, emin, emin, pmin, srfx, found )

      if ( ctx%failed() ) return

      if ( found ) then
!
!        See whether this solution is in the element.
!
         call zzinpdt ( ctx, srfx, bounds, corpar, margin, altidx, xin )

         if ( ctx%failed() ) return

         if ( xin ) then

            dist = vdist( vertex, srfx )

            if ( dist < mndist ) then
!
!              Record the intercept, distance, and surface index.
!
               xpt = srfx

               nxpts  = 1
               mndist = dist

            end if

         end if

      end if

!
!     Unlike the outer ellipsoid, either intersection of the ray with
!     the inner ellipsoid might be a valid solution. We'll test for the
!     case where the intersection farther from the ray's vertex is the
!     correct one.
!
      negdir = -udir

      call surfpt ( ctx, endpt2, negdir, emin, emin, pmin, srfx, found )

      if ( ctx%failed() ) return

      if ( found ) then

         call zzinpdt ( ctx, srfx, bounds, corpar, margin, altidx, xin )

         if ( ctx%failed() ) return

         if ( xin ) then

            dist = vdist( vertex, srfx )

            if ( dist < mndist ) then
!
!              Record the intercept, distance, and surface index.
!
               xpt = srfx

               nxpts  = 1
!
!              There's no need to update MNDIST at this point.
!
            end if

         end if

      end if

!
!     NXPTS and XPT are set.
!
      return
      end associate
      end subroutine zzrytpdt

      !> Determine the plate ID and body-fixed coordinates of the
      !> intersection of a specified ray with the surface defined by a
      !> type 2 DSK plate model.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE   is the file handle of a DSK file containing a shape
      !>              model for a target body. The shape model is stored
      !>              in a type 2 DSK segment.
      !>
      !>     DLADSC   is the DLA descriptor of a type 2 DSK segment
      !>              containing plate model data representing the surface of
      !>              the target body. The caller should declare DLADSC
      !>              with size DLADSZ; this size parameter is defined in
      !>              the INCLUDE file dla.inc. Normally this descriptor
      !>              will be obtained by a search through a DSK file
      !>              using the DLA search routines; see the $Examples
      !>              header section below for a working code example
      !>              illustrating a simple search.
      !>
      !>     VERTEX   is the vertex of a ray. VERTEX is expressed relative
      !>              to the body fixed reference frame associated with the
      !>              target body. This reference frame is the same frame
      !>              relative to which the vertices of the plate model
      !>              are expressed. Units are km.
      !>
      !>              The vertex is required to be outside the target
      !>              body.
      !>
      !>     RAYDIR   is the ray's direction vector. RAYDIR is expressed
      !>              relative to the body fixed reference frame associated
      !>              with the target body.
      !>
      !>## Detailed Output
      !>
      !>     PLID     is the ID of the plate closest to the input ray's
      !>              vertex at which a ray-surface intercept exists.
      !>              If no intercept exists, PLID is undefined.
      !>
      !>     XPT      is the ray-target intercept closest to the ray's
      !>              vertex, if an intercept exists. XPT is expressed
      !>              relative to the body-fixed reference frame associated
      !>              with the target body. Units are km.
      !>
      !>              If no intercept exists, XPT is undefined.
      !>
      !>     FOUND    is a logical flag that indicates whether or not the
      !>              ray does indeed intersect the target. If the ray
      !>              intersects a plate FOUND is .TRUE. Otherwise FOUND is
      !>              .FALSE.
      !>
      !>## Parameters
      !>
      !>     XFRACT   is the default plate expansion fraction. This
      !>              parameter can be overridden.
      !>
      !>     See the include file
      !>
      !>        dsktol.inc
      !>
      !>     for the values of tolerance parameters used by default by the
      !>     ray-surface intercept algorithm.
      !>
      !>     See the include file
      !>
      !>        dla.inc
      !>
      !>     for declarations of DLA descriptor sizes and documentation of the
      !>     contents of DLA descriptors.
      !>
      !>     See the include file
      !>
      !>        dskdsc.inc
      !>
      !>     for declarations of DSK descriptor sizes and documentation of the
      !>     contents of DSK descriptors.
      !>
      !>     See the include file
      !>
      !>        dsk02.inc
      !>
      !>     for declarations of DSK data type 2 (plate model) parameters.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input handle is invalid, an error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     2)  If a file read error occurs, the error is signaled by a
      !>         routine in the call tree of this routine.
      !>
      !>     3)  If the input DLA descriptor is invalid, the effect of this
      !>         routine is undefined. The error *may* be diagnosed by
      !>         routines in the call tree of this routine, but there are no
      !>         guarantees.
      !>
      !>     4)  If an error occurs while trying to look up any component
      !>         of the shape model, the error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     5)  If the input ray direction is the zero vector, the error
      !>         SPICE(ZEROVECTOR) is signaled.
      !>
      !>     6)  If the coarse voxel grid scale of the shape model is less
      !>         than 1, the error SPICE(VALUEOUTOFRANGE) is signaled.
      !>
      !>     7)  If the coarse voxel grid of the shape model contains more
      !>         than MAXCGR (see dsk02.inc) voxels, the error
      !>         SPICE(GRIDTOOLARGE) is signaled.
      !>
      !>     8)  PEPPER: the plate lists of the intersected voxels are
      !>         buffered whatever their size (SPICELIB signaled
      !>         SPICE(ARRAYTOOSMALL) beyond 256000 plates in a voxel group,
      !>         and XDDA beyond 50000 voxels on the ray).
      !>
      !>     9)  Due to round-off errors, results from this routine may
      !>         differ across platforms. Results also may differ from
      !>         those expected---and not necessarily by a small amount.
      !>         For example, a ray may miss a plate it was expected to
      !>         hit and instead hit another plate considerably farther
      !>         from the ray's vertex, or miss the target entirely.
      !>
      !>     10) In the event that an intercept point lies on multiple
      !>         plates (that is, the point is on an edge or vertex),
      !>         a plate will be selected. Due to round-off error, the
      !>         selection may vary across platforms.
      !>
      !>## Files
      !>
      !>     See the description of the input argument HANDLE.
      !>
      !>## Particulars
      !>
      !>     This routine solves the ray-surface intercept problem for
      !>     a specified ray and a surface represented by triangular plate
      !>     model. The surface representation is provided by data in a
      !>     type 2 segment of a DSK file.
      !>
      !>     This routine does not assume that the segment from which the
      !>     surface model data are read represents the entire surface of
      !>     the target body. A program could call this routine repeatedly
      !>     to find the surface intercept of a ray and a shape model
      !>     partitioned into multiple segments.
      !>
      !>     In general, this routine should be expected to run faster
      !>     when used with smaller shape models.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as input,
      !>     the compiler and supporting libraries, and the machine specific
      !>     arithmetic implementation.
      !>
      !>     1) Find the surface intercept points corresponding to a latitude/
      !>        longitude grid of a specified resolution, for a specified
      !>        target body.
      !>
      !>        This simple program assumes the shape model for the target
      !>        body is stored in a single type 2 DSK segment, and that this
      !>        segment is the first one in the DSK file to which it belongs.
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM DSKX02_EX1
      !>      IMPLICIT NONE
      !>
      !>      INCLUDE 'dla.inc'
      !>      INCLUDE 'dskdsc.inc'
      !>      INCLUDE 'dsk02.inc'
      !>C
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      DSKSGR
      !>      DOUBLE PRECISION      RPD
      !>C
      !>C
      !>C     Local parameters
      !>C
      !>      INTEGER               FILSIZ
      !>      PARAMETER           ( FILSIZ = 255 )
      !>
      !>      INTEGER               NLAT
      !>      PARAMETER           ( NLAT   = 9 )
      !>
      !>      INTEGER               NLON
      !>      PARAMETER           ( NLON   = 9 )
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      DOUBLE PRECISION      TOL
      !>      PARAMETER           ( TOL   =  1.D-12 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(FILSIZ)    DSK
      !>
      !>      DOUBLE PRECISION      DSKDSC ( DSKDSZ )
      !>      DOUBLE PRECISION      LAT
      !>      DOUBLE PRECISION      LON
      !>      DOUBLE PRECISION      MAXR
      !>      DOUBLE PRECISION      R
      !>      DOUBLE PRECISION      RAYDIR ( 3 )
      !>      DOUBLE PRECISION      VERTEX ( 3 )
      !>      DOUBLE PRECISION      XLAT
      !>      DOUBLE PRECISION      XLON
      !>      DOUBLE PRECISION      XPT    ( 3 )
      !>      DOUBLE PRECISION      XR
      !>
      !>      INTEGER               DLADSC ( DLADSZ )
      !>      INTEGER               HANDLE
      !>      INTEGER               I
      !>      INTEGER               J
      !>      INTEGER               PLID
      !>
      !>      LOGICAL               FOUND
      !>
      !>C
      !>C     Prompt for the name of the DSK to read.
      !>C
      !>      CALL PROMPT ( 'Enter DSK name > ', DSK )
      !>C
      !>C     Open the DSK file for read access.
      !>C     We use the DAS-level interface for
      !>C     this function.
      !>C
      !>      CALL DASOPR ( DSK, HANDLE )
      !>C
      !>C     Begin a forward search through the
      !>C     kernel, treating the file as a DLA.
      !>C     In this example, it's a very short
      !>C     search.
      !>C
      !>      CALL DLABFS ( HANDLE, DLADSC, FOUND )
      !>
      !>      IF ( .NOT. FOUND ) THEN
      !>C
      !>C        We arrive here only if the kernel
      !>C        contains no segments.  This is
      !>C        unexpected, but we're prepared for it.
      !>C
      !>         CALL SETMSG ( 'No segments found '
      !>     .   //            'in DSK file #.'    )
      !>         CALL ERRCH  ( '#',  DSK           )
      !>         CALL SIGERR ( 'SPICE(NODATA)'     )
      !>
      !>      END IF
      !>
      !>C
      !>C     If we made it this far, DLADSC is the
      !>C     DLA descriptor of the first segment.
      !>C
      !>C     We're going to generate the intercept points
      !>C     using a set of rays which point toward the
      !>C     origin and whose vertices are on a
      !>C     specified lat/lon grid.  To start out we
      !>C     must pick a reasonable range from the origin
      !>C     for the vertices:  the range must be large
      !>C     enough so that the vertices are guaranteed
      !>C     to be outside the target body but small
      !>C     enough that we don't lose too much precision
      !>C     in the surface intercept computation.
      !>C
      !>C     We'll look up the upper bound for the target
      !>C     radius, then use 2 times this value as the
      !>C     vertex magnitude.
      !>C
      !>      CALL DSKGD ( HANDLE, DLADSC, DSKDSC )
      !>
      !>      MAXR = DSKDSC(MX3IDX)
      !>      R    = 2.D0 * MAXR
      !>
      !>C
      !>C     Now generate the intercept points.  We generate
      !>C     intercepts along latitude bounds, working from
      !>C     north to south. Latitude ranges from +80 to
      !>C     -80 degrees. Longitude ranges from 0 to 320
      !>C     degrees. The increment is 20 degrees for
      !>C     latitude and 40 degrees for longitude.
      !>C
      !>      DO I = 1, NLAT
      !>
      !>         LAT = RPD() * ( 100.D0 - 20.D0*I )
      !>
      !>         DO J = 1, NLON
      !>
      !>            LON = RPD() * 40.D0 * (J-1)
      !>C
      !>C           Produce a ray vertex for the current
      !>C           lat/lon value.  Negate the vertex to
      !>C           produce the ray's direction vector.
      !>C
      !>            CALL LATREC ( R, LON, LAT, VERTEX )
      !>            CALL VMINUS ( VERTEX,      RAYDIR )
      !>C
      !>C           Find the surface intercept for this
      !>C           ray.
      !>C
      !>            CALL DSKX02 ( HANDLE, DLADSC, VERTEX,
      !>     .                    RAYDIR, PLID,   XPT,    FOUND  )
      !>C
      !>C           Since the ray passes through the origin on
      !>C           the body-fixed frame associated with the
      !>C           target body, we'd rarely expect to find that
      !>C           the ray failed to intersect the surface.
      !>C           For safety, we check the FOUND flag.  (A
      !>C           "not found" condition could be a sign of
      !>C           a bug.)
      !>C
      !>            IF ( .NOT. FOUND ) THEN
      !>
      !>               WRITE(*,*) ' '
      !>               WRITE(*,*) 'Intercept not found!'
      !>               WRITE(*,*) '   Ray vertex:'
      !>               WRITE(*,*) '   Longitude (deg): ', LON/RPD()
      !>               WRITE(*,*) '   Latitude  (deg): ', LAT/RPD()
      !>               WRITE(*,*) '   Range      (km): ', R
      !>               WRITE(*,*) ' '
      !>
      !>            ELSE
      !>C
      !>C              This is the normal case.  Display the
      !>C              intercept plate ID and the intercept
      !>C              point in both Cartesian and latitudinal
      !>C              coordinates.  Show the corresponding ray
      !>C              vertex to facilitate validation of results.
      !>C
      !>C              Use RECRAD rather than RECLAT to produce
      !>C              non-negative longitudes.
      !>C
      !>               CALL RECRAD ( XPT, XR, XLON, XLAT )
      !>
      !>               WRITE(*,*) ' '
      !>               WRITE(*,*) 'Intercept found:'
      !>               WRITE(*,*) '   Plate ID:             ', PLID
      !>               WRITE(*, '(1X,A,3F12.8)' )
      !>     .         '   Cartesian coordinates:', XPT
      !>               WRITE(*,*) '   Latitudinal coordinates:'
      !>               WRITE(*,*) '   Longitude (deg): ', XLON/RPD()
      !>               WRITE(*,*) '   Latitude  (deg): ', XLAT/RPD()
      !>               WRITE(*,*) '   Range      (km): ', XR
      !>               WRITE(*,*)
      !>               WRITE(*,*) '   Ray vertex:'
      !>               WRITE(*,*) '   Longitude (deg): ', LON/RPD()
      !>               WRITE(*,*) '   Latitude  (deg): ', LAT/RPD()
      !>               WRITE(*,*) '   Range      (km): ', R
      !>               WRITE(*,*) ' '
      !>
      !>            END IF
      !>
      !>         END DO
      !>
      !>      END DO
      !>C
      !>C     Close the kernel.  This isn't necessary in a stand-
      !>C     alone program, but it's good practice in subroutines
      !>C     because it frees program and system resources.
      !>C
      !>      CALL DASCLS ( HANDLE )
      !>      END
      !>```
      !>
