      !>
      !>```fortran
      !>      PROGRAM TANGPT_EX3
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Parameters
      !>C
      !>      CHARACTER*(*)         FMT1F3
      !>      PARAMETER           ( FMT1F3  = '(1X,A,F14.3)' )
      !>
      !>      CHARACTER*(*)         FMT3F3
      !>      PARAMETER           ( FMT3F3  = '(1X,A,3F14.3)' )
      !>
      !>      CHARACTER*(*)         FMT1F6
      !>      PARAMETER           ( FMT1F6  = '(1X,A,F14.6)' )
      !>
      !>      CHARACTER*(*)         FMTMF3
      !>      PARAMETER           ( FMTMF3 = '(1X,A,2F13.3,F10.3)' )
      !>
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'tangpt_ex3.tm' )
      !>
      !>      CHARACTER*(*)         TIMFMT
      !>      PARAMETER           ( TIMFMT =
      !>     .          'YYYY-MM-DD HR:MN:SC.###### UTC ::RND' )
      !>
      !>      INTEGER               BDNMLN
      !>      PARAMETER           ( BDNMLN = 36 )
      !>
      !>      INTEGER               CORLEN
      !>      PARAMETER           ( CORLEN = 10 )
      !>
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>      INTEGER               LOCLEN
      !>      PARAMETER           ( LOCLEN = 25 )
      !>
      !>      INTEGER               NCASE
      !>      PARAMETER           ( NCASE  =  5 )
      !>
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 35 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(CORLEN)    ABCORR
      !>      CHARACTER*(CORLEN)    CORRS  ( NCASE )
      !>      CHARACTER*(FRNMLN)    FIXREF
      !>      CHARACTER*(LOCLEN)    LOCI   ( NCASE )
      !>      CHARACTER*(LOCLEN)    LOCUS
      !>      CHARACTER*(BDNMLN)    OBSRVR
      !>      CHARACTER*(FRNMLN)    RAYFRM
      !>      CHARACTER*(BDNMLN)    SC
      !>      CHARACTER*(BDNMLN)    TARGET
      !>      CHARACTER*(TIMLEN)    TIMSTR
      !>      CHARACTER*(TIMLEN)    UTCTIM
      !>
      !>      DOUBLE PRECISION      ALT
      !>      DOUBLE PRECISION      DIFF   ( 3 )
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      RANGE
      !>      DOUBLE PRECISION      RAYDIR ( 3 )
      !>      DOUBLE PRECISION      RAYLT
      !>      DOUBLE PRECISION      SRFPT  ( 3 )
      !>      DOUBLE PRECISION      SRFVEC ( 3 )
      !>      DOUBLE PRECISION      SVALT
      !>      DOUBLE PRECISION      SVEPOC
      !>      DOUBLE PRECISION      SVRANG
      !>      DOUBLE PRECISION      SVSRFP ( 3 )
      !>      DOUBLE PRECISION      SVSRFV ( 3 )
      !>      DOUBLE PRECISION      SVTANP ( 3 )
      !>      DOUBLE PRECISION      TANPT  ( 3 )
      !>      DOUBLE PRECISION      TRGEPC
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Initial values
      !>C
      !>      DATA                  CORRS  / 'CN+S', 'XCN+S',
      !>     .                               'CN',   'NONE',
      !>     .                               'CN+S'          /
      !>
      !>      DATA                  LOCI   / 'TANGENT POINT',
      !>     .                               'TANGENT POINT',
      !>     .                               'TANGENT POINT',
      !>     .                               'TANGENT POINT',
      !>     .                               'SURFACE POINT'  /
      !>
      !>      DATA                  UTCTIM /
      !>     .              '2020-12-30 00:00:00 UTC'  /
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( META )
      !>
      !>C
      !>C     Set name of spacecraft used to define ray direction.
      !>C
      !>      SC = 'MRO'
      !>
      !>C
      !>C     Initialize inputs to TANGPT that are common to all
      !>C     cases.
      !>C
      !>      TARGET = 'MARS'
      !>      OBSRVR = 'DSS-14'
      !>      FIXREF = 'IAU_MARS'
      !>      RAYFRM = 'J2000'
      !>
      !>C
      !>C     Convert observation time to TDB seconds past J2000.
      !>C
      !>      CALL STR2ET ( UTCTIM, ET )
      !>
      !>C
      !>C     Generate ray direction vector. Use apparent position
      !>C     of the MRO spacecraft.
      !>C
      !>      CALL SPKPOS ( SC,     ET,     RAYFRM,
      !>     .              'CN+S', OBSRVR, RAYDIR, RAYLT )
      !>
      !>      WRITE(*,*) ' '
      !>      WRITE( *, '(A)') 'Observer:   ' // OBSRVR
      !>      WRITE( *, '(A)') 'Target:     ' // TARGET
      !>      WRITE( *, '(A)') 'Spacecraft: ' // SC
      !>
      !>C
      !>C     Compute the apparent tangent point for each case.
      !>C
      !>      DO I = 1, NCASE
      !>
      !>         WRITE(*,*) ' '
      !>
      !>         ABCORR = CORRS(I)
      !>         LOCUS  = LOCI(I)
      !>
      !>         WRITE(*, '(A)') 'Aberration correction:       '
      !>     .   //               ABCORR
      !>
      !>         WRITE(*, '(A)') 'Aberration correction locus: '
      !>     .   //               LOCUS
      !>
      !>         WRITE(*,*) ' '
      !>
      !>C
      !>C        Compute tangent point.
      !>C
      !>         CALL TANGPT ( 'ELLIPSOID',
      !>     .                 TARGET, ET,     FIXREF, ABCORR,
      !>     .                 LOCUS,  OBSRVR, RAYFRM, RAYDIR,
      !>     .                 TANPT,  ALT,    RANGE,  SRFPT,
      !>     .                 TRGEPC, SRFVEC                 )
      !>
      !>C
      !>C        Convert the target epoch to a string for output.
      !>C
      !>         CALL TIMOUT ( TRGEPC, TIMFMT, TIMSTR )
      !>
      !>         WRITE(*, '(A)') '  Observation Time = '
      !>     .   //               UTCTIM
      !>
      !>         WRITE(*, '(A)') '  Target Time      = '
      !>     .   //                 TIMSTR
      !>
      !>         WRITE(*, FMT1F3) '   ALT    (km) = ', ALT
      !>         WRITE(*, FMT1F3) '   RANGE  (km) = ', RANGE
      !>         WRITE(*, FMT3F3) '   TANPT  (km) = ', TANPT
      !>         WRITE(*, FMT3F3) '   SRFPT  (km) = ', SRFPT
      !>         WRITE(*, FMT3F3) '   SRFVEC (km) = ', SRFVEC
      !>
      !>         IF ( I .EQ. 1 ) THEN
      !>C
      !>C           Save results for comparison.
      !>C
      !>            SVALT  = ALT
      !>            SVEPOC = TRGEPC
      !>            SVRANG = RANGE
      !>            CALL VEQU( TANPT,  SVTANP )
      !>            CALL VEQU( SRFPT,  SVSRFP )
      !>            CALL VEQU( SRFVEC, SVSRFV )
      !>
      !>         ELSE
      !>C
      !>C           Compare results to CN+S, tangent point
      !>C           locus case.
      !>C
      !>            WRITE(*,*) ' '
      !>
      !>            WRITE(*, '(A)')
      !>     .      '  Differences from case 1 outputs:'
      !>
      !>            WRITE(*, FMT1F6)
      !>     .      '   Target time delta (s) = ',
      !>     .      TRGEPC - SVEPOC
      !>
      !>            WRITE(*, FMTMF3)
      !>     .      '   ALT    delta (km) = ', ALT - SVALT
      !>
      !>            WRITE(*, FMTMF3)
      !>     .      '   RANGE  delta (km) = ', RANGE - SVRANG
      !>
      !>            CALL VSUB   ( TANPT, SVTANP, DIFF )
      !>            WRITE(*, FMTMF3)
      !>     .      '   TANPT  delta (km) = ', DIFF
      !>
      !>            CALL VSUB   ( SRFPT, SVSRFP, DIFF )
      !>            WRITE(*, FMTMF3)
      !>     .      '   SRFPT  delta (km) = ', DIFF
      !>
      !>            CALL VSUB   ( SRFVEC, SVSRFV, DIFF )
      !>            WRITE(*, FMTMF3)
      !>     .      '   SRFVEC delta (km) = ', DIFF
      !>
      !>         END IF
      !>
      !>         WRITE(*,*) ' '
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a PC/Linux/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        Observer:   DSS-14
      !>        Target:     MARS
      !>        Spacecraft: MRO
      !>
      !>        Aberration correction:       CN+S
      !>        Aberration correction locus: TANGENT POINT
      !>
      !>          Observation Time = 2020-12-30 00:00:00 UTC
      !>          Target Time      = 2020-12-29 23:52:40.613204 UTC
      !>            ALT    (km) =        140.295
      !>            RANGE  (km) =  131724847.608
      !>            TANPT  (km) =       1351.574      1182.155     -3029.495
      !>            SRFPT  (km) =       1298.181      1135.455     -2908.454
      !>            SRFVEC (km) =  121233989.354  -5994858.328  51164606.676
      !>
      !>        Aberration correction:       XCN+S
      !>        Aberration correction locus: TANGENT POINT
      !>
      !>          Observation Time = 2020-12-30 00:00:00 UTC
      !>          Target Time      = 2020-12-30 00:07:19.347692 UTC
      !>            ALT    (km) =       4921.539
      !>            RANGE  (km) =  131713124.520
      !>            TANPT  (km) =       -413.404     -8220.856     -1193.471
      !>            SRFPT  (km) =       -168.808     -3356.879      -483.938
      !>            SRFVEC (km) =  120615301.766 -13523495.083  51160641.665
      !>
      !>          Differences from case 1 outputs:
      !>            Target time delta (s) =     878.734488
      !>            ALT    delta (km) =      4781.244
      !>            RANGE  delta (km) =    -11723.089
      !>            TANPT  delta (km) =     -1764.978    -9403.011  1836.024
      !>            SRFPT  delta (km) =     -1466.989    -4492.334  2424.517
      !>            SRFVEC delta (km) =   -618687.588 -7528636.755 -3965.012
      !>
      !>        Aberration correction:       CN
      !>        Aberration correction locus: TANGENT POINT
      !>
      !>          Observation Time = 2020-12-30 00:00:00 UTC
      !>          Target Time      = 2020-12-29 23:52:40.613219 UTC
      !>            ALT    (km) =       3409.162
      !>            RANGE  (km) =  131724843.177
      !>            TANPT  (km) =       1933.641      5183.696     -3951.091
      !>            SRFPT  (km) =        965.945      2589.501     -1962.095
      !>            SRFVEC (km) =  121233070.966  -5997405.747  51166472.910
      !>
      !>          Differences from case 1 outputs:
      !>            Target time delta (s) =       0.000015
      !>            ALT    delta (km) =      3268.868
      !>            RANGE  delta (km) =        -4.431
      !>            TANPT  delta (km) =       582.067     4001.541  -921.596
      !>            SRFPT  delta (km) =      -332.236     1454.046   946.360
      !>            SRFVEC delta (km) =      -918.388    -2547.420  1866.234
      !>
      !>        Aberration correction:       NONE
      !>        Aberration correction locus: TANGENT POINT
      !>
      !>          Observation Time = 2020-12-30 00:00:00 UTC
      !>          Target Time      = 2020-12-30 00:00:00.000000 UTC
      !>            ALT    (km) =        781.382
      !>            RANGE  (km) =  131718986.013
      !>            TANPT  (km) =        615.190     -3545.867     -2111.285
      !>            SRFPT  (km) =        500.266     -2883.463     -1713.075
      !>            SRFVEC (km) =  120983074.323  -9765994.151  51162607.074
      !>
      !>          Differences from case 1 outputs:
      !>            Target time delta (s) =     439.386796
      !>            ALT    delta (km) =       641.087
      !>            RANGE  delta (km) =     -5861.595
      !>            TANPT  delta (km) =      -736.384    -4728.022   918.210
      !>            SRFPT  delta (km) =      -797.915    -4018.919  1195.379
      !>            SRFVEC delta (km) =   -250915.031 -3771135.823 -1999.603
      !>
      !>        Aberration correction:       CN+S
      !>        Aberration correction locus: SURFACE POINT
      !>
      !>          Observation Time = 2020-12-30 00:00:00 UTC
      !>          Target Time      = 2020-12-29 23:52:40.613204 UTC
      !>            ALT    (km) =        140.308
      !>            RANGE  (km) =  131724847.611
      !>            TANPT  (km) =       1351.579      1182.159     -3029.507
      !>            SRFPT  (km) =       1298.181      1135.455     -2908.454
      !>            SRFVEC (km) =  121233989.351  -5994858.332  51164606.689
      !>
      !>          Differences from case 1 outputs:
      !>            Target time delta (s) =       0.000000
      !>            ALT    delta (km) =         0.013
      !>            RANGE  delta (km) =         0.003
      !>            TANPT  delta (km) =         0.005        0.004    -0.012
      !>            SRFPT  delta (km) =        -0.000        0.000     0.000
      !>            SRFVEC delta (km) =        -0.003       -0.005     0.013
      !>
      !>## Restrictions
      !>
      !>     1)  This routine is applicable only to computations for which
      !>         radiation paths can be modeled as straight lines.
      !>
      !>     2)  This routine does not account for differential aberration
      !>         corrections across the target body surface: when aberration
      !>         corrections are used, the entire target ellipsoid's position
      !>         and orientation are modified by the corrections that apply at
      !>         the aberration correction locus.
      !>
      !>     3)  A cautionary note: if aberration corrections are used, and if
      !>         DREF is the target body-fixed frame, the epoch at which that
      !>         frame is evaluated is offset from ET by the light time
      !>         between the observer and the *center* of the target body.
      !>         This light time normally will differ from the light time
      !>         between the observer and the tangent or surface point.
      !>         Consequently the orientation of the target body-fixed frame
      !>         at TRGEPC will not match that of the target body-fixed frame
      !>         at the epoch associated with DREF. As a result, various
      !>         derived quantities may not be as expected: for example,
      !>         SRFVEC would not be parallel to DVEC.
      !>
      !>         In many applications the errors arising from this frame
      !>         discrepancy may be insignificant; however a safe approach is
      !>         to always use as DREF a frame other than the target
      !>         body-fixed frame.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     M. Costa Sitja     (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 20-OCT-2021 (NJB) (MCS)
      module subroutine tangpt ( ctx, method, target, et, fixref, abcorr, corloc, obsrvr, dref, dvec, tanpt, alt, range, srfpt, trgepc, srfvec )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: clight
      use pepper_math, only: mtxv, mxv, vdist, vdot, vnorm, vrel
      use pepper_strings, only: eqstr, ljucrs
      use pepper_inc_frmtyp, frmtyp_all => all  ! PEPPER: ALL (unused) would hide the intrinsic
      use pepper_inc_zzabcorr
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: method  !! Computation method.
      character(*), intent(in) :: target  !! Name of target body.
      real(wp), intent(in) :: et  !! Epoch in ephemeris seconds past J2000 TDB.
      character(*), intent(in) :: fixref  !! Body-fixed, body-centered target body frame.
      character(*), intent(in) :: abcorr  !! Aberration correction.
      character(*), intent(in) :: corloc  !! Aberration correction locus: 'TANGENT POINT' or 'SURFACE POINT'.
      character(*), intent(in) :: obsrvr  !! Name of observing body.
      character(*), intent(in) :: dref  !! Reference frame of ray direction vector.
      real(wp), intent(in) :: dvec   ( 3 )  !! Ray direction vector.
      real(wp), intent(out) :: tanpt  ( 3 )  !! "Tangent point": point on ray nearest to surface.
      real(wp), intent(out) :: alt  !! Altitude of tangent point above surface.
      real(wp), intent(out) :: range  !! Distance of tangent point from observer.
      real(wp), intent(out) :: srfpt  ( 3 )  !! Point on surface nearest to tangent point.
      real(wp), intent(out) :: trgepc  !! Epoch associated with correction locus.
      real(wp), intent(out) :: srfvec ( 3 )  !! Vector from observer to surface point SRFPT.
      real(wp), parameter :: cnvlim = 1.0e-16_wp
      integer(ip), parameter :: mxcvit = 10
      integer(ip), parameter :: mxncit = 3
      integer(ip), parameter :: loclen = 15
      character(loclen) :: locstr
      real(wp) :: ctrpos ( 3 )
      real(wp) :: dist
      real(wp) :: dval
      real(wp) :: epcdif
      real(wp) :: fixdir ( 3 )
      real(wp) :: fixobs ( 3 )
      real(wp) :: j2dir  ( 3 )
      real(wp) :: j2fixm ( 3, 3 )
      real(wp) :: j2lcus ( 3 )
      real(wp) :: j2lpos ( 3 )
      real(wp) :: j2opos ( 3 )
      real(wp) :: j2tpos ( 3 )
      real(wp) :: lt
      real(wp) :: ltcent
      real(wp) :: ltdiff
      real(wp) :: p      ( 3 )
      real(wp) :: prevlt
      real(wp) :: prvepc
      real(wp) :: prvsrf ( 3 )
      real(wp) :: prvtan ( 3 )
      real(wp) :: r2jmat ( 3, 3 )
      real(wp) :: refepc
      real(wp) :: s
      real(wp) :: ssbost ( 6 )
      real(wp) :: ssbtst ( 6 )
      real(wp) :: stlfix ( 3 )
      real(wp) :: stlloc ( 3 )
      real(wp) :: stlobs ( 3 )
      real(wp) :: stloff ( 3 )
      real(wp) :: tanoff ( 3 )
      real(wp) :: tpos   ( 3 )
      real(wp) :: trgpos ( 3 )
      integer(ip) :: dcentr
      integer(ip) :: dclass
      integer(ip) :: dfrcde
      integer(ip) :: dtypid
      integer(ip) :: fxcent
      integer(ip) :: fxclss
      integer(ip) :: fxfcde
      integer(ip) :: fxtyid
      integer(ip) :: i
      integer(ip) :: nitr
      integer(ip) :: obscde
      integer(ip) :: trgcde
      logical :: attblk ( nabcor )
      logical :: fnd
      logical :: ltcnv
      logical :: stlcnv
      if ( .not. allocated ( ctx%tangpt_state ) ) allocate ( ctx%tangpt_state )
      associate ( first => ctx%tangpt_state%first, &
                  prvcor => ctx%tangpt_state%prvcor, &
                  prvloc => ctx%tangpt_state%prvloc, &
                  prvtcd => ctx%tangpt_state%prvtcd, &
                  tanloc => ctx%tangpt_state%tanloc, &
                  usecn => ctx%tangpt_state%usecn, &
                  uselt => ctx%tangpt_state%uselt, &
                  usestl => ctx%tangpt_state%usestl, &
                  xmit => ctx%tangpt_state%xmit, &
                  svctr1 => ctx%tangpt_state%svctr1, &
                  svtarg => ctx%tangpt_state%svtarg, &
                  svtcde => ctx%tangpt_state%svtcde, &
                  svfnd1 => ctx%tangpt_state%svfnd1, &
                  svctr2 => ctx%tangpt_state%svctr2, &
                  svobsr => ctx%tangpt_state%svobsr, &
                  svobsc => ctx%tangpt_state%svobsc, &
                  svfnd2 => ctx%tangpt_state%svfnd2, &
                  svctr3 => ctx%tangpt_state%svctr3, &
                  svfref => ctx%tangpt_state%svfref, &
                  svfxfc => ctx%tangpt_state%svfxfc, &
                  svctr4 => ctx%tangpt_state%svctr4, &
                  svdref => ctx%tangpt_state%svdref, &
                  svdfrc => ctx%tangpt_state%svdfrc, &
                  svctr5 => ctx%tangpt_state%svctr5, &
                  svradi => ctx%tangpt_state%svradi, &
                  svnrad => ctx%tangpt_state%svnrad )
      if ( ctx%failed() ) return

!
!     Counter initialization is done separately.
!
      if ( first ) then
!
!        Initialize counters.
!
         call zzctruin( ctx, svctr1 )
         call zzctruin( ctx, svctr2 )
         call zzctruin( ctx, svctr3 )
         call zzctruin( ctx, svctr4 )
         call zzctruin( ctx, svctr5 )
!
!        To be used if DSK shapes are supported:
!
!         CALL ZZCTRUIN( SVCTR6 )

      end if

!
!     Parse the aberration correction specifier, if it's new.
!
      if (  first  .or.  ( abcorr /= prvcor )  ) then
!
!        PRVCOR is updated only when a valid correction has been
!        recognized. PRVCOR is blank on the first pass; afterward
!        it is always valid.
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any. Analyze the new flag.
!
         call zzvalcor ( ctx, abcorr, attblk )

         if ( ctx%failed() ) return
!
!        Set logical flags indicating the attributes of the requested
!        correction:
!
!           XMIT is .TRUE. when the correction is for transmitted
!           radiation.
!
!           USELT is .TRUE. when any type of light time correction
!           (normal or converged Newtonian) is specified.
!
!           USECN indicates converged Newtonian light time correction.
!
!           USESTL indicates stellar aberration corrections.
!
!        The above definitions are consistent with those used by
!        ZZVALCOR.
!
         xmit    =  attblk ( xmtidx )
         uselt   =  attblk ( ltidx  )
         usecn   =  attblk ( cnvidx )
         usestl  =  attblk ( stlidx )

!
!        The aberration correction flag is valid; save it.
!
         prvcor = abcorr

!
!        FIRST will be set to .FALSE. later, after all first-pass
!        actions have been performed.
!
      end if

!
!     Get the sign S prefixing LT in the expression for TRGEPC.
!     When light time correction is not used, setting S = 0
!     allows us to seamlessly set TRGEPC equal to ET.
!
      if ( uselt ) then

         if ( xmit ) then
            s   =  1.0_wp
         else
            s   = -1.0_wp
         end if

      else
         s = 0.0_wp
      end if

!
!     The method cannot be anything other than 'ELLIPSOID'.
!
      if ( .not. eqstr( method, 'ELLIPSOID') ) then

         call ctx%setmsg ( 'Method is currently restricted to ' &
         //            'ELLIPSOID, but input value was #.' )
         call ctx%errch  ( '#', method                         )
         call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'               )
         return

      end if

!
!     Code from this point onward assumes the target shape is modeled
!     as a triaxial ellipsoid.
!
!     If we're using aberration corrections, the aberration correction
!     locus must be equivalent to one of 'TANGENT POINT' or 'SURFACE
!     POINT'. TANLOC is set to .TRUE. if and only if the locus is the
!     tangent point.
!
      if (  first  .or.  ( corloc /= prvloc )  ) then
!
!        Left justify the input locus string, convert to upper case,
!        and compress all embedded blanks for comparison.
!
         call ljucrs ( 0, corloc, locstr )

         if ( locstr == 'TANGENTPOINT' ) then

            tanloc = .true.

         else if ( locstr == 'SURFACEPOINT' ) then

            tanloc = .false.

         else

            call ctx%setmsg ( 'Aberration correction locus must be one ' &
            //            'of TANGENT POINT or SURFACE POINT but ' &
            //            'was #.'                                  )
            call ctx%errch  ( '#', corloc                               )
            call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                     )
            return

         end if

!
!        At this point we have a valid locus. TANLOC is set.
!        Save the input locus string so we can check for
!        a change on the next call.
!
         prvloc = corloc

      end if

!
!     Check for a zero ray direction vector.
!
      if ( all(dvec == 0.0_wp) ) then

         call ctx%setmsg ( 'Input ray direction was the zero ' &
         //            'vector; this vector must be non-zero.' )
         call ctx%sigerr ( 'SPICE(ZEROVECTOR)'                     )
         return

      end if

!
!     Obtain integer codes for the target and observer.
!
      call zzbods2c ( ctx, svctr1, svtarg, svtcde, svfnd1, &
                      target, trgcde, fnd    )

      if ( ctx%failed() ) return

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The target, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit, or that you ' &
         //            'failed to load a kernel containing a ' &
         //            'name-ID mapping for this body.'           )
         call ctx%errch  ( '#', target                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

      call zzbods2c ( ctx, svctr2, svobsr, svobsc, svfnd2, &
                      obsrvr, obscde, fnd    )

      if ( ctx%failed() ) return

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The observer, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit, or that you ' &
         //            'failed to load a kernel containing a ' &
         //            'name-ID mapping for this body.'           )
         call ctx%errch  ( '#', obsrvr                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     Check the input body codes. If they are equal, signal
!     an error.
!
      if ( obscde == trgcde ) then

         call ctx%setmsg ( 'The observing body and target body are the ' &
         //            'same. Both are #.'                          )
         call ctx%errch  ( '#',  obsrvr                                 )
         call ctx%sigerr ( 'SPICE(BODIESNOTDISTINCT)'                   )
         return

      end if

!
!     Get the target body's ellipsoid radii.
!
      if (  first  .or.  ( trgcde /= prvtcd )  ) then
!
!        This the first pass, or else the target body has changed. We
!        need to get radii for the new target body.
!
!        Re-initialize the counter used to detect changes to the target
!        body radii.
!
         call zzctruin( ctx, svctr5 )

         prvtcd = trgcde

      end if

      call zzbodvcd ( ctx, trgcde, 'RADII', 3, svctr5, svnrad, svradi )

      if ( ctx%failed() ) return

      if ( svnrad /= 3 ) then

         call ctx%setmsg ( 'Number of radii associated with target ' &
         //            'body # is #; number must be 3.'         )
         call ctx%errch  ( '#',  target                             )
         call ctx%errint ( '#',  svnrad                             )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                    )
         return

      end if

!
!     At this point, we've performed all first-pass actions.
!
      first = .false.

!
!     Determine the attributes of the frame designated by FIXREF.
!
      call zznamfrm ( ctx, svctr3, svfref, svfxfc, fixref, fxfcde )

      call frinfo ( ctx, fxfcde, fxcent, fxclss, fxtyid, fnd )

      if ( ctx%failed() ) return

      if ( .not. fnd ) then

         call ctx%setmsg ( 'Reference frame # is not recognized by ' &
         //            'the SPICE frame subsystem. Possibly ' &
         //            'a required frame definition kernel has ' &
         //            'not been loaded.'                        )
         call ctx%errch  ( '#',  fixref                              )
         call ctx%sigerr ( 'SPICE(NOFRAME)'                          )
         return

      end if

!
!     Make sure that FIXREF is centered at the target body's center.
!
      if ( fxcent /= trgcde ) then

         call ctx%setmsg ( 'Reference frame # is not centered at the ' &
         //            'target body #. The ID code of the frame ' &
         //            'center is #.'                             )
         call ctx%errch  ( '#',  fixref                               )
         call ctx%errch  ( '#',  target                               )
         call ctx%errint ( '#',  fxcent                               )
         call ctx%sigerr ( 'SPICE(INVALIDFRAME)'                      )
         return

      end if

!
!     Determine the attributes of the frame designated by DREF.
!
      call zznamfrm ( ctx, svctr4, svdref, svdfrc, dref, dfrcde )

      call frinfo ( ctx, dfrcde, dcentr, dclass, dtypid, fnd )

      if ( ctx%failed() ) return

      if ( .not. fnd ) then

         call ctx%setmsg ( 'Reference frame # is not recognized by ' &
         //            'the SPICE frame subsystem. Possibly ' &
         //            'a required frame definition kernel has ' &
         //            'not been loaded.'                        )
         call ctx%errch  ( '#',  dref                                )
         call ctx%sigerr ( 'SPICE(NOFRAME)'                          )
         return

      end if

!
!     Get the position of the target relative to the observer. If
!     light time corrections are used, this gives us an initial
!     light time estimate and initial target epoch.
!
      call spkpos ( ctx, target, et, fixref, abcorr, obsrvr, tpos, lt )

      if ( ctx%failed() ) return

      if ( all(tpos == 0.0_wp) ) then

         call ctx%setmsg ( 'Observer # and target # have distinct ' &
         //            'ID codes but the distance between these ' &
         //            'objects is zero.'                        )
         call ctx%errch  ( '#',  obsrvr                              )
         call ctx%errch  ( '#',  target                              )
         call ctx%sigerr ( 'SPICE(NOSEPARATION)'                     )
         return

      end if

!
!     Negate the target's position to obtain the position of the
!     observer relative to the target.
!
      fixobs = -tpos

!
!     Now we can check whether the observer is inside the ellipsoid.
!     Find the point on the ellipsoid that lies on the line between
!     FIXOBS and the ellipsoid's center.
!
      call edpnt ( ctx, fixobs, svradi(1), svradi(2), svradi(3), p )

      if ( ctx%failed() ) return

      if ( vnorm(p) >= vnorm(fixobs) ) then

         call ctx%setmsg ( 'Observer # is inside ellipsoid representing ' &
         //            'target body # shape.'   )
         call ctx%errch  ( '#', obsrvr              )
         call ctx%errch  ( '#', target              )
         call ctx%sigerr ( 'SPICE(INVALIDGEOMETRY)' )
         return

      end if

!
!     The target epoch is dependent on the aberration correction. The
!     coefficient S has been set to give us the correct answer for each
!     case.
!
      trgepc = et  +  s*lt

!
!     Transform the direction vector from frame DREF to the body-fixed
!     frame associated with the target. The epoch TRGEPC associated
!     with the body-fixed frame has been set already.
!
!     We'll compute the transformation in two parts: first
!     from frame DREF to J2000, then from J2000 to the target
!     frame.
!
!     The orientation of the ray's frame is evaluated at ET in any
!     of the following situations:
!
!        - The frame is inertial
!        - Light time corrections are not used
!        - The frame is centered at the observer
!
!     Let REFEPC be the epoch of participation of the observer.
!
      if (      ( dclass ==  inertl ) &
           .or. ( dcentr ==  obscde ) &
           .or. (        .not. uselt  )  ) then

         refepc = et

      else
!
!        The epoch at which the orientation of ray frame is evaluated
!        is the epoch of participation of the center of that frame.
!
!        Find the light time from the observer to the center of
!        frame DREF.
!
         call spkezp ( ctx, dcentr, et,     'J2000', abcorr, &
                       obscde, ctrpos, ltcent          )

         if ( ctx%failed() ) return

         refepc  =  et  +  s * ltcent

      end if

!
!     The epoch REFEPC associated with frame DREF has been set.
!
!     Compute the ray direction in the J2000 frame.
!
      if ( dfrcde == j2code ) then

         j2dir = dvec

      else

         call refchg ( ctx, dfrcde, j2code, refepc, r2jmat )

         if ( ctx%failed() ) return

         call mxv ( r2jmat, dvec, j2dir )

      end if

!
!     Now transform the ray direction from the J2000 frame to the
!     target body-fixed frame at TRGEPC.
!
      call refchg ( ctx, j2code, fxfcde, trgepc, j2fixm )

      if ( ctx%failed() ) return

      call mxv ( j2fixm, j2dir, fixdir )

!
!     We have all the inputs needed to make initial estimates of
!     our outputs.
!
      call npedln ( ctx, svradi(1), svradi(2), svradi(3), &
                    fixobs,    fixdir,    srfpt,    alt )

      if ( ctx%failed() ) return

!
!     Compute the observer-to-surface point vector for the initial
!     estimated solution.
!
      srfvec = srfpt - fixobs

!
!     Now compute the tangent point.
!
!     Start by finding the nearest point to SRFPT on the line
!     containing the input ray. Note that although we're setting the
!     value of the outputs TANPT here, we're not done yet.
!
!     We retain the altitude found by NPEDLN, since the following
!     call can introduce round-off error in the intercept case.
!
      call nplnpt ( ctx, fixobs, fixdir, srfpt, tanpt, dval )

!
!     Note that TANPT might not be valid here, if we're in the look-
!     away case. We'll deal with this case below.
!
!     A SPICE error should not be possible here but we check anyway
!     for safety.
!
      if ( ctx%failed() ) return

      if ( .not. uselt ) then
!
!        Aberration corrections are not used.
!
         trgepc = et

!
!        If TANPT is on or behind the ray's vertex, reset TANPT to be
!        the vertex, and set the range to zero. Reset the surface point
!        SRFPT to the nearest point on the target to the observer, and
!        set ALT to the altitude of the observer with respect to that
!        point.
!
!        Note that if aberration corrections were used, then the test
!        for the ray pointing away from the target could give a
!        different result. We handle that case separately later on.
!
         tanoff = tanpt - fixobs

         if ( vdot( tanoff, fixdir ) <= 0.0_wp ) then
!
!           TANPT is on or behind the ray's vertex.
!
            tanpt = fixobs
            range = 0.0_wp

            call nearpt ( ctx, fixobs, svradi(1), svradi(2), svradi(3), &
                          srfpt,  alt                             )
            if ( ctx%failed() ) return

!
!           Compute SRFVEC using our newly computed value of SRFPT.
!
            srfvec = srfpt - fixobs

         else
!
!           The tangent point lies ahead of the observer.
!
            if ( alt == 0.0_wp ) then
!
!              This is the geometric intercept case. ALT, SRFPT, TANPT,
!              and SRFVEC are already set. To eliminate any error in
!              TANPT, we set it equal to SRFPT.
!
               tanpt = srfpt

               range = vnorm ( srfvec )

            else
!
!              This is the normal geometric case. All outputs
!              other than range are already set.
!
               range = vdist ( fixobs, tanpt )

            end if

         end if

         return

      end if

!
!     Still here? Then we are using aberration corrections. The outputs
!     we've computed serve as first estimates for converged values.
!
!     Since we're using light time corrections, we're going to make an
!     estimate of light time to the aberration correction locus, then
!     re-do our computation of the target position and orientation
!     using the new light time value.
!
!     Note that for non-converged light time, we perform several more
!     iterations. The initial light time correction was for the target
!     center.
!
      if ( usecn ) then
         nitr = mxcvit
      else
         nitr = mxncit
      end if
!
!     Compute new light time estimate and new target epoch.
!
      if ( tanloc ) then
!
!        Compute distance to the tangent point.
!
         dist = vdist ( fixobs, tanpt )

      else
!
!        Compute distance to the surface point.
!
         dist = vnorm ( srfvec )

      end if

!
!     We'll need the state of the observer relative to the solar system
!     barycenter. This state need be computed just once. The position
!     of the target relative to the solar system barycenter will need
!     to be re-computed on each loop iteration.
!
      call spkssb ( ctx, obscde, et, 'J2000', ssbost )

      if ( ctx%failed() ) return

!
!     Compute light time based on distance to the aberration correction
!     locus; compute the new target epoch based on the light time.
!
      lt     =  dist / clight
      trgepc =  et  +  s * lt

      prevlt = 0.0_wp
      prvepc = trgepc

      i      = 0
      ltdiff = 1.0_wp
      epcdif = 1.0_wp

!
!     Initialize STLCNV, the flag that indicates whether stellar
!     aberration corrections have converged.
!
      if ( usestl ) then
         stlcnv = .false.
      else
         stlcnv = .true.
      end if

!
!     Initialize LTCNV, the flag that indicates whether light time
!     corrections have converged.
!
      ltcnv  = .false.

!
!     The loop terminates if both light time and stellar aberration
!     correction have converged or if the maximum number of iterations
!     has been reached.
!
!     Light time correction convergence is indicated when either of
!     these conditions are met:
!
!         - The relative difference between successive light time
!           estimates becomes less than CNVLIM
!
!         - The target epoch doesn't change
!
!     Stellar aberration convergence is indicated when both of
!     these conditions are met:
!
!        - The relative difference between successive values of TANPT
!          becomes less than CNVLIM
!
!        - The relative difference between successive values of SRFPT
!          becomes less than CNVLIM
!
      do while (             ( i     <  nitr   ) &
                 .and. .not. ( ltcnv .and. stlcnv ) )

         if ( usestl ) then
!
!           Track the output points in order to test convergence of
!           the stellar aberration correction.
!
            prvtan = tanpt
            prvsrf = srfpt

         end if

!
!        Get the J2000-relative state of the target relative to
!        the solar system barycenter at the target epoch. The
!        observer's position doesn't change.
!
         call spkssb ( ctx, trgcde, trgepc, 'J2000', ssbtst )

         if ( ctx%failed() ) return

!
!        Convert the position of the observer relative to the solar
!        system barycenter from the J2000 frame to the target frame at
!        TRGEPC.
!
!        SSBOST contains the J2000-relative state of the observer
!        relative to the solar system barycenter at ET.
!
         j2opos = ssbost(1:3) - ssbtst(1:3)
         call pxform ( ctx, 'J2000', fixref, trgepc, j2fixm )

         if ( ctx%failed() ) return

!
!        If we're using stellar aberration corrections, which we
!        normally should do if we're using light time corrections,
!        compute the stellar aberration correction for the light time
!        corrected aberration correction locus.
!
         if ( usestl ) then
!
!           Get the position of the aberration correction locus
!           relative to the observer in the J2000 frame. The locus is
!           expressed as an offset from the target center.
!
!           First convert the locus from the target body-fixed frame to
!           the J2000 frame.
!
            if ( tanloc ) then
               call mtxv ( j2fixm, tanpt, j2lcus )
            else
               call mtxv ( j2fixm, srfpt, j2lcus )
            end if

!
!           Compute the position of the locus relative to the observer
!           in the J2000 frame.
!
            j2tpos = -j2opos
            j2lpos = j2tpos + j2lcus

!
!           Correct the vector from the observer to the aberration
!           correction locus for stellar aberration and retain the
!           offset STLOFF from the uncorrected vector to the corrected
!           vector.
!
            if ( xmit ) then
               call stlabx ( ctx, j2lpos, ssbost(4), stlloc )
            else
               call stelab ( ctx, j2lpos, ssbost(4), stlloc )
            end if

            stloff = stlloc - j2lpos

!
!           Convert the stellar aberration correction offset to the
!           target body-fixed frame at TRGEPC.
!
            call mxv ( j2fixm, stloff, stlfix )

         else
!
!           We're not using stellar aberration correction, so just
!           zero out the offset.
!
            stlfix = 0.0_wp

         end if

!
!        Convert the observer's position relative to the target from
!        the J2000 frame to the target frame at the target epoch. Let
!        TRGPOS be the negative of this vector.
!
         call mxv    ( j2fixm, j2opos, fixobs )
         trgpos = -fixobs

!
!        Convert the ray direction vector from the J2000 frame
!        to the target frame at the target epoch.
!
         call mxv ( j2fixm, j2dir, fixdir )

!
!        The ray-ellipsoid near point computation must be performed
!        using the apparent target. We've accounted for light time,
!        but stellar aberration must be accounted for as well. The
!        apparent target is shifted due to stellar aberration by the
!        body-fixed vector STLFIX. Equivalently, we can shift the
!        observer position by -STLFIX.
!
!        If stellar aberration correction was not commanded, then
!        STLFIX is the zero vector.
!
         stlobs = fixobs - stlfix

!
!        Re-compute the surface point and ray altitude.
!
         call npedln ( ctx, svradi(1), svradi(2), svradi(3), &
                       stlobs,    fixdir,    srfpt,    alt )

         if ( ctx%failed() ) return

!
!        Now compute the tangent point.
!
!        Start by finding the nearest point to SRFPT on the line
!        containing the input ray.
!
!        We retain the altitude found by NPEDLN, since the following
!        call can introduce round-off error in the intercept case.
!
         if ( alt /= 0.0_wp ) then
            call nplnpt ( ctx, stlobs, fixdir, srfpt, tanpt, dval )
         else
            tanpt = srfpt
         end if

!
!        The output SRFVEC extends from the observer to the apparent
!        position of the surface point.
!
         srfvec = srfpt - stlobs

!
!        We may need to update TANPT, SRFPT and SRFVEC if the tangent
!        point is behind the observer (the look-away case).
!
         tanoff = tanpt - stlobs

         if ( vdot( tanoff, fixdir ) <= 0.0_wp ) then
!
!           TANPT is on or behind the ray's vertex. Reset TANPT to be
!           the vertex.
!
            tanpt = stlobs
            range = 0.0_wp

!
!           In this case, the surface point is considered to be the
!           nearest point on the target to the observer. The altitude
!           of the observer above this point is the tangent point's
!           altitude.
!
            call nearpt ( ctx, stlobs,    svradi(1), svradi(2), &
                          svradi(3), srfpt,     alt       )

            if ( ctx%failed() ) return

            srfvec = srfpt - tanpt

!
!           Set the light time and the target epoch, based on the
!           locus.
!
            if ( tanloc ) then

               lt     = 0.0_wp
               trgepc = et

            else

               lt     = alt / clight
               trgepc = et + s*lt

            end if

         else
!
!           This is the normal case.
!
!           Compute a new light time estimate and new target epoch.
!           Light time estimates are computed using the light-time
!           corrected position of the aberration correction locus;
!           stellar aberration does not apply. Therefore we use FIXOBS
!           as the observer position for the distance computations.
!
            if ( tanloc ) then
!
!              Compute distance to the tangent point.
!
               dist = vdist ( fixobs, tanpt )

            else
!
!              Compute distance to the surface point.
!
               dist = vdist ( fixobs, srfpt )

            end if
!
!           Compute a new light time estimate and a new target epoch.
!
            lt     = dist / clight
            trgepc = et  +  s * lt

         end if

!
!        Compute the changes in the light time and target epoch for
!        this loop pass. Determine whether light time and stellar
!        aberration have converged.
!
         lt      =   (lt)
         ltdiff  =   abs( lt     - prevlt )
         epcdif  =   abs( trgepc - prvepc )

         prevlt  =   lt
         prvepc  =   trgepc
         i       =   i + 1

         ltcnv  =        (  ltdiff < ( cnvlim * abs(lt) )  ) &
                   .or.  (  epcdif ==   0.0_wp                )

         if ( usestl ) then

            stlcnv =       ( vrel( tanpt, prvtan ) < cnvlim ) &
                     .and. ( vrel( srfpt, prvsrf ) < cnvlim )
         end if

      end do

      range = vdist ( stlobs, tanpt )

      return
      end associate
      end subroutine tangpt

      !> Indicate whether one triaxial ellipsoid is occulted by another as
      !> seen from a specified viewing location.
      !>
      !> The function returns an integer code indicating the geometric
      !> relationship of the three bodies.  Negative codes indicate that
      !> the first target is partially or fully occulted by the second;
      !> positive codes indicate that the second target is partially
      !> or fully occulted by the first; a value of zero indicates no
      !> occultation.
      !>
      !> See Detailed_Output for the list of codes and meanings.
      !>
      !>## Detailed Input
      !>
      !>     VIEWPT         is a point from which a possible occultation of
      !>                    one ellipsoidal "target" body by another is
      !>                    observed. VIEWPT must be external to both target
      !>                    bodies.
      !>
      !>     CENTR1         is the center of the first ellipsoidal target
      !>                    body.
      !>
      !>     SEMAX1         is a 3x3 matrix whose columns are semi-axis
      !>                    vectors of the first ellipsoid.  The columns of
      !>                    SEMAX1 must form a right-handed, orthogonal basis:
      !>                    the columns are mutually orthogonal, and the third
      !>                    column points in the direction of the cross
      !>                    product of the first and second.  In other words,
      !>                    if the columns were scaled to unit length, the
      !>                    matrix would be orthogonal.
      !>
      !>                    The lengths of the column vectors are the lengths
      !>                    of the ellipsoid's semi-axes.  It is not necessary
      !>                    that the longest semi-axis appear in the first
      !>                    column.
      !>
      !>                    An example:  if the first ellipsoid is described
      !>                    by the equation
      !>
      !>                         2       2       2
      !>                        x       y       z
      !>                       ---  +  ---  +  ---   =   1
      !>                         2       2       2
      !>                        a       b       c
      !>
      !>                    then a corresponding semi-axis matrix would
      !>                    be
      !>
      !>                       +-          -+
      !>                       |  a   0   0 |
      !>                       |  0   b   0 |
      !>                       |  0   0   c |
      !>                       +-          -+
      !>
      !>                    A second example of a valid semi-axis matrix is
      !>
      !>                       +-          -+
      !>                       |  0  -a   0 |
      !>                       |  0   0  -b |
      !>                       |  c   0   0 |
      !>                       +-          -+
      !>
      !>     CENTR2         is the center of the second ellipsoidal target
      !>                    body.
      !>
      !>     SEMAX2         is a semi-axis matrix for the second ellipsoidal
      !>                    target body.  See the description of SEMAX1 for
      !>                    details.
      !>
      !>## Detailed Output
      !>
      !>     The function returns an integer code indicating the geometric
      !>     relationship of the three bodies.
      !>
      !>     Codes and meanings are:
      !>
      !>        TOTAL1                Total occultation of first target by
      !>                              second.
      !>
      !>        ANNLR1                Annular occultation of first target by
      !>                              second.  The second target does not
      !>                              block the limb of the first.
      !>
      !>        PARTL1                Partial occultation of first target by
      !>                              second target.
      !>
      !>        NOOCC                 No occultation or transit:  both objects
      !>                              are completely visible to the observer.
      !>
      !>        PARTL2                Partial occultation of second target by
      !>                              first target.
      !>
      !>        ANNLR2                Annular occultation of second target by
      !>                              first.
      !>
      !>        TOTAL2                Total occultation of second target by
      !>                              first.
      !>
      !>## Parameters
      !>
      !>     UBEL           Upper bound of SPICELIB ellipse data structure.
      !>
      !>     UBPL           Upper bound of SPICELIB plane data structure.
      !>
      !>## Exceptions
      !>
      !>     1)  If the observer is inside either target ellipsoid, the error
      !>         SPICE(NOTDISJOINT) is signaled.
      !>
      !>     2)  If this routine determines that the target bodies intersect,
      !>         the error SPICE(NOTDISJOINT) is signaled.
      !>
      !>     3)  If any of the semi-axis lengths of either ellipsoid is
      !>         non-positive, the error SPICE(BADAXISLENGTH) is signaled.
      !>
      !>     4)  If either semi-axis matrix does not have a right-handed,
      !>         mutually orthogonal set of columns, the error
      !>         SPICE(NOTAROTATION) will be signaled.
      !>
      !>## Files
      !>
      !>     None.
      !>
      !>## Particulars
      !>
      !>     For many purposes, modeling extended bodies as tri-axial
      !>     ellipsoids is adequate for determining whether one body is
      !>     occulted by another as seen from a specified observer.
      !>
      !>     This routine may be used as a tool to support more higher-level
      !>     occultation tests involving ephemeris objects.
      !>
      !>## Examples
      !>
      !>     1)  View a total occultation of one ellipsoid by another
      !>         as seen from a viewing location on the +x axis.
      !>
      !>                 PROGRAM EX1
      !>                 IMPLICIT NONE
      !>
      !>           C
      !>           C     SPICELIB functions
      !>           C
      !>                 INTEGER ZZOCCED
      !>
      !>           C
      !>           C     Local variables
      !>           C
      !>                 DOUBLE PRECISION      CENTR1 ( 3 )
      !>                 DOUBLE PRECISION      CENTR2 ( 3 )
      !>                 DOUBLE PRECISION      SEMAX1 ( 3, 3 )
      !>                 DOUBLE PRECISION      SEMAX2 ( 3, 3 )
      !>                 DOUBLE PRECISION      VIEWPT ( 3 )
      !>
      !>                 INTEGER               CODE
      !>
      !>           C
      !>           C     Initial values
      !>           C
      !>                 DATA VIEWPT /    2.D1, 0.D0, 0.D0 /
      !>
      !>                 DATA CENTR1 /    1.D1, 0.D0, 0.D0 /
      !>
      !>                 DATA SEMAX1 /    1.D0, 0.D0, 0.D0,
      !>                .                 0.D0, 5.D0, 0.D0,
      !>                .                 0.D0, 0.D0, 1.D1 /
      !>
      !>                 DATA CENTR2 /   -1.D1, 0.D0, 0.D0 /
      !>
      !>                 DATA SEMAX2 /    2.D0, 0.D0, 0.D0,
      !>                .                 0.D0, 1.D1, 0.D0,
      !>                .                 0.D0, 0.D0, 2.D1 /
      !>
      !>           C
      !>           C     Find the occultation state and write out the
      !>           C     occultation code.  We don't place the ZZOCCED
      !>           C     call directly in the WRITE statement because
      !>           C     ZZOCCED can signal errors; an error signaled in
      !>           C     an I/O statement would cause recursive I/O.
      !>           C
      !>                 CODE = ZZOCCED ( VIEWPT, CENTR1, SEMAX1,
      !>                .                         CENTR2, SEMAX2 )
      !>
      !>                 WRITE (*,*), 'CODE = ', CODE
      !>                 END
      !>
      !>     We expect that the smaller ellipsoid, listed first in the call to
      !>     ZZOCCED, completely occults the larger, so the return code should
      !>     be 3.
      !>
      !>## Restrictions
      !>
      !>     1) The test done by this routine for intersection of target bodies
      !>        may return a false negative result.  The test is based on
      !>        finding an intersection of spheres inscribed in each target
      !>        body.
      !>
      !>        Correct application code should never exercise this test.
      !>
      !>     2) This routine relies on ZZASRYEL to determine the minimum and
      !>        maximum angular separation of a specified ray and ellipse. In
      !>        some unusual cases in which multiple extreme values are very
      !>        close, or in which the extrema occur at points very close
      !>        together on the ellipse, ZZASRYEL may locate the incorrect
      !>        extremum.  This can result in erroneous classification of a
      !>        partial occultation as a total occultation or annular transit.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 17-MAR-2006 (NJB)
      !>
      !>        Bug fixes:
      !>
      !>           - Test for intersection of viewpoint with targets
      !>             was corrected.  Previous test did not properly account
      !>             for target orientation.
      !>
      !>           - Computation of maximum bounding cones of targets
      !>             failed when viewing point was inside either maximum
      !>             bounding sphere.  The algorithm now has a separate
      !>             branch to handle this situation.
      !>
      !>           - Computation of minimum bounding cone for target was
      !>             incorrect for the computation done after transformation
      !>             of the targets.  This computation has been corrected.
      !>
      !>-    SPICELIB Version 1.0.0, 17-AUG-2005 (NJB)
      module integer(ip) function zzocced ( ctx, viewpt, centr1, semax1, centr2, semax2 )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: halfpi, pi
      use pepper_math, only: det, el2cgv, mtxv, mxm, mxv, ucrss, unorm, vdist, vnorm, vsep
      use pepper_inc_zzocced
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: viewpt ( 3 )  !! Observation location.
      real(wp), intent(in) :: centr1 ( 3 )  !! Center of first ellipsoid.
      real(wp), intent(in) :: semax1 ( 3, 3 )  !! Semi-major axis matrix for first ellipsoid.
      real(wp), intent(in) :: centr2 ( 3 )  !! Center of second ellipsoid.
      real(wp), intent(in) :: semax2 ( 3, 3 )  !! Semi-major axis matrix for second ellipsoid.



!     Tolerance value for determinant of a rotation matrix.  The
!     determinant must differ from 1 by no more than DTOL.
!
      real(wp), parameter :: dtol = 1.0e-12_wp

!
!     Tolerance value for norms of columns of a rotation matrix.  The
!     norms must differ from 1 by no more than NTOL.
!
      real(wp), parameter :: ntol = 1.0e-14_wp

      real(wp) :: angcmp
      real(wp) :: bigctr ( 3 )
      real(wp) :: bigr
      real(wp) :: ctrs   ( 3, 2 )
      real(wp) :: dist   ( 2 )
      real(wp) :: invray ( 3 )
      real(wp) :: level
      real(wp) :: limb   ( ubel )
      real(wp) :: lmbctr ( 3 )
      real(wp) :: lmbmaj ( 3 )
      real(wp) :: lmbmin ( 3 )
      real(wp) :: lplane ( ubpl )
      real(wp) :: lnorml ( 3 )
      real(wp) :: majlen
      real(wp) :: maxang ( 2 )
      real(wp) :: maxpt  ( 3 )
      real(wp) :: maxrad ( 2 )
      real(wp) :: maxsep
      real(wp) :: minang ( 2 )
      real(wp) :: minlen
      real(wp) :: minpt  ( 3 )
      real(wp) :: minrad ( 2 )
      real(wp) :: minsep
      real(wp) :: minvec ( 3 )
      real(wp) :: r      ( 3, 2 )
      real(wp) :: raydir ( 3 )
      real(wp) :: rmat   ( 3, 3, 2 )
      real(wp) :: sclmat ( 3, 3 )
      real(wp) :: sclrot ( 3, 3 )
      real(wp) :: smlctr ( 3 )
      real(wp) :: smldir ( 3 )
      real(wp) :: smlmaj ( 3 )
      real(wp) :: smlmat ( 3, 3 )
      real(wp) :: smlmin ( 3 )
      real(wp) :: smlvu  ( 3 )
      real(wp) :: t12pos ( 3 )
      real(wp) :: t1opos ( 3 )
      real(wp) :: t2sep
      real(wp) :: tilt
      real(wp) :: tmpctr ( 3 )
      real(wp) :: tmpmaj ( 3 )
      real(wp) :: tmpmin ( 3 )
      real(wp) :: tpos   ( 3, 2 )
      real(wp) :: trgsep
      real(wp) :: ttdist
      real(wp) :: uasize
      real(wp) :: ubdist
      real(wp) :: view   ( 3 )
      real(wp) :: vph
      real(wp) :: vpproj ( 3 )
      real(wp) :: xasep
      real(wp) :: xdist  ( 2 )
      real(wp) :: xlimb  ( ubel )
      real(wp) :: xr     ( 3, 3 )
      real(wp) :: xsmlvu ( 3 )
      real(wp) :: xtpos  ( 3, 2 )
      real(wp) :: xview  ( 3 )
      real(wp) :: xvwtrg ( 3 )

      integer(ip) :: bigidx
      integer(ip) :: frtidx
      integer(ip) :: i
      integer(ip) :: s
      integer(ip) :: smlidx
      logical :: sfront

!
!     Overview
!     =======================================================
!
!     This routine starts out by initializing variables and
!     performing some error checks on the inputs.
!
!     The routine proceeds to classify the type occultation,
!     starting with simple approximation techniques, and if those
!     fail, following with more computationally expensive techniques.
!
!     All of the classifications have two elements:
!
!        - Determining the type of overlap: total occultation
!          or annular transit, partial occultation, or no
!          occultation.
!
!        - Determining which object is in front of the other
!          if an overlap exists.
!
!     For each classification, this routine sets the return code to
!     indicate the above attributes of the occultation geometry.
!
!     The first classification step is performed using "bounding
!     cones." For each ellipsoid, we define a "minimum bounding cone"
!     and a "maximum bounding cone."  A minimum bounding cone for an
!     ellipsoid has the viewing point as its vertex and is tangent to
!     the sphere whose radius is the ellipsoid's minimum semi-axis
!     length and whose center coincides with the ellipsoid's center.
!
!     A maximum bounding cone is defined analogously, with the sphere
!     having radius equal to the ellipsoid's maximum semi-axis length.
!
!     Since all of the bounding cones intersect in the viewing point,
!     it's inaccurate to speak of the cones as "not intersecting."
!     However, it's very convenient to ignore this intersection, so
!     we'll consider a pair of cones to intersect or "overlap" only if
!     they intersect in more than just their common vertex.
!
!     The conditions that can be determined by the initial bounding
!     cone tests are as follows:
!
!        1) The maximum bounding cones are disjoint.  This implies
!           there is no occultation.
!
!        2) The maximum bounding cone of one ellipsoid is contained
!           in the minimum bounding cone of the other.  This implies
!           there is a total occultation or annular transit.
!
!        3) The minimum bounding cones of the ellipsoids overlap,
!           and neither of these cones is contained in the maximum
!           bounding cone of the other ellipsoid.  This implies there
!           is a partial occultation.
!
!     If the occultation cannot be classified by the above tests, the
!     next step is to change the problem into an equivalent one in
!     which one of the ellipsoids is a sphere.  This new problem can be
!     attacked by considering the angular separation between the ray
!     from the viewing point to the center of the sphere and the limb
!     of the other ellipsoid.
!
!     To obtain this simplified geometric configuration, we apply to
!     all participating objects a non-singular linear transformation.
!     This transformation maps one of the ellipsoids to the unit sphere.
!     The viewing point, the center of the ellipsoid mapped to the
!     unit sphere, and the center and generating vectors of the limb
!     of the other ellipsoid are all subjected to this transformation.
!     The result is a collection of objects that yield the same
!     occultation state as the original set.  (The reader may want
!     to verify that limbs of ellipsoids map to limbs under this
!     transformation.)
!
!     The conditions that can be identified immediately using the
!     transformed objects are:
!
!        4)  The minimum angular separation between the ray from the
!            viewing point to the center of the unit sphere ("the ray"
!            henceforth) and the limb of the other ellipsoid is greater
!            than the angular radius (one half of the apparent angular
!            size as seen from the viewing point) of the unit sphere.
!            This implies there is no occultation.
!
!        5)  The minimum angular separation between the ray and the
!            limb of the other ellipsoid is negative (meaning the ray
!            penetrates the plane region bounded by the limb) and has
!            magnitude greater than the angular radius of the unit
!            sphere.  This implies the unit sphere is in total
!            occultation or in annular transit across the other
!            ellipsoid.
!
!     If both of the above tests fail, there is an occultation, but
!     it remains to be classified.  We do know at this point that the
!     unit sphere extends beyond the other ellipsoid, but we don't
!     know whether the other ellipsoid also extends beyond the unit
!     sphere.  If it does, we have a partial occultation; if it
!     doesn't, the other ellipsoid is totally occulted by the unit
!     sphere or is in annular transit across it.
!
!     At this point, we perform a second set of bounding cone tests.
!     The reason this may be useful is that the linear transformation
!     we've performed gives rise to a new set of bounding cones whose
!     containment relationships *are not* necessarily the same as those
!     of the original ellipsoids.  The conditions that can be
!     identified at this point by the bounding cone tests are:
!
!        6) The bounding cone of the unit sphere (the minimum and
!           maximum bounding cones are coincident) contains the maximum
!           bounding cone of the other ellipsoid.  This implies the
!           latter ellipsoid is in total occultation or annular
!           transit.
!
!        7) The bounding cone of the unit sphere does not contain
!           the minimum bounding cone of the other ellipsoid.  This
!           implies there is a partial occultation.
!
!     If these tests fail, the final step is to find the maximum
!     angular separation of the ray and the limb of the other
!     ellipsoid.  This separation is signed, with a negative sign
!     indicating that the ray penetrates the plane region bounded by
!     the limb.  The conditions we can determine using this information
!     are:
!
!        8) The maximum *magnitude* of the angular separation of the
!           limb and the ray is less than or equal to the angular size
!           of the unit sphere. This implies the other ellipsoid is in
!           total occultation or annular transit across the unit sphere.
!
!        9) The maximum *magnitude* of the angular separation of the
!           limb and the ray is greater than the angular size
!           of the unit sphere. This implies there is a partial
!           occultation.
!
!     Executable code
!     =======================================================
!
!     Set an initial function value.
!
      zzocced = noocc

!
!     Standard SPICE error handling.
!
      if ( ctx%failed() ) return

!
!     Extract the radii of the targets from the semi-axis vectors.
!     At the same time, create rotation matrices that map vectors
!     from the principal axis frames of the targets to the base frame.
!
      do i = 1, 3

         call unorm ( semax1(1,i), rmat(1,i,1), r(i,1) )
         call unorm ( semax2(1,i), rmat(1,i,2), r(i,2) )

      end do

!
!     Find the minimum and maximum radii of both targets.
!
      do i = 1, 2
         minrad(i) = min ( r(1,i), r(2,i), r(3,i) )
         maxrad(i) = max ( r(1,i), r(2,i), r(3,i) )
      end do

!
!     Make sure the input target radii are positive.  We'll actually do
!     a more stringent test later, but we must prevent divide-by-zero
!     errors at this point.
!
      if (  ( minrad(1) <= 0.0_wp ) .or. ( minrad(2) <= 0.0_wp )  ) then

         call ctx%setmsg ( 'Minimum radii of bodies 1 and 2 are #, #. ' // &
                       'Target radii must be positive.'             )
         call ctx%errdp  ( '#',  minrad(1)                              )
         call ctx%errdp  ( '#',  minrad(2)                              )
         call ctx%sigerr ( 'SPICE(BADAXISLENGTH)'                       )
         return

      end if

!
!     Compute view point-to-target vectors and ranges for both
!     target bodies.
!
      ctrs(:,1) = centr1
      ctrs(:,2) = centr2

      do i = 1, 2

         tpos(:,i) = ctrs(:,i) - viewpt

         dist(i) = vnorm( tpos(1,i) )

         if ( dist(i) == 0.0_wp ) then

            call ctx%setmsg ( 'Center of object # coincides with ' // &
                          'the viewing point.'                 )
            call ctx%errint ( '#',  i                              )
            call ctx%sigerr ( 'SPICE(NOTDISJOINT)'                 )
            return

         end if

      end do

!
!     Now check the semi-axis matrices.  We'll create new matrices
!     from these inputs by scaling the columns of each to unit length.
!     the resulting matrices are supposed to be rotations.
!
      do i = 1, 2

         if (  .not.  isrot ( ctx, rmat(1,1,i), ntol, dtol )  ) then

            call ctx%setmsg ( 'Matrix derived by unitizing columns '  // &
                          'of semi-axis matrix SEMAX# is not a '  // &
                          'rotation matrix.  The determinant of ' // &
                          'this matrix is #.'                     )
            call ctx%errint ( '#',  i                                 )
            call ctx%errdp  ( '#',  det ( rmat(1,1,i) )               )
            call ctx%sigerr ( 'SPICE(NOTAROTATION)'                   )
            return

         end if

      end do

!
!     Find the position of the second target relative to the first.
!
      t12pos = tpos(:,2) - tpos(:,1)

      ttdist = vnorm ( t12pos )

!
!     Make sure the targets are non-intersecting.
!
      if (  ttdist  <=  ( minrad(1) + minrad(2) )  ) then

         call ctx%setmsg ( 'Targets must be non-intersecting, but  '     // &
                       'spheres inscribed in the targets intersect.' )
         call ctx%sigerr ( 'SPICE(NOTDISJOINT)'                          )
         return

      end if

!
!     Make sure that the viewing point is outside of both target
!     ellipsoids.
!
      do i = 1, 2
!
!        Transform the Ith target position into the frame of the
!        Ith target.
!
         call mtxv ( rmat(1,1,i), tpos(1,i), xtpos(1,i) )

!
!        The viewpoint position is the negative of the target position.
!        Since we're squaring the terms involving the target position,
!        we omit the minus signs.
!
         level =    ( xtpos(1,i) / r(1,i) )**2 &
                 +  ( xtpos(2,i) / r(2,i) )**2 &
                 +  ( xtpos(3,i) / r(3,i) )**2

         if ( level < 1.0_wp ) then

            call ctx%setmsg ( 'Viewpoint is inside target #; level ' // &
                          'surface parameter = #.'               )
            call ctx%errint ( '#',  i                                )
            call ctx%errdp  ( '#',  level                            )
            call ctx%sigerr ( 'SPICE(NOTDISJOINT)'                   )
            return

         end if

      end do

!
!     Find the minimum and maximum angular radii of both targets.  Note
!     that the distances used as denominators are guaranteed to be
!     positive at this point.
!
      do i = 1, 2

         minang(i) = dasine ( ctx, minrad(i)/dist(i), atol )

         if ( ctx%failed() ) return

!
!        The situation is a bit more complicated for the maximum
!        bounding sphere, because the observer can be outside both
!        ellipsoids but inside one or both maximum bounding spheres.
!        We handle that special case separately.
!
         if ( dist(i) >= maxrad(i) ) then
!
!           The viewing point is outside the sphere; we use the sphere
!           to define the maximum angular radius.
!
            maxang(i) = dasine ( ctx, maxrad(i)/dist(i), atol )

            if ( ctx%failed() ) return

         else
!
!           The viewing point is outside the Ith ellipsoid but inside
!           the nominal bounding sphere.  We can't use the sphere to
!           define the maximum bounding cone.  Instead, we bound the
!           angular radius of the ellipsoid as follows:
!
!              1) Find the limb of the ellipsoid as seen from the
!                 viewing point, and construct the limb plane.
!
!              2) Find the orthogonal projection of the viewing point
!                 onto the limb plane; call this project VPPROJ.  The
!                 height of the viewing point above VPPROJ is VPH.
!
!              3) Create an upper bound UBDIST on the maximum distance
!                 between VPPROJ and any limb point.  Here's where we
!                 use a crude but safe estimate:  let UBDIST be the
!                 sum of the distance between VPPROJ and the center of
!                 the limb and the semi-major axis length of the limb.
!                 The triangle inequality shows this is a valid upper
!                 bound.
!
!              4) The viewing point and the circle of radius UBDIST
!                 centered at VPPROJ define a right circular cone
!                 that contains the limb:  this is our choice of
!                 the maximum bounding cone.  The arctangent of
!                 UBDIST/VPH is the angular radius of this cone.
!
!           The vector XTPOS(*,I) contains the position of the Ith
!           target relative to the viewing point, represented in the
!           principal axis frame of the Ith target. Let XVWTRG contain
!           the inverse of this vector, which is the observer position
!           relative to the center of the Ith target, in the principal
!           axis frame of the Ith target.
!
            xvwtrg = -xtpos(:,i)

            call edlimb ( ctx, r(1,i), r(2,i), r(3,i), xvwtrg, limb )

!
!           Extract the limb's center and semi-axis vectors.
!
            call el2cgv ( limb, lmbctr, lmbmaj, lmbmin )

!
!           Create the limb plane.
!
            call psv2pl ( ctx, lmbctr, lmbmaj, lmbmin, lplane )

!
!           Project the viewing point onto the limb plane.  Find
!           the height of the viewing point relative to this plane.
!
            call vprjp ( ctx, xvwtrg, lplane, vpproj )

            vph = vdist ( xvwtrg, vpproj )

!
!           Find an upper bound on the distance of any limb point from
!           VPPROJ.
!
            ubdist = vdist ( vpproj, lmbctr )  +  vnorm ( lmbmaj )

!
!           Find the angular size of the maximum bounding cone.  We
!           use the 2-argument arctangent to avoid divide-by-zero
!           problems.  The worst that can happen is that VPH is
!           zero, which gives us a degenerate cone of angular radius
!           pi/2.
!
            maxang(i) = atan2 ( ubdist, vph )

         end if
!
!        At this point MAXANG(I) and MINANG(I) are both set for the
!        Ith ellipsoid.
!
      end do

!
!     Find the angular separation of the centers of the targets
!     seen by the observer.
!
      trgsep = vsep ( tpos(1,1), tpos(1,2) )

!
!     If bounding cones defined by the maximum radii don't intersect,
!     we're done.
!
      if (  trgsep  > ( maxang(1) + maxang(2) )  ) then

         zzocced = noocc

         return

      end if

!
!     Use the maximum angular sizes to determine which ellipsoid
!     appears to the observer to be "biggest."  This is merely a
!     heuristic:  the orientation of the ellipsoids may cause the order
!     of the apparent angular sizes to be the opposite. The idea,
!     however, is that for "reasonable" cases, we'll correctly identify
!     the ellipsoid of larger angular size. This choice is made to
!     improve efficiency.
!
      if (  maxang(1)  >  maxang(2)  ) then
         bigidx  =  1
      else
         bigidx  =  2
      end if

!
!     The other index is SMLIDX.
!
      smlidx = 3 - bigidx

!
!     We're ready to see whether an occultation condition exists.
!     We can efficiently handle some cases by working with bounding
!     cones defined by the viewing point, the centers of the targets,
!     and spheres centered at the targets having radii equal to the
!     minimum and maximum radii of the targets.
!
!     If the two minimum bounding cones have non-trivial intersection
!     (of course they always intersect at their common vertex), we're
!     guaranteed some sort of occultation.  Check for this case.
!
      if (  ( minang(1) + minang(2) )  >  trgsep  ) then
!
!        The minimum bounding cones do overlap. Determine which target
!        is "in front" of the other.  We do this determining which
!        minimum sphere is in front of the other.
!
!        We'll do the test by examining the angle between the vectors
!        from the first target to the observer and the from the first
!        target to the second.  If that angle is less than the
!        complement of the angular radius of the first target, then the
!        minimum sphere of the second target is in transit across the
!        first. Otherwise the minimum sphere of the second target is at
!        least partially occulted by the first.
!
!        Let T1OPOS be the vector from the first target to the observer.
!
         t1opos = -tpos(:,1)

!
!        ANGCMP is the angle between a vector from the first target's
!        center to its limb and the plane containing the center and
!        orthogonal to the vector from the first target's center to the
!        observer.
!
         angcmp = halfpi - minang(1)

!
!        T2SEP is the angle between the vector from the first target's
!        center to the observer and the vector from the first target
!        to the second target.
!
         t2sep  =  vsep ( t1opos, t12pos )

         if ( t2sep < angcmp ) then
!
!           The second target is "in front" of the first.
!
            frtidx =  2

!
!           Set the sign of the return code.
!
            s      = -1

         else

            frtidx =  1
            s      =  1

         end if

!
!        Now classify the occultation.  If the minimum sphere
!        of the front target has angular size greater than the maximum
!        angular size of the rear target plus the angular separation
!        of the target centers, the occultation is total.
!
         do i = 1, 2
!
!           (The subscript 3-I used below is 2 if I is 1 and vice
!           versa.)
!
            if (  minang(i)  >=  ( maxang(3-i) + trgsep )  ) then
!
!              If target I is in front, it totally occults the other
!              target.  Otherwise, the other target is in annular
!              transit across target I.
!
               if ( frtidx == i ) then
                  zzocced = s * total2
               else
                  zzocced = s * annlr2
               end if

!
!              We've found the occultation type, so we're done.
!
               return

            end if

         end do

!
!        If the angular size of the minimum sphere of *each* target
!        plus the angular separation of the centers exceeds the
!        maximum angular size of the other target, the occultation
!        is partial.  In other words, overlap is guaranteed, but it
!        is also guaranteed that neither target is totally blocked
!        by the other.
!
         if (       (  ( minang(1) + trgsep ) > maxang(2)  ) &
              .and. (  ( minang(2) + trgsep ) > maxang(1)  )   ) then
!
!           The occultation code is +/- PARTL2, depending on whether
!           the first target is in front.
!
            zzocced = s * partl2

            return

         end if
!
!        If we get to this point, we were unable to classify the
!        occultation using bounding cones alone.
!
      end if

!
!     This is the end of the case of overlapping minimum bounding
!     cones.
!
!     We're going apply a linear transformation to the viewing point
!     and both targets so as to convert the larger of the targets into
!     a sphere. We'll then find the angular separation from the other
!     target of the ray from viewing point to the center of the sphere.
!     In practice, we must transform the viewing point, the target
!     centers, and the limb of the ellipsoid that doesn't get mapped
!     to the unit sphere.
!
!     Note that this transformation *does not* preserve angular
!     separation, but it preserves set containment relationships.
!     In particular, the limbs of the targets map to limbs under
!     this transformation, since the limbs are the intersection sets
!     of the targets and tangent rays emanating from the viewing point.
!
!     First step:  find the limb of the smaller ellipsoid as
!     seen from the viewing point.  We need to map the viewing point
!     into the principal axis frame of the smaller ellipsoid first.
!     Let SMLMAT be the rotation matrix that effects this mapping.
!
      smlmat = transpose(rmat(:,:,smlidx))

!
!     Apply SMLMAT to the vector from the center of the smaller
!     ellipsoid to the viewing point.
!
      smlvu = viewpt - ctrs(:,smlidx)

      call mxv  ( smlmat, smlvu,          view  )

!
!     Find the limb of the smaller ellipsoid as seen from VIEW.
!
      call edlimb ( ctx, r(1,smlidx), r(2,smlidx), r(3,smlidx), view, limb )

!
!     Unpack the limb and map it from the principal axis frame of the
!     small ellipsoid back into the original frame.
!
      call el2cgv ( limb, tmpctr, tmpmaj, tmpmin )

      call mtxv   ( smlmat, tmpctr, smlctr )
      call mtxv   ( smlmat, tmpmaj, smlmaj )
      call mtxv   ( smlmat, tmpmin, smlmin )

!
!     At this point SMLCTR is the position of the center of the limb
!     relative to the center of the small ellipsoid.  We want to express
!     this center relative to the origin; we use the vector SMLCTR for
!     this.
!
      tmpctr = ctrs(:,smlidx) + smlctr
      smlctr = tmpctr

!
!     Create the transformation matrix that maps the larger ellipsoid
!     to the unit sphere.
!
!     First compute the scale matrix SCLMAT that scales vector
!     components by the reciprocals of the respective semi-axis
!     lengths of the large ellipsoid.
!
      sclmat = 0.0_wp

      sclmat(1,1) = 1.0_wp / r(1,bigidx)
      sclmat(2,2) = 1.0_wp / r(2,bigidx)
      sclmat(3,3) = 1.0_wp / r(3,bigidx)

!
!     Compose the row-scaling matrix SCLMAT with the frame
!     transformation required to map vectors to the principal axis
!     frame of this ellipsoid.  The result is the transformation
!     that maps the larger ellipsoid to the unit sphere.
!
!     We use one matrix SCLROT to perform these composed operations.
!
      xr = transpose(rmat(:,:,bigidx))
      call mxm   ( sclmat,            xr,  sclrot )

!
!     Transform the viewing point, the large ellipsoid's center vector,
!     and vectors defining the limb of the smaller ellipsoid using the
!     mapping that converts the larger ellipsoid to the unit sphere.
!
!     Map the viewing point to XVIEW.
!
      call mxv ( sclrot, viewpt, xview  )

!
!     Map the center of the large ellipsoid to BIGCTR.
!
      call mxv ( sclrot, ctrs(1,bigidx), bigctr )

!
!     Map the limb vectors of the smaller ellipsoid.
!
      call mxv  ( sclrot, smlctr, tmpctr )
      smlctr = tmpctr

      call mxv  ( sclrot, smlmaj, tmpmaj )
      call mxv  ( sclrot, smlmin, tmpmin )

!
!     Find the semi-axes of the transformed limb of the smaller
!     ellipsoid. Pack these vectors into the transformed limb data
!     structure XLIMB.
!
      call saelgv ( ctx, tmpmaj, tmpmin, smlmaj, smlmin )
      call cgv2el ( ctx, smlctr, smlmaj, smlmin, xlimb  )

!
!     Find the direction vector of the ray from the viewing point
!     to the transformed center of the large ellipsoid.
!
      raydir = bigctr - xview

!
!     Find the angular separation of the ray and the transformed
!     limb of the small ellipsoid.  The output MINPT is the limb
!     point at which the minimum angular separation is attained.
!
      call zzasryel ( ctx, 'MIN', xlimb, xview, raydir, minsep, minpt )

      if ( ctx%failed() ) return

!
!     Find the angular radius of the unit sphere centered at
!     BIGCTR, as seen from XVIEW.
!
      bigr = vnorm ( raydir )

!
!     Although previous error checks should ensure that BIGR is
!     greater than or equal to 1, we'll use a safe arcsine
!     computation.
!
      uasize = dasine ( ctx, 1.0_wp/bigr, atol )

      if ( ctx%failed() ) return

!
!     At this point, UASIZE is the angular size of the unit sphere
!     representing the transformed larger ellipsoid.  MINSEP is the
!     angular separation of the ray from the viewing point to the
!     center of the unit sphere and the transformed limb of the
!     smaller ellipsoid.
!
      if ( minsep > uasize ) then
!
!        There's no overlap.
!
         zzocced = noocc

         return

      end if

!
!     There's an overlap; now we must classify it. We know the limb
!     point MINPT at which the minimum angular separation occurs lies
!     in front of or behind the unit sphere, since the angular
!     separation at this point is less than or equal to UASIZE.
!
!     Find the vector from the center of the sphere to MINPT.
!
      minvec = minpt - bigctr

!
!     Get the inverse of the ray's direction vector.
!
      invray = -raydir

!
!     Now we can apply the criterion from the spherical occultation
!     algorithm to determine whether MINPT is in front of or behind
!     the sphere.  We'll use the logical flag SFRONT to indicate the
!     relative position of MINPT.
!
!     Set the sign S used later to set the return code as well.
!
      if (  vsep(minvec, invray)  <=  ( halfpi - uasize )  ) then
!
!        MINPT is in front.
!
         sfront = .true.
      else
         sfront = .false.
      end if

      if (      (          sfront   .and.  ( smlidx == 1 )  ) &
           .or. (  ( .not. sfront ) .and.  ( smlidx == 2 )  )  ) then
!
!        The first target is in front.
!
         s  =  1
      else
         s  = -1
      end if

      if ( minsep <= -uasize ) then
!
!        Arriving here implies that the "smaller" ellipsoid actually
!        appears larger than the other.  Recall that our determination
!        of which ellipsoid had larger apparent extent was fallible.
!        This situation is not an error condition.
!
!        The ray intersects the interior of the plane region bounded by
!        the limb of the "smaller" ellipsoid, and the unit sphere is
!        either totally occulted by the smaller ellipsoid or is in
!        annular transit across it.
!
         if ( sfront ) then
!
!           The point of minimum angular separation on the limb of the
!           smaller ellipsoid is in front: we have a total occultation
!           of the larger ellipsoid.
!
            zzocced =  s * total2

         else
!
!           We have an annular transit of the larger ellipsoid
!           across the smaller one.
!
            zzocced =  s * annlr2

         end if

      else
!
!        We know that some type of occultation exists. We know the
!        unit sphere is *neither* totally occulted by the other
!        ellipsoid nor in annular transit across it. It's possible that
!        the other ellipsoid is totally occulted by the unit sphere or
!        is in annular transit across it; otherwise we have a partial
!        occultation.
!
!        We try two quick classification tests first:
!
!           1) We see whether the maximum bounding cone of the small
!              ellipsoid is contained in the cone defined by the
!              viewing point and unit sphere.
!
!           2) We see whether the minimum bounding cone of the small
!              ellipsoid extends beyond the cone defined by the
!              viewing point and unit sphere.
!
!        Note that we need to re-compute the bounding cones for the
!        small ellipsoid since we've applied a linear transformation
!        to it.
!
!        Note also that these tests are not duplicates of the tests
!        performed earlier, since now the bounding cones of the
!        ellipsoids have been changed by the transformation applied
!        to both.
!
!        The linear transformation applied to the small ellipsoid does
!        not preserve distances, so we must re-compute the distance
!        from the viewing point to the center of the small ellipsoid.
!
         xsmlvu = xview - smlctr

         xdist(smlidx) = vnorm ( xsmlvu )

!
!        Compute angular radii of bounding cones for the transformed
!        limb of the small ellipsoid.  First, capture the semi-axis
!        lengths of the limb.
!
         majlen = vnorm( smlmaj )
         minlen = vnorm( smlmin )

         if ( xdist(smlidx) >= majlen ) then
!
!           The viewing point is outside a sphere of radius MAJLEN
!           centered at the limb's center.  We use this sphere to
!           to define the maximum angular radius.  Note that this
!           sphere may have larger angular extent than the small
!           ellipsoid, but it's guaranteed to block the small
!           ellipsoid.
!
            maxang(smlidx) = dasine ( ctx, majlen/xdist(smlidx), atol )

            if ( ctx%failed() ) return

         else
!
!           We create a maximum bounding cone using the same technique
!           we used above for the original, untransformed targets.  In
!           this case we already have the components of the limb of
!           the transformed, small target.
!
!           Create the limb plane.
!
            call psv2pl ( ctx, smlctr, smlmaj, smlmin, lplane )

!
!           Project the viewing point onto the limb plane.  Find
!           the height of the viewing point relative to this plane.
!
            call vprjp ( ctx, xview, lplane, vpproj )

            vph = vdist ( xview, vpproj )

!
!           Find an upper bound on the distance of any limb point from
!           VPPROJ.
!
            ubdist = vdist ( vpproj, smlctr )  +  majlen

!
!           Find the angular size of the maximum bounding cone.  We
!           use the 2-argument arctangent to avoid divide-by-zero
!           problems.  The worst that can happen is that VPH is
!           zero, which gives us a degenerate cone of angular radius
!           pi/2.
!
            maxang(smlidx) = atan2 ( ubdist, vph )

         end if

!
!        Now find the minimum bounding cone.  The situation is slightly
!        complicated by the fact that we have the limb of the
!        transformed, small ellipsoid rather than the ellipsoid itself.
!        We don't want to use ZZASRYEL here because that routine is
!        slow:  we don't want to call it if a quick test will do. So we
!        use a somewhat crude estimate that guarantees that all rays
!        contained in the small bounding cone intersect the small
!        ellipsoid.  The approach is as follows:
!
!           1) Determine the angle between the normal to the limb plane
!              pointing towards XVIEW and the viewing point-limb center
!              vector. Call this angle TILT.
!
!           2) For a circle having radius equal to the semi-minor axis
!              length of the limb, inscribed in the limb, and coplanar
!              with the limb, the minimum angular radius of any point
!              on the circle, as seen from XVIEW, is associated with
!              the point farthest from XVIEW.  The angular separation
!              of the vector from the limb center to this point and the
!              vector from XVIEW to the limb center is pi/2 + TILT.
!              Find the angular radius associated with that point.
!
!        Start out by constructing a normal to the limb plane.
!
         call ucrss ( smlmaj, smlmin, lnorml )

!
!        Choose a value of TILT not exceeding pi/2.
!
         tilt = vsep ( lnorml, xsmlvu )

         if ( tilt > halfpi ) then

            tilt = pi - tilt

         end if

!
!        Now we have a right triangle whose base is the distance from
!        XVIEW to the limb's center plus sin(TILT)*MINLEN, and whose
!        height is cos(TILT)*MINLEN.
!
!        Find the angle associated with the corner of the triangle
!        associated with the viewing point.  This is the angular
!        radius of our minimum bounding cone.
!
         minang(smlidx)  = atan2 ( cos(tilt)*minlen, &
                                   sin(tilt)*minlen + xdist(smlidx) )

!
!        Compute angular separation of the transformed centers.
!
         smldir = smlctr - xview

         xasep  =  vsep ( raydir, smldir )

!
!        Test for inclusion of the maximum bounding cone of the small
!        ellipsoid in the circumscribing cone of the sphere.
!
         if (  ( xasep + maxang(smlidx) )  <=  uasize  ) then
!
!           The small ellipsoid is either in total occultation or
!           in annular transit across the sphere.
!
            if ( sfront ) then
!
!              MINPT is in front of the sphere. We have an annular
!              transit of the small ellipsoid across the small one.
!
               zzocced =  s * annlr2

            else
!
!              MINPT is behind the sphere.  We have a total
!              occultation of the small ellipsoid.
!
               zzocced =  s * total2

            end if

            return

         end if

!
!        Test for non-containment of the minimum bounding cone of the
!        small ellipsoid by the circumscribing cone of the sphere.
!
         if (  ( xasep + minang(smlidx) )  >  uasize  ) then
!
!           The small ellipsoid is either in partial occultation or
!           in partial transit across the sphere.
!
            zzocced = s * partl2

            return

         end if

!
!        Arriving at this point means we've been unable to classify
!        the occultation or transit.  We're going to need to compute
!        the maximum angular separation of the limb from the ray
!        emanating from the viewing point and passing through the
!        center of the sphere.
!
         call zzasryel ( ctx, 'MAX', xlimb, xview, raydir, maxsep, maxpt )

         if ( ctx%failed() ) return

         if ( abs(maxsep) <= uasize ) then
!
!           Whether the ray from the viewing point to the center
!           of the unit sphere does nor does not penetrate the plane
!           region bounded by the limb of the smaller ellipse, no
!           point on that limb has greater angular separation than
!           UASIZE from the ray.
!
!           The small ellipsoid is either in total occultation or
!           in annular transit across the sphere.
!
            if ( sfront ) then
!
!              MINPT is in front of the sphere. We have an annular
!              transit of the small ellipsoid across the smaller.
!
               zzocced =  s * annlr2

            else
!
!              MINPT is behind the sphere.  We have a total
!              occultation of the small ellipsoid.
!
               zzocced =  s * total2

            end if

         else
!
!           Whether the ray from the viewing point to the center
!           of the unit sphere does nor does not penetrate the plane
!           region bounded by the limb of the smaller ellipse, some
!           point on that limb has greater angular separation than
!           UASIZE from the ray.
!
!           The small ellipsoid is either in partial occultation or
!           in partial transit across the sphere.
!
            zzocced = s * partl2

         end if
!
!        We've classified the occultation in the case where the
!        maximum angular separation of the ray and limb had to be
!        computed.
!
!        This is the end of the code for the case where there is
!        overlap, but the unit sphere is *neither* totally occulted by
!        the other ellipsoid nor in annular transit across it.
!
      end if
!
!     ZZOCCED has been set.
!

      return
      end function zzocced

      !> Map a point to the nearest plate in a specified type 2 DSK
      !> segment.
      !>
      !> The point is expressed in the reference frame of the segment and
      !> represents an offset from the center of the segment's reference
      !> frame.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE     is the handle of a DSK file containing a type 2 DSK
      !>                segment. The input point is to be matched with the
      !>                closest plate in this segment.
      !>
      !>     DLADSC     is the DLA descriptor of the DSK segment to be used.
      !>
      !>     DSKDSC     is the DSK descriptor of the DSK segment to be used.
      !>
      !>     POINT      is a point that is on or very near the surface
      !>                described by the DSK segment. POINT is expressed in
      !>                the reference frame of the segment and represents an
      !>                offset from the center of that frame. The frame center
      !>                may be distinct from the central body of the segment.
      !>
      !>## Detailed Output
      !>
      !>     PLID       is the ID of the plate nearest to the input point, if
      !>                such a plate is found. A plate ID is the index of a
      !>                plate in the set of plates contained in the segment.
      !>                PLID is 1-based.
      !>
      !>                The distances between POINT and the respective plates
      !>                are computed using the plate expansion factor XFRACT.
      !>                See the Parameters section below and the routine
      !>                PLTEXP for details.
      !>
      !>                A plate will be found only if POINT is sufficiently
      !>                close to at least one plate in the segment, when plate
      !>                expansion is taken into account. A margin is used to
      !>                determine whether a plate is close enough to the point
      !>                to be considered as a solution. See the Parameters
      !>                section for details.
      !>
      !>     PLATE      is the plate designated by PLID. It is an array of
      !>                three integers. The integers are the IDs of the
      !>                plate's vertices.
      !>
      !>     VERTS      is an array containing the plate's vertices. These
      !>                a 3-dimensional, double precision vectors. The Ith
      !>                vertex is stored in elements
      !>
      !>                   VERTS(1:3,I)
      !>
      !>     FOUND      is a logical flag that is set to .TRUE. if and only
      !>                if plate nearest to the input point was found
      !>
      !>                The outputs PLID, PLATE, and VERTS are valid if and
      !>                only if FOUND is .TRUE.
      !>
      !>## Parameters
      !>
      !>     See the include file
      !>
      !>        dsktol.inc
      !>
      !>     for declarations of these parameters. These defaults can be
      !>     overridden. See DSKSTL for details.
      !>
      !>     PTMEMM     is the default value of the point-plate membership
      !>                parameter, which is used to determine whether a point
      !>                is close enough to a plate to be considered as a
      !>                solution. Let S be the current value of this
      !>                parameter; the bounding radius of the segment is
      !>                multiplied by (1+S) to produce a distance used for
      !>                this comparison.
      !>
      !>     XFRACT     is the default value of an expansion factor applied to
      !>                each plate before the distance of POINT from the plate
      !>                is computed. Let S be the current value of this
      !>                parameter; each plate is expanded by a factor of (1+S)
      !>                to produce a plate used for the membership test.
      !>
      !>                This expansion is performed to keep results of this
      !>                routine consistent with those of DSKX02, which also
      !>                performs plate expansion.
      !>
      !>## Exceptions
      !>
      !>     1)  If an invalid voxel edge length is detected, the error
      !>         SPICE(VALUEOUTOFRANGE) is signaled.
      !>
      !>     2)  If the coarse voxel scale is zero, the error
      !>         SPICE(VALUEOUTOFRANGE) is signaled.
      !>
      !>     3)  If an unrecognized coordinate system is encountered, the
      !>         error SPICE(NOTSUPPORTED) is signaled.
      !>
      !>     4)  If an error occurs while this routine attempts to read
      !>         DSK data, the error will be signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data are required:
      !>
      !>        - DSK data: the DSK file designated by HANDLE and containing
      !>          the segment having the DLA descriptor DLADSC must be loaded
      !>          at the time this routine is called.
      !>
      !>     Kernel data are normally loaded once per program run, NOT every
      !>     time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine supports geometry routines that must associate
      !>     a computed surface point with the plate to which that point
      !>     belongs.
      !>
      !>## Examples
      !>
      !>     See usage in ZZDSKNRM.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 03-OCT-2021 (NJB)
      !>
      !>        Corrected typo in comments.
      !>
      !>-    SPICELIB Version 1.0.0, 22-FEB-2017 (NJB)
      !>
      !>        Added FAILED calls.
      !>
      !>        23-AUG-2016 (NJB)
      !>
      !>        Bug fix: now saves previous handle and DLA descriptor.
      !>
      !>        17-JUN-2016 (NJB)
      !>
      !>           Added support for planetodetic coordinates. Updated
      !>           bounding radius computation for segments using latitudinal
      !>           coordinates; this routine now calls ZZSEGBOX. Changed
      !>           implementation to use ZZINVELT and ZZVOXCVO. Updated
      !>           parameter descriptions.
      !>
      !>        07-OCT-2015 (NJB)
      !>
      !>           Now uses plate expansion before testing point-plate
      !>           distance.
      !>
      !>        15-DEC-2014 (NJB)
      module subroutine zzptpl02 ( ctx, handle, dladsc, dskdsc, point, plid, plate, verts, found )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: dpmax
      use pepper_math, only: pltexp, pltnrm, vdot, vhatip
      use pepper_inc_dla
      use pepper_inc_dskdsc
      use pepper_inc_dsk02
      use pepper_inc_dsktol
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! DSK file handle.
      integer(ip), intent(in) :: dladsc ( * )  !! DLA descriptor of segment.
      real(wp), intent(in) :: dskdsc ( * )  !! DSK descriptor of segment.
      real(wp), intent(in) :: point  ( 3 )  !! Input point.
      integer(ip), intent(out) :: plid  !! Plate ID.
      integer(ip), intent(out) :: plate  ( 3 )  !! Plate, expressed as an array of three vertex IDs.
      real(wp), intent(out) :: verts  ( 3, 3 )  !! Vertices of plate.
      logical, intent(out) :: found  !! Found flag.
      integer(ip) :: nplate_1(1)  !! one-element copy of nplate (array argument)
      integer(ip) :: pltptr_1(1)  !! one-element copy of pltptr (array argument)
      integer(ip) :: cgrptr_1(1)  !! one-element copy of cgrptr (array argument)
      integer(ip) :: cgrscl_1(1)  !! one-element copy of cgrscl (array argument)
      real(wp) :: voxsiz_1(1)  !! one-element copy of voxsiz (array argument)
      integer(ip), parameter :: bufsiz = 1000
      real(wp) :: boxctr ( 3 )
      real(wp) :: dist
      real(wp) :: dmin
      real(wp) :: offset ( 3 )
      real(wp) :: normal ( 3 )
      real(wp) :: pnear  ( 3 )
      real(wp) :: pntoff ( 3 )
      real(wp) :: ptsrfm
      real(wp) :: vrttmp ( 3, 3 )
      real(wp) :: xpdfrc
      real(wp) :: xverts ( 3, 3 )
      integer(ip) :: cgrcor ( 3 )
      integer(ip) :: cgrext ( 3 )
      integer(ip) :: cgroff ( 3 )
      integer(ip) :: cgrptr
      integer(ip) :: cgrvid
      integer(ip) :: i
      integer(ip) :: j
      integer(ip) :: k
      integer(ip) :: n
      integer(ip) :: nplate
      integer(ip) :: nread
      integer(ip) :: pidtmp
      integer(ip) :: pltbuf ( bufsiz )
      integer(ip) :: pltptr
      integer(ip) :: plttmp ( 3 )
      integer(ip) :: ptrloc
      integer(ip) :: ptroff
      integer(ip) :: remain
      integer(ip) :: start
      integer(ip) :: vgrcor ( 3 )
      integer(ip) :: vid
      logical :: inside
      real(wp) :: limit
      if ( .not. allocated ( ctx%zzptpl02_state ) ) allocate ( ctx%zzptpl02_state )
      associate ( cgrscl => ctx%zzptpl02_state%cgrscl, &
                  corsys => ctx%zzptpl02_state%corsys, &
                  maxr => ctx%zzptpl02_state%maxr, &
                  pass1 => ctx%zzptpl02_state%pass1, &
                  prvhan => ctx%zzptpl02_state%prvhan, &
                  prvdsc => ctx%zzptpl02_state%prvdsc, &
                  vgrext => ctx%zzptpl02_state%vgrext, &
                  voxori => ctx%zzptpl02_state%voxori, &
                  voxsiz => ctx%zzptpl02_state%voxsiz )
      if ( ctx%failed() ) return

!
!     No plate has been found so far.
!
      found = .false.

!
!     Decide whether we're looking at the segment we saw
!     on the previous call.
!
      if (  pass1  .or. &
            .not.  dlassg( ctx, handle, prvhan, dladsc, prvdsc )  ) then
!
!        We'll need to look up the voxel grid parameters for this
!        segment.
!
         call dskd02 ( ctx, handle, dladsc, kwvxor, 1, 3, n, voxori )
         call dskd02 ( ctx, handle, dladsc, kwvxsz, 1, 1, n, voxsiz_1 )
         voxsiz = voxsiz_1(1)
         call dski02 ( ctx, handle, dladsc, kwvgrx, 1, 3, n, vgrext )
         call dski02 ( ctx, handle, dladsc, kwcgsc, 1, 1, n, cgrscl_1 )
         cgrscl = cgrscl_1(1)

         if ( ctx%failed() ) return

         if ( voxsiz == 0.0_wp ) then

            call ctx%setmsg ( 'Voxel edge length is zero; length ' &
            //            'must be positive.'                  )
            call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'             )
            return

         end if

         if ( cgrscl == 0 ) then

            call ctx%setmsg ( 'Coarse voxel scale is zero; scale ' &
            //            'must be positive.'                  )
            call ctx%sigerr ( 'SPICE(VALUEOUTOFRANGE)'             )
            return

         end if

         corsys = nint( dskdsc(sysidx) )

         call zzsegbox ( ctx, dskdsc, boxctr, maxr )

         if ( ctx%failed() ) return

!
!        We successfully obtained the desired segment parameters, so we
!        don't need to execute this code again until the segment
!        changes. Save the current handle and DLA descriptor.
!
         prvhan = handle
         prvdsc = dladsc(1:dladsz)

         pass1  = .false.

      end if

!
!     Look up the point-plate membership margin; compute
!     the distance limit. This call must be made on every
!     call to ZZPTPL02.
!
      call dskgtl ( ctx, keyptm, ptsrfm )

      limit = ptsrfm * maxr

!
!     Look up the plate expansion fraction. This call must be made on
!     every call to ZZPTPL02.
!
      call dskgtl ( ctx, keyxfr, xpdfrc )

!
!     Find out whether the point is within the volume element
!     bounding the segment.
!
      call zzinvelt ( ctx, point,          corsys, dskdsc(paridx), &
                      dskdsc(mn1idx), ptsrfm, 0,              inside )

      if ( ctx%failed() ) return

      if ( .not. inside ) then
!
!        The point is too far from the segment to be considered
!        to lie on a plate in that segment.
!
         return

      end if

!
!     Map the point to the coordinates of a voxel containing it. If the
!     point is outside the voxel grid, map the point to the closest
!     voxel.
!
      offset = point - voxori

      do i = 1, 3

         j         = int( offset(i) / voxsiz ) + 1

         vgrcor(i) = max(min(1, vgrext(i)), min(max(1, vgrext(i)), j))

      end do

!
!     Compute the coordinates of the coarse voxel containing the fine
!     voxel we just identified. Get the 1-d offset of the fine voxel
!     relative the coarse voxel; this offset gives us the index of the
!     pointer associating the fine voxel with its plate list. The
!     1-d offset PTROFF is 1-based.
!
      call zzvoxcvo ( ctx, vgrcor, vgrext, cgrscl, cgrcor, cgroff, ptroff )

      if ( ctx%failed() ) return

!
!     Fetch the pointer from the coarse voxel to the first element of
!     its fine voxel pointer array.
!
!     We'll need the 1-D offset of the coarse voxel from the base of
!     the coarse voxel grid.
!
      do i = 1, 3
         cgrext(i) = vgrext(i) / cgrscl
      end do

      cgrvid = zzvox2id ( ctx, cgrcor, cgrext )

      call dski02 ( ctx, handle, dladsc, kwcgpt, cgrvid, 1, n, cgrptr_1 )
      cgrptr = cgrptr_1(1)

      if ( ctx%failed() ) return

      if ( cgrptr < 1 ) then
!
!        There are no non-empty fine voxels, hence no plates, in the
!        coarse voxel we're looking at.
!
         return

      end if
!
!     Look up the pointer to the plate list for this voxel, and if
!     the pointer is non-null, look up the plate count.
!
      ptrloc = (cgrptr - 1) + ptroff

      call dski02 ( ctx, handle, dladsc, kwvxpt, ptrloc, 1, n, pltptr_1 )
      pltptr = pltptr_1(1)

      if (  ctx%failed()  .or.  ( pltptr < 1 )  ) return

      call dski02 ( ctx, handle, dladsc, kwvxpl, pltptr, 1, n, nplate_1 )
      nplate = nplate_1(1)

      if (  ctx%failed()  .or.  ( nplate < 1 )  ) return

!
!     Loop through the plates, keeping track of the minimum plate-point
!     distance.
!
      dmin   = dpmax
      remain = nplate
      nread  = min ( remain, bufsiz )
      i      = 1

      do while ( remain > 0 )
!
!        Look up the current set of plate IDs.
!
         call dski02 ( ctx, handle,   dladsc, kwvxpl, &
                       pltptr+i, nread,  n,      pltbuf )

         if ( ctx%failed() ) return
!
!        Look up the vertices of each plate in the buffer and find
!        the distance of the point from that plate. Quit if we
!        find a match.
!
         do j = 1, nread

            pidtmp = pltbuf(j)
            start  = ( 3*(pidtmp-1) ) + 1

            call dski02 ( ctx, handle, dladsc, kwplat, start, 3, n, plttmp )

            do k = 1, 3

               vid   = plttmp(k)
               start = ( 3*(vid-1) ) + 1

               call dskd02 ( ctx, handle, dladsc, kwvert, &
                             start,  3,      n,      vrttmp(1,k) )

            end do

            if ( ctx%failed() ) return

!
!           Work with an expanded version of the plate.
!
            call pltexp ( vrttmp, xpdfrc, xverts )

            call pltnrm ( xverts(1,1), xverts(1,2), xverts(1,3), &
                          normal                                )

            if ( ctx%failed() ) return

            call vhatip ( normal )

            pntoff = point - xverts(:,1)

            if ( abs( vdot(pntoff,normal) ) <= limit ) then
!
!              The input point lies in a narrow region of space
!              bounded by two planes, both of which are parallel
!              to the plate. The plate lies between the planes.
!
!              This test does not rule out a comparison between POINT
!              and a distant plate, if POINT is close to the plane
!              containing that plate. However, the proportion of such
!              cases will normally be small.
!
               call pltnp ( ctx, point,       xverts(1,1), xverts(1,2), &
                            xverts(1,3), pnear,       dist        )

               if ( ctx%failed() ) return

            else
               dist = dpmax
            end if

            if ( dist <= limit ) then
!
!              We have a reasonable candidate for the closest plate.
!
               found = .true.

               if ( dist < dmin ) then

                  dmin  = dist
                  plid  = pidtmp
!
!                 Set the output vertices to the original version.
!
                  plate = plttmp
                  verts = vrttmp
!
!                 We'll return the above values if we don't find
!                 a better match.
!
               end if

            end if

         end do

!
!        Prepare to read the next set of plate IDs, if any.
!
         remain = remain - nread
         i      = i      + nread
         nread  = min ( remain, bufsiz )

      end do

      return
      end associate
      end subroutine zzptpl02

      !> Find nearest intersection to ray's vertex of ray and
      !> a coordinate volume element. If the vertex is inside
      !> the element, the vertex is considered to be the solution.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     VERTEX,
      !>     RAYDIR     are, respectively, the vertex and direction vector of
      !>                the ray to be used in the intercept computation.
      !>
      !>                Both the vertex and ray direction must be represented
      !>                in the reference frame of the segment to which the
      !>                volume element boundaries correspond. The vertex is
      !>                considered to be an offset from the center of the
      !>                reference frame associated with the segment.
      !>
      !>     DSKDSC     is a DSK segment descriptor. The coordinate system
      !>                and spatial boundaries of a the segment are specified
      !>                by members of this descriptor.
      !>
      !>## Detailed Output
      !>
      !>     XPT        is the intercept of the ray on the boundary of the
      !>                input volume element, if such an intercept exists. If
      !>                the ray's vertex is inside the element, XPT is set
      !>                equal to the vertex. XPT is valid if and only if FOUND
      !>                is .TRUE.
      !>
      !>                XPT is expressed in the reference frame associated
      !>                with the inputs VERTEX and RAYDIR. XPT represents
      !>                an offset from the origin of the coordinate system.
      !>
      !>                XPT is valid only if NXPTS is set to 1.
      !>
      !>     NXPTS      is the number of intercept points of the ray and
      !>                the volume element.
      !>
      !>                Currently there are only two possible values for
      !>                NXPTS:
      !>
      !>                   1 for an intersection
      !>                   0 for no intersection
      !>
      !>                If the vertex is inside the element, NXPTS is
      !>                set to 1.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1) If the coordinate system code in the segment descriptor
      !>        is not recognized, the error SPICE(NOTSUPPORTED) will be
      !>        signaled.
      !>
      !>## Files
      !>
      !>     None. However, the input segment boundaries normally have
      !>     been obtained from a loaded DSK file.
      !>
      !>## Particulars
      !>
      !>     This routine sits on top of data DSK type-specific ray-segment
      !>     intercept routines such as DSKX02.
      !>
      !>## Examples
      !>
      !>     See usage in ZZDSKBUX.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 19-JUL-2016 (NJB)
      module subroutine zzrytelt ( ctx, vertex, raydir, dskdsc, margin, nxpts, xpt )
      use pepper_kinds, only: ip, wp
      use pepper_inc_dskdsc
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: vertex ( 3 )  !! Ray's vertex.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      real(wp), intent(in) :: dskdsc ( dskdsz )  !! DSK descriptor of segment.
      real(wp), intent(in) :: margin  !! Margin used for element expansion.
      integer(ip), intent(out) :: nxpts  !! Number of intercept points.
      real(wp), intent(out) :: xpt    ( 3 )  !! Intercept.

      integer(ip) :: corsys

      if ( ctx%failed() ) return

      corsys = nint( dskdsc(sysidx) )

      if ( corsys == latsys ) then

         call zzrytlat ( ctx, vertex, raydir, dskdsc(mn1idx), &
                         margin, nxpts,  xpt              )

      else if ( corsys == recsys ) then

         call zzrytrec ( ctx, vertex, raydir, dskdsc(mn1idx), &
                         margin, nxpts,  xpt              )

      else if ( corsys == pdtsys ) then

         call zzrytpdt ( ctx, vertex,         raydir, &
                         dskdsc(mn1idx), dskdsc(paridx), &
                         margin,         nxpts,          xpt )
      else

         call ctx%setmsg( 'Coordinate system # is not supported.' )
         call ctx%errint( '#', corsys                             )
         call ctx%sigerr( 'SPICE(BADCOORDSYS)'                    )
         return

      end if

      return
      end subroutine zzrytelt

      !> Find the outward unit normal vector at a specified point on the
      !> surface of a body represented by one or more DSK segments. The
      !> set of surface IDs to be considered is specified by the caller.
      !>
      !> This routine uses DSK segments in an unprioritized manner.
      !> All segments meeting the body, time, and surface constraints
      !> are considered.
      !>
      !> Segment descriptor and derived bounding data are passed in.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     BODYID     is the body ID of the target on which the input
      !>                point is located.
      !>
      !>     NSURF,
      !>     SRFLST     are, respectively, the surface list count and
      !>                an array containing a list of surface IDs.
      !>
      !>                If the count is zero, all surfaces for the body
      !>                are considered applicable.
      !>
      !>     ET         is the lookup epoch, specified as seconds past
      !>                J2000 TDB. Only DSK segments containing ET in
      !>                their time coverage intervals are considered
      !>                in the normal vector computation.
      !>
      !>     FIXFID     is the frame ID of a body-fixed reference frame
      !>                centered on the target body.
      !>
      !>     NSEG       is the number of DSK segments for which the input
      !>                buffers contain data.
      !>
      !>     HANBUF     is the DSK handle buffer.
      !>
      !>     DLABUF     is the DLA segment descriptor buffer.
      !>
      !>     DSKBUF     is the DSK segment descriptor buffer.
      !>
      !>     OFFBUF     is the frame offset buffer. For each DSK segment, the
      !>                entry in this buffer is the position of that segment's
      !>                reference frame center relative to the target body's
      !>                center. The vector is expressed in the segment's
      !>                reference frame. Units are km.
      !>
      !>     CTRBUF     is the bounding sphere center buffer. For each DSK
      !>                segment, the entry in this buffer is the position of
      !>                that segment's outer bounding sphere center relative
      !>                to the segment's reference frame center. The vector is
      !>                expressed in the segment's reference frame. Units are
      !>                km.
      !>
      !>     RADBUF     is the bounding sphere radius buffer. For each DSK
      !>                segment, the entry in this buffer is the radius of the
      !>                segment's outer bounding sphere. Units are km.
      !>
      !>     POINT      is a point on the surface of the target body. POINT is
      !>                expressed in the reference frame designated by FIXFID.
      !>                POINT represents an offset from the target body
      !>                center.
      !>
      !>                POINT must be located on the surface of the target
      !>                body, within a small tolerance.
      !>
      !>## Detailed Output
      !>
      !>     NORMAL     is the unit length, outward normal vector on the
      !>                surface of the target body at POINT. NORMAL is
      !>                expressed in the reference frame designated by FIXFID.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input segment count is non-positive, the error
      !>         SPICE(NODSKSEGMENTS) is signaled.
      !>
      !>     2)  If an unrecognized coordinate system code is found
      !>         in a DSK descriptor, the error SPICE(BADCOORDSYS) is
      !>         signaled.
      !>
      !>     3)  PEPPER: no limit on the number of segments containing the
      !>         input point (SPICELIB signaled SPICE(TOOMANYHITS) for more
      !>         than MAXHIT = 1000).
      !>
      !>     4)  If the input point is not contained in any DSK segment,
      !>         the error SPICE(POINTNOTINSEGMENT) is signaled.
      !>
      !>     5)  If an unrecognized segment data type is encountered,
      !>         the error SPICE(NOTSUPPORTED) is signaled.
      !>
      !>     6)  If the input point is not sufficiently close to the
      !>         surface, the error SPICE(POINTOFFSURFACE) will be
      !>         signaled.
      !>
      !>     7)  Any other errors that occur while looking up DSK data or
      !>         mapping the surface point to a normal vector will be signaled
      !>         by routines in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>     Frame kernels may be required in order to perform transformations
      !>     from DSK segment frames to the output frame. In some cases,
      !>     additional kernels such as CK kernels and SCLK kernels could be
      !>     required to support the offset vector lookup.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be called from the DSK API segment
      !>     buffering subsystem. All of the input buffers should contain
      !>     values computed after changes to the set of loaded DSKs.
      !>
      !>     This routine takes advantage of the input segment bound
      !>     information to efficiently determine which segments may contain
      !>     the input point.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 22-FEB-2017 (NJB)
      !>
      !>        Added FAILED calls.
      !>
      !>        07-APR-2016 (NJB)
      !>
      !>        Based on first version 17-DEC-2014 (NJB)
      module subroutine zzdskbun ( ctx, bodyid, nsurf, srflst, et, fixfid, nseg, hanbuf, dlabuf, dskbuf, offbuf, ctrbuf, radbuf, point, normal )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: mtxv, mxv, pltnrm, vdist, vhatip
      use pepper_inc_dla
      use pepper_inc_dskdsc
      use pepper_inc_dsktol
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: bodyid  !! ID code of target body.
      integer(ip), intent(in) :: nsurf  !! Number of IDs in surface list.
      integer(ip), intent(in) :: srflst ( * )  !! List of surface IDs.
      real(wp), intent(in) :: et  !! Lookup epoch, expressed as seconds past J2000 TDB.
      integer(ip), intent(in) :: fixfid  !! Frame ID of body-fixed frame for output vectors.
      integer(ip), intent(in) :: nseg  !! Number of segments in buffers.
      integer(ip), intent(in) :: hanbuf ( * )  !! DSK handle buffer.
      integer(ip), intent(in) :: dlabuf ( dladsz, * )  !! DLA segment descriptor buffer.
      real(wp), intent(in) :: dskbuf ( dskdsz, * )  !! DSK segment descriptor buffer.
      real(wp), intent(in) :: offbuf ( 3,      * )  !! Frame center offset buffer.
      real(wp), intent(in) :: ctrbuf ( 3,      * )  !! Bounding sphere center buffer.
      real(wp), intent(in) :: radbuf ( * )  !! Bounding sphere radius buffer.
      real(wp), intent(in) :: point  ( 3 )  !! Surface point.
      real(wp), intent(out) :: normal ( 3 )  !! Outward unit normal vector at surface point.

      real(wp) :: dist
      real(wp) :: segpt  ( 3 )
      real(wp) :: sgmarg
      real(wp), allocatable :: sgxbuf ( :, :, : )
      real(wp) :: verts  ( 3, 3 )
      real(wp) :: vtemp  ( 3 )
      real(wp) :: xform  ( 3, 3 )

      integer(ip) :: corsys
      integer(ip) :: dtype
      integer(ip) :: i
      integer(ip) :: j
      integer(ip) :: nhit
      integer(ip) :: plate  ( 3 )
      integer(ip) :: plid
      integer(ip) :: prvfrm
      integer(ip) :: segfid
      integer(ip), allocatable :: sghit ( : )
      integer(ip) :: surfce
      integer(ip) :: winner

      logical :: bodyok
      logical :: done
      logical :: inside
      logical :: multfr
      logical :: surfok
      logical :: timeok
      logical :: xfnd

      if ( ctx%failed() ) return

!
!     Check the incoming segment count.
!
      if ( nseg <= 0 ) then

         call ctx%setmsg ( 'Input segment list was empty. This may ' &
         //            'be due to no DSKs containing data for ' &
         //            'body # having been loaded.'            )
         call ctx%errint ( '#',  bodyid                            )
         call ctx%sigerr ( 'SPICE(NODSKSEGMENTS)'                  )
         return

      end if

!
!     PEPPER: at most NSEG segments contain the point (SPICELIB: a
!     buffer of 1000 hits, TOOMANYHITS).
!
      allocate ( sghit(nseg), sgxbuf(3,3,nseg) )

!
!     Get the segment margin from the tolerance database.
!
      call dskgtl ( ctx, keysgr, sgmarg )

!
!     Indicate we haven't yet seen a segment frame different
!     from the one designated by FIXFID.
!
      multfr = .false.

!
!     Make a local copy of the point. We'll update this copy
!     later if need be.
!
      segpt = point

!
!     By default, each segment in the input list must be checked
!     for intersection.
!
!     We start out by trying to eliminate segments from consideration
!     by comparing the point's distance from their centers to the radii
!     of their bounding spheres. Only those segments whose bounding
!     spheres contain the point are examined further.
!
      nhit   = 0
      prvfrm = 0

      do i = 1, nseg
!
!        BODYOK indicates whether the input body ID matches that
!        of the current segment.
!
         surfok = .false.
         timeok = .false.

         bodyok = bodyid == nint( dskbuf(ctridx,i) )

         if ( bodyok ) then
!
!           See whether the current segment contains a surface we're
!           supposed to consider. If the surface list is empty, we
!           consider all surfaces. Otherwise, the surface of the
!           segment must be on the surface list in order to qualify.
!
            j = 0

            if ( nsurf > 0 ) then

               surfce = nint( dskbuf(srfidx,i) )
               j      = findloc(srflst(1:nsurf), surfce, dim=1)

            end if

            surfok = ( nsurf == 0 ) .or. ( j > 0 )

!
!           See whether the segment covers the input epoch.
!
            timeok =        ( et >= dskbuf(btmidx,i) ) &
                      .and. ( et <= dskbuf(etmidx,i) )

         end if

         if ( bodyok .and. surfok .and. timeok  ) then
!
!           This segment is to be considered.
!
!           In order to do any geometric comparison, the point must be
!           in the same frame as the segment we're checking. Transform
!           the point if need be.
!
!           Get the segment's frame ID. Get the transformation from the
!           input frame to the output frame if needed.

            segfid = nint( dskbuf(frmidx,i) )

            if ( segfid /= fixfid ) then
!
!              We have a segment that uses a different frame
!              from that specified by FIXFID.
!
               multfr = .true.

               if ( segfid /= prvfrm ) then
!
!                 The frame of the current segment doesn't match
!                 that of the previous segment, so we'll need
!                 to look up the transformation from the input
!                 frame to the segment frame.
!
!                 Otherwise, XFORM already contains the correct
!                 transformation.
!
                  call refchg ( ctx, fixfid, segfid, et, xform )

                  if ( ctx%failed() ) return

!
!                 Transform the local copy of the point to the segment's
!                 frame, and shift the local copy of the point so
!                 that it represents an offset relative to center of
!                 the segment's frame.
!
                  call mxv  ( xform, point,  segpt  )

!
!                 The direction of the buffered offset is from the body
!                 to the segment frame's center. The offset is
!                 expressed in the segment's frame.
!
                  vtemp = segpt - offbuf(:,i)
                  segpt = vtemp

               end if

            else if ( multfr ) then
!
!              The input and segment frames are the same for this
!              segment, but the current value of SEGPT needs to be
!              reset.
!
               segpt = point

            end if

!
!           Find the distance of the point from the "center" of the
!           segment's coverage volume.
!
            dist = vdist ( ctrbuf(1,i), segpt )

            if ( dist <= radbuf(i) ) then
!
!              The point is inside or on the bounding surface. We'll
!              check the boundary of the segment for an intersection.
!
               corsys = nint( dskbuf(sysidx,i) )

               if ( corsys == latsys ) then

                  call zzinlat ( ctx, segpt,  dskbuf(mn1idx,i), &
                                 sgmarg, 0,                inside )

               else if ( corsys == recsys ) then

                  call zzinrec ( ctx, segpt,  dskbuf(mn1idx,i), &
                                 sgmarg, 0,                inside )

               else if ( corsys == pdtsys ) then

                  call zzinpdt ( ctx, segpt,             dskbuf(mn1idx,i), &
                                 dskbuf(paridx, i), sgmarg, &
                                 0,                 inside           )
               else

                  call ctx%setmsg( 'Coordinate system # is not supported.' )
                  call ctx%errint( '#', corsys                             )
                  call ctx%sigerr( 'SPICE(BADCOORDSYS)'                    )
                  return

               end if

               if ( ctx%failed() ) return

               if ( inside ) then
!
!                 The point in inside the region enclosed by the
!                 boundary of this segment. Save the index of the
!                 segment in the "hit list."
!
                  nhit           = nhit + 1
                  sghit ( nhit ) = i
!
!                 Save the frame transformation for this segment.
!
                  sgxbuf(:,:,nhit) = xform

               end if

            end if
!
!           The current segment matched the input criteria.
!
!           Update the saved segment frame ID to that of the segment
!           we just examined.
!
            prvfrm = segfid

         end if

      end do

!
!     We have an error if no segments were hit. None of that
!     "not found" nonsense here.
!
      if ( nhit == 0 ) then

         call ctx%setmsg ( 'Input point (# # #) in frame # does not ' &
         //            'lie inside any segment for the ' &
         //            'specified body (#) and surfaces.'        )
         call ctx%errdp  ( '#', point(1)                             )
         call ctx%errdp  ( '#', point(2)                             )
         call ctx%errdp  ( '#', point(3)                             )
         call ctx%errint ( '#', fixfid                               )
         call ctx%errint ( '#', bodyid                               )
         call ctx%sigerr ( 'SPICE(POINTNOTINSEGMENT)'                )
         return

      end if

!
!     Now process the segments on the hit list. If we find a segment
!     surface on which the input point is located, we compute the
!     normal vector and terminate the search.
!
      i      = 1
      done   = .false.
      winner = 0
      prvfrm = 0

      do while ( .not. done )
!
!        I is the index in the hit list of the segment
!        we're considering. J is the index of that segment
!        in the parallel input arrays.
!
         j = sghit (i)

         segfid = nint( dskbuf(frmidx,j) )

         if ( segfid /= fixfid ) then

            if ( segfid /= prvfrm ) then
!
!              Transform and shift the input point.
!
!              Here I is an index in the hit list and J is
!              an index in the input arrays.
!
               xform = sgxbuf(:,:,i)

               call mxv  ( xform, point, segpt )

               vtemp = segpt - offbuf(:,j)
               segpt = vtemp

            end if

         else if ( multfr ) then

            segpt = point

         end if

!
!        If the point lies on the surface described by the
!        current segment, find the outward unit normal
!        vector at the point.
!
         dtype = nint( dskbuf(typidx,j) )
         xfnd  = .false.

         if ( dtype == 2 ) then
!
!           Find the plate on which the point lies, if any.
!
            call zzptpl02 ( ctx, hanbuf(j), dlabuf(1,j), dskbuf(1,j), segpt, &
                            plid,      plate,       verts,       xfnd  )

            if ( ctx%failed() ) return

            if ( xfnd ) then
!
!              Find the unit outward normal at SEGPT. We must
!              convert the output of PLTNRM to unit length.
!
               call pltnrm ( verts(1,1), verts(1,2), verts(1,3), &
                             normal                              )
               if ( ctx%failed() ) return

               call vhatip ( normal )
!
!              WINNER is the index in the hit list of the current
!              segment.
!
               winner = i
               done   = .true.

            end if

         else

            call ctx%setmsg ( 'Segment type is #; this type is not ' &
            //            'currently supported.'                )
            call ctx%errint ( '#', dtype                            )
            call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                 )
            return

         end if

         if ( ctx%failed() ) return

         if ( .not. done ) then

            if ( i == nhit ) then
!
!              We've looked at all of the segments.
!
               done = .true.

            else
!
!              Consider the next segment.
!
               i = i + 1

            end if

         end if

      end do

!
!     If we have an result, it may be represented in a frame
!     other than the input point frame. Transform it back to the
!     input frame, if need be.
!
      if ( xfnd ) then
!
!        J is the index in the input arrays of the "winning" segment.
!
         j      = sghit ( winner )

         segfid = nint( dskbuf(frmidx,j) )

         if ( segfid /= fixfid ) then
!
!           The segment frame and input frame differ. The normal
!           vector must be converted back to the input frame.
!
            xform = sgxbuf(:,:,winner)

            call mtxv ( xform, normal, vtemp  )
            normal = vtemp

         end if

      else
!
!        The input point was not legitimate; otherwise we
!        would have found a solution.
!
         call ctx%setmsg ( 'Input point (# # #) in frame # does not ' &
         //            'lie on the surface contained in any ' &
         //            'segment for the specified body (#) ' &
         //            'and surfaces.'                           )
         call ctx%errdp  ( '#', point(1)                             )
         call ctx%errdp  ( '#', point(2)                             )
         call ctx%errdp  ( '#', point(3)                             )
         call ctx%errint ( '#', fixfid                               )
         call ctx%errint ( '#', bodyid                               )
         call ctx%sigerr ( 'SPICE(POINTOFFSURFACE)'                  )
         return

      end if

      return
      end subroutine zzdskbun

      !> Find the intersection of a ray and the surface described by
      !> a single DSK segment.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     HANDLE     is the handle of a DSK file containing a segment
      !>                to be used in a ray-surface intercept computation.
      !>
      !>     DLASDC     is the DLA descriptor of the DSK segment to be used.
      !>
      !>     DTYPE      is the data type code of the segment. While this
      !>                information can be retrieved from the DSK descriptor
      !>                of the segment, the availability of this argument
      !>                saves the time needed to do so.
      !>
      !>     ET         is the epoch of the intersection computation,
      !>                expressed as seconds past J2000 TDB. This epoch is
      !>                used for DSK segment selection.
      !>
      !>     VERTEX,
      !>     RAYDIR     are, respectively, the vertex and direction vector of
      !>                the ray to be used in the intercept computation.
      !>
      !>                Both the vertex and ray's direction vector must be
      !>                represented in the reference frame of the segment. The
      !>                vertex is considered to be an offset from the center
      !>                of the reference frame associated with the segment.
      !>
      !>## Detailed Output
      !>
      !>     XPT        is the intercept of the ray on the surface described
      !>                by the segment, if such an intercept exists. If the
      !>                ray intersects the surface at multiple points, the
      !>                one closest to the ray's vertex is selected. XPT is
      !>                valid if and only if FOUND is .TRUE.
      !>
      !>                XPT is expressed in the reference frame associated
      !>                with the specified segment. It represents an offset
      !>                from the center of this frame. Note that the frame
      !>                center may differ from the central body of the
      !>                segment.
      !>
      !>     DC         is the double precision component of the data
      !>                source information. Contents are data type-
      !>                dependent. DC is valid if and only if FOUND
      !>                is .TRUE.
      !>
      !>     IC         is the integer component of the data
      !>                source information. Contents are data type-
      !>                dependent. IC is valid if and only if FOUND
      !>                is .TRUE.
      !>
      !>                For type 2 segments, IC contains just the
      !>                intercept plate ID in element 1.
      !>
      !>     FOUND      is a logical flag that is set to .TRUE. if and only
      !>                if a ray-surface intercept was found.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the DSK segment data type is not recognized, the error
      !>         SPICE(TYPENOTSUPPORTED) is signaled.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data are required:
      !>
      !>        - DSK data: the DSK file designated by HANDLE and containing
      !>          the segment having the DLA descriptor DLADSC must be loaded
      !>          at the time this routine is called.
      !>
      !>     Kernel data are normally loaded once per program run, NOT every
      !>     time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine sits on top of data DSK type-specific ray-segment
      !>     intercept routines such as DSKX02.
      !>
      !>## Examples
      !>
      !>     See usage in ZZDSKBUX.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 18-FEB-2016 (NJB)
      !>
      !>        Based on first version 20-JAN-2015 (NJB)
      module subroutine zzdsksgx ( ctx, handle, dladsc, dtype, et, vertex, raydir, xpt, dc, ic, found )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: handle  !! DSK file handle.
      integer(ip), intent(in) :: dladsc ( * )  !! DLA descriptor of segment.
      integer(ip), intent(in) :: dtype  !! Data type code.
      real(wp), intent(in) :: et  !! Epoch, expressed as seconds past J2000 TDB.
      real(wp), intent(in) :: vertex ( 3 )  !! Ray's vertex.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      real(wp), intent(out) :: xpt    ( 3 )  !! Surface intercept, if found.
      real(wp), intent(out) :: dc     ( * )  !! D.p. component of source info.
      integer(ip), intent(out) :: ic     ( * )  !! Integer component of source info.
      logical, intent(out) :: found  !! Found flag.

      real(wp) :: retval

      integer(ip) :: plid

      if ( ctx%failed() ) return

!
!     Note: input argument ET is provided to support time-dependent
!     data types.
!
      retval = (et)
      dc(1)  = (dc(1))

      if ( dtype == 2 ) then
!
!        The intercept plate ID is returned in element 1 of
!        IC, if an intercept is found.
!
         call dskx02 ( ctx, handle, dladsc, vertex, &
                       raydir, plid,   xpt,    found )

         if ( found ) then
            ic(1) = plid
         end if

      else

         call ctx%setmsg ( 'DSK ray-surface intercepts are not ' &
         //            'supported for DSK data type #.'     )
         call ctx%errint ( '#', dtype                           )
         call ctx%sigerr ( 'SPICE(TYPENOTSUPPORTED)'            )
         return

      end if

      return
      end subroutine zzdsksgx

      !> Find a ray-surface intercept on the surface of a body represented
      !> by one or more DSK segments. If multiple intercepts exist, select
      !> the one closest to the ray's vertex. The set of surface IDs to be
      !> considered is specified by the caller.
      !>
      !> This routine uses DSK segments in an unprioritized manner.
      !> All segments meeting the body, time, and surface constraints
      !> are considered.
      !>
      !> Segment descriptor and derived bounding data are passed in.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     BODYID     is the body ID of the target on which the input
      !>                point is located.
      !>
      !>     NSURF,
      !>     SRFLST     are, respectively, the surface list count and
      !>                an array containing a list of surface IDs.
      !>
      !>                If the count is zero, all surfaces for the body
      !>                are considered applicable.
      !>
      !>     ET         is the lookup epoch, specified as seconds past
      !>                J2000 TDB. Only DSK segments containing ET in
      !>                their time coverage intervals are considered
      !>                in the normal vector computation.
      !>
      !>     FIXFID     is the frame ID of a body-fixed reference frame
      !>                centered on the target body.
      !>
      !>     NSEG       is the number of DSK segments for which the input
      !>                buffers contain data.
      !>
      !>     HANBUF     is the DSK handle buffer.
      !>
      !>     DLABUF     is the DLA segment descriptor buffer.
      !>
      !>     DSKBUF     is the DSK segment descriptor buffer.
      !>
      !>     OFFBUF     is the frame offset buffer. For each DSK segment, the
      !>                entry in this buffer is the position of that segment's
      !>                reference frame center relative to the target body's
      !>                center. The vector is expressed in the segment's
      !>                reference frame. Units are km.
      !>
      !>     CTRBUF     is the bounding sphere center buffer. For each DSK
      !>                segment, the entry in this buffer is the position of
      !>                that segment's outer bounding sphere center relative
      !>                to the segment's reference frame center. The vector is
      !>                expressed in the segment's reference frame. Units are
      !>                km.
      !>
      !>     RADBUF     is the bounding sphere radius buffer. For each DSK
      !>                segment, the entry in this buffer is the radius of the
      !>                segment's outer bounding sphere. Units are km.
      !>
      !>     VERTEX,
      !>     RAYDIR     are, respectively, the vertex and direction vector of
      !>                the ray to be used in the intercept computation.
      !>
      !>                Both the vertex and ray must be represented in the
      !>                reference frame designated by FIXFID. The vertex is
      !>                considered to be an offset from the target body.
      !>
      !>## Detailed Output
      !>
      !>     XPT        is the surface intercept, if an intercept exists. If
      !>                multiple intercepts exist, the one closest to the
      !>                ray's vertex is selected. XPT is represented in the
      !>                reference frame designated by FIXFID. XPT is
      !>                considered to be an offset from the target body.
      !>
      !>     SEGIDX     is the index, within the input buffer arguments, of
      !>                the segment providing the surface data on which XPT
      !>                was found. SEGIDX is valid if and only if FOUND is
      !>                .TRUE.
      !>
      !>     FOUND      is a logical flag that is .TRUE. if and only if a
      !>                ray-surface intercept was found.
      !>
      !>## Parameters
      !>
      !>     SGREED     is the default margin used to determine whether
      !>                segments should be tested for intersection. Segments
      !>                are effectively expanded slightly for intersection
      !>                tests, using this margin. For example, if a segment
      !>                has latitudinal coordinates, and if the ray hits the
      !>                eastern longitude boundary of the segment, the
      !>                latitude of this intercept is within the segment's
      !>                latitude bounds, RMAX is the segment's maximum radius,
      !>                and the radius R of the intercept satisfies
      !>
      !>                   RMAX < R < RMAX * (1+SGREED)
      !>
      !>                then the intercept is considered to be "on" the
      !>                segment's boundary, and the segment's surface data
      !>                are tested for intersection.
      !>
      !>                See the routines that test points for inclusion in
      !>                segments for details concerning use of the segment
      !>                margin. For latitudinal, planetodetic, and
      !>                rectangular coordinates respectively, these are
      !>
      !>                   ZZINLAT
      !>                   ZZINPDT
      !>                   ZZINREC
      !>
      !>                See the include file dsktol.inc for the value of
      !>                this parameter.
      !>
      !>                This parameter can be overridden. See the include
      !>                file dsktol.inc and the routine DSKSTL for details.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input segment count is non-positive, the error
      !>         SPICE(NODSKSEGMENTS) is signaled.
      !>
      !>     2)  If an unrecognized coordinate system code is found
      !>         in a DSK descriptor, the error SPICE(BADCOORDSYS) is
      !>         signaled.
      !>
      !>     3)  PEPPER: no limit on the number of segments containing the
      !>         input point (SPICELIB signaled SPICE(BUFFERTOOSMALL) for more
      !>         than MAXHIT = 1000).
      !>
      !>     4)  Any other errors that occur while looking up DSK data or
      !>         mapping the surface point to a normal vector will be signaled
      !>         by routines in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>     Frame kernels may be required in order to perform transformations
      !>     from DSK segment frames to the output frame. In some cases,
      !>     additional kernels such as CK kernels and SCLK kernels could be
      !>     required to support the offset vector lookup.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be called from the DSK API segment
      !>     buffering subsystem. All of the input buffers should contain
      !>     values computed after changes to the set of loaded DSKs.
      !>
      !>     This routine takes advantage of the input segment bound
      !>     information to efficiently determine which segments may be
      !>     intersected by the input ray.
      !>
      !>     This routine uses DSK data in an unprioritized fashion: all
      !>     DSK segments having the required body, surface, and time
      !>     attributes are considered in the computation.
      !>
      !>## Examples
      !>
      !>     None.
      !>
      !>## Restrictions
      !>
      !>     This is a private routine. It is meant to be used only by the DSK
      !>     subsystem.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman    (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 19-JUL-2016 (NJB)
      !>
      !>        30-JAN-2015 (NJB)
      !>
      !>        Updated argument list: now returns segment
      !>        index and source info arrays. Added header.
      !>        Added support for rectangular coordinates.
      !>
      !>        30-JAN-2015 (NJB)
      !>
      !>        Updated to accommodate change in argument list of
      !>        ZZDSKSPH.
      !>
      !>        28-JAN-2015 (NJB)
      !>
      !>        Now uses outer bounding sphere to produce vertex near the
      !>        target for individual ray-segment intercept computations.
      !>
      !>        17-DEC-2014 (NJB)
      !>
      !>        Updated to allow DSK segments to use body-fixed frames
      !>        not centered on the target.
      !>
      !>        10-OCT-2014 (NJB)
      !>
      !>        First version.
      module subroutine zzdskbux ( ctx, bodyid, nsurf, srflst, et, fixfid, nseg, hanbuf, dlabuf, dskbuf, offbuf, ctrbuf, radbuf, vertex, raydir, xpt, segidx, dc, ic, found )
      use pepper_kinds, only: ip, wp
      use pepper_arrays, only: orderd
      use pepper_math, only: mtxv, mxv, vdist, vnorm
      use pepper_inc_dla
      use pepper_inc_dskdsc
      use pepper_inc_dsktol
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: bodyid  !! ID code of target body.
      integer(ip), intent(in) :: nsurf  !! Number of IDs in surface list.
      integer(ip), intent(in) :: srflst ( * )  !! List of surface IDs.
      real(wp), intent(in) :: et  !! Lookup epoch, expressed as seconds past J2000 TDB.
      integer(ip), intent(in) :: fixfid  !! Frame ID of body-fixed frame for output vectors.
      integer(ip), intent(in) :: nseg  !! Number of segments in buffers.
      integer(ip), intent(in) :: hanbuf ( * )  !! DSK handle buffer.
      integer(ip), intent(in) :: dlabuf ( dladsz, * )  !! DLA segment descriptor buffer.
      real(wp), intent(in) :: dskbuf ( dskdsz, * )  !! DSK segment descriptor buffer.
      real(wp), intent(in) :: offbuf ( 3,      * )  !! Frame center offset buffer.
      real(wp), intent(in) :: ctrbuf ( 3,      * )  !! Bounding sphere center buffer.
      real(wp), intent(in) :: radbuf ( * )  !! Bounding sphere radius buffer.
      real(wp), intent(in) :: vertex ( 3 )  !! Ray's vertex.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      real(wp), intent(out) :: xpt    ( 3 )  !! Intercept point.
      integer(ip), intent(out) :: segidx  !! Index of segment in input buffers.
      real(wp), intent(out) :: dc     ( * )  !! D.p. component of source info.
      integer(ip), intent(out) :: ic     ( * )  !! Integer component of source info.
      logical, intent(out) :: found  !! Found flag. True if and only if intercept exists.

      real(wp), parameter :: radscl = 1.01_wp

      real(wp) :: dist
      real(wp) :: dmin
      real(wp) :: maxrad
      real(wp) :: minrad
      real(wp) :: segdir ( 3 )
      real(wp) :: segvtx ( 3 )
      real(wp) :: pnear  ( 3 )
      real(wp), allocatable :: sgdist ( : )
      real(wp) :: sgmarg
      real(wp), allocatable :: sgxbuf ( :, :, : )
      real(wp) :: sphvtx ( 3 )
      real(wp) :: srfx   ( 3 )
      real(wp) :: vtemp  ( 3 )
      real(wp) :: xform  ( 3, 3 )

      integer(ip) :: dtype
      integer(ip) :: i
      integer(ip), allocatable :: iorder ( : )
      integer(ip) :: j
      integer(ip) :: k
      integer(ip) :: nhit
      integer(ip) :: nxpts
      integer(ip) :: prvfrm
      integer(ip) :: segfid
      integer(ip), allocatable :: sghit ( : )
      integer(ip) :: surfce
      integer(ip) :: winner

      logical :: bodyok
      logical :: done
      logical :: multfr
      logical :: surfok
      logical :: timeok
      logical :: xfnd

      if ( ctx%failed() ) return

!
!     Check the incoming segment count.
!
      if ( nseg <= 0 ) then

         call ctx%setmsg ( 'Input segment list was empty. This may ' &
         //            'be due to no DSKs containing data for ' &
         //            'body # having been loaded.'            )
         call ctx%errint ( '#',  bodyid                            )
         call ctx%sigerr ( 'SPICE(NODSKSEGMENTS)'                  )
         return

      end if

!
!     PEPPER: at most NSEG segments contain the point (SPICELIB: a
!     buffer of 1000 hits, BUFFERTOOSMALL).
!
      allocate ( iorder(nseg), sgdist(nseg), sghit(nseg), sgxbuf(3,3,nseg) )

!
!     No intercept has been found.
!
      segidx = 0
      found  = .false.

!
!     Indicate we haven't yet seen a segment frame different
!     from the one designated by FIXFID.
!
      multfr = .false.

!
!     Obtain the "greedy" segment margin.
!
      call dskgtl ( ctx, keysgr, sgmarg )

!
!     Make a local copy of the ray. We'll update this copy
!     later if need be.
!
      segvtx = vertex
      segdir = raydir

!
!     Obtain the radius of an outer bounding sphere for the given body
!     and surface list.
!
      call zzdsksph ( ctx, bodyid, nsurf, srflst, minrad, maxrad )

      if ( ctx%failed() ) return
!
!     Scale up the bounding sphere to avoid round-off difficulties.
!     We'll use this value in the loop below.
!
      maxrad = maxrad * radscl

!
!     If the ray's vertex is distant from the target, use a vertex on
!     the surface of the outer bounding sphere of the target.
!
!     Note that distant vertices can give rise to large transverse
!     displacements of the ray's intercepts on the segments'
!     boundaries. In cases where the ray intercept is very close to the
!     segment's spatial coverage boundaries, this can cause the ray to
!     miss all plates in type 2 segments, unless a large plate
!     expansion factor is used. Using an intercept on the outer
!     bounding sphere greatly ameliorates this problem.
!
      if ( vnorm(segvtx) > maxrad ) then
!
!        Find the intercept of the ray with the outer bounding
!        sphere. We'll use this intercept as the vertex for
!        later computations.
!
         call surfpt ( ctx, segvtx, segdir, maxrad, &
                       maxrad, maxrad, sphvtx, xfnd )

         if ( ctx%failed() .or. ( .not. xfnd ) ) then
!
!           It would be highly unusual for the SURFPT call to
!           fail to produce an intercept. Check anyway.
!
            return

         end if

         segvtx = sphvtx

      end if

!
!     By default, each segment in the input list must be checked
!     for intersection.
!
!     We start out by trying to eliminate segments from consideration
!     by comparing the ray's distance from their centers to the radii
!     of their bounding spheres. Only those segments whose bounding
!     spheres are hit are examined further.
!
      nhit   = 0
      prvfrm = 0

      do i = 1, nseg
!
!        BODYOK indicates whether the input body ID matches that
!        of the current segment.
!
         surfok = .false.
         timeok = .false.

         bodyok = bodyid == nint( dskbuf(ctridx,i) )

         if ( bodyok ) then
!
!           See whether the current segment contains a surface we're
!           supposed to consider. If the surface list is empty, we
!           consider all surfaces. Otherwise, the surface of the
!           segment must be on the surface list in order to qualify.
!
            j = 0

            if ( nsurf > 0 ) then

               surfce = nint( dskbuf(srfidx,i) )
               j      = findloc(srflst(1:nsurf), surfce, dim=1)

            end if

            surfok = ( nsurf == 0 ) .or. ( j > 0 )

!
!           See whether the segment covers the input epoch.
!
            timeok =        ( et >= dskbuf(btmidx,i) ) &
                      .and. ( et <= dskbuf(etmidx,i) )

         end if

         if ( bodyok .and. surfok .and. timeok  ) then
!
!           This segment is to be considered.
!
!           In order to do any geometric comparison, the ray must be in
!           the same frame as the segment we're checking. Transform the
!           input vertex and ray if need be.
!
!           Get the segment's frame ID. Get the transformation from the
!           input frame to the output frame if needed.

            segfid = nint( dskbuf(frmidx,i) )

            if ( segfid /= fixfid ) then
!
!              We have a segment that uses a different frame
!              from that specified by FIXFID.
!
               multfr = .true.

               if ( segfid /= prvfrm ) then
!
!                 The frame of the current segment doesn't match
!                 that of the previous segment, so we'll need
!                 to look up the transformation from the input
!                 frame to the segment frame.
!
!                 Otherwise, XFORM already contains the correct
!                 transformation.
!
                  call refchg ( ctx, fixfid, segfid, et, xform )

                  if ( ctx%failed() ) return

!
!                 Transform the local copy of the ray to the segment's
!                 frame, and shift the local copy of the ray's vertex
!                 so that it represents an offset relative to center of
!                 the segment's frame.
!
                  call mxv  ( xform, raydir, segdir )
                  call mxv  ( xform, vertex, segvtx )

!
!                 The direction of the buffered offset is from the body
!                 to the segment frame's center. The offset is
!                 expressed in the segment's frame.
!
                  vtemp = segvtx - offbuf(:,i)
                  segvtx = vtemp

               end if

            else if ( multfr ) then
!
!              The input and segment frames are the same for this
!              segment, but the current values of SEGVTX and SEGDIR
!              need to be reset.
!
               segvtx = vertex
               segdir = raydir

            end if

!
!           Find the distance of the ray from the "center" of the
!           segment's coverage volume.
!
            call nplnpt ( ctx, segvtx, segdir, ctrbuf(1,i), pnear, dist )

            if ( dist <= radbuf(i) ) then
!
!              The line containing the ray intersects the bounding
!              surface. We'll check the boundary of the segment for an
!              intersection.
!
               call zzrytelt ( ctx, segvtx, segdir, dskbuf(1,i), &
                               sgmarg, nxpts,  xpt         )

               if ( ctx%failed() ) return

               if ( nxpts > 0 ) then
!
!                 The ray hits the boundary of this segment. Save the
!                 index of the segment in the "hit list." Record the
!                 distance from the ray's vertex to the intercept in
!                 the parallel array SGDIST.

                  nhit           = nhit + 1
                  sghit ( nhit ) = i
                  sgdist( nhit ) = vdist( segvtx, xpt )
!
!                 Save the frame transformation for this segment.
!
                  sgxbuf(:,:,nhit) = xform

               end if

            end if
!
!           The current segment matched the input criteria.
!
!           Update the saved segment frame ID to that of the segment
!           we just examined.
!
            prvfrm = segfid

         end if

      end do

!
!     Leave now if no segments were hit.
!
      if ( nhit == 0 ) return

!
!     Find the order of the segments on the hit list, where
!     the metric is the distance of the ray intercepts from
!     the ray's vertex.
!
      call orderd ( sgdist, nhit, iorder )

!
!     Now process the segments on the hit list in order. If we find a
!     surface intercept (that is, a ray intercept with the surface
!     represented by the segment's data, as opposed to the segment's
!     boundary), compare its distance from the ray's vertex to the
!     vertex-boundary distance of the next segment. If the
!     vertex-surface distance is smaller, we terminate the search,
!     since no other segment can contribute a closer intercept.
!
      i      = 1
      done   = .false.
      winner = 0
      prvfrm = 0

      do while ( .not. done )
!
!        J is the index in the hit list of the segment
!        we're considering. K is the index of that segment
!        in the parallel input arrays.
!
         j = iorder(i)
         k = sghit (j)

         segfid = nint( dskbuf(frmidx,k) )

         if ( segfid /= fixfid ) then

            if ( segfid /= prvfrm ) then
!
!              Transform and shift the input ray.
!
!              Here J is an index in the hit list and K is
!              an index in the input arrays.
!
               xform = sgxbuf(:,:,j)

               call mxv  ( xform,  vertex, segvtx )
               call mxv  ( xform,  raydir, segdir )

               vtemp = segvtx - offbuf(:,k)
               segvtx = vtemp

            end if

         else if ( multfr ) then

            segvtx = vertex
            segdir = raydir

         end if

!
!        Find the surface intercept using the segment topography
!        data.
!
         dtype = nint( dskbuf(typidx,k) )

         call zzdsksgx ( ctx, hanbuf(k), dlabuf(1,k), dtype, et, &
                         segvtx,    segdir,      srfx,  dc, &
                         ic,        xfnd                   )

         if ( ctx%failed() ) return

         if ( xfnd ) then
!
!           At least one surface intercept exists.
!
            if ( .not. found ) then
!
!              The intercept we just found is the first one, and
!              at least for now, it is the winner.
!
!              Save the intercept and vertex-intercept distance
!              for this segment.
!
               found  = .true.
               dmin   = vdist( srfx, segvtx )

               xpt = srfx

               winner = j

            else
!
!              At least one surface intercept was found already.
!
!              Compare the vertex-intercept distance for this segment
!              to the best found so far.
!
               dist = vdist( srfx, segvtx )

               if ( dist < dmin ) then
!
!                 This intercept is closer to the ray's vertex than
!                 any we've seen yet. We have a new winner.
!
                  dmin   = dist

                  xpt = srfx

                  winner = j

               end if

            end if

         end if

!
!        If there's at least one solution in hand, see whether
!        we can stop looking for better solutions.
!
         if ( found ) then

            if ( i < nhit ) then
!
!              There are more segments in the hit list. Compare the
!              minimum vertex-intercept distance of the segments we've
!              checked to the vertex-boundary distance of the next
!              segment.
!
               j = iorder(i+1)

               if ( dmin <= sgdist(j) ) then
!
!                 The best intercept we've found is closer to the
!                 vertex than any intercept that may exist in the
!                 current segment, or any of the remaining segments in
!                 the hit list.
!
                  done  = .true.

               end if

            end if

         end if

         if ( .not. done ) then

            if ( i == nhit ) then
!
!              We've looked at all of the segments.
!
               done = .true.

            else
!
!              Consider the next segment.
!
               i = i + 1

            end if

         end if

      end do

!
!     If we have an intercept, it may be represented in a frame
!     other than the input ray frame. Transform it back to the
!     input frame, and shift it as well if the segment frame and
!     input frame have different centers.
!
      if ( found ) then
!
!        K is the index in the input arrays of the "winning" segment.
!        We'll return this index as SEGIDX.
!
         k      = sghit ( winner )
         segidx = k

         segfid = nint( dskbuf(frmidx,k) )

         if ( segfid /= fixfid ) then
!
!           The segment frame and input frame differ. The intercept
!           must be converted back to the input frame. It also may
!           need to be shifted so that it is expressed as an offset
!           from the target body. If the shift is done, it must be
!           done before the frame transformation, since the offset
!           is expressed relative to the segment's frame.
!
            if ( .not. all(offbuf(:,k) == 0.0_wp) ) then
!
!              OFFBUF(*,K) contains the offset of the segment frame
!              center from the segment's central body.
!
               vtemp = xpt + offbuf(:,k)
               xpt = vtemp

            end if

            xform = sgxbuf(:,:,winner)

            call mtxv ( xform, xpt, vtemp )
            xpt = vtemp

         end if

      end if
!
!     FOUND and XPT are set.
!
      return
      end subroutine zzdskbux

      !> Prepare and execute unprioritized ray-surface intercept
      !> computation using DSK API segment buffers.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     BODYID     is the ID code of a target body. The ray-surface
      !>                intercept computation is performed using data
      !>                that represent the surface of this body.
      !>
      !>     NSURF,
      !>     SRFLST     are, respectively, a count of surface IDs and
      !>                a list of IDs. If the list is non-empty, only
      !>                the indicated surfaces will be used. If the
      !>                list is empty, all surfaces associated with the
      !>                input body ID will be considered.
      !>
      !>     ET         is the epoch for which the computation is to be
      !>                performed. This epoch is used for DSK segment
      !>                selection; only segments containing ET in their time
      !>                coverage interval will be used. ET is expressed as
      !>                seconds past J2000 TDB.
      !>
      !>     FIXFID     is the frame ID of a body-fixed frame associated
      !>                with the body designated by BODYID. This frame
      !>                is used to express the input ray's vertex and
      !>                direction vector. The output intercept will be
      !>                expressed in this frame as well.
      !>
      !>     VERTEX,
      !>     RAYDIR     are, respectively, the vertex and direction vector
      !>                of a ray. Both vectors are expressed in the frame
      !>                designated by FIXFID.
      !>
      !>## Detailed Output
      !>
      !>     XPT        is the surface intercept on the target body
      !>                nearest to the ray's vertex, if the intercept
      !>                exists.
      !>
      !>     FOUND      is a logical flag that is set to .TRUE. if and
      !>                only if an intercept exists.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If this routine is called directly, it signals the error
      !>         SPICE(BOGUSENTRY).
      !>
      !>     See the entry points for descriptions of errors specific to
      !>     those routines.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by the DSK subsystem.
      !>
      !>     This routine prepares the local buffers for a ray-surface
      !>     intercept computation using unprioritized DSK data.
      !>     It calls ZZDSKBUX to perform the computation.
      !>
      !>## Examples
      !>
      !>     See usage in ZZRAYSFX.
      !>
      !>## Restrictions
      !>
      !>     1) This is a private routine.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 22-FEB-2017 (NJB)
      !>
      !>        Added FAILED calls.
      !>
      !>        12-MAY-2016 (NJB)
      module subroutine zzsbfxr ( ctx, bodyid, nsurf, srflst, et, fixfid, vertex, raydir, xpt, found )
      use pepper_kinds, only: ip, wp
      use pepper_inc_dla
      use pepper_inc_dskdsc
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: bodyid  !! ID code of target body.
      integer(ip), intent(in) :: nsurf  !! Number of surface IDs in list.
      integer(ip), intent(in) :: srflst ( * )  !! Surface ID list.
      real(wp), intent(in) :: et  !! Evaluation epoch, seconds past J2000 TDB.
      integer(ip), intent(in) :: fixfid  !! Frame ID of ray and intercept.
      real(wp), intent(in) :: vertex ( 3 )  !! Ray's vertex.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      real(wp), intent(out) :: xpt    ( 3 )  !! Surface intercept point.
      logical, intent(out) :: found  !! Found flag. True if intercept exists.
      integer(ip) :: stsize
      real(wp) :: locdc  ( maxdc )
      integer(ip) :: bix
      integer(ip) :: j
      integer(ip) :: locic  ( maxic )
      integer(ip) :: nseg
      integer(ip) :: segidx
      logical :: update
!
!     PEPPER: the segment table grows to hold the body's segments.
!
      call zzdsksbf_room ( ctx, bodyid )
      stsize = size ( ctx%zzdsksbf_state%sthan, kind=ip )
      associate ( bsrctr => ctx%zzdsksbf_state%bsrctr, &
                  btbody => ctx%zzdsksbf_state%btbody, &
                  btnbod => ctx%zzdsksbf_state%btnbod, &
                  btsegp => ctx%zzdsksbf_state%btsegp, &
                  btstsz => ctx%zzdsksbf_state%btstsz, &
                  first => ctx%zzdsksbf_state%first, &
                  stctr => ctx%zzdsksbf_state%stctr, &
                  stdlad => ctx%zzdsksbf_state%stdlad, &
                  stdscr => ctx%zzdsksbf_state%stdscr, &
                  stfree => ctx%zzdsksbf_state%stfree, &
                  sthan => ctx%zzdsksbf_state%sthan, &
                  stoff => ctx%zzdsksbf_state%stoff, &
                  strad => ctx%zzdsksbf_state%strad )
      if ( ctx%failed() ) return

      if ( first ) then
!
!        Initialize BSR counter.
!
         call zzctruin ( ctx, bsrctr )

         first = .false.

      end if

!
!     See whether the state of the loaded DSK set has changed
!     since the last call.
!
      call zzdskchk ( ctx, bsrctr, update )

      if ( update ) then
!
!        Make sure the ZZDSKBSR subsystem has completed the segment
!        list for the input body since the last time the BSR loaded
!        kernel state changed.
!
         call zzdskbbl ( ctx, bodyid )

!
!        Initialize the local buffers. We restart from scratch
!        each time the BSR loaded kernel state changes.
!
         call zzdsksbi ( ctx, btsize, stsize, btbody, btnbod, btsegp, &
                         btstsz, sthan,  stdscr, stdlad, stfree, &
                         stoff,  stctr,  strad                  )
      end if

      if ( ctx%failed() ) return

!
!     Find the index of the input body ID in the body table. If
!     we re-initialized the tables, the index will be zero.
!
      bix = findloc(btbody(1:btnbod), bodyid, dim=1)

      if ( bix == 0 ) then
!
!        We don't have buffered information for this body. Update
!        the body and segment tables to store data for it.
!
         call zzdsksba ( ctx, bodyid, &
                         btsize, stsize, btbody, btnbod, btsegp, &
                         btstsz, sthan,  stdscr, stdlad, stfree, &
                         stoff,  stctr,  strad                  )

         if ( ctx%failed() ) return
!
!        The new body's position in the body table is at the end.
!
         bix = btnbod

      end if

!
!     Find the ray-surface intercept, using the buffered segment
!     data.
!
      j    = btsegp(bix)
      nseg = btstsz(bix)

      call zzdskbux ( ctx, bodyid,     nsurf,      srflst, et,  fixfid, &
                      nseg,       sthan(j),   stdlad(1,j), stdscr(1,j), &
                      stoff(1,j), stctr(1,j), strad(j),    vertex, &
                      raydir,     xpt,        segidx,      locdc, &
                      locic,      found                               )

      return
      end associate
      end subroutine zzsbfxr

      !> Prepare and execute unprioritized ray-surface intercept
      !> computation using DSK API segment buffers. Return source
      !> information including handle, DLA descriptor, and
      !> segment-specific information such as plate ID.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     BODYID     is the ID code of a target body. The ray-surface
      !>                intercept computation is performed using data
      !>                that represent the surface of this body.
      !>
      !>     NSURF,
      !>     SRFLST     are, respectively, a count of surface IDs and
      !>                a list of IDs. If the list is non-empty, only
      !>                the indicated surfaces will be used. If the
      !>                list is empty, all surfaces associated with the
      !>                input body ID will be considered.
      !>
      !>     ET         is the epoch for which the computation is to be
      !>                performed. This epoch is used for DSK segment
      !>                selection; only segments containing ET in their time
      !>                coverage interval will be used. ET is expressed as
      !>                seconds past J2000 TDB.
      !>
      !>     FIXFID     is the frame ID of a body-fixed frame associated
      !>                with the body designated by BODYID. This frame
      !>                is used to express the input ray's vertex and
      !>                direction vector. The output intercept will be
      !>                expressed in this frame as well.
      !>
      !>     VERTEX,
      !>     RAYDIR     are, respectively, the vertex and direction vector
      !>                of a ray. Both vectors are expressed in the frame
      !>                designated by FIXFID.
      !>
      !>## Detailed Output
      !>
      !>     XPT        is the surface intercept on the target body
      !>                nearest to the ray's vertex, if the intercept
      !>                exists.
      !>
      !>     HANDLE     is the handle of the DSK file that contributed
      !>                the segment in which the intercept was found.
      !>
      !>     DLADSC     is the DLA descriptor of the segment in which
      !>                the intercept was found.
      !>
      !>     DSKDSC     is the DSK descriptor of the segment in which
      !>                the intercept was found.
      !>
      !>     DC         is the double precision component of the source
      !>                data associated with the intercept.
      !>
      !>     IC         is the integer component of the source
      !>                data associated with the intercept.
      !>
      !>                   For type 2 segments, this component contains
      !>                   a plate ID in the first element.
      !>
      !>     FOUND      is a logical flag that is set to .TRUE. if and
      !>                only if an intercept exists. The other outputs
      !>                are valid if and only if FOUND is .TRUE.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If this routine is called directly, it signals the error
      !>         SPICE(BOGUSENTRY).
      !>
      !>     See the entry points for descriptions of errors specific to
      !>     those routines.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by the DSK subsystem.
      !>
      !>     This routine prepares the local buffers for a ray-surface
      !>     intercept computation using unprioritized DSK data.
      !>     It calls ZZDSKBUX to perform the computation.
      !>
      !>## Examples
      !>
      !>     See usage in ZZRAYSFX.
      !>
      !>## Restrictions
      !>
      !>     1) This is a private routine.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 22-FEB-2017 (NJB)
      !>
      !>        Added FAILED calls.
      !>
      !>        12-MAY-2016 (NJB)
      module subroutine zzsbfxri ( ctx, bodyid, nsurf, srflst, et, fixfid, vertex, raydir, xpt, handle, dladsc, dskdsc, dc, ic, found )
      use pepper_kinds, only: ip, wp
      use pepper_inc_dla
      use pepper_inc_dskdsc
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: bodyid  !! ID code of target body.
      integer(ip), intent(in) :: nsurf  !! Number of surface IDs in list.
      integer(ip), intent(in) :: srflst ( * )  !! Surface ID list.
      real(wp), intent(in) :: et  !! Evaluation epoch, seconds past J2000 TDB.
      integer(ip), intent(in) :: fixfid  !! Frame ID of ray and intercept.
      real(wp), intent(in) :: vertex ( 3 )  !! Ray's vertex.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      real(wp), intent(out) :: xpt    ( 3 )  !! Surface intercept point.
      integer(ip), intent(out) :: handle  !! Handle of DSK file.
      integer(ip), intent(out) :: dladsc ( * )  !! DLA descriptor of segment.
      real(wp), intent(out) :: dskdsc ( * )  !! DSK descriptor of segment.
      real(wp), intent(out) :: dc     ( * )  !! Double precision component of source info.
      integer(ip), intent(out) :: ic     ( * )  !! Integer component of source info.
      logical, intent(out) :: found  !! Found flag. True if intercept exists.
      integer(ip) :: stsize
      real(wp) :: locdc  ( maxdc )
      integer(ip) :: bix
      integer(ip) :: j
      integer(ip) :: locic  ( maxic )
      integer(ip) :: nseg
      integer(ip) :: segidx
      logical :: update
!
!     PEPPER: the segment table grows to hold the body's segments.
!
      call zzdsksbf_room ( ctx, bodyid )
      stsize = size ( ctx%zzdsksbf_state%sthan, kind=ip )
      associate ( bsrctr => ctx%zzdsksbf_state%bsrctr, &
                  btbody => ctx%zzdsksbf_state%btbody, &
                  btnbod => ctx%zzdsksbf_state%btnbod, &
                  btsegp => ctx%zzdsksbf_state%btsegp, &
                  btstsz => ctx%zzdsksbf_state%btstsz, &
                  first => ctx%zzdsksbf_state%first, &
                  stctr => ctx%zzdsksbf_state%stctr, &
                  stdlad => ctx%zzdsksbf_state%stdlad, &
                  stdscr => ctx%zzdsksbf_state%stdscr, &
                  stfree => ctx%zzdsksbf_state%stfree, &
                  sthan => ctx%zzdsksbf_state%sthan, &
                  stoff => ctx%zzdsksbf_state%stoff, &
                  strad => ctx%zzdsksbf_state%strad )
      if ( ctx%failed() ) return

      if ( first ) then
!
!        Initialize BSR counter.
!
         call zzctruin ( ctx, bsrctr )

         first = .false.

      end if

!
!     See whether the state of the loaded DSK set has changed
!     since the last call.
!
      call zzdskchk ( ctx, bsrctr, update )

      if ( update ) then
!
!        Make sure the ZZDSKBSR subsystem has completed the segment
!        list for the input body since the last time the BSR loaded
!        kernel state changed.
!
         call zzdskbbl ( ctx, bodyid )

!
!        Initialize the local buffers. We restart from scratch
!        each time the BSR loaded kernel state changes.
!
         call zzdsksbi ( ctx, btsize, stsize, btbody, btnbod, btsegp, &
                         btstsz, sthan,  stdscr, stdlad, stfree, &
                         stoff,  stctr,  strad                  )
      end if

      if ( ctx%failed() ) return

!
!     Find the index of the input body ID in the body table. If
!     we re-initialized the tables, the index will be zero.
!
      bix = findloc(btbody(1:btnbod), bodyid, dim=1)

      if ( bix == 0 ) then
!
!        We don't have buffered information for this body. Update
!        the body and segment tables to store data for it.
!
         call zzdsksba ( ctx, bodyid, &
                         btsize, stsize, btbody, btnbod, btsegp, &
                         btstsz, sthan,  stdscr, stdlad, stfree, &
                         stoff,  stctr,  strad                  )

         if ( ctx%failed() ) return
!
!        The new body's position in the body table is at the end.
!
         bix = btnbod

      end if

!
!     Find the ray-surface intercept, using the buffered segment
!     data.
!
      j    = btsegp(bix)
      nseg = btstsz(bix)

      call zzdskbux ( ctx, bodyid,     nsurf,      srflst, et,  fixfid, &
                      nseg,       sthan(j),   stdlad(1,j), stdscr(1,j), &
                      stoff(1,j), stctr(1,j), strad(j),    vertex, &
                      raydir,     xpt,        segidx,      dc, &
                      ic,         found                                )

      if ( ctx%failed() ) return

      if ( found ) then
!
!        Adjust the segment index to make it relative to the base value
!        1, instead of the current base J.
!
         segidx = segidx + j - 1

         handle = sthan( segidx )

         dladsc(1:dladsz) = stdlad(1:dladsz,segidx)
         dskdsc(1:dskdsz) = stdscr(1:dskdsz,segidx)

      end if

      return
      end associate
      end subroutine zzsbfxri

      !> Prepare and execute unprioritized outward surface normal
      !> computation using DSK API segment buffers.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     BODYID     is the ID code of a target body. The outward
      !>                normal vector computation is performed using data
      !>                that represent the surface of this body.
      !>
      !>     NSURF,
      !>     SRFLST     are, respectively, a count of surface IDs and
      !>                a list of IDs. If the list is non-empty, only
      !>                the indicated surfaces will be used. If the
      !>                list is empty, all surfaces associated with the
      !>                input body ID will be considered.
      !>
      !>     ET         is the epoch for which the computation is to be
      !>                performed. This epoch is used for DSK segment
      !>                selection; only segments containing ET in their time
      !>                coverage interval will be used. ET is expressed as
      !>                seconds past J2000 TDB.
      !>
      !>     FIXFID     is the frame ID of a body-fixed frame associated with
      !>                the body designated by BODYID. This frame is used to
      !>                express the input surface point. The output normal
      !>                vector will be expressed in this frame as well.
      !>
      !>     POINT      is a surface point on the body designated by BODYID.
      !>                POINT is not arbitrary: it must be within a small
      !>                tolerance of the actual surface. Usually POINT is
      !>                obtained as the output of a SPICE computation.
      !>
      !>                POINT is expressed in the frame designated by FIXFID.
      !>
      !>## Detailed Output
      !>
      !>     NORMAL     is the unit-length outward surface normal vector at
      !>                the input POINT.
      !>
      !>                NORMAL is expressed in the frame designated by FIXFID.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If this routine is called directly, it signals the error
      !>         SPICE(BOGUSENTRY).
      !>
      !>     See the entry points for descriptions of errors specific to
      !>     those routines.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by the DSK subsystem.
      !>
      !>     This routine prepares the local buffers for a surface normal
      !>     vector computation using unprioritized DSK data. It calls
      !>     ZZDSKBUN to perform the computation.
      !>
      !>## Examples
      !>
      !>     See usage in DSKNRM (provisional name).
      !>
      !>## Restrictions
      !>
      !>     1) This is a private routine.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.0, 22-FEB-2017 (NJB)
      !>
      !>        Added FAILED calls.
      !>
      !>        12-MAY-2016 (NJB)
      module subroutine zzsbfnrm ( ctx, bodyid, nsurf, srflst, et, fixfid, point, normal )
      use pepper_kinds, only: ip, wp
      use pepper_inc_dla
      use pepper_inc_dskdsc
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: bodyid  !! ID code of target body.
      integer(ip), intent(in) :: nsurf  !! Number of surface IDs in list.
      integer(ip), intent(in) :: srflst ( * )  !! Surface ID list.
      real(wp), intent(in) :: et  !! Evaluation epoch, seconds past J2000 TDB.
      integer(ip), intent(in) :: fixfid  !! Frame ID of surface point and normal vector.
      real(wp), intent(in) :: point  ( 3 )  !! Surface point.
      real(wp), intent(out) :: normal ( 3 )  !! Unit length outward normal at input point.
      integer(ip) :: stsize
      real(wp) :: locdc  ( maxdc )
      integer(ip) :: bix
      integer(ip) :: j
      integer(ip) :: locic  ( maxic )
      integer(ip) :: nseg
      integer(ip) :: segidx
      logical :: update
!
!     PEPPER: the segment table grows to hold the body's segments.
!
      call zzdsksbf_room ( ctx, bodyid )
      stsize = size ( ctx%zzdsksbf_state%sthan, kind=ip )
      associate ( bsrctr => ctx%zzdsksbf_state%bsrctr, &
                  btbody => ctx%zzdsksbf_state%btbody, &
                  btnbod => ctx%zzdsksbf_state%btnbod, &
                  btsegp => ctx%zzdsksbf_state%btsegp, &
                  btstsz => ctx%zzdsksbf_state%btstsz, &
                  first => ctx%zzdsksbf_state%first, &
                  stctr => ctx%zzdsksbf_state%stctr, &
                  stdlad => ctx%zzdsksbf_state%stdlad, &
                  stdscr => ctx%zzdsksbf_state%stdscr, &
                  stfree => ctx%zzdsksbf_state%stfree, &
                  sthan => ctx%zzdsksbf_state%sthan, &
                  stoff => ctx%zzdsksbf_state%stoff, &
                  strad => ctx%zzdsksbf_state%strad )
      if ( ctx%failed() ) return

!
!     The following block of code is straight cut-and-paste from
!     ZZSBFXR. (We need to consider packaging this code in a
!     utility routine.)
!
      if ( first ) then
!
!        Initialize BSR counter.
!
         call zzctruin ( ctx, bsrctr )

         first = .false.

      end if

!
!     See whether the state of the loaded DSK set has changed
!     since the last call.
!
      call zzdskchk ( ctx, bsrctr, update )

      if ( update ) then
!
!        Make sure the ZZDSKBSR subsystem has completed the segment
!        list for the input body since the last time the BSR loaded
!        kernel state changed.
!
         call zzdskbbl ( ctx, bodyid )

!
!        Initialize the local buffers. We restart from scratch
!        each time the BSR loaded kernel state changes.
!
         call zzdsksbi ( ctx, btsize, stsize, btbody, btnbod, btsegp, &
                         btstsz, sthan,  stdscr, stdlad, stfree, &
                         stoff,  stctr,  strad                  )
      end if

      if ( ctx%failed() ) return

!
!     Find the index of the input body ID in the body table. If
!     we re-initialized the tables, the index will be zero.
!
      bix = findloc(btbody(1:btnbod), bodyid, dim=1)

      if ( bix == 0 ) then
!
!        We don't have buffered information for this body. Update
!        the body and segment tables to store data for it.
!
         call zzdsksba ( ctx, bodyid, &
                         btsize, stsize, btbody, btnbod, btsegp, &
                         btstsz, sthan,  stdscr, stdlad, stfree, &
                         stoff,  stctr,  strad                  )

         if ( ctx%failed() ) return
!
!        The new body's position in the body table is at the end.
!
         bix = btnbod

      end if

!
!     Find the outward unit normal vector, using the buffered segment
!     data.
!
      j    = btsegp(bix)
      nseg = btstsz(bix)

      call zzdskbun ( ctx, bodyid,      nsurf,      srflst,     et, &
                      fixfid,      nseg,       sthan(j),   stdlad(1,j), &
                      stdscr(1,j), stoff(1,j), stctr(1,j), strad(j), &
                      point,       normal                              )

      return
      end associate
      end subroutine zzsbfnrm

      !> Compute a ray-surface intercept using data provided by
      !> multiple loaded DSK segments. Return information about
      !> the source of the data defining the surface on which the
      !> intercept was found: DSK handle, DLA and DSK descriptors,
      !> and DSK data type-dependent parameters.
      !>
      !>## Detailed Input
      !>
      !>     PRI      is a logical flag indicating whether to perform a
      !>              prioritized or unprioritized DSK segment search. In an
      !>              unprioritized search, no segment masks another: data from
      !>              all specified segments are used to define the surface of
      !>              interest.
      !>
      !>              The search is unprioritized if and only if PRI is set to
      !>              .FALSE. In the N0066 SPICE Toolkit, this is the only
      !>              allowed value.
      !>
      !>     TARGET   is the name of the target body on which a surface
      !>              intercept is sought.
      !>
      !>     NSURF,
      !>     SRFLST   are, respectively, a count of surface ID codes in a list
      !>              and an array containing the list. Only DSK segments for
      !>              the body designated by TARGET and having surface IDs in
      !>              this list will be considered in the intercept
      !>              computation. If the list is empty, all DSK segments for
      !>              TARGET will be considered.
      !>
      !>     ET       is the epoch of the intersection computation, expressed
      !>              as seconds past J2000 TDB. This epoch is used only for
      !>              DSK segment selection. Segments used in the intercept
      !>              computation must include ET in their time coverage
      !>              intervals.
      !>
      !>     FIXREF   is the name of a body-fixed, body-centered reference
      !>              frame associated with the target. The input ray vectors
      !>              are specified in this frame, as is the output intercept
      !>              point.
      !>
      !>              The frame designated by FIXREF must have a fixed
      !>              orientation relative to the frame of any DSK segment used
      !>              in the computation.
      !>
      !>     VERTEX,
      !>     RAYDIR   are, respectively, the vertex and direction vector of the
      !>              ray to be used in the intercept computation.
      !>
      !>              Both the vertex and ray's direction vector must be
      !>              represented in the reference frame designated by FIXREF.
      !>              The vertex is considered to be an offset from the target
      !>              body.
      !>
      !>     MAXD,
      !>     MAXI     are, respectively, the declared sizes of the arrays DC
      !>              and IC. MAXD must be at least DCSIZE, while MAXI must be
      !>              at least ICSIZE. See the $Parameters section for details.
      !>
      !>## Detailed Output
      !>
      !>     XPT      is the intercept of the input ray on the surface
      !>              specified by the inputs
      !>
      !>                 PRI
      !>                 TARGET
      !>                 NSURF
      !>                 SRFLST
      !>                 ET
      !>
      !>              if such an intercept exists. If the ray intersects the
      !>              surface at multiple points, the one closest to the ray's
      !>              vertex is selected.
      !>
      !>              XPT is defined if and only if FOUND is .TRUE.
      !>
      !>              Units are km.
      !>
      !>     HANDLE,
      !>     DLADSC,
      !>     DSKDSC   are, respectively, the DSK file handle, DLA descriptor,
      !>              and DSK descriptor of the DSK file and segment that
      !>              contributed the surface data on which the intercept was
      !>              found.
      !>
      !>              These outputs are defined if and only if FOUND is .TRUE.
      !>
      !>     DC,
      !>     IC       are, respectively, double precision and integer arrays
      !>              that may contain additional information associated with
      !>              the segment contributing the surface data on which the
      !>              intercept was found. The information is DSK data
      !>              type-dependent.
      !>
      !>                 For DSK type 2 segments
      !>
      !>                    IC(1) is the intercept plate ID. DC is unused.
      !>
      !>              These outputs are defined if and only if FOUND is .TRUE.
      !>
      !>              The declared length of DC must be at least DCSIZE; the
      !>              declared length of IC must be at least ICSIZE. See the
      !>              $Parameters section for details.
      !>
      !>     FOUND    is a logical flag that is set to .TRUE. if and only if
      !>              and intercept was found.
      !>
      !>## Parameters
      !>
      !>     See the include file
      !>
      !>        dsksrc.inc
      !>
      !>     for declarations of size parameters
      !>
      !>        DCSIZE
      !>        ICSIZE
      !>
      !>     for the output arguments
      !>
      !>        DC
      !>        IC
      !>
      !>     See the include files
      !>
      !>        dla.inc
      !>        dskdsc.inc
      !>
      !>     for declarations of DLA and DSK descriptor sizes and
      !>     documentation of the contents of these descriptors.
      !>
      !>     See the include file
      !>
      !>        dsktol.inc
      !>
      !>     for the values of tolerance parameters used by default by the
      !>     ray-surface intercept algorithm. These are discussed in the
      !>     $Particulars section below.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input prioritization flag PRI is set to .TRUE.,
      !>         the error SPICE(BADPRIORITYSPEC) is signaled.
      !>
      !>     2)  If the input body name TARGET cannot be mapped to an
      !>         ID code, the error SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     3)  If the input frame name FIXREF cannot be mapped to an
      !>         ID code, the error SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     4)  If the frame center associated with FIXREF cannot be
      !>         retrieved, the error SPICE(NOFRAMEINFO) is signaled.
      !>
      !>     5)  If the frame center associated with FIXREF is not
      !>         the target body, the error SPICE(INVALIDFRAME) is signaled.
      !>
      !>     6)  If MAXD is less than DCSIZE or MAXI is less than ICSIZE,
      !>         the error SPICE(ARRAYTOOSMALL) is signaled.
      !>
      !>     7)  If NSURF is less than 0, the error SPICE(INVALIDCOUNT)
      !>         is signaled.
      !>
      !>     8)  If an error occurs during the intercept computation, the error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: ephemeris data for the positions of the centers
      !>        of DSK reference frames relative to the target body are
      !>        required if those frames are not centered at the target
      !>        body center.
      !>
      !>        Typically ephemeris data are made available by loading one
      !>        or more SPK files via FURNSH.
      !>
      !>     -  DSK data: DSK files containing topographic data for the
      !>        target body must be loaded. If a surface list is specified,
      !>        data for at least one of the listed surfaces must be loaded.
      !>
      !>     -  Frame data: if a frame definition is required to convert
      !>        DSK segment data to the body-fixed frame designated by
      !>        FIXREF, the target, that definition must be available in the
      !>        kernel pool. Typically the definitions of frames not already
      !>        built-in to SPICE are supplied by loading a frame kernel.
      !>
      !>     -  CK data: if the frame to which FIXREF refers is a CK frame,
      !>        and if any DSK segments used in the computation have a
      !>        different frame, at least one CK file will be needed to
      !>        permit transformation of vectors between that frame and both
      !>        the J2000 and the target body-fixed frames.
      !>
      !>     -  SCLK data: if a CK file is needed, an associated SCLK
      !>        kernel is required to enable conversion between encoded SCLK
      !>        (used to time-tag CK data) and barycentric dynamical time
      !>        (TDB).
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This is the lowest-level public interface for computing
      !>     ray-surface intercepts, where the surface is modeled using
      !>     topographic data provided by DSK files. The highest-level
      !>     interface for this purpose is SINCPT.
      !>
      !>     In cases where the data source information returned by this
      !>     routine are not needed, the routine DSKXV may be more suitable.
      !>
      !>     This routine works with multiple DSK files. It places no
      !>     restrictions on the data types or coordinate systems of the DSK
      !>     segments used in the computation. DSK segments using different
      !>     reference frames may be used in a single computation. The only
      !>     restriction is that any pair of reference frames used directly or
      !>     indirectly are related by a constant rotation.
      !>
      !>     This routine enables calling applications to identify the source
      !>     of the data defining the surface on which an intercept was found.
      !>     The file, segment, and segment-specific information such as a DSK
      !>     type 2 plate ID are returned.
      !>
      !>     This routine can be used for improved efficiency in situations
      !>     in which multiple ray-surface intercepts are to be performed
      !>     using a constant ray vertex.
      !>
      !>     Using DSK data
      !>     ==============
      !>
      !>        DSK loading and unloading
      !>        -------------------------
      !>
      !>        DSK files providing data used by this routine are loaded by
      !>        calling FURNSH and can be unloaded by calling UNLOAD or
      !>        KCLEAR. See the documentation of FURNSH for limits on numbers
      !>        of loaded DSK files.
      !>
      !>        For run-time efficiency, it's desirable to avoid frequent
      !>        loading and unloading of DSK files. When there is a reason to
      !>        use multiple versions of data for a given target body---for
      !>        example, if topographic data at varying resolutions are to be
      !>        used---the surface list can be used to select DSK data to be
      !>        used for a given computation. It is not necessary to unload
      !>        the data that are not to be used. This recommendation presumes
      !>        that DSKs containing different versions of surface data for a
      !>        given body have different surface ID codes.
      !>
      !>        DSK data priority
      !>        -----------------
      !>
      !>        A DSK coverage overlap occurs when two segments in loaded DSK
      !>        files cover part or all of the same domain---for example, a
      !>        given longitude-latitude rectangle---and when the time
      !>        intervals of the segments overlap as well.
      !>
      !>        When DSK data selection is prioritized, in case of a coverage
      !>        overlap, if the two competing segments are in different DSK
      !>        files, the segment in the DSK file loaded last takes
      !>        precedence. If the two segments are in the same file, the
      !>        segment located closer to the end of the file takes
      !>        precedence.
      !>
      !>        When DSK data selection is unprioritized, data from competing
      !>        segments are combined. For example, if two competing segments
      !>        both represent a surface as sets of triangular plates, the
      !>        union of those sets of plates is considered to represent the
      !>        surface.
      !>
      !>        Currently only unprioritized data selection is supported.
      !>        Because prioritized data selection may be the default behavior
      !>        in a later version of the routine, the presence of the PRI
      !>        argument is required.
      !>
      !>        Round-off errors and mitigating algorithms
      !>        ------------------------------------------
      !>
      !>        When topographic data are used to represent the surface of a
      !>        target body, round-off errors can produce some results that
      !>        may seem surprising.
      !>
      !>        Note that, since the surface in question might have mountains,
      !>        valleys, and cliffs, the points of intersection found for
      !>        nearly identical sets of inputs may be quite far apart from
      !>        each other: for example, a ray that hits a mountain side in a
      !>        nearly tangent fashion may, on a different host computer, be
      !>        found to miss the mountain and hit a valley floor much farther
      !>        from the observer, or even miss the target altogether.
      !>
      !>        Round-off errors can affect segment selection: for example, a
      !>        ray that is expected to intersect the target body's surface
      !>        near the boundary between two segments might hit either
      !>        segment, or neither of them; the result may be
      !>        platform-dependent.
      !>
      !>        A similar situation exists when a surface is modeled by a set
      !>        of triangular plates, and the ray is expected to intersect the
      !>        surface near a plate boundary.
      !>
      !>        To avoid having the routine fail to find an intersection when
      !>        one clearly should exist, this routine uses two "greedy"
      !>        algorithms:
      !>
      !>           1) If the ray passes sufficiently close to any of the
      !>              boundary surfaces of a segment (for example, surfaces of
      !>              maximum and minimum longitude or latitude), that segment
      !>              is tested for an intersection of the ray with the
      !>              surface represented by the segment's data.
      !>
      !>              This choice prevents all of the segments from being
      !>              missed when at least one should be hit, but it could, on
      !>              rare occasions, cause an intersection to be found in a
      !>              segment other than the one that would be found if higher
      !>              precision arithmetic were used.
      !>
      !>           2) For type 2 segments, which represent surfaces as
      !>              sets of triangular plates, each plate is expanded very
      !>              slightly before a ray-plate intersection test is
      !>              performed. The default plate expansion factor is
      !>
      !>                 1 + XFRACT
      !>
      !>              where XFRACT is declared in
      !>
      !>                 dsktol.inc
      !>
      !>              For example, given a value for XFRACT of 1.e-10, the
      !>              sides of the plate are lengthened by 1/10 of a micron
      !>              per km. The expansion keeps the centroid of the plate
      !>              fixed.
      !>
      !>              Plate expansion prevents all plates from being missed
      !>              in cases where clearly at least one should be hit.
      !>
      !>              As with the greedy segment selection algorithm, plate
      !>              expansion can occasionally cause an intercept to be
      !>              found on a different plate than would be found if higher
      !>              precision arithmetic were used. It also can occasionally
      !>              cause an intersection to be found when the ray misses
      !>              the target by a very small distance.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Compute surface intercepts of rays emanating from a set of
      !>        vertices distributed on a longitude-latitude grid. All
      !>        vertices are outside the target body, and all rays point
      !>        toward the target's center.
      !>
      !>        Check intercepts against expected values. Indicate the
      !>        number of errors, the number of computations, and the
      !>        number of intercepts found.
      !>
      !>        Use the meta-kernel shown below to load example SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File: dskxsi_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                        Contents
      !>              ---------                        --------
      !>              phobos512.bds                    DSK based on
      !>                                               Gaskell ICQ Q=512
      !>                                               plate model
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'phobos512.bds' )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM DSKXSI_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Multi-segment spear program.
      !>C
      !>C     This program expects all loaded DSKs
      !>C     to represent the same body and surface.
      !>C
      !>      INCLUDE 'dla.inc'
      !>      INCLUDE 'dsk.inc'
      !>      INCLUDE 'dskdsc.inc'
      !>      INCLUDE 'dsksrc.inc'
      !>      INCLUDE 'srftrn.inc'
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      RPD
      !>      DOUBLE PRECISION      VDIST
      !>
      !>      LOGICAL               FAILED
      !>C
      !>C     Local parameters
      !>C
      !>      DOUBLE PRECISION      DTOL
      !>      PARAMETER           ( DTOL   = 1.D-14 )
      !>
      !>      INTEGER               BDNMLN
      !>      PARAMETER           ( BDNMLN = 36 )
      !>
      !>      INTEGER               FILSIZ
      !>      PARAMETER           ( FILSIZ = 255 )
      !>
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>      INTEGER               TYPLEN
      !>      PARAMETER           ( TYPLEN = 4 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(FILSIZ)    DSK1
      !>      CHARACTER*(TYPLEN)    FILTYP
      !>      CHARACTER*(FRNMLN)    FIXREF
      !>      CHARACTER*(FILSIZ)    META
      !>      CHARACTER*(FILSIZ)    SOURCE
      !>      CHARACTER*(BDNMLN)    TARGET
      !>
      !>      DOUBLE PRECISION      D
      !>      DOUBLE PRECISION      DC     ( DCSIZE )
      !>      DOUBLE PRECISION      DSKDSC ( DSKDSZ )
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      RAYDIR ( 3 )
      !>      DOUBLE PRECISION      LAT
      !>      DOUBLE PRECISION      LATCRD ( 3 )
      !>      DOUBLE PRECISION      LATSTP
      !>      DOUBLE PRECISION      LON
      !>      DOUBLE PRECISION      LONSTP
      !>      DOUBLE PRECISION      POLMRG
      !>      DOUBLE PRECISION      R
      !>      DOUBLE PRECISION      RADIUS
      !>      DOUBLE PRECISION      VERTEX ( 3 )
      !>      DOUBLE PRECISION      XPT    ( 3 )
      !>      DOUBLE PRECISION      XYZHIT ( 3 )
      !>
      !>      INTEGER               BODYID
      !>      INTEGER               DLADSC ( DLADSZ )
      !>      INTEGER               DTYPE
      !>      INTEGER               FRAMID
      !>      INTEGER               HANDLE
      !>      INTEGER               IC     ( ICSIZE )
      !>      INTEGER               NCASES
      !>      INTEGER               NDERR
      !>      INTEGER               NHITS
      !>      INTEGER               NLSTEP
      !>      INTEGER               NSURF
      !>      INTEGER               PLID
      !>      INTEGER               SRFLST ( MAXSRF )
      !>      INTEGER               SURFID
      !>
      !>      LOGICAL               FOUND
      !>
      !>      CALL CHKIN ( 'SPEAR' )
      !>
      !>C
      !>C     Prompt for the name of the meta-kernel.
      !>C
      !>      CALL PROMPT ( 'Enter meta-kernel name >  ', META )
      !>
      !>C
      !>C     Load the meta-kernel.
      !>C
      !>      CALL FURNSH ( META )
      !>
      !>C
      !>C     Get a handle for one of the loaded DSKs,
      !>C     then find the first segment and extract
      !>C     the body and surface IDs.
      !>C
      !>      CALL KDATA  ( 1,      'DSK',  DSK1, FILTYP,
      !>     .              SOURCE, HANDLE, FOUND )
      !>
      !>      CALL DLABFS ( HANDLE, DLADSC, FOUND )
      !>
      !>      IF ( .NOT. FOUND ) THEN
      !>         CALL SIGERR ( 'SPICE(NOSEGMENT)' )
      !>      END IF
      !>
      !>      CALL DSKGD ( HANDLE, DLADSC, DSKDSC )
      !>
      !>      BODYID = NINT( DSKDSC(CTRIDX) )
      !>      SURFID = NINT( DSKDSC(SRFIDX) )
      !>      FRAMID = NINT( DSKDSC(FRMIDX) )
      !>
      !>      CALL BODC2N ( BODYID, TARGET, FOUND )
      !>
      !>      IF ( .NOT. FOUND ) THEN
      !>         CALL SETMSG ( 'Cannot map body ID # to a name.' )
      !>         CALL ERRINT ( '#',  BODYID                      )
      !>         CALL SIGERR ( 'SPICE(BODYNAMENOTFOUND)'         )
      !>      END IF
      !>
      !>      CALL FRMNAM ( FRAMID, FIXREF )
      !>
      !>      IF ( FIXREF .EQ. ' ' ) THEN
      !>         CALL SETMSG ( 'Cannot map frame ID # to a name.' )
      !>         CALL ERRINT ( '#',  FRAMID                       )
      !>         CALL SIGERR ( 'SPICE(FRAMENAMENOTFOUND)'         )
      !>      END IF
      !>
      !>C
      !>C     Set the magnitude of the ray vertices. Use a large
      !>C     number to ensure the vertices are outside of
      !>C     any realistic target.
      !>C
      !>      R = 1.D10
      !>
      !>C
      !>C     Spear the target with rays pointing toward
      !>C     the origin.  Use a grid of ray vertices
      !>C     located on a sphere enclosing the target.
      !>C
      !>C     The variable POLMRG ("pole margin") can
      !>C     be set to a small positive value to reduce
      !>C     the number of intercepts done at the poles.
      !>C     This may speed up the computation for
      !>C     the multi-segment case, since rays parallel
      !>C     to the Z axis will cause all segments converging
      !>C     at the pole of interest to be tested for an
      !>C     intersection.
      !>C
      !>      POLMRG = 5.D-1
      !>      LATSTP = 1.D0
      !>      LONSTP = 2.D0
      !>
      !>      NCASES = 0
      !>      NHITS  = 0
      !>      NDERR  = 0
      !>
      !>      LON    = -180.D0
      !>      LAT    = 90.D0
      !>      NLSTEP = 0
      !>
      !>C
      !>C     Set the epoch for interval selection.
      !>C
      !>      ET     = 0.D0
      !>
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'Computing intercepts...'
      !>
      !>      DO WHILE ( LON .LT. 180.D0 )
      !>
      !>         DO WHILE ( NLSTEP .LE. 180  )
      !>
      !>            IF ( LON .EQ. -180.D0 ) THEN
      !>
      !>               LAT = 90.D0 - NLSTEP*LATSTP
      !>
      !>            ELSE
      !>
      !>               IF ( NLSTEP .EQ. 0 ) THEN
      !>
      !>                  LAT =  90.D0 - POLMRG
      !>
      !>               ELSE IF ( NLSTEP .EQ. 180 ) THEN
      !>
      !>                  LAT = -90.D0 + POLMRG
      !>
      !>               ELSE
      !>
      !>                  LAT = 90.D0 - NLSTEP*LATSTP
      !>
      !>               END IF
      !>
      !>            END IF
      !>
      !>            NCASES = NCASES + 1
      !>
      !>            CALL LATREC ( R, LON*RPD(), LAT*RPD(), VERTEX )
      !>            CALL VMINUS ( VERTEX, RAYDIR )
      !>
      !>            NSURF     = 1
      !>            SRFLST(1) = SURFID
      !>
      !>            CALL DSKXSI ( .FALSE., TARGET, NSURF,  SRFLST,
      !>     .                    ET,      FIXREF, VERTEX, RAYDIR,
      !>     .                    DCSIZE,  ICSIZE, XPT,    HANDLE,
      !>     .                    DLADSC, DSKDSC,  DC,     IC,
      !>     .                    FOUND                           )
      !>
      !>            IF ( .NOT. FAILED() .AND. FOUND ) THEN
      !>C
      !>C              Record that a new intercept was found.
      !>C
      !>               NHITS = NHITS + 1
      !>C
      !>C              Compute the latitude and longitude of
      !>C              the intercept. Make sure these agree
      !>C              well with those of the vertex.
      !>C
      !>               CALL RECLAT ( XPT,       LATCRD(1),
      !>     .                       LATCRD(2), LATCRD(3) )
      !>
      !>               RADIUS = LATCRD(1)
      !>
      !>               CALL LATREC ( RADIUS,   LON*RPD(),
      !>     .                       LAT*RPD(), XYZHIT    )
      !>
      !>               D = VDIST ( XPT, XYZHIT )
      !>
      !>               IF ( D/R .GT. DTOL ) THEN
      !>C
      !>C                 Get the intercept segment's plate ID if
      !>C                 applicable.
      !>C
      !>                  DTYPE = NINT( DSKDSC(TYPIDX) )
      !>
      !>                  WRITE (*,*) '======================'
      !>                  WRITE (*,*) 'LON, LAT       = ', LON, LAT
      !>                  WRITE (*,*) 'Bad intercept'
      !>                  WRITE (*,*) 'Distance error = ', D
      !>                  WRITE (*,*) 'XPT            = ', XPT
      !>                  WRITE (*,*) 'XYZHIT         = ', XYZHIT
      !>
      !>                  IF ( DTYPE .EQ. 2 ) THEN
      !>                     PLID = IC(1)
      !>                     WRITE (*,*) 'Plate ID      = ', PLID
      !>                  END IF
      !>
      !>                  NDERR = NDERR + 1
      !>
      !>               END IF
      !>
      !>            ELSE
      !>C
      !>C              Missing the target entirely is a fatal error.
      !>C
      !>               WRITE (*,*) '======================'
      !>               WRITE (*,*) 'LON, LAT = ', LON, LAT
      !>               WRITE (*,*) 'No intercept'
      !>               WRITE (*,*) 'NCASES = ', NCASES
      !>               STOP
      !>
      !>            END IF
      !>
      !>            NLSTEP = NLSTEP + 1
      !>
      !>         END DO
      !>
      !>         LON    = LON + LONSTP
      !>         LAT    = 90.D0
      !>         NLSTEP = 0
      !>
      !>      END DO
      !>
      !>      WRITE (*,*) 'Done.'
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'NCASES = ', NCASES
      !>      WRITE (*,*) 'NHITS  = ', NHITS
      !>      WRITE (*,*) 'NDERR  = ', NDERR
      !>      WRITE (*,*) ' '
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, using as input the meta-kernel dskxsi_ex1.tm, the
      !>        output was:
      !>
      !>        Enter meta-kernel name >  dskxsi_ex1.tm
      !>
      !>         Computing intercepts...
      !>         Done.
      !>
      !>         NCASES =        32580
      !>         NHITS  =        32580
      !>         NDERR  =            0
      !>
      !>## Restrictions
      !>
      !>     1)  The frame designated by FIXREF must have a fixed
      !>         orientation relative to the frame of any DSK segment
      !>         used in the computation. This routine has no
      !>         practical way of ensuring that this condition is met;
      !>         so this responsibility is delegated to the calling
      !>         application.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 06-AUG-2021 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Updated code example to prompt for input meta-kernel name and
      !>        set input time to zero.
      !>
      !>-    SPICELIB Version 1.0.0, 04-APR-2017 (NJB)
      !>
      !>        Original 26-FEB-2016 (NJB)
      module subroutine dskxsi ( ctx, pri, target, nsurf, srflst, et, fixref, vertex, raydir, maxd, maxi, xpt, handle, dladsc, dskdsc, dc, ic, found )
      use pepper_kinds, only: ip, wp
      use pepper_inc_dsktol
      use pepper_inc_dsksrc
      use pepper_inc_srftrn
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      logical, intent(in) :: pri  !! Data prioritization flag.
      character(*), intent(in) :: target  !! Target body name.
      integer(ip), intent(in) :: nsurf  !! Number of surface IDs in list.
      integer(ip), intent(in) :: srflst ( * )  !! Surface ID list.
      real(wp), intent(in) :: et  !! Epoch, expressed as seconds past J2000 TDB.
      character(*), intent(in) :: fixref  !! Name of target body-fixed reference frame.
      real(wp), intent(in) :: vertex ( 3 )  !! Vertex of ray.
      real(wp), intent(in) :: raydir ( 3 )  !! Direction vector of ray.
      integer(ip), intent(in) :: maxd  !! Size of DC array.
      integer(ip), intent(in) :: maxi  !! Size of IC array.
      real(wp), intent(out) :: xpt    ( 3 )  !! Intercept point.
      integer(ip), intent(out) :: handle  !! Handle of segment contributing surface data.
      integer(ip), intent(out) :: dladsc ( * )  !! DLA descriptor of segment.
      real(wp), intent(out) :: dskdsc ( * )  !! DSK descriptor of segment.
      real(wp), intent(out) :: dc     ( * )  !! Double precision component of source info.
      integer(ip), intent(out) :: ic     ( * )  !! Integer component of source info.
      logical, intent(out) :: found  !! Found flag.
      integer(ip) :: fxcent
      integer(ip) :: fxclss
      integer(ip) :: fxtpid
      logical :: frmfnd
      logical :: newfrm
      logical :: newtrg
      logical :: trgfnd
      logical :: update
      integer(ip) :: trgcde
      if ( .not. allocated ( ctx%dskxsi_state ) ) then
         allocate ( ctx%dskxsi_state )
         ctx%dskxsi_state%prvfrm = ' '
      end if
      associate ( first => ctx%dskxsi_state%first, &
                  fixfid => ctx%dskxsi_state%fixfid, &
                  frmctr => ctx%dskxsi_state%frmctr, &
                  prvtcd => ctx%dskxsi_state%prvtcd, &
                  svtcde => ctx%dskxsi_state%svtcde, &
                  svtfnd => ctx%dskxsi_state%svtfnd, &
                  svtnam => ctx%dskxsi_state%svtnam, &
                  trgctr => ctx%dskxsi_state%trgctr )
      if ( ctx%failed() ) return

      if ( first ) then
!
!        Initialize counters.
!
         call zzctruin( ctx, trgctr )
         call zzctruin( ctx, frmctr )

         if ( ctx%failed() ) return

      end if

!
!     Reject PRI if not set properly.
!
      if ( pri ) then

         call ctx%setmsg ( 'In the N0066 SPICE Toolkit, PRI must be ' &
         //            'set to .FALSE., indicating that an ' &
         //            'unprioritized search is to be performed.' )
         call ctx%sigerr ( 'SPICE(BADPRIORITYSPEC)'                   )
         return

      end if

!
!     Reject NSURF if not set properly. Zero is a valid value.
!
      if ( nsurf < 0 ) then

         call ctx%setmsg ( 'The surface count NSURF must be non-negative ' &
         //            'but was #.'                                   )
         call ctx%errint ( '#',  nsurf                                    )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                          )
         return

      end if

!
!     Check output array sizes.
!
      if (  ( maxd < dcsize ) .or. ( maxi < icsize )  ) then

         call ctx%setmsg ( 'Output array size MAXD must be at least #; ' &
         //            'output array size MAXI must be at least #. ' &
         //            'Actual sizes were # and # respectively.'    )
         call ctx%errint ( '#',  dcsize                                 )
         call ctx%errint ( '#',  icsize                                 )
         call ctx%errint ( '#',  maxd                                   )
         call ctx%errint ( '#',  maxi                                   )
         call ctx%sigerr ( 'SPICE(ARRAYTOOSMALL)'                       )
         return

      end if

!
!     Obtain integer codes for the target and reference frame.
!
      call zzbods2c ( ctx, trgctr, svtnam, svtcde, svtfnd, &
                      target, trgcde, trgfnd         )

      if ( ctx%failed() ) return

      if ( .not. trgfnd ) then

         call ctx%setmsg ( 'The target, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit, or that you ' &
         //            'failed to load a kernel containing a ' &
         //            'name-ID mapping for this body.'           )
         call ctx%errch  ( '#', target                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

      newfrm = ( fixref /= ctx%dskxsi_state%prvfrm ) .or. first
      newtrg = ( trgcde /= prvtcd ) .or. first

!
!     Get the frame ID if the pool state has changed. The
!     first call to ZZPCKTRCK will indicate an update.
!
      call zzpctrck ( ctx, frmctr, update )

      if ( update .or. newfrm .or. newtrg ) then

         call namfrm ( ctx, fixref, fixfid )

         if ( ctx%failed() ) return

         if ( fixfid == 0 ) then

            call ctx%setmsg ( 'Reference frame # is not recognized by ' &
            //            'the SPICE frame subsystem. Possibly ' &
            //            'a required frame definition kernel has ' &
            //            'not been loaded.'                        )
            call ctx%errch  ( '#',  fixref                              )
            call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                   )
            return

         end if

!
!        Determine the attributes of the frame designated by FIXREF.
!
         call frinfo ( ctx, fixfid, fxcent, fxclss, fxtpid, frmfnd )

         if ( ctx%failed() ) return

         if ( .not. frmfnd ) then

            call ctx%setmsg ( 'Attributes for reference frame # ' &
            //            'could not be obtained from ' &
            //            'the SPICE frame subsystem. Possibly ' &
            //            'a required frame definition kernel has ' &
            //            'not been loaded.'                        )
            call ctx%errch  ( '#',  fixref                              )
            call ctx%sigerr ( 'SPICE(NOFRAMEINFO)'                      )
            return

         end if
!
!        Make sure that FIXREF is centered at the target body's center.
!
         if ( fxcent /= trgcde ) then

            call ctx%setmsg ( 'Reference frame # is not centered at the ' &
            //            'target body #. The ID code of the frame ' &
            //            'center is #.'                             )
            call ctx%errch  ( '#',  fixref                               )
            call ctx%errch  ( '#',  target                               )
            call ctx%errint ( '#',  fxcent                               )
            call ctx%sigerr ( 'SPICE(INVALIDFRAME)'                      )
            return

         end if

!
!        We have a valid frame at this point. Save the name.
!
         first  = .false.
         ctx%dskxsi_state%prvfrm = fixref

!
!        Update the previous target ID code as well.
!
         prvtcd = trgcde

      end if

!
!     TRGCDE and FIXFID are set.
!
!     Perform the intercept computation.
!
      call zzsbfxri ( ctx, trgcde, nsurf,  srflst, et, &
                      fixfid, vertex, raydir, xpt, handle, &
                      dladsc, dskdsc, dc,     ic,  found   )

      return
      end associate
      end subroutine dskxsi

      !> Compute ray-surface intercepts for a set of rays, using data
      !> provided by multiple loaded DSK segments.
      !>
      !>## Detailed Input
      !>
      !>     PRI      is a logical flag indicating whether to perform
      !>              a prioritized or unprioritized DSK segment search.
      !>              In an unprioritized search, no segment masks another:
      !>              data from all specified segments are used to
      !>              define the surface of interest.
      !>
      !>              The search is unprioritized if and only if PRI
      !>              is set to .FALSE. In the N0066 SPICE Toolkit, this
      !>              is the only allowed value.
      !>
      !>     TARGET   is the name of the target body on which a surface
      !>              intercept is sought.
      !>
      !>     NSURF,
      !>     SRFLST   are, respectively, a count of surface ID codes in a
      !>              list and the containing list. Only DSK segments for
      !>              the body designated by TARGET and having surface
      !>              IDs in this list will considered in the intercept
      !>              computation. If the list is empty, all DSK segments
      !>              for TARGET will be considered.
      !>
      !>     ET       is the epoch of the intersection computation,
      !>              expressed as seconds past J2000 TDB. This epoch is
      !>              used only for DSK segment selection. Segments used
      !>              the intercept computation must include ET in their
      !>              time coverage intervals.
      !>
      !>     FIXREF   is the name of a body-fixed, body-centered reference
      !>              frame associated with the target. The input ray vectors
      !>              are specified in this frame, as is the output intercept
      !>              point.
      !>
      !>              The frame designated by FIXREF must have a fixed
      !>              orientation relative to the frame of any DSK segment
      !>              used in the computation.
      !>
      !>     NRAYS,
      !>     VTXARR,
      !>     DIRARR   are, respectively, a count of rays, an array containing
      !>              the vertices of rays, and an array containing the
      !>              direction vectors of the rays.
      !>
      !>              The ray's vertices are considered to represent offsets
      !>              from the center of the target body.
      !>
      !>              The rays' vertices and direction vectors are
      !>              represented in the reference frame designated by
      !>              FIXREF.
      !>
      !>## Detailed Output
      !>
      !>     XPTARR   is an array containing the intercepts of the input
      !>              rays on the surface specified by the inputs
      !>
      !>                 PRI
      !>                 TARGET
      !>                 NSURF
      !>                 SRFLST
      !>                 ET
      !>
      !>              The Ith element of XPTARR is the intercept
      !>              corresponding to the Ith ray, if such an intercept
      !>              exists. If a ray intersects the surface at multiple
      !>              points, the intercept closest to the ray's vertex is
      !>              selected.
      !>
      !>              The Ith element of XPTARR is defined if and only if the
      !>              Ith element of FNDARR is .TRUE.
      !>
      !>              Units are km.
      !>
      !>     FNDARR   is an array of logical flags indicating whether the
      !>              input rays intersect the surface. The Ith element of
      !>              FNDARR is set to .TRUE. if and only if an intercept
      !>              was found for the Ith ray.
      !>
      !>## Parameters
      !>
      !>     See the include file
      !>
      !>        dsktol.inc
      !>
      !>     for the values of tolerance parameters used by default by the
      !>     ray-surface intercept algorithm.
      !>
      !>     These parameters are discussed in the $Particulars section
      !>     below.
      !>
      !>     See the include file
      !>
      !>        dla.inc
      !>
      !>     for declarations of DLA descriptor sizes and documentation of the
      !>     contents of DLA descriptors.
      !>
      !>     See the include file
      !>
      !>        dskdsc.inc
      !>
      !>     for declarations of DSK descriptor sizes and documentation of the
      !>     contents of DSK descriptors.
      !>
      !>## Exceptions
      !>
      !>     1)  If the input prioritization flag PRI is set to .TRUE.,
      !>         the error SPICE(BADPRIORITYSPEC) is signaled.
      !>
      !>     2)  If NRAYS is less than 1, the error SPICE(INVALIDCOUNT)
      !>         is signaled.
      !>
      !>     3)  If NSURF is less than 0, the error SPICE(INVALIDCOUNT)
      !>         is signaled.
      !>
      !>     4)  If the input body name TARGET cannot be mapped to an
      !>         ID code, the error SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     5)  If the input frame name FIXREF cannot be mapped to an
      !>         ID code, the error SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     6)  If the frame center associated with FIXREF cannot be
      !>         retrieved, the error SPICE(NOFRAMEINFO) is signaled.
      !>
      !>     7)  If the frame center associated with FIXREF is not
      !>         the target body, the error SPICE(INVALIDFRAME) is signaled.
      !>
      !>     8)  If an error occurs during the intercept computation, the error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: ephemeris data for the positions of the centers
      !>        of DSK reference frames relative to the target body are
      !>        required if those frames are not centered at the target
      !>        body center.
      !>
      !>        Typically ephemeris data are made available by loading one
      !>        or more SPK files via FURNSH.
      !>
      !>     -  DSK data: DSK files containing topographic data for the
      !>        target body must be loaded. If a surface list is specified,
      !>        data for at least one of the listed surfaces must be loaded.
      !>
      !>     -  Frame data: if a frame definition is required to convert
      !>        DSK segment data to the body-fixed frame designated by
      !>        FIXREF, the target, that definition must be available in the
      !>        kernel pool. Typically the definitions of frames not already
      !>        built-in to SPICE are supplied by loading a frame kernel.
      !>
      !>     -  CK data: if the frame to which FIXREF refers is a CK frame,
      !>        and if any DSK segments used in the computation have a
      !>        different frame, at least one CK file will be needed to
      !>        permit transformation of vectors between that frame and both
      !>        the J2000 and the target body-fixed frames.
      !>
      !>     -  SCLK data: if a CK file is needed, an associated SCLK
      !>        kernel is required to enable conversion between encoded SCLK
      !>        (used to time-tag CK data) and barycentric dynamical time
      !>        (TDB).
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     This routine is suitable for efficient ray-surface intercept
      !>     computations in which the relative observer-target geometry is
      !>     constant but the rays vary.
      !>
      !>     For cases in which it is necessary to know the source of the
      !>     data defining the surface on which an intercept was found,
      !>     use the SPICELIB routine DSKXSI.
      !>
      !>     For cases in which a ray's vertex is not explicitly known but is
      !>     defined by relative observer-target geometry, the SPICELIB
      !>     ray-surface intercept routine SINCPT should be used.
      !>
      !>     This routine works with multiple DSK files. It places no
      !>     restrictions on the data types or coordinate systems of the DSK
      !>     segments used in the computation. DSK segments using different
      !>     reference frames may be used in a single computation. The only
      !>     restriction is that any pair of reference frames used directly or
      !>     indirectly are related by a constant rotation.
      !>
      !>     Using DSK data
      !>     ==============
      !>
      !>        DSK loading and unloading
      !>        -------------------------
      !>
      !>        DSK files providing data used by this routine are loaded by
      !>        calling FURNSH and can be unloaded by calling UNLOAD or
      !>        KCLEAR. See the documentation of FURNSH for limits on numbers
      !>        of loaded DSK files.
      !>
      !>        For run-time efficiency, it's desirable to avoid frequent
      !>        loading and unloading of DSK files. When there is a reason to
      !>        use multiple versions of data for a given target body---for
      !>        example, if topographic data at varying resolutions are to be
      !>        used---the surface list can be used to select DSK data to be
      !>        used for a given computation. It is not necessary to unload
      !>        the data that are not to be used. This recommendation presumes
      !>        that DSKs containing different versions of surface data for a
      !>        given body have different surface ID codes.
      !>
      !>        DSK data priority
      !>        -----------------
      !>
      !>        A DSK coverage overlap occurs when two segments in loaded DSK
      !>        files cover part or all of the same domain---for example, a
      !>        given longitude-latitude rectangle---and when the time
      !>        intervals of the segments overlap as well.
      !>
      !>        When DSK data selection is prioritized, in case of a coverage
      !>        overlap, if the two competing segments are in different DSK
      !>        files, the segment in the DSK file loaded last takes
      !>        precedence. If the two segments are in the same file, the
      !>        segment located closer to the end of the file takes
      !>        precedence.
      !>
      !>        When DSK data selection is unprioritized, data from competing
      !>        segments are combined. For example, if two competing segments
      !>        both represent a surface as sets of triangular plates, the
      !>        union of those sets of plates is considered to represent the
      !>        surface.
      !>
      !>        Currently only unprioritized data selection is supported.
      !>        Because prioritized data selection may be the default behavior
      !>        in a later version of the routine, the presence of the PRI
      !>        argument is required.
      !>
      !>        Round-off errors and mitigating algorithms
      !>        ------------------------------------------
      !>
      !>        When topographic data are used to represent the surface of a
      !>        target body, round-off errors can produce some results that
      !>        may seem surprising.
      !>
      !>        Note that, since the surface in question might have mountains,
      !>        valleys, and cliffs, the points of intersection found for
      !>        nearly identical sets of inputs may be quite far apart from
      !>        each other: for example, a ray that hits a mountain side in a
      !>        nearly tangent fashion may, on a different host computer, be
      !>        found to miss the mountain and hit a valley floor much farther
      !>        from the observer, or even miss the target altogether.
      !>
      !>        Round-off errors can affect segment selection: for example, a
      !>        ray that is expected to intersect the target body's surface
      !>        near the boundary between two segments might hit either
      !>        segment, or neither of them; the result may be
      !>        platform-dependent.
      !>
      !>        A similar situation exists when a surface is modeled by a set
      !>        of triangular plates, and the ray is expected to intersect the
      !>        surface near a plate boundary.
      !>
      !>        To avoid having the routine fail to find an intersection when
      !>        one clearly should exist, this routine uses two "greedy"
      !>        algorithms:
      !>
      !>           1) If the ray passes sufficiently close to any of the
      !>              boundary surfaces of a segment (for example, surfaces of
      !>              maximum and minimum longitude or latitude), that segment
      !>              is tested for an intersection of the ray with the
      !>              surface represented by the segment's data.
      !>
      !>              This choice prevents all of the segments from being
      !>              missed when at least one should be hit, but it could, on
      !>              rare occasions, cause an intersection to be found in a
      !>              segment other than the one that would be found if higher
      !>              precision arithmetic were used.
      !>
      !>           2) For type 2 segments, which represent surfaces as
      !>              sets of triangular plates, each plate is expanded very
      !>              slightly before a ray-plate intersection test is
      !>              performed. The default plate expansion factor is
      !>
      !>                 1 + XFRACT
      !>
      !>              where XFRACT is declared in
      !>
      !>                 dsktol.inc
      !>
      !>              For example, given a value for XFRACT of 1.e-10, the
      !>              sides of the plate are lengthened by 1/10 of a micron
      !>              per km. The expansion keeps the centroid of the plate
      !>              fixed.
      !>
      !>              Plate expansion prevents all plates from being missed
      !>              in cases where clearly at least one should be hit.
      !>
      !>              As with the greedy segment selection algorithm, plate
      !>              expansion can occasionally cause an intercept to be
      !>              found on a different plate than would be found if higher
      !>              precision arithmetic were used. It also can occasionally
      !>              cause an intersection to be found when the ray misses
      !>              the target by a very small distance.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Compute surface intercepts of rays emanating from a set of
      !>        vertices distributed on a longitude-latitude grid. All
      !>        vertices are outside the target body, and all rays point
      !>        toward the target's center.
      !>
      !>        Check intercepts against expected values. Indicate the
      !>        number of errors, the number of computations, and the
      !>        number of intercepts found.
      !>
      !>        Use the meta-kernel shown below to load example SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File: dskxv_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                        Contents
      !>              ---------                        --------
      !>              phobos512.bds                    DSK based on
      !>                                               Gaskell ICQ Q=512
      !>                                               plate model
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'phobos512.bds' )
      !>
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM DSKXV_EX1
      !>      IMPLICIT NONE
      !>
      !>C
      !>C     Multi-segment, vectorized spear program.
      !>C
      !>C     This program expects all loaded DSKs
      !>C     to represent the same body and surface.
      !>C
      !>      INCLUDE 'dla.inc'
      !>      INCLUDE 'dsk.inc'
      !>      INCLUDE 'dskdsc.inc'
      !>
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      RPD
      !>      DOUBLE PRECISION      VDIST
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      DOUBLE PRECISION      DTOL
      !>      PARAMETER           ( DTOL   = 1.D-14 )
      !>
      !>      INTEGER               BDNMLN
      !>      PARAMETER           ( BDNMLN = 36 )
      !>
      !>      INTEGER               CMDLEN
      !>      PARAMETER           ( CMDLEN = 1000 )
      !>
      !>      INTEGER               FILSIZ
      !>      PARAMETER           ( FILSIZ = 255 )
      !>
      !>      INTEGER               LNSIZE
      !>      PARAMETER           ( LNSIZE = 80 )
      !>
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>      INTEGER               MAXN
      !>      PARAMETER           ( MAXN   = 100000 )
      !>
      !>      INTEGER               TYPLEN
      !>      PARAMETER           ( TYPLEN = 4 )
      !>
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(CMDLEN)    CMD
      !>      CHARACTER*(FILSIZ)    DSK1
      !>      CHARACTER*(TYPLEN)    FILTYP
      !>      CHARACTER*(FRNMLN)    FIXREF
      !>      CHARACTER*(FILSIZ)    FNAME
      !>      CHARACTER*(LNSIZE)    IDCH
      !>      CHARACTER*(FILSIZ)    SOURCE
      !>      CHARACTER*(BDNMLN)    TARGET
      !>
      !>      DOUBLE PRECISION      D
      !>      DOUBLE PRECISION      DSKDSC ( DSKDSZ )
      !>      DOUBLE PRECISION      DIRARR ( 3, MAXN )
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      LAT
      !>      DOUBLE PRECISION      LATCRD ( 3 )
      !>      DOUBLE PRECISION      LATSTP
      !>      DOUBLE PRECISION      LON
      !>      DOUBLE PRECISION      LONSTP
      !>      DOUBLE PRECISION      POLMRG
      !>      DOUBLE PRECISION      R
      !>      DOUBLE PRECISION      RADIUS
      !>      DOUBLE PRECISION      VLAT
      !>      DOUBLE PRECISION      VLON
      !>      DOUBLE PRECISION      VRAD
      !>      DOUBLE PRECISION      VTXARR ( 3, MAXN )
      !>      DOUBLE PRECISION      XPTARR ( 3, MAXN )
      !>      DOUBLE PRECISION      XYZHIT ( 3 )
      !>
      !>      INTEGER               BODYID
      !>      INTEGER               DLADSC ( DLADSZ )
      !>      INTEGER               FRAMID
      !>      INTEGER               HANDLE
      !>      INTEGER               I
      !>      INTEGER               J
      !>      INTEGER               NDERR
      !>      INTEGER               NHITS
      !>      INTEGER               NLSTEP
      !>      INTEGER               NRAYS
      !>      INTEGER               NSURF
      !>      INTEGER               SRFLST ( MAXSRF )
      !>      INTEGER               SURFID
      !>
      !>      LOGICAL               FNDARR ( MAXN )
      !>      LOGICAL               FOUND
      !>
      !>C
      !>C     Saved variables
      !>C
      !>C     Save large arrays to avoid stack problems.
      !>C
      !>      SAVE                  DIRARR
      !>      SAVE                  FNDARR
      !>      SAVE                  XPTARR
      !>
      !>      CALL CHKIN ( 'SPEAR' )
      !>
      !>C
      !>C     Prompt for the name of the meta-kernel.
      !>C
      !>      CALL PROMPT ( 'Enter meta-kernel name >  ', FNAME )
      !>
      !>C
      !>C     Load the meta-kernel.
      !>C
      !>      CALL FURNSH ( FNAME )
      !>
      !>C
      !>C     Get a handle for one of the loaded DSKs,
      !>C     then find the first segment and extract
      !>C     the body and surface IDs.
      !>C
      !>      CALL KDATA  ( 1,      'DSK',  DSK1, FILTYP,
      !>     .              SOURCE, HANDLE, FOUND )
      !>
      !>      CALL DLABFS ( HANDLE, DLADSC, FOUND )
      !>
      !>      IF ( .NOT. FOUND ) THEN
      !>         CALL SIGERR ( 'SPICE(NOSEGMENT)' )
      !>      END IF
      !>
      !>      CALL DSKGD ( HANDLE, DLADSC, DSKDSC )
      !>
      !>      BODYID = NINT( DSKDSC(CTRIDX) )
      !>      SURFID = NINT( DSKDSC(SRFIDX) )
      !>      FRAMID = NINT( DSKDSC(FRMIDX) )
      !>
      !>      CALL BODC2N ( BODYID, TARGET, FOUND )
      !>
      !>      IF ( .NOT. FOUND ) THEN
      !>         CALL SETMSG ( 'Cannot map body ID # to a name.' )
      !>         CALL ERRINT ( '#',  BODYID                      )
      !>         CALL SIGERR ( 'SPICE(BODYNAMENOTFOUND)'         )
      !>      END IF
      !>
      !>      CALL FRMNAM ( FRAMID, FIXREF )
      !>
      !>      IF ( FIXREF .EQ. ' ' ) THEN
      !>         CALL SETMSG ( 'Cannot map frame ID # to a name.' )
      !>         CALL ERRINT ( '#',  FRAMID                       )
      !>         CALL SIGERR ( 'SPICE(FRAMENAMENOTFOUND)'         )
      !>      END IF
      !>
      !>C
      !>C     Set the magnitude of the ray vertices. Use a large
      !>C     number to to ensure the vertices are outside of
      !>C     any realistic target.
      !>C
      !>      R = 1.D10
      !>
      !>C
      !>C     Spear the target with rays pointing toward
      !>C     the origin.  Use a grid of ray vertices
      !>C     located on a sphere enclosing the target.
      !>C
      !>C     The variable POLMRG ("pole margin") can
      !>C     be set to a small positive value to reduce
      !>C     the number of intercepts done at the poles.
      !>C     This may speed up the computation for
      !>C     the multi-segment case, since rays parallel
      !>C     to the Z axis will cause all segments converging
      !>C     at the pole of interest to be tested for an
      !>C     intersection.
      !>C
      !>      POLMRG = 5.D-1
      !>      LATSTP = 1.D0
      !>      LONSTP = 2.D0
      !>
      !>      NHITS  = 0
      !>      NDERR  = 0
      !>
      !>      LON    = -180.D0
      !>      LAT    = 90.D0
      !>      NLSTEP = 0
      !>      NRAYS  = 0
      !>
      !>C
      !>C     Set the epoch for interval selection.
      !>C
      !>      ET     = 0.D0
      !>
      !>C
      !>C     Generate rays.
      !>C
      !>      DO WHILE ( LON .LT. 180.D0 )
      !>
      !>         DO WHILE ( NLSTEP .LE. 180  )
      !>
      !>            IF ( LON .EQ. -180.D0 ) THEN
      !>
      !>               LAT = 90.D0 - NLSTEP*LATSTP
      !>
      !>            ELSE
      !>
      !>               IF ( NLSTEP .EQ. 0 ) THEN
      !>
      !>                  LAT =  90.D0 - POLMRG
      !>
      !>               ELSE IF ( NLSTEP .EQ. 180 ) THEN
      !>
      !>                  LAT = -90.D0 + POLMRG
      !>
      !>               ELSE
      !>
      !>                  LAT =  90.D0 - NLSTEP*LATSTP
      !>
      !>               END IF
      !>
      !>            END IF
      !>
      !>            NRAYS  = NRAYS  + 1
      !>
      !>            CALL LATREC ( R,               LON*RPD(),
      !>     .                    LAT*RPD(),       VTXARR(1,NRAYS) )
      !>            CALL VMINUS ( VTXARR(1,NRAYS), DIRARR(1,NRAYS) )
      !>
      !>            NLSTEP = NLSTEP + 1
      !>
      !>         END DO
      !>
      !>         LON    = LON + LONSTP
      !>         LAT    = 90.D0
      !>         NLSTEP = 0
      !>
      !>      END DO
      !>
      !>C
      !>C     Assign surface ID list.
      !>C
      !>C     Note that, if we knew that all files had the desired
      !>C     surface ID, we could set `nsurf' to 0 and omit the
      !>C     initialization of the surface ID list.
      !>C
      !>      NSURF     = 1
      !>      SRFLST(1) = SURFID
      !>
      !>      WRITE (*,*) ' '
      !>      WRITE (*,*) 'Computing intercepts...'
      !>
      !>      CALL DSKXV ( .FALSE., TARGET, NSURF, SRFLST,
      !>     .             ET,      FIXREF, NRAYS, VTXARR,
      !>     .             DIRARR,  XPTARR, FNDARR        )
      !>
      !>      WRITE (*,*) 'Done.'
      !>      WRITE (*,*) ' '
      !>
      !>C
      !>C     Check results.
      !>C
      !>      DO I = 1, NRAYS
      !>
      !>         IF ( FNDARR(I) ) THEN
      !>C
      !>C           Record that a new intercept was found.
      !>C
      !>            NHITS = NHITS + 1
      !>C
      !>C           Compute the latitude and longitude of
      !>C           the intercept. Make sure these agree
      !>C           well with those of the vertex.
      !>C
      !>            CALL RECLAT ( XPTARR(1,I), LATCRD(1),
      !>     .                    LATCRD(2),   LATCRD(3) )
      !>
      !>            RADIUS = LATCRD(1)
      !>
      !>C
      !>C           Recover the vertex longitude and latitude.
      !>C
      !>            CALL RECLAT ( VTXARR(1,I), VRAD, VLON, VLAT )
      !>
      !>            CALL LATREC ( RADIUS,  VLON,
      !>     .                    VLAT,    XYZHIT )
      !>
      !>            D = VDIST ( XPTARR(1,I), XYZHIT )
      !>
      !>            IF ( D/R .GT. DTOL ) THEN
      !>C
      !>C              Get the intercept segment's plate ID if
      !>C              applicable.
      !>C
      !>               WRITE (*,*) '======================'
      !>               WRITE (*,*) 'LON, LAT       = ', LON, LAT
      !>               WRITE (*,*) 'Bad intercept'
      !>               WRITE (*,*) 'Distance error = ', D
      !>               WRITE (*,*) 'XPT            = ',
      !>     .                     ( XPTARR(J,I), J = 1, 3 )
      !>               WRITE (*,*) 'XYZHIT         = ', XYZHIT
      !>
      !>               NDERR = NDERR + 1
      !>
      !>            END IF
      !>
      !>         ELSE
      !>C
      !>C           Missing the target entirely is a fatal error.
      !>C
      !>C           This is true only for this program, not in
      !>C           general. For example, if the target shape is
      !>C           a torus, many rays would miss the target.
      !>C
      !>            WRITE (*,*) '======================'
      !>            WRITE (*,*) 'LON, LAT = ', LON, LAT
      !>            WRITE (*,*) 'No intercept'
      !>            WRITE (*,*) 'I        = ', I
      !>            STOP
      !>
      !>         END IF
      !>
      !>      END DO
      !>
      !>      WRITE (*,*) 'NRAYS  = ', NRAYS
      !>      WRITE (*,*) 'NHITS  = ', NHITS
      !>      WRITE (*,*) 'NDERR  = ', NDERR
      !>      WRITE (*,*) ' '
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, using as input the meta-kernel dskxv_ex1.tm, the
      !>        output was:
      !>
      !>        Enter meta-kernel name >  dskxv_ex1.tm
      !>
      !>         Computing intercepts...
      !>         Done.
      !>
      !>         NRAYS  =        32580
      !>         NHITS  =        32580
      !>         NDERR  =            0
      !>
      !>## Restrictions
      !>
      !>     1)  The frame designated by FIXREF must have a fixed
      !>         orientation relative to the frame of any DSK segment
      !>         used in the computation. This routine has no
      !>         practical way of ensuring that this condition is met;
      !>         so this responsibility is delegated to the calling
      !>         application.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 06-AUG-2021 (JDR) (BVS)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Updated code example to prompt for input meta-kernel name and
      !>        set input time to zero.
      !>
      !>-    SPICELIB Version 1.0.0, 21-FEB-2017 (NJB)
      !>
      !>        Original 25-FEB-2016 (NJB)
      module subroutine dskxv ( ctx, pri, target, nsurf, srflst, et, fixref, nrays, vtxarr, dirarr, xptarr, fndarr )
      use pepper_kinds, only: ip, wp
      use pepper_inc_dsktol
      use pepper_inc_zzctr
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      logical, intent(in) :: pri  !! Data prioritization flag.
      character(*), intent(in) :: target  !! Target body name.
      integer(ip), intent(in) :: nsurf  !! Number of surface IDs in list.
      integer(ip), intent(in) :: srflst ( * )  !! Surface ID list.
      real(wp), intent(in) :: et  !! Epoch, expressed as seconds past J2000 TDB.
      character(*), intent(in) :: fixref  !! Name of target body-fixed reference frame.
      integer(ip), intent(in) :: nrays  !! Number of rays.
      real(wp), intent(in) :: vtxarr ( 3, * )  !! Array of vertices of rays.
      real(wp), intent(in) :: dirarr ( 3, * )  !! Array of direction vectors of rays.
      real(wp), intent(out) :: xptarr ( 3, * )  !! Intercept point array.
      logical, intent(out) :: fndarr ( * )  !! Found flag array.
      integer(ip) :: fxcent
      integer(ip) :: fxclss
      integer(ip) :: fxtpid
      integer(ip) :: i
      logical :: frmfnd
      logical :: newfrm
      logical :: newtrg
      logical :: trgfnd
      logical :: update
      integer(ip) :: trgcde
      if ( .not. allocated ( ctx%dskxv_state ) ) then
         allocate ( ctx%dskxv_state )
         ctx%dskxv_state%prvfrm = ' '
      end if
      associate ( first => ctx%dskxv_state%first, &
                  fixfid => ctx%dskxv_state%fixfid, &
                  frmctr => ctx%dskxv_state%frmctr, &
                  prvtcd => ctx%dskxv_state%prvtcd, &
                  svtcde => ctx%dskxv_state%svtcde, &
                  svtfnd => ctx%dskxv_state%svtfnd, &
                  svtnam => ctx%dskxv_state%svtnam, &
                  trgctr => ctx%dskxv_state%trgctr )
      if ( ctx%failed() ) return

      if ( first ) then
!
!        Initialize counters.
!
         call zzctruin( ctx, trgctr )
         call zzctruin( ctx, frmctr )

         if ( ctx%failed() ) return

      end if

!
!     Reject PRI if not set properly.
!
      if ( pri ) then

         call ctx%setmsg ( 'In the N0066 SPICE Toolkit, PRI must be ' &
         //            'set to .FALSE., indicating that an ' &
         //            'unprioritized search is to be performed.' )
         call ctx%sigerr ( 'SPICE(BADPRIORITYSPEC)'                   )
         return

      end if

!
!     Reject NRAYS if not set properly.
!
      if ( nrays < 1 ) then

         call ctx%setmsg ( 'The ray count NRAYS must be at least 1 but ' &
         //            'was #.'                                     )
         call ctx%errint ( '#',  nrays                                  )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                        )
         return

      end if

!
!     Reject NSURF if not set properly. Zero is a valid value.
!
      if ( nsurf < 0 ) then

         call ctx%setmsg ( 'The surface count NSURF must be non-negative ' &
         //            'but was #.'                                   )
         call ctx%errint ( '#',  nsurf                                    )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                          )
         return

      end if

!
!     Obtain integer codes for the target and reference frame.
!
      call zzbods2c ( ctx, trgctr, svtnam, svtcde, svtfnd, &
                      target, trgcde, trgfnd         )

      if ( ctx%failed() ) return

      if ( .not. trgfnd ) then

         call ctx%setmsg ( 'The target, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit, or that you ' &
         //            'failed to load a kernel containing a ' &
         //            'name-ID mapping for this body.'           )
         call ctx%errch  ( '#', target                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

      newfrm = ( fixref /= ctx%dskxv_state%prvfrm ) .or. first
      newtrg = ( trgcde /= prvtcd ) .or. first

!
!     Get the frame ID if the pool state has changed. The
!     first call to ZZPCKTRCK will indicate an update.
!
      call zzpctrck ( ctx, frmctr, update )

      if ( update .or. newfrm .or. newtrg ) then

         call namfrm ( ctx, fixref, fixfid )

         if ( ctx%failed() ) return

         if ( fixfid == 0 ) then

            call ctx%setmsg ( 'Reference frame # is not recognized by ' &
            //            'the SPICE frame subsystem. Possibly ' &
            //            'a required frame definition kernel has ' &
            //            'not been loaded.'                        )
            call ctx%errch  ( '#',  fixref                              )
            call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                   )
            return

         end if

!
!        Determine the attributes of the frame designated by FIXREF.
!
         call frinfo ( ctx, fixfid, fxcent, fxclss, fxtpid, frmfnd )

         if ( ctx%failed() ) return

         if ( .not. frmfnd ) then

            call ctx%setmsg ( 'Attributes for reference frame # ' &
            //            'could not be obtained from ' &
            //            'the SPICE frame subsystem. Possibly ' &
            //            'a required frame definition kernel has ' &
            //            'not been loaded.'                        )
            call ctx%errch  ( '#',  fixref                              )
            call ctx%sigerr ( 'SPICE(NOFRAMEINFO)'                      )
            return

         end if
!
!        Make sure that FIXREF is centered at the target body's center.
!
         if ( fxcent /= trgcde ) then

            call ctx%setmsg ( 'Reference frame # is not centered at the ' &
            //            'target body #. The ID code of the frame ' &
            //            'center is #.'                             )
            call ctx%errch  ( '#',  fixref                               )
            call ctx%errch  ( '#',  target                               )
            call ctx%errint ( '#',  fxcent                               )
            call ctx%sigerr ( 'SPICE(INVALIDFRAME)'                      )
            return

         end if

!
!        We have a valid frame at this point. Save the name.
!
         first  = .false.
         ctx%dskxv_state%prvfrm = fixref

!
!        Update the previous target ID code as well.
!
         prvtcd = trgcde

      end if

!
!     TRGCDE and FIXFID are set.
!
!     Perform the intercept computations.
!
      do i = 1, nrays

         call zzsbfxr ( ctx, trgcde,      nsurf,       srflst, &
                        et,          fixfid,      vtxarr(1,i), &
                        dirarr(1,i), xptarr(1,i), fndarr(i)   )

         if ( ctx%failed() ) return

      end do

      return
      end associate
      end subroutine dskxv

      !> Find the illumination angles (phase, incidence, and
      !> emission) at a specified surface point of a target body.
      !>
      !> The surface of the target body may be represented by a triaxial
      !> ellipsoid or by topographic data provided by DSK files.
      !>
      !> The illumination source is a specified ephemeris object.
      !>
      !>## Detailed Input
      !>
      !>     METHOD   is a short string providing parameters defining
      !>              the computation method to be used. In the syntax
      !>              descriptions below, items delimited by brackets
      !>              are optional.
      !>
      !>              METHOD may be assigned the following values:
      !>
      !>                 'ELLIPSOID'
      !>
      !>                    The illumination angle computation uses a
      !>                    triaxial ellipsoid to model the surface of the
      !>                    target body. The ellipsoid's radii must be
      !>                    available in the kernel pool.
      !>
      !>                 'DSK/UNPRIORITIZED[/SURFACES = <surface list>]'
      !>
      !>                    The illumination angle computation uses
      !>                    topographic data to model the surface of the
      !>                    target body. These data must be provided by
      !>                    loaded DSK files.
      !>
      !>                    The surface list specification is optional. The
      !>                    syntax of the list is
      !>
      !>                       <surface 1> [, <surface 2>...]
      !>
      !>                    If present, it indicates that data only for the
      !>                    listed surfaces are to be used; however, data
      !>                    need not be available for all surfaces in the
      !>                    list. If absent, loaded DSK data for any surface
      !>                    associated with the target body are used.
      !>
      !>                    The surface list may contain surface names or
      !>                    surface ID codes. Names containing blanks must
      !>                    be delimited by double quotes, for example
      !>
      !>                       'SURFACES = "Mars MEGDR 128 PIXEL/DEG"'
      !>
      !>                    If multiple surfaces are specified, their names
      !>                    or IDs must be separated by commas.
      !>
      !>                    See the $Particulars section below for details
      !>                    concerning use of DSK data.
      !>
      !>              Neither case nor white space are significant in METHOD,
      !>              except within double-quoted strings representing surface
      !>              names. For example, the string ' eLLipsoid ' is valid.
      !>
      !>              Within double-quoted strings representing surface names,
      !>              blank characters are significant, but multiple
      !>              consecutive blanks are considered equivalent to a single
      !>              blank. Case is not significant. So
      !>
      !>                 "Mars MEGDR 128 PIXEL/DEG"
      !>
      !>              is equivalent to
      !>
      !>                 " mars megdr  128  pixel/deg "
      !>
      !>              but not to
      !>
      !>                 "MARS MEGDR128PIXEL/DEG"
      !>
      !>     TARGET   is the name of the target body. TARGET is
      !>              case-insensitive, and leading and trailing blanks in
      !>              TARGET are not significant. Optionally, you may
      !>              supply a string containing the integer ID code for
      !>              the object. For example both 'MOON' and '301' are
      !>              legitimate strings that indicate the Moon is the
      !>              target body.
      !>
      !>     ILUSRC   is the name of the illumination source. This source
      !>              may be any ephemeris object. Case, blanks, and
      !>              numeric values are treated in the same way as for the
      !>              input TARGET.
      !>
      !>     ET       is the epoch, expressed as seconds past J2000 TDB,
      !>              for which the apparent illumination angles at the
      !>              specified surface point on the target body, as seen
      !>              from the observing body, are to be computed.
      !>
      !>     FIXREF   is the name of the body-fixed, body-centered
      !>              reference frame associated with the target body. The
      !>              input surface point SPOINT and the output vector
      !>              SRFVEC are expressed relative to this reference
      !>              frame. The string FIXREF is case-insensitive, and
      !>              leading and trailing blanks in FIXREF are not
      !>              significant.
      !>
      !>     ABCORR   is the aberration correction to be used in computing
      !>              the position and orientation of the target body and
      !>              the location of the illumination source.
      !>
      !>              For remote sensing applications, where the apparent
      !>              illumination angles seen by the observer are desired,
      !>              normally either of the corrections
      !>
      !>                 'LT+S'
      !>                 'CN+S'
      !>
      !>              should be used. These and the other supported options
      !>              are described below. ABCORR may be any of the
      !>              following:
      !>
      !>                 'NONE'     No aberration correction.
      !>
      !>              Let LT represent the one-way light time between the
      !>              observer and the input surface point SPOINT (note: NOT
      !>              between the observer and the target body's center). The
      !>              following values of ABCORR apply to the "reception" case
      !>              in which photons depart from SPOINT at the light-time
      !>              corrected epoch ET-LT and *arrive* at the observer's
      !>              location at ET:
      !>
      !>                 'LT'       Correct both the position of SPOINT as
      !>                            seen by the observer, and the position
      !>                            of the illumination source as seen by
      !>                            the target, for light time. Correct the
      !>                            orientation of the target for light
      !>                            time.
      !>
      !>                 'LT+S'     Correct both the position of SPOINT as
      !>                            seen by the observer, and the position
      !>                            of the illumination source as seen by
      !>                            the target, for light time and stellar
      !>                            aberration. Correct the orientation of
      !>                            the target for light time.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equations for SPOINT and the
      !>                            illumination source, the 'CN'
      !>                            correction iterates until the solution
      !>                            converges.
      !>
      !>                 'CN+S'     Converged Newtonian light time and
      !>                            stellar aberration corrections. This
      !>                            option produces a solution that is at
      !>                            least as accurate at that obtainable
      !>                            with the 'LT+S' option. Whether the
      !>                            'CN+S' solution is substantially more
      !>                            accurate depends on the geometry of the
      !>                            participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons *arrive* at
      !>              SPOINT at the light-time corrected epoch ET+LT and
      !>              *depart* from the observer's location at ET:
      !>
      !>                 'XLT'      "Transmission" case: correct for
      !>                            one-way light time using a Newtonian
      !>                            formulation. This correction yields the
      !>                            illumination angles at the moment that
      !>                            SPOINT receives photons emitted from the
      !>                            observer's location at ET.
      !>
      !>                            The light time correction uses an
      !>                            iterative solution of the light time
      !>                            equation. The solution invoked by the
      !>                            'XLT' option uses one iteration.
      !>
      !>                            Both the target position as seen by the
      !>                            observer, and rotation of the target
      !>                            body, are corrected for light time.
      !>
      !>                 'XLT+S'    "Transmission" case: correct for
      !>                            one-way light time and stellar
      !>                            aberration using a Newtonian
      !>                            formulation  This option modifies the
      !>                            angles obtained with the 'XLT' option
      !>                            to account for the observer's and
      !>                            target's velocities relative to the
      !>                            solar system barycenter (the latter
      !>                            velocity is used in computing the
      !>                            direction to the apparent illumination
      !>                            source).
      !>
      !>                 'XCN'      Converged Newtonian light time
      !>                            correction. This is the same as XLT
      !>                            correction but with further iterations
      !>                            to a converged Newtonian light time
      !>                            solution.
      !>
      !>                 'XCN+S'    "Transmission" case: converged
      !>                            Newtonian light time and stellar
      !>                            aberration corrections. This option
      !>                            produces a solution that is at least as
      !>                            accurate at that obtainable with the
      !>                            'XLT+S' option. Whether the 'XCN+S'
      !>                            solution is substantially more accurate
      !>                            depends on the geometry of the
      !>                            participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed.
      !>
      !>              Neither case nor white space are significant in
      !>              ABCORR. For example, the string
      !>
      !>                'Lt + s'
      !>
      !>              is valid.
      !>
      !>     OBSRVR   is the name of the observing body. The observing body is
      !>              an ephemeris object: it typically is a spacecraft, an
      !>              extended body, or a surface point for which ephemeris
      !>              data are available. OBSRVR is case-insensitive, and
      !>              leading and trailing blanks in OBSRVR are not
      !>              significant. Optionally, you may supply a string
      !>              containing the integer ID code for the object. For
      !>              example both 'MOON' and '301' are legitimate strings that
      !>              indicate the Moon is the observer.
      !>
      !>              OBSRVR may be not be identical to TARGET.
      !>
      !>     SPOINT   is a surface point on the target body, expressed in
      !>              Cartesian coordinates, relative to the body-fixed
      !>              target frame designated by FIXREF.
      !>
      !>              SPOINT need not be visible from the observer's
      !>              location at the epoch ET.
      !>
      !>              The components of SPOINT have units of km.
      !>
      !>## Detailed Output
      !>
      !>     TRGEPC   is the "target surface point epoch." TRGEPC is defined as
      !>              follows: letting LT be the one-way light time between the
      !>              observer and the input surface point SPOINT, TRGEPC is
      !>              either the epoch ET-LT, ET+LT or ET depending on whether
      !>              the requested aberration correction is, respectively, for
      !>              received radiation, transmitted radiation or omitted. LT
      !>              is computed using the method indicated by ABCORR.
      !>
      !>              TRGEPC is expressed as seconds past J2000 TDB.
      !>
      !>     SRFVEC   is the vector from the observer's position at ET to
      !>              the aberration-corrected (or optionally, geometric)
      !>              position of SPOINT, where the aberration corrections
      !>              are specified by ABCORR. SRFVEC is expressed in the
      !>              target body-fixed reference frame designated by
      !>              FIXREF, evaluated at TRGEPC.
      !>
      !>              The components of SRFVEC are given in units of km.
      !>
      !>              One can use the SPICELIB function VNORM to obtain the
      !>              distance between the observer and SPOINT:
      !>
      !>                 DIST = VNORM ( SRFVEC )
      !>
      !>              The observer's position OBSPOS, relative to the
      !>              target body's center, where the center's position is
      !>              corrected for aberration effects as indicated by
      !>              ABCORR, can be computed via the call:
      !>
      !>                 CALL VSUB ( SPOINT, SRFVEC, OBSPOS )
      !>
      !>              To transform the vector SRFVEC from a reference frame
      !>              FIXREF at time TRGEPC to a time-dependent reference
      !>              frame REF at time ET, the routine PXFRM2 should be
      !>              called. Let XFORM be the 3x3 matrix representing the
      !>              rotation from the reference frame FIXREF at time
      !>              TRGEPC to the reference frame REF at time ET. Then
      !>              SRFVEC can be transformed to the result REFVEC as
      !>              follows:
      !>
      !>                  CALL PXFRM2 ( FIXREF, REF,    TRGEPC, ET, XFORM )
      !>                  CALL MXV    ( XFORM,  SRFVEC, REFVEC )
      !>
      !>     The following outputs depend on the existence of a well-defined
      !>     outward normal vector to the surface at SPOINT. See restriction 1.
      !>
      !>     PHASE    is the phase angle at SPOINT, as seen from OBSRVR at time
      !>              ET. This is the angle between the negative of the vector
      !>              SRFVEC and the SPOINT-illumination source vector at
      !>              TRGEPC. Units are radians. The range of PHASE is [0, pi].
      !>              See $Particulars below for a detailed discussion of the
      !>              definition.
      !>
      !>     INCDNC   is the illumination source incidence angle at SPOINT, as
      !>              seen from OBSRVR at time ET. This is the angle between
      !>              the surface normal vector at SPOINT and the
      !>              SPOINT-illumination source vector at TRGEPC. Units are
      !>              radians. The range of INCDNC is [0, pi]. See $Particulars
      !>              below for a detailed discussion of the definition.
      !>
      !>     EMISSN   is the emission angle at SPOINT, as seen from OBSRVR at
      !>              time ET. This is the angle between the surface normal
      !>              vector at SPOINT and the negative of the vector SRFVEC.
      !>              Units are radians. The range of EMISSN is [0, pi]. See
      !>              $Particulars below for a detailed discussion of the
      !>              definition.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the specified aberration correction is relativistic or
      !>         calls for stellar aberration but not light time correction,
      !>         the error SPICE(NOTSUPPORTED) is signaled.
      !>
      !>     2)  If the specified aberration correction is any other
      !>         unrecognized value, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     3)  If any of the target, observer, or illumination source
      !>         input strings cannot be converted to an integer ID code, the
      !>         error SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     4)  If OBSRVR and TARGET map to the same NAIF integer ID code,
      !>         the error SPICE(BODIESNOTDISTINCT) is signaled.
      !>
      !>     5)  If the input target body-fixed frame FIXREF is not
      !>         recognized, the error SPICE(NOFRAME) is signaled. A frame
      !>         name may fail to be recognized because a required frame
      !>         specification kernel has not been loaded; another cause is a
      !>         misspelling of the frame name.
      !>
      !>     6)  If the input frame FIXREF is not centered at the target body,
      !>         the error SPICE(INVALIDFRAME) is signaled.
      !>
      !>     7)  If the input argument METHOD is not recognized, the error
      !>         SPICE(INVALIDMETHOD) is signaled.
      !>
      !>     8)  If insufficient ephemeris data have been loaded prior to
      !>         calling ILLUMG, an error is signaled by a
      !>         routine in the call tree of this routine. Note that when
      !>         light time correction is used, sufficient ephemeris data must
      !>         be available to propagate the states of observer, target, and
      !>         the illumination source to the solar system barycenter.
      !>
      !>     9)  If the computation method specifies an ellipsoidal target
      !>         shape and triaxial radii of the target body have not been
      !>         loaded into the kernel pool prior to calling ILLUMG, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     10) If PCK data specifying the target body-fixed frame orientation
      !>         have not been loaded prior to calling ILLUMG, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     11) If METHOD specifies that the target surface is represented by
      !>         DSK data, and no DSK files are loaded for the specified
      !>         target, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     12) If METHOD specifies that the target surface is represented by
      !>         DSK data, and data representing the portion of the surface on
      !>         which SPOINT is located are not available, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     13) If METHOD specifies that the target surface is represented
      !>         by DSK data, SPOINT must lie on the target surface, not above
      !>         or below it. A small tolerance is used to allow for round-off
      !>         error in the calculation determining whether SPOINT is on the
      !>         surface.
      !>
      !>         If, in the DSK case, SPOINT is too far from the surface, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>         If the surface is represented by a triaxial ellipsoid, SPOINT
      !>         is not required to be close to the ellipsoid; however, the
      !>         results computed by this routine will be unreliable if SPOINT
      !>         is too far from the ellipsoid.
      !>
      !>     14) If radii for TARGET are not found in the kernel pool, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     15) If the size of the TARGET body radii kernel variable is not
      !>         three, an error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>     16) If any of the three TARGET body radii is less-than or equal to
      !>         zero, an error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: ephemeris data for target, observer, and the
      !>        illumination source must be loaded. If aberration
      !>        corrections are used, the states of target, observer, and
      !>        the illumination source relative to the solar system
      !>        barycenter must be calculable from the available ephemeris
      !>        data. Typically ephemeris data are made available by loading
      !>        one or more SPK files via FURNSH.
      !>
      !>     -  PCK data: rotation data for the target body must be
      !>        loaded. These may be provided in a text or binary PCK file.
      !>
      !>     -  Shape data for the target body:
      !>
      !>           PCK data:
      !>
      !>              If the target body shape is modeled as an ellipsoid,
      !>              triaxial radii for the target body must be loaded into
      !>              the kernel pool. Typically this is done by loading a
      !>              text PCK file via FURNSH.
      !>
      !>              Triaxial radii are also needed if the target shape is
      !>              modeled by DSK data, but the DSK NADIR method is
      !>              selected.
      !>
      !>           DSK data:
      !>
      !>              If the target shape is modeled by DSK data, DSK files
      !>              containing topographic data for the target body must be
      !>              loaded. If a surface list is specified, data for at
      !>              least one of the listed surfaces must be loaded.
      !>
      !>     The following data may be required:
      !>
      !>     -  Frame data: if a frame definition is required to convert the
      !>        observer and target states to the body-fixed frame of the
      !>        target, that definition must be available in the kernel
      !>        pool. Typically the definition is supplied by loading a
      !>        frame kernel via FURNSH.
      !>
      !>     -  Surface name-ID associations: if surface names are specified
      !>        in METHOD, the association of these names with their
      !>        corresponding surface ID codes must be established by
      !>        assignments of the kernel variables
      !>
      !>           NAIF_SURFACE_NAME
      !>           NAIF_SURFACE_CODE
      !>           NAIF_SURFACE_BODY
      !>
      !>        Normally these associations are made by loading a text
      !>        kernel containing the necessary assignments. An example
      !>        of such an assignment is
      !>
      !>           NAIF_SURFACE_NAME += 'Mars MEGDR 128 PIXEL/DEG'
      !>           NAIF_SURFACE_CODE += 1
      !>           NAIF_SURFACE_BODY += 499
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     SPICELIB contains four routines that compute illumination angles:
      !>
      !>        ILLUMF   (same as this routine, except that illumination
      !>                  and visibility flags are returned)
      !>
      !>        ILLUMG   (this routine)
      !>
      !>        ILUMIN   (same as ILLUMG, except that the sun is fixed
      !>                  as the illumination source)
      !>
      !>        ILLUM    (deprecated)
      !>
      !>     ILLUMF is the most capable of the set.
      !>
      !>     Illumination angles
      !>     ===================
      !>
      !>     The term "illumination angles" refers to the following set of
      !>     angles:
      !>
      !>        phase angle              Angle between the vectors from the
      !>                                 surface point to the observer and
      !>                                 from the surface point to the
      !>                                 illumination source.
      !>
      !>        incidence angle          Angle between the surface normal at
      !>                                 the specified surface point and the
      !>                                 vector from the surface point to the
      !>                                 illumination source.
      !>
      !>        emission angle           Angle between the surface normal at
      !>                                 the specified surface point and the
      !>                                 vector from the surface point to the
      !>                                 observer.
      !>
      !>     The diagram below illustrates the geometric relationships
      !>     defining these angles. The labels for the incidence, emission,
      !>     and phase angles are "inc.", "e.", and "phase".
      !>
      !>                                                      *
      !>                                              illumination source
      !>
      !>                    surface normal vector
      !>                              ._                 _.
      !>                              |\                 /|  illumination
      !>                                \    phase      /    source vector
      !>                                 \   .    .    /
      !>                                 .            .
      !>                                   \   ___   /
      !>                              .     \/     \/
      !>                                    _\ inc./
      !>                             .    /   \   /
      !>                             .   |  e. \ /
      !>         *             <--------------- *  surface point on
      !>      viewing            vector            target body
      !>      location           to viewing
      !>      (observer)         location
      !>
      !>     Note that if the target-observer vector, the target normal vector
      !>     at the surface point, and the target-illumination source vector
      !>     are coplanar, then phase is the sum of the incidence and emission
      !>     angles. This rarely occurs; usually
      !>
      !>        phase angle  <  incidence angle + emission angle
      !>
      !>     All of the above angles can be computed using light time
      !>     corrections, light time and stellar aberration corrections, or no
      !>     aberration corrections. In order to describe apparent geometry as
      !>     observed by a remote sensing instrument, both light time and
      !>     stellar aberration corrections should be used.
      !>
      !>     The way aberration corrections are applied by this routine
      !>     is described below.
      !>
      !>        Light time corrections
      !>        ======================
      !>
      !>           Observer-target surface point vector
      !>           ------------------------------------
      !>
      !>           Let ET be the epoch at which an observation or remote
      !>           sensing measurement is made, and let ET - LT ("LT" stands
      !>           for "light time") be the epoch at which the photons
      !>           received at ET were emitted from the surface point SPOINT.
      !>           Note that the light time between the surface point and
      !>           observer will generally differ from the light time between
      !>           the target body's center and the observer.
      !>
      !>           Target body's orientation
      !>           -------------------------
      !>
      !>           Using the definitions of ET and LT above, the target body's
      !>           orientation at ET - LT is used. The surface normal is
      !>           dependent on the target body's orientation, so the body's
      !>           orientation model must be evaluated for the correct epoch.
      !>
      !>           Target body -- illumination source vector
      !>           -----------------------------------------
      !>
      !>           The surface features on the target body near SPOINT will
      !>           appear in a measurement made at ET as they were at ET-LT.
      !>           In particular, lighting on the target body is dependent on
      !>           the apparent location of the illumination source as seen
      !>           from the target body at ET-LT. So, a second light time
      !>           correction is used to compute the position of the
      !>           illumination source relative to the surface point.
      !>
      !>        Stellar aberration corrections
      !>        ==============================
      !>
      !>        Stellar aberration corrections are applied only if
      !>        light time corrections are applied as well.
      !>
      !>           Observer-target surface point body vector
      !>           -----------------------------------------
      !>
      !>           When stellar aberration correction is performed, the
      !>           direction vector SRFVEC is adjusted so as to point to the
      !>           apparent position of SPOINT: considering SPOINT to be an
      !>           ephemeris object, SRFVEC points from the observer's
      !>           position at ET to the light time and stellar aberration
      !>           corrected position of SPOINT.
      !>
      !>           Target body-illumination source vector
      !>           --------------------------------------
      !>
      !>           The target body-illumination source vector is the apparent
      !>           position of the illumination source, corrected for light
      !>           time and stellar aberration, as seen from the target body
      !>           at time ET-LT.
      !>
      !>     Using DSK data
      !>     ==============
      !>
      !>        DSK loading and unloading
      !>        -------------------------
      !>
      !>        DSK files providing data used by this routine are loaded by
      !>        calling FURNSH and can be unloaded by calling UNLOAD or
      !>        KCLEAR. See the documentation of FURNSH for limits on numbers
      !>        of loaded DSK files.
      !>
      !>        For run-time efficiency, it's desirable to avoid frequent
      !>        loading and unloading of DSK files. When there is a reason to
      !>        use multiple versions of data for a given target body---for
      !>        example, if topographic data at varying resolutions are to be
      !>        used---the surface list can be used to select DSK data to be
      !>        used for a given computation. It is not necessary to unload
      !>        the data that are not to be used. This recommendation presumes
      !>        that DSKs containing different versions of surface data for a
      !>        given body have different surface ID codes.
      !>
      !>        DSK data priority
      !>        -----------------
      !>
      !>        A DSK coverage overlap occurs when two segments in loaded DSK
      !>        files cover part or all of the same domain---for example, a
      !>        given longitude-latitude rectangle---and when the time
      !>        intervals of the segments overlap as well.
      !>
      !>        When DSK data selection is prioritized, in case of a coverage
      !>        overlap, if the two competing segments are in different DSK
      !>        files, the segment in the DSK file loaded last takes
      !>        precedence. If the two segments are in the same file, the
      !>        segment located closer to the end of the file takes
      !>        precedence.
      !>
      !>        When DSK data selection is unprioritized, data from competing
      !>        segments are combined. For example, if two competing segments
      !>        both represent a surface as sets of triangular plates, the
      !>        union of those sets of plates is considered to represent the
      !>        surface.
      !>
      !>        Currently only unprioritized data selection is supported.
      !>        Because prioritized data selection may be the default behavior
      !>        in a later version of the routine, the UNPRIORITIZED keyword is
      !>        required in the METHOD argument.
      !>
      !>        Syntax of the METHOD input argument
      !>        -----------------------------------
      !>
      !>        The keywords and surface list in the METHOD argument
      !>        are called "clauses." The clauses may appear in any
      !>        order, for example
      !>
      !>           DSK/<surface list>/UNPRIORITIZED
      !>           DSK/UNPRIORITIZED/<surface list>
      !>           UNPRIORITIZED/<surface list>/DSK
      !>
      !>        The simplest form of the METHOD argument specifying use of
      !>        DSK data is one that lacks a surface list, for example:
      !>
      !>           'DSK/UNPRIORITIZED'
      !>
      !>        For applications in which all loaded DSK data for the target
      !>        body are for a single surface, and there are no competing
      !>        segments, the above string suffices. This is expected to be
      !>        the usual case.
      !>
      !>        When, for the specified target body, there are loaded DSK
      !>        files providing data for multiple surfaces for that body, the
      !>        surfaces to be used by this routine for a given call must be
      !>        specified in a surface list, unless data from all of the
      !>        surfaces are to be used together.
      !>
      !>        The surface list consists of the string
      !>
      !>           SURFACES =
      !>
      !>        followed by a comma-separated list of one or more surface
      !>        identifiers. The identifiers may be names or integer codes in
      !>        string format. For example, suppose we have the surface
      !>        names and corresponding ID codes shown below:
      !>
      !>           Surface Name                              ID code
      !>           ------------                              -------
      !>           'Mars MEGDR 128 PIXEL/DEG'                1
      !>           'Mars MEGDR 64 PIXEL/DEG'                 2
      !>           'Mars_MRO_HIRISE'                         3
      !>
      !>        If data for all of the above surfaces are loaded, then
      !>        data for surface 1 can be specified by either
      !>
      !>           'SURFACES = 1'
      !>
      !>        or
      !>
      !>           'SURFACES = "Mars MEGDR 128 PIXEL/DEG"'
      !>
      !>        Double quotes are used to delimit the surface name because
      !>        it contains blank characters.
      !>
      !>        To use data for surfaces 2 and 3 together, any
      !>        of the following surface lists could be used:
      !>
      !>           'SURFACES = 2, 3'
      !>
      !>           'SURFACES = "Mars MEGDR  64 PIXEL/DEG", 3'
      !>
      !>           'SURFACES = 2, Mars_MRO_HIRISE'
      !>
      !>           'SURFACES = "Mars MEGDR 64 PIXEL/DEG", Mars_MRO_HIRISE'
      !>
      !>        An example of a METHOD argument that could be constructed
      !>        using one of the surface lists above is
      !>
      !>           'DSK/UNPRIORITIZED/SURFACES = "Mars MEGDR 64 PIXEL/DEG", 3'
      !>
      !>        Aberration corrections using DSK data
      !>        -------------------------------------
      !>
      !>        For irregularly shaped target bodies, the distance between the
      !>        observer and the nearest surface intercept need not be a
      !>        continuous function of time; hence the one-way light time
      !>        between the intercept and the observer may be discontinuous as
      !>        well. In such cases, the computed light time, which is found
      !>        using an iterative algorithm, may converge slowly or not at
      !>        all. In all cases, the light time computation will terminate,
      !>        but the result may be less accurate than expected.
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Find the phase, solar incidence, and emission angles at the
      !>        sub-solar and sub-spacecraft points on Mars as seen from the
      !>        Mars Global Surveyor spacecraft at a specified UTC time. Use
      !>        light time and stellar aberration corrections.
      !>
      !>        Use both an ellipsoidal Mars shape model and topographic data
      !>        provided by a DSK file.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File: illumg_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                        Contents
      !>              ---------                        --------
      !>              de430.bsp                        Planetary ephemeris
      !>              mar097.bsp                       Mars satellite ephemeris
      !>              pck00010.tpc                     Planet orientation and
      !>                                               radii
      !>              naif0011.tls                     Leapseconds
      !>              mgs_ext12_ipng_mgs95j.bsp        MGS ephemeris
      !>              megr90n000cb_plate.bds           Plate model based on
      !>                                               MEGDR DEM, resolution
      !>                                               4 pixels/degree.
      !>
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de430.bsp',
      !>                                  'mar097.bsp',
      !>                                  'pck00010.tpc',
      !>                                  'naif0011.tls',
      !>                                  'mgs_ext12_ipng_mgs95j.bsp',
      !>                                  'megr90n000cb_plate.bds'      )
      !>           \begintext
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM ILLUMG_EX1
      !>      IMPLICIT NONE
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      DPR
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         F1
      !>      PARAMETER           ( F1     = '(A,F15.9)' )
      !>
      !>      CHARACTER*(*)         F2
      !>      PARAMETER           ( F2     = '(A)' )
      !>
      !>      CHARACTER*(*)         F3
      !>      PARAMETER           ( F3     = '(A,2(2X,L))' )
      !>
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'illumg_ex1.tm' )
      !>
      !>      INTEGER               NAMLEN
      !>      PARAMETER           ( NAMLEN = 32 )
      !>
      !>      INTEGER               TIMLEN
      !>      PARAMETER           ( TIMLEN = 25 )
      !>
      !>      INTEGER               CORLEN
      !>      PARAMETER           ( CORLEN = 5 )
      !>
      !>      INTEGER               MTHLEN
      !>      PARAMETER           ( MTHLEN = 50 )
      !>
      !>      INTEGER               NMETH
      !>      PARAMETER           ( NMETH  = 2 )
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(CORLEN)    ABCORR
      !>      CHARACTER*(NAMLEN)    FIXREF
      !>      CHARACTER*(MTHLEN)    ILUMTH ( NMETH )
      !>      CHARACTER*(NAMLEN)    OBSRVR
      !>      CHARACTER*(MTHLEN)    SUBMTH ( NMETH )
      !>      CHARACTER*(NAMLEN)    TARGET
      !>      CHARACTER*(TIMLEN)    UTC
      !>
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      SRFVEC ( 3 )
      !>      DOUBLE PRECISION      SSCEMI
      !>      DOUBLE PRECISION      SSCPHS
      !>      DOUBLE PRECISION      SSCPT  ( 3 )
      !>      DOUBLE PRECISION      SSCSOL
      !>      DOUBLE PRECISION      SSLEMI
      !>      DOUBLE PRECISION      SSLPHS
      !>      DOUBLE PRECISION      SSLSOL
      !>      DOUBLE PRECISION      SSOLPT ( 3 )
      !>      DOUBLE PRECISION      TRGEPC
      !>
      !>      INTEGER               I
      !>
      !>C
      !>C     Initial values
      !>C
      !>      DATA                  ILUMTH / 'Ellipsoid',
      !>     .                               'DSK/Unprioritized' /
      !>
      !>      DATA                  SUBMTH / 'Near Point/Ellipsoid',
      !>     .                            'DSK/Nadir/Unprioritized' /
      !>
      !>C
      !>C     Load kernel files.
      !>C
      !>      CALL FURNSH ( META )
      !>C
      !>C     Convert the UTC request time string to seconds past
      !>C     J2000 TDB.
      !>C
      !>      UTC = '2003 OCT 13 06:00:00 UTC'
      !>
      !>      CALL UTC2ET ( UTC, ET )
      !>
      !>      WRITE (*,F2) ' '
      !>      WRITE (*,F2) 'UTC epoch is '//UTC
      !>C
      !>C     Assign observer and target names. The acronym MGS
      !>C     indicates Mars Global Surveyor. See NAIF_IDS for a
      !>C     list of names recognized by SPICE. Also set the
      !>C     aberration correction flag.
      !>C
      !>      TARGET = 'Mars'
      !>      OBSRVR = 'MGS'
      !>      FIXREF = 'IAU_MARS'
      !>      ABCORR = 'CN+S'
      !>
      !>      DO I = 1, NMETH
      !>C
      !>C        Find the sub-solar point on Mars as
      !>C        seen from the MGS spacecraft at ET. Use the
      !>C        "near point" style of sub-point definition
      !>C        when the shape model is an ellipsoid, and use
      !>C        the "nadir" style when the shape model is
      !>C        provided by DSK data. This makes it easy to
      !>C        verify the solar incidence angle when
      !>C        the target is modeled as an  ellipsoid.
      !>C
      !>         CALL SUBSLR ( SUBMTH(I),  TARGET,  ET,
      !>     .                 FIXREF,     ABCORR,  OBSRVR,
      !>     .                 SSOLPT,     TRGEPC,  SRFVEC  )
      !>C
      !>C        Now find the sub-spacecraft point.
      !>C
      !>         CALL SUBPNT ( SUBMTH(I),  TARGET,  ET,
      !>     .                 FIXREF,     ABCORR,  OBSRVR,
      !>     .                 SSCPT,      TRGEPC,  SRFVEC )
      !>C
      !>C        Find the phase, solar incidence, and emission
      !>C        angles at the sub-solar point on Mars as
      !>C        seen from MGS at time ET.
      !>C
      !>         CALL ILLUMG ( ILUMTH(I), TARGET,  'SUN',
      !>     .                 ET,        FIXREF,  ABCORR,
      !>     .                 OBSRVR,    SSOLPT,  TRGEPC,
      !>     .                 SRFVEC,    SSLPHS,  SSLSOL,
      !>     .                 SSLEMI                      )
      !>C
      !>C        Do the same for the sub-spacecraft point.
      !>C
      !>         CALL ILLUMG ( ILUMTH(I), TARGET,  'SUN',
      !>     .                 ET,        FIXREF,  ABCORR,
      !>     .                 OBSRVR,    SSCPT,   TRGEPC,
      !>     .                 SRFVEC,    SSCPHS,  SSCSOL,
      !>     .                 SSCEMI                      )
      !>C
      !>C        Convert the angles to degrees and write them out.
      !>C
      !>         SSLPHS = DPR() * SSLPHS
      !>         SSLSOL = DPR() * SSLSOL
      !>         SSLEMI = DPR() * SSLEMI
      !>
      !>         SSCPHS = DPR() * SSCPHS
      !>         SSCSOL = DPR() * SSCSOL
      !>         SSCEMI = DPR() * SSCEMI
      !>
      !>         WRITE (*,F2) ' '
      !>         WRITE (*,F2) '   ILLUMG method: '//ILUMTH(I)
      !>         WRITE (*,F2) '   SUBPNT method: '//SUBMTH(I)
      !>         WRITE (*,F2) '   SUBSLR method: '//SUBMTH(I)
      !>         WRITE (*,F2) ' '
      !>         WRITE (*,F2) '      Illumination angles at the '
      !>     .   //           'sub-solar point:'
      !>         WRITE (*,F2) ' '
      !>
      !>         WRITE (*,F1) '      Phase angle           (deg.): ',
      !>     .                SSLPHS
      !>         WRITE (*,F1) '      Solar incidence angle (deg.): ',
      !>     .                SSLSOL
      !>         WRITE (*,F1) '      Emission angle        (deg.): ',
      !>     .                SSLEMI
      !>         WRITE (*,F2) ' '
      !>
      !>         IF ( I .EQ. 1 ) THEN
      !>            WRITE (*,F2) '        The solar incidence angle '
      !>     .      //           'should be 0.'
      !>            WRITE (*,F2) '        The emission and phase '
      !>     .      //           'angles should be equal.'
      !>            WRITE (*,F2) ' '
      !>         END IF
      !>
      !>         WRITE (*,F2) '      Illumination angles at the '
      !>     .   //          'sub-s/c point:'
      !>         WRITE (*,F2) ' '
      !>         WRITE (*,F1) '      Phase angle           (deg.): ',
      !>     .               SSCPHS
      !>         WRITE (*,F1) '      Solar incidence angle (deg.): ',
      !>     .               SSCSOL
      !>         WRITE (*,F1) '      Emission angle        (deg.): ',
      !>     .               SSCEMI
      !>         WRITE (*,F2) ' '
      !>
      !>         IF ( I .EQ. 1 ) THEN
      !>            WRITE (*,F2) '        The emission angle '
      !>     .      //           'should be 0.'
      !>            WRITE (*,F2) '        The solar incidence '
      !>     .      //           'and phase angles should be equal.'
      !>         END IF
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>        UTC epoch is 2003 OCT 13 06:00:00 UTC
      !>
      !>           ILLUMG method: Ellipsoid
      !>           SUBPNT method: Near Point/Ellipsoid
      !>           SUBSLR method: Near Point/Ellipsoid
      !>
      !>              Illumination angles at the sub-solar point:
      !>
      !>              Phase angle           (deg.):   138.370270685
      !>              Solar incidence angle (deg.):     0.000000000
      !>              Emission angle        (deg.):   138.370270685
      !>
      !>                The solar incidence angle should be 0.
      !>                The emission and phase angles should be equal.
      !>
      !>              Illumination angles at the sub-s/c point:
      !>
      !>              Phase angle           (deg.):   101.439331040
      !>              Solar incidence angle (deg.):   101.439331041
      !>              Emission angle        (deg.):     0.000000002
      !>
      !>                The emission angle should be 0.
      !>                The solar incidence and phase angles should be equal.
      !>
      !>           ILLUMG method: DSK/Unprioritized
      !>           SUBPNT method: DSK/Nadir/Unprioritized
      !>           SUBSLR method: DSK/Nadir/Unprioritized
      !>
      !>              Illumination angles at the sub-solar point:
      !>
      !>              Phase angle           (deg.):   138.387071677
      !>              Solar incidence angle (deg.):     0.967122745
      !>              Emission angle        (deg.):   137.621480599
      !>
      !>              Illumination angles at the sub-s/c point:
      !>
      !>              Phase angle           (deg.):   101.439331359
      !>              Solar incidence angle (deg.):   101.555993667
      !>              Emission angle        (deg.):     0.117861156
      !>
      !>## Restrictions
      !>
      !>     1)  Results from this routine are not meaningful if the input
      !>         point lies on a ridge or vertex of a surface represented by
      !>         DSK data, or if for any other reason the direction of the
      !>         outward normal vector at the point is undefined.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     B.V. Semenov       (JPL)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 2.1.0, 20-NOV-2021 (JDR) (EDW) (NJB)
      !>
      !>        Bug fix: PRVCOR is no longer set to blank before
      !>        ABCORR is parsed.
      !>
      !>        Body radii accessed from kernel pool using ZZGFTREB.
      !>
      !>        Minor edits to header.
      !>
      !>-    SPICELIB Version 2.0.0, 04-APR-2017 (NJB)
      !>
      !>       07-APR-2016 (NJB)
      !>
      !>        Upgraded to support surfaces represented by DSKs.
      !>
      !>-    SPICELIB Version 1.0.0, 31-MAR-2014 (NJB) (BVS)
      module subroutine illumg ( ctx, method, target, ilusrc, et, fixref, abcorr, obsrvr, spoint, trgepc, srfvec, phase, incdnc, emissn )
      use pepper_containers, only: grow
      use pepper_kinds, only: ip, wp
      use pepper_math, only: vsep
      use pepper_strings, only: eqstr
      use pepper_inc_gf
      use pepper_inc_zzabcorr
      use pepper_inc_zzctr
      use pepper_inc_zzdsk
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: method  !! Computation method.
      character(*), intent(in) :: target  !! Name of target body.
      character(*), intent(in) :: ilusrc  !! Name of illumination source.
      real(wp), intent(in) :: et  !! Epoch in ephemeris seconds past J2000 TDB.
      character(*), intent(in) :: fixref  !! Body-fixed, body-centered target body frame.
      character(*), intent(in) :: abcorr  !! Desired aberration correction.
      character(*), intent(in) :: obsrvr  !! Name of observing body.
      real(wp), intent(in) :: spoint ( 3 )  !! Body-fixed coordinates of a target surface point.
      real(wp), intent(out) :: trgepc  !! Target surface point epoch.
      real(wp), intent(out) :: srfvec ( 3 )  !! Vector from observer to target surface point.
      real(wp), intent(out) :: phase  !! Phase angle at the surface point.
      real(wp), intent(out) :: incdnc  !! Source incidence angle at the surface point.
      real(wp), intent(out) :: emissn  !! Emission angle at the surface point.
      character(cvtlen) :: pntdef
      character(shplen) :: shpstr
      character(sublen) :: subtyp
      character(tmtlen) :: trmstr
      real(wp) :: lt
      real(wp) :: lti
      real(wp) :: normal ( 3 )
      real(wp) :: obspos ( 3 )
      real(wp) :: opstat ( 6 )
      real(wp) :: radii  ( 3 )
      real(wp) :: s
      real(wp) :: tistat ( 6 )
      integer(ip) :: fxfcde
      integer(ip) :: obscde
      integer(ip) :: type
      integer(ip) :: typeid
      logical :: attblk ( nabcor )
      logical :: fnd
      logical :: surfup
      integer(ip) :: center
      integer(ip) :: trgcde
      logical :: pri
      if ( .not. allocated ( ctx%illumg_state ) ) allocate ( ctx%illumg_state )
!
!     PEPPER: the surface list has room for any number of surfaces (it
!     grows before the ASSOCIATE block; SPICELIB's held MAXSRF, 100).
!
      call grow ( ctx%illumg_state%srflst, len(method)/2 + 1 )
      associate ( first => ctx%illumg_state%first, &
                  nsurf => ctx%illumg_state%nsurf, &
                  prvcor => ctx%illumg_state%prvcor, &
                  prvmth => ctx%illumg_state%prvmth, &
                  shape => ctx%illumg_state%shape, &
                  srflst => ctx%illumg_state%srflst, &
                  uselt => ctx%illumg_state%uselt, &
                  xmit => ctx%illumg_state%xmit, &
                  svctr1 => ctx%illumg_state%svctr1, &
                  svtarg => ctx%illumg_state%svtarg, &
                  svtcde => ctx%illumg_state%svtcde, &
                  svfnd1 => ctx%illumg_state%svfnd1, &
                  svctr2 => ctx%illumg_state%svctr2, &
                  svobsr => ctx%illumg_state%svobsr, &
                  svobsc => ctx%illumg_state%svobsc, &
                  svfnd2 => ctx%illumg_state%svfnd2, &
                  svctr3 => ctx%illumg_state%svctr3, &
                  svfref => ctx%illumg_state%svfref, &
                  svrefc => ctx%illumg_state%svrefc, &
                  svctr4 => ctx%illumg_state%svctr4 )
      if ( ctx%failed() ) return

!
!     Counter initialization is done separately.
!
      if ( first ) then
!
!        Initialize counters.
!
         call zzctruin( ctx, svctr1 )
         call zzctruin( ctx, svctr2 )
         call zzctruin( ctx, svctr3 )

      end if

!
!     If necessary, parse the aberration correction flag.
!
      if (  first  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any. Analyze the new flag.
!
         call zzvalcor ( ctx, abcorr, attblk )

         if ( ctx%failed() ) return

!
!        Set logical flags indicating the attributes of the requested
!        correction:
!
!           XMIT is .TRUE. when the correction is for transmitted
!           radiation.
!
!           USELT is .TRUE. when any type of light time correction
!           (normal or converged Newtonian) is specified.
!
!           USESTL indicates stellar aberration corrections.
!
!        The above definitions are consistent with those used by
!        ZZVALCOR.
!
         xmit    =  attblk ( xmtidx )
         uselt   =  attblk ( ltidx  )

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr
!
!        We do NOT set FIRST to .FALSE. here, since we're not
!        yet done with it.
!
      end if

!
!     Get the target ID code here, since it will be needed
!     for the initialization calls below.
!
      call zzbods2c ( ctx, svctr1, svtarg, svtcde, svfnd1, &
                      target, trgcde, fnd    )

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The target, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit. '           )
         call ctx%errch  ( '#', target                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     Check whether the surface name/ID mapping has been updated.
!
      call zzsrftrk ( ctx, svctr4, surfup )

!
!     If necessary, parse the method specification. PRVMTH
!     and the derived flags NEAR and ELIPSD start out with
!     valid values. PRVMTH records the last valid value of
!     METHOD; ELIPSD is the corresponding shape flag.
!
      if ( first  .or.  surfup  .or.  ( method /= prvmth ) ) then
!
!        Set the previous method string to an invalid value, so it
!        cannot match any future, valid input. This will force this
!        routine to parse the input method on the next call if any
!        failure occurs in this branch. Once success is assured, we can
!        record the current method in the previous method string.
!
         prvmth = ' '

!
!        Parse the method string. If the string is valid, the
!        outputs SHAPE and SUBTYP will always be be set. However,
!        SUBTYP is not used in this routine.
!
!        For DSK shapes, the surface list array and count will be set
!        if the method string contains a surface list.
!
         call zzprsmet ( ctx, trgcde, method, size(srflst, kind=ip), shpstr, subtyp, &
                         pri,    nsurf,  srflst, pntdef, trmstr )

         if ( ctx%failed() ) return

         if (  eqstr( shpstr, 'ELLIPSOID' )  ) then

            shape = ellshp

         else if (  eqstr( shpstr, 'DSK' )  ) then

            shape = dskshp

         else
!
!           This is a backstop check.
!
            call ctx%setmsg ( '[1] Returned shape value from method ' &
            //            'string was <#>.'                      )
            call ctx%errch  ( '#', shpstr                            )
            call ctx%sigerr ( 'SPICE(BUG)'                           )
            return

         end if

!
!        There should be no subtype specification in the method
!        string.
!
         if ( subtyp /= ' ' ) then

            call ctx%setmsg ( 'Spurious sub-observer point type <#> ' &
            //            'was present in the method string #. ' &
            //            'The sub-observer type is valid in ' &
            //            'the method strings for SUBPNT and ' &
            //            'SUBSLR, but is not applicable for ILLUMG.' )
            call ctx%errch  ( '#', subtyp                                 )
            call ctx%errch  ( '#', method                                 )
            call ctx%sigerr ( 'SPICE(INVALIDMETHOD)'                      )
            return

         end if

         prvmth = method

      end if

!
!     At this point, the first pass actions were successful.
!
      first = .false.

!
!     Obtain integer codes for the observer and
!     illumination source.
!
      call zzbods2c ( ctx, svctr2, svobsr, svobsc, svfnd2, &
                      obsrvr, obscde, fnd    )

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The observer, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit. '           )
         call ctx%errch  ( '#', obsrvr                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     Check the observer and target body codes. If they are equal,
!     signal an error.
!
      if ( obscde == trgcde ) then

         call ctx%setmsg ( 'In computing illumination angles, ' &
         //            'the observing body and target body are the ' &
         //            'same. Both are #.'                          )
         call ctx%errch  ( '#',  obsrvr                                 )
         call ctx%sigerr ( 'SPICE(BODIESNOTDISTINCT)'                   )
         return

      end if

!
!     Determine the attributes of the frame designated by FIXREF.
!
      call zznamfrm ( ctx, svctr3, svfref, svrefc, fixref, fxfcde )

      call frinfo ( ctx, fxfcde, center, type, typeid, fnd )

      if ( ctx%failed() ) return

      if ( .not. fnd ) then

         call ctx%setmsg ( 'Reference frame # is not recognized by ' // &
                       'the SPICE frame subsystem. Possibly '    // &
                       'a required frame definition kernel has ' // &
                       'not been loaded.'                        )
         call ctx%errch  ( '#',  fixref                              )
         call ctx%sigerr ( 'SPICE(NOFRAME)'                          )
         return

      end if

!
!     Make sure that FIXREF is centered at the target body's center.
!
      if ( center /= trgcde ) then

         call ctx%setmsg ( 'Reference frame # is not centered at the ' &
         //            'target body #. The ID code of the frame ' &
         //            'center is #.'                             )
         call ctx%errch  ( '#',  fixref                               )
         call ctx%errch  ( '#',  target                               )
         call ctx%errint ( '#',  center                               )
         call ctx%sigerr ( 'SPICE(INVALIDFRAME)'                      )
         return

      end if

!
!     Get the sign S prefixing LT in the expression for TRGEPC.
!     When light time correction is not used, setting S = 0
!     allows us to seamlessly set TRGEPC equal to ET.
!
!     We don't support transmission corrections, so S is never
!     set to 1.
!
      if ( uselt ) then

         if ( xmit ) then
            s =  1.0_wp
         else
            s = -1.0_wp
         end if

      else
         s =  0.0_wp
      end if

!
!     Look up the state of the surface point relative to the observer.
!     The body-fixed frame of the surface point is to be evaluated
!     at the epoch of the surface point, not at the epoch of the
!     center of the frame; we indicate this by setting the input
!     argument EVLREF to 'TARGET'.
!
      call spkcpt ( ctx, spoint,   target, fixref, et,     fixref, &
                    'TARGET', abcorr, obsrvr, opstat, lt     )

      if ( ctx%failed() ) return

!
!     TRGEPC is the epoch associated with the surface point. Below,
!     since S is set to 0.D0 if no aberration corrections are used, we
!     require no logical branch.
!
      trgepc = et  +  ( s * lt )

!
!     Now find the state of the illumination source as seen by
!     the surface point at TRGEPC. We want to evaluate the orientation
!     of the body-fixed frame of the surface point at the epoch
!     associated with the surface point, not at the epoch associated
!     with the frame's center;  we indicate this by setting the input
!     argument EVLREF to 'OBSERVER'.
!
      call spkcpo ( ctx, ilusrc, trgepc, fixref, 'OBSERVER', abcorr, &
                    spoint, target, fixref, tistat,     lti     )

      if ( ctx%failed() ) return

!
!     Find the surface normal at SPOINT. This computation depends
!     on target body shape model.
!
      if ( shape == ellshp ) then
!
!        We'll need the radii of the target body.
!
         call zzgftreb ( ctx, trgcde, radii )

         call surfnm ( ctx, radii(1), radii(2), radii(3), spoint, normal )
!
!        We check FAILED at the end of the IF block.
!
      else if ( shape == dskshp ) then
!
!        Compute the outward unit normal at SPOINT on the surface
!        defined by the designated DSK data.
!
         call zzsbfnrm ( ctx, trgcde, nsurf,  srflst, et, &
                         fxfcde, spoint, normal     )
!
!        We check FAILED at the end of the IF block.
!
      else
!
!        We've already checked the computation method input argument,
!        so we don't expect to arrive here. This code is present for
!        safety.
!
         call ctx%setmsg ( 'The computation method # was not recognized. ' )
         call ctx%errch  ( '#',  method                                    )
         call ctx%sigerr ( 'SPICE(INVALIDMETHOD)'                          )
         return

      end if

!
!     Check for errors before calling math routines.
!
      if ( ctx%failed() ) return

!
!     We'll need the negative of the observer-surface point position
!     for the following angle computation. Set the output SRFVEC while
!     we're at it.
!
      srfvec = opstat(1:3)
      obspos = -srfvec

!
!     Find the illumination angles. VSEP will give us angular
!     separation in radians.
!
      phase   =  vsep ( obspos, tistat )
      incdnc  =  vsep ( normal, tistat )
      emissn  =  vsep ( normal, obspos )

!
!     TRGEPC has already been set.
!
      return
      end associate
      end subroutine illumg

      !> Map array of surface points on a specified target body to
      !> the corresponding unit length outward surface normal vectors.
      !>
      !> The surface of the target body may be represented by a triaxial
      !> ellipsoid or by topographic data provided by DSK files.
      !>
      !>## Detailed Input
      !>
      !>     METHOD   is a short string providing parameters defining
      !>              the computation method to be used. In the syntax
      !>              descriptions below, items delimited by brackets
      !>              are optional.
      !>
      !>              METHOD may be assigned the following values:
      !>
      !>                 'ELLIPSOID'
      !>
      !>                    The normal vector computation uses a triaxial
      !>                    ellipsoid to model the surface of the target
      !>                    body. The ellipsoid's radii must be available
      !>                    in the kernel pool.
      !>
      !>                 'DSK/UNPRIORITIZED[/SURFACES = <surface list>]'
      !>
      !>                    The normal vector computation uses topographic
      !>                    data to model the surface of the target body.
      !>                    These data must be provided by loaded DSK
      !>                    files.
      !>
      !>                    The surface list specification is optional. The
      !>                    syntax of the list is
      !>
      !>                       <surface 1> [, <surface 2>...]
      !>
      !>                    If present, it indicates that data only for the
      !>                    listed surfaces are to be used; however, data
      !>                    need not be available for all surfaces in the
      !>                    list. If absent, loaded DSK data for any surface
      !>                    associated with the target body are used.
      !>
      !>                    The surface list may contain surface names or
      !>                    surface ID codes. Names containing blanks must
      !>                    be delimited by double quotes, for example
      !>
      !>                       SURFACES = "Mars MEGDR 128 PIXEL/DEG"
      !>
      !>                    If multiple surfaces are specified, their names
      !>                    or IDs must be separated by commas.
      !>
      !>                    See the $Particulars section below for details
      !>                    concerning use of DSK data.
      !>
      !>              Neither case nor white space are significant in
      !>              METHOD, except within double-quoted strings. For
      !>              example, the string ' eLLipsoid ' is valid.
      !>
      !>              Within double-quoted strings, blank characters are
      !>              significant, but multiple consecutive blanks are
      !>              considered equivalent to a single blank. Case is
      !>              not significant. So
      !>
      !>                 "Mars MEGDR 128 PIXEL/DEG"
      !>
      !>              is equivalent to
      !>
      !>                 " mars megdr  128  pixel/deg "
      !>
      !>              but not to
      !>
      !>                 "MARS MEGDR128PIXEL/DEG"
      !>
      !>     TARGET   is the name of the target body. TARGET is
      !>              case-insensitive, and leading and trailing blanks in
      !>              TARGET are not significant. Optionally, you may
      !>              supply a string containing the integer ID code for
      !>              the object. For example both 'MOON' and '301' are
      !>              legitimate strings that indicate the Moon is the
      !>              target body.
      !>
      !>              When the target body's surface is represented by a
      !>              tri-axial ellipsoid, this routine assumes that a
      !>              kernel variable representing the ellipsoid's radii is
      !>              present in the kernel pool. Normally the kernel
      !>              variable would be defined by loading a PCK file.
      !>
      !>     ET       is the epoch for which target surface data will be
      !>              selected, if the surface is modeled using DSK data.
      !>              In this case, only segments having time coverage that
      !>              includes the epoch ET will be used.
      !>
      !>              ET is ignored if the target is modeled as an
      !>              ellipsoid.
      !>
      !>              ET is expressed as TDB seconds past J2000 TDB.
      !>
      !>     FIXREF   is the name of a body-fixed reference frame centered
      !>              on the target body. FIXREF may be any such frame
      !>              supported by the SPICE system, including built-in
      !>              frames (documented in the Frames Required Reading)
      !>              and frames defined by a loaded frame kernel (FK). The
      !>              string FIXREF is case-insensitive, and leading and
      !>              trailing blanks in FIXREF are not significant.
      !>
      !>              The input surface points in the array SRFPTS are
      !>              expressed relative to this reference frame, as are
      !>              the normal vectors computed by this routine.
      !>
      !>     NPTS     is the number of surface points in the array SRFPTS.
      !>
      !>     SRFPTS   is an array of target body surface points. Elements
      !>
      !>                 SRFPTS(1,I)
      !>                 SRFPTS(2,I)
      !>                 SRFPTS(3,I)
      !>
      !>              are the Cartesian coordinates, expressed in the
      !>              reference frame designated by FIXREF, of the Ith
      !>              surface point in the array. Each surface point
      !>              represents an offset from the center of that frame.
      !>
      !>              All surface points must actually be "on" the surface,
      !>              that is, the distance of each point from the surface
      !>              must be less than a small margin. See the $Parameters
      !>              section below for a description of this margin.
      !>
      !>## Detailed Output
      !>
      !>     NORMLS   is an array of unit length, outward normal vectors
      !>              corresponding to the points in SRFPTS. Elements
      !>
      !>                 NORMLS(1,I)
      !>                 NORMLS(2,I)
      !>                 NORMLS(3,I)
      !>
      !>              are the Cartesian coordinates, expressed in the
      !>              reference frame designated by FIXREF, of the Ith
      !>              normal vector in the array.
      !>
      !>## Parameters
      !>
      !>     PTMEMM   is the default point-surface membership margin. This
      !>              margin limits the distance an input point can be from
      !>              a surface and still be considered to lie on that
      !>              surface.
      !>
      !>              The details of the application of PTMEMM are
      !>              implementation-dependent. In the DSK case, roughly
      !>              speaking, a point-surface distance limit within a DSK
      !>              segment is set to
      !>
      !>                 PTMEMM * MAXR
      !>
      !>              where MAXR is the radius of an outer bounding sphere
      !>              for the segment.
      !>
      !>              For shapes modeled as ellipsoids, the expression
      !>              above is applied to the maximum radius of the
      !>              ellipsoid.
      !>
      !>              See the include file
      !>
      !>                 dsktol.inc
      !>
      !>              for the declaration of PTMEMM.
      !>
      !>              This margin can be overridden. See dsktol.inc
      !>              and DSKSTL for details.
      !>
      !>## Exceptions
      !>
      !>     1)  If the target body name specified in the input string cannot
      !>         be converted to an integer ID code, the error
      !>         SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     2)  If the input target body-fixed frame FIXREF is not
      !>         recognized, the error SPICE(NOFRAME) is signaled. A frame
      !>         name may fail to be recognized because a required frame
      !>         specification kernel has not been loaded; another cause is a
      !>         misspelling of the frame name.
      !>
      !>     3)  If the input frame FIXREF is not centered at the target body,
      !>         the error SPICE(INVALIDFRAME) is signaled.
      !>
      !>     4)  If data are not available to convert between the frame
      !>         FIXREF and the frame of a DSK segment of interest, an error
      !>         is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     5)  If the input argument METHOD cannot be parsed, an error
      !>         is signaled by either this routine or a routine in
      !>         the call tree of this routine.
      !>
      !>     6)  If the computation method specifies an ellipsoidal target
      !>         model, and if triaxial radii of the target body have not been
      !>         loaded into the kernel pool prior to calling SRFNRM, an error
      !>         is signaled by a routine in the call tree of this routine.
      !>
      !>     7)  If the computation method specifies an ellipsoidal target
      !>         model, and if any of the radii of the target body are
      !>         non-positive, an error is signaled by a routine in the call
      !>         tree of this routine. The target must be an extended body.
      !>
      !>     8)  If METHOD specifies that the target surface is represented by
      !>         DSK data, and no DSK files are loaded for the specified
      !>         target, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     9)  If METHOD specifies that the target surface is represented by
      !>         DSK data, and data representing the portion of the surface
      !>         corresponding to the surface points provided in SRFPTS are
      !>         not available, an error is signaled by a routine in the
      !>         call tree of this routine.
      !>
      !>     10) If an input surface point is not within a small tolerance
      !>         of the specified surface, the error SPICE(POINTNOTONSURFACE)
      !>         is signaled. See the $Parameters section for details.
      !>
      !>     11) If the radii are not available in the kernel pool, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     12) If the target shape is "ellipsoid" and not all radii of the
      !>         ellipsoid are strictly positive, the error
      !>         SPICE(BADAXISLENGTH) is signaled.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  Shape data for the target body:
      !>
      !>          PCK data:
      !>
      !>             If the target shape is modeled as an ellipsoid,
      !>             triaxial radii for the target body must be loaded into
      !>             the kernel pool. Typically this is done by loading a
      !>             text PCK file via FURNSH.
      !>
      !>          DSK data:
      !>
      !>             If the target shape is modeled by DSK data, DSK files
      !>             containing topographic data for the target body must be
      !>             loaded. If a surface list is specified, data for at
      !>             least one of the listed surfaces must be loaded.
      !>
      !>     -  Target body orientation data: these may be provided in a
      !>        text or binary PCK file. In some cases, target body
      !>        orientation may be provided by one more more CK files. In
      !>        either case, data are made available by loading the files
      !>        via FURNSH.
      !>
      !>     The following data may be required:
      !>
      !>     -  Frame data: if a frame definition is required to convert
      !>        between the body-fixed frame of the target and the frame of
      !>        a DSK segment providing topographic data, that definition
      !>        must be available in the kernel pool. Typically the
      !>        definition is supplied by loading a frame kernel via FURNSH.
      !>
      !>     -  Surface name-ID associations: if surface names are specified
      !>        in METHOD, the association of these names with their
      !>        corresponding surface ID codes must be established by
      !>        assignments of the kernel variables
      !>
      !>           NAIF_SURFACE_NAME
      !>           NAIF_SURFACE_CODE
      !>           NAIF_SURFACE_BODY
      !>
      !>        Normally these associations are made by loading a text
      !>        kernel containing the necessary assignments. An example of
      !>        such a set of assignments is
      !>
      !>           NAIF_SURFACE_NAME += 'Mars MEGDR 128 PIXEL/DEG'
      !>           NAIF_SURFACE_CODE += 1
      !>           NAIF_SURFACE_BODY += 499
      !>
      !>     -  SCLK data: if the target body's orientation is provided by
      !>        CK files, an associated SCLK kernel must be loaded.
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     Using DSK data
      !>     ==============
      !>
      !>        DSK loading and unloading
      !>        -------------------------
      !>
      !>        DSK files providing data used by this routine are loaded by
      !>        calling FURNSH and can be unloaded by calling UNLOAD or
      !>        KCLEAR. See the documentation of FURNSH for limits on numbers
      !>        of loaded DSK files.
      !>
      !>        For run-time efficiency, it's desirable to avoid frequent
      !>        loading and unloading of DSK files. When there is a reason to
      !>        use multiple versions of data for a given target body---for
      !>        example, if topographic data at varying resolutions are to be
      !>        used---the surface list can be used to select DSK data to be
      !>        used for a given computation. It is not necessary to unload
      !>        the data that are not to be used. This recommendation presumes
      !>        that DSKs containing different versions of surface data for a
      !>        given body have different surface ID codes.
      !>
      !>        DSK data priority
      !>        -----------------
      !>
      !>        A DSK coverage overlap occurs when two segments in loaded DSK
      !>        files cover part or all of the same domain---for example, a
      !>        given longitude-latitude rectangle---and when the time
      !>        intervals of the segments overlap as well.
      !>
      !>        When DSK data selection is prioritized, in case of a coverage
      !>        overlap, if the two competing segments are in different DSK
      !>        files, the segment in the DSK file loaded last takes
      !>        precedence. If the two segments are in the same file, the
      !>        segment located closer to the end of the file takes
      !>        precedence.
      !>
      !>        When DSK data selection is unprioritized, data from competing
      !>        segments are combined. For example, if two competing segments
      !>        both represent a surface as sets of triangular plates, the
      !>        union of those sets of plates is considered to represent the
      !>        surface.
      !>
      !>        Currently only unprioritized data selection is supported.
      !>        Because prioritized data selection may be the default behavior
      !>        in a later version of the routine, the UNPRIORITIZED keyword is
      !>        required in the METHOD argument.
      !>
      !>        Syntax of the METHOD input argument
      !>        -----------------------------------
      !>
      !>        The keywords and surface list in the METHOD argument
      !>        are called "clauses." The clauses may appear in any
      !>        order, for example
      !>
      !>           DSK/<surface list>/UNPRIORITIZED
      !>           DSK/UNPRIORITIZED/<surface list>
      !>           UNPRIORITIZED/<surface list>/DSK
      !>
      !>        The simplest form of the METHOD argument specifying use of
      !>        DSK data is one that lacks a surface list, for example:
      !>
      !>           'DSK/UNPRIORITIZED'
      !>
      !>        For applications in which all loaded DSK data for the target
      !>        body are for a single surface, and there are no competing
      !>        segments, the above string suffices. This is expected to be
      !>        the usual case.
      !>
      !>        When, for the specified target body, there are loaded DSK
      !>        files providing data for multiple surfaces for that body, the
      !>        surfaces to be used by this routine for a given call must be
      !>        specified in a surface list, unless data from all of the
      !>        surfaces are to be used together.
      !>
      !>        The surface list consists of the string
      !>
      !>           SURFACES =
      !>
      !>        followed by a comma-separated list of one or more surface
      !>        identifiers. The identifiers may be names or integer codes in
      !>        string format. For example, suppose we have the surface
      !>        names and corresponding ID codes shown below:
      !>
      !>           Surface Name                              ID code
      !>           ------------                              -------
      !>           'Mars MEGDR 128 PIXEL/DEG'                1
      !>           'Mars MEGDR 64 PIXEL/DEG'                 2
      !>           'Mars_MRO_HIRISE'                         3
      !>
      !>        If data for all of the above surfaces are loaded, then
      !>        data for surface 1 can be specified by either
      !>
      !>           'SURFACES = 1'
      !>
      !>        or
      !>
      !>           'SURFACES = "Mars MEGDR 128 PIXEL/DEG"'
      !>
      !>        Double quotes are used to delimit the surface name because
      !>        it contains blank characters.
      !>
      !>        To use data for surfaces 2 and 3 together, any
      !>        of the following surface lists could be used:
      !>
      !>           'SURFACES = 2, 3'
      !>
      !>           'SURFACES = "Mars MEGDR  64 PIXEL/DEG", 3'
      !>
      !>           'SURFACES = 2, Mars_MRO_HIRISE'
      !>
      !>           'SURFACES = "Mars MEGDR 64 PIXEL/DEG", Mars_MRO_HIRISE'
      !>
      !>        An example of a METHOD argument that could be constructed
      !>        using one of the surface lists above is
      !>
      !>           'DSK/UNPRIORITIZED/SURFACES = "Mars MEGDR 64 PIXEL/DEG", 3'
      !>
      !>## Examples
      !>
      !>     The numerical results shown for this example may differ across
      !>     platforms. The results depend on the SPICE kernels used as input,
      !>     the compiler and supporting libraries, and the machine specific
      !>     arithmetic implementation.
      !>
      !>     1) Compute outward normal vectors at surface points on a target
      !>        body, where the points correspond to a given planetocentric
      !>        longitude/latitude grid. Use both ellipsoid and DSK shape
      !>        models.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File: srfnrm_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                        Contents
      !>              ---------                        --------
      !>              pck00010.tpc                     Planet orientation and
      !>                                               radii
      !>              phobos512.bds                    DSK based on
      !>                                               Gaskell ICQ Q=512
      !>                                               plate model
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'pck00010.tpc',
      !>                                  'phobos512.bds' )
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>      PROGRAM SRFNRM_EX1
      !>      IMPLICIT NONE
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      DPR
      !>      DOUBLE PRECISION      RPD
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         FMT1
      !>      PARAMETER           ( FMT1   = '(1X,A,F11.6)' )
      !>
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'srfnrm_ex1.tm' )
      !>
      !>      INTEGER               BDNMLN
      !>      PARAMETER           ( BDNMLN = 36 )
      !>
      !>      INTEGER               FILSIZ
      !>      PARAMETER           ( FILSIZ = 255 )
      !>
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>      INTEGER               LNSIZE
      !>      PARAMETER           ( LNSIZE = 79 )
      !>
      !>      INTEGER               MAXN
      !>      PARAMETER           ( MAXN   = 100000 )
      !>
      !>      INTEGER               MTHLEN
      !>      PARAMETER           ( MTHLEN = 80 )
      !>C
      !>C     Local variables
      !>C
      !>      CHARACTER*(FRNMLN)    FIXREF
      !>      CHARACTER*(MTHLEN)    METHOD ( 2 )
      !>      CHARACTER*(LNSIZE)    OUTLIN
      !>      CHARACTER*(BDNMLN)    TARGET
      !>
      !>      DOUBLE PRECISION      DLAT
      !>      DOUBLE PRECISION      DLON
      !>      DOUBLE PRECISION      ET
      !>      DOUBLE PRECISION      GRID   ( 2, MAXN )
      !>      DOUBLE PRECISION      LAT
      !>      DOUBLE PRECISION      LAT0
      !>      DOUBLE PRECISION      LON
      !>      DOUBLE PRECISION      LON0
      !>      DOUBLE PRECISION      NORMLS ( 3, MAXN, 2 )
      !>      DOUBLE PRECISION      NRMLAT
      !>      DOUBLE PRECISION      NRMLON
      !>      DOUBLE PRECISION      NRMRAD
      !>      DOUBLE PRECISION      SRFPTS ( 3, MAXN, 2 )
      !>      DOUBLE PRECISION      XLAT
      !>      DOUBLE PRECISION      XLON
      !>      DOUBLE PRECISION      XR
      !>
      !>      INTEGER               I
      !>      INTEGER               J
      !>      INTEGER               N
      !>      INTEGER               NLAT
      !>      INTEGER               NLON
      !>
      !>C
      !>C     Saved variables
      !>C
      !>      SAVE                  GRID
      !>      SAVE                  NORMLS
      !>      SAVE                  SRFPTS
      !>
      !>C
      !>C     Load kernels.
      !>C
      !>      CALL FURNSH ( META )
      !>C
      !>C     Set target, reference frame, and epoch.
      !>C
      !>      TARGET = 'PHOBOS'
      !>      FIXREF = 'IAU_PHOBOS'
      !>      ET     = 0.D0
      !>C
      !>C     Use both a reference ellipsoid and DSK data
      !>C     to represent the surface.
      !>C
      !>      METHOD(1) = 'ELLIPSOID'
      !>      METHOD(2) = 'DSK/UNPRIORITIZED'
      !>C
      !>C     Set the grid dimensions.
      !>C
      !>      NLON   = 6
      !>      NLAT   = 3
      !>C
      !>C     Derive evenly spaced grid separations and starting
      !>C     values in the longitude and latitude dimensions.
      !>C     Units are degrees.
      !>C
      !>      LAT0 = 90.D0
      !>      LON0 =  0.D0
      !>
      !>      DLAT = 180.D0 / (NLAT + 1)
      !>      DLON = 360.D0 /  NLON
      !>
      !>C
      !>C     Now generate the grid points.  We generate
      !>C     points along latitude bands, working from
      !>C     north to south.  The latitude range is selected
      !>C     to range from +45 to -45 degrees.  Longitude
      !>C     ranges from 0 to 300 degrees.  The increment
      !>C     is 45 degrees for latitude and 60 degrees for
      !>C     longitude.
      !>C
      !>      N = 0
      !>
      !>      DO I = 1, NLAT
      !>
      !>         LAT = RPD() * ( LAT0 - I*DLAT )
      !>
      !>         DO J = 1, NLON
      !>
      !>            N   = N + 1
      !>            LON = RPD() * ( LON0 + (J-1)*DLON )
      !>
      !>            GRID(1,N) = LON
      !>            GRID(2,N) = LAT
      !>
      !>         END DO
      !>
      !>      END DO
      !>
      !>C
      !>C     Find the surface points corresponding to the grid points.
      !>C
      !>C
      !>C     Compute outward normal vectors at the surface points,
      !>C     using both surface representations.
      !>C
      !>      DO I = 1, 2
      !>
      !>         CALL LATSRF ( METHOD(I),    TARGET, ET,
      !>     .                 FIXREF,       N,      GRID,
      !>     .                 SRFPTS(1,1,I)              )
      !>
      !>         CALL SRFNRM ( METHOD(I),    TARGET, ET,
      !>     .                 FIXREF,       N,      SRFPTS(1,1,I),
      !>     .                 NORMLS(1,1,I)                      )
      !>      END DO
      !>
      !>      WRITE (*,*) 'Number of grid points: ', N
      !>
      !>C
      !>C     Print out the surface points in latitudinal
      !>C     coordinates and compare the derived lon/lat values
      !>C     to those of the input grid for the first 3 points.
      !>C
      !>      DO I = 1, 3
      !>C
      !>C        Use RECRAD rather than RECLAT to produce
      !>C        non-negative longitudes.
      !>C
      !>         CALL RECRAD ( SRFPTS(1,I,1), XR, XLON, XLAT )
      !>
      !>         WRITE (*,*) ' '
      !>
      !>         OUTLIN = ' Surface point for grid point #:'
      !>         CALL REPMI  ( OUTLIN, '#', I, OUTLIN )
      !>         CALL TOSTDO ( OUTLIN )
      !>
      !>         WRITE (*,*)    '  Latitudinal Coordinates:'
      !>         WRITE (*,FMT1) '    Longitude           (deg): ',
      !>     .                  XLON*DPR()
      !>         WRITE (*,FMT1) '    Latitude            (deg): ',
      !>     .                  XLAT*DPR()
      !>         WRITE (*,FMT1) '    Ellipsoid Radius     (km): ',
      !>     .                  XR
      !>
      !>         CALL RECRAD ( SRFPTS(1,I,2), XR, XLON, XLAT )
      !>
      !>         WRITE (*,FMT1) '    DSK Radius           (km): ',
      !>     .                  XR
      !>C
      !>C        Convert the Ith normal vector to latitudinal
      !>C        coordinates.
      !>C
      !>         CALL RECRAD ( NORMLS(1,I,1), NRMRAD, NRMLON, NRMLAT )
      !>
      !>         WRITE (*,*)    '  Ellipsoid normal vector direction:'
      !>         WRITE (*,FMT1) '    Longitude           (deg): ',
      !>     .                       NRMLON*DPR()
      !>         WRITE (*,FMT1) '    Latitude            (deg): ',
      !>     .                      NRMLAT*DPR()
      !>
      !>         CALL RECRAD ( NORMLS(1,I,2), NRMRAD, NRMLON, NRMLAT )
      !>
      !>         WRITE (*,*)    '  DSK normal vector direction:'
      !>         WRITE (*,FMT1) '    Longitude           (deg): ',
      !>     .                  NRMLON*DPR()
      !>         WRITE (*,FMT1) '    Latitude            (deg): ',
      !>     .                  NRMLAT*DPR()
      !>
      !>      END DO
      !>
      !>      END
      !>```
      !>
      !>        When this program was executed on a Mac/Intel/gfortran/64-bit
      !>        platform, the output was:
      !>
      !>         Number of grid points:           18
      !>
      !>         Surface point for grid point 1:
      !>           Latitudinal Coordinates:
      !>             Longitude           (deg):    0.000000
      !>             Latitude            (deg):   45.000000
      !>             Ellipsoid Radius     (km):   10.542977
      !>             DSK Radius           (km):   10.156402
      !>           Ellipsoid normal vector direction:
      !>             Longitude           (deg):    0.000000
      !>             Latitude            (deg):   63.895146
      !>           DSK normal vector direction:
      !>             Longitude           (deg):  341.337568
      !>             Latitude            (deg):   62.610726
      !>
      !>         Surface point for grid point 2:
      !>           Latitudinal Coordinates:
      !>             Longitude           (deg):   60.000000
      !>             Latitude            (deg):   45.000000
      !>             Ellipsoid Radius     (km):   10.172847
      !>             DSK Radius           (km):   10.131412
      !>           Ellipsoid normal vector direction:
      !>             Longitude           (deg):   66.059787
      !>             Latitude            (deg):   58.877649
      !>           DSK normal vector direction:
      !>             Longitude           (deg):   48.859884
      !>             Latitude            (deg):   56.924717
      !>
      !>         Surface point for grid point 3:
      !>           Latitudinal Coordinates:
      !>             Longitude           (deg):  120.000000
      !>             Latitude            (deg):   45.000000
      !>             Ellipsoid Radius     (km):   10.172847
      !>             DSK Radius           (km):   10.423766
      !>           Ellipsoid normal vector direction:
      !>             Longitude           (deg):  113.940213
      !>             Latitude            (deg):   58.877649
      !>           DSK normal vector direction:
      !>             Longitude           (deg):  118.553200
      !>             Latitude            (deg):   55.906774
      !>
      !>        Note that only the first 3 points of the grid are
      !>        presented in the output (the rest of the points are not
      !>        shown due to their large number).
      !>
      !>## Restrictions
      !>
      !>     None.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 08-JUL-2020 (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>        Limited the number of grid points presented in the output of
      !>        the code example to three.
      !>
      !>-    SPICELIB Version 1.0.0, 22-FEB-2017 (NJB)
      !>
      !>        Added FAILED call.
      !>
      !>        01-JUL-2016 (NJB)
      module subroutine srfnrm ( ctx, method, target, et, fixref, npts, srfpts, normls )
      use pepper_containers, only: grow
      use pepper_kinds, only: ip, wp
      use pepper_math, only: vhatip
      use pepper_strings, only: eqstr
      use pepper_inc_dsktol
      use pepper_inc_gf
      use pepper_inc_zzctr
      use pepper_inc_zzdsk
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: method  !! Computation method.
      character(*), intent(in) :: target  !! Name of target body.
      real(wp), intent(in) :: et  !! Epoch in TDB seconds past J2000 TDB.
      character(*), intent(in) :: fixref  !! Body-fixed, body-centered target body frame.
      integer(ip), intent(in) :: npts  !! Number of surface points in input array.
      real(wp), intent(in) :: srfpts ( 3, * )  !! Array of surface points.
      real(wp), intent(out) :: normls ( 3, * )  !! Array of outward, unit length normal vectors.
      character(cvtlen) :: lmbtyp
      character(shplen) :: shpstr
      character(sublen) :: subtyp
      character(tmtlen) :: trmtyp
      real(wp) :: a2
      real(wp) :: b2
      real(wp) :: c2
      real(wp) :: level
      real(wp) :: limit
      real(wp) :: ptsrfm
      integer(ip) :: fixfid
      integer(ip) :: fxcent
      integer(ip) :: fxclss
      integer(ip) :: fxclid
      integer(ip) :: i
      integer(ip) :: n
      integer(ip) :: trgcde
      logical :: fnd
      logical :: surfup
      real(wp) :: maxr
      logical :: pri
      if ( .not. allocated ( ctx%srfnrm_state ) ) allocate ( ctx%srfnrm_state )
!
!     PEPPER: the surface list has room for any number of surfaces (it
!     grows before the ASSOCIATE block; SPICELIB's held MAXSRF, 100).
!
      call grow ( ctx%srfnrm_state%srflst, len(method)/2 + 1 )
      associate ( svctr1 => ctx%srfnrm_state%svctr1, &
                  svtarg => ctx%srfnrm_state%svtarg, &
                  svtcde => ctx%srfnrm_state%svtcde, &
                  svfnd1 => ctx%srfnrm_state%svfnd1, &
                  svctr2 => ctx%srfnrm_state%svctr2, &
                  svfref => ctx%srfnrm_state%svfref, &
                  svfxfc => ctx%srfnrm_state%svfxfc, &
                  svctr3 => ctx%srfnrm_state%svctr3, &
                  svprvt => ctx%srfnrm_state%svprvt, &
                  svradi => ctx%srfnrm_state%svradi, &
                  nsurf => ctx%srfnrm_state%nsurf, &
                  first => ctx%srfnrm_state%first, &
                  prvmth => ctx%srfnrm_state%prvmth, &
                  shape => ctx%srfnrm_state%shape, &
                  srfctr => ctx%srfnrm_state%srfctr, &
                  srflst => ctx%srfnrm_state%srflst )
      if ( ctx%failed() ) return

      if ( first ) then
!
!        Initialize local surface counter.
!
         call zzctruin ( ctx, srfctr )
!
!        Initialize target, frame, and radius counters.
!
         call zzctruin ( ctx, svctr1 )
         call zzctruin ( ctx, svctr2 )
         call zzctruin ( ctx, svctr3 )

      end if

!
!     Obtain integer code for the target.
!
      call zzbods2c ( ctx, svctr1, svtarg, svtcde, svfnd1, &
                      target, trgcde, fnd    )

      if ( ctx%failed() ) return

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The target, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit, or that you ' &
         //            'failed to load a kernel containing a ' &
         //            'name-ID mapping for this body.'           )
         call ctx%errch  ( '#', target                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     Determine the attributes of the frame designated by FIXREF.
!
      call zznamfrm ( ctx, svctr2, svfref, svfxfc, fixref, fixfid )

      call frinfo ( ctx, fixfid, fxcent, fxclss, fxclid, fnd )

      if ( ctx%failed() ) return

      if ( .not. fnd ) then

         call ctx%setmsg ( 'Reference frame # is not recognized by ' // &
                       'the SPICE frame subsystem. Possibly '    // &
                       'a required frame definition kernel has ' // &
                       'not been loaded.'                        )
         call ctx%errch  ( '#',  fixref                              )
         call ctx%sigerr ( 'SPICE(NOFRAME)'                          )
         return

      end if

!
!     Make sure that FIXREF is centered at the target body's center.
!
      if ( fxcent /= trgcde ) then

         call ctx%setmsg ( 'Reference frame # is not centered at the ' &
         //            'target body #. The ID code of the frame ' &
         //            'center is #.'                             )
         call ctx%errch  ( '#',  fixref                               )
         call ctx%errch  ( '#',  target                               )
         call ctx%errint ( '#',  fxcent                               )
         call ctx%sigerr ( 'SPICE(INVALIDFRAME)'                      )
         return

      end if

!
!     Check whether the surface name/ID mapping has been updated.
!
      call zzsrftrk ( ctx, srfctr, surfup )

!
!     Initialize the SINCPT utility package for the next computation.
!     The choice of initialization routine depends on the target
!     surface type.
!
      if ( first  .or.  surfup  .or.  ( method /= prvmth ) ) then
!
!        Set the previous method string to an invalid value, so it
!        cannot match any future, valid input. This will force this
!        routine to parse the input method on the next call if any
!        failure occurs in this branch. Once success is assured, we can
!        record the current method in the previous method string.
!
         prvmth = ' '

!
!        Parse the method string. If the string is valid, the
!        outputs SHAPE and SUBTYP will always be be set. However,
!        SUBTYP is not used in this routine.
!
!        For DSK shapes, the surface list array and count will be set
!        if the method string contains a surface list.
!
         call zzprsmet ( ctx, trgcde, method, size(srflst, kind=ip), shpstr, subtyp, &
                         pri,    nsurf,  srflst, lmbtyp, trmtyp )

         if ( ctx%failed() ) return

         if (  eqstr( shpstr, 'ELLIPSOID' )  ) then

            shape = ellshp

         else if (  eqstr( shpstr, 'DSK' )  ) then

            shape = dskshp

         else
!
!           This is a backstop check.
!
            call ctx%setmsg ( '[1] Returned shape value from method ' &
            //            'string was <#>.'                      )
            call ctx%errch  ( '#', shpstr                            )
            call ctx%sigerr ( 'SPICE(BUG)'                           )
            return

         end if

!
!        There should be no subtype specification in the method
!        string.
!
         if ( subtyp /= ' ' ) then

            call ctx%setmsg ( 'Spurious sub-observer point type <#> ' &
            //            'was present in the method string #. ' &
            //            'The sub-observer type is valid in ' &
            //            'the method strings for SUBPNT and ' &
            //            'SUBSLR, but is not applicable for SRFNRM.' )
            call ctx%errch  ( '#', subtyp                                 )
            call ctx%errch  ( '#', method                                 )
            call ctx%sigerr ( 'SPICE(INVALIDMETHOD)'                      )
            return

         end if

         prvmth = method

      end if

!
!     At this point, the first pass actions were successful.
!
      first = .false.

!
!     Check the target body shape.
!
      if ( shape == ellshp ) then

         if ( trgcde /= svprvt ) then
!
!           Reset counter to force lookup.
!
            call zzctruin ( ctx, svctr3 )

         end if
!
!        Look up target radii using counter.
!
         call zzbodvcd ( ctx, trgcde, 'RADII', 3, svctr3, n, svradi )

         if ( ctx%failed() ) return

         if (  min( svradi(1), svradi(2), svradi(3) ) <= 0.0_wp ) then

            call ctx%setmsg ( 'Body # radii should be positive but ' &
            //            'were # # #.'                         )
            call ctx%errch  ( '#',  target                          )
            call ctx%errdp  ( '#',  svradi(1)                       )
            call ctx%errdp  ( '#',  svradi(2)                       )
            call ctx%errdp  ( '#',  svradi(3)                       )
            call ctx%sigerr ( 'SPICE(BADAXISLENGTH)'                )
            return

         end if

!
!        The radii are valid. Update the previous target ID.
!
         svprvt = trgcde

!
!        Compute the point-surface distance limit.
!
         maxr   = max ( svradi(1), svradi(2), svradi(3) )

         call dskgtl ( ctx, keyptm, ptsrfm )

         limit  = ptsrfm * maxr

!
!        Generate normal vectors.
!
         do i = 1, npts

            a2    = svradi(1)*svradi(1)
            b2    = svradi(2)*svradi(2)
            c2    = svradi(3)*svradi(3)

            level = (   ( srfpts(1,i)*srfpts(1,i) / a2 ) &
                      + ( srfpts(2,i)*srfpts(2,i) / b2 ) &
                      + ( srfpts(3,i)*srfpts(3,i) / c2 )  ) ** 0.5_wp

!
!           The test below is a distance test if the target shape
!           is a sphere. For other ellipsoids, it's an approximation.
!
            if ( abs( level - 1.0_wp ) >= limit ) then

               call ctx%setmsg ( 'Input point at index # is not on ' &
               //            'the target body surface. The ' &
               //            'level surface parameter (x/a)**2 ' &
               //            '+ (y/b)**2 + (z/c)**2 for this ' &
               //            'point is #.'                      )
               call ctx%errint ( '#', i                             )
               call ctx%errdp  ( '#', level                         )
               call ctx%sigerr ( 'SPICE(POINTNOTONSURFACE)'         )
               return

            end if

            call surfnm ( ctx, svradi(1),   svradi(2),  svradi(3), &
                          srfpts(1,i), normls(1,i)            )

            if ( ctx%failed() ) return

         end do

      else if  ( shape == dskshp ) then
!
!        Generate normal vectors.
!
         do i = 1, npts
!
!           Use the DSK API segment buffering system to efficiently
!           select relevant segments and compute normals.
!
            call zzsbfnrm ( ctx, trgcde, nsurf,       srflst,     et, &
                            fixfid, srfpts(1,i), normls(1,i)     )

            if ( ctx%failed() ) return

!
!           Make sure normals have unit length.
!
            call vhatip ( normls(1,i) )

         end do

      else

         call ctx%setmsg ( 'Input method <#> does not specify ' &
         //            'the target shape as either ELLIPSOID ' &
         //            'or DSK.'                               )
         call ctx%errch  ( '#', method                             )
         call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                   )
         return

      end if

      return
      end associate
      end subroutine srfnrm

      !> Initialize generalized intercept utilities, which are entry
      !> points in this package, by storing the target ID code and
      !> ellipsoid radii to be used by the callback entry points of this
      !> package.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     TRGCDE   is the integer body ID of the target body for which
      !>              ray-surface intercept or ray-surface near point
      !>              computations are to be performed by the callback
      !>              entry points of this package.
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If an error occurs during lookup of the target body's radii,
      !>         the error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     2)  If the body-fixed frame used by the caller of this routine
      !>         does not have its axes properly aligned with the target
      !>         body's reference ellipsoid, results from this routine will be
      !>         invalid.
      !>
      !>         This routine does not have the capability of detecting such
      !>         an error.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>     This routine expects the radii of the target body's reference
      !>     ellipsoid to be present in the kernel pool.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by SPICELIB.
      !>
      !>     This routine supports the generalized ray-surface intercept
      !>     algorithm used by SINCPT.
      !>
      !>     This routine prepares the callback entry points for computations
      !>     using an ellipsoidal shape model. It obtains radii for ellipsoid
      !>     computations: ray-ellipsoid intersection computation using SURFPT
      !>     and ray-ellipsoid altitude computation using NPEDLN.
      !>
      !>     Note the absence of a frame ID from the argument list. This
      !>     routine and related utilities assume the input ray vectors are
      !>     expressed in a body-fixed frame centered at the target body's
      !>     center, having its axes aligned with the principal axes of the
      !>     target body's reference ellipsoid.
      !>
      !>## Examples
      !>
      !>     See usage in SINCPT, ZZSFXCOR.
      !>
      !>## Restrictions
      !>
      !>     1)  This is a private routine.
      !>
      !>     2)  See exception (2) above.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 30-MAY-2021 (NJB) (JDR)
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>        Updated comments.
      !>
      !>-    SPICELIB Version 1.0.0, 01-JUN-2016 (NJB)
      module subroutine zzsuelin ( ctx, trgcde )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: trgcde  !! Target body ID code.
      if ( .not. allocated ( ctx%zzsinutl_state ) ) allocate ( ctx%zzsinutl_state )
      associate ( savmnr => ctx%zzsinutl_state%savmnr, &
                  savmxr => ctx%zzsinutl_state%savmxr, &
                  savrad => ctx%zzsinutl_state%savrad, &
                  savtyp => ctx%zzsinutl_state%savtyp )
      if ( ctx%failed() ) return

      savtyp = elltrg

      call zzgftreb ( ctx, trgcde, savrad )

      if ( ctx%failed() ) return

      savmnr = min( savrad(1), savrad(2), savrad(3) )
      savmxr = max( savrad(1), savrad(2), savrad(3) )

      return
      end associate
      end subroutine zzsuelin

      !> Initialize generalized intercept utilities, which are entry
      !> points in this package, by storing the target ID code, DSK
      !> surface ID list, and frame ID to be used by the callback entry
      !> points of this package. This routine is to be used for
      !> computations in which the target surface is modeled using
      !> DSK data.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     TRGCDE   is the integer body ID of the target body for which
      !>              ray-surface intercept or ray-surface near point
      !>              computations are to be performed by the callback
      !>              entry points of this package.
      !>
      !>     NSURF,
      !>     SRFLST   are, respectively, the count of surface IDs in the
      !>              surface ID list and the list itself.
      !>
      !>              If the list is empty, all surfaces associated with
      !>              the target body are used.
      !>
      !>     FIXFID   is the frame ID code of a body-fixed reference frame
      !>              associated with the target body. The frame must be
      !>              centered at the target body's center.
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     MAXSRF   is the maximum supported size of a surface ID list.
      !>              See the include file dsk.inc for the parameter's
      !>              value.
      !>
      !>## Exceptions
      !>
      !>     1)  If the number of IDs in the surface list is negative or
      !>         exceeds MAXSRF, the error SPICE(INVALIDCOUNT) is signaled.
      !>
      !>     2)  If an error occurs during calculation of the radii of the
      !>         inner and outer bounding spheres for the target body,
      !>         the error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     3)  The reference frame designated by FIXFID must be centered
      !>         at the target body's center. This condition must be
      !>         checked by the caller of this routine.
      !>
      !>     4)  If a body RADII vector has other than exactly thee elements,
      !>         an error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     5)  If a body RADII vector has any element less-than or equal to
      !>         zero, an error is signaled by a routine in the call tree of
      !>         this routine.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by the DSK subsystem.
      !>
      !>     This routine supports the generalized ray-surface intercept
      !>     algorithm used by SINCPT.
      !>
      !>     This routine prepares the callback entry points for computations
      !>     using a DSK shape model. It stores the target body ID, DSK
      !>     surface ID list, and ID of the target body-fixed frame. It
      !>     also computes the radii of the inner and outer bounding
      !>     surfaces for the target body; these surfaces are computed using
      !>     loaded DSK segments for the surfaces indicated by the input
      !>     body ID and surface ID list.
      !>
      !>     The stored quantities are used by the callback entry points of
      !>     this package.
      !>
      !>## Examples
      !>
      !>     See usage in SINCPT, ZZSFXCOR.
      !>
      !>## Restrictions
      !>
      !>     1)  This is a private routine.
      !>
      !>     2)  See exception (2) above.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>     E.D. Wright        (JPL)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.1.0, 07-SEP-2021 (EDW) (JDR)
      !>
      !>        Body radii accessed from kernel pool using ZZGFTREB.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 01-JUN-2016 (NJB)
      module subroutine zzsudski ( ctx, trgcde, nsurf, srflst, fixfid )
      use pepper_containers, only: grow
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: trgcde  !! Target body ID code.
      integer(ip), intent(in) :: nsurf  !! Number of surface IDs in surface list.
      integer(ip), intent(in) :: srflst ( * )  !! Surface list.
      integer(ip), intent(in) :: fixfid  !! Target body-fixed frame ID.
      if ( .not. allocated ( ctx%zzsinutl_state ) ) allocate ( ctx%zzsinutl_state )
!
!     PEPPER: the surface list has room for any number of surfaces (it
!     grows before the ASSOCIATE block; SPICELIB's held MAXSRF, 100).
!
      call grow ( ctx%zzsinutl_state%savsrf, max(1_ip, nsurf) )
      associate ( savfid => ctx%zzsinutl_state%savfid, &
                  savmnr => ctx%zzsinutl_state%savmnr, &
                  savmxr => ctx%zzsinutl_state%savmxr, &
                  savnsf => ctx%zzsinutl_state%savnsf, &
                  savrad => ctx%zzsinutl_state%savrad, &
                  savsrf => ctx%zzsinutl_state%savsrf, &
                  savtrg => ctx%zzsinutl_state%savtrg, &
                  savtyp => ctx%zzsinutl_state%savtyp )
      if ( ctx%failed() ) return

      savtyp = dsktrg

!
!     PEPPER: any number of surfaces (SPICELIB required at most MAXSRF,
!     100).
!
      if ( nsurf < 0 ) then
         call ctx%setmsg ( 'Surface count must be non-negative ' &
         //            'but was #.'                         )
         call ctx%errint ( '#', nsurf                           )
         call ctx%sigerr ( 'SPICE(INVALIDCOUNT)'                )
         return
      end if

      savnsf = nsurf

      savsrf(1:savnsf) = srflst(1:savnsf)

      savfid = fixfid
      savtrg = trgcde

      savrad = 0.0_wp

      if ( ctx%failed() ) return

!
!     Fetch minimum and maximum radius of target body surface.
!
      call zzdsksph ( ctx, trgcde, savnsf, savsrf, savmnr, savmxr )

      return
      end associate
      end subroutine zzsudski

      !> Perform ray-surface intercept using values set via the
      !> initialization entry points of this package. This routine
      !> is used as a callback by the generalized ray-surface intercept
      !> algorithm.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     VERTEX,
      !>     RAYDIR   are, respectively, the vertex and direction vector of
      !>              a ray. When the target's surface is represented by DSK
      !>              data, both vectors are expressed in the frame
      !>              designated by FIXFID, which is set via a call to one
      !>              of the initialization routines of this package.
      !>
      !>              When the target's surface is represented by an
      !>              ellipsoid, the vectors are presumed to be expressed in
      !>              a body-fixed frame compatible with that ellipsoid.
      !>
      !>     ET       is the epoch for which the computation is to be
      !>              performed. This epoch is used for DSK segment
      !>              selection; only segments containing ET in their time
      !>              coverage interval will be used. ET is expressed as
      !>              seconds past J2000 TDB.
      !>
      !>## Detailed Output
      !>
      !>     SPOINT   is the surface intercept on the target body
      !>              nearest to the ray's vertex, if the intercept
      !>              exists.
      !>
      !>     FOUND    is a logical flag that is set to .TRUE. if and
      !>              only if an intercept exists.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If an error occurs while this routine attempts to compute a
      !>         surface intercept, the error is signaled by a routine in
      !>         the call tree of this routine.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>     If any loaded DSK segment has a reference frame that is not
      !>     centered at the segment's central (target) body, SPK data are
      !>     required to compute the offset between the frame's center and
      !>     the segment's center.
      !>
      !>     Frame kernels may be required in order to look up a segment's
      !>     frame center offset. In some cases, additional kernels such
      !>     as CK kernels and SCLK kernels could be required to support
      !>     the offset vector lookup.
      !>
      !>     This routine uses PCK data for target body reference ellipsoids.
      !>
      !>     If an ellipsoidal target model is selected, this routine expects
      !>     the radii of the target body's reference ellipsoid to be present
      !>     in the kernel pool.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by SPICELIB.
      !>
      !>     This routine prepares the local buffers for a ray-surface
      !>     intercept computation using unprioritized DSK data. It calls
      !>     ZZSBFXR to perform the computation.
      !>
      !>## Examples
      !>
      !>     See usage in SINCPT, ZZSFXCOR.
      !>
      !>## Restrictions
      !>
      !>     1)  This is a private routine.
      !>
      !>     2)  One of the initialization routines ZZSUDSKI or ZZSUELIN
      !>         must be called before the first time this routine is called.
      !>         Whenever the set of data to be considered changes, an
      !>         initialization call must be made before this routine may
      !>         be called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 30-MAY-2021 (NJB) (JDR)
      !>
      !>        Updated comments: this routine no longer is considered
      !>        a DSK subsystem routine.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 01-JUN-2016 (NJB)
      module subroutine zzraysfx ( ctx, vertex, raydir, et, spoint, found )
      use pepper_containers, only: grow
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: et  !! Evaluation epoch, seconds past J2000 TDB.
      real(wp), intent(in) :: vertex ( 3 )  !! Ray's vertex.
      real(wp), intent(in) :: raydir ( 3 )  !! Ray's direction vector.
      real(wp), intent(out) :: spoint ( 3 )  !! Surface intercept point.
      logical, intent(out) :: found  !! Found flag. .TRUE. if intercept exists.
      if ( .not. allocated ( ctx%zzsinutl_state ) ) allocate ( ctx%zzsinutl_state )
!
!     PEPPER: the surface list has room for any number of surfaces (it
!     grows before the ASSOCIATE block; SPICELIB's held MAXSRF, 100).
!
      call grow ( ctx%zzsinutl_state%savsrf, 1_ip )
      associate ( savfid => ctx%zzsinutl_state%savfid, &
                  savnsf => ctx%zzsinutl_state%savnsf, &
                  savrad => ctx%zzsinutl_state%savrad, &
                  savsrf => ctx%zzsinutl_state%savsrf, &
                  savtrg => ctx%zzsinutl_state%savtrg, &
                  savtyp => ctx%zzsinutl_state%savtyp )
      if ( ctx%failed() ) return

      if ( savtyp == elltrg ) then

         call surfpt ( ctx, vertex,    raydir,    savrad(1), &
                       savrad(2), savrad(3), spoint,    found )

      else if ( savtyp == dsktrg ) then

         call zzsbfxr ( ctx, savtrg, savnsf, savsrf, et, &
                        savfid, vertex, raydir, spoint, found )

      else

         call ctx%setmsg ( 'Surface type code # is not supported. ' &
         //            'This code branch is not supposed to be ' &
         //            'reached.'                               )
         call ctx%errint ( '#', savtyp                              )
         call ctx%sigerr ( 'SPICE(BUG)'                             )
         return

      end if

      return
      end associate
      end subroutine zzraysfx

      !> Return the radius of an outer bounding sphere for the target body.
      !> The radius is not necessarily a minimum upper bound.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     MAXRAD   is the radius of an outer bounding sphere for the
      !>              target body. The sphere is centered at the center of
      !>              the target body.
      !>
      !>              If the target's surface is modeled as an ellipsoid,
      !>              this radius is the maximum radius of the ellipsoid. If
      !>              the target's surface is modeled using DSK data, the
      !>              radius is determined by the surface list used at
      !>              initialization time.
      !>
      !>              The radius is not necessarily a least upper bound.
      !>
      !>              Units are km.
      !>
      !>## Detailed Output
      !>
      !>     None.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If a bounding sphere has not been computed due to
      !>         initialization failure, the value returned by this
      !>         routine will be invalid.
      !>
      !>## Files
      !>
      !>     None. However, see the $Files sections of routines ZZSUELIN
      !>     and ZZSUDSKI.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by SPICELIB.
      !>
      !>     This routine supports the generalized ray-surface intercept
      !>     algorithm used by SINCPT.
      !>
      !>     Note: this routine does not accept an epoch as an input argument,
      !>     so when the last setup was performed by ZZSUDSKI, this routine
      !>     computes its result using all DSK segments for the target body
      !>     (the ID code of which was passed to ZZSUDSKI). This could result
      !>     in the computed maximum radius being substantially larger than
      !>     the maximum radius that would be obtained by considering only
      !>     segments covering the epoch of interest.
      !>
      !>     The routine considers all segments for the target in the
      !>     interest of efficiency: it simply returns a value that was
      !>     computed during the last setup call. If the routine were
      !>     time-dependent, it would need to re-compute the maximum radius
      !>     each time it was called.
      !>
      !>     If a need arises for a time-dependent version of this routine,
      !>     that routine should be given a new name, and the routine should
      !>     be added to this package.
      !>
      !>## Examples
      !>
      !>     See usage in SINCPT, ZZSFXCOR.
      !>
      !>## Restrictions
      !>
      !>     1)  This is a private routine.
      !>
      !>     2)  One of the initialization routines ZZSUDSKI or ZZSUELIN
      !>         must be called before the first time this routine is called.
      !>         Whenever the set of data to be considered changes, an
      !>         initialization call must be made before this routine may
      !>         be called.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman       (JPL)
      !>     J. Diaz del Rio    (ODC Space)
      !>
      !>## Version
      !>
      !>-    SPICELIB Version 1.0.1, 16-JUL-2021 (NJB) (JDR)
      !>
      !>        Updated comments: this routine no longer is considered
      !>        a DSK subsystem routine.
      !>
      !>        Edited the header to comply with NAIF standard.
      !>
      !>-    SPICELIB Version 1.0.0, 01-JUN-2016 (NJB)
      module subroutine zzmaxrad ( ctx, maxrad )
      use pepper_kinds, only: ip, wp
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(out) :: maxrad  !! Radius of outer bounding sphere for target body.
      logical :: return
      if ( .not. allocated ( ctx%zzsinutl_state ) ) allocate ( ctx%zzsinutl_state )
      associate ( savmxr => ctx%zzsinutl_state%savmxr )
      maxrad = savmxr

      return
      end associate
      end subroutine zzmaxrad

      !> Return the radius of an inner bounding sphere for the target body.
      !> The radius is not necessarily a maximum lower bound.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     MINRAD   is the radius of the inner bounding sphere for the
      !>              target body. The sphere is centered at the center of
      !>              the target body.
      !>
      !>              If the target's surface is modeled as an ellipsoid,
      !>              this radius is the minimum radius of the ellipsoid. If
      !>              the target's surface is modeled using DSK data, the
      !>              radius is determined by the surface list used at
      !>              initialization time.
      !>
      !>              The radius is not necessarily a least upper bound.
      !>
      !>              Units are km.
      !>
      !>## Detailed Output
