      module subroutine subslr ( ctx, method, target, et, fixref, abcorr, obsrvr, spoint, trgepc, srfvec )
      use pepper_containers, only: grow
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: clight
      use pepper_math, only: mxv, vdist
      use pepper_strings, only: eqstr
      use pepper_inc_frmtyp, frmtyp_all => all  ! PEPPER: ALL (unused) would hide the intrinsic
      use pepper_inc_gf
      use pepper_inc_zzabcorr
      use pepper_inc_zzctr
      use pepper_inc_zzdsk
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      character(*), intent(in) :: method  !! Computation method.
      character(*), intent(in) :: target  !! Name of target body.
      real(wp), intent(in) :: et  !! Epoch in ephemeris seconds past J2000 TDB.
      character(*), intent(in) :: fixref  !! Body-fixed, body-centered target body frame.
      character(*), intent(in) :: abcorr  !! Aberration correction.
      character(*), intent(in) :: obsrvr  !! Name of observing body.
      real(wp), intent(out) :: spoint ( 3 )  !! Sub-solar point on the target body.
      real(wp), intent(out) :: trgepc  !! Sub-solar point epoch.
      real(wp), intent(out) :: srfvec ( 3 )  !! Vector from observer to sub-solar point.
      character(cvtlen) :: pntdef
      character(shplen) :: shpstr
      character(sublen) :: subtyp
      character(tmtlen) :: trmstr
      real(wp) :: altsun
      real(wp) :: dvec   ( 3 )
      real(wp) :: etdiff
      real(wp) :: j2pos  ( 3 )
      real(wp) :: lt
      real(wp) :: ltdiff
      real(wp) :: obspos ( 3 )
      real(wp) :: obsrng
      real(wp) :: prevet
      real(wp) :: prevlt
      real(wp) :: radii  ( 3 )
      real(wp) :: s
      real(wp) :: slt
      real(wp) :: spos   ( 3 )
      real(wp) :: ssbost ( 6 )
      real(wp) :: ssbtst ( 6 )
      real(wp) :: sslrlt
      real(wp) :: sslrst ( 6 )
      real(wp) :: sunst  ( 6 )
      real(wp) :: tpos   ( 3 )
      real(wp) :: xform  ( 3, 3 )
      integer(ip) :: fixcid
      integer(ip) :: fixcls
      integer(ip) :: fixctr
      integer(ip) :: fixfid
      integer(ip) :: i
      integer(ip) :: nitr
      integer(ip) :: obscde
      integer(ip) :: trgcde
      logical :: attblk ( nabcor )
      logical :: fnd
      logical :: surfup
      logical :: pri
      logical :: xmit
      if ( .not. allocated ( ctx%subslr_state ) ) allocate ( ctx%subslr_state )
!
!     PEPPER: the surface list has room for any number of surfaces (it
!     grows before the ASSOCIATE block; SPICELIB's held MAXSRF, 100).
!
      call grow ( ctx%subslr_state%srflst, len(method)/2 + 1 )
      associate ( first => ctx%subslr_state%first, &
                  near => ctx%subslr_state%near, &
                  nsurf => ctx%subslr_state%nsurf, &
                  prvcor => ctx%subslr_state%prvcor, &
                  prvmth => ctx%subslr_state%prvmth, &
                  shape => ctx%subslr_state%shape, &
                  srflst => ctx%subslr_state%srflst, &
                  usecn => ctx%subslr_state%usecn, &
                  uselt => ctx%subslr_state%uselt, &
                  usestl => ctx%subslr_state%usestl, &
                  svctr1 => ctx%subslr_state%svctr1, &
                  svtarg => ctx%subslr_state%svtarg, &
                  svtcde => ctx%subslr_state%svtcde, &
                  svfnd1 => ctx%subslr_state%svfnd1, &
                  svctr2 => ctx%subslr_state%svctr2, &
                  svobsr => ctx%subslr_state%svobsr, &
                  svobsc => ctx%subslr_state%svobsc, &
                  svfnd2 => ctx%subslr_state%svfnd2, &
                  svctr3 => ctx%subslr_state%svctr3, &
                  svfref => ctx%subslr_state%svfref, &
                  svrefc => ctx%subslr_state%svrefc, &
                  svctr4 => ctx%subslr_state%svctr4 )
      if ( ctx%failed() ) return

!
!     Counter initialization is done separately.
!
      if ( first ) then
!
!        Initialize counters.
!
         call zzctruin( ctx, svctr1 )
         call zzctruin( ctx, svctr2 )
         call zzctruin( ctx, svctr3 )

      end if

      if (  first  .or.  ( abcorr /= prvcor )  ) then
!
!        The aberration correction flag differs from the value it
!        had on the previous call, if any. Analyze the new flag.
!
         call zzvalcor ( ctx, abcorr, attblk )

         if ( ctx%failed() ) return

!
!        Reject an aberration correction flag calling for transmission
!        corrections.
!
         if ( attblk(xmtidx) ) then

            call ctx%setmsg ( 'Aberration correction flag # calls for ' &
            //            'transmission-style corrections.'        )
            call ctx%errch  ( '#', abcorr                              )
            call ctx%sigerr ( 'SPICE(NOTSUPPORTED)'                    )
            return

         end if

!
!        Set logical flags indicating the attributes of the requested
!        correction:
!
!           XMIT is .TRUE. when the correction is for transmitted
!           radiation.
!
!           USELT is .TRUE. when any type of light time correction
!           (normal or converged Newtonian) is specified.
!
!           USECN indicates converged Newtonian light time correction.
!
!        The above definitions are consistent with those used by
!        ZZPRSCOR.
!
         xmit    =  attblk ( xmtidx )
         uselt   =  attblk ( ltidx  )
         usecn   =  attblk ( cnvidx )
         usestl  =  attblk ( stlidx )

!
!        The aberration correction flag is recognized; save it.
!
         prvcor = abcorr

      end if

!
!     Obtain integer codes for the target and observer.
!
      call zzbods2c ( ctx, svctr1, svtarg, svtcde, svfnd1, &
                      target, trgcde, fnd    )

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The target, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit, or that you ' &
         //            'failed to load a kernel containing a ' &
         //            'name-ID mapping for this body.'           )
         call ctx%errch  ( '#', target                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

      call zzbods2c ( ctx, svctr2, svobsr, svobsc, svfnd2, &
                      obsrvr, obscde, fnd    )

      if ( .not. fnd ) then

         call ctx%setmsg ( 'The observer, ' &
         //            '''#'', is not a recognized name for an ' &
         //            'ephemeris object. The cause of this ' &
         //            'problem may be that you need an updated ' &
         //            'version of the SPICE Toolkit, or that you ' &
         //            'failed to load a kernel containing a ' &
         //            'name-ID mapping for this body.'           )
         call ctx%errch  ( '#', obsrvr                                )
         call ctx%sigerr ( 'SPICE(IDCODENOTFOUND)'                    )
         return

      end if

!
!     The target body may not be the sun.
!
      if ( trgcde == sun ) then

         call ctx%setmsg ( 'The target body is the sun; the sub-solar ' &
         //            'point is undefined for this case.'          )
         call ctx%sigerr ( 'SPICE(INVALIDTARGET)'                       )
         return

      end if

!
!     Determine the attributes of the frame designated by FIXREF.
!
      call zznamfrm ( ctx, svctr3, svfref, svrefc, fixref, fixfid )

      call frinfo ( ctx, fixfid, fixctr, fixcls, fixcid, fnd )

      if ( ctx%failed() ) return

      if ( .not. fnd ) then

         call ctx%setmsg ( 'Reference frame # is not recognized by ' // &
                       'the SPICE frame subsystem. Possibly '    // &
                       'a required frame definition kernel has ' // &
                       'not been loaded.'                        )
         call ctx%errch  ( '#',  fixref                              )
         call ctx%sigerr ( 'SPICE(NOFRAME)'                          )
         return

      end if

!
!     Make sure that FIXREF is centered at the target body's center.
!
      if ( fixctr /= trgcde ) then

         call ctx%setmsg ( 'Reference frame # is not centered at the ' &
         //            'target body #. The ID code of the frame ' &
         //            'center is #.'                             )
         call ctx%errch  ( '#',  fixref                               )
         call ctx%errch  ( '#',  target                               )
         call ctx%errint ( '#',  fixctr                               )
         call ctx%sigerr ( 'SPICE(INVALIDFRAME)'                      )
         return

      end if

!
!     Check whether the surface name/ID mapping has been updated.
!
      call zzsrftrk ( ctx, svctr4, surfup )

!
!     If necessary, parse the method specification. PRVMTH
!     and the derived variables NEAR and SHAPE start out with
!     valid values. PRVMTH records the last valid value of
!     METHOD; NEAR and SHAPE are the corresponding variables.
!
      if ( first  .or.  surfup  .or.  ( method /= prvmth ) ) then
!
!        Set the previous method string to an invalid value, so it
!        cannot match any future, valid input. This will force this
!        routine to parse the input method on the next call if any
!        failure occurs in this branch. Once success is assured, we can
!        record the current method in the previous method string.
!
         prvmth = ' '
!
!        Parse the method string. If the string is valid, the
!        outputs SHAPE and SUBTYP will always be be set. However,
!        SUBTYP is not used in this routine.
!
!        For DSK shapes, the surface list array and count will be set
!        if the method string contains a surface list.
!
         call zzprsmet ( ctx, trgcde, method, size(srflst, kind=ip), shpstr, subtyp, &
                         pri,    nsurf,  srflst, pntdef, trmstr )

         if ( ctx%failed() ) return

         if ( subtyp == ' ' ) then

            call ctx%setmsg ( 'Sub-solar point type is required ' &
            //            'but was not found in the method string #.' )
            call ctx%errch  ( '#', method                                 )
            call ctx%sigerr ( 'SPICE(INVALIDSUBTYPE)'                     )
            return

         end if

         if (  eqstr( shpstr, 'ELLIPSOID' )  ) then

            shape = ellshp

         else if (  eqstr( shpstr, 'DSK' )  ) then

            shape = dskshp

         else
!
!           This is a backstop check.
!
            call ctx%setmsg ( 'Returned shape value from method ' &
            //            'string was <#>.'                  )
            call ctx%errch  ( '#', shpstr                        )
            call ctx%sigerr ( 'SPICE(BUG)'                       )
            return

         end if

         if ( shape == ellshp ) then
!
!           Allow both "near point" and "nadir" expressions
!           the ellipsoid case, since these are equivalent.
!
            near =      eqstr( subtyp, 'NEAR POINT' ) &
                   .or. eqstr( subtyp, 'NADIR'      )

         else
!
!           "near point" is not supported for DSKs.
!
            near = eqstr( subtyp, 'NADIR' )

         end if

         if ( .not. near ) then

            if ( .not. eqstr( subtyp, 'INTERCEPT' ) ) then

               call ctx%setmsg ( 'Invalid sub-solar point type <#> ' &
               //            'was found in the method string #.' )
               call ctx%errch  ( '#', subtyp                         )
               call ctx%errch  ( '#', method                         )
               call ctx%sigerr ( 'SPICE(INVALIDSUBTYPE)'             )
               return

            end if

         end if

!
!        Save the current value of METHOD.
!
         prvmth = method

      end if

!
!     At this point, the first pass actions were successful.
!
      first = .false.

      if ( shape == dskshp ) then
!
!        This is the DSK case.
!
!        Initialize the intercept algorithm to use a DSK
!        model for the surface of the target body.
!
         call zzsudski ( ctx, trgcde, nsurf, srflst, fixfid )

      else if ( shape /= ellshp ) then

         call ctx%setmsg ( 'Computation method argument was <#>; this ' &
         //            'string must specify a supported shape ' &
         //            'model and computation type. See the ' &
         //            'header of SUBSLR for details.'            )
         call ctx%errch  ( '#',  method                               )
         call ctx%sigerr ( 'SPICE(INVALIDMETHOD)'                     )
         return

      end if

      if ( ctx%failed() ) return

!
!     Get the sign S prefixing LT in the expression for TRGEPC.
!     When light time correction is not used, setting S = 0
!     allows us to seamlessly set TRGEPC equal to ET.
!
      if ( uselt ) then
         s = -1.0_wp
      else
         s =  0.0_wp
      end if

!
!     Determine the position of the observer in target body-fixed
!     coordinates. This is a first estimate.
!
!         -  Call SPKEZP to compute the position of the target body as
!            seen from the observing body and the light time (LT)
!            between them. We request that the coordinates of POS be
!            returned relative to the body fixed reference frame
!            associated with the target body, using aberration
!            corrections specified by the input argument ABCORR.
!
!         -  Call VMINUS to negate the direction of the vector (OBSPOS)
!            so it will be the position of the observer as seen from
!            the target body in target body fixed coordinates.
!
!            Note that this result is not the same as the result of
!            calling SPKEZP with the target and observer switched. We
!            computed the vector FROM the observer TO the target in
!            order to get the proper light time and stellar aberration
!            corrections (if requested). Now we need the inverse of
!            that corrected vector in order to compute the sub-solar
!            point.
!
      call spkezp ( ctx, trgcde, et, fixref, abcorr, obscde, tpos, lt )

      if ( ctx%failed() ) return

!
!     Negate the target's position to obtain the position of the
!     observer relative to the target.
!
      obspos = -tpos

!
!     Make a first estimate of the target epoch.
!
      trgepc = et + s*lt

!
!     Find the sub-solar point given the target epoch, observer-target
!     position, and target body orientation we've already computed. If
!     we're not using light time correction, this is all we need do.
!     Otherwise, our result will give us an initial estimate of the
!     target epoch, which we'll then improve.
!

!
!     Get the radii of the target body from the kernel pool.
!
      call zzgftreb ( ctx, trgcde, radii )

      if ( ctx%failed() ) return

!
!     Get the position of the Sun SPOS as seen from the target
!     in the target body-fixed frame at TRGEPC.
!
      call spkezp ( ctx, sun, trgepc, fixref, abcorr, trgcde, spos, slt )

      if ( ctx%failed() ) return

!
!     Make a first estimate of the sub-solar point. The algorithm
!     we use depends on the sub-solar point definition.
!
      if ( near ) then
!
!        Locate the nearest point to the Sun on the target's
!        reference ellipsoid.
!
         call nearpt ( ctx, spos,   radii(1), radii(2), radii(3), &
                       spoint, altsun                       )

         if ( ctx%failed() ) return

!
!        If the target is an ellipsoid, the NEARPT call above does the
!        trick. For DSKs, we define a ray emanating from the sun and
!        passing through the near point on the reference ellipsoid. The
!        closest ray-DSK surface intercept to the sun is the initial
!        estimate of the sub-solar point.
!
         if ( shape == dskshp ) then
!
!           Generate the ray direction; find the DSK intercept.
!
            dvec = spoint - spos

            call zzsbfxr ( ctx, trgcde, nsurf, srflst, trgepc, &
                           fixfid, spos,  dvec,   spoint, fnd )

            if ( ctx%failed() ) return

            if ( .not. fnd ) then

               call ctx%setmsg ( 'No sub-solar point was found on ' &
               //            'the surface defined by DSK data. ' &
               //            'Observer is #; target is #. This ' &
               //            'problem can occur for bodies having ' &
               //            'shapes not well modeled by ' &
               //            'ellipsoids. Consider using the ' &
               //            '"Intercept: DSK" computation method.' )
               call ctx%errch  ( '#', obsrvr                            )
               call ctx%errch  ( '#', target                            )
               call ctx%sigerr ( 'SPICE(SUBPOINTNOTFOUND)'              )
               return

            end if

         end if

      else
!
!        This is the case for the "intercept" sub-solar point
!        definition.
!
!        Generate the ray direction.
!
         dvec = -spos

         if ( shape == ellshp ) then
!
!           Locate the surface intercept of the ray from the
!           sun to the target center.
!
            call surfpt ( ctx, spos,   dvec, radii(1), radii(2), radii(3), &
                          spoint, fnd                                )

            if ( ctx%failed() ) return

            if ( .not. fnd ) then
!
!              If there's no intercept, we have a numerical problem.
!
               call ctx%setmsg ( 'No intercept of sun-target ' &
               //            'ray was found.'              )
               call ctx%sigerr ( 'SPICE(DEGENERATECASE)'       )
               return

            end if

         else
!
!           Find the DSK intercept.
!
            call zzsbfxr ( ctx, trgcde, nsurf, srflst, trgepc, &
                           fixfid, spos,  dvec,   spoint, fnd )

            if ( ctx%failed() ) return

            if ( .not. fnd ) then

               call ctx%setmsg ( 'No sub-solar point was found on ' &
               //            'the surface defined by DSK data. ' &
               //            'Observer is #; target is #. This ' &
               //            'problem can occur for a body having ' &
               //            'an irregular shape such that the ' &
               //            'origin of the body-fixed reference ' &
               //            'frame is outside of the body. A tor' &
               //            'us is an example of such a shape.'   )
               call ctx%errch  ( '#', obsrvr                           )
               call ctx%errch  ( '#', target                           )
               call ctx%sigerr ( 'SPICE(SUBPOINTNOTFOUND)'             )
               return

            end if

         end if

      end if

      if ( ctx%failed() ) return

!
!     If we're not using light time and stellar aberration
!     corrections, we're almost done now. Note that we need only
!     check for use of light time corrections, because use of
!     stellar aberration corrections alone has been prevented by an
!     earlier check.
!
      if ( .not. uselt ) then
!
!        The TRGEPC value we'll return is simply the input time. The
!        previous call to SPKEZP call yielded the vector OBSPOS. SPOINT
!        was set immediately above. The only output left to compute is
!        SRFVEC.
!
         trgepc = et

         srfvec = spoint - obspos

         return

      end if

!
!     Compute the range from the observer to the sub-solar
!     point. We'll use this range for a light time estimate.
!
      obsrng = vdist ( obspos, spoint )

!
!     Compute the one-way light time and target epoch based on our
!     first computation of SPOINT. The coefficient S has been
!     set to give us the correct answer for each aberration
!     correction case.
!
      lt     = obsrng / clight
      trgepc = et  + s*lt

!
!     We'll now make an improved sub-solar point estimate using the
!     previous estimate of the sub-solar point. The number of
!     iterations depends on the light time correction type.
!
      if ( usecn ) then
         nitr = maxitr
      else
         nitr = 1
      end if

!
!     Get the J2000-relative state of the observer relative to
!     the solar system barycenter at ET.
!
      call spkssb ( ctx, obscde, et, 'J2000', ssbost )

      if ( ctx%failed() ) return

!
!     Initialize the variables required to evaluate the
!     loop termination condition.
!
      i      = 0
      ltdiff = 1.0_wp
      etdiff = 1.0_wp
      prevlt = lt
      prevet = trgepc

      do while (       ( i      <   nitr                ) &
                 .and. ( ltdiff > ( cnvlim * abs(lt) )  ) &
                 .and. ( etdiff >   0.0_wp                )  )
!
!        Get the J2000-relative state of the target relative to
!        the solar system barycenter at the target epoch.
!
         call spkssb ( ctx, trgcde, trgepc, 'J2000', ssbtst )

         if ( ctx%failed() ) return

!
!        Find the position of the observer relative to the target.
!        Convert this vector from the J2000 frame to the target
!        frame at TRGEPC.
!
         j2pos = ssbost(1:3) - ssbtst(1:3)
         call pxform ( ctx, 'J2000', fixref, trgepc, xform )

         if ( ctx%failed() ) return

         call mxv ( xform, j2pos, obspos )

!
!        Note: if we're using stellar aberration correction, we do not
!        apply the stellar aberration correction of the estimated
!        sub-solar point as seen by the observer to the next estimate
!        of the sun-solar point. The location of this point depends on
!        the illumination of the target, which is a function of the
!        observer-surface point light time. This is the only way in
!        which the observer plays a role in determining the sub-solar
!        point.
!
!        Stellar aberration of the sun's position relative to the
!        sub-solar point *is* used.
!
!        First find the apparent position of the sun as seen from the
!        estimated sub-solar point.
!

         call spkcpo ( ctx, 'SUN',  trgepc, fixref, 'OBSERVER', &
                       abcorr, spoint, target, fixref, sunst, slt )

!
!        Create the target-center to sun vector.
!
         spos = sunst(1:3) + spoint

         if ( ctx%failed() ) return

!
!        Find the sub-solar point using the current estimated
!        geometry.
!
         if ( near ) then
!
!           Locate the nearest point to the sun on the target's
!           reference ellipsoid.
!
            call nearpt ( ctx, spos,   radii(1), radii(2), radii(3), &
                          spoint, altsun                        )

            if ( ctx%failed() ) return
!
!           If the target is an ellipsoid, the NEARPT call above does
!           the trick. For DSKs, we define a ray emanating from the sun
!           and passing through the near point on the reference
!           ellipsoid. The closest ray-DSK surface intercept to the sun
!           is the initial estimate of the sub-solar point.
!
            if ( shape == dskshp ) then
!
!              Locate the surface intercept of the ray from the
!              Sun to the target center.
!
               dvec = spoint - spos

               call zzsbfxr ( ctx, trgcde, nsurf, srflst, trgepc, &
                              fixfid, spos,  dvec,   spoint, fnd )

               if ( ctx%failed() ) return

               if ( .not. fnd ) then

                  call ctx%setmsg ( 'No sub-solar point was found on ' &
                  //            'the surface defined by DSK data. ' &
                  //            'Observer is #; target is #. This ' &
                  //            'problem can occur for bodies hav' &
                  //            'ing shapes not well modeled by ' &
                  //            'ellipsoids. Consider using the ' &
                  //            '"Intercept: DSK" computation ' &
                  //            'method.'                        )
                  call ctx%errch  ( '#', obsrvr                      )
                  call ctx%errch  ( '#', target                      )
                  call ctx%sigerr ( 'SPICE(SUBPOINTNOTFOUND)'        )
                  return

               end if

            end if

         else

!           This is the "intercept" case.
!
!           Generate the ray direction.
!
            dvec = -spos

            if ( shape == ellshp ) then
!
!              Locate the surface intercept of the ray from the
!              sun to the target center.
!
               call surfpt ( ctx, spos,     dvec,   radii(1), radii(2), &
                             radii(3), spoint, fnd                )

               if ( ctx%failed() ) return

               if ( .not. fnd ) then
!
!                 If there's no intercept, we have a numerical problem.
!
                  call ctx%setmsg ( 'No intercept of sun-target ' &
                  //            'ray was found.'              )
                  call ctx%sigerr ( 'SPICE(DEGENERATECASE)'       )
                  return

               end if

            else
!
!              Find the DSK intercept.
!
               call zzsbfxr ( ctx, trgcde, nsurf, srflst, trgepc, &
                              fixfid, spos,  dvec,   spoint, fnd )

               if ( ctx%failed() ) return

               if ( .not. fnd ) then

                  call ctx%setmsg ( 'No sub-solar point was found on ' &
                  //            'the surface defined by DSK data. ' &
                  //            'Observer is #; target is #. This ' &
                  //            'problem can occur for a body having ' &
                  //            'an irregular shape such that the ' &
                  //            'origin of the body-fixed reference ' &
                  //            'frame is outside of the body. A tor' &
                  //            'us is an example of such a shape.'   )
                  call ctx%errch  ( '#', obsrvr                           )
                  call ctx%errch  ( '#', target                           )
                  call ctx%sigerr ( 'SPICE(SUBPOINTNOTFOUND)'             )
                  return

               end if

            end if

         end if

!
!        Update the observer to sub-solar point range.
!
         obsrng = vdist ( obspos, spoint )

!
!        Compute a new light time estimate and new target epoch.
!
         lt      =  obsrng / clight
         trgepc  =  et  + s*lt

!
!        At this point, we have new estimates of the sub-solar point
!        SPOINT, the observer altitude OBSRNG, the target epoch
!        TRGEPC, and the position of the observer relative to the
!        target OBSPOS.
!
!        We use the d.p. identity function TOUCHD to force the compiler
!        to create double precision arguments from the differences
!        LT-PREVLT and TRGEPC-PREVET. Some compilers will perform
!        extended-precision register arithmetic, which can prevent a
!        difference from rounding to zero. Simply storing the result of
!        the subtraction in a double precision variable doesn't solve
!        the problem, because that variable can be optimized out of
!        existence.
!
         ltdiff  =   abs( (lt     - prevlt) )
         etdiff  =   abs( (trgepc - prevet) )
         prevlt  =   lt
         prevet  =   trgepc
         i       =   i + 1

         call spkssb ( ctx, trgcde, trgepc, 'J2000', ssbtst )

         if ( ctx%failed() ) return

!
!        Find the position of the observer relative to the target.
!        Convert this vector from the J2000 frame to the target
!        frame at TRGEPC.
!
         j2pos = ssbost(1:3) - ssbtst(1:3)
         call pxform ( ctx, 'J2000', fixref, trgepc, xform )

         if ( ctx%failed() ) return

         call mxv ( xform, j2pos, obspos )

      end do

!
!     SPOINT and TRGEPC have been set. Compute SRFVEC, using
!     both light time and stellar aberration corrections if
!     these have been requested by the caller. Note that
!     the position of the target body was computed without
!     stellar aberration corrections, so we may not be able
!     to use it for this computation.
!
      if ( usestl ) then

         call spkcpt ( ctx, spoint,   target, fixref, et,     fixref, &
                       'TARGET', abcorr, obsrvr, sslrst, sslrlt )
         if ( ctx%failed() ) return

         srfvec = sslrst(1:3)

      else

         srfvec = spoint - obspos

      end if

      return
      end associate
      end subroutine subslr

      !> Initialize the data used by the tangent ray state routine
      !> ZZTANSTA, which is used directly by ZZTANGNT and indirectly by
      !> LIMBPT and TERMPT.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     CURVE      is an integer code indicating the type of set on the
      !>                target body on which tangent points are to be found.
      !>                When the target is an ellipsoid, the set is literally
      !>                a curve. When the target is a DSK shape, the set is
      !>                often not connected; so it is not actually a curve;
      !>                still, we retain the familiar terminology for the
      !>                ellipsoid case.
      !>
      !>                Possible values and meanings are:
      !>
      !>                   LMBCRV            limb
      !>                   UMBRAL            umbral terminator
      !>                   PNMBRL            penumbral terminator
      !>
      !>                Terminator computations are performed assuming
      !>                the light source is spherical.
      !>
      !>     SRCRAD     is the radius of the illumination source. This
      !>                value is used for terminator computations only.
      !>                When used, SRCRAD must be strictly positive.
      !>                Units are km.
      !>
      !>     SHAPE      is an integer code indicating the target body shape.
      !>
      !>                Possible values and meanings are:
      !>
      !>                   ELLSHP            shape is modeled as an ellipsoid
      !>                   DSKSHP            shape is provided by DSK data
      !>
      !>     TRGCDE     is the body ID code of the target body.
      !>
      !>     NSURF,
      !>     SRFLST     are, respectively, the count of surface IDs and the
      !>                surface ID list.
      !>
      !>     FIXFID     is the frame ID code of a body-fixed frame centered
      !>                on the target body. The output tangent points will
      !>                be expressed in this frame.
      !>
      !>     ET         is the computation epoch, expressed as seconds past
      !>                J2000 TDB. ET is used for DSK segment selection.
      !>                If the target shape is modeled as an ellipsoid, ET
      !>                is ignored.
      !>
      !>     PLNVEC     is a vector used to define a half-plane in which
      !>                to search for tangent rays. The half-plane contains
      !>                PLNVEC, the target body center, and AXIS.
      !>
      !>                For limb and umbral terminator computations,
      !>                tangent rays lie in the half-plane containing PLNVEC.
      !>
      !>                For penumbral terminator computations, tangent rays
      !>                touch the target in the half-plane containing PLNVEC,
      !>                but touch the light source in the complementary
      !>                half-plane bounded by the line containing AXIS.
      !>
      !>     AXIS       is a second vector used to define a half-plane in
      !>                which to search for tangent vectors. AXIS lies in
      !>                the line forming the boundary of the half-plane.
      !>
      !>                For limb computations, AXIS points from the target
      !>                toward the observation point.
      !>
      !>                For terminator computations, AXIS points from the
      !>                target toward the center of the illumination source.
      !>
      !>## Detailed Output
      !>
      !>     None. This routine operates by side effects.
      !>
      !>## Parameters
      !>
      !>     See the INCLUDE file zzdsk.inc for declarations of these
      !>     parameters.
      !>
      !>     ELLSHP     is a code specifying an ellipsoidal shape model.
      !>
      !>     DSKSHP     is a code specifying a DSK-based shape model.
      !>
      !>     LMBCRV     is a code specifying a limb computation.
      !>
      !>     UMBRAL     is a code specifying an umbral terminator computation.
      !>
      !>                The umbral terminator is the boundary of the portion
      !>                of the target surface that receives no light from the
      !>                illumination source.
      !>
      !>     PNMBRL     is a code specifying an penumbral terminator
      !>                computation.
      !>
      !>                The penumbral terminator is the boundary of the
      !>                portion of the target surface that is not subject to
      !>                self-occultation of light from the illumination
      !>                source. Given that the light source is modeled as
      !>                a sphere, from any target surface point nearer to
      !>                the source than the penumbral terminator, the source
      !>                appears to be a lit disc.
      !>
      !>## Exceptions
      !>
      !>     1)  If AXIS is the zero vector, the error SPICE(ZEROVECTOR) is
      !>         signaled.
      !>
      !>     2)  If PLNDEF is the zero vector, the error SPICE(ZEROVECTOR) is
      !>         signaled.
      !>
      !>     3)  If the curve type code is unrecognized, the error
      !>         SPICE(BADCURVETYPE) is signaled.
      !>
      !>     4)  If a terminator curve is specified by the source radius
      !>         is non-positive, the error SPICE(BADSOURCERADIUS) is
      !>         signaled.
      !>
      !>     5)  If AXIS and PLNDEF are linearly dependent, the error
      !>         SPICE(DEGENERATECASE) is signaled.
      !>
      !>     6)  If the target shape code is unrecognized, the error
      !>         SPICE(BADSHAPE) is signaled.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>     If any loaded DSK segment has a reference frame that is not
      !>     centered at the segment's central (target) body, SPK data are
      !>     required to compute the offset between the frame's center and
      !>     the segment's center.
      !>
      !>     Frame kernels may be required in order to look up a segment's
      !>     frame center offset. In some cases, additional kernels such
      !>     as CK kernels and SCLK kernels could be required to support
      !>     the offset vector lookup.
      !>
      !>     This routine uses PCK data for target body reference
      !>     ellipsoids.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by the DSK subsystem.
      !>
      !>     This routine initializes the tangent ray utilities for limb or
      !>     terminator computation.
      !>
      !>## Examples
      !>
      !>     See usage in ZZTANGNT.
      !>
      !>## Restrictions
      !>
      !>     1) This is a private routine.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-     SPICELIB Version 1.0.0 11-FEB-2016 (NJB)
      !>
      !>        Original version 26-OCT-2015 (NJB)
      module subroutine zztanini ( ctx, curve, srcrad, shape, trgcde, nsurf, srflst, fixfid, et, plnvec, axis )
      use pepper_kinds, only: ip, wp
      use pepper_math, only: vcrss, vhat, vhatip
      use pepper_inc_zzdsk
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: curve  !! Type of curve: limb or terminator type.
      real(wp), intent(in) :: srcrad  !! Radius of illumination source.
      integer(ip), intent(in) :: shape  !! Target shape.
      integer(ip), intent(in) :: trgcde  !! Target body ID code.
      integer(ip), intent(in) :: nsurf  !! Number of surfaces in list.
      integer(ip), intent(in) :: srflst ( * )  !! Surface ID list.
      integer(ip), intent(in) :: fixfid  !! Frame ID of target body-fixed frame.
      real(wp), intent(in) :: et  !! Epoch, expressed as seconds past J2000 TDB.
      real(wp), intent(in) :: plnvec ( 3 )  !! Reference vector contained in cutting half-plane.
      real(wp), intent(in) :: axis   ( 3 )  !! Axis vector: edge of cutting half-plane.
      real(wp) :: apex   ( 3 )
      real(wp) :: raydir ( 3 )
      real(wp) :: vrtoff ( 3 )
      if ( .not. allocated ( ctx%zztanutl_state ) ) allocate ( ctx%zztanutl_state )
      associate ( svaxis => ctx%zztanutl_state%svaxis, &
                  svcurv => ctx%zztanutl_state%svcurv, &
                  svet => ctx%zztanutl_state%svet, &
                  svirad => ctx%zztanutl_state%svirad, &
                  svnrml => ctx%zztanutl_state%svnrml, &
                  svvrtx => ctx%zztanutl_state%svvrtx )
      if ( ctx%failed() ) return

!
!     Check for zero vectors on input.
!
      if ( all(axis == 0.0_wp) ) then

         call ctx%setmsg ( 'Input axis vector is the zero vector.' )
         call ctx%sigerr ( 'SPICE(ZEROVECTOR)'                     )
         return

      end if

      if ( all(plnvec == 0.0_wp) ) then

         call ctx%setmsg ( 'Input reference vector is the zero vector.' )
         call ctx%sigerr ( 'SPICE(ZEROVECTOR)'                          )
         return

      end if

!
!     Save the curve type.
!
      if (       ( curve /= lmbcrv ) &
          .and.  ( curve /= umbral ) &
          .and.  ( curve /= pnmbrl )  ) then

         call ctx%setmsg ( 'Curve type code # was not recognized.' )
         call ctx%errint ( '#', curve                              )
         call ctx%sigerr ( 'SPICE(BADCURVETYPE)'                   )
         return

      end if

      svcurv = curve

!
!     Save the illumination source radius.
!
      if (  ( curve == umbral ) .or. ( curve == pnmbrl )  ) then

         if ( srcrad <= 0.0_wp ) then

            call ctx%setmsg ( 'The source radius was #. The radius ' &
            //            'must be positive for a terminator ' &
            //            'computation.'                         )
            call ctx%errdp  ( '#', srcrad                            )
            call ctx%sigerr ( 'SPICE(BADSOURCERADIUS)'               )
            return

         end if

      end if

      svirad = srcrad

!
!     Compute a normal vector to the plane defined by
!     AXIS and PLNVEC. The direction of positive rotation
!     about the normal is from AXIS toward PLNVEC.
!
      call vcrss ( axis, plnvec, svnrml )

      if ( all(svnrml == 0.0_wp) ) then

         call ctx%setmsg ( 'Input reference vector and axis vector ' &
         //            'are linearly dependent.'                 )
         call ctx%sigerr ( 'SPICE(DEGENERATECASE)'                   )
         return

      end if

!
!     Scale the normal vector to unit length.
!
      call vhatip ( svnrml )

!
!     Save a unit-length copy of the input axis.
!     Save the original axis as the ray's vertex; this
!     will be used directly in the limb computation and
!     will be used, after addition of an offset, in the
!     terminator computations. Save the evaluation epoch.
!
      svvrtx = axis
      call vhat ( axis, svaxis )

      svet = et
!
!     Prepare the DSK SINCPT utilities for a computation with
!     the input surface set.
!
      if ( shape == ellshp ) then
!
!        This is the ellipsoid case.
!
         call zzsuelin ( ctx, trgcde )

      else if ( shape == dskshp ) then
!
!        This is the DSK case.
!
         call zzsudski ( ctx, trgcde, nsurf, srflst, fixfid )

      else

         call ctx%setmsg ( 'Target shape code # was not recognized.' )
         call ctx%errint ( '#', shape                                )
         call ctx%sigerr ( 'SPICE(BADSHAPE)'                         )
         return

      end if

      return
      end associate
      end subroutine zztanini

      !> This is the state callback routine used by ZZTANSLV to
      !> find tangent rays on the target body's surface.
      !>
      !> Indicate whether a vector emanating from a given vertex, and
      !> rotated about the normal by the specified angle, measured from
      !> the AXIS direction, intersects the target. If an intersection
      !> exists, return the intercept closest to the ray's vertex.
      !>
      !> The ray's vertex depends on the curve type set via a call
      !> to ZZTANINI.
      !>
      !> This routine is called directly by ZZTANGNT and is used
      !> indirectly by LIMBPT and TERMPT.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     ANGLE      is the angle between a ray and the AXIS vector
      !>                stored by ZZTANINI. AXIS points away from the
      !>                target.
      !>
      !>                The vertex of the vector depends on the curve type,
      !>                which also is stored by ZZTANINI.
      !>
      !>                For a limb computation, the vertex is the observer's
      !>                location.
      !>
      !>                For an umbral terminator computation, the vertex
      !>                is on the surface of the light source, in the half-
      !>                plane defined by PLNDEF and AXIS. The line containing
      !>                the ray is tangent to the light source at the vertex.
      !>
      !>                For a penumbral terminator computation, the vertex is
      !>                on the surface of the light source, in the half-plane
      !>                complementary to that defined by PLNDEF and AXIS. The
      !>                line containing the ray is tangent to the light source
      !>                at the vertex.
      !>
      !>                Units are radians.
      !>
      !>## Detailed Output
      !>
      !>     OCULTD     is a logical flag that is .TRUE. if and only if the
      !>                ray defined by ANGLE and the values set by ZZTANINI
      !>                intersects the target.
      !>
      !>     POINT      is the ray-surface intercept closest to the ray's
      !>                vertex, if an intercept exists.
      !>
      !>## Parameters
      !>
      !>     See zzdsk.inc for declarations of parameters used internally.
      !>
      !>## Exceptions
      !>
      !>     1)  Any errors that occur while looking up DSK data will be
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     2)  Any errors that occur while computing ray-surface intercepts
      !>         will be signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>     If any loaded DSK segment has a reference frame that is not
      !>     centered at the segment's central (target) body, SPK data are
      !>     required to compute the offset between the frame's center and
      !>     the segment's center.
      !>
      !>     Frame kernels may be required in order to look up a segment's
      !>     frame center offset. In some cases, additional kernels such
      !>     as CK kernels and SCLK kernels could be required to support
      !>     the offset vector lookup.
      !>
      !>     This routine uses PCK data for target body reference
      !>     ellipsoids.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by the DSK subsystem.
      !>
      !>     This routine computes the state of ray for a given input angle.
      !>     The state is "occulted" or "not occulted." When the state is
      !>     occulted, this routine returns the surface intercept point
      !>     nearest to the ray's vertex.
      !>
      !>     This is the state callback routine used by ZZTANSLV to
      !>     find tangent rays on the target body's surface.
      !>
      !>## Examples
      !>
      !>     See usage in ZZTANGNT and ZZTANSLV.
      !>
      !>## Restrictions
      !>
      !>     1) This is a private routine.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-     SPICELIB Version 1.0.0 11-FEB-2016 (NJB)
      !>
      !>        Original version 26-OCT-2015 (NJB)
      module subroutine zztansta ( ctx, angle, ocultd, point )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: pi
      use pepper_math, only: vrotv
      use pepper_inc_zzdsk
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      real(wp), intent(in) :: angle  !! Angle of ray.
      logical, intent(out) :: ocultd  !! Occultation state flag. True if ray is occulted.
      real(wp), intent(out) :: point  ( 3 )  !! Tangent point on target.
      real(wp) :: apex   ( 3 )
      real(wp) :: raydir ( 3 )
      real(wp) :: vrtoff ( 3 )
      if ( .not. allocated ( ctx%zztanutl_state ) ) allocate ( ctx%zztanutl_state )
      associate ( svaxis => ctx%zztanutl_state%svaxis, &
                  svcurv => ctx%zztanutl_state%svcurv, &
                  svet => ctx%zztanutl_state%svet, &
                  svirad => ctx%zztanutl_state%svirad, &
                  svnrml => ctx%zztanutl_state%svnrml, &
                  svvrtx => ctx%zztanutl_state%svvrtx )
      if ( ctx%failed() ) return

      if ( svcurv == lmbcrv ) then
!
!        This is the limb case.
!
!        We'll rotate SVAXIS by ANGLE to achieve the desired result.
!
         call vrotv ( svaxis, svnrml, angle, raydir )

         call zzraysfx ( ctx, svvrtx, raydir, svet, point, ocultd )

      else if ( svcurv == umbral ) then
!
!        This is the umbral terminator case.
!
!        Produce the ray's direction vector by rotating
!        the axis about the cutting half-plane normal by
!        the input angle.
!
         call vrotv ( svaxis, svnrml, angle, raydir )
!
!        Produce the offset of the ray's vertex from the
!        center of the source by rotating the axis
!        vector by ANGLE-pi/2 radians. The length
!        of the vector must be SVIRAD. The saved axis
!        has unit length.
!
         call vrotv  ( svaxis, svnrml, angle-(pi/2), vrtoff )
         vrtoff = svirad*vrtoff
         apex = svvrtx + vrtoff

         call zzraysfx ( ctx, apex, raydir, svet, point, ocultd )

      else if ( svcurv == pnmbrl ) then
!
!        This is the penumbral terminator case.
!
!        Produce the ray's direction vector by rotating
!        the axis about the cutting half-plane normal by
!        the *negative* of the input angle.
!
         call vrotv ( svaxis, svnrml, -angle, raydir )
!
!        Produce the ray's vertex by rotating the axis
!        vector about the normal, *not its negative,*
!        by 3*pi/2 - ANGLE radians. The length of the vector
!        must be SRCRAD. The saved axis has unit length.
!
         call vrotv  ( svaxis, svnrml, (1.5_wp*pi)-angle, vrtoff )

         vrtoff = svirad*vrtoff

         apex = svvrtx + vrtoff

         call zzraysfx ( ctx, apex, raydir, svet, point, ocultd )

      else
!
!        This case should have been ruled out by a check in
!        ZZTANINI. Check again anyway.
!
         call ctx%setmsg ( 'Bad curve type code #.' )
         call ctx%errint ( '#', svcurv              )
         call ctx%sigerr ( 'SPICE(BUG)'             )
         return

      end if

      return
      end associate
      end subroutine zztansta

      !> Solve for tangent points on a target surface of rays contained
      !> within a specified half-plane. The rays may emanate from a
      !> specified vertex or may be tangent to a "source" sphere; the
      !> first case supports limb finding and the second terminator
      !> finding.
      !>
      !> SPICE Private routine intended solely for the support of SPICE
      !> routines. Users should not call this routine directly due to the
      !> volatile nature of this routine.
      !>
      !>## Detailed Input
      !>
      !>     CURVE      is an integer code indicating the type of set on the
      !>                target body on which tangent points are to be found.
      !>                When the target is an ellipsoid, the set is literally
      !>                a curve. When the target is a DSK shape, the set is
      !>                often not connected; so it is not actually a curve;
      !>                still, we retain the familiar terminology for the
      !>                ellipsoid case.
      !>
      !>                Possible values and meanings are:
      !>
      !>                   LMBCRV            limb
      !>                   UMBRAL            umbral terminator
      !>                   PNMBRL            penumbral terminator
      !>
      !>                Terminator computations are performed assuming
      !>                the light source is spherical.
      !>
      !>     SRCRAD     is the radius of the illumination source. This
      !>                value is used for terminator computations only.
      !>                When used, SRCRAD must be strictly positive.
      !>                Units are km.
      !>
      !>     SHAPE      is an integer code indicating the target body shape.
      !>
      !>                Possible values and meanings are:
      !>
      !>                   ELLSHP            shape is modeled as an ellipsoid
      !>                   DSKSHP            shape is provided by DSK data
      !>
      !>     TRGCDE     is the body ID code of the target body.
      !>
      !>     NSURF,
      !>     SRFLST     are, respectively, the count of surface IDs and the
      !>                surface ID list.
      !>
      !>     FIXFID     is the frame ID code of a body-fixed frame centered
      !>                on the target body. The output tangent points will
      !>                be expressed in this frame.
      !>
      !>     ET         is the computation epoch, expressed as seconds past
      !>                J2000 TDB. ET is used for DSK segment selection.
      !>                If the target shape is modeled as an ellipsoid, ET
      !>                is ignored.
      !>
      !>     PLNVEC     is a vector used to define a half-plane in which
      !>                to search for tangent rays. The half-plane contains
      !>                PLNVEC, the target body center, and AXIS.
      !>
      !>                For limb and umbral terminator computations,
      !>                tangent rays lie in the half-plane containing PLNVEC.
      !>
      !>                For penumbral terminator computations, tangent rays
      !>                touch the target in the half-plane containing PLNVEC,
      !>                but touch the light source in the complementary
      !>                half-plane bounded by the line containing AXIS.
      !>
      !>     AXIS       is a second vector used to define a half-plane in
      !>                which to search for tangent vectors. AXIS lies in
      !>                the line forming the boundary of the half-plane.
      !>
      !>                For limb computations, AXIS points from the target
      !>                toward the observation point.
      !>
      !>                For terminator computations, AXIS points from the
      !>                target toward the center of the illumination source.
      !>
      !>     SCHSTP,
      !>     SOLTOL     are, respectively, the search angular step size and
      !>                solution convergence tolerance used to find tangent
      !>                rays and associated limb points within each cutting
      !>                half plane.
      !>
      !>## Detailed Output
      !>
      !>     RESULT     is a cell (not a window) containing ray-axis angular
      !>                separation values at which ray-surface tangencies
      !>                occur.
      !>
      !>                Here "angular separation" refers to the angle between
      !>                a ray and the input vector AXIS. AXIS points away from
      !>                the target.
      !>
      !>                The vertex of the vector depends on the curve type,
      !>                which is indicated by the input code CURVE.
      !>
      !>                For a limb computation, the vertex is the observer's
      !>                location.
      !>
      !>                For an umbral terminator computation, the vertex is on
      !>                the surface of the light source, in the half- plane
      !>                defined by PLNDEF and AXIS. The line containing the
      !>                ray is tangent to the light source at the vertex.
      !>
      !>                For a penumbral terminator computation, the vertex is
      !>                on the surface of the light source, in the half-plane
      !>                complementary to that defined by PLNDEF and AXIS. The
      !>                line containing the ray is tangent to the light source
      !>                at the vertex.
      !>
      !>                Units are radians.
      !>
      !>     POINTS     is an array of tangent points on the target body's
      !>                surface. Elements
      !>
      !>                   POINTS(J,I), J = 1, 3
      !>
      !>                constitute the tangent point for the ray having
      !>                angular separation
      !>
      !>                   RESULT(I)
      !>
      !>                from AXIS. Here the ray's vertex is as described
      !>                above in the discussion of the RESULT output cell.
      !>
      !>## Parameters
      !>
      !>     See the INCLUDE file zzdsk.inc for declarations of these
      !>     parameters.
      !>
      !>     ELLSHP     is a code specifying an ellipsoidal shape model.
      !>
      !>     DSKSHP     is a code specifying a DSK-based shape model.
      !>
      !>     LMBCRV     is a code specifying a limb computation.
      !>
      !>     UMBRAL     is a code specifying an umbral terminator computation.
      !>
      !>                The umbral terminator is the boundary of the portion
      !>                of the target surface that receives no light from the
      !>                illumination source.
      !>
      !>     PNMBRL     is a code specifying an penumbral terminator
      !>                computation.
      !>
      !>                The penumbral terminator is the boundary of the
      !>                portion of the target surface that is not subject to
      !>                self-occultation of light from the illumination
      !>                source. Given that the light source is modeled as
      !>                a sphere, from any target surface point nearer to
      !>                the source than the penumbral terminator, the source
      !>                appears to be a lit disc.
      !>
      !>## Exceptions
      !>
      !>     1)  If AXIS is the zero vector, the error SPICE(ZEROVECTOR) is
      !>         signaled.
      !>
      !>     2)  If PLNDEF is the zero vector, the error SPICE(ZEROVECTOR) is
      !>         signaled.
      !>
      !>     3)  If the curve type code is unrecognized, the error
      !>         SPICE(BADCURVETYPE) is signaled.
      !>
      !>     4)  If a terminator curve is specified by the source radius
      !>         is non-positive, the error SPICE(BADSOURCERADIUS) is
      !>         signaled.
      !>
      !>     5)  If AXIS and PLNDEF are linearly dependent, the error
      !>         SPICE(DEGENERATECASE) is signaled.
      !>
      !>     6)  If the target shape code is unrecognized, the error
      !>         SPICE(BADSHAPE) is signaled.
      !>
      !>## Files
      !>
      !>     This routine makes use of DSK files loaded by the ZZDSKBSR
      !>     subsystem.
      !>
      !>     If any loaded DSK segment has a reference frame that is not
      !>     centered at the segment's central (target) body, SPK data are
      !>     required to compute the offset between the frame's center and
      !>     the segment's center.
      !>
      !>     Frame kernels may be required in order to look up a segment's
      !>     frame center offset. In some cases, additional kernels such
      !>     as CK kernels and SCLK kernels could be required to support
      !>     the offset vector lookup.
      !>
      !>     This routine uses PCK data for target body reference
      !>     ellipsoids.
      !>
      !>## Particulars
      !>
      !>     This routine is meant to be used only by the DSK subsystem.
      !>
      !>     This routine computes target tangent points for limb or
      !>     terminator computations.
      !>
      !>## Examples
      !>
      !>     See usage in LIMBPT and TERMPT.
      !>
      !>## Restrictions
      !>
      !>     1) This is a private routine.
      !>
      !>## Literature References
      !>
      !>     None.
      !>
      !>## Author and Institution
      !>
      !>     N.J. Bachman   (JPL)
      !>
      !>## Version
      !>
      !>-     SPICELIB Version 1.1.0, 17-OCT-2021 (NJB)
      !>
      !>         Deleted unnecessary declarations of external routines
      !>         GFBAIL and GFREPU.
      !>
      !>-     SPICELIB Version 1.0.0, 24-AUG-2016 (NJB)
      !>
      !>           10-FEB-2016 (NJB)
      !>
      !>           Removed VERTEX from argument list.
      !>
      !>           Original version 26-OCT-2015 (NJB)
      module subroutine zztangnt ( ctx, curve, srcrad, shape, trgcde, nsurf, srflst, fixfid, et, plnvec, axis, schstp, soltol, result, points )
      use pepper_kinds, only: ip, wp
      use pepper_constants, only: pi
      use pepper_math, only: vnorm, vrotv
      use pepper_inc_zzdsk
      implicit none
      class(pepper_context), intent(inout) :: ctx  !! the context
      integer(ip), intent(in) :: curve  !! Type of curve: limb or terminator type.
      real(wp), intent(in) :: srcrad  !! Radius of illumination source.
      integer(ip), intent(in) :: shape  !! Target shape.
      integer(ip), intent(in) :: trgcde  !! Target body ID code.
      integer(ip), intent(in) :: nsurf  !! Number of surfaces in list.
      integer(ip), intent(in) :: srflst ( * )  !! Surface ID list.
      integer(ip), intent(in) :: fixfid  !! Frame ID of target body-fixed frame.
      real(wp), intent(in) :: et  !! Epoch, expressed as seconds past J2000 TDB.
      real(wp), intent(in) :: plnvec ( 3 )  !! Reference vector contained in cutting half-plane.
      real(wp), intent(in) :: axis   ( 3 )  !! Axis vector: edge of cutting half-plane.
      real(wp), intent(in) :: schstp  !! Angular step size for searching.
      real(wp), intent(in) :: soltol  !! Solution convergence tolerance.
      real(wp), allocatable, intent(inout) :: result ( : )  !! Cell (not window) containing transition angles. Lower bound LBCELL; grows (PEPPER).
      real(wp), allocatable, intent(inout) :: points ( :, : )  !! Array of tangent points. Grows (PEPPER).


      real(wp) :: alpha
      real(wp) :: start
      real(wp) :: finish
      real(wp) :: maxrad
      real(wp) :: mindst
      real(wp) :: r
      real(wp) :: refvec ( 3 )

      integer(ip) :: i
      integer(ip) :: n

      logical :: cstep
      logical :: endflg ( 2 )

      if ( ctx%failed() ) return

!
!     Empty the result window.
!
      call scardd ( ctx, 0, result )

!
!     Rotate the plane definition vector by pi about AXIS if
!     we're generating penumbral terminator points.
!
      if ( curve == pnmbrl ) then

         call vrotv ( plnvec, axis, pi, refvec )
      else
         refvec = plnvec
      end if

!
!     Prepare the tangent finding utilities.
!
      call zztanini ( ctx, curve,  srcrad, shape,  trgcde, nsurf, srflst, &
                      fixfid, et,     refvec, axis                  )
!
!     Fetch a maximum bounding radius for the target.
!
!     Caution: we assume ZZTANINI has initialized the
!     SINCPT utility subsystem by calling one of
!
!        ZZSUELIN
!        ZZSUDSKI
!
      call zzmaxrad ( ctx, maxrad )

!
!     Scale up MAXRAD slightly to ensure bracketing.
!
      maxrad = maxrad * 1.001_wp

      if ( ctx%failed() ) return

      if ( maxrad <= 0.0_wp ) then

         call ctx%setmsg ( 'Target maximum radius # is non-positive.' )
         call ctx%errdp  ( '#',  maxrad                               )
         call ctx%sigerr ( 'SPICE(INVALIDRADIUS)'                     )
         return

      end if

      if ( curve == lmbcrv ) then
!
!        We're looking for limb points.
!
!        Set the initial ray-axis separation.
!
         start  = 0.0_wp
!
!        If the vertex is outside of the bounding sphere,
!        set the initial angle to the supplement of
!        the angular radius of the target, based on
!        its maximum radius.
!
         r      = vnorm( axis )
         mindst = maxrad * ( 1.0_wp + margin )

         if ( r > mindst ) then

            start = pi -  dasine( ctx, maxrad/r, margin )

        end if

         if ( ctx%failed() ) return
!
!        Set the final ray-axis separation.
!
         finish = pi

      else
!
!        For the terminator cases, check for an invalid source radius.
!
         if ( srcrad <= 0.0_wp ) then

            call ctx%setmsg ( 'Source radius # is non-positive.' )
            call ctx%errdp  ( '#',  srcrad                       )
            call ctx%sigerr ( 'SPICE(INVALIDRADIUS)'             )
            return

         end if

!
!        Make sure the source and outer bounding sphere of the
!        target don't intersect.
!
         r = vnorm( axis )

         if ( (srcrad + maxrad) > r ) then

            call ctx%setmsg ( 'Source radius # and target maximum ' &
            //            'radius # sum to #; distance between ' &
            //            'source and target centers is #. Source ' &
            //            'and target are too close together.'     )
            call ctx%errdp  ( '#',  srcrad                             )
            call ctx%errdp  ( '#',  maxrad                             )
            call ctx%errdp  ( '#',  r                                  )
            call ctx%sigerr ( 'SPICE(OBJECTSTOOCLOSE)'                 )
            return

         end if

         if ( curve == umbral ) then
!
!           We'll search for a point on the umbral terminator.
!
!           For this search, the angle we measure is that between a ray
!           tangent to the source and a ray emanating from the tangent
!           point and parallel to the axis, pointing in the
!           target-source direction. The ray lies in a plane containing
!           the source-target axis.
!
!           The minimum angle is achieved when the ray is tangent to
!           the target sphere; the maximum angle is achieved when the
!           ray intersects the target center.
!
!           The following equation is valid regardless of whether
!           or not SRCRAD > MAXRAD.
!
            start = pi + dasine( ctx, (srcrad-maxrad)/r, margin )

            if ( ctx%failed() ) return

!
!           Set the final ray-axis separation.
!
            finish = pi +  dasine( ctx, srcrad/r, margin )

            if ( ctx%failed() ) return

         else if ( curve == pnmbrl ) then
!
!           We'll search for a point on the umbral terminator.
!
!           We measure the ray's angle from the axis, but in this case,
!           the angle increases in the clockwise (negative sense about
!           the normal to the cutting half-plane defined by the cross
!           product of the axis and the reference vector. Each ray
!           emanating from, and tangent to, the source's surface passes
!           through the axis at a point between the source and target.
!
!           In order to use the root-finding utilities, we treat the
!           angle as a positive quantity.
!
!           The initial ray contains a line segment connecting
!           tangency points on each sphere. The segment, axis,
!           and radii of the spheres form two similar triangles.
!           Below, ALPHA is the fraction of the source-target
!           distance belonging to the triangle having a vertex
!           at the center of the source.
!
            alpha = srcrad / ( srcrad + maxrad )

            start = pi -  dasine( ctx, srcrad / (alpha*r), margin )

            if ( ctx%failed() ) return

!
!           We stop looking when the ray intersects the target center.
!
            finish = pi - dasine( ctx, srcrad / r, margin )

            if ( ctx%failed() ) return

         else

            call ctx%setmsg ( 'Input curve code # was not recognized.' )
            call ctx%errint ( '#', curve                               )
            call ctx%sigerr ( 'SPICE(BUG)'                             )
            return

         end if

      end if

!
!     Search for ray occultations. The endpoints of the occultation
!     intervals are angles at which tangency occurs.
!
!     We consider the angle to be measured from the AXIS vector.
!     The initial and final values START and FINISH have been set
!     above.
!
      cstep  = .true.

      call zztanslv ( ctx, zztansta, gfstep, gfrefn, &
                      cstep,    schstp, start,  finish, &
                      soltol,   result, points, endflg )

      if ( ctx%failed() ) return

!
!     If the first endpoint of RESULT is the interval start but is not
!     a point of transition, delete it from RESULT. Note that RESULT
!     becomes a cell rather than a window. We must delete the
!     corresponding point from the POINTS array as well.
!
      if ( cardd( ctx,result) > 0 ) then

         if ( ( result(1) == start ) .and. ( .not. endflg(1) ) ) then

            n = cardd( ctx, result )

            do i = 2, n

               result(i-1) = result(i)

               points(1:3,i-1) = points(1:3,i)

            end do

            call scardd ( ctx, n-1, result )

         end if

      end if

!
!     If the final endpoint of RESULT is not a transition, delete
!     it as well. In this case decrementing the cardinality of
!     RESULT suffices.
!
      n = cardd( ctx,result)

      if ( n > 0 ) then

         if ( ( result(n) == finish ) .and. ( .not. endflg(2) ) ) then

            call scardd ( ctx, n-1, result )

         end if

      end if

      return
      end subroutine zztangnt

      !> Find limb points on a target body. The limb is the set of points
      !> of tangency on the target of rays emanating from the observer.
      !> The caller specifies half-planes bounded by the observer-target
      !> center vector in which to search for limb points.
      !>
      !> The surface of the target body may be represented either by a
      !> triaxial ellipsoid or by topographic data.
      !>
      !>## Detailed Input
      !>
      !>     METHOD   is a short string providing parameters defining
      !>              the computation method to be used. In the syntax
      !>              descriptions below, items delimited by brackets
      !>              are optional.
      !>
      !>              METHOD may be assigned the following values:
      !>
      !>                'TANGENT/DSK/UNPRIORITIZED[/SURFACES = <surface list>]'
      !>
      !>                    The limb point computation uses topographic data
      !>                    provided by DSK files (abbreviated as "DSK data"
      !>                    below) to model the surface of the target body. A
      !>                    limb point is defined as the point of tangency, on
      !>                    the surface represented by the DSK data, of a ray
      !>                    emanating from the observer.
      !>
      !>                    Limb points are generated within a specified set
      !>                    of "cutting" half-planes that have as an edge the
      !>                    line containing the observer-target vector.
      !>                    Multiple limb points may be found within a given
      !>                    half-plane, if the target body shape allows for
      !>                    this.
      !>
      !>                    The surface list specification is optional. The
      !>                    syntax of the list is
      !>
      !>                       <surface 1> [, <surface 2>...]
      !>
      !>                    If present, it indicates that data only for the
      !>                    listed surfaces are to be used; however, data need
      !>                    not be available for all surfaces in the list. If
      !>                    the list is absent, loaded DSK data for any
      !>                    surface associated with the target body are used.
      !>
      !>                    The surface list may contain surface names or
      !>                    surface ID codes. Names containing blanks must
      !>                    be delimited by double quotes, for example
      !>
      !>                       SURFACES = "Mars MEGDR 128 PIXEL/DEG"
      !>
      !>                    If multiple surfaces are specified, their names
      !>                    or IDs must be separated by commas.
      !>
      !>                    See the $Particulars section below for details
      !>                    concerning use of DSK data.
      !>
      !>                    This is the highest-accuracy method supported by
      !>                    this subroutine. It generally executes much more
      !>                    slowly than the 'GUIDED' method described below.
      !>
      !>                'GUIDED/DSK/UNPRIORITIZED[/SURFACES = <surface list>]'
      !>
      !>                    This method uses DSK data as described above, but
      !>                    limb points generated by this method are "guided"
      !>                    so as to lie in the limb plane of the target
      !>                    body's reference ellipsoid, on the target body's
      !>                    surface. This method produces a unique limb point
      !>                    for each cutting half-plane. If multiple limb
      !>                    point candidates lie in a given cutting
      !>                    half-plane, the outermost one is chosen.
      !>
      !>                    This method may be used only with the 'CENTER'
      !>                    aberration correction locus (see the description
      !>                    of CORLOC below).
      !>
      !>                    Limb points generated by this method are
      !>                    approximations; they are generally not true
      !>                    ray-surface tangent points. However, these
      !>                    approximations can be generated much more quickly
      !>                    than tangent points.
      !>
      !>                'TANGENT/ELLIPSOID'
      !>                'GUIDED/ELLIPSOID'
      !>
      !>                    Both of these methods generate limb points on the
      !>                    target body's reference ellipsoid. The 'TANGENT'
      !>                    option may be used with any aberration correction
      !>                    locus, while the 'GUIDED' option may be used only
      !>                    with the 'CENTER' locus (see the description of
      !>                    CORLOC below).
      !>
      !>                    When the locus is set to 'CENTER', these methods
      !>                    produce the same results.
      !>
      !>                 Neither case nor white space are significant in
      !>                 METHOD, except within double-quoted strings. For
      !>                 example, the string ' eLLipsoid/tAnGenT ' is valid.
      !>
      !>                 Within double-quoted strings, blank characters are
      !>                 significant, but multiple consecutive blanks are
      !>                 considered equivalent to a single blank. Case is
      !>                 not significant. So
      !>
      !>                    "Mars MEGDR 128 PIXEL/DEG"
      !>
      !>                 is equivalent to
      !>
      !>                    " mars megdr  128  pixel/deg "
      !>
      !>                 but not to
      !>
      !>                    "MARS MEGDR128PIXEL/DEG"
      !>
      !>     TARGET   is the name of the target body. The target body is
      !>              an extended ephemeris object.
      !>
      !>              The string TARGET is case-insensitive, and leading
      !>              and trailing blanks in TARGET are not significant.
      !>              Optionally, you may supply a string containing the
      !>              integer ID code for the object. For example both
      !>              'MOON' and '301' are legitimate strings that indicate
      !>              the Moon is the target body.
      !>
      !>              When the target body's surface is represented by a
      !>              tri-axial ellipsoid, this routine assumes that a
      !>              kernel variable representing the ellipsoid's radii is
      !>              present in the kernel pool. Normally the kernel
      !>              variable would be defined by loading a PCK file.
      !>
      !>     ET       is the epoch of participation of the observer,
      !>              expressed as TDB seconds past J2000 TDB: ET is
      !>              the epoch at which the observer's state is computed.
      !>
      !>              When aberration corrections are not used, ET is also
      !>              the epoch at which the position and orientation of
      !>              the target body are computed.
      !>
      !>              When aberration corrections are used, the position
      !>              and orientation of the target body are computed at
      !>              ET-LT, where LT is the one-way light time between the
      !>              aberration correction locus and the observer. The
      !>              locus is specified by the input argument CORLOC.
      !>              See the descriptions of ABCORR and CORLOC below for
      !>              details.
      !>
      !>     FIXREF   is the name of a body-fixed reference frame centered
      !>              on the target body. FIXREF may be any such frame
      !>              supported by the SPICE system, including built-in
      !>              frames (documented in the Frames Required Reading)
      !>              and frames defined by a loaded frame kernel (FK). The
      !>              string FIXREF is case-insensitive, and leading and
      !>              trailing blanks in FIXREF are not significant.
      !>
      !>              The output limb points in the array POINTS and the
      !>              output observer-target tangent vectors in the array
      !>              TANGTS are expressed relative to this reference frame.
      !>
      !>     ABCORR   indicates the aberration corrections to be applied
      !>              when computing the target's position and orientation.
      !>              Corrections are applied at the location specified by
      !>              the aberration correction locus argument CORLOC,
      !>              which is described below.
      !>
      !>              For remote sensing applications, where apparent limb
      !>              points seen by the observer are desired, normally
      !>              either of the corrections
      !>
      !>                 'LT+S'
      !>                 'CN+S'
      !>
      !>              should be used. The correction 'NONE' may be suitable
      !>              for cases in which the target is very small and the
      !>              observer is close to, and has small velocity relative
      !>              to, the target (e.g. comet Churyumov-Gerasimenko and
      !>              the Rosetta Orbiter).
      !>
      !>              These and the other supported options are described
      !>              below. ABCORR may be any of the following:
      !>
      !>                 'NONE'     Apply no correction. Return the
      !>                            geometric limb points on the target
      !>                            body.
      !>
      !>              Let LT represent the one-way light time between the
      !>              observer and the aberration correction locus. The
      !>              following values of ABCORR apply to the "reception"
      !>              case in which photons depart from the locus at the
      !>              light-time corrected epoch ET-LT and *arrive* at the
      !>              observer's location at ET:
      !>
      !>                 'LT'       Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the locus at the moment it
      !>                            emitted photons arriving at the
      !>                            observer at ET.
      !>
      !>                            The light time correction uses an
      !>                            iterative solution of the light time
      !>                            equation. The solution invoked by the
      !>                            'LT' option uses two iterations.
      !>
      !>                            Both the target position as seen by the
      !>                            observer, and rotation of the target
      !>                            body, are corrected for light time.
      !>
      !>                 'LT+S'     Correct for one-way light time and
      !>                            stellar aberration using a Newtonian
      !>                            formulation. This option modifies the
      !>                            locus obtained with the 'LT' option to
      !>                            account for the observer's velocity
      !>                            relative to the solar system
      !>                            barycenter. These corrections yield
      !>                            points on the apparent limb.
      !>
      !>                 'CN'       Converged Newtonian light time
      !>                            correction. In solving the light time
      !>                            equation, the 'CN' correction iterates
      !>                            until the solution converges. Both the
      !>                            position and rotation of the target
      !>                            body are corrected for light time.
      !>
      !>                 'CN+S'     Converged Newtonian light time and
      !>                            stellar aberration corrections. This
      !>                            option produces a solution that is at
      !>                            least as accurate at that obtainable
      !>                            with the 'LT+S' option. Whether the
      !>                            'CN+S' solution is substantially more
      !>                            accurate depends on the geometry of the
      !>                            participating objects and on the
      !>                            accuracy of the input data. In all
      !>                            cases this routine will execute more
      !>                            slowly when a converged solution is
      !>                            computed.
      !>
      !>              The following values of ABCORR apply to the
      !>              "transmission" case in which photons depart from the
      !>              observer's location at ET and arrive at the aberration
      !>              correction locus at the light-time corrected epoch
      !>              ET+LT:
      !>
      !>                 'XLT'      Correct for one-way light time (also
      !>                            called "planetary aberration") using a
      !>                            Newtonian formulation. This correction
      !>                            yields the locus at the moment it
      !>                            receives photons departing from the
      !>                            observer at ET.
      !>
      !>                            The light time correction uses an
      !>                            iterative solution of the light time
      !>                            equation. The solution invoked by the
      !>                            'LT' option uses two iterations.
      !>
      !>                            Both the target position as seen by the
      !>                            observer, and rotation of the target
      !>                            body, are corrected for light time.
      !>
      !>                 'XLT+S'    Correct for one-way transmission light
      !>                            time and stellar aberration using a
      !>                            Newtonian formulation. This option
      !>                            modifies the locus obtained with the 'XLT'
      !>                            option to account for the observer's
      !>                            velocity relative to the solar system
      !>                            barycenter. These corrections yield points
      !>                            on the apparent limb.
      !>
      !>                 'XCN'      Converged transmission Newtonian light
      !>                            time correction. In solving the light time
      !>                            equation, the 'XCN' correction iterates
      !>                            until the solution converges. Both the
      !>                            position and rotation of the target body
      !>                            are corrected for light time.
      !>
      !>                 'XCN+S'    Converged transmission Newtonian light
      !>                            time and stellar aberration corrections.
      !>                            This option produces a solution that is at
      !>                            least as accurate at that obtainable with
      !>                            the `XLT+S' option. Whether the 'XCN+S'
      !>                            solution is substantially more accurate
      !>                            depends on the geometry of the
      !>                            participating objects and on the accuracy
      !>                            of the input data. In all cases this
      !>                            routine will execute more slowly when a
      !>                            converged solution is computed.
      !>
      !>     CORLOC   is a string specifying the aberration correction
      !>              locus: the point or set of points for which
      !>              aberration corrections are performed. CORLOC may be
      !>              assigned the values:
      !>
      !>                 'CENTER'
      !>
      !>                     Light time and stellar aberration corrections
      !>                     are applied to the vector from the observer to
      !>                     the center of the target body. The one way
      !>                     light time from the target center to the
      !>                     observer is used to determine the epoch at
      !>                     which the target body orientation is computed.
      !>
      !>                     This choice is appropriate for small target
      !>                     objects for which the light time from the
      !>                     surface to the observer varies little across
      !>                     the entire target. It may also be appropriate
      !>                     for large, nearly ellipsoidal targets when the
      !>                     observer is very far from the target.
      !>
      !>                     Computation speed for this option is faster
      !>                     than for the 'ELLIPSOID LIMB' option.
      !>
      !>                 'ELLIPSOID LIMB'
      !>
      !>                     Light time and stellar aberration corrections
      !>                     are applied to individual limb points on the
      !>                     reference ellipsoid. For a limb point on the
      !>                     surface described by topographic data, lying
      !>                     in a specified cutting half-plane, the unique
      !>                     reference ellipsoid limb point in the same
      !>                     half-plane is used as the locus of the
      !>                     aberration corrections.
      !>
      !>                     This choice is appropriate for large target
      !>                     objects for which the light time from the limb
      !>                     to the observer is significantly different
      !>                     from the light time from the target center to
      !>                     the observer.
      !>
      !>                     Because aberration corrections are repeated for
      !>                     individual limb points, computational speed for
      !>                     this option is relatively slow.
      !>
      !>     OBSRVR   is the name of the observing body. The observing body
      !>              is an ephemeris object: it typically is a spacecraft,
      !>              the earth, or a surface point on the earth. OBSRVR is
      !>              case-insensitive, and leading and trailing blanks in
      !>              OBSRVR are not significant. Optionally, you may
      !>              supply a string containing the integer ID code for
      !>              the object. For example both 'MOON' and '301' are
      !>              legitimate strings that indicate the Moon is the
      !>              observer.
      !>
      !>     REFVEC,
      !>     ROLSTP,
      !>     NCUTS    are, respectively, a reference vector, a roll step
      !>              angle, and a count of cutting half-planes.
      !>
      !>              REFVEC defines the first of a sequence of cutting
      !>              half-planes in which limb points are to be found.
      !>              Each cutting half-plane has as its edge the line
      !>              containing the observer-target vector; the first
      !>              half-plane contains REFVEC.
      !>
      !>              REFVEC is expressed in the body-fixed reference frame
      !>              designated by FIXREF.
      !>
      !>              ROLSTP is an angular step by which to roll the
      !>              cutting half-planes about the observer-target vector.
      !>              The first half-plane is aligned with REFVEC; the Ith
      !>              half-plane is rotated from REFVEC about the
      !>              observer-target vector in the counter-clockwise
      !>              direction by (I-1)*ROLSTP. Units are radians.
      !>              ROLSTP should be set to
      !>
      !>                 2*pi/NCUTS
      !>
      !>              to generate an approximately uniform distribution of
      !>              limb points along the limb.
      !>
      !>              NCUTS is the number of cutting half-planes used to
      !>              find limb points; the angular positions of
      !>              consecutive half-planes increase in the positive
      !>              sense (counterclockwise) about the target-observer
      !>              vector and are distributed roughly equally about that
      !>              vector: each half-plane has angular separation of
      !>              approximately
      !>
      !>                 ROLSTP radians
      !>
      !>              from each of its neighbors. When the aberration
      !>              correction locus is set to 'CENTER', the angular
      !>              separation is the value above, up to round-off. When
      !>              the locus is 'ELLIPSOID LIMB', the separations are
      !>              less uniform due to differences in the aberration
      !>              corrections used for the respective limb points.
      !>
      !>     SCHSTP,
      !>     SOLTOL   are used only for DSK-based surfaces. These inputs
      !>              are, respectively, the search angular step size and
      !>              solution convergence tolerance used to find tangent
      !>              rays and associated limb points within each cutting
      !>              half plane. These values are used when the METHOD
      !>              argument includes the 'TANGENT' option. In this case,
      !>              limb points are found by a two-step search process:
      !>
      !>                 1) Bracketing: starting with the direction
      !>                    opposite the observer-target vector, rays
      !>                    emanating from the observer are generated
      !>                    within the half-plane at successively greater
      !>                    angular separations from the initial direction,
      !>                    where the increment of angular separation is
      !>                    SCHSTP. The rays are tested for intersection
      !>                    with the target surface. When a transition
      !>                    between non-intersection to intersection is
      !>                    found, the angular separation of a tangent ray
      !>                    has been bracketed.
      !>
      !>                 2) Root finding: each time a tangent ray is
      !>                    bracketed, a search is done to find the angular
      !>                    separation from the starting direction at which
      !>                    a tangent ray exists. The search terminates
      !>                    when successive rays are separated by no more
      !>                    than SOLTOL. When the search converges, the
      !>                    last ray-surface intersection point found in
      !>                    the convergence process is considered to be a
      !>                    limb point.
      !>
      !>               SCHSTP and SOLTOL have units of radians.
      !>
      !>               Target bodies with simple surfaces---for example,
      !>               convex shapes---will have a single limb point within
      !>               each cutting half-plane. For such surfaces, SCHSTP
      !>               can be set large enough so that only one bracketing
      !>               step is taken. A value greater than pi, for example
      !>               4.D0, is recommended.
      !>
      !>               Target bodies with complex surfaces can have
      !>               multiple limb points within a given cutting
      !>               half-plane. To find all limb points, SCHSTP must be
      !>               set to a value smaller than the angular separation
      !>               of any two limb points in any cutting half-plane,
      !>               where the vertex of the angle is the observer.
      !>               SCHSTP must not be too small, or the search will be
      !>               excessively slow.
      !>
      !>               For both kinds of surfaces, SOLTOL must be chosen so
      !>               that the results will have the desired precision.
      !>               Note that the choice of SOLTOL required to meet a
      !>               specified bound on limb point height errors depends
      !>               on the observer-target distance.
      !>
      !>     MAXN     is the maximum number of limb points that can be
      !>              stored in the output array POINTS.
      !>
      !>## Detailed Output
      !>
      !>     NPTS     is an array of counts of limb points within the
      !>              specified set of cutting half-planes. The Ith
      !>              element of NPTS is the limb point count in the Ith
      !>              half-plane. NPTS should be declared with length
      !>              at least NCUTS.
      !>
      !>              For most target bodies, there will be one limb point
      !>              per half-plane. For complex target shapes, the limb
      !>              point count in a given half-plane can be greater
      !>              than one (see example 3 below), and it can be zero.
      !>
      !>     POINTS   is an array containing the limb points found by this
      !>              routine. Sets of limb points associated with
      !>              half-planes are ordered by the indices of the
      !>              half-planes in which they're found. The limb points
      !>              in a given half-plane are ordered by decreasing
      !>              angular separation from the observer-target
      !>              direction; the outermost limb point in a given
      !>              half-plane is the first of that set.
      !>
      !>              The limb points for the half-plane containing REFVEC
      !>              occupy array elements
      !>
      !>                 POINTS(1,1) through POINTS(3,NPTS(1))
      !>
      !>              Limb points for the second half plane occupy
      !>              elements
      !>
      !>                 POINTS(1, NPTS(1)+1       ) through
      !>                 POINTS(3, NPTS(1)+NPTS(2) )
      !>
      !>              and so on.
      !>
      !>              POINTS should be declared with dimensions
      !>
      !>                 ( 3, MAXN )
      !>
      !>              Limb points are expressed in the reference frame
      !>              designated by FIXREF. For each limb point, the
      !>              orientation of the frame is evaluated at the epoch
      !>              corresponding to the limb point; the epoch is
      !>              provided in the output array EPOCHS (described
      !>              below).
      !>
      !>              Units of the limb points are km.
      !>
      !>     EPOCHS   is an array of epochs associated with the limb
      !>              points, accounting for light time if aberration
      !>              corrections are used. EPOCHS contains one element
      !>              for each limb point. EPOCHS should be declared
      !>              with length
      !>
      !>                 MAXN
      !>
      !>              The element
      !>
      !>                 EPOCHS(I)
      !>
      !>              is associated with the limb point
      !>
      !>                 POINTS(J,I), J = 1 to 3
      !>
      !>              If CORLOC is set to 'CENTER', all values of EPOCHS
      !>              will be the epoch associated with the target body
      !>              center. That is, if aberration corrections are used,
      !>              and if LT is the one-way light time from the target
      !>              center to the observer, the elements of EPOCHS will
      !>              all be set to
      !>
      !>                 ET - LT
      !>
      !>              If CORLOC is set to 'ELLIPSOID LIMB', all values of
      !>              EPOCHS for the limb points in a given half plane
      !>              will be those for the reference ellipsoid limb point
      !>              in that half plane. That is, if aberration
      !>              corrections are used, and if LT(I) is the one-way
      !>              light time to the observer from the reference
      !>              ellipsoid limb point in the Ith half plane, the
      !>              elements of EPOCHS for that half plane will all be
      !>              set to
      !>
      !>                 ET - LT(I)
      !>
      !>              When the target shape is given by DSK data, there
      !>              normally will be a small difference in the light
      !>              time between an actual limb point and that implied
      !>              by the corresponding element of EPOCHS. See the
      !>              description of TANGTS below.
      !>
      !>     TANGTS   is an array of tangent vectors connecting the
      !>              observer to the limb points. The tangent vectors are
      !>              expressed in the frame designated by FIXREF. For the
      !>              Ith vector, the orientation of the frame is
      !>              evaluated at the Ith epoch provided in the output
      !>              array EPOCHS (described above).
      !>
      !>              TANGTS should be declared with dimensions
      !>
      !>                 ( 3, MAXN )
      !>
      !>              The elements
      !>
      !>                 TANGTS(J,I), J = 1 to 3
      !>
      !>              are associated with the limb point
      !>
      !>                 POINTS(J,I), J = 1 to 3
      !>
      !>              Units of the tangent vectors are km.
      !>
      !>              When the target shape is given by DSK data, there
      !>              normally will be a small difference in the light
      !>              time between an actual limb point and that implied
      !>              by the corresponding element of EPOCHS. This
      !>              difference will affect the orientation of the target
      !>              body-fixed frame and the output tangent vectors
      !>              returned in the array TANGTS. All other factors
      !>              being equal, the error in the tangent vector due to
      !>              the light time error is proportional to the
      !>              observer-target distance.
      !>
      !>## Parameters
      !>
      !>     None.
      !>
      !>## Exceptions
      !>
      !>     1)  If the specified aberration correction is unrecognized, an
      !>         error is signaled by a routine in the call tree of this
      !>         routine.
      !>
      !>     2)  If either the target or observer input strings cannot be
      !>         converted to an integer ID code, the error
      !>         SPICE(IDCODENOTFOUND) is signaled.
      !>
      !>     3)  If OBSRVR and TARGET map to the same NAIF integer ID code,
      !>         the error SPICE(BODIESNOTDISTINCT) is signaled.
      !>
      !>     4)  If the input target body-fixed frame FIXREF is not
      !>         recognized, the error SPICE(NOFRAME) is signaled. A frame
      !>         name may fail to be recognized because a required frame
      !>         specification kernel has not been loaded; another cause is a
      !>         misspelling of the frame name.
      !>
      !>     5)  If the input frame FIXREF is not centered at the target body,
      !>         the error SPICE(INVALIDFRAME) is signaled.
      !>
      !>     6)  If the input argument METHOD is not recognized, the error
      !>         SPICE(INVALIDMETHOD) is signaled by either this routine or a
      !>         routine in the call tree of this routine.
      !>
      !>     7)  If METHOD contains an invalid limb type, the error
      !>         SPICE(INVALIDLIMBTYPE) is signaled.
      !>
      !>     8)  If the target and observer have distinct identities but are
      !>         at the same location, the error SPICE(NOSEPARATION) is
      !>         signaled.
      !>
      !>     9)  If insufficient ephemeris data have been loaded prior to
      !>         calling LIMBPT, an error is signaled by a routine in
      !>         the call tree of this routine. When light time correction is
      !>         used, sufficient ephemeris data must be available to
      !>         propagate the states of both observer and target to the solar
      !>         system barycenter.
      !>
      !>     10) If the computation method requires an ellipsoidal target shape
      !>         and triaxial radii of the target body have not been loaded
      !>         into the kernel pool prior to calling LIMBPT, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>         When the target shape is modeled by topographic data, radii
      !>         of the reference triaxial ellipsoid are still required if
      !>         the aberration correction locus is ELLIPSOID LIMB or if
      !>         the limb point generation method is GUIDED.
      !>
      !>     11) If the radii are available in the kernel pool but the count
      !>         of radii values is not three, the error SPICE(BADRADIUSCOUNT)
      !>         is signaled.
      !>
      !>     12) If the target body's shape is modeled as an ellipsoid, and if
      !>         any of the radii of the target body are non-positive, an error
      !>         is signaled by a routine in the call tree of this routine. The
      !>         target must be an extended body.
      !>
      !>     13) If PCK data specifying the target body-fixed frame orientation
      !>         have not been loaded prior to calling LIMBPT, an error is
      !>         signaled by a routine in the call tree of this routine.
      !>
      !>     14) If METHOD specifies that the target surface is represented by
      !>         DSK data, and no DSK files are loaded for the specified
      !>         target, an error is signaled by a routine in the call tree
      !>         of this routine.
      !>
      !>     15) If the array bound MAXN is less than 1, the error
      !>         SPICE(INVALIDSIZE) is signaled.
      !>
      !>     16) If the number of cutting half-planes specified by NCUTS
      !>         is negative or greater than MAXN, the error
      !>         SPICE(INVALIDCOUNT) is signaled.
      !>
      !>     17) If the aberration correction locus is not recognized, the
      !>         error SPICE(INVALIDLOCUS) is signaled.
      !>
      !>     18) If the aberration correction locus is 'ELLIPSOID LIMB'
      !>         but limb type is not 'TANGENT', the error
      !>         SPICE(BADLIMBLOCUSMIX) is signaled.
      !>
      !>     19) If the reference vector REFVEC is the zero vector, the
      !>         error SPICE(ZEROVECTOR) is signaled.
      !>
      !>     20) If the reference vector REFVEC and the observer target
      !>         vector are linearly dependent, the error
      !>         SPICE(DEGENERATECASE) is signaled.
      !>
      !>     21) If the limb computation uses the target ellipsoid limb
      !>         plane, and the limb plane normal and reference vector
      !>         REFVEC are linearly dependent, the error
      !>         SPICE(DEGENERATECASE) is signaled.
      !>
      !>     22) If the limb points cannot all be stored in the output POINTS
      !>         array, the error SPICE(OUTOFROOM) is signaled.
      !>
      !>     23) If the surface is represented by DSK data, and if the search
      !>         step is non-positive, the error SPICE(INVALIDSEARCHSTEP) is
      !>         signaled.
      !>
      !>     24) If the surface is represented by DSK data, and if the search
      !>         tolerance is non-positive, the error SPICE(INVALIDTOLERANCE)
      !>         is signaled.
      !>
      !>     25) If the roll step is non-positive and NCUTS is greater
      !>         than 1, the error SPICE(INVALIDROLLSTEP) is signaled.
      !>
      !>## Files
      !>
      !>     Appropriate kernels must be loaded by the calling program before
      !>     this routine is called.
      !>
      !>     The following data are required:
      !>
      !>     -  SPK data: ephemeris data for target and observer must be
      !>        loaded. If aberration corrections are used, the states of
      !>        target and observer relative to the solar system barycenter
      !>        must be calculable from the available ephemeris data.
      !>        Typically ephemeris data are made available by loading one
      !>        or more SPK files via FURNSH.
      !>
      !>     -  Target body orientation data: these may be provided in a text
      !>        or binary PCK file. In some cases, target body orientation
      !>        may be provided by one more more CK files. In either case,
      !>        data are made available by loading the files via FURNSH.
      !>
      !>     -  Shape data for the target body:
      !>
      !>           PCK data:
      !>
      !>              If the target body shape is modeled as an ellipsoid,
      !>              triaxial radii for the target body must be loaded into
      !>              the kernel pool. Typically this is done by loading a
      !>              text PCK file via FURNSH.
      !>
      !>              Triaxial radii are also needed if the target shape is
      !>              modeled by DSK data but one or both of the GUIDED limb
      !>              definition method or the ELLIPSOID LIMB aberration
      !>              correction locus are selected.
      !>
      !>           DSK data:
      !>
      !>              If the target shape is modeled by DSK data, DSK files
      !>              containing topographic data for the target body must be
      !>              loaded. If a surface list is specified, data for at
      !>              least one of the listed surfaces must be loaded.
      !>
      !>     The following data may be required:
      !>
      !>     -  Frame data: if a frame definition is required to convert the
      !>        observer and target states to the body-fixed frame of the
      !>        target, that definition must be available in the kernel
      !>        pool. Typically the definition is supplied by loading a
      !>        frame kernel via FURNSH.
      !>
      !>     -  Surface name-ID associations: if surface names are specified
      !>        in `method', the association of these names with their
      !>        corresponding surface ID codes must be established by
      !>        assignments of the kernel variables
      !>
      !>           NAIF_SURFACE_NAME
      !>           NAIF_SURFACE_CODE
      !>           NAIF_SURFACE_BODY
      !>
      !>        Normally these associations are made by loading a text
      !>        kernel containing the necessary assignments. An example
      !>        of such a set of assignments is
      !>
      !>           NAIF_SURFACE_NAME += 'Mars MEGDR 128 PIXEL/DEG'
      !>           NAIF_SURFACE_CODE += 1
      !>           NAIF_SURFACE_BODY += 499
      !>
      !>     -  SCLK data: if the target body's orientation is provided by
      !>        CK files, an associated SCLK kernel must be loaded.
      !>
      !>     In all cases, kernel data are normally loaded once per program
      !>     run, NOT every time this routine is called.
      !>
      !>## Particulars
      !>
      !>     Using DSK data
      !>     ==============
      !>
      !>        DSK loading and unloading
      !>        -------------------------
      !>
      !>        DSK files providing data used by this routine are loaded by
      !>        calling FURNSH and can be unloaded by calling UNLOAD or
      !>        KCLEAR. See the documentation of FURNSH for limits on numbers
      !>        of loaded DSK files.
      !>
      !>        For run-time efficiency, it's desirable to avoid frequent
      !>        loading and unloading of DSK files. When there is a reason to
      !>        use multiple versions of data for a given target body---for
      !>        example, if topographic data at varying resolutions are to be
      !>        used---the surface list can be used to select DSK data to be
      !>        used for a given computation. It is not necessary to unload
      !>        the data that are not to be used. This recommendation presumes
      !>        that DSKs containing different versions of surface data for a
      !>        given body have different surface ID codes.
      !>
      !>        DSK data priority
      !>        -----------------
      !>
      !>        A DSK coverage overlap occurs when two segments in loaded DSK
      !>        files cover part or all of the same domain---for example, a
      !>        given longitude-latitude rectangle---and when the time
      !>        intervals of the segments overlap as well.
      !>
      !>        When DSK data selection is prioritized, in case of a coverage
      !>        overlap, if the two competing segments are in different DSK
      !>        files, the segment in the DSK file loaded last takes
      !>        precedence. If the two segments are in the same file, the
      !>        segment located closer to the end of the file takes
      !>        precedence.
      !>
      !>        When DSK data selection is unprioritized, data from competing
      !>        segments are combined. For example, if two competing segments
      !>        both represent a surface as sets of triangular plates, the
      !>        union of those sets of plates is considered to represent the
      !>        surface.
      !>
      !>        Currently only unprioritized data selection is supported.
      !>        Because prioritized data selection may be the default behavior
      !>        in a later version of the routine, the UNPRIORITIZED keyword is
      !>        required in the METHOD argument.
      !>
      !>        Syntax of the METHOD input argument
      !>        -----------------------------------
      !>
      !>        The keywords and surface list in the METHOD argument
      !>        are called "clauses." The clauses may appear in any
      !>        order, for example
      !>
      !>           TANGENT/DSK/UNPRIORITIZED/<surface list>
      !>           DSK/TANGENT/<surface list>/UNPRIORITIZED
      !>           UNPRIORITIZED/<surface list>/DSK/TANGENT
      !>
      !>        The simplest form of the METHOD argument specifying use of
      !>        DSK data is one that lacks a surface list, for example:
      !>
      !>           'TANGENT/DSK/UNPRIORITIZED'
      !>           'GUIDED/DSK/UNPRIORITIZED'
      !>
      !>        For applications in which all loaded DSK data for the target
      !>        body are for a single surface, and there are no competing
      !>        segments, the above strings suffice. This is expected to be
      !>        the usual case.
      !>
      !>        When, for the specified target body, there are loaded DSK
      !>        files providing data for multiple surfaces for that body, the
      !>        surfaces to be used by this routine for a given call must be
      !>        specified in a surface list, unless data from all of the
      !>        surfaces are to be used together.
      !>
      !>        The surface list consists of the string
      !>
      !>           SURFACES =
      !>
      !>        followed by a comma-separated list of one or more surface
      !>        identifiers. The identifiers may be names or integer codes in
      !>        string format. For example, suppose we have the surface
      !>        names and corresponding ID codes shown below:
      !>
      !>           Surface Name                              ID code
      !>           ------------                              -------
      !>           'Mars MEGDR 128 PIXEL/DEG'                1
      !>           'Mars MEGDR 64 PIXEL/DEG'                 2
      !>           'Mars_MRO_HIRISE'                         3
      !>
      !>        If data for all of the above surfaces are loaded, then
      !>        data for surface 1 can be specified by either
      !>
      !>           'SURFACES = 1'
      !>
      !>        or
      !>
      !>           'SURFACES = "Mars MEGDR 128 PIXEL/DEG"'
      !>
      !>        Double quotes are used to delimit the surface name because
      !>        it contains blank characters.
      !>
      !>        To use data for surfaces 2 and 3 together, any
      !>        of the following surface lists could be used:
      !>
      !>           'SURFACES = 2, 3'
      !>
      !>           'SURFACES = "Mars MEGDR  64 PIXEL/DEG", 3'
      !>
      !>           'SURFACES = 2, Mars_MRO_HIRISE'
      !>
      !>           'SURFACES = "Mars MEGDR 64 PIXEL/DEG", Mars_MRO_HIRISE'
      !>
      !>        An example of a METHOD argument that could be constructed
      !>        using one of the surface lists above is
      !>
      !>     'TANGENT/DSK/UNPRIORITIZED/SURFACES= "Mars MEGDR 64 PIXEL/DEG",3'
      !>
      !>## Examples
      !>
      !>     The numerical results shown for these examples may differ across
      !>     platforms. The results depend on the SPICE kernels used as
      !>     input, the compiler and supporting libraries, and the machine
      !>     specific arithmetic implementation.
      !>
      !>     1) Find apparent limb points on Phobos as seen from Mars.
      !>
      !>        Due to Phobos' irregular shape, the TANGENT limb point
      !>        definition will used. It suffices to compute light time and
      !>        stellar aberration corrections for the center of Phobos, so
      !>        the CENTER aberration correction locus will be used. Use
      !>        converged Newtonian light time and stellar aberration
      !>        corrections in order to model the apparent position and
      !>        orientation of Phobos.
      !>
      !>        For comparison, compute limb points using both ellipsoid
      !>        and topographic shape models.
      !>
      !>        Use the target body-fixed +Z axis as the reference direction
      !>        for generating cutting half-planes. This choice enables the
      !>        user to see whether the first limb point is near the target's
      !>        north pole.
      !>
      !>        For each option, use just three cutting half-planes, in order
      !>        to keep the volume of output manageable. In most applications,
      !>        the number of cuts and the number of resulting limb points
      !>        would be much greater.
      !>
      !>        Use the meta-kernel shown below to load the required SPICE
      !>        kernels.
      !>
      !>           KPL/MK
      !>
      !>           File: limbpt_ex1.tm
      !>
      !>           This meta-kernel is intended to support operation of SPICE
      !>           example programs. The kernels shown here should not be
      !>           assumed to contain adequate or correct versions of data
      !>           required by SPICE-based user applications.
      !>
      !>           In order for an application to use this meta-kernel, the
      !>           kernels referenced here must be present in the user's
      !>           current working directory.
      !>
      !>           The names and contents of the kernels referenced
      !>           by this meta-kernel are as follows:
      !>
      !>              File name                        Contents
      !>              ---------                        --------
      !>              de430.bsp                        Planetary ephemeris
      !>              mar097.bsp                       Mars satellite ephemeris
      !>              pck00010.tpc                     Planet orientation and
      !>                                               radii
      !>              naif0011.tls                     Leapseconds
      !>              phobos512.bds                    DSK based on
      !>                                               Gaskell ICQ Q=512
      !>                                               Phobos plate model
      !>           \begindata
      !>
      !>              KERNELS_TO_LOAD = ( 'de430.bsp',
      !>                                  'mar097.bsp',
      !>                                  'pck00010.tpc',
      !>                                  'naif0011.tls',
      !>                                  'phobos512.bds' )
      !>           \begintext
      !>
      !>           End of meta-kernel
      !>
      !>        Example code begins here.
      !>
      !>```fortran
      !>C
      !>C     LIMBPT example 1
      !>C
      !>C        Find limb points on Phobos as seen from Mars.
      !>C
      !>C        Compute limb points using the tangent definition.
      !>C        Perform aberration corrections for the target center.
      !>C        Use both ellipsoid and DSK shape models.
      !>C
      !>      PROGRAM LIMBPT_EX1
      !>      IMPLICIT NONE
      !>C
      !>C     SPICELIB functions
      !>C
      !>      DOUBLE PRECISION      DPR
      !>      DOUBLE PRECISION      PI
      !>
      !>C
      !>C     Local parameters
      !>C
      !>      CHARACTER*(*)         META
      !>      PARAMETER           ( META   = 'limbpt_ex1.tm' )
      !>
      !>      CHARACTER*(*)         FM1
      !>      PARAMETER           ( FM1     =  '(A,F20.9)' )
      !>
      !>      CHARACTER*(*)         FM2
      !>      PARAMETER           ( FM2     =  '(1X,3F20.9)' )
      !>
      !>      INTEGER               BDNMLN
      !>      PARAMETER           ( BDNMLN = 36 )
      !>
      !>      INTEGER               FRNMLN
      !>      PARAMETER           ( FRNMLN = 32 )
      !>
      !>      INTEGER               CORLEN
